INSERT INTO discovery.sub_department_master (id, department_id, sub_department_name, is_active, display_order, created_at, sub_department_name_kannada) VALUES ('378bd4e7-0daf-4a9b-bb60-7e75795b0603', '7f8d398a-7ac3-425b-bdc4-df5bd5944b47', 'Youth Empowerment & Sports Department', true, 0, '2026-10-30 16:55:56.458552+00', 'ಯುವ ಸಬಲೀಕರಣ ಮತ್ತು ಕ್ರೀಡಾ ಇಲಾಖೆ');
INSERT INTO discovery.sub_department_master (id, department_id, sub_department_name, is_active, display_order, created_at, sub_department_name_kannada) VALUES ('112a135c-3258-4069-ac38-23616ab5a51a', '754e71d9-6fb5-4948-9726-3527641d0db8', 'Karnataka State Unorganised Workers Social Security Board', true, 0, '2026-10-30 16:55:56.458552+00', 'ಕರ್ನಾಟಕ ರಾಜ್ಯ ಅಸಂಘಟಿತ ಕಾರ್ಮಿಕರ ಸಾಮಾಜಿಕ ಭದ್ರತಾ ಮಂಡಳಿ');
INSERT INTO discovery.sub_department_master (id, department_id, sub_department_name, is_active, display_order, created_at, sub_department_name_kannada) VALUES ('c8a02a33-93e1-41f0-a0f1-bf5d39dcfcfe', '754e71d9-6fb5-4948-9726-3527641d0db8', 'Karnataka State Workers Welfare and Social Security (Ashadeepa Yojane) Society', true, 0, '2026-10-30 16:55:56.458552+00', 'ಕರ್ನಾಟಕ ರಾಜ್ಯ ಕಾರ್ಮಿಕರ ಕಲ್ಯಾಣ ಮತ್ತು ಸಾಮಾಜಿಕ ಭದ್ರತಾ (ಆಶಾದೀಪ ಯೋಜನೆ) ಸೊಸೈಟಿ');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('d3dcb14a-29e5-478d-851f-d329309555da', 'WOMEN-CHILD-DEVELOPM-14', '5dc8fe6b-c715-4224-848b-e49d44badb6e', 'Unemployment Allowance for Diabilities', 'General', 0, 'Under this scheme, eligible unemployed persons with disabilities (PwDs) who have completed SSLC or a higher level of education are provided with financial assistance of ₹1,000 per month.', '["Disability Certificate /UDID Card mandatory", "Proff of Unemployment , attested by Gazetted officers", "Registration Certificate: by Employment Exchange or Special Employment Exchange", "Cast and income certificate."]', '["The persons with disabiltities 40 or above."]', '[]', '["Citizens can register on the Seva One portal and apply for services, or visit the nearest Grama One / Karnataka One / Bangalore One centre. A unique acknowledgement number is generated for each request and can be used to track the application."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '9cfa639f-c0f2-4322-b61b-7bcb7daf2787', 'ವಿಕಲಾಂಗರಿಗೆ ನಿರುದ್ಯೋಗ ಭತ್ಯೆ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಈ ಯೋಜನೆಯಡಿ, ಎಸ್', NULL, NULL, NULL, NULL, NULL, '["40% ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ದೃಷ್ಟಿದೋಷ ಹೊಂದಿರುವ ವಿದ್ಯಾರ್ಥಿಗಳು."]', '["ನಾಗರಿಕರು ಸೇವಾ ಒನ್ ಪೋರ್ಟಲ್"]', 1, '["ನಿರುದ್ಯೋಗ ವಿನಿಮಯ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರ.", "ಯುಡಿಐಡಿ ಕಾರ್ಡ್ (ವಿಶಿಷ್ಟ ಅಂಗವಿಕಲರ ಗುರುತಿನ ಚೀಟಿ) ಕಡ್ಡಾಯ", "ನಿರ್ವಹಣಾ ಭತ್ಯೆ/ಶುಲ್ಕ ಮರುಪಾವತಿ/ವಿದ್ಯಾರ್ಥಿವೇತನ ಯೋಜನೆಯಡಿ ಪ್ರಯೋಜನಗಳನ್ನು ಪಡೆಯದಿರುವ ಬಗ್ಗೆ ಸ್ವಯಂ ಘೋಷಣೆ", "ಆದಾಯ ಪ್ರಮಾಣ ಪತ್ರ."]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('4a8f7b6e-ffef-4959-a6e4-9a3c073278a3', 'WOMEN-CHILD-DEVELOPM-13', '5dc8fe6b-c715-4224-848b-e49d44badb6e', 'Talking Laptop to Students with Visual Impairment students studying in SSLC', 'General', 0, 'To support and encourage visually impaired students studying in SSLC and higher cl to pursue higher education, the Department provides the latest technology-enabled talking laptops to eligible students selected by the district-level committee.', '["UDID card certificate", "Caste Certificate Issued by Tahsildar", "SSLC and current academic year mark sheet (If the student is currently studying in 10th grade, then they should upload the 9th grade Passed Marks List.)", "Residence proof obtained from Tahsildad regarding residence in Karnataka for 10 years", "Self declaratiion letter that the laptop is not obtained is not obtained fro any other social welfare Department/other Department/University", "Recommendation letter from the school / College (upload)", "No laptop transfer self declaration on 100rs Bond. (upload)", "Study certificate", "Income and Cast certificate", "passsport size photo"]', '["The students with visual impairment 40 or above.", "Residence proof obtained from Tahsildad regarding residence in Karnataka for 10 years."]', '[]', '["Citizens can register on the Seva One portal and apply for services, or visit the nearest Grama One / Karnataka One / Bangalore One centre. A unique acknowledgement number is generated for each request and can be used to track the application."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '9cfa639f-c0f2-4322-b61b-7bcb7daf2787', 'ಎಸ್.ಎಸ್.ಎಲ್.ಸಿ. ಹಾಗೂ ನಂತರ ವ್ಯಾಸಂಗ ಮಾಡುತ್ತಿರುವ ಅಂಧ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ಟಾಕಿಂಗ್ ಲ್ಯಾಪ್', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಎಸ್', NULL, NULL, NULL, NULL, NULL, '["40% ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ದೃಷ್ಟಿದೋಷ ಹೊಂದಿರುವ ವಿದ್ಯಾರ್ಥಿಗಳು.", "10 ವರ್ಷಗಳ ಕಾಲ ಕರ್ನಾಟಕದಲ್ಲಿ ವಾಸವಾಗಿರುವ ಬಗ್ಗೆ."]', '["ನಾಗರಿಕರು ಸೇವಾ ಒನ್ ಪೋರ್ಟಲ್"]', 1, '["ವಿಕಲಚೇತನರ ಗುರುತಿನ ಚೀಟಿ ಯುಡಿಐಡಿ", "ತಹಶೀಲ್ದಾರರಿಂದ ಪಡೆದ ಜಾತಿ ಪ್ರಮಾಣ ಪತ್ರ.", "ಎಸ್.ಎಸ್.ಎಲ್.ಸಿ ಮತ್ತು ಪ್ರಸಕ್ತ ಶೈಕ್ಷಣಿಕ ವರ್ಷದ ಅಂಕಪಟ್ಟಿ (ಪ್ರಸ್ಥುತ ಎಸ್.ಎಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('34241d09-1bf5-45a4-9625-ca34ac6682a4', 'WOMEN-CHILD-DEVELOPM-12', '5dc8fe6b-c715-4224-848b-e49d44badb6e', 'Sewing Machines for Self Employed Persons with Hearing Impairement', 'General', 0, 'For the self employment of hearing impaired persons, Sewing Machines will be distributed to eligble persons with disablities after the selection of district committee.', '["Tailioring class certificate / literacy certifiacte", "UDID Card", "Residence proof obtained from Tahsildad regarding residence in Karnataka for 10 years", "Regarding non transfer/resale of sewing machine self declaration", "Certificate for not being in Government or Private employment", "Self declaratiion letter not obtained Sewing Machines from any other department or social welfare Department/University", "self declaration Certificate of not sealing Sewing Machines attested by a Rs.20 stamps paper.", "Not availed same benefit in other department with notary", "passsport size photo"]', '["Persons with hearing impairment shall have a disability percentage of 40% or above. Further, beneficiaries whose disability certificate specifies the disability as “temporary” shall not be eligible to avail the benefits under this scheme.", "Residence proof obtained from Tahsildad regarding residence in Karnataka for 10 years."]', '[]', '["Citizens can register on the Seva One portal and apply for services, or visit the nearest Grama One / Karnataka One / Bangalore One centre. A unique acknowledgement number is generated for each request and can be used to track the application."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '9cfa639f-c0f2-4322-b61b-7bcb7daf2787', 'ಶ್ರವಣದೋಷವುಳ್ಳ ವ್ಯಕ್ತಿಗಳು ಸ್ವಯಂ ಉದ್ಯೋಗ ನಡೆಸಲು ಹೊಲಿಗೆ ಯಂತ್ರ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಶ್ರವಣದೋಷವುಳ್ಳ ವ್ಯಕ್ತಿಗಳ ಸ್ವಯಂ ಉದ್ಯೋಗಕ್ಕಾಗಿ, ಜಿಲ್ಲಾ ಸಮಿತಿಯ ಆಯ್ಕೆಯ ನಂತರ ಅರ್ಹ ವಿಕಲಚೇತನರಿಗೆ ಹೊಲಿಗೆ ಯಂತ್ರಗಳನ್ನು ವಿತರಿಸಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಶ್ರವಣದೋಷವುಳ್ಳ ವ್ಯಕ್ತಿಗಳ ವಿಕಲಚೇತನತೆಯ ಪ್ರಮಾಣ ಶೇ.40 ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಾಗಿರತಕ್ಕದ್ದು ಹಾಗೂ ಅಂಗವಿಕಲತೆಯ ಪ್ರಮಾಣ ಪತ್ರದಲ್ಲಿ ತಾತ್ಕಾಲಿಕ ಎಂದಿದ್ದಲ್ಲಿ ಅಂತಹ ಫಲಾನುಭವಿಗಳು ಈ ಯೋಜನೆಯ ಸೌಲಭ್ಯ ಪಡೆಯಲು ಅರ್ಹರಿರುವುದಿಲ್ಲ ಎಂದು ತಿದ್ದಿ ಓದಿಕೊಳ್ಳತಕ್ಕದ್ದು.", "10 ವರ್ಷಗಳ ಕಾಲ ಕರ್ನಾಟಕದಲ್ಲಿ ವಾಸವಾಗಿರುವ ಬಗ್ಗೆ."]', '["ನಾಗರಿಕರು ಸೇವಾ ಒನ್ ಪೋರ್ಟಲ್"]', 1, '["ಟೈಲರಿಂಗ್ ವರ್ಗ ಪ್ರಮಾಣಪತ್ರ ಅಥವಾ ಸಾಕ್ಷರತೆ ಪ್ರಮಾಣಪತ್ರ", "ವಿಕಲಚೇತನರ ಗುರುತಿನ ಚೀಟಿ", "10 ವರ್ಷಗಳ ಕಾಲ ಕರ್ನಾಟಕದಲ್ಲಿ ವಾಸವಾಗಿರುವ ಬಗ್ಗೆ ತಹಶೀಲ್ದಾರ್ ಅವರಿಂದ ಪಡೆದ ವಾಸಸ್ಥಳ ದೃಢೀಕರಣ ಪತ್ರ", "ಹೊಲಿಗೆ ಯಂತ್ರದ ವರ್ಗಾವಣೆ/ಮರುಮಾರಾಟ ಮಾಡದಿರುವ ಬಗ್ಗೆ ಸ್ವಯಂ ಘೋಷಣೆ", "ಸರ್ಕಾರಿ ಅಥವಾ ಖಾಸಗಿ ಉದ್ಯೋಗದಲ್ಲಿಲ್ಲದ ಬಗ್ಗೆ ಪ್ರಮಾಣಪತ್ರ", "ಯಾವುದೇ ಇತರ ಇಲಾಖೆ ಅಥವಾ ಸಮಾಜ ಕಲ್ಯಾಣ ಇಲಾಖೆ/ವಿಶ್ವವಿದ್ಯಾಲಯದಿಂದ ಹೊಲಿಗೆ ಯಂತ್ರಗಳನ್ನು ಪಡೆದಿಲ್ಲ ಎಂಬ ಬಗ್ಗೆ ಸ್ವಯಂ ಘೋಷಣಾ ಪ್ರಮಾಣ ಪತ್ರ", "ಹೊಲಿಗೆ ಯಂತ್ರಯನ್ನು ಮರು ಮಾರಾಟ ಮಾಡುವುದಿಲ್ಲ ಎಂದು ರೂ.20 ಸ್ಟ್ಯಾಂಪ್ ಪೇಪರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('009ffab5-3c0a-4b00-920b-c587e64c0658', 'WOMEN-CHILD-DEVELOPM-11', '5dc8fe6b-c715-4224-848b-e49d44badb6e', 'Prize money for Merit Scholorship Disability Students', 'General', 0, 'Incentive scholarship are provided to meritorious students with disabilities who secure 50% and above marks in public exams. The scheme has been extended to TCH.B.Ed., and M.Ed students.', '["Disability Certificate /UDID Card mandatory", "Certificate from School headmaster /College Principal", "Year of passing in which the student has scored more than 50%", "Marks Sheet of the exam"]', '["the disability percentage must be 40% or higher.", "Incentive scholarship are provided to meritorious students with disabilities who secure 50% and above marks in public exams."]', '[]', '["Citizens can register on the Seva One portal and apply for services, or visit the nearest Grama One / Karnataka One / Bangalore One centre. A unique acknowledgement number is generated for each request and can be used to track the application."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '9cfa639f-c0f2-4322-b61b-7bcb7daf2787', 'ಪ್ರತಿಭಾವಂತ ಅಂಗವಿಕಲ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ನೀಡುತ್ತಿರುವ ಪ್ರೋತ್ಸಾಹ ಧನ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಸಾರ್ವತ್ರಿಕ ಪರೀಕ್ಷೆಗಳಲ್ಲಿ ಶೇಕಡ 50 ಕ್ಕಿಂತಲೂ ಹೆಚ್ಚಿನ ಅಂಕಗಳನ್ನು ಪಡೆದ ಪ್ರತಿಭಾನ್ವಿತ ವಿಕಲಚೇತನ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ಪ್ರೋತ್ಸಾಹ ಧನ ನೀಡುವ ಯೋಜನೆಯ ಸೌಲಭ್ಯ ಪಡೆಯ ಬಹುದಾಗಿದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಅಂಗವೈಕಲ್ಯದ ಶೇಕಡಾವಾರು 40% ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನದಾಗಿರಬೇಕು.", "ಸಾರ್ವತ್ರಿಕ ಪರೀಕ್ಷೆಗಳಲ್ಲಿ ಶೇಕಡ 50 ಕ್ಕಿಂತಲೂ ಹೆಚ್ಚಿನ ಅಂಕಗಳನ್ನು ಪಡೆದ ಪ್ರತಿಭಾನ್ವಿತ ವಿಕಲಚೇತನ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ಪ್ರೋತ್ಸಾಹ ಧನ ನೀಡುವ"]', '["ನಾಗರಿಕರು ಸೇವಾ ಒನ್ ಪೋರ್ಟಲ್"]', 1, '["ಅಂಕಪಟ್ಟಿ (ಕೊನೆಯದಾಗಿ ಕಾಣಿಸಿಕೊಂಡ ಪರೀಕ್ಷೆ)", "ಯುಡಿಐಡಿ ಕಾರ್ಡ್ (ವಿಶಿಷ್ಟ ಅಂಗವಿಕಲರ ಗುರುತಿನ ಚೀಟಿ) ಕಡ್ಡಾಯ", "ಶಾಲಾ ಮುಖ್ಯೋಪಾಧ್ಯಾಯರು/ಕಾಲೇಜು ಪ್ರಾಂಶುಪಾಲರಿಂದ ಪ್ರಮಾಣಪತ್ರ", "ವಿದ್ಯಾರ್ಥಿಯು 60% ಕ್ಕಿಂತ ಹೆಚ್ಚು ಅಂಕಗಳನ್ನು ಗಳಿಸಿದ ವರ್ಷ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('66e8195d-cdca-4176-9ad7-8385b8df0f93', 'HORTICULTURE-AND-SER-3', '7fc7181a-5bee-4a83-b61b-bd3c78da95b2', 'Technical information related to Sericulture Department', 'General', 0, 'Technical information related to Sericulture Department', '["Application form with Details"]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '2486ba28-e160-4a76-8df1-ce8e643a84c9', 'ರೇಷ್ಮೆ ಕೃಷಿಗೆ ಸಂಬಂಧಿಸಿದಂತೆ ತಾಂತ್ರಿಕ ಮಾಹಿತಿ ನೀಡುವುದು', 'Technical information related to Sericulture Department', NULL, NULL, NULL, NULL, NULL, NULL, 'ರೇಷ್ಮೆ ಕೃಷಿಗೆ ಸಂಬಂಧಿಸಿದಂತೆ ತಾಂತ್ರಿಕ ಮಾಹಿತಿ ನೀಡುವುದು', NULL, NULL, NULL, true, 'Yes', '[]', '[]', 1, '["1 ವಿವರಗಳೊಂದಿಗೆ ಅರ್ಜಿ ನಮೂನೆ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('13176a97-df75-45fe-8f61-55f99f88b5cf', 'WOMEN-CHILD-DEVELOPM-10', '5dc8fe6b-c715-4224-848b-e49d44badb6e', 'Sadhane Scheme (Incentive for participation in national and international sports)', 'General', 0, 'the persons with disabilities who participate in national and international sports events are provided finance assistannt as a token of encouragement', '["UDID Card (Unique Disability Identity Card) mandatory", "Disability Certificate", "Invitation Letter", "Applicant Photo (Passport Size)", "Certificate from Sports Authority of India / National Sports Federation of India", "Participation Certificate", "Bills regarding expenditure", "Certificate from Department of Youth Empowerment and Sports regarding being physically fit for tournament", "Ration Card"]', '["the disability percentage must be 40% or higher.", "persons with disabilities who is receiving financial assistance under this scheme shall refund the assistance provided by the Department in full, if they do not participate in the competition or if the competitions are discontinued for any reason. Sports persons wishing to receive financial assistance shall submit their application after providing all the required information at least 07 days in advance, agreeing to abide by these conditions. Applications that do not provide complete information shall be rejected without fail."]', '[]', '["Citizens can register on the Seva One portal and apply for services, or visit the nearest Grama One / Karnataka One / Bangalore One centre. A unique acknowledgement number is generated for each request and can be used to track the application."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '9cfa639f-c0f2-4322-b61b-7bcb7daf2787', 'ಸಾಧನ ಯೋಜನೆ (ರಾಷ್ಟ್ರಿಯ ಅಂತರಾಷ್ಟ್ರಿಯ ಕ್ರೀಡೆಗಳಲ್ಲಿ ಭಾಗವಹಿಸಲು ಪ್ರೊತ್ಸಾಹಧನ)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಅಂಗವಿಕಲ ಕ್ರೀಡಾಪಟುಗಳಿಗೆ ಪ್ರೋತ್ಸಾಹ ನೀಡಿ ಧನಸಹಾಯ ನೀಡಲು “ಸಾಧನೆ” ಎಂಬ ಯೋಜನೆಯು ಜಾರಿಯಲ್ಲಿದ್ದು, ಕ್ರೀಡೆಗಳಲ್ಲಿ ವಿಶೇಷ ಸಾಧನೆಗೈದ ವಿಕಲಚೇತನರಿಗೆ ಧನ ಸಹಾಯವನ್ನು ನೀಡಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಅಂಗವೈಕಲ್ಯದ ಶೇಕಡಾವಾರು 40% ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನದಾಗಿರಬೇಕು.", "ಈ ಯೋಜನೆಯಡಿ ಧನಸಹಾಯ ಪಡೆಯುವ ಕ್ರೀಡಾ ಪಟುಗಳು ಸ್ಪರ್ಧೆಯಲ್ಲಿ ಭಾಗವಹಿಸದಿದ್ದರೆ ಇಲ್ಲವೇ ಯಾವುದೇ ಕಾರಣಕ್ಕೆ ಸ್ಪರ್ಧೆಗಳು ನಿಂತು ಹೋದಲ್ಲಿ ಇಲಾಖೆಯು ನೀಡುವ ಧನಸಹಾಯವನ್ನು ಪೂರ್ಣ ಪ್ರಮಾಣದಲ್ಲಿ ಹಿಂತಿರುಗಿಸಬೇಕಿರುತ್ತದೆ. ಈ ಕರಾರಿಗೆ ಬದ್ಧವಾಗಿರುವ ಬಗ್ಗೆ ಧನಸಹಾಯ ಪಡೆಯುವ ಮೊದಲು ಇಚ್ಛಿಸುವ ಕ್ರೀಡಾಪಟುಗಳು ಕನಿಷ್ಠ 7 ದಿನಗಳ ಮೊದಲು ಎಲ್ಲಾ ಮಾಹಿತಿಗಳನ್ನು ಒದಗಿಸಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಬೇಕಾಗಿರುತ್ತದೆ. ಪೂರ್ಣ ಮಾಹಿತಿ ಒದಗಿಸದಿರುವ ಅರ್ಜಿಗಳನ್ನು ನಿರ್ದಾಕ್ಷಿಣ್ಯವಾಗಿ ತಿರಸ್ಕರಿಸಲಾಗುವುದು\""]', '["ನಾಗರಿಕರು ಸೇವಾ ಒನ್ ಪೋರ್ಟಲ್"]', 1, '["ಯುಡಿಐಡಿ ಕಾರ್ಡ್ (ವಿಶಿಷ್ಟ ಅಂಗವಿಕಲ ಗುರುತಿನ ಚೀಟಿ) ಕಡ್ಡಾಯ", "ಅಂಗವೈಕಲ್ಯ ಪ್ರಮಾಣಪತ್ರ", "ಆಮಂತ್ರಣ ಪತ್ರವನ್ನು", "ಅರ್ಜಿದಾರರ ಫೋಟೋ (ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('39445dcf-2436-45ee-ae91-a827212bdb95', 'WOMEN-CHILD-DEVELOPM-9', '5dc8fe6b-c715-4224-848b-e49d44badb6e', 'Prathibe Scheme', 'General', 0, 'Under the Scheme "Prathibe” financial assistance is provided to encourage Persons with Disabilities participating in cultural activities', '["Registration Certificate of the NGOs", "Program Details", "inivitation certificate of the Artist Group", "Payments for the disabled person for participating in the program", "Bond regarding utilization of funds for the intended purpose ( to be submitted by NGO )", "Photograps of the program", "Ration Card"]', '["the disability percentage must be 40% or higher.", "persons with disabilities who is receiving financial assistance under this scheme shall refund the assistance provided by the Department in full, if they do not participate in the competition or if the competitions are discontinued for any reason. Sports persons wishing to receive financial assistance shall submit their application after providing all the required information at least 07 days in advance, agreeing to abide by these conditions. Applications that do not provide complete information shall be rejected without fail."]', '[]', '["Citizens can register on the Seva One portal and apply for services, or visit the nearest Grama One / Karnataka One / Bangalore One centre. A unique acknowledgement number is generated for each request and can be used to track the application."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '9cfa639f-c0f2-4322-b61b-7bcb7daf2787', 'ಪ್ರತಿಬೆ ಯೋಜನೆ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ವಿಕಲಚೇತನರು ಸಾಂಸ್ಕೃತಿಕ ಚಟುವಟಿಕೆಗಳಲ್ಲಿ ಭಾಗವಹಿಸಲು ಪ್ರೋತ್ಸಾಹ ನೀಡುವ ಸಲುವಾಗಿ ಪ್ರತಿಭೆ ಯೋಜನೆಯ ಸೌಲಭ್ಯವನ್ನು ಪಡೆಯಬಹುಧಾಗಿದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಅಂಗವೈಕಲ್ಯದ ಶೇಕಡಾವಾರು 40% ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನದಾಗಿರಬೇಕು.", "ಈ ಯೋಜನೆಯಡಿ ಧನಸಹಾಯ ಪಡೆಯುವ ಕ್ರೀಡಾ ಪಟುಗಳು ಸ್ಪರ್ಧೆಯಲ್ಲಿ ಭಾಗವಹಿಸದಿದ್ದರೆ ಇಲ್ಲವೇ ಯಾವುದೇ ಕಾರಣಕ್ಕೆ ಸ್ಪರ್ಧೆಗಳು ನಿಂತು ಹೋದಲ್ಲಿ ಇಲಾಖೆಯು ನೀಡುವ ಧನಸಹಾಯವನ್ನು ಪೂರ್ಣ ಪ್ರಮಾಣದಲ್ಲಿ ಹಿಂತಿರುಗಿಸಬೇಕಿರುತ್ತದೆ. ಈ ಕರಾರಿಗೆ ಬದ್ಧವಾಗಿರುವ ಬಗ್ಗೆ ಧನಸಹಾಯ ಪಡೆಯುವ ಮೊದಲು ಇಚ್ಛಿಸುವ ಕ್ರೀಡಾಪಟುಗಳು ಕನಿಷ್ಠ 7 ದಿನಗಳ ಮೊದಲು ಎಲ್ಲಾ ಮಾಹಿತಿಗಳನ್ನು ಒದಗಿಸಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಬೇಕಾಗಿರುತ್ತದೆ. ಪೂರ್ಣ ಮಾಹಿತಿ ಒದಗಿಸದಿರುವ ಅರ್ಜಿಗಳನ್ನು ನಿರ್ದಾಕ್ಷಿಣ್ಯವಾಗಿ ತಿರಸ್ಕರಿಸಲಾಗುವುದು\""]', '["ನಾಗರಿಕರು ಸೇವಾ ಒನ್ ಪೋರ್ಟಲ್"]', 1, '["ಯುಡಿಐಡಿ ಕಾರ್ಡ್ (ವಿಶಿಷ್ಟ ಅಂಗವಿಕಲರ ಗುರುತಿನ ಚೀಟಿ) ಕಡ್ಡಾಯ", "NGO ನ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರ", "ಕಾರ್ಯಕ್ರಮದ ವಿವರಗಳು", "ಕಲಾವಿದರ ಗುಂಪಿನ ಆಮಂತ್ರಣ ಪ್ರಮಾಣ ಪತ್ರ", "ಕಾರ್ಯಕ್ರಮದಲ್ಲಿ ಭಾಗವಹಿಸಲು ಅಂಗವಿಕಲ ವ್ಯಕ್ತಿಗೆ ಪಾವತಿಗಳು", "ಉದ್ದೇಶಿತ ಉದ್ದೇಶಕ್ಕಾಗಿ ನಿಧಿಯ ಬಳಕೆಗೆ ಸಂಬಂಧಿಸಿದ ಬಾಂಡ್ (ಎನ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('609412a0-eddf-4376-b192-9e8f5da71134', 'WOMEN-CHILD-DEVELOPM-8', '5dc8fe6b-c715-4224-848b-e49d44badb6e', 'Motorized Two Wheeler for Persons with Physically Disability', 'General', 0, 'Persons in the age group of 20-60 years with severe physical disabilities and hailing from families with income less than Rs.2.00 lakhs per annum will be provided motorized two wheelers once in a life time, to the eligible beneficiaries', '["UDID", "LL/DL certificate.", "work Certifiacte / Study certificate", "Motorized two-wheeler not obtained from any other department or sources in Rs.20/- Bond", "passsport size photo (upload)", "Residence proof obtained from Tahsildad regarding residence in Karnataka for 7.5 years", "The person with disability should possess a ration card, or the annual income of the family should not exceed ₹2.00 lakh in The case of residents of rural areas and ₹2.50 lakh in the case of residents of urban areas.", "Ration Card"]', '["the disability percentage must be 75% or higher.", "Residence proof obtained from Tahsildad regarding residence in Karnataka for 7.5 years", "The person with disability should possess a ration card, or the annual income of the family should not exceed ₹2.00 lakh in the case of residents of rural areas and ₹2.50 lakh in the case of residents of urban areas."]', '[]', '["Citizens can register on the Seva One portal and apply for services, or visit the nearest Grama One / Karnataka One / Bangalore One centre. A unique acknowledgement number is generated for each request and can be used to track the application."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '9cfa639f-c0f2-4322-b61b-7bcb7daf2787', 'ತೀವ್ರತರನಾಧ ದೈಹಿಕ ವಿಕಲಚೇತನರಿಗೆ ಯಂತ್ರಚಾಲಿತ ದ್ವಿಚಕ್ರ ವಾಹನ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '20 ರಿಂದ 60 ವರ್ಷದ ವಯೋಮಾನದ ತೀವ್ರತರವಾದ ದೈಹಿಕ ವಿಕಲಚೇತನರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯವು ಗ್ರಾಮೀಣ ಪ್ರದೇಶದ ವಾಸಿಯಾಗಿದ್ದಲ್ಲಿ ರೂ.2.00 ಲಕ್ಷ ಮತ್ತು ನಗರ ಪ್ರದೇಶದ ವಾಸಿಯಾಗಿದ್ದಲ್ಲಿ ರೂ.2.50 ಲಕ್ಷಗಳ ವಿಧದಲ್ಲಿ ಬರುವ ಅನುಕೂಲವಾಗುವಂತೆ ಜೀವಿತ ಕಾಲದಲ್ಲಿ ಒಂದು ಬಾರಿ ಯಂತ್ರಚಾಲಿತ ದ್ವಿಚಕ್ರ ವಾಹನವನ್ನು ಸರ್ಕಾರದಿಂದ ಮಂಜೂರು ಮಾಡಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಅಂಗವೈಕಲ್ಯದ ಶೇಕಡಾವಾರು 75% ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನದಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಭಾರತದ ಪ್ರಜೆಯಾಗಿರಬೇಕು ಹಾಗೂ ಕರ್ನಾಟಕದಲ್ಲಿ ಕನಿಷ್ಟ ಹಿಂದಿನ 7.5 ವರ್ಷಗಳ ವಾಸಿಯಾಗಿರಬೇಕು.", "ಪಡಿತರ ಚಿಟಿ ಹೊಂದಿರತಕ್ಕುದ್ದು ಅಥವಾ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯವು ಗ್ರಾಮೀಣ ಪ್ರದೇಶದ ವಾಸಿಯಾಗಿದ್ದಲ್ಲಿ ರೂ.2.00 ಲಕ್ಷ ಮತ್ತು ನಗರ ಪ್ರದೇಶದ ವಾಸಿಯಾಗಿದ್ದಲ್ಲಿ ರೂ.2.50 ಲಕ್ಷಗಳು ಮೀರಿರಬಾರದು."]', '["ನಾಗರಿಕರು ಸೇವಾ ಒನ್ ಪೋರ್ಟಲ್"]', 1, '["ವಿಶಿಷ್ಟ ಅಂಗವೈಕಲ್ಯ ಗುರುತಿನ ಚೀಟಿ (UDID)", "ಯಂತ್ರಚಾಲಿತ ದ್ವಿಚಕ್ರ ವಾಹನ ಚಾಲನಾ ಪರವಾನಗಿ (LL) / ಯಂತ್ರಚಾಲಿತ ದ್ವಿಚಕ್ರ ವಾಹನ ಚಾಲನಾ ಪರವಾನಗಿ (DL)", "ಉದ್ಯೋಗ ಪ್ರಮಾಣಪತ್ರ / ವ್ಯಾಸಂಗ ಪ್ರಮಾಣಪತ್ರ", "ಬೇರೆ ಯಾವುದೇ ಇಲಾಖೆ ಅಥವಾ ಮೂಲದಿಂದ ಮೋಟಾರುಚಾಲಿತ ದ್ವಿಚಕ್ರ ವಾಹನವನ್ನು ಪಡೆದಿಲ್ಲವೆಂದು ₹20ರ ಬಾಂಡ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('5e35ef18-a1e6-458c-b607-41d61403a2b5', 'WOMEN-CHILD-DEVELOPM-7', '5dc8fe6b-c715-4224-848b-e49d44badb6e', 'Medical Relief Fund Scheme', 'General', 0, 'Under this scheme, maximum of Rs.1.00 lakh financial assistance is provided to Persons with Disabilities for minimizing the disability conditions through corrective surgeries in Government hospitals, Sanjay Gandhi Accident Relief Hospital, Bangalore or reputed private hospitals across the State of Karnataka.', '["Medical certificate & esitmated cost partainting to surgery", "UDID Card (Unique Disability Identity Card) mandatory", "Discharge Summary", "Applicant Photo (Passport Size)", "Medical Bill/Hospital Bills", "Caste and income certificate recently obtained from Tehsildar"]', '["The disability percentage must be 40% or higher.", "The person with disability should possess a ration card, or the annual income of the family should not exceed ₹2.00 lakh in the case of residents of rural areas and ₹2.50 lakh in the case of residents of urban areas."]', '[]', '["Citizens can register on the Seva One portal and apply for services, or visit the nearest Grama One / Karnataka One / Bangalore One centre. A unique acknowledgement number is generated for each request and can be used to track the application."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '9cfa639f-c0f2-4322-b61b-7bcb7daf2787', 'ವೈದ್ಯಕೀಯ ಪರಿಹಾರ ನಿಧಿ ಯೋಜನೆ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಅಂಗವಿಕಲ ವ್ಯಕ್ತಿಗಳಿಗೆ ಅಂಗವಿಕಲತೆಯನ್ನು ನಿವಾರಿಸಲು ಶಸ್ರ', NULL, NULL, NULL, NULL, NULL, '["ಅಂಗವೈಕಲ್ಯದ ಶೇಕಡಾವಾರು 40% ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನದಾಗಿರಬೇಕು.", "ವಿಕಲಚೇತನರ ವ್ಯಕ್ತಿಯು ಪಡಿತರ ಚೀಟಿಯನ್ನು ಹೊಂದಿರತಕ್ಕದು ಅಥವಾ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯವು ಗ್ರಾಮೀಣ ಪ್ರದೇಶದ ವಾಸಿಯಾಗಿದ್ದಲ್ಲಿ ರೂ.2.00 ಲಕ್ಷ ಮತ್ತು ನಗರ ಪ್ರದೇಶದ ವಾಸಿಯಾಗಿದ್ದಲ್ಲಿ ರೂ.2.50 ಲಕ್ಷಗಳು ಮೀರಿರಬಾರದು."]', '["ನಾಗರಿಕರು ಸೇವಾ ಒನ್ ಪೋರ್ಟಲ್"]', 1, '["ವೈದ್ಯಕೀಯ ಪ್ರಮಾಣಪತ್ರ", "ಯುಡಿಐಡಿ ಕಾರ್ಡ್ (ವಿಶಿಷ್ಟ ಅಂಗವಿಕಲ ಗುರುತಿನ ಚೀಟಿ) ಕಡ್ಡಾಯ", "ಡಿಸ್ಚಾರ್ಜ್ ಸಾರಾಂಶ", "ಅರ್ಜಿದಾರರ ಫೋಟೋ (ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('ab92301b-3474-4d07-b095-faa26fe04290', 'SCHEDULED-TRIBES-WEL-4', '3639208c-68b3-4afd-b526-9ba51fe3f226', 'SSLC Prize Money for ST Students', 'Prize Money', 60, '', '["Caste Certificate, Aadhar Card, SSLC Marks,"]', '["Minimum 60% marks with First Class in the first attempt. No family income limit is applicable."]', '[]', '[]', NULL, NULL, 'https://twd.karnataka.gov.in/twSSLCPRIZEMONEY/', true, '2026-10-30 16:55:56.458552+00', '10bbe8f2-3183-4b94-93c4-70b9d94c09ba', 'ಎಸ್', 'SSLC ST', NULL, 'In-house portal of the TWD. Hosted in KSDC and periodic Audit are being carried out by the ISECRON a', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["ಮೊದಲ ಪ್ರಯತ್ನದಲ್ಲಿ ಪ್ರಥಮ ದರ್ಜೆಯೊಂದಿಗೆ ಕನಿಷ್ಠ 60% ಅಂಕಗಳು. ಯಾವುದೇ ಕುಟುಂಬದ ಆದಾಯ ಮಿತಿ ಅನ್ವಯಿಸುವುದಿಲ್ಲ."]', '[]', 1, '["ಜಾತಿ ಪ್ರಮಾಣ ಪತ್ರ, ಆಧಾರ್ ಕಾರ್ಡ್, ಎಸ್.ಎಸ್.ಎಲ್.ಸಿ ಅಂಕಪಟ್ಟಿ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('8731145f-6947-4499-b86c-c50a89fbe3cf', 'WOMEN-CHILD-DEVELOPM-6', '5dc8fe6b-c715-4224-848b-e49d44badb6e', 'Death Relief Fund This scheme only applicable for VRW MRW URW', 'General', 0, 'under this scheme the provision is applicable only to Village Rehabilitation Workers, Multipurpose Rehabilitation Workers and Urban Rehabilitation Workers. If any of them dies while in service, their legal heirs are eligible to receive compensation of ₹1.00 lakh.', '["UDID Identity Card mandatory", "Workers Appointment letter", "Death Certificate", "Family Tree", "Service Certificate"]', '["ವಿವಿಧೋದ್ದೇಶ ಪುನರ್ವಸತಿ ಕಾರ್ಯಕರ್ತರು, ಗ್ರಾಮೀಣ ಪುನರ್ವಸತಿ ಕಾರ್ಯಕರ್ತರು,ನಗರ ಪುನರ್ವಸತಿ ಕಾರ್ಯಕರ್ತರು ಇವರು ಮಾತ್ರಾ ಸೌಲಭ್ಯ ಪಡೆಯಬಹುದಾಗಿರುತ್ತಾರೆ."]', '[]', '["Citizens can register on the Seva One portal and apply for services, or visit the nearest Grama One / Karnataka One / Bangalore One centre. A unique acknowledgement number is generated for each request and can be used to track the application."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '9cfa639f-c0f2-4322-b61b-7bcb7daf2787', 'ಮರಣ ಪರಿಹಾರ ನಿಧಿ ಈ ಯೋಜನೆಯು VRW MRW URW ಗೆ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ವಿವಿಧೋದ್ದೇಶ ಪುನರ್ವಸತಿ ಕಾರ್ಯಕರ್ತರು, ಗ್ರಾಮೀಣ ಪುನರ್ವಸತಿ ಕಾರ್ಯಕರ್ತರು,ನಗರ ಪುನರ್ವಸತಿ ಕಾರ್ಯಕರ್ತರು ಇವರಿಗೆ ಮಾತ್ರಾ ಅನವೈಸುತಿದ್ದು ಸದರಿ ರವರು ತಮ್ಮ ಕಾರ್ಯಅವಧಿಯಲ್ಲಿ ನಿಧನಹೊಂದಿದಲ್ಲಿ ರೂ.1.00 ಲಕ್ಷಗಳ ಪರಿಹಾರ ಧನ ಸೌಲಭ್ಯ ಪಡೆಯಬಹುದಾಗಿರುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '[]', '["ನಾಗರಿಕರು ಸೇವಾ ಒನ್ ಪೋರ್ಟಲ್"]', 1, '["ಯುಡಿಐಡಿ ಗುರುತಿನ ಚೀಟಿ ಕಡ್ಡಾಯ", "ಕಾರ್ಮಿಕರ ನೇಮಕಾತಿ ಪತ್ರ", "ಮರಣ ಪ್ರಮಾಣಪತ್ರ", "ವಂಶ ವೃಕ್ಷ", "ಸೇವಾ ಪ್ರಮಾಣಪತ್ರ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('da147df7-db7f-4a8c-88f6-80f580af9287', 'WOMEN-CHILD-DEVELOPM-5', '5dc8fe6b-c715-4224-848b-e49d44badb6e', 'Child Care Allowance', 'General', 0, 'The women with visual impairment experiences greater hardship in upbringing the newly born child. In this context under the scheme a sum of Rs 2,000/- per month for Five years is paid to the beneficiary towards the services of ayah, health care, nutritional food, medical treatments, for maximum of two children.', '["Childs Birth Certificate", "Disabilty Identity Card", "Mother and Child Protection (MCP) Card", "UDID Card (Unique Disability Identity Card) mandatory", "Caste and income certificate recently obtained from Tehsildar", "Declaration of usege of funds", "Bank Pass Book Front Page.", "Ration Card", "Domicile Certificate for Residing of 03 Years in Karnataka.", "Care giver certificate"]', '["The women with visual impairment experiences greater hardship in upbringing the newly born child.", "The applicant must be a citizen of India as on the date of application and must have been residing in Karnataka for at least 03 years."]', '[]', '["Citizens can register on the Seva One portal and apply for services, or visit the nearest Grama One / Karnataka One / Bangalore One centre. A unique acknowledgement number is generated for each request and can be used to track the application."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '9cfa639f-c0f2-4322-b61b-7bcb7daf2787', 'ಶಿಶುಪಾಲನಾ ಭತ್ಯೆ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಅಂಧ ಮಹಿಳೆಯರು ಮಗುವಿಗೆ ಜನ್ಮ ನೀಡಿದಾಗ ಆ ಮಗುವನ್ನು ಇತರೆ ಸಾಮಾನ್ಯ ತಾಯಂದಿರಂತೆ ಆರೈಕೆ ಮಾಡುವುದು ಕಷ್ಟಕರವಾಗಿರುತ್ತದೆ. ಇಂತಹ ಅಂಧ ಮಹಿಳೆಯರಿಗೆ ಜನಿಸುವ ಮಕ್ಕಳಿಗೆ ಆರೈಕೆ ಮಾಡಲು ಆಯಾ ಸೇವೆ, ಆರೋಗ್ಯ ಪಾಲನೆ, ಪೌಷ್ಠಿಕ ಆಹಾರ, ಔಷಧೋಪಚಾರಗಳಿಗೆ ಮಾಹೆಯಾನ ರೂ.2000/- ದಂತೆ 5 ವರ್ಷಗಳ ಅವಧಿಗೆ ಸಹಾಯಧನವನ್ನು ನೀಡಲಾಗುತ್ತಿದೆ. ಈ ಸೌಲಭ್ಯವನ್ನು ಗರಿಷ್ಠ 2 ಮಕ್ಕಳವರೆಗೆ ಪಡೆಯಬಹುದಾಗಿದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಅಂಧ ಮಹಿಳೆಯರು ಮಗುವಿಗೆ ಜನ್ಮ ನೀಡಿದಾಗ ಆ ಮಗುವನ್ನು ಇತರೆ ಸಾಮಾನ್ಯ ತಾಯಂದಿರಂತೆ ಆರೈಕೆ ಮಾಡುವುದು ಕಷ್ಟಕರವಾಗಿರುತ್ತದೆ.", "ಎಂಬುದರ ಬದಲಾಗಿ ವಿಕಲಚೇತನರು ಭಾರತದ ಪ್ರಜೆಯಾಗಿರಬೇಕು ಅರ್ಜಿ ಸಲ್ಲಿಸಿದ ದಿನಾಂಕಕ್ಕೆ, ಕನಿಷ್ಠ 03 ವರ್ಷಗಳು ಕರ್ನಾಟಕದಲ್ಲಿ ವಾಸವಿರಬೇಕು."]', '["ನಾಗರಿಕರು ಸೇವಾ ಒನ್ ಪೋರ್ಟಲ್"]', 1, '["ಮಗುವಿನ ಜನನ ಪ್ರಮಾಣಪತ್ರ", "ಅಂಗವೈಕಲ್ಯ ಗುರುತಿನ ಚೀಟಿ", "ತಾಯಿ ಮತ್ತು ಮಕ್ಕಳ ರಕ್ಷಣಾ (MCP) ಕಾರ್ಡ್", "ವಿಶಿಷ್ಟ ಅಂಗವೈಕಲ್ಯ ಗುರುತಿನ ಚೀಟಿ (UDID ಕಾರ್ಡ್) — ಕಡ್ಡಾಯ", "ತಹಶೀಲ್ದಾರರಿಂದ ಇತ್ತೀಚೆಗೆ ಪಡೆದ ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ", "ಅನುದಾನದ ಮೊತ್ತವನ್ನು ಬಳಸುವ ಉದ್ದೇಶದ ಕುರಿತು ಘೋಷಣಾ ಪತ್ರ", "ಬ್ಯಾಂಕ್ ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('5c72d14e-0d4a-4930-a1e6-e3f319c51890', 'WOMEN-CHILD-DEVELOPM-4', '5dc8fe6b-c715-4224-848b-e49d44badb6e', 'Braille Kit Scheme for Persons with Visual Impairment', 'General', 0, 'To enable visually impaired students in the State to lead more independent lives, assistive devices such as talking mobile phones, Braille watches, white canes, and other aids are being procured and distributed to persons with disabilities', '["Study Certificate / Voter ID", "UDID", "Recommendation letter from the school / College", "Residence proof obtained from Tehsildar regarding residence in Karnataka for 7.5 years.", "Caste and income certificate recently obtained from Tehsildar", "Concerne letter form native district office that the benefit is not received under this scheme.", "The self-declaration certificate from Person with disabilities that they have not received any other department", "passsport size photo"]', '["Priority shall be given first to students with 100% visual impairment, followed by consideration of students with 60% or more visual impairment.", "Students with visual impairment shall be citizens of India and shall have been residing in Karnataka for at least the preceding 7.5 years.", "Concerne letter form native district office that the benefit is not received under this scheme."]', '[]', '["Citizens can register on the Seva One portal and apply for services, or visit the nearest Grama One / Karnataka One / Bangalore One centre. A unique acknowledgement number is generated for each request and can be used to track the application."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '9cfa639f-c0f2-4322-b61b-7bcb7daf2787', 'ದೃಷ್ಟಿದೋಷ ಹೊಂದಿರುವ ವಿಕಲಚೇತನರಿಗೆ ಬ್ರೈಲ್', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಅಂಧ ವಿದ್ಯಾರ್ಥಿಗಳು ತಮ್ಮ ದೈನಂದಿನ ಚಟುವಟಿಕೆಗಳಲ್ಲಿ ಸ್ವಾವಲಂಬಿಗಳಾಗಲು ರಾಜ್ಯದ ಅಂಧ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ಟಾಕಿಂಗ್ ಮೊಬೈಲ್, ಬ್ರೈಲ್ ವಾಚ್, ವಾಕಿಂಗ್ ಸ್ಟಿಕ್ ಮತ್ತು ಇನ್ನಿತರೆ ಸಾಧನಗಳನ್ನು ಒಳಗೊಂಡ ಖರೀದಿಸಿ ವಿತರಿಸಲಾಗುವ ಯೋಜನೆ.', NULL, NULL, NULL, NULL, NULL, '["ಮೊದಲು ಶೇ.100 ರಷ್ಟು ದೃಷ್ಟಿದೋಷವುಳ್ಳ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ಆದ್ಯತೆ ನೀಡುವುದು, ಅನಂತರ ಶೇ.60 ಹಾಗೂ ಅದಕಿಂತ ಹೆಚ್ಚಿನ ದೃಷ್ಟಿ ದೋಷವುಳ್ಳ ವಿದ್ಯಾರ್ಥಿಗಳನ್ನು ಪರಿಗಣಿಸುವುದು.", "ಅಂಧ ವಿದ್ಯಾರ್ಥಿಗಳು ಭಾರತದ ಪ್ರಜೆಯಾಗಿರಬೇಕು ಹಾಗೂ ಕರ್ನಾಟಕದಲ್ಲಿ ಕನಿಷ್ಟ ಹಿಂದಿನ 7.5 ವರ್ಷಗಳ ವಾಸಿಯಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಮೂಲ ಜಿಲ್ಲೆಯ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲರ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳ ಕಚೇರಿಯಿಂದ, ಈ ಯೋಜನೆಯಡಿ ಈ ಹಿಂದೆ ಸೌಲಭ್ಯ ಪಡೆದಿಲ್ಲವೆಂದು ದೃಢೀಕರಿಸುವ ಪತ್ರ."]', '["ನಾಗರಿಕರು ಸೇವಾ ಒನ್ ಪೋರ್ಟಲ್"]', 1, '["ವ್ಯಾಸಂಗ ಪ್ರಮಾಣಪತ್ರ / ಮತದಾರರ ಗುರುತಿನ ಚೀಟಿ", "ವಿಶಿಷ್ಟ ಅಂಗವೈಕಲ್ಯ ಗುರುತಿನ ಚೀಟಿ (UDID)", "ಶಾಲೆ / ಕಾಲೇಜಿನಿಂದ ಪಡೆದ ಶಿಫಾರಸು ಪತ್ರ", "ಕರ್ನಾಟಕದಲ್ಲಿ 7.5 ವರ್ಷಗಳಿಂದ ವಾಸಿಸುತ್ತಿರುವುದಕ್ಕೆ ನಿವಾಸ ಪ್ರಮಾಣಪತ್ರ", "ತಹಶೀಲ್ದಾರರಿಂದ ಇತ್ತೀಚೆಗೆ ಪಡೆದ ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ", "ಅರ್ಜಿದಾರರ ಮೂಲ ಜಿಲ್ಲೆಯ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲರ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳ ಕಚೇರಿಯಿಂದ, ಈ ಯೋಜನೆಯಡಿ ಈ ಹಿಂದೆ ಸೌಲಭ್ಯ ಪಡೆದಿಲ್ಲವೆಂದು ದೃಢೀಕರಿಸುವ ಪತ್ರ.", "ಸದರಿ ಸೌಲಭ್ಯವನ್ನು ಯಾವುದೇ ಇತರೆ ಇಲಾಖೆಯಿಂದ ಸೌಲಭ್ಯವನ್ನು ಪಡೆದಿಲ್ಲವೆಂದು ಸ್ವಯಂ ಘೋಷಣಾ ಪತ್ರ", "ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('06d59633-e8f6-4a18-ba4f-23792160ea1a', 'WOMEN-CHILD-DEVELOPM-3', '5dc8fe6b-c715-4224-848b-e49d44badb6e', 'Battery operated wheelchair for persons with disabilities', 'General', 0, 'In order to get the facility of this scheme, the physically challenged persons must be 75% and above physically challenged, who are not able to drive a motorized two-wheeler and have at least one hand and one eye in possession, and should be able to drive a battery-operated wheel chair in all other ways.', '["1 recent photograph", "Caste and income certificate recently obtained from Tehsildar", "Ration Card / ರೇಷನ್ ಕಾರ್ಡ್", "Copy of UDID Card and Medical Certificate of Persons with Disabilities", "The self-declaration certificate from Person with disabilities that they have not received benefit under motorized two-wheeler scheme", "Residence proof obtained from Tehsildar regarding residence in Karnataka for 10 years."]', '["the physically challenged persons must be 75% and above physically challenged, who are not able to drive a motorized two-wheeler and have at least one hand and one eye in possession, and should be able to drive a battery-operated wheel chair"]', '[]', '["Citizens can register on the Seva One portal and apply for services, or visit the nearest Grama One / Karnataka One / Bangalore One centre. A unique acknowledgement number is generated for each request and can be used to track the application."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '9cfa639f-c0f2-4322-b61b-7bcb7daf2787', 'ವಿಕಲಚೇತನ ವ್ಯಕ್ತಿಗಳಿಗೆ ಬ್ಯಾಟರಿ ಚಾಲಿತ್', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಈ ಯೋಜನೆಯ ಸೌಲಭ್ಯ ಪಡೆಯಲು ದೈಹಿಕ ವಿಕಲಚೇತನರು ಶೇ.75% ಮತ್ತು ಅದಕಿಂತ ಹೆಚ್ಚಿನ ದೈಹಿಕ ವಿಕಲಚೇತನರಾಗಿದ್ದು, ಯಂತ್ರಚಾಲಿತ ದ್ವಿಚಕ್ರವಾಹನ ಚಾಲನೆ ಮಾಡಲು ಸಾಮರ್ಥ್ಯ ಹೊಂದಿರದ ಹಾಗೂ ಕನಿಷ್ಟ ಒಂದು ಕೈ, ಒಂದು ಕಣ್ಣು ಸ್ವಾಧೀನದಲ್ಲಿದ್ದು ಹಾಗೂ ಬ್ಯಾಟರಿಚಾಲಿತ ವ್ಹೀಲ್', NULL, NULL, NULL, NULL, NULL, '["ದೈಹಿಕ ವಿಕಲಚೇತನರು ಶೇ.75% ಮತ್ತು ಅದಕಿಂತ ಹೆಚ್ಚಿನ ದೈಹಿಕ ವಿಕಲಚೇತನರಾಗಿದ್ದು, ಮತ್ತು ಅದಕಿಂತ ಹೆಚ್ಚಿನ ದೈಹಿಕ ವಿಕಲಚೇತನರಾಗಿದ್ದು, ಯಂತ್ರಚಾಲಿತ ದ್ವಿಚಕ್ರವಾಹನ ಚಾಲನೆ ಮಾಡಲು ಸಾಮರ್ಥ್ಯ ಹೊಂದಿರದ ಹಾಗೂ ಕನಿಷ್ಟ ಒಂದು ಕೈ, ಒಂದು ಕಣ್ಣು ಸ್ವಾಧೀನದಲ್ಲಿದ್ದು ಹಾಗೂ ಬ್ಯಾಟರಿಚಾಲಿತ ವ್ಹೀಲ್"]', '["ನಾಗರಿಕರು ಸೇವಾ ಒನ್ ಪೋರ್ಟಲ್"]', 1, '["ಇತ್ತೀಚಿನ 1 ಭಾವಾಚಿತ್ರ", "ತಹಸೀಲ್ದಾರ್ ಅವರಿಂದ ಇತ್ತೀಚೆಗೆ ಪಡೆದ ಜಾತಿ ಮತ್ತು", "ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ", "ರೇಷನ್ ಕಾರ್ಡ್", "ಯುಡಿಐಡಿ (UDID) ಕಾರ್ಡ್ ಮತ್ತು ವಿಕಲಾಂಗ ವ್ಯಕ್ತಿಗಳ 6.ವೈದ್ಯಕೀಯ ಪ್ರಮಾಣಪತ್ರದ ಪ್ರತಿ", "ಮೋಟಾರು ಸಂಚಲಿತ ದ್ವಿಚಕ್ರ ವಾಹನ ಯೋಜನೆಯಡಿ ಯಾವುದೇ ಸೌಲಭ್ಯಗಳನ್ನು ಪಡೆದಿಲ್ಲ ಎಂದು ವಿಕಲಾಂಗ ವ್ಯಕ್ತಿಯ ಸ್ವಯಂ-ಘೋಷಣಾ ಪ್ರಮಾಣಪತ್ರ", "ಕರ್ನಾಟಕದಲ್ಲಿ 10 ವರ್ಷಗಳ ಕಾಲ ವಾಸವಾಗಿದ್ದಾರೆಂದು ತಹಸೀಲ್ದಾರ್ ಅವರಿಂದ ಪಡೆದ ನಿವಾಸ ಪ್ರಮಾಣ ಪತ್ರ."]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('61571627-ad3b-4f91-8c9f-bde9c8c9e355', 'SCHEDULED-TRIBES-WEL-3', '3639208c-68b3-4afd-b526-9ba51fe3f226', 'Post Matric Scholarship for ST Students', 'Scholarship', 60, '', '["Income & Caste Certificate, Aadhar Card, SSLC Marks, College Admission details"]', '["50 lakh Family Income limit"]', '[]', '[]', NULL, NULL, 'https://ssp.postmatric.karnataka.gov.in/post_sa_2627/login', true, '2026-10-30 16:55:56.458552+00', '10bbe8f2-3183-4b94-93c4-70b9d94c09ba', 'ಮೆಟ್ರಿಕ್ ನಂತರದ ವಿದ್ಯಾರ್ಥಿವೇತನ', 'PMS ST', NULL, 'Content owned and Maintained by DPAR(e-Gov),', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["50 ಲಕ್ಷ ಕುಟುಂಬ ಆದಾಯ ಮಿತಿ"]', '[]', 1, '["ಆದಾಯ ಮತ್ತು ಜಾತಿ ಪ್ರಮಾಣ ಪತ್ರ, ಆಧಾರ್ ಕಾರ್ಡ್, ಎಸ್.ಎಸ್.ಎಲ್.ಸಿ ಅಂಕಪಟ್ಟಿ, ಕಾಲೇಜು ಪ್ರವೇಶ ವಿವರಗಳು"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('e6fe63ce-f6e5-49af-a6ff-7d367b74357c', 'WOMEN-CHILD-DEVELOPM-2', '5dc8fe6b-c715-4224-848b-e49d44badb6e', 'Aids and Appliances Scheme', 'General', 0, 'aids and appliances (Caliper, Braille Watch, Walking stick, clucths, stick hearing impaired and other etc.)are distributed to the Persons with Disabilities within limit of Rs. 15000/- free of cost.', '["Self declaratiion letter /document that aid and appliances has been taken in previous year from any department/gramma panchayat/taluk panchayat", "Income certificate recently obtained from Tahsildar", "Residence proof obtained from Tahsildad regarding residence in Karnataka for 07 years", "UDID Card", "passsport size photo"]', '["the disability percentage must be 40% or higher.", "A residence certificate confirming that the applicant has lived in Karnataka for 07 years.", "The person with disability should possess a ration card, or the annual income of the family should not exceed ₹2.00 lakh in the case of residents of rural areas and ₹2.50 lakh in the case of residents of urban areas.", "Since assistive devices and equipment may get damaged early due to differences in the manner of their use, the same beneficiary shall be sanctioned assistive devices and equipment once again every 03 years."]', '[]', '["Citizens can register on the Seva One portal and apply for services, or visit the nearest Grama One / Karnataka One / Bangalore One centre. A unique acknowledgement number is generated for each request and can be used to track the application."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '9cfa639f-c0f2-4322-b61b-7bcb7daf2787', 'ಸಾಧನ ಸಲಕರಣೆಗಳ ಯೋಜನೆ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ವಿಕಲಚೇತನರಿಗೆ ಅವಶ್ಯವಾಗಿರುವ ಸಾಧನ ಸಲಕರಣೆಗಳನ್ನು (ಕ್ಯಾಲಿಪರ್ಸ್, ಬ್ರೈಲ್ ವಾಚ್, ವಾಕಿಂಗ್ ಸ್ಟಿಕ್, ಕ್ರಚಸ್, ಊರುಗೋಲು, ಶ್ರವಣಸಾಧನ ಇನ್ನು ಮುಂತಾದವುಗಳು) ರೂ.15,000/-ಗಳ ಮಿತಿಯೊಳಗೆ ಉಚಿತವಾಗಿ ನೀಡಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಅಂಗವೈಕಲ್ಯದ ಶೇಕಡಾವಾರು 40% ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನದಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಕರ್ನಾಟಕದಲ್ಲಿ 07 ವರ್ಷಗಳ ಕಾಲ ಕರ್ನಾಟಕದಲ್ಲಿ ವಾಸವಾಗಿರುವ ಬಗ್ಗೆ.", "ವಿಕಲಚೇತನರ ವ್ಯಕ್ತಿಯು ಪಡಿತರ ಚೀಟಿಯನ್ನು ಹೊಂದಿರತಕ್ಕದು ಅಥವಾ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯವು ಗ್ರಾಮೀಣ ಪ್ರದೇಶದ ವಾಸಿಯಾಗಿದ್ದಲ್ಲಿ ರೂ.2.00 ಲಕ್ಷ ಮತ್ತು ನಗರ ಪ್ರದೇಶದ ವಾಸಿಯಾಗಿದ್ದಲ್ಲಿ ರೂ.2.50 ಲಕ್ಷಗಳು ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರ ವ್ಯಕ್ತಿಯು ಸಾಧನ ಸಲಕರಣೆಗಳ ಬಳಕೆಯ ವಿಧಾನದಲ್ಲಿ ವ್ಯತ್ಯಾಸವಾಗುವುದರಿಂದ ಸಾಧನ ಸಲಕರಣೆಗಳು ಬೇಗನೇ ಹಾಳಾಗುವ ಸಂಭವವಿದ್ದು, ಪ್ರತಿ ಮೂರು ವರ್ಷಕ್ಕೊಮ್ಮೆ ಅದೇ ಫಲಾನುಭವಿಗೆ ಮತ್ತೊಮ್ಮೆ ಸಾಧನ ಸಲಕರಣೆಗಳನ್ನು ಮಂಜೂರು ಮಾಡುವುದು."]', '["ನಾಗರಿಕರು ಸೇವಾ ಒನ್ ಪೋರ್ಟಲ್"]', 1, '["ಕಳೆದ ಸಾಲಿನಲ್ಲಿ ಸಾಧನ ಸಲಕರಣೆ ಪಡೆಯದೇ ಇರುವ ಬಗ್ಗೆ ಇಲಾಖೆ/ಗ್ರಾಮ ಪಂಚಾಯಿತಿ/ತಾಲ್ಲೂಕು ಪಂಚಾಯಿತಿ ಪ್ರಮಾಣ ಪತ್ರ", "ಇತ್ತೀಚೆಗೆ ತಹಶೀಲ್ದಾರ್ ಅವರಿಂದ ಪಡೆದ ಆದಾಯ ಪ್ರಮಾಣ ಪತ್ರ", "07 ವರ್ಷಗಳ ಕಾಲ ಕರ್ನಾಟಕದಲ್ಲಿ ವಾಸವಾಗಿರುವ ಬಗ್ಗೆ ತಹಶೀಲ್ದಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('adb5efce-5618-4b8b-8a3c-d35c9129cff1', 'WOMEN-CHILD-DEVELOPM-1', '5dc8fe6b-c715-4224-848b-e49d44badb6e', 'Aadhara Scheme for Disabled person', 'General', 0, 'If your loan application is approved, the loan will be disbursed at the interest rate as per bank regulations. A subsidy of 50% of the loan amount or a maximum of Rs.1,00,000/- is given.', '["Disability Certificate/UDID Card mandatory.", "Project Report.", "NOC from Bank.", "Income Certificate & Cast Certificate.", "Literacy Certificate.", "Bank Pass Book Front Page.", "Ration Card", "Domicile Certificate for Residing of 10 Years in Karnataka.", "Passport size Photo.", "Self Declaration Bond."]', '["The applicant must belong to the BPL category, and the disability percentage must be 40% or higher.", "A residence certificate confirming that the applicant has lived in Karnataka for 10 years."]', '[]', '["Citizens can register on the Seva One portal and apply for services, or visit the nearest Grama One / Karnataka One / Bangalore One centre. A unique acknowledgement number is generated for each request and can be used to track the application."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '9cfa639f-c0f2-4322-b61b-7bcb7daf2787', 'ಆಧಾರ ಯೋಜನೆ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ನಿಮ್ಮ ಸಾಲದ ಅರ್ಜಿಯು ಅನುಮೋದನೆಯಾದಲ್ಲಿ, ಬ್ಯಾಂಕಿನ ನಿಯಮಾವಳಿಗಳ ಪ್ರಕಾರ ನಿಗದಿಪಡಿಸಿದ ಬಡ್ಡಿ ದರದಲ್ಲಿ ಸಾಲವನ್ನು ವಿತರಿಸಲಾಗುತ್ತದೆ. ಸಾಲದ ಮೊತ್ತದ ಶೇ. 50ರಷ್ಟು ಅಥವಾ ಗರಿಷ್ಠ ರೂ. 1,00,000/- ವರೆಗೆ ಸಹಾಯಧನವನ್ನು ನೀಡಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಅರ್ಜಿದಾರರ ಆರ್ಥಿಕ ವರ್ಗೀಕರಣವು BPL ಆಗಿರಬೇಕು ಮತ್ತು ಅಂಗವೈಕಲ್ಯದ ಶೇಕಡಾವಾರು 40% ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನದಾಗಿರಬೇಕು", "ಕರ್ನಾಟಕದಲ್ಲಿ 10 ವರ್ಷಗಳಿಂದ ವಾಸಿಸುತ್ತಿರುವುದಕ್ಕೆ ನಿವಾಸ ಪ್ರಮಾಣಪತ್ರ"]', '["ನಾಗರಿಕರು ಸೇವಾ ಒನ್ ಪೋರ್ಟಲ್"]', 1, '["ಅಂಗವೈಕಲ್ಯ ಪ್ರಮಾಣಪತ್ರ/ಯುಡಿಐಡಿ ಕಾರ್ಡ್ ಕಡ್ಡಾಯ", "ಯೋಜನಾ ವರದಿ", "ಬ್ಯಾಂಕ್ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC)", "ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ ಮತ್ತು ಜಾತಿ ಪ್ರಮಾಣಪತ್ರ", "ಸಾಕ್ಷರತಾ ಪ್ರಮಾಣಪತ್ರ", "ಬ್ಯಾಂಕ್ ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('e8d5b10d-d4a6-4b0b-b0db-f196b2027f82', 'SOCIAL-WELFARE-DEPAR-24', '81b60538-519f-4131-bd38-c390f2d882d6', 'Dr. Babu Jagjeevan Ram Two Wheeler Cargo Transport Scheme', 'Loan with Subsidy', 0, 'In 2022-23, a scheme will be implemented to promote self-employment and increase self-confidence among Scheduled Castes and Scheduled Tribes youth. This scheme is designed to facilitate e-commerce businesses and create employment in other services. Under this scheme, beneficiaries who purchase electric or other two-wheeler/three-wheeler goods transport vehicles will receive a subsidy of Rs. 50,000 and a loan of Rs. 20,000.', '["Applicant Aadhar Card (Mandatory)", "Applicant Photo (Mandatory)", "Applicant Voter ID (Mandatory)", "Applicant Ration Card (Mandatory)", "Caste & Income Certificate issued by competent authority (Mandatory)", "Must Possess Relevant Vehicle Driving License (Mandatory)", "Must Possess Relevant Vehicle Quotation (Mandatory)", "In E-Commerce, submit proof of employment or a self-affidavit for selling goods (Mandatory)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)", "The applicant must declare they have not received prior assistance from the Corporation (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Applicant Age should be between 21 to 60 years.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '89a39d1c-4045-4c4b-a669-094b8f2dfcdc', 'ಡಾ. ಬಾಬು ಜಗಜೀವನ ರಾಂ ದ್ವಿಚಕ್ರ ವಾಹನ ಸರಕು ಸಾಗಾಣಿಕೆ ಯೋಜನೆ', 'Two Wheeler Cargo Transport Scheme', NULL, NULL, 'Online', NULL, NULL, NULL, '2022-23 ನೇ ಸಾಲಿನಲ್ಲಿ ಪರಿಶಿಷ್ಟ ಜಾತಿ ಮತ್ತು ವರಿಶಿಷ್ಟ ಪಂಗಡದ ಯುವಕರಲ್ಲಿ ಸ್ವಯಂ ಉದ್ಯೋಗವನ್ನು ಉತ್ತೇಜಿಸಲು ಮತ್ತು ಆತ್ಮವಿಶ್ವಾಸವನ್ನು ಹೆಚ್ಚಿಸಲು , ಇ-ಕಾಮರ್ಸ್ ವ್ಯವಹಾರಗಳನ್ನು ಸುಲಭಗೊಳಿಸಲು ಮತ್ತು ಇತರ ಸೇವೆಗಳಲ್ಲಿ ಉದ್ಯೋಗವನ್ನು ಸೃಷ್ಟಿಸಲು ಈ ಯೋಜನೆಯನ್ನು ವಿನ್ಯಾಸಗೊಳಿಸಲಾಗಿದೆ. ಈ ಯೋಜನೆಯಡಿಯಲ್ಲಿ, ವಿದ್ಯುತ್ ಅಥವಾ ಇತರೆ ಎರಡು/ಮೂರು ಚಕ್ರದ ಸರಕು ಸಾಗಣೆ ವಾಹನಗಳನ್ನು ಖರೀದಿಸುವ ಫಲಾನುಭವಿಗಳಿಗೆ ರೂ. 50,000 ಸಹಾಯಧನ ಹಾಗೂ ರೂ. 20,000 ಸಾಲವನ್ನು ನೀಡಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 60 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('b926018b-3ec8-4550-a410-4627009e128a', 'SOCIAL-WELFARE-DEPAR-23', '81b60538-519f-4131-bd38-c390f2d882d6', 'Swavalambi Sarathi Scheme', 'Subsidy', 0, 'Under Swalambi Sarathi Yojana, the scheme will be implemented in collaboration with banks by sanctioning 75% subsidy or maximum Rs.4.00 lakhs for goods transport/taxi (yellow board) vehicles.', '["Applicant Aadhar Cards (Mandatory)", "Applicant Ration Card (Mandatory)", "Applicant Voter ID (Mandatory)", "Caste & Income Certificate issued by competent authority (Mandatory)", "Vehicle Quotation (Mandatory)", "The applicant must declare they have not received prior assistance from the Corporation (Mandatory)", "Applicant Photo (Mandatory)", "Bank Pass Book (with Cover Page) (Mandatory)", "Vehicle Driving License(DL) (Mandatory)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 56 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '89a39d1c-4045-4c4b-a669-094b8f2dfcdc', 'ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ ಯೋಜನೆ', 'Swavalambi Sarathi /ISB 3.5', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ ಯೋಜನೆಯಡಿ ಸರಕು ಸಾಗಾಣಿಕೆ/ಟ್ಯಾಕ್ಸಿ (ಹಳದಿ ಬೋರ್ಡ್) ವಾಹನಗಳಿಗೆ ಘಟಕ ವೆಚ್ಚದ ಶೇ.75ರಷ್ಟು ಅಥವಾ ಗರಿಷ್ಟ ರೂ.4.00 ಲಕ್ಷಗಳವರೆಗೆ ಸಹಾಯಧನವನ್ನು ಮಂಜೂರು ಮಾಡಿ ಬ್ಯಾಂಕ್', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 56 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('9d209525-4561-4f10-a751-13f1a9d965ba', 'SCHEDULED-TRIBES-WEL-2', '3639208c-68b3-4afd-b526-9ba51fe3f226', 'Pre Matric Scholarship for 9 &10th Std ST Students', 'Scholarship', 60, '', '["Income & Caste Certificate, Aadhar Card, SSLC Marks, College Admission details"]', '["50 lakh Family Income limit"]', '[]', '[]', NULL, NULL, 'https://ssp.postmatric.karnataka.gov.in/ssppre/', true, '2026-10-30 16:55:56.458552+00', '10bbe8f2-3183-4b94-93c4-70b9d94c09ba', 'ಮೆಟ್ರಿಕ್ ಪೂರ್ವ ವಿದ್ಯಾರ್ಥಿವೇತನ 9 ಮತ್ತು 10ನೇ ತರಗತಿ', 'PRMS ST', NULL, 'Content owned and Maintained by DPAR(e-Gov),', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["50 ಲಕ್ಷ ಕುಟುಂಬ ಆದಾಯ ಮಿತಿ"]', '[]', 1, '["ಆದಾಯ ಮತ್ತು ಜಾತಿ ಪ್ರಮಾಣ ಪತ್ರ, ಆಧಾರ್ ಕಾರ್ಡ್, ಎಸ್.ಎಸ್.ಎಲ್.ಸಿ ಅಂಕಪಟ್ಟಿ, ಕಾಲೇಜು ಪ್ರವೇಶ ವಿವರಗಳು"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('008f9229-ad96-4583-a823-8c5163e9083f', 'SOCIAL-WELFARE-DEPAR-22', '81b60538-519f-4131-bd38-c390f2d882d6', 'Micro Credit Prerana Scheme 5 Lakh', 'Loan with Subsidy', 0, 'Loans and grants will be extended to support various economic activities undertaken by Self-Help Groups of Scheduled Caste women. Each female member will receive Rs. 25,000, comprising a subsidy of Rs. 15,000 and a loan of Rs. 10,000. Self-help groups with a minimum of 10 women members and a unit cost of Rs. 2.50 lakhs will be eligible for loan assistance as per regulations. The loan must be repaid to the Corporation in 36 equal installments with a 4% interest rate', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '89a39d1c-4045-4c4b-a669-094b8f2dfcdc', 'ಪ್ರೇರಣಾ (ಮೈಕ್ರೋ ಕ್ರೆಡಿಟ್) ಯೋಜನೆ 5 ಲಕ್ಷ', 'Prerana (Micro Credit) 5 Lakh', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯದ ಮಹಿಳಾ ಸ್ವಸಹಾಯ ಸಂಘಗಳ ವಿವಿಧ ಉದ್ದೇಶದ ಆರ್ಥಿಕ ಚಟುವಟಿಕೆಗಳಿಗೆ ಸಾಲ ಮತ್ತು ಸಹಾಯಧನ ನೀಡಲಾಗುವುದು. ಪ್ರತಿ ಮಹಿಳಾ ಸದಸ್ಯರಿಗೆ ರೂ 25000. ಇದರಲ್ಲಿ ಸಹಾಯಧನ ರೂ15000 ಹಾಗೂ ಸಾಲ ರೂ10000 ಗಳಾಗಿರುತ್ತದೆ. ಕನಿಷ್ಠ 10 ಜನ ಮಹಿಳಾ ಸದಸ್ಯರು ಇರುವ ಸ್ವ-ಸಹಾಯ ಗುಂಪಿಗೆ ಘಟಕ ವೆಚ್ಛ ರೂ 2.50 ಲಕ್ಷಗಳಂತೆ ನಿಯಮಾನುಸಾರ ಅರ್ಹರಿರುವ ಗುಂಪಿಗೆ ಸಾಲ ಸೌಲಭ್ಯ ಒದಗಿಸಲಾಗುವುದು. ಸದರಿ ಸಾಲದ ಹಣವನ್ನು 36 ಸಮ ಕಂತುಗಳಲ್ಲಿ ಶೇ 4 ರ ಬಡ್ಡಿ ದರದಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಮರುಪಾವತಿ ಮಾಡ ಬೇಕಾಗಿರುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('2d3d9b48-87ad-4ff0-a921-ff7baf0f053d', 'SOCIAL-WELFARE-DEPAR-21', '81b60538-519f-4131-bd38-c390f2d882d6', 'Micro Credit Prerana Scheme', 'Loan with Subsidy', 0, 'Loans and grants will be extended to support various economic activities undertaken by Self-Help Groups of Scheduled Caste women. Each female member will receive Rs. 25,000, comprising a subsidy of Rs. 15,000 and a loan of Rs. 10,000. Self-help groups with a minimum of 10 women members and a unit cost of Rs. 2.50 lakhs will be eligible for loan assistance as per regulations. The loan must be repaid to the Corporation in 36 equal installments with a 4% interest rate', '["Applicant''s Aadhar Cards (Mandatory)", "Applicant''s Ration Card (Mandatory)", "Applicant''s Voter ID (Mandatory)", "Caste & Income Certificate issued by competent authority (Mandatory)", "The applicant must declare they have not received prior assistance from the Corporation (Mandatory)", "Applicant''s Photo (Mandatory)", "Bank Pass Book (with Cover Page) (Mandatory)", "Should Have Valid Association Registration Copy (Mandatory)", "Copy of at least 3 months'' worth of recent association meeting minutes (Mandatory)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 60 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability.", "Registered Copy of Self Help Group.", "Out of the 60% Scheduled Caste members of the association, 40% of the members should belong to the sub-castes belonging to the corporation.", "Members of the SHG should have ration card."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '89a39d1c-4045-4c4b-a669-094b8f2dfcdc', 'ಪ್ರೇರಣಾ (ಮೈಕ್ರೋ ಕ್ರೆಡಿಟ್) ಯೋಜನೆ', 'Prerana (Micro Credit)', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯದ ಮಹಿಳಾ ಸ್ವಸಹಾಯ ಸಂಘಗಳ ವಿವಿಧ ಉದ್ದೇಶದ ಆರ್ಥಿಕ ಚಟುವಟಿಕೆಗಳಿಗೆ ಸಾಲ ಮತ್ತು ಸಹಾಯಧನ ನೀಡಲಾಗುವುದು. ಪ್ರತಿ ಮಹಿಳಾ ಸದಸ್ಯರಿಗೆ ರೂ.25000. ಇದರಲ್ಲಿ ಸಹಾಯಧನ ರೂ.15000 ಹಾಗೂ ಸಾಲ ರೂ.10000 ಗಳಾಗಿರುತ್ತದೆ. ಕನಿಷ್ಠ 10 ಜನ ಮಹಿಳಾ ಸದಸ್ಯರು ಇರುವ ಸ್ವ-ಸಹಾಯ ಗುಂಪಿಗೆ ಘಟಕ ವೆಚ್ಛ ರೂ. 2.50 ಲಕ್ಷಗಳಂತೆ ನಿಯಮಾನುಸಾರ ಅರ್ಹರಿರುವ ಗುಂಪಿಗೆ ಸಾಲ ಸೌಲಭ್ಯ ಒದಗಿಸಲಾಗುವುದು. ಸದರಿ ಸಾಲದ ಹಣವನ್ನು 36 ಸಮ ಕಂತುಗಳಲ್ಲಿ ಶೇ 4 ರ ಬಡ್ಡಿ ದರದಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಮರುಪಾವತಿ ಮಾಡಬೇಕಾಗಿರುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 60 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು.", "ಚಾಲ್ತಿಯಲ್ಲಿರುವ ಸಂಘದ ನೊಂದಣಿ ಪತ್ರ.", "ಸಂಘದ ಶೇ 60 ರ ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸದಸ್ಯರುಗಳ ಪೈಕಿ ಶೇ 40 ರಷ್ಟು ಸದಸ್ಯರು ನಿಗಮಕ್ಕೆ ಸೇರಿದ ಉಪ ಜಾತಿಯವರಾಗಿರಬೇಕು.", "ಸಂಘದ ಸದಸ್ಯರು ಪಡಿತರ ಚೀಟಿಯನ್ನು ಹೊಂದಿರಬೇಕು."]', '[]', 1, '["ಎಲ್ಲಾ ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('69e69d06-7255-44a7-82e8-7a386b1fd2b1', 'SOCIAL-WELFARE-DEPAR-20', '81b60538-519f-4131-bd38-c390f2d882d6', 'Self Employment Direct Loan Scheme', 'Loan with Subsidy', 0, 'Scheduled caste individuals can engage in small-scale economic activities such as selling fruits, vegetables, fish, and rearing livestock like cows, sheep, pigs, or rabbits. The unit cost for these endeavors is Rs.1.00 lakh, with financial support comprising a Rs.50,000 subsidy and a Rs.50,000 loan. Beneficiaries are required to repay the loan to the corporation in 36 equal installments, with an interest rate of 4%.', '["Applicant Aadhar Card (Optional)", "Ration card (Optional)", "Aadhar linked PassBook Front Page Photo (Optional)", "Caste & Income Certificate issued by competent authority (Optional)", "The applicant must declare they have not received prior assistance from the Corporation (Optional)", "Passport size Photo (Optional)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)", "Project Report / Quotation (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 60 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '89a39d1c-4045-4c4b-a669-094b8f2dfcdc', 'ಸ್ವಯಂ ಉದ್ಯೋಗ (ನೇರಸಾಲ) ಯೋಜನೆ', 'Self Employment Scheme', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಪರಿಶಿಷ್ಟ ಜಾತಿ ನಿರುದ್ಯೋಗಿಗಳಿಗೆ ಹಣ್ಣು,, ತರಕಾರಿ, ಮೀನು, ಮಾಂಸ ಮಾರಾಟ, ಹಸು/ಕುರಿ/ಹಂದಿ/ಮೊಲ ಸಾಕಾಣಿಕೆ ಇತ್ಯಾದಿ ಕಿರು ಆರ್ಥಿಕ ಚಟುವಟಿಕೆಗಳಿಗೆ ಘಟಕ ವೆಚ್ಚ ರೂ.1.00ಲಕ್ಷಗಳಾಗಿದ್ದು, ಈ ಪೈಕಿ ರೂ.50,000/- ಸಹಾಯಧನ ಹಾಗೂ ರೂ.50,000/- ಸಾಲದ ರೂಪದಲ್ಲಿ ಆರ್ಥಿಕ ನೆರವನ್ನು ಕಲ್ಪಿಸಲಾಗುತ್ತಿದೆ. ಸಾಲದ ಮೊತ್ತವನ್ನು 36 ಸಮಾನ ಕಂತುಗಳಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಶೇ.4ರ ಬಡ್ಡಿದರದೊಂದಿಗೆ ಮರುಪಾವತಿಸಬೇಕಾಗಿರುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 60 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('d93d4ec0-7470-478b-a66b-de4d15897362', 'SOCIAL-WELFARE-DEPAR-19', '81b60538-519f-4131-bd38-c390f2d882d6', 'ISB - Fast Food Truck Trailer/Mobile Food Kitchen - Rs. 4.00 Lakhs', 'Subsidy', 0, 'Under the ISB (Industrial Service Business) scheme, this fully subsidized Fast Food Truck Trailer/Mobile Kitchen is a mobile food service unit worth ₹4.00 lakhs.', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '89a39d1c-4045-4c4b-a669-094b8f2dfcdc', 'ಐಎಸ್ಬಿ - ಫಾಸ್ಟ್ ಫುಡ್ ಟ್ರಕ್ ಟ್ರೇಲರ್/ಮೊಬೈಲ್ ಫುಡ್ ಕಿಚನ್ - ₹4.00 ಲಕ್ಷಗಳು', 'Fast Food Truck Trailer/Mobile Food Kitchen - 4 Lakh', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಐಎಸ್ಬಿ (ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ) ಯೋಜನೆಯ ಅಡಿಯಲ್ಲಿ ಸಂಪೂರ್ಣ ಸಹಾಯಧನದೊಂದಿಗೆ ನೀಡಲಾಗುವ ಈ ಫಾಸ್ಟ್ ಫುಡ್ ಟ್ರಕ್ ಟ್ರೇಲರ್/ಮೊಬೈಲ್ ಕಿಚನ್ ₹4.00 ಲಕ್ಷ ಮೌಲ್ಯದ ಚಲಿಸುವ ಆಹಾರ ಸೇವಾ ಘಟಕವಾಗಿದೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('774304ee-64c0-48f8-89a8-8068f6b05f1c', 'REVENUE-DEPARTMENT-19', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Non creamy layer Certificate', 'Certificate', 7, 'This certificate is provided to the applicant, based on Income and Caste 
 (OBC) Details of the Applicant and his/her Family. The Certificate is used to avail education, employment and other governament benefits', '["Address Proof", "Affidavit", "Epic", "ID Proof", "Rationcard", "School certificate (If Studied)"]', '["Citizens in need of this service"]', '[]', '["Application Submission – The applicant submits their request through one of four channels: NK (Nadakacheri) Users, Seva Sindhu Users, Online Users, or GP (Gram Panchayat) Users.", "Document Upload – The applicant uploads all required supporting documents for their application.", "Field Verification – The VAO (Village Accountant) and RI (Revenue Inspector) conduct field verification using the Samyojane Mobile Application. This mobile app is also where applications get processed.", "Digital Signing / Approval – The application moves to the TAH/DT/GOT login stage, where the authorized officer can Approve, Modify, or Reject the application, followed by digital signing.", "Certificate Delivery to Citizen – Once approved and signed, the citizen is notified via SMS with a link to download the certificate, and a PDF copy is also sent via email — accessible on desktop, tablet, or mobile."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '3094b139-9107-4665-b080-413a0975c11c', 'ಮೇಲುಸ್ಥರಕ್ಕೆ ಸೇರಿಲ್ಲವೆಂದು ದೃಢಿಕರಣ ಪತ್ರ', NULL, NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, 40.00, NULL, 'ಅರ್ಜಿದಾರರು ಮತ್ತು ಅವರ ಕುಟುಂಬದ ಆದಾಯ ಮತ್ತು ಜಾತಿ (OBC) ವಿವರಗಳ ಆಧಾರದ ಮೇಲೆ ಈ ಪ್ರಮಾಣಪತ್ರವನ್ನು ನೀಡಲಾಗುತ್ತದೆ. ಶಿಕ್ಷಣ, ಉದ್ಯೋಗ ಮತ್ತು ಇತರ ಸರ್ಕಾರಿ ಸೌಲಭ್ಯಗಳನ್ನು ಪಡೆಯಲು ಪ್ರಮಾಣಪತ್ರ ಬಳಸಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, true, 'Yes', '["ಸೇವೆಯ ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಸಾರ್ವಜನಿಕರು"]', '["ಅರ್ಜಿ ಸಲ್ಲಿಕೆ – ಅರ್ಜಿದಾರರು ನಾಲ್ಕು ವಿಧಾನಗಳಲ್ಲಿ ಒಂದರ ಮೂಲಕ ಅರ್ಜಿ ಸಲ್ಲಿಸುತ್ತಾರೆ: NK (ನಾಡಕಚೇರಿ) ಬಳಕೆದಾರರು, ಸೇವಾ ಸಿಂಧು ಬಳಕೆದಾರರು, ಆನ್‌ಲೈನ್ ಬಳಕೆದಾರರು, ಅಥವಾ GP (ಗ್ರಾಮ ಪಂಚಾಯತ್) ಬಳಕೆದಾರರು.", "ದಾಖಲೆಗಳ ಅಪ್‌ಲೋಡ್ – ಅರ್ಜಿದಾರರು ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಪೋಷಕ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಕು.", "ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ – VAO (ಗ್ರಾಮ ಲೆಕ್ಕಾಧಿಕಾರಿ) ಮತ್ತು RI (ಕಂದಾಯ ನಿರೀಕ್ಷಕರು) ಸಂಯೋಜನೆ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ ನಡೆಸುತ್ತಾರೆ. ಅರ್ಜಿಗಳ ಪ್ರಕ್ರಿಯೆಯೂ ಇದೇ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ನಡೆಯುತ್ತದೆ.", "ಡಿಜಿಟಲ್ ಸಹಿ / ಅನುಮೋದನೆ – ಅರ್ಜಿಯು TAH/DT/GOT ಲಾಗಿನ್ ಹಂತಕ್ಕೆ ಹೋಗುತ್ತದೆ, ಅಲ್ಲಿ ಅಧಿಕೃತ ಅಧಿಕಾರಿ ಅರ್ಜಿಯನ್ನು ಅನುಮೋದಿಸಬಹುದು, ಮಾರ್ಪಡಿಸಬಹುದು, ಅಥವಾ ತಿರಸ್ಕರಿಸಬಹುದು, ನಂತರ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡಲಾಗುತ್ತದೆ.", "ಪ್ರಮಾಣಪತ್ರ ವಿತರಣೆ – ಅನುಮೋದನೆ ಮತ್ತು ಸಹಿ ಆದ ನಂತರ, ನಾಗರಿಕರಿಗೆ SMS ಮೂಲಕ ಪ್ರಮಾಣಪತ್ರ ಡೌನ್‌ಲೋಡ್ ಮಾಡುವ ಲಿಂಕ್ ಕಳುಹಿಸಲಾಗುತ್ತದೆ, ಮತ್ತು PDF ಪ್ರತಿಯನ್ನು ಇಮೇಲ್ ಮೂಲಕವೂ ಕಳುಹಿಸಲಾಗುತ್ತದೆ — ಇದನ್ನು ಡೆಸ್ಕ್‌ಟಾಪ್, ಟ್ಯಾಬ್ಲೆಟ್, ಅಥವಾ ಮೊಬೈಲ್‌ನಲ್ಲಿ ಪ್ರವೇಶಿಸಬಹುದು."]', 1, '["ವಿಳಾಸದ ಪುರಾವೆ", "ಅಫೀದಾವಿತ್", "ಎಫಿಕ್", "ಗುರುತಿನ ಚೀಟಿ", "ಪಡಿತರ ಚೀಟಿ", "ಶಾಲಾ ದಾಖಲೆ (ವಿಧ್ಯಾಭ್ಯಾಸ ಹೊಂದಿದ್ದಲ್ಲಿ)"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('3230deb3-300d-4265-94b5-dd53b7049881', 'SOCIAL-WELFARE-DEPAR-18', '81b60538-519f-4131-bd38-c390f2d882d6', 'Land Purchase scheme', 'Loan with Subsidy', 0, 'Under the Land-Ownership Scheme, land will be purchased from non-Scheduled Caste/Scheduled Tribe landowners. Landless women agricultural labourers belonging to the Scheduled Caste community will receive Rs. 20 lakh for 27 districts and Rs. 25 lakh for 4 districts (Bangalore City, Bangalore Rural, Chikkaballapur, and Ramanagara), with 50% subsidy and 50% loan. Khushki/Tari/Bagaitu land within a maximum distance of 10 km from the beneficiary''s residence will be provided. The loan must be repaid to the Corporation in 10 annual equal installments at an interest rate of 6% per annum.', '["Beneficiary Aadhaar Card As Residential Proof (Mandatory)", "Beneficiary Caste Certificate Issued by the competent authority (Mandatory)", "Beneficiary Income Certificate Issued by the competent authority (Mandatory)", "Letter of Landless Agricultural labourers (from Tahsildar) (Mandatory)", "Beneficiary Ration Card (Mandatory)", "Land Owners Cover letter for sale of land (To be notarized and submitted on Stamp paper.) (Mandatory)", "land owner Family Tree (To be verified and submitted by village accountants.) (Mandatory)", "Letter of No Objection (NOC) from Family Members (should be notarized and submitted.) (Mandatory)", "Latest pahani and mutation copy (Mandatory)", "Land Owners Last 13 years E.C. (Encumbrance Certificate should be submitted.) (Mandatory)", "Beneficiary Photo (Mandatory)"]', '["Applicants must belong to scheduled castes and its related community.", "The applicant must be a land less agriculture labour family.", "Self-declaration certificate must be submitted in case of caste certificate.", "Should be resident of Karnataka state.", "The applicant and no member of his family should not be in employment in any Govt./Semi Govt organization.", "The beneficiaries eligible to avail of facilities under the land ownership scheme must be landless women agricultural laborers.", "Additionally, the landowners selling the land should not belong to Scheduled Castes and Scheduled Tribes.", "The land to be purchased is a maximum of 10 km from the place where the beneficiary lives. m. should be within range."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '89a39d1c-4045-4c4b-a669-094b8f2dfcdc', 'ಭೂ-ಒಡೆತನ ಯೋಜನೆ', 'Land Purchase scheme', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಭೂ -ಒಡೆತನ ಯೋಜನೆಯಡಿ ಪರಿಶಿಷ್ಟ ಜಾತಿ / ಪರಿಶಿಷ್ಟ ಪಂಗಡಕ್ಕೆ ಸೇರದ ಭೂ ಮಾಲೀಕರಿಂದ ಜಮೀನನ್ನು ಖರೀದಿಸಿ, ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸಮುದಾಯದ ಭೂ ರಹಿತ ಮಹಿಳಾ ಕೃಷಿ ಕಾರ್ಮಿಕರಿಗೆ 27 ಜಿಲ್ಲೆಗಳಿಗೆ ರೂ 20 ಲಕ್ಷ ಮತ್ತು 4 ಜಿಲ್ಲೆಗಳಿಗೆ (ಬೆಂಗಳೂರು ನಗರ, ಬೆಂಗಳೂರು ಗ್ರಾಮಾಂತರ, ಚಿಕ್ಕಬಳ್ಳಾಪುರ ಮತ್ತು ರಾಮನಗರ) ರೂ 25 ಲಕ್ಷಗಳಿಗೆ (ಸಹಾಯಧನ ಶೇ 50 ಮತ್ತು ಸಾಲ ಶೇ 50 ರಷ್ಟು) ಖುಷ್ಕಿ/ತರಿ/ಬಾಗಾಯ್ತು ಜಮೀನನ್ನು ಫಲಾನುಭವಿಯು ವಾಸಿಸುತ್ತಿರುವ ಸ್ಥಳದಿಂದ ಗರಿಷ್ಠ 10 ಕಿ. ಮೀ. ವ್ಯಾಪ್ತಿಯೊಳಗೆ ಖರೀದಿಸಿ, ಭೂರಹಿತ ಮಹಿಳಾ ಕೃಷಿ ಕಾರ್ಮಿಕರಿಗೆ ಒದಗಿಸಲಾಗುವುದು ಮತ್ತು ಸಾಲದ ಮೊತ್ತವನ್ನು 10 ವಾರ್ಷಿಕ ಸಮ ಕಂತುಗಳಲ್ಲಿ ವಾರ್ಷಿಕ ಶೇ 6 ರ ಬಡ್ಡಿ ದರದಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಮರುಪಾವತಿ ಮಾಡ ಬೇಕಾಗಿರುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '["ಅರ್ಜಿದಾರರು ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸಂಬಂಧಿತ ಜಾತಿಗಳಿಗೆ ಸೇರಿದವರಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಭೂ ರಹಿತ ಕೃಷಿ ಕಾರ್ಮಿಕ ಕುಟುಂಬದವರಾಗಿರಬೇಕು.", "ಜಾತಿ ಪ್ರಮಾಣ ಪತ್ರವನ್ನು ಸಲ್ಲಿಸಿದಲ್ಲಿ ಕಡ್ಡಾಯವಾಗಿ ಸ್ವಯಂ ಘೋಷಣೆ ಪ್ರಮಾಣ ಪತ್ರವನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು/ ಕುಟುಂಬದ ಅವಲಂಬಿತ ಯಾವುದೇ ಸದಸ್ಯರು ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ನೌಕರಿಯಲ್ಲಿರಬಾರದು.", "ಭೂಒಡೆತನ ಯೋಜನೆಯಡಿ ಸೌಲಭ್ಯ ಪಡೆಯಲು ಫಲಾಪೇಕ್ಷಿಯು ಭೂರಹಿತ ಮಹಿಳಾ ಕೃಷಿ ಕಾರ್ಮಿಕರಾಗಿರಬೇಕು.", "ಜಮೀನು ಮಾರಾಟ ಮಾಡುವ ಭೂಮಾಲೀಕರು ಪರಿಶಿಷ್ಟಜಾತಿ ಮತ್ತು ಪರಿಶಿಷ್ಟ ಪಂಗಡಕ್ಕೆ ಸೇರಿರಬಾರದು.", "ಖರೀದಿಸುವ ಜಮೀನು ಫಲಾನುಭವಿಯು ವಾಸಿಸುತ್ತಿರುವ ಸ್ಥಳದಿಂದ ಗರಿಷ್ಠ 10 ಕಿ. ಮೀ. ವ್ಯಾಪ್ತಿಯೊಳಗೆ ಇರಬೇಕು."]', '[]', 1, '["ಫಲಾನುಭವಿಯ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('965bb825-5fe2-409e-a11c-8069d1ca3d56', 'SOCIAL-WELFARE-DEPAR-17', '81b60538-519f-4131-bd38-c390f2d882d6', 'Sheep/Goat Farming Scheme', 'Loan with Subsidy', 0, 'Under the Sheep Farming Scheme, beneficiaries receive a loan of ₹50,000 along with a subsidy of ₹50,000 to support sustainable sheep rearing and income generation', '["Applicant Aadhar Card (Optional)", "Ration card (Optional)", "Aadhar linked PassBook Front Page Photo (Optional)", "Caste & Income Certificate issued by competent authority (Optional)", "The applicant must declare they have not received prior assistance from the Corporation (Optional)", "Passport size Photo (Optional)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)", "Project Report / Quotation (Optional)"]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '89a39d1c-4045-4c4b-a669-094b8f2dfcdc', 'ಕುರಿ/ಮೇಖೆ ಸಾಕಾಣಿಕೆ ಯೋಜನೆ', 'Sheep/Goat Farming Scheme', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಈ ಯೋಜನೆಯ ಅಡಿಯಲ್ಲಿ ಫಲಾನುಭವಿಗಳಿಗೆ ₹50,000 ರ ঋಣ ಮತ್ತು ₹50,000 ರ ಸಹಾಯಧನವನ್ನು ಒದಗಿಸಲಾಗುತ್ತದೆ, ಇದು ಸ್ಥಿರ ಕುರಿ ಸಾಕಾಣಿಕೆ ಮತ್ತು ಆದಾಯ ಉತ್ಪಾದನೆಗೆ ನೆರವಾಗುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('9b0b267d-d2ca-47c3-a0f9-28216cd72a99', 'SOCIAL-WELFARE-DEPAR-16', '81b60538-519f-4131-bd38-c390f2d882d6', 'Industrial Service Business - ISB (in association with Bank) Maximum Rs. 2 lakh subsidy', 'Subsidy', 0, 'Industrial Service Business (in collaboration with the Bank) development scheme, assistance from the Corporation to start self-employment units for unemployed youths and women of the Scheduled Caste community in small scale industry, service sector and business sectors and the rest is loan from the bank. Subsidy of 70% of the unit cost or a maximum of Rs 2 lakh', '["Applicant''s Aadhar Cards (Optional)", "Ration Card (Mandatory)", "Aadhar linked PassBook Front Page Photo (Mandatory)", "Caste & Income Certificate issued by competent authority (Optional)", "Project Report / Quotation (Optional)", "The applicant must declare they have not received prior assistance from the Corporation (Optional)", "Applicant Photo (Mandatory)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 56 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '89a39d1c-4045-4c4b-a669-094b8f2dfcdc', 'ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್', 'Industrial Service Business 2.0', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 56 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('ffbd84dc-1817-4473-bb9b-d580788052d2', 'SOCIAL-WELFARE-DEPAR-15', '81b60538-519f-4131-bd38-c390f2d882d6', 'Industrial Service Business - ISB (in association with Bank) Maximum Rs. 1 lakh subsidy', 'Subsidy', 0, 'Industrial Service Busines (in collaboration with the Bank) development scheme, assistance from the Corporation to start self-employment units for unemployed youths and women of the Scheduled Caste community in small scale industry, service sector and business sectors and the rest is loan from the bank. Subsidy of 20% of the unit cost or a maximum of Rs 1 lakh', '["Applicant Aadhar Cards (Mandatory)", "Applicant Ration Card (Mandatory)", "Applicant Voter ID (Mandatory)", "Caste & Income Certificate issued by competent authority (Mandatory)", "Project Report / Quotation (Mandatory)", "The applicant must declare they have not received prior assistance from the Corporation (Mandatory)", "Applicant Aadhar Card (Mandatory)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 56 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '89a39d1c-4045-4c4b-a669-094b8f2dfcdc', 'ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್', 'Industrial Service Business 1.0', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 56 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('5bb469fa-4881-47de-96a5-a8fe825c9c47', 'REVENUE-DEPARTMENT-10', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Agricultural Family member certificate', 'Certificate', 14, 'This certificate is issued to the applicant who belong to the agricultural family and this certificate is use claim the reservation in education and other governament benefits', '["Address Proof", "Epic", "Genealogical certificate", "ID Proof", "Rationcard", "RTC Copy", "Self Declaration before RI.DT"]', '["Citizens in need of this service"]', '[]', '["Application Submission – The applicant submits their request through one of four channels: NK (Nadakacheri) Users, Seva Sindhu Users, Online Users, or GP (Gram Panchayat) Users.", "Document Upload – The applicant uploads all required supporting documents for their application.", "Field Verification – The VAO (Village Accountant) and RI (Revenue Inspector) conduct field verification using the Samyojane Mobile Application. This mobile app is also where applications get processed.", "Digital Signing / Approval – The application moves to the TAH/DT/GOT login stage, where the authorized officer can Approve, Modify, or Reject the application, followed by digital signing.", "Certificate Delivery to Citizen – Once approved and signed, the citizen is notified via SMS with a link to download the certificate, and a PDF copy is also sent via email — accessible on desktop, tablet, or mobile."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '3094b139-9107-4665-b080-413a0975c11c', 'ವ್ಯವಸಾಯಗಾರರ ಕುಟುಂಬದ ದೃಡೀಕರಣ ಪತ್ರ', NULL, NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, 40.00, NULL, 'ಕೃಷಿ ಕುಟುಂಬಕ್ಕೆ ಸೇರಿದ ಅರ್ಜಿದಾರರಿಗೆ ಈ ಪ್ರಮಾಣಪತ್ರವನ್ನು ನೀಡಲಾಗುತ್ತದೆ. ಶಿಕ್ಷಣದಲ್ಲಿ ಮೀಸಲಾತಿ ಹಾಗೂ ಇತರ ಸರ್ಕಾರಿ ಸೌಲಭ್ಯಗಳನ್ನು ಪಡೆಯಲು ಈ ಪ್ರಮಾಣಪತ್ರ ಬಳಸಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, true, 'Yes', '["ಸೇವೆಯ ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಸಾರ್ವಜನಿಕರು"]', '["ಅರ್ಜಿ ಸಲ್ಲಿಕೆ – ಅರ್ಜಿದಾರರು ನಾಲ್ಕು ವಿಧಾನಗಳಲ್ಲಿ ಒಂದರ ಮೂಲಕ ಅರ್ಜಿ ಸಲ್ಲಿಸುತ್ತಾರೆ: NK (ನಾಡಕಚೇರಿ) ಬಳಕೆದಾರರು, ಸೇವಾ ಸಿಂಧು ಬಳಕೆದಾರರು, ಆನ್‌ಲೈನ್ ಬಳಕೆದಾರರು, ಅಥವಾ GP (ಗ್ರಾಮ ಪಂಚಾಯತ್) ಬಳಕೆದಾರರು.", "ದಾಖಲೆಗಳ ಅಪ್‌ಲೋಡ್ – ಅರ್ಜಿದಾರರು ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಪೋಷಕ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಕು.", "ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ – VAO (ಗ್ರಾಮ ಲೆಕ್ಕಾಧಿಕಾರಿ) ಮತ್ತು RI (ಕಂದಾಯ ನಿರೀಕ್ಷಕರು) ಸಂಯೋಜನೆ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ ನಡೆಸುತ್ತಾರೆ. ಅರ್ಜಿಗಳ ಪ್ರಕ್ರಿಯೆಯೂ ಇದೇ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ನಡೆಯುತ್ತದೆ.", "ಡಿಜಿಟಲ್ ಸಹಿ / ಅನುಮೋದನೆ – ಅರ್ಜಿಯು TAH/DT/GOT ಲಾಗಿನ್ ಹಂತಕ್ಕೆ ಹೋಗುತ್ತದೆ, ಅಲ್ಲಿ ಅಧಿಕೃತ ಅಧಿಕಾರಿ ಅರ್ಜಿಯನ್ನು ಅನುಮೋದಿಸಬಹುದು, ಮಾರ್ಪಡಿಸಬಹುದು, ಅಥವಾ ತಿರಸ್ಕರಿಸಬಹುದು, ನಂತರ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡಲಾಗುತ್ತದೆ.", "ಪ್ರಮಾಣಪತ್ರ ವಿತರಣೆ – ಅನುಮೋದನೆ ಮತ್ತು ಸಹಿ ಆದ ನಂತರ, ನಾಗರಿಕರಿಗೆ SMS ಮೂಲಕ ಪ್ರಮಾಣಪತ್ರ ಡೌನ್‌ಲೋಡ್ ಮಾಡುವ ಲಿಂಕ್ ಕಳುಹಿಸಲಾಗುತ್ತದೆ, ಮತ್ತು PDF ಪ್ರತಿಯನ್ನು ಇಮೇಲ್ ಮೂಲಕವೂ ಕಳುಹಿಸಲಾಗುತ್ತದೆ — ಇದನ್ನು ಡೆಸ್ಕ್‌ಟಾಪ್, ಟ್ಯಾಬ್ಲೆಟ್, ಅಥವಾ ಮೊಬೈಲ್‌ನಲ್ಲಿ ಪ್ರವೇಶಿಸಬಹುದು."]', 1, '["ವಿಳಾಸದ ಪುರಾವೆ", "ಎಫಿಕ್", "ವಂಶವೃಕ್ಷ", "ಗುರುತಿನ ಚೀಟಿ", "ಪಡಿತರ ಚೀಟಿ", "ಪಹಣಿ ಪ್ರತಿ", "ಸ್ವಯಂ ಘೋಷಣೆ ಪತ್ರ ರಾನಿ/ಉ ತ ಸಮ್ಮುಖದಲ್ಲಿ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('6928a5fa-52c7-45a6-96df-669b6cf067bf', 'SOCIAL-WELFARE-DEPAR-14', '81b60538-519f-4131-bd38-c390f2d882d6', 'Ganga Kalyana', 'Loan with Subsidy', 0, 'Under this scheme, irrigation facilities are provided to small and very small scheduled caste farmers with 1½ to 5.00 acres of land by drilling boreholes, installing pump sets, and electrifying them. In certain districts such as Kolar, Chikkaballapur, Bangalore (Rural), Bangalore (City), Tumkur, and Ramnagar, the unit cost has been increased to Rs.4.75 lakh due to declining groundwater levels. Of this amount, Rs.4.25 lakh will be subsidized, and the remaining Rs.50,000/- will be provided as a term loan.In other districts, the unit cost is fixed at Rs.3.75 lakh, with Rs.3.25 lakh provided as a subsidy and Rs.50,000/- lakh as a term loan. Additionally, out of the unit cost, Rs.75,000 per borehole will be allocated to the respective Escom for electrification, within the subsidy limit of the unit cost.', '["Applicant Aadhar Cards (Optional)", "Ration Card (Mandatory)", "Aadhar linked PassBook Front Page Photo (Mandatory)", "Caste & Income Certificate issued by competent authority (Optional)", "The applicant must declare they have not received prior assistance from the Corporation (Optional)", "Passport size photo of the applicant (Mandatory)", "Small and Marginal Farmer Certificate (Mandatory)", "RTC (Mandatory)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicants must be at least 21 years old and there is no upper age limit.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability.", "The applicants must be small and medium marginal farmers and should not have access to irrigation facilities."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '89a39d1c-4045-4c4b-a669-094b8f2dfcdc', 'ಗಂಗಾ ಕಲ್ಯಾಣ ಯೋಜನೆ', 'Ganga Kalyana', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಈ ಯೋಜನೆಯಡಿ 1½ ಎಕರೆಯಿಂದ 5.00 ಎಕರೆ ಜಮೀನು ಹೊಂದಿರುವ ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸಣ್ಣ ಮತ್ತು ಅತೀ ಸಣ್ಣ ರೈತರ ಜಮೀನಿನಲ್ಲಿ ಕೊಳವೆಬಾವಿ ಕೊರೆಸಿ, ಪಂಪ್ ಸೆಟ್ ಅಳವಡಿಸಿ ವಿದ್ಯುದ್ಧೀಕರಣಗೊಳಿಸಿ ನೀರಾವರಿ ಸೌಲಭ್ಯ ಕಲ್ಪಿಸಲಾಗುತ್ತಿದೆ. ಈ ಯೋಜನೆಯಡಿ ಕೋಲಾರ, ಚಿಕ್ಕಬಳ್ಳಾಪುರ, ಬೆಂಗಳೂರು(ಗ್ರಾ), ಬೆಂಗಳೂರು(ನಗರ), ತುಮಕೂರು ಮತ್ತು ರಾಮನಗರ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಅಂತರ್ಜಲ ಮಟ್ಟ ಕೆಳಗೆ ಕುಸಿದಿರುವುದರಿಂದ ಈ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಘಟಕ ವೆಚ್ಚ ರೂ.4.75 ಲಕ್ಷಕ್ಕೆ ಹೆಚ್ಚಿಸಲಾಗಿದ್ದು, ಇದರಲ್ಲಿ ರೂ.4.25 ಲಕ್ಷ ಸಹಾಯಧನವಿದ್ದು, ಉಳಿದ ರೂ.50,000/- ಅವಧಿಸಾಲವಾಗಿರುತ್ತದೆ. ಇತರೆ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಘಟಕ ವೆಚ್ಚ ರೂ.3.75 ಲಕ್ಷ ನಿಗದಿಪಡಿಸಿದ್ದು, ಇದರಲ್ಲಿ ರೂ.3.25 ಲಕ್ಷ ಸಹಾಯಧನ ಮತ್ತು ರೂ.50,000/- ಅವಧಿಸಾಲವಾಗಿರುತ್ತದೆ. ಘಟಕ ವೆಚ್ಚದ ಪೈಕಿ ವಿದ್ಯುದ್ದೀಕರಣಕ್ಕೆ ಘಟಕ ವೆಚ್ಚದ ಸಹಾಯಧನದ ಮಿತಿಯಲ್ಲಿ ಪ್ರತಿ ಕೊಳವೆಬಾವಿಗೆ ರೂ.75,000/-ಗಳನ್ನು ಸಂಬಂಧಿಸಿದ ಎಸ್ಕಾಂಗಳಿಗೆ ಬಿಡುಗಡೆ ಮಾಡಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಕನಿಷ್ಠ 21 ವರ್ಷಗಳು ಪೂರ್ಣಗೊಂಡಿರಬೇಕು ಗರಿಷ್ಠ ವಯೋಮಿತಿ ತೆಗೆದು ಹಾಕಲಾಗಿದೆ.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು.", "ಅರ್ಜಿದಾರರು ಸಣ್ಣ ಮತ್ತು ಅತಿ ಸಣ್ಣ ರೈತರಾಗಿರಬೇಕು ಹಾಗೂ ನೀರಾವರಿ ಸೌಲಭ್ಯ ಹೊಂದಿರಬಾರದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('f2e9c01e-8fb6-462f-a367-d0cc7fe3e798', 'SOCIAL-WELFARE-DEPAR-13', '81b60538-519f-4131-bd38-c390f2d882d6', 'Dairy Farming Scheme', 'Subsidy', 0, 'Under the Dairy Farming Scheme, beneficiaries are provided a subsidy of ₹1.25 lakhs to support the establishment and development of dairy farming for sustainable livelihood and milk production', '["Applicant Aadhar Card (Optional)", "Ration card (Optional)", "Aadhar linked PassBook Front Page Photo (Optional)", "Caste & Income Certificate issued by competent authority (Optional)", "The applicant must declare they have not received prior assistance from the Corporation (Optional)", "Passport size Photo (Optional)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)", "Project Report / Quotation (Optional)"]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '89a39d1c-4045-4c4b-a669-094b8f2dfcdc', 'ಹೈನುಗಾರಿಕೆ ಯೋಜನೆ', 'Dairy Farming Scheme', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಈ ಯೋಜನೆಯ ಅಡಿಯಲ್ಲಿ ಫಲಾನುಭವಿಗಳಿಗೆ ಹೈನುಗಾರಿಕೆಯನ್ನು ಸ್ಥಾಪಿಸಲು ಮತ್ತು ಅಭಿವೃದ್ಧಿಪಡಿಸಲು ₹1.25 ಲಕ್ಷಗಳ ಸಹಾಯಧನವನ್ನು ನೀಡಲಾಗುತ್ತದೆ, ಇದು ಸ್ಥಿರ ಜೀವನೋಪಾಯ ಮತ್ತು ಹಾಲು ಉತ್ಪಾದನೆಗೆ ನೆರವಾಗುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('e6a395c9-48a4-4b35-b0b8-c3918dfd4f31', 'REVENUE-DEPARTMENT-132', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Certified Copies', 'General', 0, 'Generate Certified copy', '[]', '["Requirement on the basis of publics and requisite fee"]', '[]', '["Parties to submit the application in Form 22 to the dealing assistant", "Dealing Assistant scrutinizes the documents.", "Parties to pay the applicable fees", "Office search", "SR signs the document copy", "Parties collect Certified Copy of the document"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'fd613c45-3686-46ff-b312-218b68f54fad', 'ದೃಢೀಕೃತ ಪ್ರತಿಗಳು', 'To Generate Certified copy of regitered document', NULL, NULL, NULL, NULL, NULL, NULL, 'ದೃಢೀಕೃತ ಪ್ರತಿಯನ್ನು ರಚಿಸಿ', NULL, NULL, NULL, NULL, NULL, '["ಸಾರ್ವಜನಿಕರ ಅಗತ್ಯತೆ ಮತ್ತು ಅಗತ್ಯ ಶುಲ್ಕ"]', '["ಸಂಬಂಧಪಟ್ಟವರು ''ನಮೂನೆ 22'' ರಲ್ಲಿನ ಅರ್ಜಿಯನ್ನು ಸಂಬಂಧಿತ ಸಹಾಯಕರಿಗೆ (Dealing Assistant) ಸಲ್ಲಿಸಬೇಕು.", "ಸಂಬಂಧಿತ ಸಹಾಯಕರು ದಾಖಲೆಗಳನ್ನು ಪರಿಶೀಲಿಸುತ್ತಾರೆ.", "ಸಂಬಂಧಪಟ್ಟವರು ಅನ್ವಯವಾಗುವ ಶುಲ್ಕವನ್ನು ಪಾವತಿಸಬೇಕು.", "ಕಚೇರಿ ದಾಖಲೆಗಳ ಪರಿಶೀಲನೆ (Office search).", "ಉಪ-ನೋಂದಣಾಧಿಕಾರಿ (SR) ದಾಖಲೆಯ ಪ್ರತಿಯ ಮೇಲೆ ಸಹಿ ಮಾಡುತ್ತಾರೆ.", "ಸಂಬಂಧಪಟ್ಟವರು ದಾಖಲೆಯ ದೃಢೀಕೃತ ಪ್ರತಿಯನ್ನು ಪಡೆದುಕೊಳ್ಳುತ್ತಾರೆ."]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('1844f58e-8f4d-420c-8806-f064c08ad1d4', 'REVENUE-DEPARTMENT-131', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Encumberance Ceritificate', 'General', 0, 'Generate Encumbarence', '["Form No.22 to be filled and submit to office"]', '["Requrement of the Public"]', '[]', '["Form No.22 with all particulars and after verify the search application amount to be collected by the party then E.C to be prepaird as per rules."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'fd613c45-3686-46ff-b312-218b68f54fad', 'ಭಾರಮುಕ್ತ ಪ್ರಮಾಣಪತ್ರ', 'To generate EC', NULL, NULL, NULL, NULL, 10.00, NULL, 'ಭಾರ ಪ್ರಮಾಣಪತ್ರವನ್ನು ರಚಿಸಿ', NULL, NULL, NULL, NULL, NULL, '["ಸಾರ್ವಜನಿಕರ ಅಗತ್ಯ"]', '["ಎಲ್ಲಾ ವಿವರಗಳೊಂದಿಗೆ ನಮೂನೆ-22 ಅನ್ನು ಪರಿಶೀಲಿಸಿ, ಸಂಬಂಧಪಟ್ಟವರಿಂದ ಪಡೆಯಬೇಕಾದ ಹುಡುಕಾಟದ ಶುಲ್ಕವನ್ನು ಖಚಿತಪಡಿಸಿಕೊಂಡ ನಂತರ, ನಿಯಮಗಳ ಪ್ರಕಾರ ಇ.ಸಿ. (E.C.) ಯನ್ನು ಸಿದ್ಧಪಡಿಸಬೇಕು."]', 1, '["ನಮೂನೆ ಸಂಖ್ಯೆ 22ನ್ನು ಭರ್ತಿ ಮಾಡಿ ಕಚೇರಿಗೆ ಸಲ್ಲಿಸಬೇಕು."]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('c31bc761-9851-4339-a2b8-f9b5d2c5a135', 'REVENUE-DEPARTMENT-130', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Marriage Registration', 'General', 0, 'Registration of Marriage', '[]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'fd613c45-3686-46ff-b312-218b68f54fad', 'ವಿವಾಹ ನೋಂದಣಿ', 'To Register the marriage', NULL, NULL, NULL, NULL, NULL, NULL, 'ವಿವಾಹ ನೋಂದಣಿ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('4aef5ef7-2671-4fee-903d-32324f6ab69a', 'REVENUE-DEPARTMENT-129', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'To generate eStamp - Digital eStamp', 'General', 0, 'To Generate eStamp Paper', '[]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'fd613c45-3686-46ff-b312-218b68f54fad', 'eStamp ಅನ್ನು ಉತ್ಪಾದಿಸಲು - ಡಿಜಿಟಲ್ eStamp', 'Digital eSTamp', NULL, NULL, NULL, NULL, NULL, NULL, 'ಇ-ಸ್ಟಾಂಪ್ ಪೇಪರ್ ಅನ್ನು ರಚಿಸಲು', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('04ae0e8d-2c07-4ade-b846-6915a3703f85', 'REVENUE-DEPARTMENT-40', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Mythiri', 'Certificate', 21, 'This certificate is issued to economically distressed gender (lingatva) minorities (hijras, koris, Joggapandu, FTM, Mangal Mukhiyas). Gender minorities between age 18 and 64 and annual income not lesser than 32,000 and this scheme is to avail monthly pensions', '["Address Proof", "Epic", "ID Proof", "Rationcard", "Transgender Medical Certificate"]', '["Movie is to be produced in any of the following languages: Kannada, Tulu, Konkani, Kodava, Banjara, Byari"]', '[]', '["Application Submission – The applicant submits their request through one of four channels: NK (Nadakacheri) Users, Seva Sindhu Users, Online Users, or GP (Gram Panchayat) Users.", "Document Upload – The applicant uploads all required supporting documents for their application.", "Field Verification – The VAO (Village Accountant) and RI (Revenue Inspector) conduct field verification using the Samyojane Mobile Application. This mobile app is also where applications get processed.", "Digital Signing / Approval – The application moves to the TAH/DT/GOT login stage, where the authorized officer can Approve, Modify, or Reject the application, followed by digital signing.", "Certificate Delivery to Citizen – Once approved and signed, the citizen is notified via SMS with a link to download the certificate, and a PDF copy is also sent via email — accessible on desktop, tablet, or mobile."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '3094b139-9107-4665-b080-413a0975c11c', 'ಮೈತ್ರಿ', NULL, NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, NULL, NULL, 'ಆರ್ಥಿಕ ಸಂಕಷ್ಟದಲ್ಲಿರುವ ಲಿಂಗತ್ವ ಅಲ್ಪಸಂಖ್ಯಾತರಿಗೆ (ಹಿಜ್ರಾ, ಕೋರಿ, ಜೋಗಪ್ಪಂಡು, FTM, ಮಂಗಳಮುಖಿಯರು) ಈ ಪ್ರಮಾಣಪತ್ರವನ್ನು ನೀಡಲಾಗುತ್ತದೆ. 18 ರಿಂದ 64 ವರ್ಷ ವಯಸ್ಸಿನ ಲಿಂಗತ್ವ ಅಲ್ಪಸಂಖ್ಯಾತರಿಗೆ, ವಾರ್ಷಿಕ ಆದಾಯ ರೂ. 32,000 ಕ್ಕಿಂತ ಕಡಿಮೆ ಇರುವವರಿಗೆ, ಮಾಸಿಕ ಪಿಂಚಣಿ ಪಡೆಯಲು ಈ ಯೋಜನೆ ಬಳಸಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, true, 'Yes', '["ಚಲನಚಿತ್ರವು ಕನ್ನಡ, ತುಳು, ಕೊಂಕಣಿ, ಕೊಡವ, ಬಂಜಾರ, ಬ್ಯಾರಿ ಭಾಷೆಗಳಲ್ಲಿ ಚಿತ್ರಿಸತಕ್ಕದ್ದು"]', '["ಅರ್ಜಿ ಸಲ್ಲಿಕೆ – ಅರ್ಜಿದಾರರು ನಾಲ್ಕು ವಿಧಾನಗಳಲ್ಲಿ ಒಂದರ ಮೂಲಕ ಅರ್ಜಿ ಸಲ್ಲಿಸುತ್ತಾರೆ: NK (ನಾಡಕಚೇರಿ) ಬಳಕೆದಾರರು, ಸೇವಾ ಸಿಂಧು ಬಳಕೆದಾರರು, ಆನ್‌ಲೈನ್ ಬಳಕೆದಾರರು, ಅಥವಾ GP (ಗ್ರಾಮ ಪಂಚಾಯತ್) ಬಳಕೆದಾರರು.", "ದಾಖಲೆಗಳ ಅಪ್‌ಲೋಡ್ – ಅರ್ಜಿದಾರರು ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಪೋಷಕ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಕು.", "ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ – VAO (ಗ್ರಾಮ ಲೆಕ್ಕಾಧಿಕಾರಿ) ಮತ್ತು RI (ಕಂದಾಯ ನಿರೀಕ್ಷಕರು) ಸಂಯೋಜನೆ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ ನಡೆಸುತ್ತಾರೆ. ಅರ್ಜಿಗಳ ಪ್ರಕ್ರಿಯೆಯೂ ಇದೇ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ನಡೆಯುತ್ತದೆ.", "ಡಿಜಿಟಲ್ ಸಹಿ / ಅನುಮೋದನೆ – ಅರ್ಜಿಯು TAH/DT/GOT ಲಾಗಿನ್ ಹಂತಕ್ಕೆ ಹೋಗುತ್ತದೆ, ಅಲ್ಲಿ ಅಧಿಕೃತ ಅಧಿಕಾರಿ ಅರ್ಜಿಯನ್ನು ಅನುಮೋದಿಸಬಹುದು, ಮಾರ್ಪಡಿಸಬಹುದು, ಅಥವಾ ತಿರಸ್ಕರಿಸಬಹುದು, ನಂತರ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡಲಾಗುತ್ತದೆ.", "ಪ್ರಮಾಣಪತ್ರ ವಿತರಣೆ – ಅನುಮೋದನೆ ಮತ್ತು ಸಹಿ ಆದ ನಂತರ, ನಾಗರಿಕರಿಗೆ SMS ಮೂಲಕ ಪ್ರಮಾಣಪತ್ರ ಡೌನ್‌ಲೋಡ್ ಮಾಡುವ ಲಿಂಕ್ ಕಳುಹಿಸಲಾಗುತ್ತದೆ, ಮತ್ತು PDF ಪ್ರತಿಯನ್ನು ಇಮೇಲ್ ಮೂಲಕವೂ ಕಳುಹಿಸಲಾಗುತ್ತದೆ — ಇದನ್ನು ಡೆಸ್ಕ್‌ಟಾಪ್, ಟ್ಯಾಬ್ಲೆಟ್, ಅಥವಾ ಮೊಬೈಲ್‌ನಲ್ಲಿ ಪ್ರವೇಶಿಸಬಹುದು."]', 1, '["ವಿಳಾಸದ ಪುರಾವೆ", "ಎಫಿಕ್", "ಗುರುತಿನ ಚೀಟಿ", "ಪಡಿತರ ಚೀಟಿ", "ಲಿಂಗತ್ವ ಅಲ್ಪಸಂಖ್ಯಾತರೆಂದು ವೈದ್ಯಕೀಯ ದೃಢೀಕರಣ ಪತ್ರ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('8177c8af-db93-4167-8d8a-f86a3e62264b', 'REVENUE-DEPARTMENT-142', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Arya Vysya Vahini/Aahaara Vahini Scheme', 'General', 0, 'Financial assistance of up to ₹1 lakh is provided to eligible Arya Vysya applicants to purchase a new electric/CNG three-wheeler or four-wheeler for self-employment, with an additional ₹1 lakh subsidy if the vehicle is converted into a food truck.', '["Aadhaar,", "Ration Card,", "Caste and Income Certificate"]', '["Age : 21-55", "Income : upto 6 lakh"]', '[]', '["Step 1 – Access the Portal", "Visit the official Arya Vysya Vahini / Aahaara Vahini Scheme application portal.", "Step 2 – Aadhaar Authentication", "Enter the applicant’s Aadhaar Number and complete Aadhaar OTP verification.", "Step 3 – Caste & Income Certificate Validation", "Enter the required Caste Certificate and Income Certificate details for verification.", "Step 4 – Driving Licence (DL) Validation", "Enter the applicant’s Driving Licence (DL) details and complete the DL validation.", "Step 5 – Enter Basic Details", "After successful validation, enter the applicant’s required basic and personal details.", "Step 6 – Upload Required Documents", "Upload the required supporting documents as specified for the scheme.", "Step 7 – Submit Application", "Review all details and uploaded documents, and submit the application.", "Step 8 – Application Acknowledgement", "After successful submission:", "A PDF copy of the submitted application will be generated.", "An SMS containing the Application Number will be sent to the registered mobile number."]', NULL, NULL, 'https://aryavysya.karnataka.gov.in/foodtruckscheme', true, '2026-10-30 16:55:56.458552+00', 'a0bd208d-579d-4e30-9879-42d172d22f6c', 'ಆರ್ಯ ವೈಶ್ಯ ವಾಹಿನಿ/ಆಹಾರ ವಾಹಿನಿ ಯೋಜನೆ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಅರ್ಹ ಆರ್ಯ ವೈಶ್ಯ ಅರ್ಜಿದಾರರಿಗೆ ಸ್ವಯಂ ಉದ್ಯೋಗಕ್ಕಾಗಿ ಹೊಸ ಎಲೆಕ್ಟ್ರಿಕ್/CNG ಮೂರು ಅಥವಾ ನಾಲ್ಕು ಚಕ್ರದ ವಾಹನ ಖರೀದಿಸಲು ₹1 ಲಕ್ಷದವರೆಗೆ ಸಹಾಯಧನ ನೀಡಲಾಗುತ್ತದೆ ಹಾಗೂ ವಾಹನವನ್ನು ಫುಡ್ ಟ್ರಕ್ ಆಗಿ ಪರಿವರ್ತಿಸಿದರೆ ಹೆಚ್ಚುವರಿಯಾಗಿ ₹1 ಲಕ್ಷ ಸಹಾಯಧನ ನೀಡಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '[]', '["ಹಂತ 1 – ಪೋರ್ಟಲ್ ಪ್ರವೇಶ", "ಅಧಿಕೃತ ಆರ್ಯ ವೈಶ್ಯ ವಾಹನ / ಆಹಾರ ವಾಹನ ಯೋಜನೆಯ ಅರ್ಜಿ ಪೋರ್ಟಲ್‌ಗೆ ಭೇಟಿ ನೀಡಿ.", "ಹಂತ 2 – ಆಧಾರ್ ದೃಢೀಕರಣ", "ಅರ್ಜಿದಾರರ ಆಧಾರ್ ಸಂಖ್ಯೆಯನ್ನು ನಮೂದಿಸಿ, ಆಧಾರ್ OTP ಮೂಲಕ ದೃಢೀಕರಣ ಪೂರ್ಣಗೊಳಿಸಿ.", "ಹಂತ 3 – ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ ಪರಿಶೀಲನೆ", "ಅಗತ್ಯವಿರುವ ಜಾತಿ ಪ್ರಮಾಣಪತ್ರ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರದ ವಿವರಗಳನ್ನು ನಮೂದಿಸಿ ಪರಿಶೀಲನೆ ಪೂರ್ಣಗೊಳಿಸಿ.", "ಹಂತ 4 – ಚಾಲನಾ ಪರವಾನಗಿ (DL) ಪರಿಶೀಲನೆ", "ಅರ್ಜಿದಾರರ ಚಾಲನಾ ಪರವಾನಗಿ (DL) ವಿವರಗಳನ್ನು ನಮೂದಿಸಿ DL ಪರಿಶೀಲನೆ ಪೂರ್ಣಗೊಳಿಸಿ.", "ಹಂತ 5 – ಮೂಲ ವಿವರಗಳ ನಮೂದು", "ಪರಿಶೀಲನೆ ಯಶಸ್ವಿಯಾದ ನಂತರ ಅರ್ಜಿದಾರರ ಅಗತ್ಯವಿರುವ ಮೂಲ ಮತ್ತು ವೈಯಕ್ತಿಕ ವಿವರಗಳನ್ನು ನಮೂದಿಸಿ.", "ಹಂತ 6 – ಅಗತ್ಯ ದಾಖಲೆಗಳ ಅಪ್‌ಲೋಡ್", "ಯೋಜನೆಗೆ ಅಗತ್ಯವಿರುವ ಪೋಷಕ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ.", "ಹಂತ 7 – ಅರ್ಜಿ ಸಲ್ಲಿಕೆ", "ಎಲ್ಲಾ ವಿವರಗಳು ಮತ್ತು ದಾಖಲೆಗಳನ್ನು ಪರಿಶೀಲಿಸಿ ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಿ.", "ಹಂತ 8 – ಅರ್ಜಿ ಸ್ವೀಕೃತಿ", "ಅರ್ಜಿ ಯಶಸ್ವಿಯಾಗಿ ಸಲ್ಲಿಕೆಯಾದ ನಂತರ:", "ಸಲ್ಲಿಸಿದ ಅರ್ಜಿಯ PDF ಪ್ರತಿ ಲಭ್ಯವಾಗುತ್ತದೆ.", "ನೋಂದಾಯಿತ ಮೊಬೈಲ್ ಸಂಖ್ಯೆಗೆ ಅರ್ಜಿ ಸಂಖ್ಯೆಯನ್ನು ಒಳಗೊಂಡ SMS ಕಳುಹಿಸಲಾಗುತ್ತದೆ."]', 1, '["ಆಧಾರ್,", "ಪಡಿತರ ಚೀಟಿ,", "ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('6a8e7e14-85e3-4ea4-94a0-37b39fc95d87', 'REVENUE-DEPARTMENT-141', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Vasavi Ganga Kalyana Scheme', 'General', 0, 'The Vasavi Ganga Kalyana Scheme provides irrigation assistance to small Arya Vysya farmers through a loan of up to ₹2 lakh at 4% interest and ₹75,000 subsidy for electrification.', '["Aadhaar,", "Ration Card,", "Caste and Income Certificate''", "FRUITS ID"]', '["Age : 21-55", "Income : upto 6 lakh"]', '[]', '["Step 1 – Access the Portal", "Visit the official Vasavi Ganga Kalyana Scheme application portal.", "Step 2 – Aadhaar Authentication", "Enter the applicant’s Aadhaar Number and complete Aadhaar OTP verification.", "Step 3 – Enter Caste & Income Certificate Details", "Enter the required Caste Certificate and Income Certificate details for verification.", "Step 4 – FRUITS ID Validation", "Enter the applicant’s FRUITS ID and complete the FRUITS ID validation.", "Step 5 – Enter Basic Details", "After successful validation, enter the applicant’s required basic and personal details.", "Step 6 – Upload Required Documents", "Upload the required supporting documents as specified for the scheme.", "Step 7 – Submit Application", "Review all the details and documents and submit the application.", "Step 8 – Application Acknowledgement", "After successful submission:", "A PDF copy of the submitted application will be generated.", "An SMS containing the Application Number will be sent to the registered mobile number."]', NULL, NULL, 'https://aryavysya.karnataka.gov.in/Vasavijalashakthi', true, '2026-10-30 16:55:56.458552+00', 'a0bd208d-579d-4e30-9879-42d172d22f6c', 'ವಾಸವಿ ಗಂಗಾ ಕಲ್ಯಾಣ ಯೋಜನೆ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ವಾಸವಿ ಗಂಗಾ ಕಲ್ಯಾಣ ಯೋಜನೆಯಡಿ ಸಣ್ಣ ಆರ್ಯ ವೈಶ್ಯ ರೈತರಿಗೆ ನೀರಾವರಿ ಸೌಲಭ್ಯಕ್ಕಾಗಿ ಶೇ.4ರ ಬಡ್ಡಿಯಲ್ಲಿ ₹2 ಲಕ್ಷದವರೆಗೆ ಸಾಲ ಹಾಗೂ ವಿದ್ಯುದ್ದೀಕರಣಕ್ಕಾಗಿ ₹75,000 ಸಹಾಯಧನ ನೀಡಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '[]', '["ಹಂತ 1 – ಪೋರ್ಟಲ್ ಪ್ರವೇಶ", "ಅಧಿಕೃತ ವಾಸವಿ ಗಂಗಾ ಕಲ್ಯಾಣ ಯೋಜನೆಯ ಅರ್ಜಿ ಪೋರ್ಟಲ್‌ಗೆ ಭೇಟಿ ನೀಡಿ.", "ಹಂತ 2 – ಆಧಾರ್ ದೃಢೀಕರಣ", "ಅರ್ಜಿದಾರರ ಆಧಾರ್ ಸಂಖ್ಯೆಯನ್ನು ನಮೂದಿಸಿ, ಆಧಾರ್ OTP ಮೂಲಕ ದೃಢೀಕರಣ ಪೂರ್ಣಗೊಳಿಸಿ.", "ಹಂತ 3 – ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರದ ವಿವರಗಳು", "ಅಗತ್ಯವಿರುವ ಜಾತಿ ಪ್ರಮಾಣಪತ್ರ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರದ ವಿವರಗಳನ್ನು ನಮೂದಿಸಿ.", "ಹಂತ 4 – FRUITS ID ಪರಿಶೀಲನೆ", "ಅರ್ಜಿದಾರರ FRUITS ID ಅನ್ನು ನಮೂದಿಸಿ ಮತ್ತು FRUITS ID ಪರಿಶೀಲನೆ ಪೂರ್ಣಗೊಳಿಸಿ.", "ಹಂತ 5 – ಮೂಲ ವಿವರಗಳ ನಮೂದು", "ಪರಿಶೀಲನೆ ಯಶಸ್ವಿಯಾದ ನಂತರ ಅರ್ಜಿದಾರರ ಅಗತ್ಯವಿರುವ ಮೂಲ ಮತ್ತು ವೈಯಕ್ತಿಕ ವಿವರಗಳನ್ನು ನಮೂದಿಸಿ.", "ಹಂತ 6 – ಅಗತ್ಯ ದಾಖಲೆಗಳ ಅಪ್‌ಲೋಡ್", "ಯೋಜನೆಗೆ ಅಗತ್ಯವಿರುವ ಪೋಷಕ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ.", "ಹಂತ 7 – ಅರ್ಜಿ ಸಲ್ಲಿಕೆ", "ಎಲ್ಲಾ ವಿವರಗಳು ಮತ್ತು ದಾಖಲೆಗಳನ್ನು ಪರಿಶೀಲಿಸಿ ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಿ.", "ಹಂತ 8 – ಅರ್ಜಿ ಸ್ವೀಕೃತಿ", "ಅರ್ಜಿ ಯಶಸ್ವಿಯಾಗಿ ಸಲ್ಲಿಕೆಯಾದ ನಂತರ:", "ಸಲ್ಲಿಸಿದ ಅರ್ಜಿಯ PDF ಪ್ರತಿ ಲಭ್ಯವಾಗುತ್ತದೆ.", "ನೋಂದಾಯಿತ ಮೊಬೈಲ್ ಸಂಖ್ಯೆಗೆ ಅರ್ಜಿ ಸಂಖ್ಯೆಯನ್ನು ಒಳಗೊಂಡ SMS ಕಳುಹಿಸಲಾಗುತ್ತದೆ."]', 1, '["ಆಧಾರ್,", "ಪಡಿತರ ಚೀಟಿ,", "ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ,", "FRUITS ಐ.ಡಿ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('951d2e8f-941c-44a4-a4b5-b5abeb1ae38c', 'REVENUE-DEPARTMENT-140', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Arivu Education Loan', 'General', 0, 'Education loan up to ₹1,00,000 per year at 2% interest is provided to eligible Arya Vysya students pursuing professional courses.', '["Aadhaar,", "Ration Card,", "Caste and Income Certificate,", "Copy of CET Admission,", "Last year mark sheet,", "Study Certificate,", "Fee Structure"]', '["Age : 18-35", "Income : upto 6 lakh"]', '[]', '["Step 1 – Access the Portal", "Visit the official Arivu Education Loan application portal and enter the applicant’s Aadhaar Number.", "Step 2 – Aadhaar OTP Verification", "Enter the OTP received on the registered mobile number to complete Aadhaar authentication.", "Step 3 – Caste & Income Certificate Validation", "Enter the Caste Certificate and Income Certificate details. The certificates will be validated before proceeding to the next stage.", "Step 4 – College Details & Validation", "Enter the required college details. The college information will then undergo validation.", "Step 5 – Upload Required Documents", "Upload the following documents:", "Copy of CET Admission", "Last Year’s Mark Sheet", "Study Certificate", "Fee Structure", "Step 6 – Enter Basic Details", "Enter the required applicant and other basic details.", "Step 7 – Submit Application", "Review all the information and uploaded documents, and submit the application.", "Step 8 – Application Acknowledgement", "After successful submission:", "A PDF copy of the submitted application will be generated.", "An SMS containing the Application Number will be sent to the registered mobile number."]', NULL, NULL, 'https://aryavysya.karnataka.gov.in/ArivuEduLoan', true, '2026-10-30 16:55:56.458552+00', 'a0bd208d-579d-4e30-9879-42d172d22f6c', 'ಅರಿವು ಶೈಕ್ಷಣಿಕ ಸಾಲ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ವೃತ್ತಿಪರ ಕೋರ್ಸ್', NULL, NULL, NULL, NULL, NULL, '[]', '["ಹಂತ 1 – ಪೋರ್ಟಲ್ ಪ್ರವೇಶ", "ಅಧಿಕೃತ ಪೋರ್ಟಲ್‌ಗೆ ಭೇಟಿ ನೀಡಿ ಮತ್ತು ಆಧಾರ್ ಸಂಖ್ಯೆಯನ್ನು ನಮೂದಿಸಿ.", "ಹಂತ 2 – ಆಧಾರ್ OTP ದೃಢೀಕರಣ", "ನೋಂದಾಯಿತ ಮೊಬೈಲ್ ಸಂಖ್ಯೆಗೆ ಬರುವ ಆಧಾರ್ OTP ನಮೂದಿಸಿ ದೃಢೀಕರಣ ಪೂರ್ಣಗೊಳಿಸಿ.", "ಹಂತ 3 – ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ ಪರಿಶೀಲನೆ", "ಜಾತಿ ಪ್ರಮಾಣಪತ್ರ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರದ ವಿವರಗಳನ್ನು ನಮೂದಿಸಿ. ಪ್ರಮಾಣಪತ್ರಗಳ ಪರಿಶೀಲನೆ ಮತ್ತು ದೃಢೀಕರಣ ಪೂರ್ಣಗೊಂಡ ನಂತರ ಮುಂದಿನ ಹಂತಕ್ಕೆ ತೆರಳಬಹುದು.", "ಹಂತ 4 – ಕಾಲೇಜು ವಿವರಗಳು ಮತ್ತು ಕಾಲೇಜು ಪರಿಶೀಲನೆ", "ಅರ್ಜಿದಾರರು ಕಾಲೇಜಿನ ಅಗತ್ಯ ವಿವರಗಳನ್ನು ನಮೂದಿಸಬೇಕು. ನಂತರ ಕಾಲೇಜಿನ ವಿವರಗಳನ್ನು ಪರಿಶೀಲನೆ/Validation ಮಾಡಲಾಗುತ್ತದೆ.", "ಹಂತ 5 – ಅಗತ್ಯ ದಾಖಲೆಗಳ ಅಪ್‌ಲೋಡ್", "ಕೆಳಗಿನ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಕು:", "CET ಪ್ರವೇಶ ಪತ್ರದ ಪ್ರತಿ", "ಕಳೆದ ವರ್ಷದ ಅಂಕಪಟ್ಟಿ", "ಅಧ್ಯಯನ ಪ್ರಮಾಣಪತ್ರ (Study Certificate)", "ಶುಲ್ಕ ರಚನೆ (Fee Structure)", "ಹಂತ 6 – ಮೂಲ ವಿವರಗಳ ನಮೂದು", "ಅಗತ್ಯವಿರುವ ವೈಯಕ್ತಿಕ ಮತ್ತು ಮೂಲ ವಿವರಗಳನ್ನು ನಮೂದಿಸಿ.", "ಹಂತ 7 – ಅರ್ಜಿ ಸಲ್ಲಿಕೆ", "ಎಲ್ಲಾ ವಿವರಗಳು ಮತ್ತು ದಾಖಲೆಗಳನ್ನು ಪರಿಶೀಲಿಸಿ ಅರ್ಜಿಯನ್ನು ಅಂತಿಮವಾಗಿ ಸಲ್ಲಿಸಿ.", "ಹಂತ 8 – ಅರ್ಜಿ ಸ್ವೀಕೃತಿ", "ಅರ್ಜಿ ಯಶಸ್ವಿಯಾಗಿ ಸಲ್ಲಿಕೆಯಾದ ನಂತರ:", "ಸಲ್ಲಿಸಿದ ಅರ್ಜಿಯ PDF ಪ್ರತಿ ಲಭ್ಯವಾಗುತ್ತದೆ.", "ನೋಂದಾಯಿತ ಮೊಬೈಲ್ ಸಂಖ್ಯೆಗೆ ಅರ್ಜಿ ಸಂಖ್ಯೆಯನ್ನು ಒಳಗೊಂಡ SMS ಕಳುಹಿಸಲಾಗುತ್ತದೆ."]', 1, '["ಆಧಾರ್,", "ಪಡಿತರ ಚೀಟಿ,", "ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ,", "ಸಿ.ಇ.ಟಿ ಪ್ರವೇಶ ಪ್ರತಿ,", "ಕಳೆದ ವರ್ಷದ ಅಂಕಪಟ್ಟಿ,", "ವ್ಯಾಸಂಗ ಪ್ರಮಾಣ ಪತ್ರ,", "ಫೀ ಸ್ಟ್ರಕ್ಚರ್ ಪ್ರತಿ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('cba110aa-33e5-4be9-bba1-fe6c9d1a38fc', 'REVENUE-DEPARTMENT-139', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Self Employment Direct Loan', 'General', 0, 'Financial assistance of ₹1,00,000 (₹20,000 subsidy + ₹80,000 loan at 4% interest) to eligible Arya Vysya applicants for starting self-employment activities.', '["Aadhaar,", "Ration Card,", "Caste and Income Certificate"]', '["Age : 18-55", "Income : upto 3 lakh"]', '[]', '["Step 1 – Access the Portal", "Visit the official Self-Employment Loan application portal:", "Self-Employment Loan Portal", "Step 2 – Aadhaar Authentication", "Enter your Aadhaar Number and complete Aadhaar OTP verification.", "Step 3 – Certificate Verification", "Enter your Caste Certificate and Income Certificate details. The system validates the certificates before proceeding.", "Step 4 – Enter Applicant Details", "Once the certificates are successfully validated, enter the required basic and personal details.", "Step 5 – Submit Application", "Review the entered information and submit the application.", "Step 6 – Application Acknowledgement", "After successful submission:", "A PDF copy of the submitted application is generated.", "An SMS containing the Application Number is sent to the registered mobile number."]', NULL, NULL, 'https://aryavysya.karnataka.gov.in/SelfEmploymentLoan', true, '2026-10-30 16:55:56.458552+00', 'a0bd208d-579d-4e30-9879-42d172d22f6c', 'ಸ್ವಯಂ ಉದ್ಯೋಗ ನೇರ ಸಾಲ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಸ್ವಯಂ ಉದ್ಯೋಗ ಆರಂಭಿಸಲು ಅರ್ಹ ಆರ್ಯ ವೈಶ್ಯರಿಗೆ ₹1,00,000 ಆರ್ಥಿಕ ನೆರವು (₹20,000 ಸಹಾಯಧನ + ₹80,000 ಸಾಲ) ನೀಡಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '[]', '["ಹಂತ 1 – ಪೋರ್ಟಲ್ ಪ್ರವೇಶ", "ಅಧಿಕೃತ ಸ್ವಯಂ ಉದ್ಯೋಗ ಸಾಲ ಅರ್ಜಿ ಪೋರ್ಟಲ್‌ಗೆ ಭೇಟಿ ನೀಡಿ:", "ಸ್ವಯಂ ಉದ್ಯೋಗ ಸಾಲ ಪೋರ್ಟಲ್", "ಹಂತ 2 – ಆಧಾರ್ ದೃಢೀಕರಣ", "ಅರ್ಜಿದಾರರು ತಮ್ಮ ಆಧಾರ್ ಸಂಖ್ಯೆಯನ್ನು ನಮೂದಿಸಿ, ನೋಂದಾಯಿತ ಮೊಬೈಲ್ ಸಂಖ್ಯೆಗೆ ಬರುವ ಆಧಾರ್ OTP ಮೂಲಕ ದೃಢೀಕರಣ ಪೂರ್ಣಗೊಳಿಸಬೇಕು.", "ಹಂತ 3 – ಪ್ರಮಾಣಪತ್ರಗಳ ಪರಿಶೀಲನೆ", "ಜಾತಿ ಪ್ರಮಾಣಪತ್ರ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರದ ವಿವರಗಳನ್ನು ನಮೂದಿಸಿ. ವ್ಯವಸ್ಥೆಯ ಮೂಲಕ ಪ್ರಮಾಣಪತ್ರಗಳ ಸ್ವಯಂಚಾಲಿತ ಪರಿಶೀಲನೆ ಮತ್ತು ದೃಢೀಕರಣ ನಡೆಯುತ್ತದೆ.", "ಹಂತ 4 – ಮೂಲ ವಿವರಗಳ ನಮೂದು", "ಪ್ರಮಾಣಪತ್ರಗಳ ಪರಿಶೀಲನೆ ಯಶಸ್ವಿಯಾದ ನಂತರ, ಅರ್ಜಿದಾರರು ಅಗತ್ಯವಿರುವ ಮೂಲ ವೈಯಕ್ತಿಕ ವಿವರಗಳನ್ನು ನಮೂದಿಸಬೇಕು.", "ಹಂತ 5 – ಅರ್ಜಿ ಸಲ್ಲಿಕೆ", "ನಮೂದಿಸಿದ ಎಲ್ಲಾ ವಿವರಗಳನ್ನು ಪರಿಶೀಲಿಸಿ, ಅರ್ಜಿಯನ್ನು ಅಂತಿಮವಾಗಿ ಸಲ್ಲಿಸಬೇಕು.", "ಹಂತ 6 – ಅರ್ಜಿ ಸ್ವೀಕೃತಿ", "ಅರ್ಜಿ ಯಶಸ್ವಿಯಾಗಿ ಸಲ್ಲಿಕೆಯಾದ ನಂತರ:", "ಸಲ್ಲಿಸಿದ ಅರ್ಜಿಯ PDF ಪ್ರತಿ ಲಭ್ಯವಾಗುತ್ತದೆ.", "ನೋಂದಾಯಿತ ಮೊಬೈಲ್ ಸಂಖ್ಯೆಗೆ ಅರ್ಜಿ ಸಂಖ್ಯೆಯನ್ನು ಒಳಗೊಂಡ SMS ಕಳುಹಿಸಲಾಗುತ್ತದೆ."]', 1, '["ಆಧಾರ್,", "ಪಡಿತರ ಚೀಟಿ,", "ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('c2d45374-e8ab-4743-a9d5-f157f713eb9f', 'REVENUE-DEPARTMENT-39', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Indira Gandhi National Old Age Pension', 'Certificate', 21, 'The scheme is used to provide a pension to all citizens above 60 years of Age. People who are above 60 years of age. and the Total income should be below Rs 32,000 to avail monthly pensions', '["Address Proof", "Age Certificate", "Epic", "ID Proof", "Rationcard"]', '["The date of travel must be at least 15 days from the current date"]', '[]', '["Application Submission – The applicant submits their request through one of four channels: NK (Nadakacheri) Users, Seva Sindhu Users, Online Users, or GP (Gram Panchayat) Users.", "Document Upload – The applicant uploads all required supporting documents for their application.", "Field Verification – The VAO (Village Accountant) and RI (Revenue Inspector) conduct field verification using the Samyojane Mobile Application. This mobile app is also where applications get processed.", "Digital Signing / Approval – The application moves to the TAH/DT/GOT login stage, where the authorized officer can Approve, Modify, or Reject the application, followed by digital signing.", "Certificate Delivery to Citizen – Once approved and signed, the citizen is notified via SMS with a link to download the certificate, and a PDF copy is also sent via email — accessible on desktop, tablet, or mobile."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '3094b139-9107-4665-b080-413a0975c11c', 'ಇಂದಿರಾ ಗಾಂಧಿ ರಾಷ್ಟ್ರೀಯ ವೃದ್ಧಾಪ್ಯ ವೇತನ', NULL, NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, NULL, NULL, '60 ವರ್ಷಕ್ಕಿಂತ ಮೇಲ್ಪಟ್ಟ ಎಲ್ಲಾ ನಾಗರಿಕರಿಗೆ ಪಿಂಚಣಿ ಒದಗಿಸಲು ಈ ಯೋಜನೆ ಬಳಸಲಾಗುತ್ತದೆ. ಮಾಸಿಕ ಪಿಂಚಣಿ ಪಡೆಯಲು 60 ವರ್ಷಕ್ಕಿಂತ ಮೇಲ್ಪಟ್ಟವರಾಗಿರಬೇಕು ಮತ್ತು ಒಟ್ಟು ಆದಾಯ ರೂ. 32,000 ಕ್ಕಿಂತ ಕಡಿಮೆ ಇರಬೇಕು.', NULL, NULL, NULL, true, 'Yes', '["ಪ್ರಯಾಣದ ದಿನಾಂಕ ಇಂದಿನಿಂದ ೧೫ ದಿನಗಳ ನಂತರದ್ದಾಗಿರಬೇಕು"]', '["ಅರ್ಜಿ ಸಲ್ಲಿಕೆ – ಅರ್ಜಿದಾರರು ನಾಲ್ಕು ವಿಧಾನಗಳಲ್ಲಿ ಒಂದರ ಮೂಲಕ ಅರ್ಜಿ ಸಲ್ಲಿಸುತ್ತಾರೆ: NK (ನಾಡಕಚೇರಿ) ಬಳಕೆದಾರರು, ಸೇವಾ ಸಿಂಧು ಬಳಕೆದಾರರು, ಆನ್‌ಲೈನ್ ಬಳಕೆದಾರರು, ಅಥವಾ GP (ಗ್ರಾಮ ಪಂಚಾಯತ್) ಬಳಕೆದಾರರು.", "ದಾಖಲೆಗಳ ಅಪ್‌ಲೋಡ್ – ಅರ್ಜಿದಾರರು ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಪೋಷಕ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಕು.", "ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ – VAO (ಗ್ರಾಮ ಲೆಕ್ಕಾಧಿಕಾರಿ) ಮತ್ತು RI (ಕಂದಾಯ ನಿರೀಕ್ಷಕರು) ಸಂಯೋಜನೆ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ ನಡೆಸುತ್ತಾರೆ. ಅರ್ಜಿಗಳ ಪ್ರಕ್ರಿಯೆಯೂ ಇದೇ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ನಡೆಯುತ್ತದೆ.", "ಡಿಜಿಟಲ್ ಸಹಿ / ಅನುಮೋದನೆ – ಅರ್ಜಿಯು TAH/DT/GOT ಲಾಗಿನ್ ಹಂತಕ್ಕೆ ಹೋಗುತ್ತದೆ, ಅಲ್ಲಿ ಅಧಿಕೃತ ಅಧಿಕಾರಿ ಅರ್ಜಿಯನ್ನು ಅನುಮೋದಿಸಬಹುದು, ಮಾರ್ಪಡಿಸಬಹುದು, ಅಥವಾ ತಿರಸ್ಕರಿಸಬಹುದು, ನಂತರ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡಲಾಗುತ್ತದೆ.", "ಪ್ರಮಾಣಪತ್ರ ವಿತರಣೆ – ಅನುಮೋದನೆ ಮತ್ತು ಸಹಿ ಆದ ನಂತರ, ನಾಗರಿಕರಿಗೆ SMS ಮೂಲಕ ಪ್ರಮಾಣಪತ್ರ ಡೌನ್‌ಲೋಡ್ ಮಾಡುವ ಲಿಂಕ್ ಕಳುಹಿಸಲಾಗುತ್ತದೆ, ಮತ್ತು PDF ಪ್ರತಿಯನ್ನು ಇಮೇಲ್ ಮೂಲಕವೂ ಕಳುಹಿಸಲಾಗುತ್ತದೆ — ಇದನ್ನು ಡೆಸ್ಕ್‌ಟಾಪ್, ಟ್ಯಾಬ್ಲೆಟ್, ಅಥವಾ ಮೊಬೈಲ್‌ನಲ್ಲಿ ಪ್ರವೇಶಿಸಬಹುದು."]', 1, '["ವಿಳಾಸದ ಪುರಾವೆ", "ವಯಸ್ಸಿನ ದೃಢೀಕರಣ ಪತ್ರ", "ಎಫಿಕ್", "ಗುರುತಿನ ಚೀಟಿ", "ಪಡಿತರ ಚೀಟಿ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('cf1b5412-512b-4e93-8bb8-8cf590c686d3', 'THE-DEPARTMENT-OF-FO-1', '98c19fd4-7019-42a5-9af1-39cd53b9d099', 'Apply for New Licence -Manufacturer', 'General', 30, 'New Manufacturer Licence – Application for obtaining a new Legal Metrology licence to legally carry out manufacturing activities involving weights and measures.', '["Documents to be submitted for Manufacturer Licence – State Jurisdiction", "Applicant/Applicants Permanent Address Certificate/Aadhaar Card/Ration Card/Passport/Tax Paid Receipt/Electrical Bill(If anyone)", "Applicant/Firm’s GST Certificate.", "Applicant/Applicants/Firms Pan Card.", "Model Approval Certificate- Issuing by the Central Govt. of India.", "Partnership deed (in case of Partnership firm)", "Specimen Signature and Photos."]', '["As per Govt Notification No: AaNaSa 223 EeBaTha 19 (e-office) Dated: 10-12-2020 available in website"]', '[]', '["Applicant need to register in E-mapan > Applicant Need to Fill the application >", "Applicant need to upload the Required Documents>", "Applicant has to make Payment >", "Applicant has to make E-Sign>", "Applicant will Submit the application", "and Should take the approval from department"]', NULL, NULL, 'https://emapan.karnataka.gov.in/Homepage_Sevaone.aspx??DepartmentID=14&ServiceID=3000&SevaOneUserID=<<sevaOneUserID>>&Token=<<token>>', true, '2026-10-30 16:55:56.458552+00', 'ef8e63a7-734d-4bc0-91ff-71ba8aa95423', 'ತೂಕ, ಅಳತೆ, ತೂಕ ಮತ್ತು ಅಳತೆ ಸಾಧನಗಳ ತಯಾರಕರ ರಾಜ್ಯವ್ಯಾಪ್ತಿ ಪರವಾನಗಿಗಳು.', 'New Manufacturer Licence – Registration of a new manufacturer under Legal Metrology.', NULL, 'State', NULL, NULL, NULL, NULL, 'ಹೊಸ ತಯಾರಕರ ಪರವಾನಗಿ – ತೂಕ ಮತ್ತು ಅಳತೆಗಳಿಗೆ ಸಂಬಂಧಿಸಿದ ಉತ್ಪಾದನಾ ಚಟುವಟಿಕೆಗಳನ್ನು ಕಾನೂನುಬದ್ಧವಾಗಿ ನಡೆಸಲು ಹೊಸ ತೂಕ, ಅಳತೆ, ತೂಕ ಮತ್ತು ಅಳತೆ ಸಾಧನಗಳ ತಯಾರಕರ ರಾಜ್ಯವ್ಯಾಪ್ತಿ ಪರವಾನಗಿ ಪಡೆಯಲು ಸಲ್ಲಿಸುವ ಅರ್ಜಿ.', NULL, NULL, NULL, true, 'Yes', '["ಸರ್ಕಾರದ ಅಧಿಸೂಚನೆ ಸಂಖ್ಯೆ: ಆನಾಸ 223 ಇಭತ 19 (ಇ-ಆಫೀಸ್) ದಿನಾಂಕ:10-12-2020 ರಲ್ಲಿ ತಿಳಿಸಿರುವ ಕಾರ್ಯವಿಧಾನದಂತೆ ವೆಬ್"]', '["ಅರ್ಜಿದಾರರು ಇ-ಮಾಪನ್ (E-Mapan) ಪೋರ್ಟಲ್"]', 1, '["ತೂಕ, ಅಳತೆ, ತೂಕ ಮತ್ತು ಅಳತೆ ಸಾಧನಗಳ ತಯಾರಕರ ರಾಜ್ಯವ್ಯಾಪ್ತಿ ಪರವಾನಗಿ ಪಡೆಯಲು ಸಲ್ಲಿಸಬೇಕಾದ ದಾಖಲೆಗಳು:", "ಅಭ್ಯರ್ಥಿ/ಅಭ್ಯರ್ಥಿಗಳ ಖಾಯಂ ವಾಸಸ್ಥಳದ ಧೃಡೀಕರಣ ಪತ್ರ./ ಆಧಾರ್ ಕಾರ್ಡ್/ರೇಷನ್ ಕಾರ್ಡ್/ಪಾಸ್"]', NULL, NULL, '1066');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('1e41ce20-a6f9-47b5-9876-f34cafa61f5c', 'THE-DEPARTMENT-OF-FO-6', '98c19fd4-7019-42a5-9af1-39cd53b9d099', 'Amendment Repairer Licence', 'General', 30, 'Amendment Of Repairer Licence – Application to update or modify the existing repairer licence details based on changes in the registered information.', '["Documents to be submitted for Repairer Licence – State Jurisdiction - Amendment", "Existing Original License Issued/Renewal.", "Court Order(for Firm Name Amendment)", "Details of Article(for Article Amendment)", "Details of Nominee/Director/Proprietary (for Nominee/Director/Proprietary Amendment)", "Applicant/Applicants Permanent Address Certificate/Aadhaar Card/Ration Card/Passport/Tax Paid Receipt/Electrical Bill(If anyone)", "Applicant/Firm’s GST Certificate.", "Applicant/Applicants/Firms Pan Card.", "Partnership deed (in case of Partnership firm)", "Applicant/Applicants Qualification Certificate.", "Specimen Signature and Photos.", "Verification Certificate of Testing Equipments & Loan Articles.", "Loan Articles & Testing Equipments Tools List."]', '["As per Govt Notification No: AaNaSa 223 EeBaTha 19 (e-office) Dated: 10-12-2020 available in website"]', '[]', '["Applicant need to register in E-mapan > Applicant Need to Fill the application >", "Applicant need to upload the Required Documents>", "Applicant has to make Payment >", "Applicant has to make E-Sign>", "Applicant will Submit the application", "and Should take the approval from department"]', NULL, NULL, 'https://emapan.karnataka.gov.in/Homepage_Sevaone.aspx??DepartmentID=14&ServiceID=3011&SevaOneUserID=<<sevaOneUserID>>&Token=<<token>>', true, '2026-10-30 16:55:56.458552+00', 'ef8e63a7-734d-4bc0-91ff-71ba8aa95423', 'ತೂಕ, ಅಳತೆ, ತೂಕ ಮತ್ತು ಅಳತೆ ಸಾಧನಗಳ ದುರಸ್ಥಿದಾರರ ರಾಜ್ಯವ್ಯಾಪ್ತಿ ಪರವಾನಗಿಗಳ ತಿದ್ದುಪಡಿ.', 'Amendment Repairer Licence – Modification of details in an existing repairer licence.', NULL, 'State', NULL, NULL, NULL, NULL, 'ದುರಸ್ಥಿ ಪರವಾನಗಿ ತಿದ್ದುಪಡಿ - ನೋಂದಾಯಿತ ಮಾಹಿತಿಯಲ್ಲಿ ಬದಲಾವಣೆಗಳಾದಾಗ, ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ದುರಶ್ತಿದಾರರ ಪರವಾನಗಿಯ ವಿವರಗಳನ್ನು ತಿದ್ದುಪಡಿ ಮಾಡಲು ಸಲ್ಲಿಸುವ ಅರ್ಜಿ.', NULL, NULL, NULL, true, 'Yes', '["ಸರ್ಕಾರದ ಅಧಿಸೂಚನೆ ಸಂಖ್ಯೆ: ಆನಾಸ 223 ಇಭತ 19 (ಇ-ಆಫೀಸ್) ದಿನಾಂಕ:10-12-2020 ರಲ್ಲಿ ತಿಳಿಸಿರುವ ಕಾರ್ಯವಿಧಾನದಂತೆ ವೆಬ್"]', '["ಅರ್ಜಿದಾರರು ಇ-ಮಾಪನ್ (E-Mapan) ಪೋರ್ಟಲ್"]', 1, '["ತೂಕ, ಅಳತೆ, ತೂಕ ಮತ್ತು ಅಳತೆ ಸಾಧನಗಳ ದುರಸ್ಥಿದಾರರ ರಾಜ್ಯವ್ಯಾಪ್ತಿ ಪರವಾನಗಿ ತಿದ್ದುಪಡಿ ಮಾಡಲು ಸಲ್ಲಿಸಬೇಕಾದ ದಾಖಲೆಗಳು:", "ಚಾಲ್ತಿಯಲ್ಲಿರುವ ಮೂಲ ಪರವಾನಗಿ (ಅಸ್ತಿತ್ವ/ನವೀಕರಣ)", "ಕೋರ್ಟ್ ಆದೇಶ (ಸಂಸ್ಥೆಯ ಹೆಸರು ತಿದ್ದುಪಡಿಗಾಗಿ)", "ಆರ್ಟಿಕಲ್ಸ್ನ ವಿವರ (ಆರ್ಟಿಕಲ್ಸ್ನ ತಿದ್ದುಪಡಿಗಾಗಿ)", "ನಾಮಿನಿ/ನಿರ್ದೇಶಕ/ಮಾಲೀಕರ ವಿವರ (ನಾಮಿನಿ/ನಿರ್ದೇಶಕ/ಮಾಲೀಕರ ತಿದ್ದುಪಡಿಗಾಗಿ)", "ಅಭ್ಯರ್ಥಿ/ಅಭ್ಯರ್ಥಿಗಳ ಖಾಯಂ ವಾಸಸ್ಥಳದ ಧೃಡೀಕರಣ ಪತ್ರ./ ಆಧಾರ್ ಕಾರ್ಡ್/ರೇಷನ್ ಕಾರ್ಡ್/ಪಾಸ್"]', NULL, NULL, '2302');
