INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('7dea7fb9-ebec-46c0-be05-171163e5d654', 'REVENUE-DEPARTMENT-21', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Bonafide Certificate', 'Certificate', 7, 'This certificate is issued in evidence showing that an agriculturist who cultivates land personally. And having minimal land to get the government benefits.', '["Address Proof", "Epic", "ID Proof", "RTC Copy", "RTC Copy1", "RTC Copy2"]', '["Citizens in need of this service"]', '[]', '["Application Submission – The applicant submits their request through one of four channels: NK (Nadakacheri) Users, Seva Sindhu Users, Online Users, or GP (Gram Panchayat) Users.", "Document Upload – The applicant uploads all required supporting documents for their application.", "Field Verification – The VAO (Village Accountant) and RI (Revenue Inspector) conduct field verification using the Samyojane Mobile Application. This mobile app is also where applications get processed.", "Digital Signing / Approval – The application moves to the TAH/DT/GOT login stage, where the authorized officer can Approve, Modify, or Reject the application, followed by digital signing.", "Certificate Delivery to Citizen – Once approved and signed, the citizen is notified via SMS with a link to download the certificate, and a PDF copy is also sent via email — accessible on desktop, tablet, or mobile."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '3094b139-9107-4665-b080-413a0975c11c', 'ಬೋನಫೈಡ್ ದೃಡಿಕರಣ ಪತ್ರ', NULL, NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, 40.00, NULL, 'ಭೂಮಿಯನ್ನು ವೈಯಕ್ತಿಕವಾಗಿ ಬೆಳೆಸುವ ಕೃಷಿಕನಾಗಿರುವುದಕ್ಕೂ, ಕನಿಷ್ಠ ಪ್ರಮಾಣದ ಭೂಮಿಯನ್ನು ಹೊಂದಿರುವುದಕ್ಕೂ ಸಾಕ್ಷಿಯಾಗಿ ಸರ್ಕಾರಿ ಸೌಲಭ್ಯಗಳನ್ನು ಪಡೆಯಲು ಈ ಪ್ರಮಾಣಪತ್ರವನ್ನು ನೀಡಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, true, 'Yes', '["ಸೇವೆಯ ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಸಾರ್ವಜನಿಕರು"]', '["ಅರ್ಜಿ ಸಲ್ಲಿಕೆ – ಅರ್ಜಿದಾರರು ನಾಲ್ಕು ವಿಧಾನಗಳಲ್ಲಿ ಒಂದರ ಮೂಲಕ ಅರ್ಜಿ ಸಲ್ಲಿಸುತ್ತಾರೆ: NK (ನಾಡಕಚೇರಿ) ಬಳಕೆದಾರರು, ಸೇವಾ ಸಿಂಧು ಬಳಕೆದಾರರು, ಆನ್‌ಲೈನ್ ಬಳಕೆದಾರರು, ಅಥವಾ GP (ಗ್ರಾಮ ಪಂಚಾಯತ್) ಬಳಕೆದಾರರು.", "ದಾಖಲೆಗಳ ಅಪ್‌ಲೋಡ್ – ಅರ್ಜಿದಾರರು ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಪೋಷಕ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಕು.", "ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ – VAO (ಗ್ರಾಮ ಲೆಕ್ಕಾಧಿಕಾರಿ) ಮತ್ತು RI (ಕಂದಾಯ ನಿರೀಕ್ಷಕರು) ಸಂಯೋಜನೆ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ ನಡೆಸುತ್ತಾರೆ. ಅರ್ಜಿಗಳ ಪ್ರಕ್ರಿಯೆಯೂ ಇದೇ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ನಡೆಯುತ್ತದೆ.", "ಡಿಜಿಟಲ್ ಸಹಿ / ಅನುಮೋದನೆ – ಅರ್ಜಿಯು TAH/DT/GOT ಲಾಗಿನ್ ಹಂತಕ್ಕೆ ಹೋಗುತ್ತದೆ, ಅಲ್ಲಿ ಅಧಿಕೃತ ಅಧಿಕಾರಿ ಅರ್ಜಿಯನ್ನು ಅನುಮೋದಿಸಬಹುದು, ಮಾರ್ಪಡಿಸಬಹುದು, ಅಥವಾ ತಿರಸ್ಕರಿಸಬಹುದು, ನಂತರ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡಲಾಗುತ್ತದೆ.", "ಪ್ರಮಾಣಪತ್ರ ವಿತರಣೆ – ಅನುಮೋದನೆ ಮತ್ತು ಸಹಿ ಆದ ನಂತರ, ನಾಗರಿಕರಿಗೆ SMS ಮೂಲಕ ಪ್ರಮಾಣಪತ್ರ ಡೌನ್‌ಲೋಡ್ ಮಾಡುವ ಲಿಂಕ್ ಕಳುಹಿಸಲಾಗುತ್ತದೆ, ಮತ್ತು PDF ಪ್ರತಿಯನ್ನು ಇಮೇಲ್ ಮೂಲಕವೂ ಕಳುಹಿಸಲಾಗುತ್ತದೆ — ಇದನ್ನು ಡೆಸ್ಕ್‌ಟಾಪ್, ಟ್ಯಾಬ್ಲೆಟ್, ಅಥವಾ ಮೊಬೈಲ್‌ನಲ್ಲಿ ಪ್ರವೇಶಿಸಬಹುದು."]', 1, '["ವಿಳಾಸದ ಪುರಾವೆ", "ಎಫಿಕ್", "ಗುರುತಿನ ಚೀಟಿ", "ಪಹಣಿ ಪ್ರತಿ", "ಪಹಣಿ ಪ್ರತಿ1", "ಪಹಣಿ ಪ್ರತಿ2"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('30f6506f-ec0c-479d-9341-b6f82b5f7c84', 'REVENUE-DEPARTMENT-20', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Land holding Certificate', 'Certificate', 7, 'This certificate is issued to the applicant who holds the land used as a proof for ownership of land to avail the benefits of the governament', '["Address Proof", "Epic", "ID Proof", "Rationcard", "RTC Copy1", "RTC Copy2"]', '["Citizens in need of this service"]', '[]', '["Application Submission – The applicant submits their request through one of four channels: NK (Nadakacheri) Users, Seva Sindhu Users, Online Users, or GP (Gram Panchayat) Users.", "Document Upload – The applicant uploads all required supporting documents for their application.", "Field Verification – The VAO (Village Accountant) and RI (Revenue Inspector) conduct field verification using the Samyojane Mobile Application. This mobile app is also where applications get processed.", "Digital Signing / Approval – The application moves to the TAH/DT/GOT login stage, where the authorized officer can Approve, Modify, or Reject the application, followed by digital signing.", "Certificate Delivery to Citizen – Once approved and signed, the citizen is notified via SMS with a link to download the certificate, and a PDF copy is also sent via email — accessible on desktop, tablet, or mobile."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '3094b139-9107-4665-b080-413a0975c11c', 'ಭೂ ಹಿಡುವಳಿ ಪ್ರಮಾಣ ಪತ್ರ', NULL, NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, 40.00, NULL, 'ಭೂಮಿಯನ್ನು ಹೊಂದಿರುವ ಅರ್ಜಿದಾರರಿಗೆ ಭೂಸ್ವಾಮ್ಯದ ಸಾಕ್ಷಿಯಾಗಿ ಈ ಪ್ರಮಾಣಪತ್ರವನ್ನು ನೀಡಲಾಗುತ್ತದೆ ಮತ್ತು ಸರ್ಕಾರಿ ಸೌಲಭ್ಯಗಳನ್ನು ಪಡೆಯಲು ಬಳಸಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, true, 'Yes', '["ಸೇವೆಯ ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಸಾರ್ವಜನಿಕರು"]', '["ಅರ್ಜಿ ಸಲ್ಲಿಕೆ – ಅರ್ಜಿದಾರರು ನಾಲ್ಕು ವಿಧಾನಗಳಲ್ಲಿ ಒಂದರ ಮೂಲಕ ಅರ್ಜಿ ಸಲ್ಲಿಸುತ್ತಾರೆ: NK (ನಾಡಕಚೇರಿ) ಬಳಕೆದಾರರು, ಸೇವಾ ಸಿಂಧು ಬಳಕೆದಾರರು, ಆನ್‌ಲೈನ್ ಬಳಕೆದಾರರು, ಅಥವಾ GP (ಗ್ರಾಮ ಪಂಚಾಯತ್) ಬಳಕೆದಾರರು.", "ದಾಖಲೆಗಳ ಅಪ್‌ಲೋಡ್ – ಅರ್ಜಿದಾರರು ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಪೋಷಕ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಕು.", "ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ – VAO (ಗ್ರಾಮ ಲೆಕ್ಕಾಧಿಕಾರಿ) ಮತ್ತು RI (ಕಂದಾಯ ನಿರೀಕ್ಷಕರು) ಸಂಯೋಜನೆ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ ನಡೆಸುತ್ತಾರೆ. ಅರ್ಜಿಗಳ ಪ್ರಕ್ರಿಯೆಯೂ ಇದೇ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ನಡೆಯುತ್ತದೆ.", "ಡಿಜಿಟಲ್ ಸಹಿ / ಅನುಮೋದನೆ – ಅರ್ಜಿಯು TAH/DT/GOT ಲಾಗಿನ್ ಹಂತಕ್ಕೆ ಹೋಗುತ್ತದೆ, ಅಲ್ಲಿ ಅಧಿಕೃತ ಅಧಿಕಾರಿ ಅರ್ಜಿಯನ್ನು ಅನುಮೋದಿಸಬಹುದು, ಮಾರ್ಪಡಿಸಬಹುದು, ಅಥವಾ ತಿರಸ್ಕರಿಸಬಹುದು, ನಂತರ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡಲಾಗುತ್ತದೆ.", "ಪ್ರಮಾಣಪತ್ರ ವಿತರಣೆ – ಅನುಮೋದನೆ ಮತ್ತು ಸಹಿ ಆದ ನಂತರ, ನಾಗರಿಕರಿಗೆ SMS ಮೂಲಕ ಪ್ರಮಾಣಪತ್ರ ಡೌನ್‌ಲೋಡ್ ಮಾಡುವ ಲಿಂಕ್ ಕಳುಹಿಸಲಾಗುತ್ತದೆ, ಮತ್ತು PDF ಪ್ರತಿಯನ್ನು ಇಮೇಲ್ ಮೂಲಕವೂ ಕಳುಹಿಸಲಾಗುತ್ತದೆ — ಇದನ್ನು ಡೆಸ್ಕ್‌ಟಾಪ್, ಟ್ಯಾಬ್ಲೆಟ್, ಅಥವಾ ಮೊಬೈಲ್‌ನಲ್ಲಿ ಪ್ರವೇಶಿಸಬಹುದು."]', 1, '["ವಿಳಾಸದ ಪುರಾವೆ", "ಎಫಿಕ್", "ಗುರುತಿನ ಚೀಟಿ", "ಪಡಿತರ ಚೀಟಿ", "ಪಹಣಿ ಪ್ರತಿ1", "ಪಹಣಿ ಪ್ರತಿ2"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('24e80caf-a4bf-4d99-b45b-27f94e12f8bd', 'DEPARTMENT-OF-ANIMAL-3', 'e23b839a-6708-4a52-8bfd-d4e4c0a9691f', 'License for Poultry and Cattle Feed Manufacturing Units', 'General', 0, 'License for Poultry and Cattle Feed Manufacturing Units', '[]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '991c91bb-dda9-4d33-983e-ad37b41fc4bf', 'ಕೋಳಿ ಮತ್ತು ಜಾನುವಾರು ಮೇವು ತಯಾರಿಕಾ ಘಟಕಗಳಿಗೆ ಪರವಾನಗಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಕೋಳಿ ಮತ್ತು ಜಾನುವಾರು ಮೇವು ತಯಾರಿಕಾ ಘಟಕಗಳಿಗೆ ಪರವಾನಗಿ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('6cceb3c1-749c-49e1-bcfb-e001a8c5d633', 'REVENUE-DEPARTMENT-18', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Agricultural Labour Certficate', 'Certificate', 14, 'Any applicant whose principal means of livelihood is manual labour on land (and includes an artisan whose principal means of livelihood is the preparation of agricultural implements)', '["Address Proof", "Epic", "ID Proof", "Rationcard"]', '["Citizens in need of this service"]', '[]', '["Application Submission – The applicant submits their request through one of four channels: NK (Nadakacheri) Users, Seva Sindhu Users, Online Users, or GP (Gram Panchayat) Users.", "Document Upload – The applicant uploads all required supporting documents for their application.", "Field Verification – The VAO (Village Accountant) and RI (Revenue Inspector) conduct field verification using the Samyojane Mobile Application. This mobile app is also where applications get processed.", "Digital Signing / Approval – The application moves to the TAH/DT/GOT login stage, where the authorized officer can Approve, Modify, or Reject the application, followed by digital signing.", "Certificate Delivery to Citizen – Once approved and signed, the citizen is notified via SMS with a link to download the certificate, and a PDF copy is also sent via email — accessible on desktop, tablet, or mobile."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '3094b139-9107-4665-b080-413a0975c11c', 'ಕೃಷಿ ಕಾರ್ಮಿಕ ಪ್ರಮಾಣ ಪತ್ರ', NULL, NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, 40.00, NULL, 'ಭೂಮಿಯಲ್ಲಿ ಕೈಕೆಲಸವೇ ಮುಖ್ಯ ಜೀವನೋಪಾಯವಾಗಿರುವ ಯಾವುದೇ ಅರ್ಜಿದಾರರಿಗೆ (ಕೃಷಿ ಸಾಧನಗಳನ್ನು ತಯಾರಿಸುವುದೇ ಮುಖ್ಯ ಜೀವನೋಪಾಯವಾಗಿರುವ ಕಾರಿಗರರನ್ನು ಒಳಗೊಂಡಂತೆ) ಈ ಪ್ರಮಾಣಪತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ.', NULL, NULL, NULL, true, 'Yes', '["ಸೇವೆಯ ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಸಾರ್ವಜನಿಕರು"]', '["ಅರ್ಜಿ ಸಲ್ಲಿಕೆ – ಅರ್ಜಿದಾರರು ನಾಲ್ಕು ವಿಧಾನಗಳಲ್ಲಿ ಒಂದರ ಮೂಲಕ ಅರ್ಜಿ ಸಲ್ಲಿಸುತ್ತಾರೆ: NK (ನಾಡಕಚೇರಿ) ಬಳಕೆದಾರರು, ಸೇವಾ ಸಿಂಧು ಬಳಕೆದಾರರು, ಆನ್‌ಲೈನ್ ಬಳಕೆದಾರರು, ಅಥವಾ GP (ಗ್ರಾಮ ಪಂಚಾಯತ್) ಬಳಕೆದಾರರು.", "ದಾಖಲೆಗಳ ಅಪ್‌ಲೋಡ್ – ಅರ್ಜಿದಾರರು ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಪೋಷಕ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಕು.", "ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ – VAO (ಗ್ರಾಮ ಲೆಕ್ಕಾಧಿಕಾರಿ) ಮತ್ತು RI (ಕಂದಾಯ ನಿರೀಕ್ಷಕರು) ಸಂಯೋಜನೆ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ ನಡೆಸುತ್ತಾರೆ. ಅರ್ಜಿಗಳ ಪ್ರಕ್ರಿಯೆಯೂ ಇದೇ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ನಡೆಯುತ್ತದೆ.", "ಡಿಜಿಟಲ್ ಸಹಿ / ಅನುಮೋದನೆ – ಅರ್ಜಿಯು TAH/DT/GOT ಲಾಗಿನ್ ಹಂತಕ್ಕೆ ಹೋಗುತ್ತದೆ, ಅಲ್ಲಿ ಅಧಿಕೃತ ಅಧಿಕಾರಿ ಅರ್ಜಿಯನ್ನು ಅನುಮೋದಿಸಬಹುದು, ಮಾರ್ಪಡಿಸಬಹುದು, ಅಥವಾ ತಿರಸ್ಕರಿಸಬಹುದು, ನಂತರ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡಲಾಗುತ್ತದೆ.", "ಪ್ರಮಾಣಪತ್ರ ವಿತರಣೆ – ಅನುಮೋದನೆ ಮತ್ತು ಸಹಿ ಆದ ನಂತರ, ನಾಗರಿಕರಿಗೆ SMS ಮೂಲಕ ಪ್ರಮಾಣಪತ್ರ ಡೌನ್‌ಲೋಡ್ ಮಾಡುವ ಲಿಂಕ್ ಕಳುಹಿಸಲಾಗುತ್ತದೆ, ಮತ್ತು PDF ಪ್ರತಿಯನ್ನು ಇಮೇಲ್ ಮೂಲಕವೂ ಕಳುಹಿಸಲಾಗುತ್ತದೆ — ಇದನ್ನು ಡೆಸ್ಕ್‌ಟಾಪ್, ಟ್ಯಾಬ್ಲೆಟ್, ಅಥವಾ ಮೊಬೈಲ್‌ನಲ್ಲಿ ಪ್ರವೇಶಿಸಬಹುದು."]', 1, '["ವಿಳಾಸದ ಪುರಾವೆ", "ಎಫಿಕ್", "ಗುರುತಿನ ಚೀಟಿ", "ಪಡಿತರ ಚೀಟಿ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('05f4e83b-bffc-4da6-b356-6d6f2b9bb997', 'REVENUE-DEPARTMENT-17', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Small / Marginal farmer Certificate', 'Certificate', 14, 'This certificate is issued to a small and Marginal Farmer is a farmer whose landholding is up to minimal agricultural land to avail government benefits.', '["Address Proof", "Epic", "ID Proof", "Rationcard", "RTC Copy"]', '["Citizens in need of this service"]', '[]', '["Application Submission – The applicant submits their request through one of four channels: NK (Nadakacheri) Users, Seva Sindhu Users, Online Users, or GP (Gram Panchayat) Users.", "Document Upload – The applicant uploads all required supporting documents for their application.", "Field Verification – The VAO (Village Accountant) and RI (Revenue Inspector) conduct field verification using the Samyojane Mobile Application. This mobile app is also where applications get processed.", "Digital Signing / Approval – The application moves to the TAH/DT/GOT login stage, where the authorized officer can Approve, Modify, or Reject the application, followed by digital signing.", "Certificate Delivery to Citizen – Once approved and signed, the citizen is notified via SMS with a link to download the certificate, and a PDF copy is also sent via email — accessible on desktop, tablet, or mobile."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '3094b139-9107-4665-b080-413a0975c11c', 'ಸಣ್ಣ /ಅತಿ ಸಣ್ಣ ಹಿಡುವಳಿದಾರ ಪ್ರಮಾಣ ಪತ್ರ', NULL, NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, 40.00, NULL, 'ಕಡಿಮೆ ಕೃಷಿ ಭೂಮಿ ಹೊಂದಿರುವ ಸಣ್ಣ ಮತ್ತು ಅಂಚಿನ ರೈತರಿಗೆ ಸರ್ಕಾರಿ ಸೌಲಭ್ಯಗಳನ್ನು ಪಡೆಯಲು ಈ ಪ್ರಮಾಣಪತ್ರವನ್ನು ನೀಡಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, true, 'Yes', '["ಸೇವೆಯ ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಸಾರ್ವಜನಿಕರು"]', '["ಅರ್ಜಿ ಸಲ್ಲಿಕೆ – ಅರ್ಜಿದಾರರು ನಾಲ್ಕು ವಿಧಾನಗಳಲ್ಲಿ ಒಂದರ ಮೂಲಕ ಅರ್ಜಿ ಸಲ್ಲಿಸುತ್ತಾರೆ: NK (ನಾಡಕಚೇರಿ) ಬಳಕೆದಾರರು, ಸೇವಾ ಸಿಂಧು ಬಳಕೆದಾರರು, ಆನ್‌ಲೈನ್ ಬಳಕೆದಾರರು, ಅಥವಾ GP (ಗ್ರಾಮ ಪಂಚಾಯತ್) ಬಳಕೆದಾರರು.", "ದಾಖಲೆಗಳ ಅಪ್‌ಲೋಡ್ – ಅರ್ಜಿದಾರರು ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಪೋಷಕ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಕು.", "ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ – VAO (ಗ್ರಾಮ ಲೆಕ್ಕಾಧಿಕಾರಿ) ಮತ್ತು RI (ಕಂದಾಯ ನಿರೀಕ್ಷಕರು) ಸಂಯೋಜನೆ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ ನಡೆಸುತ್ತಾರೆ. ಅರ್ಜಿಗಳ ಪ್ರಕ್ರಿಯೆಯೂ ಇದೇ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ನಡೆಯುತ್ತದೆ.", "ಡಿಜಿಟಲ್ ಸಹಿ / ಅನುಮೋದನೆ – ಅರ್ಜಿಯು TAH/DT/GOT ಲಾಗಿನ್ ಹಂತಕ್ಕೆ ಹೋಗುತ್ತದೆ, ಅಲ್ಲಿ ಅಧಿಕೃತ ಅಧಿಕಾರಿ ಅರ್ಜಿಯನ್ನು ಅನುಮೋದಿಸಬಹುದು, ಮಾರ್ಪಡಿಸಬಹುದು, ಅಥವಾ ತಿರಸ್ಕರಿಸಬಹುದು, ನಂತರ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡಲಾಗುತ್ತದೆ.", "ಪ್ರಮಾಣಪತ್ರ ವಿತರಣೆ – ಅನುಮೋದನೆ ಮತ್ತು ಸಹಿ ಆದ ನಂತರ, ನಾಗರಿಕರಿಗೆ SMS ಮೂಲಕ ಪ್ರಮಾಣಪತ್ರ ಡೌನ್‌ಲೋಡ್ ಮಾಡುವ ಲಿಂಕ್ ಕಳುಹಿಸಲಾಗುತ್ತದೆ, ಮತ್ತು PDF ಪ್ರತಿಯನ್ನು ಇಮೇಲ್ ಮೂಲಕವೂ ಕಳುಹಿಸಲಾಗುತ್ತದೆ — ಇದನ್ನು ಡೆಸ್ಕ್‌ಟಾಪ್, ಟ್ಯಾಬ್ಲೆಟ್, ಅಥವಾ ಮೊಬೈಲ್‌ನಲ್ಲಿ ಪ್ರವೇಶಿಸಬಹುದು."]', 1, '["ವಿಳಾಸದ ಪುರಾವೆ", "ಎಫಿಕ್", "ಗುರುತಿನ ಚೀಟಿ", "ಪಡಿತರ ಚೀಟಿ", "ಪಹಣಿ ಪ್ರತಿ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('b859810c-abd5-4595-bd29-ebfc204bb318', 'REVENUE-DEPARTMENT-16', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Agriculturist Certificate', 'Certificate', 14, 'This certificate is issued to an applicant who works in his own agricultural land', '["Address Proof", "ID Proof", "RI Report", "RTC Copy", "VA Report"]', '["Citizens in need of this service"]', '[]', '["Application Submission – The applicant submits their request through one of four channels: NK (Nadakacheri) Users, Seva Sindhu Users, Online Users, or GP (Gram Panchayat) Users.", "Document Upload – The applicant uploads all required supporting documents for their application.", "Field Verification – The VAO (Village Accountant) and RI (Revenue Inspector) conduct field verification using the Samyojane Mobile Application. This mobile app is also where applications get processed.", "Digital Signing / Approval – The application moves to the TAH/DT/GOT login stage, where the authorized officer can Approve, Modify, or Reject the application, followed by digital signing.", "Certificate Delivery to Citizen – Once approved and signed, the citizen is notified via SMS with a link to download the certificate, and a PDF copy is also sent via email — accessible on desktop, tablet, or mobile."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '3094b139-9107-4665-b080-413a0975c11c', 'ವ್ಯವಸಾಯಗಾರ ದೃಡಿಕರಣ ಪತ್ರ', NULL, NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, 40.00, NULL, 'ತಮ್ಮದೇ ಕೃಷಿ ಭೂಮಿಯಲ್ಲಿ ಕೆಲಸ ಮಾಡುವ ಅರ್ಜಿದಾರರಿಗೆ ಈ ಪ್ರಮಾಣಪತ್ರವನ್ನು ನೀಡಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, true, 'Yes', '["ಸೇವೆಯ ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಸಾರ್ವಜನಿಕರು"]', '["ಅರ್ಜಿ ಸಲ್ಲಿಕೆ – ಅರ್ಜಿದಾರರು ನಾಲ್ಕು ವಿಧಾನಗಳಲ್ಲಿ ಒಂದರ ಮೂಲಕ ಅರ್ಜಿ ಸಲ್ಲಿಸುತ್ತಾರೆ: NK (ನಾಡಕಚೇರಿ) ಬಳಕೆದಾರರು, ಸೇವಾ ಸಿಂಧು ಬಳಕೆದಾರರು, ಆನ್‌ಲೈನ್ ಬಳಕೆದಾರರು, ಅಥವಾ GP (ಗ್ರಾಮ ಪಂಚಾಯತ್) ಬಳಕೆದಾರರು.", "ದಾಖಲೆಗಳ ಅಪ್‌ಲೋಡ್ – ಅರ್ಜಿದಾರರು ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಪೋಷಕ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಕು.", "ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ – VAO (ಗ್ರಾಮ ಲೆಕ್ಕಾಧಿಕಾರಿ) ಮತ್ತು RI (ಕಂದಾಯ ನಿರೀಕ್ಷಕರು) ಸಂಯೋಜನೆ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ ನಡೆಸುತ್ತಾರೆ. ಅರ್ಜಿಗಳ ಪ್ರಕ್ರಿಯೆಯೂ ಇದೇ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ನಡೆಯುತ್ತದೆ.", "ಡಿಜಿಟಲ್ ಸಹಿ / ಅನುಮೋದನೆ – ಅರ್ಜಿಯು TAH/DT/GOT ಲಾಗಿನ್ ಹಂತಕ್ಕೆ ಹೋಗುತ್ತದೆ, ಅಲ್ಲಿ ಅಧಿಕೃತ ಅಧಿಕಾರಿ ಅರ್ಜಿಯನ್ನು ಅನುಮೋದಿಸಬಹುದು, ಮಾರ್ಪಡಿಸಬಹುದು, ಅಥವಾ ತಿರಸ್ಕರಿಸಬಹುದು, ನಂತರ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡಲಾಗುತ್ತದೆ.", "ಪ್ರಮಾಣಪತ್ರ ವಿತರಣೆ – ಅನುಮೋದನೆ ಮತ್ತು ಸಹಿ ಆದ ನಂತರ, ನಾಗರಿಕರಿಗೆ SMS ಮೂಲಕ ಪ್ರಮಾಣಪತ್ರ ಡೌನ್‌ಲೋಡ್ ಮಾಡುವ ಲಿಂಕ್ ಕಳುಹಿಸಲಾಗುತ್ತದೆ, ಮತ್ತು PDF ಪ್ರತಿಯನ್ನು ಇಮೇಲ್ ಮೂಲಕವೂ ಕಳುಹಿಸಲಾಗುತ್ತದೆ — ಇದನ್ನು ಡೆಸ್ಕ್‌ಟಾಪ್, ಟ್ಯಾಬ್ಲೆಟ್, ಅಥವಾ ಮೊಬೈಲ್‌ನಲ್ಲಿ ಪ್ರವೇಶಿಸಬಹುದು."]', 1, '["ವಿಳಾಸದ ಪುರಾವೆ", "ಗುರುತಿನ ಚೀಟಿ", "ರಾ ನೀ ವರದಿ", "ಪಹಣಿ ಪ್ರತಿ", "ಗ್ರಾ ಲೇ ವರದಿ"]', NULL, NULL, NULL);
