INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('4e6a341d-127f-4336-8830-100d93be55f2', 'REVENUE-DEPARTMENT-12', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Land less Certificate', 'Certificate', 7, 'This certificate is issued to applicants who do not own any agricultural land. 
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('58585b5c-d89d-4c65-af47-7f3422661b39', 'REVENUE-DEPARTMENT-11', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'No Re-Marriage Certificate', 'Certificate', 7, 'This is certificate is a proof that the individual has not remarried. This certificate is required for availing of Government benefits.', '["Address Proof", "Death Certificate", "Epic", "ID Proof", "Rationcard", "self declaration"]', '["Citizens in need of this service"]', '[]', '["Application Submission – The applicant submits their request through one of four channels: NK (Nadakacheri) Users, Seva Sindhu Users, Online Users, or GP (Gram Panchayat) Users.", "Document Upload – The applicant uploads all required supporting documents for their application.", "Field Verification – The VAO (Village Accountant) and RI (Revenue Inspector) conduct field verification using the Samyojane Mobile Application. This mobile app is also where applications get processed.", "Digital Signing / Approval – The application moves to the TAH/DT/GOT login stage, where the authorized officer can Approve, Modify, or Reject the application, followed by digital signing.", "Certificate Delivery to Citizen – Once approved and signed, the citizen is notified via SMS with a link to download the certificate, and a PDF copy is also sent via email — accessible on desktop, tablet, or mobile."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '3094b139-9107-4665-b080-413a0975c11c', 'ಮರುವಿವಾಹವಾಗದಿರುವ ಬಗ್ಗೆ ದೃಡೀಕರಣ ಪತ್ರ', NULL, NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, 40.00, NULL, 'ವ್ಯಕ್ತಿಯು ಮರುಮದುವೆಯಾಗಿಲ್ಲ ಎಂಬುದಕ್ಕೆ ಈ ಪ್ರಮಾಣಪತ್ರ ಸಾಕ್ಷಿಯಾಗಿದೆ. ಸರ್ಕಾರಿ ಸೌಲಭ್ಯಗಳನ್ನು ಪಡೆಯಲು ಈ ಪ್ರಮಾಣಪತ್ರ ಅಗತ್ಯವಿದೆ.', NULL, NULL, NULL, true, 'Yes', '["ಸೇವೆಯ ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಸಾರ್ವಜನಿಕರು"]', '["ಅರ್ಜಿ ಸಲ್ಲಿಕೆ – ಅರ್ಜಿದಾರರು ನಾಲ್ಕು ವಿಧಾನಗಳಲ್ಲಿ ಒಂದರ ಮೂಲಕ ಅರ್ಜಿ ಸಲ್ಲಿಸುತ್ತಾರೆ: NK (ನಾಡಕಚೇರಿ) ಬಳಕೆದಾರರು, ಸೇವಾ ಸಿಂಧು ಬಳಕೆದಾರರು, ಆನ್‌ಲೈನ್ ಬಳಕೆದಾರರು, ಅಥವಾ GP (ಗ್ರಾಮ ಪಂಚಾಯತ್) ಬಳಕೆದಾರರು.", "ದಾಖಲೆಗಳ ಅಪ್‌ಲೋಡ್ – ಅರ್ಜಿದಾರರು ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಪೋಷಕ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಕು.", "ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ – VAO (ಗ್ರಾಮ ಲೆಕ್ಕಾಧಿಕಾರಿ) ಮತ್ತು RI (ಕಂದಾಯ ನಿರೀಕ್ಷಕರು) ಸಂಯೋಜನೆ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ ನಡೆಸುತ್ತಾರೆ. ಅರ್ಜಿಗಳ ಪ್ರಕ್ರಿಯೆಯೂ ಇದೇ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ನಡೆಯುತ್ತದೆ.", "ಡಿಜಿಟಲ್ ಸಹಿ / ಅನುಮೋದನೆ – ಅರ್ಜಿಯು TAH/DT/GOT ಲಾಗಿನ್ ಹಂತಕ್ಕೆ ಹೋಗುತ್ತದೆ, ಅಲ್ಲಿ ಅಧಿಕೃತ ಅಧಿಕಾರಿ ಅರ್ಜಿಯನ್ನು ಅನುಮೋದಿಸಬಹುದು, ಮಾರ್ಪಡಿಸಬಹುದು, ಅಥವಾ ತಿರಸ್ಕರಿಸಬಹುದು, ನಂತರ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡಲಾಗುತ್ತದೆ.", "ಪ್ರಮಾಣಪತ್ರ ವಿತರಣೆ – ಅನುಮೋದನೆ ಮತ್ತು ಸಹಿ ಆದ ನಂತರ, ನಾಗರಿಕರಿಗೆ SMS ಮೂಲಕ ಪ್ರಮಾಣಪತ್ರ ಡೌನ್‌ಲೋಡ್ ಮಾಡುವ ಲಿಂಕ್ ಕಳುಹಿಸಲಾಗುತ್ತದೆ, ಮತ್ತು PDF ಪ್ರತಿಯನ್ನು ಇಮೇಲ್ ಮೂಲಕವೂ ಕಳುಹಿಸಲಾಗುತ್ತದೆ — ಇದನ್ನು ಡೆಸ್ಕ್‌ಟಾಪ್, ಟ್ಯಾಬ್ಲೆಟ್, ಅಥವಾ ಮೊಬೈಲ್‌ನಲ್ಲಿ ಪ್ರವೇಶಿಸಬಹುದು."]', 1, '["ವಿಳಾಸದ ಪುರಾವೆ", "ಮರಣ ದಾಖಲೆ", "ಎಫಿಕ್", "ಗುರುತಿನ ಚೀಟಿ", "ಪಡಿತರ ಚೀಟಿ", "ಸ್ವಯಂ ಘೋಷಣೆ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('4b4f82fa-e857-4a32-adef-4cda8df2d54b', 'DEPARTMENT-OF-ANIMAL-2', 'e23b839a-6708-4a52-8bfd-d4e4c0a9691f', 'Postmortem Certificate for Animals', 'General', 0, 'Postmortem Certificate for Animals', '[]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '991c91bb-dda9-4d33-983e-ad37b41fc4bf', 'ಪ್ರಾಣಿಗಳಿಗೆ ಮರಣೋತ್ತರ ಪ್ರಮಾಣಪತ್ರ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಪ್ರಾಣಿಗಳಿಗೆ ಮರಣೋತ್ತರ ಪ್ರಮಾಣಪತ್ರ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, NULL);
