INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('f8435224-ce99-4646-8e36-5ff9cdea9801', 'REVENUE-DEPARTMENT-2', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Caste Certificate (Cat-A)', 'Certificate', 21, 'Caste and income certificate is issued to a person belonging to the Backwards Classes(CAT A) for the purpose of employment, education and other government benefits', '["Address Proof", "Epic", "ID Proof", "Old Caste Certificate", "Rationcard", "Relatives Certificate & Genealogical tree if none of the documents available", "School certificate (If Studied)", "self declaration"]', '["Citizens in need of this service"]', '[]', '["Application Submission – The applicant submits their request through one of four channels: NK (Nadakacheri) Users, Seva Sindhu Users, Online Users, or GP (Gram Panchayat) Users.", "Document Upload – The applicant uploads all required supporting documents for their application.", "Field Verification – The VAO (Village Accountant) and RI (Revenue Inspector) conduct field verification using the Samyojane Mobile Application. This mobile app is also where applications get processed.", "Digital Signing / Approval – The application moves to the TAH/DT/GOT login stage, where the authorized officer can Approve, Modify, or Reject the application, followed by digital signing.", "Certificate Delivery to Citizen – Once approved and signed, the citizen is notified via SMS with a link to download the certificate, and a PDF copy is also sent via email — accessible on desktop, tablet, or mobile."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '3094b139-9107-4665-b080-413a0975c11c', 'ಜಾತಿ ಪ್ರಮಾಣ ಪತ್ರ (ಪ್ರವರ್ಗ-ಎ)', NULL, NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, 40.00, NULL, 'ಉದ್ಯೋಗ, ಶಿಕ್ಷಣ ಮತ್ತು ಇತರ ಸರ್ಕಾರಿ ಸೌಲಭ್ಯಗಳನ್ನು ಪಡೆಯುವ ಉದ್ದೇಶಕ್ಕಾಗಿ ಹಿಂದುಳಿದ ವರ್ಗಗಳಿಗೆ (CAT A) ಸೇರಿದ ವ್ಯಕ್ತಿಗೆ ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರವನ್ನು ನೀಡಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, true, 'Yes', '["ಸೇವೆಯ ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಸಾರ್ವಜನಿಕರು"]', '["ಅರ್ಜಿ ಸಲ್ಲಿಕೆ – ಅರ್ಜಿದಾರರು ನಾಲ್ಕು ವಿಧಾನಗಳಲ್ಲಿ ಒಂದರ ಮೂಲಕ ಅರ್ಜಿ ಸಲ್ಲಿಸುತ್ತಾರೆ: NK (ನಾಡಕಚೇರಿ) ಬಳಕೆದಾರರು, ಸೇವಾ ಸಿಂಧು ಬಳಕೆದಾರರು, ಆನ್‌ಲೈನ್ ಬಳಕೆದಾರರು, ಅಥವಾ GP (ಗ್ರಾಮ ಪಂಚಾಯತ್) ಬಳಕೆದಾರರು.", "ದಾಖಲೆಗಳ ಅಪ್‌ಲೋಡ್ – ಅರ್ಜಿದಾರರು ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಪೋಷಕ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಕು.", "ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ – VAO (ಗ್ರಾಮ ಲೆಕ್ಕಾಧಿಕಾರಿ) ಮತ್ತು RI (ಕಂದಾಯ ನಿರೀಕ್ಷಕರು) ಸಂಯೋಜನೆ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ ನಡೆಸುತ್ತಾರೆ. ಅರ್ಜಿಗಳ ಪ್ರಕ್ರಿಯೆಯೂ ಇದೇ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ನಡೆಯುತ್ತದೆ.", "ಡಿಜಿಟಲ್ ಸಹಿ / ಅನುಮೋದನೆ – ಅರ್ಜಿಯು TAH/DT/GOT ಲಾಗಿನ್ ಹಂತಕ್ಕೆ ಹೋಗುತ್ತದೆ, ಅಲ್ಲಿ ಅಧಿಕೃತ ಅಧಿಕಾರಿ ಅರ್ಜಿಯನ್ನು ಅನುಮೋದಿಸಬಹುದು, ಮಾರ್ಪಡಿಸಬಹುದು, ಅಥವಾ ತಿರಸ್ಕರಿಸಬಹುದು, ನಂತರ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡಲಾಗುತ್ತದೆ.", "ಪ್ರಮಾಣಪತ್ರ ವಿತರಣೆ – ಅನುಮೋದನೆ ಮತ್ತು ಸಹಿ ಆದ ನಂತರ, ನಾಗರಿಕರಿಗೆ SMS ಮೂಲಕ ಪ್ರಮಾಣಪತ್ರ ಡೌನ್‌ಲೋಡ್ ಮಾಡುವ ಲಿಂಕ್ ಕಳುಹಿಸಲಾಗುತ್ತದೆ, ಮತ್ತು PDF ಪ್ರತಿಯನ್ನು ಇಮೇಲ್ ಮೂಲಕವೂ ಕಳುಹಿಸಲಾಗುತ್ತದೆ — ಇದನ್ನು ಡೆಸ್ಕ್‌ಟಾಪ್, ಟ್ಯಾಬ್ಲೆಟ್, ಅಥವಾ ಮೊಬೈಲ್‌ನಲ್ಲಿ ಪ್ರವೇಶಿಸಬಹುದು."]', 1, '["ವಿಳಾಸದ ಪುರಾವೆ", "ಎಫಿಕ್", "ಗುರುತಿನ ಚೀಟಿ", "ಹಳೆ ಜಾತಿ ಪತ್ರ", "ಪಡಿತರ ಚೀಟಿ", "ವಂಶವೃಕ್ಷ ಮತ್ತು ಸಂಬಂಧಿಕರ ದೃಢೀಕರಣ", "ಶಾಲಾ ದಾಖಲೆ (ವಿಧ್ಯಾಭ್ಯಾಸ ಹೊಂದಿದ್ದಲ್ಲಿ)", "ಸ್ವಯಂ ಘೋಷಣೆ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('65ff6570-13bb-401f-b87c-834174249991', 'REVENUE-DEPARTMENT-1', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Caste and Income Certficate', 'Certificate', 21, 'Caste and income certificate is issued to a person belonging to the Backwards Classes(CAT 2A, CAT 2B, CAT 3A, CAT 3 B) for the purpose of employment, education and other government benefits', '["Address Proof", "Affidavit (Self)", "Epic", "ID Proof", "Old Caste Certificate", "Others", "Rationcard", "Relatives Certificate & Genealogical tree if none of the documents available", "Salary certificate", "School certificate (If Studied)", "self declaration"]', '["Citizens in need of this service"]', '[]', '["Application Submission – The applicant submits their request through one of four channels: NK (Nadakacheri) Users, Seva Sindhu Users, Online Users, or GP (Gram Panchayat) Users.", "Document Upload – The applicant uploads all required supporting documents for their application.", "Field Verification – The VAO (Village Accountant) and RI (Revenue Inspector) conduct field verification using the Samyojane Mobile Application. This mobile app is also where applications get processed.", "Digital Signing / Approval – The application moves to the TAH/DT/GOT login stage, where the authorized officer can Approve, Modify, or Reject the application, followed by digital signing.", "Certificate Delivery to Citizen – Once approved and signed, the citizen is notified via SMS with a link to download the certificate, and a PDF copy is also sent via email — accessible on desktop, tablet, or mobile."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '3094b139-9107-4665-b080-413a0975c11c', 'ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣ ಪತ್ರ', NULL, NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, 40.00, NULL, 'ಉದ್ಯೋಗ, ಶಿಕ್ಷಣ ಮತ್ತು ಇತರ ಸರ್ಕಾರಿ ಸೌಲಭ್ಯಗಳನ್ನು ಪಡೆಯುವ ಉದ್ದೇಶಕ್ಕಾಗಿ ಹಿಂದುಳಿದ ವರ್ಗಗಳಿಗೆ (CAT 2A, CAT 2B, CAT 3A, CAT 3B) ಸೇರಿದ ವ್ಯಕ್ತಿಗೆ ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರವನ್ನು ನೀಡಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, true, 'Yes', '["ಸೇವೆಯ ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಸಾರ್ವಜನಿಕರು"]', '["ಅರ್ಜಿ ಸಲ್ಲಿಕೆ – ಅರ್ಜಿದಾರರು ನಾಲ್ಕು ವಿಧಾನಗಳಲ್ಲಿ ಒಂದರ ಮೂಲಕ ಅರ್ಜಿ ಸಲ್ಲಿಸುತ್ತಾರೆ: NK (ನಾಡಕಚೇರಿ) ಬಳಕೆದಾರರು, ಸೇವಾ ಸಿಂಧು ಬಳಕೆದಾರರು, ಆನ್‌ಲೈನ್ ಬಳಕೆದಾರರು, ಅಥವಾ GP (ಗ್ರಾಮ ಪಂಚಾಯತ್) ಬಳಕೆದಾರರು.", "ದಾಖಲೆಗಳ ಅಪ್‌ಲೋಡ್ – ಅರ್ಜಿದಾರರು ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಪೋಷಕ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಕು.", "ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ – VAO (ಗ್ರಾಮ ಲೆಕ್ಕಾಧಿಕಾರಿ) ಮತ್ತು RI (ಕಂದಾಯ ನಿರೀಕ್ಷಕರು) ಸಂಯೋಜನೆ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ ನಡೆಸುತ್ತಾರೆ. ಅರ್ಜಿಗಳ ಪ್ರಕ್ರಿಯೆಯೂ ಇದೇ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ನಡೆಯುತ್ತದೆ.", "ಡಿಜಿಟಲ್ ಸಹಿ / ಅನುಮೋದನೆ – ಅರ್ಜಿಯು TAH/DT/GOT ಲಾಗಿನ್ ಹಂತಕ್ಕೆ ಹೋಗುತ್ತದೆ, ಅಲ್ಲಿ ಅಧಿಕೃತ ಅಧಿಕಾರಿ ಅರ್ಜಿಯನ್ನು ಅನುಮೋದಿಸಬಹುದು, ಮಾರ್ಪಡಿಸಬಹುದು, ಅಥವಾ ತಿರಸ್ಕರಿಸಬಹುದು, ನಂತರ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡಲಾಗುತ್ತದೆ.", "ಪ್ರಮಾಣಪತ್ರ ವಿತರಣೆ – ಅನುಮೋದನೆ ಮತ್ತು ಸಹಿ ಆದ ನಂತರ, ನಾಗರಿಕರಿಗೆ SMS ಮೂಲಕ ಪ್ರಮಾಣಪತ್ರ ಡೌನ್‌ಲೋಡ್ ಮಾಡುವ ಲಿಂಕ್ ಕಳುಹಿಸಲಾಗುತ್ತದೆ, ಮತ್ತು PDF ಪ್ರತಿಯನ್ನು ಇಮೇಲ್ ಮೂಲಕವೂ ಕಳುಹಿಸಲಾಗುತ್ತದೆ — ಇದನ್ನು ಡೆಸ್ಕ್‌ಟಾಪ್, ಟ್ಯಾಬ್ಲೆಟ್, ಅಥವಾ ಮೊಬೈಲ್‌ನಲ್ಲಿ ಪ್ರವೇಶಿಸಬಹುದು."]', 1, '["ವಿಳಾಸದ ಪುರಾವೆ", "ಅಫೀದಾವಿತ್ (ಸ್ವಂತ)", "ಎಫಿಕ್", "ಗುರುತಿನ ಚೀಟಿ", "ಹಳೆ ಜಾತಿ ಪತ್ರ", "ಇತರೇ ದಾಖಲೆಗಳು", "ಪಡಿತರ ಚೀಟಿ", "ವಂಶವೃಕ್ಷ ಮತ್ತು ಸಂಬಂಧಿಕರ ದೃಢೀಕರಣ", "ವೇತನ ಪ್ರಮಾಣ ಪತ್ರ", "ಶಾಲಾ ದಾಖಲೆ (ವಿಧ್ಯಾಭ್ಯಾಸ ಹೊಂದಿದ್ದಲ್ಲಿ)", "ಸ್ವಯಂ ಘೋಷಣೆ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('b370642e-c646-49cc-b823-2980cee93bd1', 'THE-DEPARTMENT-OF-FO-16', '98c19fd4-7019-42a5-9af1-39cd53b9d099', 'Issuing of Verification Certificate', 'General', 30, 'Issuance of Verification Certificate – Various Categories of Traders - A service for the verification of weights and measures instruments used by various categories of traders for commercial purposes, in accordance with the provisions and standards prescribed under the Legal Metrology laws and rules. The instruments are examined and verified by the competent authority and, upon satisfying the prescribed requirements, are duly stamped and a Verification Certificate is issued.', '["For Manufacturer:", "Model Approval Certificate", "Manufacturer License copy", "List of particulars of Weights & Measures to be verified", "For Dealers:", "Dealer License Copy", "Weighing Instruments Purchase bill.", "For Users/Traders of Weights & Measures (Re-verification):", "Previous year’s Verification Certificate."]', '["As per Govt Notification No: AaNaSa 223 EeBaTha 19 (e-office) Dated: 10-12-2020 available in website"]', '[]', '["The applicant has to log on to https://emapan.karnataka.gov.in/", "Create an user ID & password", "Click on to apply for Verification certificate.", "Fill the required details.", "Upload the previous year Verification Certificate and scanned documents.", "Submit the application.", "Asst. Controller/ Inspector will verify the weighing Instruments. After confirming the correctness of the weighing instruments, verification fee will be collected as per Schedule IX of Karnataka Legal Metrology (Enforcement) (Amendment)Rules, 2021.", "Asst. Controller/ Inspector will generate the Money Receipt.", "After Generating the Verification Certificate, it will be sent to User’s Login.", "User can download & print Verification Certificate in User Login."]', NULL, NULL, 'https://emapan.karnataka.gov.in/Homepage_Sevaone.aspx??DepartmentID=14&ServiceID=3015&SevaOneUserID=<<sevaOneUserID>>&Token=<<token>>', true, '2026-10-30 16:55:56.458552+00', 'ef8e63a7-734d-4bc0-91ff-71ba8aa95423', 'ಸತ್ಯಾಪನಾ ಪ್ರಮಾಣ ಪತ್ರ ನೀಡುವಿಕೆ', 'Issuance of Verification Certificate – Various Categories of Traders', NULL, 'To the concerned shop/establishment', NULL, NULL, NULL, NULL, 'ಸತ್ಯಾಪನಾ ಪ್ರಮಾಣ ಪತ್ರ ನೀಡುವಿಕೆ -ವಿವಿಧ ಬಗೆಯ ವ್ಯಾಪಾರಿಗಳು ವಾಣಿಜ್ಯ ಉದ್ದೇಶಕ್ಕಾಗಿ ಬಳಸುವ ತೂಕ ಮತ್ತು ಅಳತೆ ಉಪಕರಣಗಳನ್ನು ಕಾನೂನು ಮಾಪನಶಾಸ್ತ್ರ ಇಲಾಖೆಯ ನಿಗಧಿತ ಮಾನದಂಡಗಳಂತೆ ಪರಿಶೀಲಿಸಿ, ಮುದ್ರಾಂಕನದ ನಂತರ ಸತ್ಯಾಪನಾ ಪ್ರಮಾಣಪತ್ರವನ್ನು ನೀಡುವ ಸೇವೆ', NULL, NULL, NULL, true, 'Yes', '[]', '["ಅರ್ಜಿದಾರರು ಇಲಾಖೆಯ ಜಾಲತಾಣ https://emapan.karnataka.gov.in/ ನ್ನು ತೆರೆಯಬೇಕು.", "ಜಾಲತಾಣದ ಮುಖಪುಟದಲ್ಲಿ ತಿಳಿಸಿರುವಂತೆ ಲಾಗಿನ್ ಯೂಸರ್ ಐ.ಡಿ. ಮತ್ತು ರಹಸ್ಯ ಪದವನ್ನು ರಚಿಸಿಕೊಳ್ಳಬೇಕು.", "ಲಾಗಿನ್ ಯೂಸರ್ ಐ.ಡಿ. ಮತ್ತು ರಹಸ್ಯ ಪದವನ್ನು ಉಪಯೋಗಿಸಿಕೊಂಡು ಅರ್ಜಿದಾರರು ಅವರ ಖಾತೆಗೆ ಲಾಗಿನ್ ಆಗಿ ಸತ್ಯಾಪನಾ ಪ್ರಮಾಣ ಪತ್ರ ಲಿಂಕ್ ಕ್ಲಿಕ್ ಮಾಡಬೇಕು.", "ಪರದೆಯಲ್ಲಿ ಮೂಡುವ ನಮೂನೆಯನ್ನು ಸೂಕ್ತವಾಗಿ ಭರ್ತಿ ಮಾಡಬೇಕು.", "ಕಳೆದ ವರ್ಷದ ಸತ್ಯಾಪನಾ ಪ್ರಮಾಣ ಪತ್ರದ ಪ್ರತಿ ಹಾಗೂ ಸಂಬಂಧಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಅಪ್"]', 1, '["ತಯಾರಕರು:", "ಮಾಡೆಲ್ ಅಪ್ರೂವಲ್ ಪ್ರಮಾಣ ಪತ್ರ.", "ತಯಾರಕರ ಲೈಸನ್ಸ್.", "ಪರಿಶೀಲನೆಗೆ ಒಳಪಡಿಸುವ ತೂಕ ಮತ್ತು ಅಳತೆ ಸಾಧನಗಳ ವಿವರಗಳ ಪಟ್ಟಿ.", "ಮಾರಾಟಗಾರರು:", "ಮಾರಾಟಗಾರರ ಲೈಸನ್ಸ್.", "ತೂಕ ಮತ್ತು ಯಂತ್ರಗಳನ್ನು ಖರೀದಿಸಿರುವ ಬಿಲ್ಲು.", "ವ್ಯಾಪಾರಸ್ಥರು(ಮರು ಸತ್ಯಾಪನೆ ಕಾರ್ಯಕ್ಕಾಗಿ);", "ಕಳೆದ ಸಾಲಿನ ಸತ್ಯಾಪನಾ ಪ್ರಮಾಣ ಪತ್ರ."]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('57bad24a-0b9e-4a56-84f3-04043801f709', 'THE-DEPARTMENT-OF-FO-13', '98c19fd4-7019-42a5-9af1-39cd53b9d099', 'Amendment Package/Commodities Manufacture', 'General', 21, 'Amendment Manufacture PC Licence – Application to modify or update the details of an existing packaged commodity manufacturer licence.', '["Documents to be submitted for Manufacturer - Amendment- Packing Registration Certificate", "Existing Original License Issued/Renewal.", "Court Order(for Firm Name Amendment)", "Details of Article(for Article Amendment)", "Details of Nominee/Director/Proprietary (for Nominee/Director/Proprietary Amendment)", "Applicant/Applicants Permanent Address Certificate/Aadhaar Card/Ration Card/Passport/Tax Paid Receipt/Electrical Bill(If anyone)", "Applicant/Firm’s GST Certificate.", "Applicant/Applicants/Firms Pan Card.", "Partnership deed (in case of Partnership firm)", "Trade License.", "Specimen Signature and Photos."]', '["As per Govt Notification No: AaNaSa 223 EeBaTha 19 (e-office) Dated: 10-12-2020 available in website"]', '[]', '["Applicant need to register in E-mapan > Applicant Need to Fill the application >", "Applicant need to upload the Required Documents>", "Applicant has to make Payment >", "Applicant has to make E-Sign>", "Applicant will Submit the application", "and Should take the approval from department"]', NULL, NULL, 'https://emapan.karnataka.gov.in/Homepage_Sevaone.aspx??DepartmentID=14&ServiceID=3012&SevaOneUserID=<<sevaOneUserID>>&Token=<<token>>', true, '2026-10-30 16:55:56.458552+00', 'ef8e63a7-734d-4bc0-91ff-71ba8aa95423', 'ಪೊಟ್ಟಣ ಸಾಮಗ್ರಿ ನೋಂದಣಿ ಪ್ರಮಾಣ ಪತ್ರ ತಿದ್ದುಪಡಿ - ತಯಾರಕರು.', 'Amendment of Manufacturer Packaged Commodity Registration Certificate – Modification or updating of an existing Manufacturer Packaged Commodity Registration Certificate.', NULL, 'State', NULL, NULL, NULL, NULL, 'ಪೊಟ್ಟಣ ಸಾಮಗ್ರಿ ನೋಂದಣಿ ಪ್ರಮಾಣ ಪತ್ರ ತಿದ್ದುಪಡಿ - ತಯಾರಕರು. - ಈಗಾಗಲೇ ಇರುವ ಪ್ಯಾಕೇಜ್ ಮಾಡಿದ ಸರಕುಗಳ ನೋಂದಣಿ ಪ್ರಮಾಣ ಪತ್ರದ ವಿವರಗಳನ್ನು ತಿದ್ದುಪಡಿ ಮಾಡಲು ಸಲ್ಲಿಸುವ ಅರ್ಜಿ.', NULL, NULL, NULL, true, 'Yes', '["ಸರ್ಕಾರದ ಅಧಿಸೂಚನೆ ಸಂಖ್ಯೆ: ಆನಾಸ 223 ಇಭತ 19 (ಇ-ಆಫೀಸ್) ದಿನಾಂಕ:10-12-2020 ರಲ್ಲಿ ತಿಳಿಸಿರುವ ಕಾರ್ಯವಿಧಾನದಂತೆ ವೆಬ್"]', '["ಅರ್ಜಿದಾರರು ಇ-ಮಾಪನ್ (E-Mapan) ಪೋರ್ಟಲ್"]', 1, '["ಪೊಟ್ಟಣ ಸಾಮಗ್ರಿ ನೋಂದಣಿ ಪ್ರಮಾಣ ಪತ್ರ ತಯಾರಕರು. ತಿದ್ದುಪಡಿ ಮಾಡಲು ಸಲ್ಲಿಸಬೇಕಾದ ದಾಖಲೆಗಳು:", "ಚಾಲ್ತಿಯಲ್ಲಿರುವ ಮೂಲ ಪರವಾನಗಿ (ಅಸ್ತಿತ್ವ/ನವೀಕರಣ)", "ಕೋರ್ಟ್ ಆದೇಶ (ಸಂಸ್ಥೆಯ ಹೆಸರು ತಿದ್ದುಪಡಿಗಾಗಿ)", "ಆರ್ಟಿಕಲ್ಸ್ನ ವಿವರ (ಆರ್ಟಿಕಲ್ಸ್ನ ತಿದ್ದುಪಡಿಗಾಗಿ)", "ನಾಮಿನಿ/ನಿರ್ದೇಶಕ/ಮಾಲೀಕರ ವಿವರ (ನಾಮಿನಿ/ನಿರ್ದೇಶಕ/ಮಾಲೀಕರ ತಿದ್ದುಪಡಿಗಾಗಿ)", "ಅಭ್ಯರ್ಥಿ/ಅಭ್ಯರ್ಥಿಗಳ ಖಾಯಂ ವಾಸಸ್ಥಳದ ಧೃಡೀಕರಣ ಪತ್ರ./ ಆಧಾರ್ ಕಾರ್ಡ್/ರೇಷನ್ ಕಾರ್ಡ್/ಪಾಸ್"]', NULL, NULL, '2299');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('63f53603-4e6c-4e2a-84a0-0150d5ae2671', 'SOCIAL-WELFARE-DEPAR-80', '81b60538-519f-4131-bd38-c390f2d882d6', 'Land Purchase scheme', 'Loan with Subsidy', 0, 'Under the Land-Ownership Scheme, land will be purchased from non-Scheduled Caste/Scheduled Tribe landowners. Landless women agricultural labourers belonging to the Scheduled Caste community will receive Rs. 20 lakh for 27 districts and Rs. 25 lakh for 4 districts (Bangalore City, Bangalore Rural, Chikkaballapur, and Ramanagara), with 50% subsidy and 50% loan. Khushki/Tari/Bagaitu land within a maximum distance of 10 km from the beneficiary''s residence will be provided. The loan must be repaid to the Corporation in 10 annual equal installments at an interest rate of 6% per annum.', '["Beneficiary Aadhaar Card As Residential Proof (Mandatory)", "Beneficiary Caste Certificate Issued by the competent authority (Mandatory)", "Beneficiary Income Certificate Issued by the competent authority (Mandatory)", "Letter of Landless Agricultural labourers (from Tahsildar) (Mandatory)", "Beneficiary Ration Card (Mandatory)", "Land Owners Cover letter for sale of land (To be notarized and submitted on Stamp paper.) (Mandatory)", "land owner Family Tree (To be verified and submitted by village accountants.) (Mandatory)", "Letter of No Objection (NOC) from Family Members (should be notarized and submitted.) (Mandatory)", "Latest pahani and mutation copy (Mandatory)", "Land Owners Last 13 years E.C. (Encumbrance Certificate should be submitted.) (Mandatory)", "Beneficiary Photo (Mandatory)"]', '["Applicants must belong to scheduled castes and its related community.", "The applicant must be a land less agriculture labour family.", "Self-declaration certificate must be submitted in case of caste certificate.", "Should be resident of Karnataka state.", "The applicant and no member of his family should not be in employment in any Govt./Semi Govt organization.", "The beneficiaries eligible to avail of facilities under the land ownership scheme must be landless women agricultural laborers.", "Additionally, the landowners selling the land should not belong to Scheduled Castes and Scheduled Tribes.", "The land to be purchased is a maximum of 10 km from the place where the beneficiary lives. m. should be within range."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '9f118461-87d3-46ad-b82e-1c26d0e43ec5', 'ಭೂ-ಒಡೆತನ ಯೋಜನೆ', 'Land Purchase scheme', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಭೂ -ಒಡೆತನ ಯೋಜನೆಯಡಿ ಪರಿಶಿಷ್ಟ ಜಾತಿ / ಪರಿಶಿಷ್ಟ ಪಂಗಡಕ್ಕೆ ಸೇರದ ಭೂ ಮಾಲೀಕರಿಂದ ಜಮೀನನ್ನು ಖರೀದಿಸಿ, ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸಮುದಾಯದ ಭೂ ರಹಿತ ಮಹಿಳಾ ಕೃಷಿ ಕಾರ್ಮಿಕರಿಗೆ 27 ಜಿಲ್ಲೆಗಳಿಗೆ ರೂ 20 ಲಕ್ಷ ಮತ್ತು 4 ಜಿಲ್ಲೆಗಳಿಗೆ (ಬೆಂಗಳೂರು ನಗರ, ಬೆಂಗಳೂರು ಗ್ರಾಮಾಂತರ, ಚಿಕ್ಕಬಳ್ಳಾಪುರ ಮತ್ತು ರಾಮನಗರ) ರೂ 25 ಲಕ್ಷಗಳಿಗೆ (ಸಹಾಯಧನ ಶೇ 50 ಮತ್ತು ಸಾಲ ಶೇ 50 ರಷ್ಟು) ಖುಷ್ಕಿ/ತರಿ/ಬಾಗಾಯ್ತು ಜಮೀನನ್ನು ಫಲಾನುಭವಿಯು ವಾಸಿಸುತ್ತಿರುವ ಸ್ಥಳದಿಂದ ಗರಿಷ್ಠ 10 ಕಿ. ಮೀ. ವ್ಯಾಪ್ತಿಯೊಳಗೆ ಖರೀದಿಸಿ, ಭೂರಹಿತ ಮಹಿಳಾ ಕೃಷಿ ಕಾರ್ಮಿಕರಿಗೆ ಒದಗಿಸಲಾಗುವುದು ಮತ್ತು ಸಾಲದ ಮೊತ್ತವನ್ನು 10 ವಾರ್ಷಿಕ ಸಮ ಕಂತುಗಳಲ್ಲಿ ವಾರ್ಷಿಕ ಶೇ 6 ರ ಬಡ್ಡಿ ದರದಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಮರುಪಾವತಿ ಮಾಡ ಬೇಕಾಗಿರುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '["ಅರ್ಜಿದಾರರು ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸಂಬಂಧಿತ ಜಾತಿಗಳಿಗೆ ಸೇರಿದವರಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಭೂ ರಹಿತ ಕೃಷಿ ಕಾರ್ಮಿಕ ಕುಟುಂಬದವರಾಗಿರಬೇಕು.", "ಜಾತಿ ಪ್ರಮಾಣ ಪತ್ರವನ್ನು ಸಲ್ಲಿಸಿದಲ್ಲಿ ಕಡ್ಡಾಯವಾಗಿ ಸ್ವಯಂ ಘೋಷಣೆ ಪ್ರಮಾಣ ಪತ್ರವನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು/ ಕುಟುಂಬದ ಅವಲಂಬಿತ ಯಾವುದೇ ಸದಸ್ಯರು ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ನೌಕರಿಯಲ್ಲಿರಬಾರದು.", "ಭೂಒಡೆತನ ಯೋಜನೆಯಡಿ ಸೌಲಭ್ಯ ಪಡೆಯಲು ಫಲಾಪೇಕ್ಷಿಯು ಭೂರಹಿತ ಮಹಿಳಾ ಕೃಷಿ ಕಾರ್ಮಿಕರಾಗಿರಬೇಕು.", "ಜಮೀನು ಮಾರಾಟ ಮಾಡುವ ಭೂಮಾಲೀಕರು ಪರಿಶಿಷ್ಟಜಾತಿ ಮತ್ತು ಪರಿಶಿಷ್ಟ ಪಂಗಡಕ್ಕೆ ಸೇರಿರಬಾರದು.", "ಖರೀದಿಸುವ ಜಮೀನು ಫಲಾನುಭವಿಯು ವಾಸಿಸುತ್ತಿರುವ ಸ್ಥಳದಿಂದ ಗರಿಷ್ಠ 10 ಕಿ. ಮೀ. ವ್ಯಾಪ್ತಿಯೊಳಗೆ ಇರಬೇಕು."]', '[]', 1, '["ಫಲಾನುಭವಿಯ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('e7cb853b-0b0e-4d93-880e-457120092f9d', 'THE-DEPARTMENT-OF-FO-15', '98c19fd4-7019-42a5-9af1-39cd53b9d099', 'Amendment Package/Commodities Importer', 'General', 21, 'Amendment Importer PC Licence – Application to modify or update the details of an existing packaged commodity Importer licence.', '["Documents to be submitted for Importer - Amendment- Packing Registration Certificate", "Existing Original License Issued/Renewal.", "Court Order(for Firm Name Amendment)", "Details of Article(for Article Amendment)", "Details of Nominee/Director/Proprietary (for Nominee/Director/Proprietary Amendment)", "Applicant/Applicants Permanent Address Certificate/Aadhaar Card/Ration Card/Passport/Tax Paid Receipt/Electrical Bill(If anyone)", "Applicant/Firm’s GST Certificate.", "Applicant/Applicants/Firms Pan Card.", "Partnership deed (in case of Partnership firm)", "Import/Export Code Certificate.", "Trade License.", "Specimen Signature and Photos."]', '["As per Govt Notification No: AaNaSa 223 EeBaTha 19 (e-office) Dated: 10-12-2020 available in website"]', '[]', '["Applicant need to register in E-mapan > Applicant Need to Fill the application >", "Applicant need to upload the Required Documents>", "Applicant has to make Payment >", "Applicant has to make E-Sign>", "Applicant will Submit the application", "and Should take the approval from department"]', NULL, NULL, 'https://emapan.karnataka.gov.in/Homepage_Sevaone.aspx??DepartmentID=14&ServiceID=3014&SevaOneUserID=<<sevaOneUserID>>&Token=<<token>>', true, '2026-10-30 16:55:56.458552+00', 'ef8e63a7-734d-4bc0-91ff-71ba8aa95423', 'ಪೊಟ್ಟಣ ಸಾಮಗ್ರಿ ನೋಂದಣಿ ಪ್ರಮಾಣ ಪತ್ರ ತಿದ್ದುಪಡಿ - ಆಮದುದಾರರು', 'Amendment of Importer Packaged Commodity Registration Certificate – Modification or updating of an existing Importer Packaged Commodity Registration Certificate.', NULL, 'State', NULL, NULL, NULL, NULL, 'ಪೊಟ್ಟಣ ಸಾಮಗ್ರಿ ನೋಂದಣಿ ಪ್ರಮಾಣ ಪತ್ರ ತಿದ್ದುಪಡಿ - ಆಮದುದಾರರು - ಈಗಾಗಲೇ ಇರುವ ಪ್ಯಾಕೇಜ್ ಮಾಡಿದ ಸರಕುಗಳ ಆಮದುದಾರರ ನೋಂದಣಿ ಪ್ರಮಾಣ ಪತ್ರದ ವಿವರಗಳನ್ನು ತಿದ್ದುಪಡಿ ಮಾಡಲು ಸಲ್ಲಿಸುವ ಅರ್ಜಿ.', NULL, NULL, NULL, true, 'Yes', '["ಸರ್ಕಾರದ ಅಧಿಸೂಚನೆ ಸಂಖ್ಯೆ: ಆನಾಸ 223 ಇಭತ 19 (ಇ-ಆಫೀಸ್) ದಿನಾಂಕ:10-12-2020 ರಲ್ಲಿ ತಿಳಿಸಿರುವ ಕಾರ್ಯವಿಧಾನದಂತೆ ವೆಬ್"]', '["ಅರ್ಜಿದಾರರು ಇ-ಮಾಪನ್ (E-Mapan) ಪೋರ್ಟಲ್"]', 1, '["ಪೊಟ್ಟಣ ಸಾಮಗ್ರಿ ನೋಂದಣಿ ಪ್ರಮಾಣ ಪತ್ರ ತಿದ್ದುಪಡಿ - ಆಮದುದಾರರು ತಿದ್ದುಪಡಿ ಮಾಡಲು ಸಲ್ಲಿಸಬೇಕಾದ ದಾಖಲೆಗಳು:", "ಚಾಲ್ತಿಯಲ್ಲಿರುವ ಮೂಲ ಪರವಾನಗಿ (ಅಸ್ತಿತ್ವ/ನವೀಕರಣ)", "ಕೋರ್ಟ್ ಆದೇಶ (ಸಂಸ್ಥೆಯ ಹೆಸರು ತಿದ್ದುಪಡಿಗಾಗಿ)", "ಆರ್ಟಿಕಲ್ಸ್ನ ವಿವರ (ಆರ್ಟಿಕಲ್ಸ್ನ ತಿದ್ದುಪಡಿಗಾಗಿ)", "ನಾಮಿನಿ/ನಿರ್ದೇಶಕ/ಮಾಲೀಕರ ವಿವರ (ನಾಮಿನಿ/ನಿರ್ದೇಶಕ/ಮಾಲೀಕರ ತಿದ್ದುಪಡಿಗಾಗಿ)", "ಅಭ್ಯರ್ಥಿ/ಅಭ್ಯರ್ಥಿಗಳ ಖಾಯಂ ವಾಸಸ್ಥಳದ ಧೃಡೀಕರಣ ಪತ್ರ./ ಆಧಾರ್ ಕಾರ್ಡ್/ರೇಷನ್ ಕಾರ್ಡ್/ಪಾಸ್"]', NULL, NULL, '2301');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('2694187b-b059-4810-8daa-df0ef8b7e004', 'THE-DEPARTMENT-OF-FO-9', '98c19fd4-7019-42a5-9af1-39cd53b9d099', 'Renewal Repairer Licence', 'General', 7, 'Renewal Of Repairer Licence – Application for renewing an existing repairer licence to continue providing repair and maintenance services legally.', '["This service has been enabled for automatic renewal. Therefore, applicants only need to submit a recent photograph and pay the prescribed fee. No other documents are required."]', '["As per Govt Notification No: AaNaSa 223 EeBaTha 19 (e-office) Dated: 10-12-2020 available in website"]', '[]', '["Applicant need to register in E-mapan > Applicant Need to Fill the application >", "Applicant need to upload the Required Documents>", "Applicant has to make Payment >", "Applicant has to make E-Sign>", "Applicant will Submit the application", "and Should take the approval from department"]', NULL, NULL, 'https://emapan.karnataka.gov.in/Homepage_Sevaone.aspx??DepartmentID=14&ServiceID=3008&SevaOneUserID=<<sevaOneUserID>>&Token=<<token>>', true, '2026-10-30 16:55:56.458552+00', 'ef8e63a7-734d-4bc0-91ff-71ba8aa95423', 'ತೂಕ, ಅಳತೆ, ತೂಕ ಮತ್ತು ಅಳತೆ ಸಾಧನಗಳ ದುರಸ್ಥಿದಾರರ ರಾಜ್ಯವ್ಯಾಪ್ತಿ ಪರವಾನಗಿಗಳ ನವೀಕರಣ.', 'Renewal Repairer Licence – Renewal of an existing repairer licence.', NULL, 'State', NULL, NULL, NULL, NULL, 'ದುರಸ್ಥಿದಾರರ ಪರವಾನಗಿ ನವೀಕರಣ - ದುರಸ್ತಿ ಮತ್ತು ನಿರ್ವಹಣಾ ಸೇವೆಗಳನ್ನು ಕಾನೂನುಬದ್ಧವಾಗಿ ಮುಂದುವರಿಸಲು ಈಗಿರುವ ತೂಕ, ಅಳತೆ, ತೂಕ ಮತ್ತು ಅಳತೆ ಸಾಧನಗಳ ದುರಸ್ಥಿದಾರರ ರಾಜ್ಯವ್ಯಾಪ್ತಿ ಪರವಾನಗಿಯನ್ನು ನವೀಕರಿಸುವ ಅರ್ಜಿ.', NULL, NULL, NULL, true, 'Yes', '["ಸರ್ಕಾರದ ಅಧಿಸೂಚನೆ ಸಂಖ್ಯೆ: ಆನಾಸ 223 ಇಭತ 19 (ಇ-ಆಫೀಸ್) ದಿನಾಂಕ:10-12-2020 ರಲ್ಲಿ ತಿಳಿಸಿರುವ ಕಾರ್ಯವಿಧಾನದಂತೆ ವೆಬ್"]', '["ಅರ್ಜಿದಾರರು ಇ-ಮಾಪನ್ (E-Mapan) ಪೋರ್ಟಲ್"]', 1, '["ಈ ಸೇವೆಯನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ನವೀಕರಿಸುವ ವ್ಯವಸ್ಥೆ ಮಾಡಲಾಗಿದೆ. ಆದ್ದರಿಂದ, ಇತ್ತೀಚಿನ ಭಾವಚಿತ್ರವನ್ನು ಸಲ್ಲಿಸಿ ನಿಗದಿತ ಶುಲ್ಕವನ್ನು ಪಾವತಿಸಿದರೆ ಸಾಕು. ಬೇರೆ ಯಾವುದೇ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸುವ ಅಗತ್ಯವಿಲ್ಲ."]', NULL, NULL, '2284');
