INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('72105a1e-c0bb-4df6-a5db-16d524fb2efe', 'DEPARTMENT-OF-LABOUR-6', '754e71d9-6fb5-4948-9726-3527641d0db8', 'Employee Registration by Employer- Apprenticeship Registration - Ashadeepa Scheme', 'General', 15, '', '[]', '[]', '[]', '["Through online web portal(currently by physical application)"]', NULL, NULL, 'https://ashadeepayojane.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', 'c8a02a33-93e1-41f0-a0f1-bf5d39dcfcfe', 'ಉದ್ಯೋಗದಾತರಿಂದ ಉದ್ಯೋಗಿ ನೋಂದಣಿ - ಅಪ್ರೆಂಟಿಸ್', NULL, NULL, NULL, NULL, NULL, 0.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '["ಅಧಿಕೃತ ಆನ್"]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('20e61ead-fa4f-483d-ad56-69a208818b69', 'DEPARTMENT-OF-LABOUR-5', '754e71d9-6fb5-4948-9726-3527641d0db8', 'Employee Registration by Employer- ESI and EPF Employee Registration - Ashadeepa Scheme', 'General', 15, '', '["Employee photo 2) Employee offer letter 3) Employee Adhar card 4) Employee Cast certificate 5) ESI E-Pehchan card , ESI and EPF ECR Challan copy or Pay slip or UTR transaction 6) For apprenticeship trainee NAPS certificate(Aggrement copy) required"]', '["Employee should be resident of Karnataka 2) Employee''s employement should be new and should not worked in any company previously i.e should be a fresher 3)Employee should be of SC/ST cast 4) Employee should not be joined before 2 years from the date of application"]', '[]', '["Through online web portal(currently by physical application)"]', NULL, NULL, 'https://ashadeepayojane.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', 'c8a02a33-93e1-41f0-a0f1-bf5d39dcfcfe', 'ಉದ್ಯೋಗದಾತರಿಂದ ಉದ್ಯೋಗಿ ನೋಂದಣಿ - ESI ಮತ್ತು EPF ಉದ್ಯೋಗಿ ನೋಂದಣಿ - ಆಶಾದೀಪ ಯೋಜನೆ', NULL, NULL, NULL, NULL, NULL, 0.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["ಉದ್ಯೋಗಿಯು ಕರ್ನಾಟಕದ ನಿವಾಸಿಯಾಗಿರಬೇಕು. 2) ಉದ್ಯೋಗಿಯು ಹೊಸಬರಾಗಿರಬೇಕು (fresher) ಮತ್ತು ಈ ಹಿಂದೆ ಯಾವುದೇ ಕಂಪನಿಯಲ್ಲಿ ಕೆಲಸ ಮಾಡಿರಬಾರದು. 3) ಉದ್ಯೋಗಿಯು ಎಸ್"]', '["ಅಧಿಕೃತ ಆನ್"]', 1, '["ಉದ್ಯೋಗಿಯ ಭಾವಚಿತ್ರ 2)ಉದ್ಯೋಗ ಪ್ರಸ್ತಾಪ ಪತ್ರ 3) ಉದ್ಯೋಗಿಯ ಆಧಾರ್ ಕಾರ್ಡ್ 4) ಉದ್ಯೋಗಿಯ ಜಾತಿ ಪ್ರಮಾಣ ಪತ್ರ 5) ಇ.ಎಸ್.ಐ ಇ-ಪೆಹಚಾನ್ ಕಾರ್ಡ್ 6) ಇ.ಎಸ್.ಐ ಮತ್ತು ಇ.ಪಿ.ಎಫ್ ಇ.ಸಿ.ಆರ್ ಚಲನ್ ಪ್ರತಿ 7) ವೇತನ ಚೀಟಿ 8) ಯು.ಟಿ.ಆರ್ ವಹಿವಾಟು 9) ಅಪ್ರೆಂಟೈಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('0c83e6d8-6b02-4256-ac1e-45040bc7d7ff', 'DEPARTMENT-OF-LABOUR-4', '754e71d9-6fb5-4948-9726-3527641d0db8', 'Employer Registration - Ashadeepa Scheme', 'General', 10, 'To encourage employment opportunities in the private sector factories and establishments, to the candidates belonging to Schedule Caste and Schedule Tribes, the Government of Karnataka has framed a scheme called “ASHADEEPA SCHEME”. The said scheme is being implemented through “Karnataka State Workers Welfare and Social Security (Ashadeepa Scheme) Society (R)”.', '["Establishment Registration Certificate 2) Bank Passbook (first page)/Canelled cheque 3) ESI Registration Number Document 4) EPF Registration Number Document"]', '["Only private establishments or industries in karnataka are eligible to apply"]', '[]', '["Through online web portal(currently by physical application)"]', NULL, NULL, 'https://ashadeepayojane.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', 'c8a02a33-93e1-41f0-a0f1-bf5d39dcfcfe', 'ಉದ್ಯೋಗದಾತರ ನೋಂದಣಿ - ಆಶಾದೀಪ ಯೋಜನೆ', NULL, NULL, NULL, NULL, NULL, 0.00, NULL, 'ಕರ್ನಾಟಕ ರಾಜ್ಯ ಸರ್ಕಾರವು, ಖಾಸಗಿ ವಲಯದ ಉದ್ಯೋಗಗಳಲ್ಲಿ ಹೆಚ್ಚಿನ ಪ್ರಮಾಣದಲ್ಲಿ ಪರಿಶಿಷ್ಟ ಜಾತಿ ಮತ್ತು ಪರಿಶಿಷ್ಟ ಪಂಗಡದ ಅಭ್ಯರ್ಥಿಗಳನ್ನು ನೇಮಕಾತಿ ಮಾಡಿಕೊಳ್ಳಲು ಮಾಲೀಕರನ್ನು/ಉದ್ಯೋಗದಾತರನ್ನು ಉತ್ತೇಜಿಸುವ ದೃಷ್ಟಿಯಿಂದ ಹಾಗೂ ಈ ಮೂಲಕ ಪರಿಶಿಷ್ಟ ಜಾತಿ ಮತ್ತು ಪರಿಶಿಷ್ಟ ಪಂಗಡದ ಅಭ್ಯರ್ಥಿಗಳು ಖಾಸಗಿ ವಲಯದಲ್ಲಿ ಉದ್ಯೋಗಾವಕಾಶ ಪಡೆಯಲು ಅನುಕೂಲವಾಗುವಂತೆ “ಆಶಾದೀಪ” ಎಂಬ ನೂತನ ಯೋಜನೆಯನ್ನು ರೂಪಿಸಿದೆ. ಈ ಯೋಜನೆಯನ್ನು ಕರ್ನಾಟಕ ರಾಜ್ಯ ಕಾರ್ಮಿಕರ ಕಲ್ಯಾಣ ಮತ್ತು ಸಾಮಾಜಿಕ ಭದ್ರತಾ (ಆಶಾದೀಪ ಯೋಜನೆ) ಸೊಸೈಟಿಯ ಮೂಲಕ ಜಾರಿಗೊಳಿಸಲಾಗುತ್ತಿದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕದಲ್ಲಿನ ಕೇವಲ ಖಾಸಗಿ ಸಂಸ್ಥೆಗಳು ಅಥವಾ ಕೈಗಾರಿಕೆಗಳು ಮಾತ್ರ ಅರ್ಜಿ ಸಲ್ಲಿಸಲು ಅರ್ಹರಾಗಿರುತ್ತಾರೆ."]', '["ಅಧಿಕೃತ ಆನ್"]', 1, '["ಕಂಪನಿ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರ 2)ಬ್ಯಾಂಕ್ ಪಾಸ್ಬುಕ್ 3) ಇಎಸ್ಐ ನೋಂದಣಿ ಸಂಖ್ಯೆ ದಾಖಲೆ 4) ಇಪಿಎಫ್ ನೋಂದಣಿ ಸಂಖ್ಯೆ ದಾಖಲೆ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('45c26cdb-c7ea-4615-8c62-bbfc857e4dc5', 'DEPARTMENT-OF-LABOUR-3', '754e71d9-6fb5-4948-9726-3527641d0db8', 'Registration of Motor Transport and Other Allied Workers under Karnataka State Motor Transport and Other Allied Workers Social Security and Welfare Board', 'General', 45, 'It is estimated that there are about 40 lakh private commercial transport and other allied workers in the unorganized category of workers. The Karnataka State Government has implemented the Karnataka State Motor Transport And Other Allied Workers Social Security and Welfare Act-2024, with the aim of providing social security and welfare facilities to them and framed rules accordingly and constituted the Karnataka State Motor Transport And Other Allied Workers Social Security and Welfare Board, through which social security schemes are being implemented for these workers.', '["Recent passport size photograph. 2) Age Proof. 3)Aadhaar Card. 4)Bank pass book 5) Driving License"]', '["This scheme is applicable only to the residents of Karnataka State.2) Age limit of applicant is 18 to 70 years. 3) Should not be an Income Tax payer. 4) Should not to be covered under ESI / EPF Scheme. 5)Scheme benefits are available both on and off duty. 6) Drivers must have a valid driving license issued by the Karnataka State Transport Department to drive a commercial transport vehicle."]', '[]', '["Through online web portal"]', NULL, NULL, 'https://ambedkarsahayahasta.karnataka.gov.in/Home/Index', true, '2026-10-30 16:55:56.458552+00', '112a135c-3258-4069-ac38-23616ab5a51a', 'ಕರ್ನಾಟಕ ರಾಜ್ಯ ಮೋಟಾರು ಸಾರಿಗೆ ಮತ್ತು ಇತರ ಸಂಬಂಧಿತ ಕಾರ್ಮಿಕರ ಸಾಮಾಜಿಕ ಭದ್ರತೆ ಮತ್ತು ಕ್ಷೇಮಾಭಿವೃದ್ದಿ ಮಂಡಳಿಯ ಅಡಿಯಲ್ಲಿ ಮೋಟಾರು ಸಾರಿಗೆ ಮತ್ತು ಇತರ ಸಂಬಂಧಿತ ಕಾರ್ಮಿಕರ ನೋಂದಣಿ', NULL, NULL, NULL, NULL, NULL, 50.00, NULL, 'ಅಸಂಘಟಿತ ವರ್ಗದ ಕಾರ್ಮಿಕರಲ್ಲಿ ಖಾಸಗಿ ವಾಣಿಜ್ಯ ಸಾರಿಗೆ ಹಾಗೂ ಇತರೆ ಸಂಬಂಧಿತ ಕಾರ್ಮಿಕರು ಬಹು ಸಂಖ್ಯೆಯಲ್ಲಿದ್ದು, ಅವರಿಗೆ ಸಾಮಾಜಿಕ ಭದ್ರತೆ ಹಾಗೂ ಕಲ್ಯಾಣ ಸೌಲಭ್ಯಗಳನ್ನು ಒದಗಿಸುವ ಉದ್ದೇಶದಿಂದ, ಕರ್ನಾಟಕ ರಾಜ್ಯ ಸರ್ಕಾರವು, “ಕರ್ನಾಟಕ ಮೋಟಾರು ಸಾರಿಗೆ ಮತ್ತು ಇತರೆ ಸಂಬಂಧಿತ ಕಾರ್ಮಿಕರ ಸಾಮಾಜಿಕ ಭದ್ರತಾ ಮತ್ತು ಕಲ್ಯಾಣ ಯೋಜನೆ”ಯನ್ನು ರೂಪಿಸಿದ್ದು, ಕರ್ನಾಟಕ ರಾಜ್ಯ ಮೋಟಾರು ಸಾರಿಗೆ ಹಾಗೂ ಇತರೆ ಸಂಬಂಧಿತ ಕಾರ್ಮಿಕರ ಸಾಮಾಜಿಕ ಭದ್ರತೆ ಮತ್ತು ಕ್ಷೇಮಾಭಿವೃದ್ಧಿ ಮಂಡಳಿಯ ಮೂಲಕ ಜಾರಿಗೊಳಿಸಲಾಗುತ್ತಿದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಈ ಯೋಜನೆಯು ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಗಳಿಗೆ ಮಾತ್ರ ಅನ್ವಯ. 2) ಅರ್ಜಿದಾರರ ವಯೋಮಿತಿ 18 ರಿಂದ 70 ವರ್ಷಗಳು. 3) ಆದಾಯ ತೆರಿಗೆ ಪಾವತಿದಾರರಾಗಿರಬಾರದು. 4) ಇ.ಎಸ್.ಐ ಮತ್ತು ಇ.ಪಿ.ಎಫ್ ಸೌಲಭ್ಯ ಹೊಂದಿರಬಾರದು.5)ಯೋಜನೆಯ ಸೌಲಭ್ಯಗಳು ಕರ್ತವ್ಯದಲ್ಲಿರುವಾಗ ಹಾಗೂ ಇಲ್ಲದಿರುವಾಗಲೂ ಸಹ ಲಭ್ಯವಾಗುತ್ತವೆ. 6)ಚಾಲಕರು, ಕರ್ನಾಟಕ ರಾಜ್ಯ ಸಾರಿಗೆ ಇಲಾಖೆಯಿಂದ ವಾಣಿಜ್ಯ ವಾಹನ ಚಲಾಯಿಸಲು ಊರ್ಜಿತ ಚಾಲನಾ ಪರವಾನಗಿಯನ್ನು ಹೊಂದಿರುವುದು ಕಡ್ಡಾಯ."]', '["ಅಧಿಕೃತ ಆನ್"]', 1, '["ಪಾಸ್ಪೋರ್ಟ್ ಅಳತೆಯ ಇತ್ತೀಚಿನ ಭಾವಚಿತ್ರ. 2) ವಯಸ್ಸಿನ ಪ್ರಮಾಣ ಪತ್ರ. 3) ಆಧಾರ್ ಕಾರ್ಡ್. 4) ಬ್ಯಾಂಕ್ ಪಾಸ್ ಪುಸ್ತಕ 5)ಚಾಲನಾ ಪರವಾನಗಿ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('bb03b1fd-1127-4f8e-a1e7-74bf4deea356', 'EDUCATION-DEPARTMENT-6', 'bd235dfc-9efa-4507-aaf0-f78a93e05e6a', 'Online Revaluation Software', 'Answer Script', 0, 'After receiving the photocopy of the answer script, students may apply for revaluation, if they wish to have their marks re-evaluated, using their Register Number.', '["Register Number"]', '["Students who has written exams in that particular academic year"]', '[]', '["Get Scanned Answer Script → Check Answers & Marks → Apply for Revaluation → Enter Register Number → Select Subject(s) → Pay Fee → Submit → Revaluation Result/Updated Marks."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', 'e61a6e68-d61f-4782-a4e6-388fca3e3652', 'ಆನ್', 'After receiving the photocopy of the answer script, students may apply for revaluation, if they wish to have their marks re-evaluated, using their Register Number.', NULL, 'Urban & Rural', NULL, NULL, 800.00, NULL, 'ಉತ್ತರ ಪತ್ರಿಕೆಯ ಛಾಯಾಪ್ರತಿಯನ್ನು ಪಡೆದ ನಂತರ, ವಿದ್ಯಾರ್ಥಿಗಳು ತಮ್ಮ ಅಂಕಗಳನ್ನು ಮರುಪರಿಶೀಲಿಸಲು ಬಯಸಿದಲ್ಲಿ, ತಮ್ಮ ನೋಂದಣಿ ಸಂಖ್ಯೆಯನ್ನು (Register Number) ಬಳಸಿ ಮರುಮೌಲ್ಯಮಾಪನಕ್ಕೆ (Revaluation) ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು.', NULL, NULL, NULL, true, 'YES', '["ಶೈಕ್ಷಣಿಕ ವರ್ಷದಲ್ಲಿ ಪರೀಕ್ಷೆ ಬರೆದ ವಿದ್ಯಾರ್ಥಿಗಳು"]', '["ಸ್ಕ್ಯಾನ್ ಮಾಡಿದ ಉತ್ತರ ಪತ್ರಿಕೆಯನ್ನು ಪಡೆಯಿರಿ → ಉತ್ತರಗಳು ಮತ್ತು ಅಂಕಗಳನ್ನು ಪರಿಶೀಲಿಸಿ → ಮರುಮೌಲ್ಯಮಾಪನಕ್ಕೆ ಅರ್ಜಿ ಸಲ್ಲಿಸಿ → ನೋಂದಣಿ ಸಂಖ್ಯೆಯನ್ನು ನಮೂದಿಸಿ → ವಿಷಯ(ಗಳನ್ನು) ಆಯ್ಕೆ ಮಾಡಿ → ಶುಲ್ಕ ಪಾವತಿಸಿ → ಸಲ್ಲಿಸಿ → ಮರುಮೌಲ್ಯಮಾಪನ ಫಲಿತಾಂಶ/ತಿದ್ದುಪಡಿ ಅಂಕಗಳನ್ನು ಪಡೆಯಿರಿ."]', 1, '["ನೋಂದಣಿ ಸಂಖ್ಯೆ"]', NULL, NULL, '3434');
