INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('70f888f9-e182-4574-a5aa-3a16e8b3d061', 'BACKWARD-CLASSES-WEL-42', '59d7c155-e129-436a-b747-c5cb6abba051', 'Application for Self Employment Direct Loan Scheme', 'self employment loan', 0, '', '["Pasport Size Photo", "Ration card", "Aadhar linked PassBook Front Page PhotoPasport Size Photo", "Ration card,adhaar card"]', '["The applicant must be between 18 to 55 years of age.", "The annual family income of the applicant must be within Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the MLA."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '70b2e99d-3915-447d-ab77-593d2675f1e3', 'ಸ್ವಯಂ
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('10cbb53a-0165-4636-a6a5-ec20ebd9f04a', 'BACKWARD-CLASSES-WEL-41', '59d7c155-e129-436a-b747-c5cb6abba051', 'Arivu Educational Loan Scheme(renewal)', 'Education loan', 0, '', '["Caste and income certificate,Aadhaar card,Ration card,Fees structure, PUC Marks Card,CET /NEET order copy,Study Certificate(12th or PUC),Aadhar linked PassBook Front Page Photo,Admission Letter"]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '70b2e99d-3915-447d-ab77-593d2675f1e3', 'ಅರಿವು ಶೈಕ್ಷಣಿಕ ಸಾಲ ಯೋಜನೆ (ನವೀಕರಣ)', 'In this scheme the selected beneficiaries in arivu fresh scheme have to apply for renewal for next academic year''s installment', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ, ಆಧಾರ್ ಕಾರ್ಡ್, ಪಡಿತರ ಚೀಟಿ, ಶುಲ್ಕದ ವಿವರ, ಪಿಯುಸಿ (PUC) ಅಂಕಪಟ್ಟಿ, ಸಿಇಟಿ (CET)/ನೀಟ್ (NEET) ಆದೇಶದ ಪ್ರತಿ, ವ್ಯಾಸಂಗ ಪ್ರಮಾಣಪತ್ರ (12ನೇ ತರಗತಿ ಅಥವಾ ಪಿಯುಸಿ), ಆಧಾರ್ ಜೋಡಣೆಯಾಗಿರುವ ಬ್ಯಾಂಕ್ ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('c85ca39b-09d8-4a10-8332-ca8ba0c68644', 'BACKWARD-CLASSES-WEL-40', '59d7c155-e129-436a-b747-c5cb6abba051', 'Arivu Educational Loan Scheme (Fresh)', 'Education loan', 0, '', '["Caste and income certificate,Aadhaar card,Ration card,Fees structure, PUC Marks Card,CET /NEET order copy,Study Certificate(12th or PUC),Aadhar linked PassBook Front Page Photo,Admission Letter"]', '["The applicant must be between 18 and 35 years of age.", "The annual family income of the applicant must be within Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas."]', '[]', '["Beneficiaries were selected through a selection committee chaired by the Chief Executive Officer of the Zilla Panchayat."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '70b2e99d-3915-447d-ab77-593d2675f1e3', 'ಅರಿವು ಶೈ ಕ್ಷಣಿಕ ಸಾಲ ಯೋಜನೆ (ಹೊಸ)', 'Under this scheme, an educational loan of up to ₹1,00,000—at an annual interest rate of 2%—will be sanctioned to students from the Uppara community who have secured admission to professional higher education courses (such as engineering, medicine, and dentistry) through CET or NEET. The annual income of the candidate and their family must be within the limit of ₹3.50 lakh.', NULL, NULL, NULL, NULL, NULL, 30.00, NULL, NULL, NULL, NULL, false, 'No', '["ಅರ್ಜಿದಾರರವಯಸ್ಸು18 ರಿಂದ 35 ವರ್ಷದ ಒಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬ ವಾರ್ಷಿಕವರಮಾನ ಗ್ರಾಮಾಂತರ ಪ್ರದೇಶದವರಿಗೆರೂ.98,000/- ಹಾಗೂ ಪಟ್ಟಣಪ್ರದೇಶದವರಿಗೆರೂ.1,20,000/- ಒಳಗಿರಬೇಕು."]', '["ಮಾನ್ಯ ಮುಖ್ಯ ಕಾರ್ಯ ನಿರ್ವಹಣಾಧಿಕಾರಿಗಳು, ಜಿಲ್ಲಾ ಪಂಚಾಯತ್ ರವರ ಅಧ್ಯಕ್ಷತೆಯ ಆಯ್ಕೆ ಸಮಿತಿಯಮೂಲಕ ಫಲಾನುಭವಿಗಳನ್ನುಆಯ್ಕೆ ಮಾಡಲಾಗುವುದು."]', 1, '["ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ, ಆಧಾರ್ ಕಾರ್ಡ್, ಪಡಿತರ ಚೀಟಿ, ಶುಲ್ಕದ ವಿವರ, ಪಿಯುಸಿ (PUC) ಅಂಕಪಟ್ಟಿ, ಸಿಇಟಿ (CET)/ನೀಟ್ (NEET) ಆದೇಶದ ಪ್ರತಿ, ವ್ಯಾಸಂಗ ಪ್ರಮಾಣಪತ್ರ (12ನೇ ತರಗತಿ ಅಥವಾ ಪಿಯುಸಿ), ಆಧಾರ್ ಜೋಡಣೆಯಾಗಿರುವ ಬ್ಯಾಂಕ್ ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('1ab5095e-d25a-4648-8bc8-2453aa43648f', 'SOCIAL-WELFARE-DEPAR-86', '81b60538-519f-4131-bd38-c390f2d882d6', 'Dr. Babu Jagjeevan Ram Two Wheeler Cargo Transport Scheme', 'Loan with Subsidy', 0, 'In 2022-23, a scheme will be implemented to promote self-employment and increase self-confidence among Scheduled Castes and Scheduled Tribes youth. This scheme is designed to facilitate e-commerce businesses and create employment in other services. Under this scheme, beneficiaries who purchase electric or other two-wheeler/three-wheeler goods transport vehicles will receive a subsidy of Rs. 50,000 and a loan of Rs. 20,000.', '["Applicant Aadhar Card (Mandatory)", "Applicant Photo (Mandatory)", "Applicant Voter ID (Mandatory)", "Applicant Ration Card (Mandatory)", "Caste & Income Certificate issued by competent authority (Mandatory)", "Must Possess Relevant Vehicle Driving License (Mandatory)", "Must Possess Relevant Vehicle Quotation (Mandatory)", "In E-Commerce, submit proof of employment or a self-affidavit for selling goods (Mandatory)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)", "The applicant must declare they have not received prior assistance from the Corporation (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Applicant Age should be between 21 to 60 years.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '9f118461-87d3-46ad-b82e-1c26d0e43ec5', 'ಡಾ. ಬಾಬು ಜಗಜೀವನ ರಾಂ ದ್ವಿಚಕ್ರ ವಾಹನ ಸರಕು ಸಾಗಾಣಿಕೆ ಯೋಜನೆ', 'Two Wheeler Cargo Transport Scheme', NULL, NULL, 'Online', NULL, NULL, NULL, '2022-23 ನೇ ಸಾಲಿನಲ್ಲಿ ಪರಿಶಿಷ್ಟ ಜಾತಿ ಮತ್ತು ವರಿಶಿಷ್ಟ ಪಂಗಡದ ಯುವಕರಲ್ಲಿ ಸ್ವಯಂ ಉದ್ಯೋಗವನ್ನು ಉತ್ತೇಜಿಸಲು ಮತ್ತು ಆತ್ಮವಿಶ್ವಾಸವನ್ನು ಹೆಚ್ಚಿಸಲು , ಇ-ಕಾಮರ್ಸ್ ವ್ಯವಹಾರಗಳನ್ನು ಸುಲಭಗೊಳಿಸಲು ಮತ್ತು ಇತರ ಸೇವೆಗಳಲ್ಲಿ ಉದ್ಯೋಗವನ್ನು ಸೃಷ್ಟಿಸಲು ಈ ಯೋಜನೆಯನ್ನು ವಿನ್ಯಾಸಗೊಳಿಸಲಾಗಿದೆ. ಈ ಯೋಜನೆಯಡಿಯಲ್ಲಿ, ವಿದ್ಯುತ್ ಅಥವಾ ಇತರೆ ಎರಡು/ಮೂರು ಚಕ್ರದ ಸರಕು ಸಾಗಣೆ ವಾಹನಗಳನ್ನು ಖರೀದಿಸುವ ಫಲಾನುಭವಿಗಳಿಗೆ ರೂ. 50,000 ಸಹಾಯಧನ ಹಾಗೂ ರೂ. 20,000 ಸಾಲವನ್ನು ನೀಡಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 60 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('181eb779-c4c7-4064-a252-284c14be04d7', 'HORTICULTURE-AND-SER-12', '7fc7181a-5bee-4a83-b61b-bd3c78da95b2', 'Programmes implemented by Price Stabilization Fund-Bonus for Pure Bivoltine Cocoons', 'General', 0, 'Programmes implemented by Price Stabilization Fund-Bonus for Pure Bivoltine Cocoons', '["Application", "Rearer Pass bookAadhaar Card", "Aadhaar Card", "FRUITS ID", "Aadhaar Linked Bank Account details ( First Page of the Bank Passbook )", "Dfl''s Purchase bill", "Bidding slip for Pure Bivoltine seed Cocoons transacted in Govt.Cocoon Markets"]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '2486ba28-e160-4a76-8df1-ce8e643a84c9', 'ಬೆಲೆ ಸ್ಥಿರೀಕರಣ ನಿಧಿ ಅನುದಾನದಿಂದ ಅನುಷ್ಟಾನಗೊಳಿಸುವ ಕಾರ್ಯಕ್ರಮಗಳು- ಶುದ್ದ ದ್ವಿತಳಿ ರೇಷ್ಮೆ ಗೂಡಿಗೆ ಬೋನಸ್', 'Programmes implemented by Price Stabilization Fund-Bonus for Pure Bivoltine Cocoons', NULL, NULL, NULL, NULL, NULL, NULL, 'ಬೆಲೆ ಸ್ಥಿರೀಕರಣ ನಿಧಿ ಅನುದಾನದಿಂದ ಅನುಷ್ಟಾನಗೊಳಿಸುವ ಕಾರ್ಯಕ್ರಮಗಳು- ಶುದ್ದ ದ್ವಿತಳಿ ರೇಷ್ಮೆ ಗೂಡಿಗೆ ಬೋನಸ್', NULL, NULL, NULL, false, 'No', '[]', '[]', 1, '["ಅರ್ಜಿ", "ರೇಷ್ಮೆ ಬೆಳೆಗಾರರ ಪಾಸು ಪುಸ್ತಕ", "ಆಧಾರ್"]', NULL, NULL, '3415');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('60296666-f267-4d48-a399-3027b380de32', 'SOCIAL-WELFARE-DEPAR-85', '81b60538-519f-4131-bd38-c390f2d882d6', 'Swavalambi Sarathi Scheme', 'Subsidy', 0, 'Under Swalambi Sarathi Yojana, the scheme will be implemented in collaboration with banks by sanctioning 75% subsidy or maximum Rs.4.00 lakhs for goods transport/taxi (yellow board) vehicles.', '["Applicant Aadhar Cards (Mandatory)", "Applicant Ration Card (Mandatory)", "Applicant Voter ID (Mandatory)", "Caste & Income Certificate issued by competent authority (Mandatory)", "Vehicle Quotation (Mandatory)", "The applicant must declare they have not received prior assistance from the Corporation (Mandatory)", "Applicant Photo (Mandatory)", "Bank Pass Book (with Cover Page) (Mandatory)", "Vehicle Driving License(DL) (Mandatory)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 56 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '9f118461-87d3-46ad-b82e-1c26d0e43ec5', 'ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ ಯೋಜನೆ', 'Swavalambi Sarathi /ISB 3.5', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ ಯೋಜನೆಯಡಿ ಸರಕು ಸಾಗಾಣಿಕೆ/ಟ್ಯಾಕ್ಸಿ (ಹಳದಿ ಬೋರ್ಡ್) ವಾಹನಗಳಿಗೆ ಘಟಕ ವೆಚ್ಚದ ಶೇ.75ರಷ್ಟು ಅಥವಾ ಗರಿಷ್ಟ ರೂ.4.00 ಲಕ್ಷಗಳವರೆಗೆ ಸಹಾಯಧನವನ್ನು ಮಂಜೂರು ಮಾಡಿ ಬ್ಯಾಂಕ್', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 56 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('51dcb441-a16f-44cd-a58f-6b4af1f5e0ed', 'SOCIAL-WELFARE-DEPAR-84', '81b60538-519f-4131-bd38-c390f2d882d6', 'Micro Credit Prerana Scheme 5 Lakh', 'Loan with Subsidy', 0, 'Loans and grants will be extended to support various economic activities undertaken by Self-Help Groups of Scheduled Caste women. Each female member will receive Rs. 25,000, comprising a subsidy of Rs. 15,000 and a loan of Rs. 10,000. Self-help groups with a minimum of 10 women members and a unit cost of Rs. 2.50 lakhs will be eligible for loan assistance as per regulations. The loan must be repaid to the Corporation in 36 equal installments with a 4% interest rate', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '9f118461-87d3-46ad-b82e-1c26d0e43ec5', 'ಪ್ರೇರಣಾ (ಮೈಕ್ರೋ ಕ್ರೆಡಿಟ್) ಯೋಜನೆ 5 ಲಕ್ಷ', 'Prerana (Micro Credit) 5 Lakh', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯದ ಮಹಿಳಾ ಸ್ವಸಹಾಯ ಸಂಘಗಳ ವಿವಿಧ ಉದ್ದೇಶದ ಆರ್ಥಿಕ ಚಟುವಟಿಕೆಗಳಿಗೆ ಸಾಲ ಮತ್ತು ಸಹಾಯಧನ ನೀಡಲಾಗುವುದು. ಪ್ರತಿ ಮಹಿಳಾ ಸದಸ್ಯರಿಗೆ ರೂ 25000. ಇದರಲ್ಲಿ ಸಹಾಯಧನ ರೂ15000 ಹಾಗೂ ಸಾಲ ರೂ10000 ಗಳಾಗಿರುತ್ತದೆ. ಕನಿಷ್ಠ 10 ಜನ ಮಹಿಳಾ ಸದಸ್ಯರು ಇರುವ ಸ್ವ-ಸಹಾಯ ಗುಂಪಿಗೆ ಘಟಕ ವೆಚ್ಛ ರೂ 2.50 ಲಕ್ಷಗಳಂತೆ ನಿಯಮಾನುಸಾರ ಅರ್ಹರಿರುವ ಗುಂಪಿಗೆ ಸಾಲ ಸೌಲಭ್ಯ ಒದಗಿಸಲಾಗುವುದು. ಸದರಿ ಸಾಲದ ಹಣವನ್ನು 36 ಸಮ ಕಂತುಗಳಲ್ಲಿ ಶೇ 4 ರ ಬಡ್ಡಿ ದರದಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಮರುಪಾವತಿ ಮಾಡ ಬೇಕಾಗಿರುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('232cfd73-8683-453b-8fc3-e3e1e16cd75c', 'SOCIAL-WELFARE-DEPAR-83', '81b60538-519f-4131-bd38-c390f2d882d6', 'Micro Credit Prerana Scheme', 'Loan with Subsidy', 0, 'Loans and grants will be extended to support various economic activities undertaken by Self-Help Groups of Scheduled Caste women. Each female member will receive Rs. 25,000, comprising a subsidy of Rs. 15,000 and a loan of Rs. 10,000. Self-help groups with a minimum of 10 women members and a unit cost of Rs. 2.50 lakhs will be eligible for loan assistance as per regulations. The loan must be repaid to the Corporation in 36 equal installments with a 4% interest rate', '["Applicant''s Aadhar Cards (Mandatory)", "Applicant''s Ration Card (Mandatory)", "Applicant''s Voter ID (Mandatory)", "Caste & Income Certificate issued by competent authority (Mandatory)", "The applicant must declare they have not received prior assistance from the Corporation (Mandatory)", "Applicant''s Photo (Mandatory)", "Bank Pass Book (with Cover Page) (Mandatory)", "Should Have Valid Association Registration Copy (Mandatory)", "Copy of at least 3 months'' worth of recent association meeting minutes (Mandatory)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 60 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability.", "Registered Copy of Self Help Group.", "Out of the 60% Scheduled Caste members of the association, 40% of the members should belong to the sub-castes belonging to the corporation.", "Members of the SHG should have ration card."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '9f118461-87d3-46ad-b82e-1c26d0e43ec5', 'ಪ್ರೇರಣಾ (ಮೈಕ್ರೋ ಕ್ರೆಡಿಟ್) ಯೋಜನೆ', 'Prerana (Micro Credit)', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯದ ಮಹಿಳಾ ಸ್ವಸಹಾಯ ಸಂಘಗಳ ವಿವಿಧ ಉದ್ದೇಶದ ಆರ್ಥಿಕ ಚಟುವಟಿಕೆಗಳಿಗೆ ಸಾಲ ಮತ್ತು ಸಹಾಯಧನ ನೀಡಲಾಗುವುದು. ಪ್ರತಿ ಮಹಿಳಾ ಸದಸ್ಯರಿಗೆ ರೂ.25000. ಇದರಲ್ಲಿ ಸಹಾಯಧನ ರೂ.15000 ಹಾಗೂ ಸಾಲ ರೂ.10000 ಗಳಾಗಿರುತ್ತದೆ. ಕನಿಷ್ಠ 10 ಜನ ಮಹಿಳಾ ಸದಸ್ಯರು ಇರುವ ಸ್ವ-ಸಹಾಯ ಗುಂಪಿಗೆ ಘಟಕ ವೆಚ್ಛ ರೂ. 2.50 ಲಕ್ಷಗಳಂತೆ ನಿಯಮಾನುಸಾರ ಅರ್ಹರಿರುವ ಗುಂಪಿಗೆ ಸಾಲ ಸೌಲಭ್ಯ ಒದಗಿಸಲಾಗುವುದು. ಸದರಿ ಸಾಲದ ಹಣವನ್ನು 36 ಸಮ ಕಂತುಗಳಲ್ಲಿ ಶೇ 4 ರ ಬಡ್ಡಿ ದರದಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಮರುಪಾವತಿ ಮಾಡಬೇಕಾಗಿರುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 60 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು.", "ಚಾಲ್ತಿಯಲ್ಲಿರುವ ಸಂಘದ ನೊಂದಣಿ ಪತ್ರ.", "ಸಂಘದ ಶೇ 60 ರ ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸದಸ್ಯರುಗಳ ಪೈಕಿ ಶೇ 40 ರಷ್ಟು ಸದಸ್ಯರು ನಿಗಮಕ್ಕೆ ಸೇರಿದ ಉಪ ಜಾತಿಯವರಾಗಿರಬೇಕು.", "ಸಂಘದ ಸದಸ್ಯರು ಪಡಿತರ ಚೀಟಿಯನ್ನು ಹೊಂದಿರಬೇಕು."]', '[]', 1, '["ಎಲ್ಲಾ ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('bfd2bc5d-31c3-456d-aec9-0cc56877d7a7', 'SOCIAL-WELFARE-DEPAR-82', '81b60538-519f-4131-bd38-c390f2d882d6', 'Self Employment Direct Loan Scheme', 'Loan with Subsidy', 0, 'Scheduled caste individuals can engage in small-scale economic activities such as selling fruits, vegetables, fish, and rearing livestock like cows, sheep, pigs, or rabbits. The unit cost for these endeavors is Rs.1.00 lakh, with financial support comprising a Rs.50,000 subsidy and a Rs.50,000 loan. Beneficiaries are required to repay the loan to the corporation in 36 equal installments, with an interest rate of 4%.', '["Applicant Aadhar Card (Optional)", "Ration card (Optional)", "Aadhar linked PassBook Front Page Photo (Optional)", "Caste & Income Certificate issued by competent authority (Optional)", "The applicant must declare they have not received prior assistance from the Corporation (Optional)", "Passport size Photo (Optional)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)", "Project Report / Quotation (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 60 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '9f118461-87d3-46ad-b82e-1c26d0e43ec5', 'ಸ್ವಯಂ ಉದ್ಯೋಗ (ನೇರಸಾಲ) ಯೋಜನೆ', 'Self Employment Scheme', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಪರಿಶಿಷ್ಟ ಜಾತಿ ನಿರುದ್ಯೋಗಿಗಳಿಗೆ ಹಣ್ಣು,, ತರಕಾರಿ, ಮೀನು, ಮಾಂಸ ಮಾರಾಟ, ಹಸು/ಕುರಿ/ಹಂದಿ/ಮೊಲ ಸಾಕಾಣಿಕೆ ಇತ್ಯಾದಿ ಕಿರು ಆರ್ಥಿಕ ಚಟುವಟಿಕೆಗಳಿಗೆ ಘಟಕ ವೆಚ್ಚ ರೂ.1.00ಲಕ್ಷಗಳಾಗಿದ್ದು, ಈ ಪೈಕಿ ರೂ.50,000/- ಸಹಾಯಧನ ಹಾಗೂ ರೂ.50,000/- ಸಾಲದ ರೂಪದಲ್ಲಿ ಆರ್ಥಿಕ ನೆರವನ್ನು ಕಲ್ಪಿಸಲಾಗುತ್ತಿದೆ. ಸಾಲದ ಮೊತ್ತವನ್ನು 36 ಸಮಾನ ಕಂತುಗಳಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಶೇ.4ರ ಬಡ್ಡಿದರದೊಂದಿಗೆ ಮರುಪಾವತಿಸಬೇಕಾಗಿರುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 60 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('7511f9e5-958a-47c0-824e-5732dbbcce3e', 'SOCIAL-WELFARE-DEPAR-78', '81b60538-519f-4131-bd38-c390f2d882d6', 'Industrial Service Business - ISB (in association with Bank) Maximum Rs. 2 lakh subsidy', 'Subsidy', 0, 'Industrial Service Business (in collaboration with the Bank) development scheme, assistance from the Corporation to start self-employment units for unemployed youths and women of the Scheduled Caste community in small scale industry, service sector and business sectors and the rest is loan from the bank. Subsidy of 70% of the unit cost or a maximum of Rs 2 lakh', '["Applicant''s Aadhar Cards (Optional)", "Ration Card (Mandatory)", "Aadhar linked PassBook Front Page Photo (Mandatory)", "Caste & Income Certificate issued by competent authority (Optional)", "Project Report / Quotation (Optional)", "The applicant must declare they have not received prior assistance from the Corporation (Optional)", "Applicant Photo (Mandatory)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 56 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '9f118461-87d3-46ad-b82e-1c26d0e43ec5', 'ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್', 'Industrial Service Business 2.0', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 56 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('cce6bb05-b9cc-4e2b-b5ef-d2f29cee792f', 'SOCIAL-WELFARE-DEPAR-77', '81b60538-519f-4131-bd38-c390f2d882d6', 'Industrial Service Business - ISB (in association with Bank) Maximum Rs. 1 lakh subsidy', 'Subsidy', 0, 'Industrial Service Busines (in collaboration with the Bank) development scheme, assistance from the Corporation to start self-employment units for unemployed youths and women of the Scheduled Caste community in small scale industry, service sector and business sectors and the rest is loan from the bank. Subsidy of 20% of the unit cost or a maximum of Rs 1 lakh', '["Applicant Aadhar Cards (Mandatory)", "Applicant Ration Card (Mandatory)", "Applicant Voter ID (Mandatory)", "Caste & Income Certificate issued by competent authority (Mandatory)", "Project Report / Quotation (Mandatory)", "The applicant must declare they have not received prior assistance from the Corporation (Mandatory)", "Applicant Aadhar Card (Mandatory)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 56 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '9f118461-87d3-46ad-b82e-1c26d0e43ec5', 'ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್', 'Industrial Service Business 1.0', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 56 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('16120289-932a-4739-b36a-473eab84f56e', 'SOCIAL-WELFARE-DEPAR-76', '81b60538-519f-4131-bd38-c390f2d882d6', 'Ganga Kalyana', 'Loan with Subsidy', 0, 'Under this scheme, irrigation facilities are provided to small and very small scheduled caste farmers with 1½ to 5.00 acres of land by drilling boreholes, installing pump sets, and electrifying them. In certain districts such as Kolar, Chikkaballapur, Bangalore (Rural), Bangalore (City), Tumkur, and Ramnagar, the unit cost has been increased to Rs.4.75 lakh due to declining groundwater levels. Of this amount, Rs.4.25 lakh will be subsidized, and the remaining Rs.50,000/- will be provided as a term loan.In other districts, the unit cost is fixed at Rs.3.75 lakh, with Rs.3.25 lakh provided as a subsidy and Rs.50,000/- lakh as a term loan. Additionally, out of the unit cost, Rs.75,000 per borehole will be allocated to the respective Escom for electrification, within the subsidy limit of the unit cost.', '["Applicant Aadhar Cards (Optional)", "Ration Card (Mandatory)", "Aadhar linked PassBook Front Page Photo (Mandatory)", "Caste & Income Certificate issued by competent authority (Optional)", "The applicant must declare they have not received prior assistance from the Corporation (Optional)", "Passport size photo of the applicant (Mandatory)", "Small and Marginal Farmer Certificate (Mandatory)", "RTC (Mandatory)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicants must be at least 21 years old and there is no upper age limit.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability.", "The applicants must be small and medium marginal farmers and should not have access to irrigation facilities."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '9f118461-87d3-46ad-b82e-1c26d0e43ec5', 'ಗಂಗಾ ಕಲ್ಯಾಣ ಯೋಜನೆ', 'Ganga Kalyana', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಈ ಯೋಜನೆಯಡಿ 1½ ಎಕರೆಯಿಂದ 5.00 ಎಕರೆ ಜಮೀನು ಹೊಂದಿರುವ ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸಣ್ಣ ಮತ್ತು ಅತೀ ಸಣ್ಣ ರೈತರ ಜಮೀನಿನಲ್ಲಿ ಕೊಳವೆಬಾವಿ ಕೊರೆಸಿ, ಪಂಪ್ ಸೆಟ್ ಅಳವಡಿಸಿ ವಿದ್ಯುದ್ಧೀಕರಣಗೊಳಿಸಿ ನೀರಾವರಿ ಸೌಲಭ್ಯ ಕಲ್ಪಿಸಲಾಗುತ್ತಿದೆ. ಈ ಯೋಜನೆಯಡಿ ಕೋಲಾರ, ಚಿಕ್ಕಬಳ್ಳಾಪುರ, ಬೆಂಗಳೂರು(ಗ್ರಾ), ಬೆಂಗಳೂರು(ನಗರ), ತುಮಕೂರು ಮತ್ತು ರಾಮನಗರ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಅಂತರ್ಜಲ ಮಟ್ಟ ಕೆಳಗೆ ಕುಸಿದಿರುವುದರಿಂದ ಈ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಘಟಕ ವೆಚ್ಚ ರೂ.4.75 ಲಕ್ಷಕ್ಕೆ ಹೆಚ್ಚಿಸಲಾಗಿದ್ದು, ಇದರಲ್ಲಿ ರೂ.4.25 ಲಕ್ಷ ಸಹಾಯಧನವಿದ್ದು, ಉಳಿದ ರೂ.50,000/- ಅವಧಿಸಾಲವಾಗಿರುತ್ತದೆ. ಇತರೆ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಘಟಕ ವೆಚ್ಚ ರೂ.3.75 ಲಕ್ಷ ನಿಗದಿಪಡಿಸಿದ್ದು, ಇದರಲ್ಲಿ ರೂ.3.25 ಲಕ್ಷ ಸಹಾಯಧನ ಮತ್ತು ರೂ.50,000/- ಅವಧಿಸಾಲವಾಗಿರುತ್ತದೆ. ಘಟಕ ವೆಚ್ಚದ ಪೈಕಿ ವಿದ್ಯುದ್ದೀಕರಣಕ್ಕೆ ಘಟಕ ವೆಚ್ಚದ ಸಹಾಯಧನದ ಮಿತಿಯಲ್ಲಿ ಪ್ರತಿ ಕೊಳವೆಬಾವಿಗೆ ರೂ.75,000/-ಗಳನ್ನು ಸಂಬಂಧಿಸಿದ ಎಸ್ಕಾಂಗಳಿಗೆ ಬಿಡುಗಡೆ ಮಾಡಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಕನಿಷ್ಠ 21 ವರ್ಷಗಳು ಪೂರ್ಣಗೊಂಡಿರಬೇಕು ಗರಿಷ್ಠ ವಯೋಮಿತಿ ತೆಗೆದು ಹಾಕಲಾಗಿದೆ.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು.", "ಅರ್ಜಿದಾರರು ಸಣ್ಣ ಮತ್ತು ಅತಿ ಸಣ್ಣ ರೈತರಾಗಿರಬೇಕು ಹಾಗೂ ನೀರಾವರಿ ಸೌಲಭ್ಯ ಹೊಂದಿರಬಾರದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('7f6c026a-2aec-4d7a-a019-b305782cfb5e', 'SOCIAL-WELFARE-DEPAR-75', '81b60538-519f-4131-bd38-c390f2d882d6', 'Dairy Farming Scheme', 'Subsidy', 0, 'Under the Dairy Farming Scheme, beneficiaries are provided a subsidy of ₹1.25 lakhs to support the establishment and development of dairy farming for sustainable livelihood and milk production', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '9f118461-87d3-46ad-b82e-1c26d0e43ec5', 'ಹೈನುಗಾರಿಕೆ ಯೋಜನೆ', 'Dairy Farming Scheme', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಈ ಯೋಜನೆಯ ಅಡಿಯಲ್ಲಿ ಫಲಾನುಭವಿಗಳಿಗೆ ಹೈನುಗಾರಿಕೆಯನ್ನು ಸ್ಥಾಪಿಸಲು ಮತ್ತು ಅಭಿವೃದ್ಧಿಪಡಿಸಲು ₹1.25 ಲಕ್ಷಗಳ ಸಹಾಯಧನವನ್ನು ನೀಡಲಾಗುತ್ತದೆ, ಇದು ಸ್ಥಿರ ಜೀವನೋಪಾಯ ಮತ್ತು ಹಾಲು ಉತ್ಪಾದನೆಗೆ ನೆರವಾಗುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('fc348396-85e1-436e-ac60-ab216b499625', 'HOME-DEPARTMENT-19', 'e4118656-e98e-472f-ba77-d686d9788f3b', 'Application for Temporary License for Sale of Crackers', 'General', 7, 'A citizen can apply to get Temporary License for Sale of Crackers', '["AFFIDAVIT", "AADHAR", "GST/TIN CERTIFICATE", "SC/ST CASTE CERTIFICATE (IF APPLICABLE)", "PHYSICLLY CHALLENGED CERTIFICATE ( IF APPLICABLE)", "BY-LAW COPY ( IF APPLIED BY ORGANIZATION)"]', '["Citizens of India"]', '[]', '["Applicant needs to submit the appication", "Application will be processed by the concerned Police Station", "Dispatch of output certificate by police station to applicant"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'd7e849fd-83ee-4dec-863d-5596b4c09181', 'ಪಟಾಕಿ ಮಾರಾಟಕ್ಕೆ ತಾತ್ಕಾಲಿಕ ಪರವಾನಗಿ ಪ್ರಮಾಣಪತ್ರಕ್ಕಾಗಿ ಅರ್ಜಿ', NULL, NULL, NULL, NULL, NULL, 5000.00, NULL, 'ಪಟಾಕಿಗಳ ಮಾರಾಟಕ್ಕಾಗಿ ತಾತ್ಕಾಲಿಕ ಪರವಾನಗಿ ಪಡೆಯಲು ನಾಗರಿಕರು ಈ ಸೇವೆಗೆ ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು.', NULL, NULL, NULL, NULL, NULL, '["ಭಾರತದ ನಾಗರಿಕರು"]', '["ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಠಾಣೆಯು ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸಿ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸುತ್ತದೆ.", "ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಠಾಣೆಯು ಔಟ್"]', 1, '["ಪ್ರಮಾಣಪತ್ರ (ಅಫಿಡವಿಟ್).", "ಆಧಾರ್ ಕಾರ್ಡ್.", "ಜಿಎಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('585990b9-38ab-4a92-83a8-a09b1d1e5bcf', 'SOCIAL-WELFARE-DEPAR-60', '81b60538-519f-4131-bd38-c390f2d882d6', 'Dr. Babu Jagjeevan Ram Two Wheeler Cargo Transport Scheme', 'Loan with Subsidy', 0, 'In 2022-23, a scheme will be implemented to promote self-employment and increase self-confidence among Scheduled Castes and Scheduled Tribes youth. This scheme is designed to facilitate e-commerce businesses and create employment in other services. Under this scheme, beneficiaries who purchase electric or other two-wheeler/three-wheeler goods transport vehicles will receive a subsidy of Rs. 50,000 and a loan of Rs. 20,000.', '["Applicant Aadhar Card (Mandatory)", "Applicant Photo (Mandatory)", "Applicant Voter ID (Mandatory)", "Applicant Ration Card (Mandatory)", "Caste & Income Certificate issued by competent authority (Mandatory)", "Must Possess Relevant Vehicle Driving License (Mandatory)", "Must Possess Relevant Vehicle Quotation (Mandatory)", "In E-Commerce, submit proof of employment or a self-affidavit for selling goods (Mandatory)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)", "The applicant must declare they have not received prior assistance from the Corporation (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Applicant Age should be between 21 to 60 years.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '21c54a07-62d8-4175-a930-a12ddf74c181', 'ಡಾ. ಬಾಬು ಜಗಜೀವನ ರಾಂ ದ್ವಿಚಕ್ರ ವಾಹನ ಸರಕು ಸಾಗಾಣಿಕೆ ಯೋಜನೆ', 'Two Wheeler Cargo Transport Scheme', NULL, NULL, 'Online', NULL, NULL, NULL, '2022-23 ನೇ ಸಾಲಿನಲ್ಲಿ ಪರಿಶಿಷ್ಟ ಜಾತಿ ಮತ್ತು ವರಿಶಿಷ್ಟ ಪಂಗಡದ ಯುವಕರಲ್ಲಿ ಸ್ವಯಂ ಉದ್ಯೋಗವನ್ನು ಉತ್ತೇಜಿಸಲು ಮತ್ತು ಆತ್ಮವಿಶ್ವಾಸವನ್ನು ಹೆಚ್ಚಿಸಲು , ಇ-ಕಾಮರ್ಸ್ ವ್ಯವಹಾರಗಳನ್ನು ಸುಲಭಗೊಳಿಸಲು ಮತ್ತು ಇತರ ಸೇವೆಗಳಲ್ಲಿ ಉದ್ಯೋಗವನ್ನು ಸೃಷ್ಟಿಸಲು ಈ ಯೋಜನೆಯನ್ನು ವಿನ್ಯಾಸಗೊಳಿಸಲಾಗಿದೆ. ಈ ಯೋಜನೆಯಡಿಯಲ್ಲಿ, ವಿದ್ಯುತ್ ಅಥವಾ ಇತರೆ ಎರಡು/ಮೂರು ಚಕ್ರದ ಸರಕು ಸಾಗಣೆ ವಾಹನಗಳನ್ನು ಖರೀದಿಸುವ ಫಲಾನುಭವಿಗಳಿಗೆ ರೂ. 50,000 ಸಹಾಯಧನ ಹಾಗೂ ರೂ. 20,000 ಸಾಲವನ್ನು ನೀಡಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 60 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('9d107eeb-4dac-4c6f-89e0-57232afb04fd', 'SOCIAL-WELFARE-DEPAR-59', '81b60538-519f-4131-bd38-c390f2d882d6', 'Swavalambi Sarathi Scheme', 'Subsidy', 0, 'Under Swalambi Sarathi Yojana, the scheme will be implemented in collaboration with banks by sanctioning 75% subsidy or maximum Rs.4.00 lakhs for goods transport/taxi (yellow board) vehicles.', '["Applicant Aadhar Cards (Mandatory)", "Applicant Ration Card (Mandatory)", "Applicant Voter ID (Mandatory)", "Caste & Income Certificate issued by competent authority (Mandatory)", "Vehicle Quotation (Mandatory)", "The applicant must declare they have not received prior assistance from the Corporation (Mandatory)", "Applicant Photo (Mandatory)", "Bank Pass Book (with Cover Page) (Mandatory)", "Vehicle Driving License(DL) (Mandatory)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 56 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '21c54a07-62d8-4175-a930-a12ddf74c181', 'ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ ಯೋಜನೆ', 'Swavalambi Sarathi /ISB 3.5', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ ಯೋಜನೆಯಡಿ ಸರಕು ಸಾಗಾಣಿಕೆ/ಟ್ಯಾಕ್ಸಿ (ಹಳದಿ ಬೋರ್ಡ್) ವಾಹನಗಳಿಗೆ ಘಟಕ ವೆಚ್ಚದ ಶೇ.75ರಷ್ಟು ಅಥವಾ ಗರಿಷ್ಟ ರೂ.4.00 ಲಕ್ಷಗಳವರೆಗೆ ಸಹಾಯಧನವನ್ನು ಮಂಜೂರು ಮಾಡಿ ಬ್ಯಾಂಕ್', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 56 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('976bdce2-a39a-46a0-bb87-1aa55049f4df', 'SOCIAL-WELFARE-DEPAR-58', '81b60538-519f-4131-bd38-c390f2d882d6', 'Micro Credit Prerana Scheme 5 Lakh', 'Loan with Subsidy', 0, 'Loans and grants will be extended to support various economic activities undertaken by Self-Help Groups of Scheduled Caste women. Each female member will receive Rs. 25,000, comprising a subsidy of Rs. 15,000 and a loan of Rs. 10,000. Self-help groups with a minimum of 10 women members and a unit cost of Rs. 2.50 lakhs will be eligible for loan assistance as per regulations. The loan must be repaid to the Corporation in 36 equal installments with a 4% interest rate', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '21c54a07-62d8-4175-a930-a12ddf74c181', 'ಪ್ರೇರಣಾ (ಮೈಕ್ರೋ ಕ್ರೆಡಿಟ್) ಯೋಜನೆ 5 ಲಕ್ಷ', 'Prerana (Micro Credit) 5 Lakh', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯದ ಮಹಿಳಾ ಸ್ವಸಹಾಯ ಸಂಘಗಳ ವಿವಿಧ ಉದ್ದೇಶದ ಆರ್ಥಿಕ ಚಟುವಟಿಕೆಗಳಿಗೆ ಸಾಲ ಮತ್ತು ಸಹಾಯಧನ ನೀಡಲಾಗುವುದು. ಪ್ರತಿ ಮಹಿಳಾ ಸದಸ್ಯರಿಗೆ ರೂ 25000. ಇದರಲ್ಲಿ ಸಹಾಯಧನ ರೂ15000 ಹಾಗೂ ಸಾಲ ರೂ10000 ಗಳಾಗಿರುತ್ತದೆ. ಕನಿಷ್ಠ 10 ಜನ ಮಹಿಳಾ ಸದಸ್ಯರು ಇರುವ ಸ್ವ-ಸಹಾಯ ಗುಂಪಿಗೆ ಘಟಕ ವೆಚ್ಛ ರೂ 2.50 ಲಕ್ಷಗಳಂತೆ ನಿಯಮಾನುಸಾರ ಅರ್ಹರಿರುವ ಗುಂಪಿಗೆ ಸಾಲ ಸೌಲಭ್ಯ ಒದಗಿಸಲಾಗುವುದು. ಸದರಿ ಸಾಲದ ಹಣವನ್ನು 36 ಸಮ ಕಂತುಗಳಲ್ಲಿ ಶೇ 4 ರ ಬಡ್ಡಿ ದರದಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಮರುಪಾವತಿ ಮಾಡ ಬೇಕಾಗಿರುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('c94331a8-9d87-4cd8-80d1-e9e6e5d20e6c', 'SOCIAL-WELFARE-DEPAR-57', '81b60538-519f-4131-bd38-c390f2d882d6', 'Micro Credit Prerana Scheme', 'Loan with Subsidy', 0, 'Loans and grants will be extended to support various economic activities undertaken by Self-Help Groups of Scheduled Caste women. Each female member will receive Rs. 25,000, comprising a subsidy of Rs. 15,000 and a loan of Rs. 10,000. Self-help groups with a minimum of 10 women members and a unit cost of Rs. 2.50 lakhs will be eligible for loan assistance as per regulations. The loan must be repaid to the Corporation in 36 equal installments with a 4% interest rate', '["Applicant''s Aadhar Cards (Mandatory)", "Applicant''s Ration Card (Mandatory)", "Applicant''s Voter ID (Mandatory)", "Caste & Income Certificate issued by competent authority (Mandatory)", "The applicant must declare they have not received prior assistance from the Corporation (Mandatory)", "Applicant''s Photo (Mandatory)", "Bank Pass Book (with Cover Page) (Mandatory)", "Should Have Valid Association Registration Copy (Mandatory)", "Copy of at least 3 months'' worth of recent association meeting minutes (Mandatory)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 60 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability.", "Registered Copy of Self Help Group.", "Out of the 60% Scheduled Caste members of the association, 40% of the members should belong to the sub-castes belonging to the corporation.", "Members of the SHG should have ration card."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '21c54a07-62d8-4175-a930-a12ddf74c181', 'ಪ್ರೇರಣಾ (ಮೈಕ್ರೋ ಕ್ರೆಡಿಟ್) ಯೋಜನೆ', 'Prerana (Micro Credit)', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯದ ಮಹಿಳಾ ಸ್ವಸಹಾಯ ಸಂಘಗಳ ವಿವಿಧ ಉದ್ದೇಶದ ಆರ್ಥಿಕ ಚಟುವಟಿಕೆಗಳಿಗೆ ಸಾಲ ಮತ್ತು ಸಹಾಯಧನ ನೀಡಲಾಗುವುದು. ಪ್ರತಿ ಮಹಿಳಾ ಸದಸ್ಯರಿಗೆ ರೂ.25000. ಇದರಲ್ಲಿ ಸಹಾಯಧನ ರೂ.15000 ಹಾಗೂ ಸಾಲ ರೂ.10000 ಗಳಾಗಿರುತ್ತದೆ. ಕನಿಷ್ಠ 10 ಜನ ಮಹಿಳಾ ಸದಸ್ಯರು ಇರುವ ಸ್ವ-ಸಹಾಯ ಗುಂಪಿಗೆ ಘಟಕ ವೆಚ್ಛ ರೂ. 2.50 ಲಕ್ಷಗಳಂತೆ ನಿಯಮಾನುಸಾರ ಅರ್ಹರಿರುವ ಗುಂಪಿಗೆ ಸಾಲ ಸೌಲಭ್ಯ ಒದಗಿಸಲಾಗುವುದು. ಸದರಿ ಸಾಲದ ಹಣವನ್ನು 36 ಸಮ ಕಂತುಗಳಲ್ಲಿ ಶೇ 4 ರ ಬಡ್ಡಿ ದರದಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಮರುಪಾವತಿ ಮಾಡಬೇಕಾಗಿರುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 60 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು.", "ಚಾಲ್ತಿಯಲ್ಲಿರುವ ಸಂಘದ ನೊಂದಣಿ ಪತ್ರ.", "ಸಂಘದ ಶೇ 60 ರ ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸದಸ್ಯರುಗಳ ಪೈಕಿ ಶೇ 40 ರಷ್ಟು ಸದಸ್ಯರು ನಿಗಮಕ್ಕೆ ಸೇರಿದ ಉಪ ಜಾತಿಯವರಾಗಿರಬೇಕು.", "ಸಂಘದ ಸದಸ್ಯರು ಪಡಿತರ ಚೀಟಿಯನ್ನು ಹೊಂದಿರಬೇಕು."]', '[]', 1, '["ಎಲ್ಲಾ ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('96b8f7a4-21a7-4b3f-a9ed-714e6dae4bbf', 'ENERGY-DEPARTMENT-10', 'e0b8deb9-4426-4525-a8e5-aab3f707df7c', 'Application for new connection under EoDB where RoW permission and extention of Electrical infrastructure is not required (Single Installations only)', 'General', 0, '', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '665dc58e-475b-4883-93a4-8761c3bf0063', 'EoDB ಅಡಿಯಲ್ಲಿ ಹೊಸ ವಿದ್ಯುತ್', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3006');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('ea915778-b375-4983-a321-c61edbd0645f', 'SOCIAL-WELFARE-DEPAR-56', '81b60538-519f-4131-bd38-c390f2d882d6', 'Self Employment Direct Loan Scheme', 'Loan with Subsidy', 0, 'Scheduled caste individuals can engage in small-scale economic activities such as selling fruits, vegetables, fish, and rearing livestock like cows, sheep, pigs, or rabbits. The unit cost for these endeavors is Rs.1.00 lakh, with financial support comprising a Rs.50,000 subsidy and a Rs.50,000 loan. Beneficiaries are required to repay the loan to the corporation in 36 equal installments, with an interest rate of 4%.', '["Applicant Aadhar Card (Optional)", "Ration card (Optional)", "Aadhar linked PassBook Front Page Photo (Optional)", "Caste & Income Certificate issued by competent authority (Optional)", "The applicant must declare they have not received prior assistance from the Corporation (Optional)", "Passport size Photo (Optional)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)", "Project Report / Quotation (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 60 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '21c54a07-62d8-4175-a930-a12ddf74c181', 'ಸ್ವಯಂ ಉದ್ಯೋಗ (ನೇರಸಾಲ) ಯೋಜನೆ', 'Self Employment Scheme', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಪರಿಶಿಷ್ಟ ಜಾತಿ ನಿರುದ್ಯೋಗಿಗಳಿಗೆ ಹಣ್ಣು,, ತರಕಾರಿ, ಮೀನು, ಮಾಂಸ ಮಾರಾಟ, ಹಸು/ಕುರಿ/ಹಂದಿ/ಮೊಲ ಸಾಕಾಣಿಕೆ ಇತ್ಯಾದಿ ಕಿರು ಆರ್ಥಿಕ ಚಟುವಟಿಕೆಗಳಿಗೆ ಘಟಕ ವೆಚ್ಚ ರೂ.1.00ಲಕ್ಷಗಳಾಗಿದ್ದು, ಈ ಪೈಕಿ ರೂ.50,000/- ಸಹಾಯಧನ ಹಾಗೂ ರೂ.50,000/- ಸಾಲದ ರೂಪದಲ್ಲಿ ಆರ್ಥಿಕ ನೆರವನ್ನು ಕಲ್ಪಿಸಲಾಗುತ್ತಿದೆ. ಸಾಲದ ಮೊತ್ತವನ್ನು 36 ಸಮಾನ ಕಂತುಗಳಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಶೇ.4ರ ಬಡ್ಡಿದರದೊಂದಿಗೆ ಮರುಪಾವತಿಸಬೇಕಾಗಿರುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 60 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('e2f65336-f63e-4131-9a97-b97bcc317fad', 'SOCIAL-WELFARE-DEPAR-55', '81b60538-519f-4131-bd38-c390f2d882d6', 'ISB - Fast Food Truck Trailer/Mobile Food Kitchen - Rs. 4.00 Lakhs', 'Subsidy', 0, 'Under the ISB (Industrial Service Business) scheme, this fully subsidized Fast Food Truck Trailer/Mobile Kitchen is a mobile food service unit worth ₹4.00 lakhs.', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '21c54a07-62d8-4175-a930-a12ddf74c181', 'ಐಎಸ್ಬಿ - ಫಾಸ್ಟ್ ಫುಡ್ ಟ್ರಕ್ ಟ್ರೇಲರ್/ಮೊಬೈಲ್ ಫುಡ್ ಕಿಚನ್ - ₹4.00 ಲಕ್ಷಗಳು', 'Fast Food Truck Trailer/Mobile Food Kitchen - 4 Lakh', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಐಎಸ್ಬಿ (ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ) ಯೋಜನೆಯ ಅಡಿಯಲ್ಲಿ ಸಂಪೂರ್ಣ ಸಹಾಯಧನದೊಂದಿಗೆ ನೀಡಲಾಗುವ ಈ ಫಾಸ್ಟ್ ಫುಡ್ ಟ್ರಕ್ ಟ್ರೇಲರ್/ಮೊಬೈಲ್ ಕಿಚನ್ ₹4.00 ಲಕ್ಷ ಮೌಲ್ಯದ ಚಲಿಸುವ ಆಹಾರ ಸೇವಾ ಘಟಕವಾಗಿದೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('ca9cbca4-dd97-4123-9394-1eccf8176ec5', 'SOCIAL-WELFARE-DEPAR-54', '81b60538-519f-4131-bd38-c390f2d882d6', 'Land Purchase scheme', 'Loan with Subsidy', 0, 'Under the Land-Ownership Scheme, land will be purchased from non-Scheduled Caste/Scheduled Tribe landowners. Landless women agricultural labourers belonging to the Scheduled Caste community will receive Rs. 20 lakh for 27 districts and Rs. 25 lakh for 4 districts (Bangalore City, Bangalore Rural, Chikkaballapur, and Ramanagara), with 50% subsidy and 50% loan. Khushki/Tari/Bagaitu land within a maximum distance of 10 km from the beneficiary''s residence will be provided. The loan must be repaid to the Corporation in 10 annual equal installments at an interest rate of 6% per annum.', '["Beneficiary Aadhaar Card As Residential Proof (Mandatory)", "Beneficiary Caste Certificate Issued by the competent authority (Mandatory)", "Beneficiary Income Certificate Issued by the competent authority (Mandatory)", "Letter of Landless Agricultural labourers (from Tahsildar) (Mandatory)", "Beneficiary Ration Card (Mandatory)", "Land Owners Cover letter for sale of land (To be notarized and submitted on Stamp paper.) (Mandatory)", "land owner Family Tree (To be verified and submitted by village accountants.) (Mandatory)", "Letter of No Objection (NOC) from Family Members (should be notarized and submitted.) (Mandatory)", "Latest pahani and mutation copy (Mandatory)", "Land Owners Last 13 years E.C. (Encumbrance Certificate should be submitted.) (Mandatory)", "Beneficiary Photo (Mandatory)"]', '["Applicants must belong to scheduled castes and its related community.", "The applicant must be a land less agriculture labour family.", "Self-declaration certificate must be submitted in case of caste certificate.", "Should be resident of Karnataka state.", "The applicant and no member of his family should not be in employment in any Govt./Semi Govt organization.", "The beneficiaries eligible to avail of facilities under the land ownership scheme must be landless women agricultural laborers.", "Additionally, the landowners selling the land should not belong to Scheduled Castes and Scheduled Tribes.", "The land to be purchased is a maximum of 10 km from the place where the beneficiary lives. m. should be within range."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '21c54a07-62d8-4175-a930-a12ddf74c181', 'ಭೂ-ಒಡೆತನ ಯೋಜನೆ', 'Land Purchase scheme', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಭೂ -ಒಡೆತನ ಯೋಜನೆಯಡಿ ಪರಿಶಿಷ್ಟ ಜಾತಿ / ಪರಿಶಿಷ್ಟ ಪಂಗಡಕ್ಕೆ ಸೇರದ ಭೂ ಮಾಲೀಕರಿಂದ ಜಮೀನನ್ನು ಖರೀದಿಸಿ, ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸಮುದಾಯದ ಭೂ ರಹಿತ ಮಹಿಳಾ ಕೃಷಿ ಕಾರ್ಮಿಕರಿಗೆ 27 ಜಿಲ್ಲೆಗಳಿಗೆ ರೂ 20 ಲಕ್ಷ ಮತ್ತು 4 ಜಿಲ್ಲೆಗಳಿಗೆ (ಬೆಂಗಳೂರು ನಗರ, ಬೆಂಗಳೂರು ಗ್ರಾಮಾಂತರ, ಚಿಕ್ಕಬಳ್ಳಾಪುರ ಮತ್ತು ರಾಮನಗರ) ರೂ 25 ಲಕ್ಷಗಳಿಗೆ (ಸಹಾಯಧನ ಶೇ 50 ಮತ್ತು ಸಾಲ ಶೇ 50 ರಷ್ಟು) ಖುಷ್ಕಿ/ತರಿ/ಬಾಗಾಯ್ತು ಜಮೀನನ್ನು ಫಲಾನುಭವಿಯು ವಾಸಿಸುತ್ತಿರುವ ಸ್ಥಳದಿಂದ ಗರಿಷ್ಠ 10 ಕಿ. ಮೀ. ವ್ಯಾಪ್ತಿಯೊಳಗೆ ಖರೀದಿಸಿ, ಭೂರಹಿತ ಮಹಿಳಾ ಕೃಷಿ ಕಾರ್ಮಿಕರಿಗೆ ಒದಗಿಸಲಾಗುವುದು ಮತ್ತು ಸಾಲದ ಮೊತ್ತವನ್ನು 10 ವಾರ್ಷಿಕ ಸಮ ಕಂತುಗಳಲ್ಲಿ ವಾರ್ಷಿಕ ಶೇ 6 ರ ಬಡ್ಡಿ ದರದಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಮರುಪಾವತಿ ಮಾಡ ಬೇಕಾಗಿರುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '["ಅರ್ಜಿದಾರರು ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸಂಬಂಧಿತ ಜಾತಿಗಳಿಗೆ ಸೇರಿದವರಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಭೂ ರಹಿತ ಕೃಷಿ ಕಾರ್ಮಿಕ ಕುಟುಂಬದವರಾಗಿರಬೇಕು.", "ಜಾತಿ ಪ್ರಮಾಣ ಪತ್ರವನ್ನು ಸಲ್ಲಿಸಿದಲ್ಲಿ ಕಡ್ಡಾಯವಾಗಿ ಸ್ವಯಂ ಘೋಷಣೆ ಪ್ರಮಾಣ ಪತ್ರವನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು/ ಕುಟುಂಬದ ಅವಲಂಬಿತ ಯಾವುದೇ ಸದಸ್ಯರು ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ನೌಕರಿಯಲ್ಲಿರಬಾರದು.", "ಭೂಒಡೆತನ ಯೋಜನೆಯಡಿ ಸೌಲಭ್ಯ ಪಡೆಯಲು ಫಲಾಪೇಕ್ಷಿಯು ಭೂರಹಿತ ಮಹಿಳಾ ಕೃಷಿ ಕಾರ್ಮಿಕರಾಗಿರಬೇಕು.", "ಜಮೀನು ಮಾರಾಟ ಮಾಡುವ ಭೂಮಾಲೀಕರು ಪರಿಶಿಷ್ಟಜಾತಿ ಮತ್ತು ಪರಿಶಿಷ್ಟ ಪಂಗಡಕ್ಕೆ ಸೇರಿರಬಾರದು.", "ಖರೀದಿಸುವ ಜಮೀನು ಫಲಾನುಭವಿಯು ವಾಸಿಸುತ್ತಿರುವ ಸ್ಥಳದಿಂದ ಗರಿಷ್ಠ 10 ಕಿ. ಮೀ. ವ್ಯಾಪ್ತಿಯೊಳಗೆ ಇರಬೇಕು."]', '[]', 1, '["ಫಲಾನುಭವಿಯ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('0eb75ef0-e81c-4eb0-a732-acd1076446e0', 'SOCIAL-WELFARE-DEPAR-53', '81b60538-519f-4131-bd38-c390f2d882d6', 'Sheep/Goat Farming Scheme', 'Loan with Subsidy', 0, 'Under the Sheep Farming Scheme, beneficiaries receive a loan of ₹50,000 along with a subsidy of ₹50,000 to support sustainable sheep rearing and income generation', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '21c54a07-62d8-4175-a930-a12ddf74c181', 'ಕುರಿ/ಮೇಖೆ ಸಾಕಾಣಿಕೆ ಯೋಜನೆ', 'Sheep/Goat Farming Scheme', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಈ ಯೋಜನೆಯ ಅಡಿಯಲ್ಲಿ ಫಲಾನುಭವಿಗಳಿಗೆ ₹50,000 ರ ঋಣ ಮತ್ತು ₹50,000 ರ ಸಹಾಯಧನವನ್ನು ಒದಗಿಸಲಾಗುತ್ತದೆ, ಇದು ಸ್ಥಿರ ಕುರಿ ಸಾಕಾಣಿಕೆ ಮತ್ತು ಆದಾಯ ಉತ್ಪಾದನೆಗೆ ನೆರವಾಗುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('9523ad1f-6883-4f20-b9b3-ee41a1cdd13a', 'SOCIAL-WELFARE-DEPAR-52', '81b60538-519f-4131-bd38-c390f2d882d6', 'Industrial Service Business - ISB (in association with Bank) Maximum Rs. 2 lakh subsidy', 'Subsidy', 0, 'Industrial Service Business (in collaboration with the Bank) development scheme, assistance from the Corporation to start self-employment units for unemployed youths and women of the Scheduled Caste community in small scale industry, service sector and business sectors and the rest is loan from the bank. Subsidy of 70% of the unit cost or a maximum of Rs 2 lakh', '["Applicant''s Aadhar Cards (Optional)", "Ration Card (Mandatory)", "Aadhar linked PassBook Front Page Photo (Mandatory)", "Caste & Income Certificate issued by competent authority (Optional)", "Project Report / Quotation (Optional)", "The applicant must declare they have not received prior assistance from the Corporation (Optional)", "Applicant Photo (Mandatory)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 56 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '21c54a07-62d8-4175-a930-a12ddf74c181', 'ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್', 'Industrial Service Business 2.0', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 56 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('b6f3d85c-11bd-4423-8fcd-c880568ef725', 'SOCIAL-WELFARE-DEPAR-51', '81b60538-519f-4131-bd38-c390f2d882d6', 'Industrial Service Business - ISB (in association with Bank) Maximum Rs. 1 lakh subsidy', 'Subsidy', 0, 'Industrial Service Busines (in collaboration with the Bank) development scheme, assistance from the Corporation to start self-employment units for unemployed youths and women of the Scheduled Caste community in small scale industry, service sector and business sectors and the rest is loan from the bank. Subsidy of 20% of the unit cost or a maximum of Rs 1 lakh', '["Applicant Aadhar Cards (Mandatory)", "Applicant Ration Card (Mandatory)", "Applicant Voter ID (Mandatory)", "Caste & Income Certificate issued by competent authority (Mandatory)", "Project Report / Quotation (Mandatory)", "The applicant must declare they have not received prior assistance from the Corporation (Mandatory)", "Applicant Aadhar Card (Mandatory)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 56 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '21c54a07-62d8-4175-a930-a12ddf74c181', 'ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್', 'Industrial Service Business 1.0', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 56 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('07a2bce2-ad0c-4d95-b6bc-98206f2c25d5', 'SOCIAL-WELFARE-DEPAR-50', '81b60538-519f-4131-bd38-c390f2d882d6', 'Ganga Kalyana', 'Loan with Subsidy', 0, 'Under this scheme, irrigation facilities are provided to small and very small scheduled caste farmers with 1½ to 5.00 acres of land by drilling boreholes, installing pump sets, and electrifying them. In certain districts such as Kolar, Chikkaballapur, Bangalore (Rural), Bangalore (City), Tumkur, and Ramnagar, the unit cost has been increased to Rs.4.75 lakh due to declining groundwater levels. Of this amount, Rs.4.25 lakh will be subsidized, and the remaining Rs.50,000/- will be provided as a term loan.In other districts, the unit cost is fixed at Rs.3.75 lakh, with Rs.3.25 lakh provided as a subsidy and Rs.50,000/- lakh as a term loan. Additionally, out of the unit cost, Rs.75,000 per borehole will be allocated to the respective Escom for electrification, within the subsidy limit of the unit cost.', '["Applicant Aadhar Cards (Optional)", "Ration Card (Mandatory)", "Aadhar linked PassBook Front Page Photo (Mandatory)", "Caste & Income Certificate issued by competent authority (Optional)", "The applicant must declare they have not received prior assistance from the Corporation (Optional)", "Passport size photo of the applicant (Mandatory)", "Small and Marginal Farmer Certificate (Mandatory)", "RTC (Mandatory)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicants must be at least 21 years old and there is no upper age limit.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability.", "The applicants must be small and medium marginal farmers and should not have access to irrigation facilities."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '21c54a07-62d8-4175-a930-a12ddf74c181', 'ಗಂಗಾ ಕಲ್ಯಾಣ ಯೋಜನೆ', 'Ganga Kalyana', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಈ ಯೋಜನೆಯಡಿ 1½ ಎಕರೆಯಿಂದ 5.00 ಎಕರೆ ಜಮೀನು ಹೊಂದಿರುವ ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸಣ್ಣ ಮತ್ತು ಅತೀ ಸಣ್ಣ ರೈತರ ಜಮೀನಿನಲ್ಲಿ ಕೊಳವೆಬಾವಿ ಕೊರೆಸಿ, ಪಂಪ್ ಸೆಟ್ ಅಳವಡಿಸಿ ವಿದ್ಯುದ್ಧೀಕರಣಗೊಳಿಸಿ ನೀರಾವರಿ ಸೌಲಭ್ಯ ಕಲ್ಪಿಸಲಾಗುತ್ತಿದೆ. ಈ ಯೋಜನೆಯಡಿ ಕೋಲಾರ, ಚಿಕ್ಕಬಳ್ಳಾಪುರ, ಬೆಂಗಳೂರು(ಗ್ರಾ), ಬೆಂಗಳೂರು(ನಗರ), ತುಮಕೂರು ಮತ್ತು ರಾಮನಗರ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಅಂತರ್ಜಲ ಮಟ್ಟ ಕೆಳಗೆ ಕುಸಿದಿರುವುದರಿಂದ ಈ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಘಟಕ ವೆಚ್ಚ ರೂ.4.75 ಲಕ್ಷಕ್ಕೆ ಹೆಚ್ಚಿಸಲಾಗಿದ್ದು, ಇದರಲ್ಲಿ ರೂ.4.25 ಲಕ್ಷ ಸಹಾಯಧನವಿದ್ದು, ಉಳಿದ ರೂ.50,000/- ಅವಧಿಸಾಲವಾಗಿರುತ್ತದೆ. ಇತರೆ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಘಟಕ ವೆಚ್ಚ ರೂ.3.75 ಲಕ್ಷ ನಿಗದಿಪಡಿಸಿದ್ದು, ಇದರಲ್ಲಿ ರೂ.3.25 ಲಕ್ಷ ಸಹಾಯಧನ ಮತ್ತು ರೂ.50,000/- ಅವಧಿಸಾಲವಾಗಿರುತ್ತದೆ. ಘಟಕ ವೆಚ್ಚದ ಪೈಕಿ ವಿದ್ಯುದ್ದೀಕರಣಕ್ಕೆ ಘಟಕ ವೆಚ್ಚದ ಸಹಾಯಧನದ ಮಿತಿಯಲ್ಲಿ ಪ್ರತಿ ಕೊಳವೆಬಾವಿಗೆ ರೂ.75,000/-ಗಳನ್ನು ಸಂಬಂಧಿಸಿದ ಎಸ್ಕಾಂಗಳಿಗೆ ಬಿಡುಗಡೆ ಮಾಡಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಕನಿಷ್ಠ 21 ವರ್ಷಗಳು ಪೂರ್ಣಗೊಂಡಿರಬೇಕು ಗರಿಷ್ಠ ವಯೋಮಿತಿ ತೆಗೆದು ಹಾಕಲಾಗಿದೆ.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು.", "ಅರ್ಜಿದಾರರು ಸಣ್ಣ ಮತ್ತು ಅತಿ ಸಣ್ಣ ರೈತರಾಗಿರಬೇಕು ಹಾಗೂ ನೀರಾವರಿ ಸೌಲಭ್ಯ ಹೊಂದಿರಬಾರದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('b1d19120-b992-4260-9391-a937525b4b93', 'SOCIAL-WELFARE-DEPAR-49', '81b60538-519f-4131-bd38-c390f2d882d6', 'Dairy Farming Scheme', 'Subsidy', 0, 'Under the Dairy Farming Scheme, beneficiaries are provided a subsidy of ₹1.25 lakhs to support the establishment and development of dairy farming for sustainable livelihood and milk production', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '21c54a07-62d8-4175-a930-a12ddf74c181', 'ಹೈನುಗಾರಿಕೆ ಯೋಜನೆ', 'Dairy Farming Scheme', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಈ ಯೋಜನೆಯ ಅಡಿಯಲ್ಲಿ ಫಲಾನುಭವಿಗಳಿಗೆ ಹೈನುಗಾರಿಕೆಯನ್ನು ಸ್ಥಾಪಿಸಲು ಮತ್ತು ಅಭಿವೃದ್ಧಿಪಡಿಸಲು ₹1.25 ಲಕ್ಷಗಳ ಸಹಾಯಧನವನ್ನು ನೀಡಲಾಗುತ್ತದೆ, ಇದು ಸ್ಥಿರ ಜೀವನೋಪಾಯ ಮತ್ತು ಹಾಲು ಉತ್ಪಾದನೆಗೆ ನೆರವಾಗುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('e4376922-42ce-49bf-8437-7599c7d30c86', 'HOME-DEPARTMENT-21', 'e4118656-e98e-472f-ba77-d686d9788f3b', 'Tenant Verification Service', 'General', 21, 'This service enables property owners to submit tenant details to the Police Department for verification of the tenant’s identity and background.', '["Passport size photo", "Identify Proof", "Address Proof"]', '["Citizens of India"]', '[]', '["Applicant needs to submit the appication", "Application will be processed by the concerned Police Station", "Dispatch of Police Verification Certificate by the concerned police department to the applicant"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'd7e849fd-83ee-4dec-863d-5596b4c09181', 'ಬಾಡಿಗೆದಾರರ ಪರಿಶೀಲನ ಅರ್ಜಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಈ ಸೇವೆಯ ಮೂಲಕ ಆಸ್ತಿ ಮಾಲೀಕರು ಬಾಡಿಗೆದಾರರ ಗುರುತು ಮತ್ತು ಪೂರ್ವಾಪರಗಳನ್ನು ಪರಿಶೀಲಿಸುವ ಉದ್ದೇಶಕ್ಕಾಗಿ ಅವರ ವಿವರಗಳನ್ನು ಪೊಲೀಸ್ ಇಲಾಖೆಗೆ ಸಲ್ಲಿಸಬಹುದು.', NULL, NULL, NULL, NULL, NULL, '["ಭಾರತದ ನಾಗರಿಕರು"]', '["ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಠಾಣೆಯು ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸಿ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸುತ್ತದೆ.", "ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಇಲಾಖೆಯು ಪೊಲೀಸ್ ಪರಿಶೀಲನಾ ಪ್ರಮಾಣಪತ್ರವನ್ನು ಅರ್ಜಿದಾರರಿಗೆ ರವಾನಿಸುತ್ತದೆ."]', 1, '["ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('d0b81d7b-2730-477c-965c-b78839c42f4e', 'HOME-DEPARTMENT-20', 'e4118656-e98e-472f-ba77-d686d9788f3b', 'NOC for setting up of Petroleum, Diesel and Naphtha sale and transport', 'General', 21, 'A citizen can apply to get NOC required for setting up of petroleum, diesel & Naphtha, Sale, Transport', '["Land Documents", "Blueprint", "NOC from HP/BPC/IOC", "Tax Paid Receipt", "NOC from Land Owner", "Sale deed", "Khatha", "NOC and Occupancy Certificate from Fire Department and Electrical Inspectorate", "Rental Lease Deed/ Partnership Deed/ Blueprint", "Memorandum of Association"]', '["Citizens of India"]', '[]', '["Applicant needs to submit the appication", "Application will be processed by the concerned Police Station", "Dispatch of output certificate by police station to applicant"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'd7e849fd-83ee-4dec-863d-5596b4c09181', 'ಪೆಟ್ರೋಲಿಯಂ, ಡೀಸೆಲ್ ಮತ್ತು ನಾಫ್ತಾ ಮಾರಾಟ ಮತ್ತು ಸಾರಿಗೆ ಸ್ಥಾಪನೆಗೆ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರಕ್ಕಾಗಿ ಅರ್ಜಿ', NULL, NULL, NULL, NULL, NULL, 500.00, NULL, 'ಪೆಟ್ರೋಲಿಯಂ, ಡೀಸೆಲ್ ಮತ್ತು ನಾಫ್ತಾ ಸಂಗ್ರಹಣೆ, ಮಾರಾಟ ಹಾಗೂ ಸಾಗಣೆಗಾಗಿ ಅಗತ್ಯವಿರುವ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC) ಪಡೆಯಲು ನಾಗರಿಕರು ಈ ಸೇವೆಗೆ ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು.', NULL, NULL, NULL, NULL, NULL, '["ಭಾರತದ ನಾಗರಿಕರು"]', '["ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಠಾಣೆಯು ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸಿ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸುತ್ತದೆ.", "ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಠಾಣೆಯು ಔಟ್"]', 1, '["ಭೂಮಿಗೆ ಸಂಬಂಧಿಸಿದ ದಾಖಲೆಗಳು.", "ನೀಲನಕ್ಷೆ (Blueprint).", "HPCL / BPCL / IOCL ಸಂಸ್ಥೆಗಳಿಂದ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC).", "ತೆರಿಗೆ ಪಾವತಿ ರಸೀದಿ.", "ಭೂಮಿಯ ಮಾಲೀಕರಿಂದ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC).", "ಮಾರಾಟ ಪತ್ರ (Sale Deed).", "ಖಾತಾ ದಾಖಲೆ (Khatha).", "ಅಗ್ನಿಶಾಮಕ ಇಲಾಖೆ ಮತ್ತು ವಿದ್ಯುತ್ ನಿರೀಕ್ಷಣಾಲಯದಿಂದ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC) ಹಾಗೂ ಆಕ್ಯುಪೆನ್ಸಿ ಪ್ರಮಾಣಪತ್ರ (Occupancy Certificate).", "ಬಾಡಿಗೆ / ಗುತ್ತಿಗೆ ಪತ್ರ, ಪಾಲುದಾರಿಕೆ ಪತ್ರ ಅಥವಾ ನೀಲನಕ್ಷೆ.", "ಸಂಸ್ಥೆಯ ಸ್ಮರಣ ಪತ್ರ (Memorandum of Association – MOA)."]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('da72cdae-bd61-4d13-a6fa-6eca11eb6f21', 'HOME-DEPARTMENT-18', 'e4118656-e98e-472f-ba77-d686d9788f3b', 'Missing Report of documents, Mobile phone etc', 'General', 0, 'Application for preliminary registration of any complaint', '["Identify Proof", "Supporting Documents of the lost Articles"]', '["Any citizen currently staying in Karnataka"]', '[]', '["Applicant needs to submit the appication", "Application will be processed by the concerned Police Station", "Dispatch of output certificate by police station to compalinant"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'd7e849fd-83ee-4dec-863d-5596b4c09181', 'ಮೊಬೈಲ್ / ದಾಖಲೆಗಳು ಕಳುವಾದ ಬಗ್ಗೆ ದೂರು', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಯಾವುದೇ ದೂರಿನ ಪ್ರಾಥಮಿಕ ನೋಂದಣಿಗಾಗಿ ಅರ್ಜಿ ಸಲ್ಲಿಸುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಪ್ರಸ್ತುತ ಕರ್ನಾಟಕದಲ್ಲಿ ವಾಸಿಸುತ್ತಿರುವ ಯಾವುದೇ ನಾಗರಿಕರು."]', '["ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಠಾಣೆಯು ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸಿ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸುತ್ತದೆ.", "ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಠಾಣೆಯು ಔಟ್"]', 1, '["ಗುರುತಿನ ಪುರಾವೆ.", "ಕಳೆದುಹೋದ ವಸ್ತುಗಳಿಗೆ ಸಂಬಂಧಿಸಿದ ಪೂರಕ ದಾಖಲೆಗಳು."]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('3114051c-0b34-48b5-b5e7-ae9293f562bd', 'HOME-DEPARTMENT-17', 'e4118656-e98e-472f-ba77-d686d9788f3b', 'NOC for petrol pump,gas agency,hotel,bar etc.', 'General', 3, 'Citizens can apply for this service to get NOC for new Petrol Pumps, Gas Agencies, Hotels, Bars etc', '["Land Documents.", "NOC from HPCL/BPCL/IOCL/Others.", "Tax Paid Details.", "NOC from Fire Department.", "NOC from Electrical Department.", "Permission letter from Excise Department.", "Permission letter from Health Department.", "Memorandum of Association"]', '["Citizens of India"]', '[]', '["Applicant needs to submit the appication.", "Application will be processed by the concerned Police Station.", "Dispatch of Police Dept NOC by the concerned police station to the applicant"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'd7e849fd-83ee-4dec-863d-5596b4c09181', 'ಪೆಟ್ರೋಲ್ ಪಂಪ್, ಹೋಟೆಲ್, ಗ್ಯಾಸ್ ಏಜೆನ್ಸಿ ಇತ್ಯಾದಿಗಳಿಗೆ ನಿರಾಕ್ಷೇಪಣಾ ಪತ್ರ ಪಡೆಯಲು ಅರ್ಜಿ', NULL, NULL, NULL, NULL, NULL, 500.00, NULL, 'ಹೊಸ ಪೆಟ್ರೋಲ್ ಬಂಕ್', NULL, NULL, NULL, NULL, NULL, '["ಭಾರತದ ನಾಗರಿಕರು"]', '["ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಠಾಣೆಯು ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸಿ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸುತ್ತದೆ.", "ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಠಾಣೆಯು ಪೊಲೀಸ್ ಇಲಾಖೆಯ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರವನ್ನು (NOC) ಅರ್ಜಿದಾರರಿಗೆ ರವಾನಿಸುತ್ತದೆ."]', 1, '["ಭೂಮಿಗೆ ಸಂಬಂಧಿಸಿದ ದಾಖಲೆಗಳು.", "HPCL / BPCL / IOCL ಅಥವಾ ಇತರ ಸಂಬಂಧಿತ ಸಂಸ್ಥೆಗಳಿಂದ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC).", "ತೆರಿಗೆ ಪಾವತಿಸಿದ ವಿವರಗಳು.", "ಅಗ್ನಿಶಾಮಕ ಇಲಾಖೆಯಿಂದ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC).", "ವಿದ್ಯುತ್ ಇಲಾಖೆಯಿಂದ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC).", "ಅಬಕಾರಿ ಇಲಾಖೆಯಿಂದ ಅನುಮತಿ ಪತ್ರ.", "ಆರೋಗ್ಯ ಇಲಾಖೆಯಿಂದ ಅನುಮತಿ ಪತ್ರ.", "ಸಂಸ್ಥೆಯ ಸ್ಮರಣ ಪತ್ರ (Memorandum of Association – MOA)."]', NULL, NULL, NULL);
