INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('5bc7b543-4fef-4a22-8b78-8da569931914', 'HOME-DEPARTMENT-15', 'e4118656-e98e-472f-ba77-d686d9788f3b', 'Disposal of petitions', 'General', 45, 'Applicant can file for a petition with police department using this service', '["Facts of the Petition"]', '["Citizens of India"]', '[]', '["Applicant needs to submit the appication", "Application will be processed by the concerned Police Station", "Endorsement will be given by police station to applicant after the disposal of Petition."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'd7e849fd-83ee-4dec-863d-5596b4c09181', 'ಅರ್ಜಿಗಳನ್ನು ಸ್ವೀಕರಿಸಲು ಮತ್ತು ವಿಲೇವಾರಿ ಮಾಡಲು ಅರ್ಜಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಅರ್ಜಿದಾರರು ಈ ಸೇವೆಯ ಮೂಲಕ ಪೊಲೀಸ್ ಇಲಾಖೆಗೆ ಮನವಿಯನ್ನು ಸಲ್ಲಿಸಬಹುದು.', NULL, NULL, NULL, NULL, NULL, '["ಭಾರತದ ನಾಗರಿಕರು"]', '["ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಠಾಣೆಯು ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸಿ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸುತ್ತದೆ.", "ಅರ್ಜಿಯ ವಿಲೇವಾರಿಯ ನಂತರ ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಠಾಣೆಯು ಅರ್ಜಿದಾರರಿಗೆ ಹಿಂಬರಹವನ್ನು ನೀಡುತ್ತದೆ."]', 1, '["ಮನವಿಯ ವಾಸ್ತವಾಂಶಗಳು"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('c4259089-fa93-4cb9-8eb3-5a7e37f73b37', 'HOME-DEPARTMENT-14', 'e4118656-e98e-472f-ba77-d686d9788f3b', 'Permission for Peaceful Assembly and procession', 'General', 15, 'Citizens can apply for this service to get permission for peaceful assembly or procession', '["NOC from Local Authorities", "Fitness Certificate of Stage", "NOC from Electrical Department", "Permission letter of owner", "Permission for Amplified sound system"]', '["Citizens of India"]', '[]', '["Applicant needs to submit the appication", "Application will be processed by the concerned Police Station", "Dispatch of Police Dept NOC by the concerned police station to the applicant"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'd7e849fd-83ee-4dec-863d-5596b4c09181', 'ಶಾಂತಿಯುತ ಸಭೆ ಮತ್ತು ಮೆರವಣಿಗೆ ಮಾಡಲು ಅನುಮತಿಗಾಗಿ ಅರ್ಜಿ', NULL, NULL, NULL, NULL, NULL, 20.00, NULL, 'ಶಾಂತಿಯುತ ಸಭೆ ಅಥವಾ ಮೆರವಣಿಗೆಯನ್ನು ಆಯೋಜಿಸಲು ಅನುಮತಿ ಪಡೆಯುವ ಸಲುವಾಗಿ ನಾಗರಿಕರು ಈ ಸೇವೆಗೆ ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು.', NULL, NULL, NULL, NULL, NULL, '["ಭಾರತದ ನಾಗರಿಕರು"]', '["ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಠಾಣೆಯು ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸಿ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸುತ್ತದೆ.", "ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಠಾಣೆಯು ಪೊಲೀಸ್ ಇಲಾಖೆಯ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರವನ್ನು (NOC) ಅರ್ಜಿದಾರರಿಗೆ ರವಾನಿಸುತ್ತದೆ."]', 1, '["ಸ್ಥಳೀಯ ಪ್ರಾಧಿಕಾರಗಳಿಂದ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC).", "ವೇದಿಕೆಯ ಸುರಕ್ಷತೆ ಮತ್ತು ಸದೃಢತೆಯ ದೃಢೀಕರಣ ಪ್ರಮಾಣಪತ್ರ.", "ವಿದ್ಯುತ್ ಇಲಾಖೆಯಿಂದ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC).", "ಮಾಲೀಕರ ಅನುಮತಿ ಪತ್ರ.", "ಧ್ವನಿವರ್ಧಕ ವ್ಯವಸ್ಥೆಯನ್ನು ಬಳಸಲು ಅನುಮತಿ ಪತ್ರ."]', NULL, NULL, NULL);
