INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('056e87fc-191f-4418-a87b-b0a553c8001f', 'HOME-DEPARTMENT-11', 'e4118656-e98e-472f-ba77-d686d9788f3b', 'Locked Home Details', 'General', 0, 'A citizen who is travelling out of station, can register with the Police station of their jurisdiction towards monitoring the house', '["Identity Proof", "Address Proof"]', '["Citizens of India"]', '[]', '["A citizen who is travelling out of station, can register with the Police station of their jurisdiction towards monitoring the house"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'd7e849fd-83ee-4dec-863d-5596b4c09181', 'ಬೀಗ ಹಾಕಿದ ಮನೆಯ ನೋಂದಣಿಗೆ ಅರ್ಜಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ನಿಲ್ದಾಣದಿಂದ ಹೊರಗೆ ಪ್ರಯಾಣಿಸುವ ನಾಗರಿಕರು, ತಾವು ವಾಸಿಸುವ ವ್ಯಾಪ್ತಿಯ ಪೊಲೀಸ್ ಠಾಣೆಯಲ್ಲಿ ತಮ್ಮ ಮನೆಯ ಮೇಲ್ವಿಚಾರಣೆಗಾಗಿ ನೋಂದಾಯಿಸಿಕೊಳ್ಳಬಹುದು.', NULL, NULL, NULL, NULL, NULL, '["ಭಾರತದ ನಾಗರಿಕರು"]', '["ನಾಗರಿಕರು ಊರಿನಿಂದ ಹೊರಗೆ ಪ್ರಯಾಣಿಸುವ ಸಂದರ್ಭದಲ್ಲಿ, ತಮ್ಮ ಮನೆಯ ಮೇಲ್ವಿಚಾರಣೆಗಾಗಿ ತಮ್ಮ ವ್ಯಾಪ್ತಿಗೆ ಒಳಪಡುವ ಪೊಲೀಸ್ ಠಾಣೆಯಲ್ಲಿ ನೋಂದಣಿ ಮಾಡಿಕೊಳ್ಳಬಹುದು."]', 1, '["ಗುರುತಿನ ಪುರಾವೆ", "ವಿಳಾಸದ ಪುರಾವೆ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('078d3799-e3a3-423c-8331-bc34bed7a3d2', 'HOME-DEPARTMENT-10', 'e4118656-e98e-472f-ba77-d686d9788f3b', 'Senior Citizen Registration', 'General', 0, 'Senior citizens can register with the Police department for extra monitoring at their households', '["Identity Proof"]', '["Citizens of India"]', '[]', '["Applicant needs to submit the appication", "Application will be processed by the concerned Police Station"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'd7e849fd-83ee-4dec-863d-5596b4c09181', 'ಹಿರಿಯ ನಾಗರಿಕರ ನೋಂದಣಿಗೆ ಅರ್ಜಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಹಿರಿಯ ನಾಗರಿಕರು ತಮ್ಮ ಮನೆಗಳಿಗೆ ಹೆಚ್ಚುವರಿ ಪೊಲೀಸ್ ನಿಗಾ ಮತ್ತು ಮೇಲ್ವಿಚಾರಣೆಯನ್ನು ಪಡೆಯಲು ಪೊಲೀಸ್ ಇಲಾಖೆಯಲ್ಲಿ ನೋಂದಾಯಿಸಿಕೊಳ್ಳಬಹುದು.', NULL, NULL, NULL, NULL, NULL, '["ಭಾರತದ ನಾಗರಿಕರು"]', '["ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಠಾಣೆಯು ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸಿ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸುತ್ತದೆ."]', 1, '["ಗುರುತಿನ ಪುರಾವೆ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('9a96a561-ca7d-4064-9abe-851025c9c800', 'ENERGY-DEPARTMENT-12', 'e0b8deb9-4426-4525-a8e5-aab3f707df7c', 'Distribution Transformer failure- Rural areas', 'General', 0, '', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '665dc58e-475b-4883-93a4-8761c3bf0063', 'ವಿತರಣಾ ಪರಿವರ್ತಕ ವಿಫಲತೆ – ಗ್ರಾಮೀಣ ಪ್ರದೇಶ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3010');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('7adffb43-8826-4f7a-a4f8-78e714a133e8', 'HOME-DEPARTMENT-9', 'e4118656-e98e-472f-ba77-d686d9788f3b', 'Complaint Registration', 'General', 0, 'This service enables citizens to submit complaints/petitions regarding incidents, grievances, or matters requiring Police intervention through the Seva Sindhu portal. The complaint is forwarded to the concerned Police Station/Police Unit for examination and necessary action.', '["Identity Proof", "Address Proof"]', '["Citizens of India"]', '[]', '["Applicant needs to submit the appication", "Application will be processed by the concerned Police Station and will be disposed by the concerned Police Unit after verifying the facts of the complaint."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'd7e849fd-83ee-4dec-863d-5596b4c09181', 'ದೂರು ದಾಖಲಾತಿಗಾಗಿ ಅರ್ಜಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಈ ಸೇವೆಯ ಮೂಲಕ ನಾಗರಿಕರು ಘಟನೆಗಳು, ಕುಂದುಕೊರತೆಗಳು ಅಥವಾ ಪೊಲೀಸ್ ಇಲಾಖೆಯ ಹಸ್ತಕ್ಷೇಪದ ಅಗತ್ಯವಿರುವ ವಿಷಯಗಳಿಗೆ ಸಂಬಂಧಿಸಿದ ದೂರುಗಳು / ಮನವಿಗಳನ್ನು ಸೇವಾ ಸಿಂಧು ಪೋರ್ಟಲ್ ಮೂಲಕ ಸಲ್ಲಿಸಬಹುದು. ಸಲ್ಲಿಸಿದ ದೂರನ್ನು ಪರಿಶೀಲನೆ ಮತ್ತು ಅಗತ್ಯ ಕ್ರಮ ಕೈಗೊಳ್ಳುವ ಸಲುವಾಗಿ ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಠಾಣೆ / ಪೊಲೀಸ್ ಘಟಕಕ್ಕೆ ರವಾನಿಸಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಭಾರತದ ನಾಗರಿಕರು"]', '["ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಠಾಣೆಯು ಅರ್ಜಿಯನ್ನು ಪ್ರಕ್ರಿಯೆಗೊಳಿಸಿ, ದೂರಿನಲ್ಲಿ ಉಲ್ಲೇಖಿಸಿರುವ ಅಂಶಗಳನ್ನು ಪರಿಶೀಲಿಸಿದ ನಂತರ ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಘಟಕವು ಅರ್ಜಿಯ ಕುರಿತು ಅಂತಿಮ ವಿಲೇವಾರಿ ಕ್ರಮ ಕೈಗೊಳ್ಳುತ್ತದೆ."]', 1, '["ಗುರುತಿನ ಪುರಾವೆ", "ವಿಳಾಸದ ಪುರಾವೆ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('5f3b9421-1ea2-4693-8b65-44bb74b19a0e', 'HOME-DEPARTMENT-8', 'e4118656-e98e-472f-ba77-d686d9788f3b', 'Job / Service Verification', 'General', 20, 'Citizens can apply for this service to get Police antecedent and address verification for job purpose', '["Address Proof", "ID Proof", "Passport size photo", "Reference Letter"]', '["Citizens of India"]', '[]', '["Applicant needs to submit the appication", "Application will be processed by the concerned Police Station", "Dispatch of output certificate by police station to applicant"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'd7e849fd-83ee-4dec-863d-5596b4c09181', 'ಉದ್ಯೋಗ ಪರಿಶೀಲನೆಗಾಗಿ ಅರ್ಜಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಉದ್ಯೋಗದ ಉದ್ದೇಶಕ್ಕಾಗಿ ಪೊಲೀಸ್ ಪೂರ್ವಾಪರ ಮತ್ತು ವಿಳಾಸ ಪರಿಶೀಲನೆ ಪಡೆಯಲು ನಾಗರಿಕರು ಈ ಸೇವೆಗೆ ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು.', NULL, NULL, NULL, NULL, NULL, '["ಭಾರತದ ನಾಗರಿಕರು"]', '["ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಠಾಣೆಯು ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸಿ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸುತ್ತದೆ.", "ಪೊಲೀಸ್ ಠಾಣೆಯು ಔಟ್"]', 1, '["ವಿಳಾಸದ ಪುರಾವೆ", "ಗುರುತಿನ ಪುರಾವೆ", "ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('2bfb2a87-5c9d-4e82-bfa9-2315b9feaa53', 'HOME-DEPARTMENT-7', 'e4118656-e98e-472f-ba77-d686d9788f3b', 'Police Clearance Certificate for going abroad (Visa for studies)/ Police Clearance Certificate for Foreign Nationals', 'General', 20, 'Applicants can apply for this service to get Police Clearance Certificate for Going Abroad (Visa For Studies)', '["Identity Proof", "Address Proof"]', '["Citizens of India"]', '[]', '["Applicant needs to submit the appication", "Application will be processed by the concerned Police Station", "Dispatch of output certificate by the concerned police department to the applicant in case of Regular PCC.", "For Indian & Foreign PCC after Recommended from the COP / SP office it will be forwarded for FRO office for further process and will be sent for Home Department for final approval and it will be dispatched for the applicant after approval."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'd7e849fd-83ee-4dec-863d-5596b4c09181', 'ಪೊಲೀಸ್ ಕ್ಲಿಯರೆನ್ಸ್ ಪ್ರಮಾಣಪತ್ರಕ್ಕಾಗಿ ಅರ್ಜಿ (ವೀಸಾ / ವಲಸೆ / ಪಿಆರ್ / ಗ್ರೀನ್ ಕಾರ್ಡ್ /ಇತರೆ)', NULL, NULL, NULL, NULL, NULL, 1000.00, NULL, 'ವಿದೇಶಕ್ಕೆ ತೆರಳಲು (ವಿದ್ಯಾರ್ಥಿ ವೀಸಾ ಉದ್ದೇಶಕ್ಕಾಗಿ) ಪೊಲೀಸ್ ಕ್ಲಿಯರೆನ್ಸ್ ಪ್ರಮಾಣಪತ್ರ (PCC) ಪಡೆಯಲು ಅರ್ಜಿದಾರರು ಈ ಸೇವೆಗೆ ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು.', NULL, NULL, NULL, NULL, NULL, '["ಭಾರತದ ನಾಗರಿಕರು"]', '["ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಠಾಣೆಯು ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸಿ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸುತ್ತದೆ.", "ಸಾಮಾನ್ಯ ಪೊಲೀಸ್ ಕ್ಲಿಯರೆನ್ಸ್ ಪ್ರಮಾಣಪತ್ರ (Regular PCC) ಪ್ರಕರಣಗಳಲ್ಲಿ: ಸಂಬಂಧಪಟ್ಟ ಪೊಲೀಸ್ ಇಲಾಖೆಯು ಔಟ್"]', 1, '["ಗುರುತಿನ ಪುರಾವೆ", "ವಿಳಾಸದ ಪುರಾವೆ"]', NULL, NULL, NULL);
