INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('793da234-28fc-4320-9206-a6f7a70dd1cf', 'DEPARTMENT-OF-LABOUR-2', '754e71d9-6fb5-4948-9726-3527641d0db8', 'Registration of labourers under Ambedkar Karmika Sahaya Hastha Scheme', 'General', 45, 'Ambedkar Karmika Sahaya Hastha Scheme aims to freely register and issue smart cards to 102 categories of unorganised and traditional workers so that they can get various benefits.', '["Recent passport size photograph. 2) Age Proof. 3)Aadhaar Card. 4)Bank pass book"]', '["This scheme is applicable only to the residents of Karnataka State.2) Age limit of applicant is 18 to 60 years. 3) Should not be an Income Tax payer. 4) Should not to be covered under ESI / EPF Scheme"]', '[]', '["Through online web portal"]', NULL, NULL, 'https://ambedkarsahayahasta.karnataka.gov.in/api/IAccount/Login', true, '2026-10-30 16:55:56.458552+00', '112a135c-3258-4069-ac38-23616ab5a51a', 'ಅಂಬೇಡ್ಕರ್ ಕಾರ್ಮಿಕ ಸಹಾಯ ಹಸ್ತ ಯೋಜನೆಯಡಿ ಕಾರ್ಮಿಕರ ನೋಂದಣಿ', NULL, NULL, NULL, NULL, NULL, 0.00, NULL, 'ಈ ಯೋಜನೆಯಡಿ ಅಸಂಘಟಿತ ವಲಯದಡಿ ಸೇವೆ ಸಲ್ಲಿಸುತ್ತಿರುವ ಎಲ್ಲಾ ವರ್ಗಗಳ ಕಾರ್ಮಿಕರು ಮತ್ತು ಹಿಂದುಳಿದ ವರ್ಗಗಳ ಪ್ರವರ್ಗ-1, 2ಎ, 3ಎ ಮತ್ತು 3ಬಿಗೆ ಸೇರಿದ ಪಾರಂಪರಿಕ ವೃತ್ತಿಯಲ್ಲಿ ತೊಡಗಿರುವ ಕಾರ್ಮಿಕರು ಹಾಗೂ ಹಿಂದುಳಿದ ವರ್ಗಗಳ ಅಲೆಮಾರಿ ಹಾಗೂ ಅರೆಅಲೆಮಾರಿ ಪಂಗಡದ ಕುಲಕಸುಬಿನಲ್ಲಿ ತೊಡಗಿರುವ ಕಾರ್ಮಿಕರು ಸೇರಿದಂತೆ ಒಟ್ಟು 102 ವರ್ಗಗಳ ಅಸಂಘಟಿತ ಕಾರ್ಮಿಕರನ್ನು ಉಚಿತವಾಗಿ ನೋಂದಾಯಿಸಿ ಸೌಲಭ್ಯಗಳನ್ನೊಳಗೊಂಡ ಸ್ಮಾರ್ಟ್ಕಾರ್ಡ್ ನೀಡಲಾಗುತ್ತಿದ್ದು, ಸದರಿ ಕಾರ್ಮಿಕರು ಸುಮಾರು 35 ಲಕ್ಷ ಇರುವುದಾಗಿ ಅಂದಾಜಿಸಲಾಗಿದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಈ ಯೋಜನೆಯು ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಗಳಿಗೆ ಮಾತ್ರ ಅನ್ವಯ. 2) ಅರ್ಜಿದಾರರ ವಯೋಮಿತಿ 18 ರಿಂದ 60 ವರ್ಷಗಳು. 3) ಆದಾಯ ತೆರಿಗೆ ಪಾವತಿದಾರರಾಗಿರಬಾರದು. 4) ಇ.ಎಸ್.ಐ ಮತ್ತು ಇ.ಪಿ.ಎಫ್ ಸೌಲಭ್ಯ ಹೊಂದಿರಬಾರದು."]', '["ಅಧಿಕೃತ ಆನ್"]', 1, '["ಪಾಸ್ಪೋರ್ಟ್ ಅಳತೆಯ ಇತ್ತೀಚಿನ ಭಾವಚಿತ್ರ. 2) ವಯಸ್ಸಿನ ಪ್ರಮಾಣ ಪತ್ರ. 3) ಆಧಾರ್ ಕಾರ್ಡ್. 4) ಬ್ಯಾಂಕ್ ಪಾಸ್ ಪುಸ್ತಕ."]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('411f6b07-859e-458c-be7b-0c2fa8c33edd', 'DEPARTMENT-OF-LABOUR-1', '754e71d9-6fb5-4948-9726-3527641d0db8', 'Registration of Gig Workers under Karnataka State Gig Workers Insurance Scheme', 'General', 45, 'Karnataka State Gig Workers Insurance Scheme is Insurance benefit for gig workers working in the state of Karnataka and Insurance benefit available for on duty as well as off duty accidents.', '["Aadhaar Number. 2) Identity Card/Pay slip/Bank Statement issued by establishments. 3) E-Shram Registration Number."]', '["18 to 60 years of age. 2) Should not be an income tax payer. 3)Should not be a beneficiary of EPF and ESI. 4) Engaged as gig worker (Delivery person) in Karnataka only."]', '[]', '["Through Seva One online web portal"]', NULL, NULL, 'https://sevaone.karnataka.gov.in/services', true, '2026-10-30 16:55:56.458552+00', '112a135c-3258-4069-ac38-23616ab5a51a', 'ಕರ್ನಾಟಕ ರಾಜ್ಯ ಗಿಗ್ ಕಾರ್ಮಿಕರ ವಿಮಾ ಯೋಜನೆಯಡಿ ಗಿಗ್ ಕಾರ್ಮಿಕರ ನೋಂದಣಿ', NULL, NULL, NULL, NULL, NULL, 0.00, NULL, 'ಕರ್ನಾಟಕ ರಾಜ್ಯದಲ್ಲಿ ಸ್ವಿಗ್ಗಿ, ಜೊಮಾಟೋಗಳಂತಹ ಸಂಸ್ಥೆಗಳಲ್ಲಿ ಫುಡ್', NULL, NULL, NULL, NULL, NULL, '["18 ರಿಂದ 60 ವಯೋಮಾನದವರು. 2)ಆದಾಯ ತೆರಿಗೆ ಪಾವತಿದಾರರಾಗಿರಬಾರದು. 3) ಭವಿಷ್ಯನಿಧಿ ಹಾಗೂ ಇ.ಎಸ್.ಐ ಫಲಾನುಭವಿಯಾಗಿರಬಾರದು. 4) ಕರ್ನಾಟಕದಲ್ಲಿ ಗಿಗ್ ವೃತ್ತಿ (ಡೆಲಿವರಿ ಕಾರ್ಯ) ನಿರ್ವಹಿಸುತ್ತಿರುವವರಿಗೆ ಮಾತ್ರ."]', '["Seva One ಅಧಿಕೃತ ಆನ್"]', 1, '["ಆಧಾರ್ ಸಂಖ್ಯೆ. 2)", "ವೃತ್ತಿ ನಿರ್ವಹಿಸುತ್ತಿರುವ ಸಂಸ್ಥೆಗಳು ವಿತರಿಸಿದ ಗುರುತಿನ ಚೀಟಿ. 3) ಇ-ಶ್ರಮ್ ನೋಂದಣಿ ಸಂಖ್ಯೆ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('de12f71c-f329-4abf-8cce-d94ce66e0d86', 'SCHOOL-EDUCATION-DEP-4', 'bd235dfc-9efa-4507-aaf0-f78a93e05e6a', 'Study Certificate', 'General', 15, '', '["Request Letter in the Prescribed Format with Accurate Details"]', '["The applicant must be a student of the institution."]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '8e51c8b4-3e79-4ebb-b323-6915d791588a', 'ವ್ಯಾಸಂಗ ಪ್ರಮಾಣ ಪತ್ರ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["ಅರ್ಜಿದಾರರು ಸಂಬಂಧಿತ ಶಿಕ್ಷಣ ಸಂಸ್ಥೆಯ ವಿದ್ಯಾರ್ಥಿಯಾಗಿರಬೇಕು."]', '[]', 1, '["ನಿಗದಿತ ನಮೂನೆಯಲ್ಲಿ ನಿಖರವಾದ ವರಗಳೊಂದಿಗೆ ಸಲ್ಲಿಸಲಾದ ಮನವಿ ಪತ್ರ"]', NULL, NULL, NULL);
