INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('f55057b7-678a-498f-8a4c-788ea3809ede', 'DEPARTMENT-OF-ELECTR-36', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Skilling Curriculum', 'General', 180, 'GoK will fund the cost of developing industry oriented future skills courses, master faculty training and promote adoption of these courses in State Government universities / affiliated colleges in the State', '["Covering letter", "Full Project Proposal along with all annexures, covering sections as outlined in section-8 of this EOI. (signed and stamped by Authorized signatory)", "Presentation for Evaluation Committee Meeting – add photographs in PPT (if already built).", "Registration Certificate of the applicant", "Know Your Customer (KYC) documents of applicant organization. KYC means Identity & Address proof of the organization which includes Company PAN Card, Electricity Bill, etc.)", "Self-Declaration of Applicant on Company letterhead, signed by MD/CEO/Company Secretary, as all Statutory Norms are compiled by the Applicant till date."]', '["Applicable to any State government universities or affiliated or autonomous colleges in the State and must be a recognized academic institution", "The proposed curriculum must focus on areas aligned with industry talent needs and emerging technologies such as AI/ML, cybersecurity, data analytics, product engineering, etc.", "The applicant must demonstrate ability to invest in curriculum development and minimum 50 hours of course delivery.", "The applicant must submit a comprehensive proposal detailing curriculum structure, delivery mode (online/offline/hybrid), number of beneficiaries, industry alignment, and expected outcomes.", "Applicant should not be debarred by any procurement entity in Central/State Government/Departments/Organizations/Institutions or any state government agency for engaging in corrupt, unfair, or fraudulent practices.", "The curriculum should be designed for roll-out within 6 months from the date of Government approval."]', '[]', '["The applicant Company should be registered with KITS under GCC Policy 2024-29", "Company should submit the incentive application along with supporting documents as prescribed in the OPG."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಕೌಶಲ್ಯಾಭಿವೃದ್ಧಿ ಪಠ್ಯಕ್ರಮ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಉದ್ಯಮ-ಆಧಾರಿತ ಭವಿಷ್ಯದ ಕೌಶಲ್ಯ ಕೋರ್ಸ್', NULL, NULL, NULL, NULL, NULL, '["ರಾಜ್ಯದ ಯಾವುದೇ ರಾಜ್ಯ ಸರ್ಕಾರದ ವಿಶ್ವವಿದ್ಯಾಲಯಗಳು ಅಥವಾ ರಾಜ್ಯದಲ್ಲಿ ಮಾನ್ಯತೆ ಪಡೆದ ಸಂಯೋಜಿತ (Affiliated) ಅಥವಾ ಸ್ವಾಯತ್ತ (Autonomous) ಕಾಲೇಜುಗಳಿಗೆ ಈ ಪ್ರೋತ್ಸಾಹಧನ ಅನ್ವಯವಾಗುತ್ತದೆ.", "ಪ್ರಸ್ತಾವಿತ ಪಠ್ಯಕ್ರಮವು ಕೈಗಾರಿಕಾ ವಲಯದ ಕೌಶಲ್ಯ ಅಗತ್ಯತೆಗಳು ಹಾಗೂ ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ/ಯಂತ್ರ ಕಲಿಕೆ (AI/ML), ಸೈಬರ್ ಭದ್ರತೆ, ದತ್ತಾಂಶ ವಿಶ್ಲೇಷಣೆ (Data Analytics), ಉತ್ಪನ್ನ ಎಂಜಿನಿಯರಿಂಗ್ (Product Engineering) ಮುಂತಾದ ಉದಯೋನ್ಮುಖ ತಂತ್ರಜ್ಞಾನ ಕ್ಷೇತ್ರಗಳಿಗೆ ಹೊಂದಿಕೊಂಡಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಪಠ್ಯಕ್ರಮ ಅಭಿವೃದ್ಧಿಯಲ್ಲಿ ಹೂಡಿಕೆ ಮಾಡುವ ಸಾಮರ್ಥ್ಯವನ್ನು ಹೊಂದಿರಬೇಕು ಹಾಗೂ ಕನಿಷ್ಠ 50 ಗಂಟೆಗಳ ತರಬೇತಿ/ಪಠ್ಯಕ್ರಮ ಬೋಧನೆಯನ್ನು ನೀಡಲು ಸಮರ್ಥರಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಪಠ್ಯಕ್ರಮದ ರಚನೆ, ಬೋಧನಾ ವಿಧಾನ (ಆನ್"]', '["ಅರ್ಜಿದಾರ ಕಂಪನಿಯು GCC ನೀತಿಯಡಿ ಕರ್ನಾಟಕ ನವೋದ್ಯಮ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ಯಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["ಅರ್ಜಿದಾರರ ಸಂಸ್ಥೆಯ ಅಧಿಕೃತ ಲೆಟರ್"]', NULL, NULL, '3354');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('bf4036ee-9aef-4fd6-a182-ba56a24853a9', 'DEPARTMENT-OF-ELECTR-37', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Joint Research', 'General', 180, 'GoK aims to fund applied research in academic programs to support the industrial application of academic research.', '["Covering letter", "Completed Full Project Proposal with all annexures, covering all sections as outlined in section-8 of this EOI (signed and stamped by Authorized signatory)", "Presentation for Evaluation Committee Meeting – add photographs in PPT (if already built).", "Company Registration Certificate of the applicant", "MOU or agreement between the academic institution and the GCC to carry out joint research.", "Audited Annual Reports (for eg. Income Tax Return, Balance Sheet, and Profit & Loss Account & Auditor’s Reports) for the last three Financial Years of the GCC.", "Know Your Customer (KYC) documents of applicant organization. KYC means Identity & Address proof of the organization which includes Company PAN Card, Electricity Bill, etc.)", "Self-Declaration of Applicant on Company letterhead, signed by MD/CEO/Company Secretary, as all Statutory Norms are compiled by the Applicant till date."]', '["Any State Government Universities and affiliated colleges registered in the state are eligible to apply for incentives in partnership with a GCC in the state.", "Any new or existing GCC’s in the state can act as participating entity in the joint research along with the academic institution.", "The research project must be focused on applied industrial innovation aligned with sectors like AI, deep tech, semiconductors, sustainability, cybersecurity, etc.", "The GCC must contribute at least 25% of the total approved project cost, with the remainder being funded by the academic institution.", "The academic institution/GCC must be recognized by the State Government and have relevant research infrastructure and capacity.", "The applicant must submit a comprehensive joint research proposal outlining scope, milestones, roles and responsibilities, and impact.", "Neither the GCC nor the academic institution should be debarred or blacklisted by any Central/State Government agency for indulging in corrupt or fraudulent practices or for indulging in unfair trade practices for any reasons whatsoever at the time of application process."]', '[]', '["The applicant Company should be registered with KITS under GCC Policy 2024-29", "Company should submit the incentive application along with supporting documents as prescribed in the OPG."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಜಂಟಿ ಸಂಶೋಧನೆ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಶೈಕ್ಷಣಿಕ ಸಂಶೋಧನೆಯನ್ನು ಉದ್ಯಮಗಳಲ್ಲಿ ಅಳವಡಿಸಿಕೊಳ್ಳುವುದಕ್ಕೆ ಬೆಂಬಲ ನೀಡಲು, ಶೈಕ್ಷಣಿಕ ಕಾರ್ಯಕ್ರಮಗಳಲ್ಲಿ ಅನ್ವಯಿಕ ಸಂಶೋಧನೆಗೆ (Applied research) ಧನಸಹಾಯ ನೀಡಲು ಕರ್ನಾಟಕ ಸರ್ಕಾರವು ಗುರಿ ಹೊಂದಿದೆ.', NULL, NULL, NULL, NULL, NULL, '["ರಾಜ್ಯದಲ್ಲಿ ನೋಂದಾಯಿತ ಯಾವುದೇ ರಾಜ್ಯ ಸರ್ಕಾರದ ವಿಶ್ವವಿದ್ಯಾಲಯಗಳು ಮತ್ತು ಅವುಗಳಿಗೆ ಸಂಯೋಜಿತ ಕಾಲೇಜುಗಳು, ರಾಜ್ಯದಲ್ಲಿರುವ ಜಿಸಿಸಿ (GCC) ಸಂಸ್ಥೆಯೊಂದಿಗೆ ಸಹಭಾಗಿತ್ವದಲ್ಲಿ ಪ್ರೋತ್ಸಾಹಧನಕ್ಕಾಗಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಲು ಅರ್ಹವಾಗಿರುತ್ತವೆ.", "ರಾಜ್ಯದಲ್ಲಿರುವ ಯಾವುದೇ ಹೊಸ ಅಥವಾ ಈಗಾಗಲೇ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿರುವ ಜಿಸಿಸಿ (GCC) ಸಂಸ್ಥೆಗಳು, ಶೈಕ್ಷಣಿಕ ಸಂಸ್ಥೆಯೊಂದಿಗೆ ಜಂಟಿ ಸಂಶೋಧನಾ ಯೋಜನೆಯಲ್ಲಿ ಭಾಗವಹಿಸುವ ಸಂಸ್ಥೆಯಾಗಿ ಕಾರ್ಯನಿರ್ವಹಿಸಬಹುದು.", "ಸಂಶೋಧನಾ ಯೋಜನೆಯು ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ (AI), ಡೀಪ್ ಟೆಕ್, ಅರೆವಾಹಕ (Semiconductors), ಸುಸ್ಥಿರತೆ (Sustainability), ಸೈಬರ್ ಭದ್ರತೆ (Cybersecurity) ಸೇರಿದಂತೆ ಕೈಗಾರಿಕಾ ನವೀನತೆಗೆ ಸಂಬಂಧಿಸಿದ ಅನ್ವಯಿಕ ಸಂಶೋಧನೆಗೆ ಕೇಂದ್ರೀಕೃತವಾಗಿರಬೇಕು.", "ಒಟ್ಟು ಅನುಮೋದಿತ ಯೋಜನಾ ವೆಚ್ಚದ ಕನಿಷ್ಠ 25% ಅನ್ನು ಜಿಸಿಸಿ (GCC) ಸಂಸ್ಥೆಯು ಭರಿಸಬೇಕು. ಉಳಿದ ಮೊತ್ತವನ್ನು ಶೈಕ್ಷಣಿಕ ಸಂಸ್ಥೆಯು ಭರಿಸಬೇಕು.", "ಶೈಕ್ಷಣಿಕ ಸಂಸ್ಥೆ/ಜಿಸಿಸಿ (GCC) ಸಂಸ್ಥೆಯು ರಾಜ್ಯ ಸರ್ಕಾರದಿಂದ ಮಾನ್ಯತೆ ಪಡೆದಿರಬೇಕು ಹಾಗೂ ಸಂಬಂಧಿತ ಸಂಶೋಧನಾ ಮೂಲಸೌಕರ್ಯ ಮತ್ತು ಸಾಮರ್ಥ್ಯವನ್ನು ಹೊಂದಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಸಂಶೋಧನೆಯ ವ್ಯಾಪ್ತಿ, ಮೈಲಿಗಲ್ಲುಗಳು, ಪಾತ್ರಗಳು ಮತ್ತು ಜವಾಬ್ದಾರಿಗಳು ಹಾಗೂ ಯೋಜನೆಯ ನಿರೀಕ್ಷಿತ ಪರಿಣಾಮಗಳನ್ನು ಒಳಗೊಂಡ ಸಮಗ್ರ ಜಂಟಿ ಸಂಶೋಧನಾ ಪ್ರಸ್ತಾವನೆಯನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಅರ್ಜಿ ಸಲ್ಲಿಸುವ ವೇಳೆಯಲ್ಲಿ ಜಿಸಿಸಿ (GCC) ಸಂಸ್ಥೆ ಅಥವಾ ಶೈಕ್ಷಣಿಕ ಸಂಸ್ಥೆಯು ಯಾವುದೇ ಕೇಂದ್ರ ಅಥವಾ ರಾಜ್ಯ ಸರ್ಕಾರದ ಸಂಸ್ಥೆಯಿಂದ ಭ್ರಷ್ಟ ಅಥವಾ ವಂಚನಾತ್ಮಕ ಚಟುವಟಿಕೆಗಳಲ್ಲಿ ಅಥವಾ ಯಾವುದೇ ರೀತಿಯ ಅನ್ಯಾಯಯುತ ವ್ಯಾಪಾರ ಪದ್ಧತಿಗಳಲ್ಲಿ ತೊಡಗಿರುವ ಕಾರಣಕ್ಕಾಗಿ ಕಪ್ಪುಪಟ್ಟಿಗೆ ಸೇರಿಸಲ್ಪಟ್ಟಿರಬಾರದು ಅಥವಾ ನಿರ್ಬಂಧಿಸಲ್ಪಟ್ಟಿರಬಾರದು."]', '["ಅರ್ಜಿದಾರ ಕಂಪನಿಯು GCC ನೀತಿಯಡಿ ಕರ್ನಾಟಕ ನವೋದ್ಯಮ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ಯಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["ಅರ್ಜಿದಾರ ಸಂಸ್ಥೆಯಿಂದ ಸಲ್ಲಿಸಲಾದ ಮುಚ್ಚಳಿಕೆ ಪತ್ರ (Covering Letter).", "ಈ ಆಸಕ್ತಿ ವ್ಯಕ್ತಪಡಿಸುವಿಕೆ (EOI) ದಾಖಲೆಯ ವಿಭಾಗ-8ರಲ್ಲಿ ಸೂಚಿಸಿರುವ ಎಲ್ಲಾ ಅಂಶಗಳನ್ನು ಒಳಗೊಂಡಂತೆ, ಎಲ್ಲಾ ಅನುಬಂಧಗಳೊಂದಿಗೆ ಪೂರ್ಣಗೊಂಡ ಯೋಜನಾ ಪ್ರಸ್ತಾವನೆ (ಅಧಿಕೃತ ಸಹಿದಾರರಿಂದ ಸಹಿ ಹಾಗೂ ಮುದ್ರೆಯೊಂದಿಗೆ).", "ಮೌಲ್ಯಮಾಪನ ಸಮಿತಿ ಸಭೆಗಾಗಿ ಪ್ರಸ್ತುತಿ (Presentation). ಯೋಜನೆಯು ಈಗಾಗಲೇ ನಿರ್ಮಾಣಗೊಂಡಿದ್ದಲ್ಲಿ, ಸಂಬಂಧಿತ ಛಾಯಾಚಿತ್ರಗಳನ್ನು ಪ್ರಸ್ತುತಿಯಲ್ಲಿ ಸೇರಿಸಬೇಕು.", "ಅರ್ಜಿದಾರ ಸಂಸ್ಥೆಯ ಕಂಪನಿ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರ.", "ಜಂಟಿ ಸಂಶೋಧನಾ ಕಾರ್ಯವನ್ನು ಕೈಗೊಳ್ಳಲು ಶೈಕ್ಷಣಿಕ ಸಂಸ್ಥೆ ಮತ್ತು ಜಿಸಿಸಿ (GCC) ಸಂಸ್ಥೆಯ ನಡುವಿನ ತಿಳುವಳಿಕೆ ಒಪ್ಪಂದ (MoU) ಅಥವಾ ಒಪ್ಪಂದದ ಪ್ರತಿ.", "ಜಿಸಿಸಿ (GCC) ಸಂಸ್ಥೆಯ ಕಳೆದ ಮೂರು ಹಣಕಾಸು ವರ್ಷಗಳ ಲೆಕ್ಕಪರಿಶೋಧಿತ ವಾರ್ಷಿಕ ವರದಿಗಳು (ಉದಾಹರಣೆಗೆ ಆದಾಯ ತೆರಿಗೆ ರಿಟರ್ನ್, ಆಯವ್ಯಯ ಪತ್ರ (Balance Sheet), ಲಾಭ-ನಷ್ಟ ಖಾತೆ ಹಾಗೂ ಲೆಕ್ಕಪರಿಶೋಧಕರ ವರದಿಗಳು).", "ಅರ್ಜಿದಾರ ಸಂಸ್ಥೆಯ ‘ನಿಮ್ಮ ಗ್ರಾಹಕರನ್ನು ತಿಳಿದುಕೊಳ್ಳಿ’ (KYC) ದಾಖಲೆಗಳು. (ಸಂಸ್ಥೆಯ ಗುರುತು ಹಾಗೂ ವಿಳಾಸದ ಪುರಾವೆಗಳಾದ ಕಂಪನಿ ಪ್ಯಾನ್ ಕಾರ್ಡ್, ವಿದ್ಯುತ್ ಬಿಲ್ ಇತ್ಯಾದಿಗಳನ್ನು ಒಳಗೊಂಡಿರಬೇಕು.)", "ಅರ್ಜಿದಾರ ಸಂಸ್ಥೆಯ ಅಧಿಕೃತ ಲೆಟರ್"]', NULL, NULL, '3359');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('4cbbc606-8117-4976-adaf-68c3d8772102', 'HORTICULTURE-AND-SER-4', '7fc7181a-5bee-4a83-b61b-bd3c78da95b2', 'Technical information related to Mulberry Cultivation and Silkworm rearing', 'General', 0, 'Technical Information related to Sericulture Department', '["Application form with Details"]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '2486ba28-e160-4a76-8df1-ce8e643a84c9', 'ಹಿಪ್ಪುನೇರಳೆ ಬೇಸಾಯ ಹಾಗೂ ರೇಷ್ಮೆ ಹುಳು ಸಾಕಾಣಿಕೆಗೆ ಸಂಬಂಧಿಸಿದ ತಾಂತ್ರಿಕ ಮಾಹಿತಿ ನೀಡುವುದು', 'Technical information related to Mulberry Cultivation and Silkworm rearing', NULL, NULL, NULL, NULL, NULL, NULL, 'ರೇಷ್ಮೆ ಕೃಷಿಗೆ ಸಂಬಂಧಿಸಿದಂತೆ ತಾಂತ್ರಿಕ ಮಾಹಿತಿ', NULL, NULL, NULL, true, 'Yes', '[]', '[]', 1, '["1 ವಿವರಗಳೊಂದಿಗೆ ಅರ್ಜಿ ನಮೂನೆ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('142d155d-c971-47f6-aae1-b6304f256623', 'DEPARTMENT-OF-ELECTR-38', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Innovation Challenge', 'General', 180, 'GoK shall promote and support innovation across the State through structured Innovation Challenges. This initiative shall empower GCCs with access to government departments for the implementation of innovative solutions that address critical public service challenges and societal issues.', '["Covering letter", "Full Project Proposal along with all annexures, covering all the sections as outlined in section – 8 of this EOI (Proposal Submission Guidelines) (signed and stamped by Authorized signatory)", "Presentation for Evaluation Committee Meeting – add photographs in PPT (if already built).", "Company Registration Certificate of the applicant", "Audited Annual Reports (for eg. Income Tax Return, Balance Sheet, and Profit & Loss Account & Auditor’s Reports) for the last three Financial Years.", "Know Your Customer (KYC) documents of applicant organization. KYC means Identity & Address proof of the organization which includes Company PAN Card, Electricity Bill, etc.)", "Self-Declaration of Applicant on Company letterhead, signed by MD/CEO/Company Secretary, as all Statutory Norms are compiled by the Applicant till date.", "Share Holding Pattern of the Company (highlighting the Foreign Investment, if any)", "CV of the proposed CEO / head of the innovation lab and key leadership team"]', '["Applicable to GCC’s set up across the State.", "Applicant should have approval from GCC parent organization leadership for the proposed budget and Innovation Lab project.", "Applicant GCC should not be debarred by any procurement entity in Central/State Government/Department/Organization/ Institution or any State government applicant for indulging in corrupt or fraudulent practices or for indulging in unfair trade practices for any reasons whatsoever at the time of selection process.", "The Technical Staff/manpower/Faculty should have experience in innovation programs.", "The company, mandatorily, must have a functional prototype / “minimum viable product” ready, which can be put through a field test / pilot in liaison with GOK."]', '[]', '["The applicant Company should be registered with KITS under GCC Policy 2024-29", "Company should submit the incentive application along with supporting documents as prescribed in the OPG."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ನವೀನತಾ ಸವಾಲು', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಕರ್ನಾಟಕ ಸರ್ಕಾರವು ರಚನಾತ್ಮಕ ''ಇನೋವೇಶನ್ ಚಾಲೆಂಜ್', NULL, NULL, NULL, NULL, NULL, '["ರಾಜ್ಯದಲ್ಲಿ ಸ್ಥಾಪಿತವಾಗಿರುವ ಜಾಗತಿಕ ಸಾಮರ್ಥ್ಯ ಕೇಂದ್ರಗಳು (GCCs) ಈ ಪ್ರೋತ್ಸಾಹಧನಕ್ಕೆ ಅರ್ಜಿ ಸಲ್ಲಿಸಲು ಅರ್ಹವಾಗಿರುತ್ತವೆ.", "ಪ್ರಸ್ತಾವಿತ ಬಜೆಟ್ ಹಾಗೂ ನವೀನತೆ ಪ್ರಯೋಗಾಲಯ (Innovation Lab) ಯೋಜನೆಗೆ ಜಿಸಿಸಿ (GCC) ಮೂಲ ಸಂಸ್ಥೆಯ (Parent Organization) ಆಡಳಿತ ಮಂಡಳಿಯಿಂದ ಅನುಮೋದನೆ ಪಡೆದಿರಬೇಕು.", "ಆಯ್ಕೆ ಪ್ರಕ್ರಿಯೆಯ ಸಂದರ್ಭದಲ್ಲಿ, ಅರ್ಜಿದಾರ ಜಿಸಿಸಿ (GCC) ಸಂಸ್ಥೆಯು ಯಾವುದೇ ಕೇಂದ್ರ ಅಥವಾ ರಾಜ್ಯ ಸರ್ಕಾರ / ಇಲಾಖೆ / ಸಂಸ್ಥೆ / ಸಂಘಟನೆಗಳಿಂದ ಭ್ರಷ್ಟ ಅಥವಾ ವಂಚನಾತ್ಮಕ ಚಟುವಟಿಕೆಗಳಲ್ಲಿ ಅಥವಾ ಯಾವುದೇ ರೀತಿಯ ಅನ್ಯಾಯಯುತ ವ್ಯಾಪಾರ ಪದ್ಧತಿಗಳಲ್ಲಿ ತೊಡಗಿರುವ ಕಾರಣಕ್ಕಾಗಿ ನಿರ್ಬಂಧಿತ (Debarred) ಆಗಿರಬಾರದು.", "ತಾಂತ್ರಿಕ ಸಿಬ್ಬಂದಿ / ಮಾನವ ಸಂಪನ್ಮೂಲ / ಅಧ್ಯಾಪಕರು ನವೀನತಾ ಕಾರ್ಯಕ್ರಮಗಳಲ್ಲಿ ಅನುಭವ ಹೊಂದಿರಬೇಕು.", "ಕಂಪನಿಯು ಕಡ್ಡಾಯವಾಗಿ ಕಾರ್ಯನಿರ್ವಹಣೆಗೆ ಯೋಗ್ಯವಾದ ಮಾದರಿ (Functional Prototype) ಅಥವಾ ಕನಿಷ್ಠ ಕಾರ್ಯಸಾಧ್ಯ ಉತ್ಪನ್ನ (Minimum Viable Product - MVP) ಹೊಂದಿರಬೇಕು. ಇದನ್ನು ಕರ್ನಾಟಕ ಸರ್ಕಾರದ (GoK) ಸಹಯೋಗದಲ್ಲಿ ಕ್ಷೇತ್ರ ಪರೀಕ್ಷೆ (Field Test) ಅಥವಾ ಪ್ರಾಯೋಗಿಕ ಅನುಷ್ಠಾನ (Pilot) ನಡೆಸಲು ಸಿದ್ಧವಾಗಿರಬೇಕು."]', '["ಅರ್ಜಿದಾರ ಕಂಪನಿಯು GCC ನೀತಿಯಡಿ ಕರ್ನಾಟಕ ನವೋದ್ಯಮ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ಯಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["ಅರ್ಜಿದಾರ ಸಂಸ್ಥೆಯಿಂದ ಸಲ್ಲಿಸಲಾದ ಮುಚ್ಚಳಿಕೆ ಪತ್ರ (Covering Letter).", "ಈ ಆಸಕ್ತಿ ವ್ಯಕ್ತಪಡಿಸುವಿಕೆ (EOI) ದಾಖಲೆಯ ವಿಭಾಗ–8 (ಯೋಜನಾ ಪ್ರಸ್ತಾವನೆ ಸಲ್ಲಿಕೆ ಮಾರ್ಗಸೂಚಿಗಳು) ರಲ್ಲಿ ಸೂಚಿಸಿರುವ ಎಲ್ಲಾ ಅಂಶಗಳನ್ನು ಒಳಗೊಂಡಂತೆ, ಎಲ್ಲಾ ಅನುಬಂಧಗಳೊಂದಿಗೆ ಪೂರ್ಣಗೊಂಡ ಯೋಜನಾ ಪ್ರಸ್ತಾವನೆ (ಅಧಿಕೃತ ಸಹಿದಾರರ ಸಹಿ ಹಾಗೂ ಮುದ್ರೆಯೊಂದಿಗೆ).", "ಮೌಲ್ಯಮಾಪನ ಸಮಿತಿ ಸಭೆಗಾಗಿ ಪ್ರಸ್ತುತಿ (Presentation). ಯೋಜನೆಯು ಈಗಾಗಲೇ ಸ್ಥಾಪಿತವಾಗಿದ್ದಲ್ಲಿ, ಸಂಬಂಧಿತ ಛಾಯಾಚಿತ್ರಗಳನ್ನು ಪ್ರಸ್ತುತಿಯಲ್ಲಿ ಸೇರಿಸಬೇಕು.", "ಅರ್ಜಿದಾರ ಸಂಸ್ಥೆಯ ಕಂಪನಿ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರ.", "ಕಳೆದ ಮೂರು ಹಣಕಾಸು ವರ್ಷಗಳ ಲೆಕ್ಕಪರಿಶೋಧಿತ ವಾರ್ಷಿಕ ವರದಿಗಳು (ಉದಾಹರಣೆಗೆ ಆದಾಯ ತೆರಿಗೆ ರಿಟರ್ನ್, ಆಯವ್ಯಯ ಪತ್ರ (Balance Sheet), ಲಾಭ-ನಷ್ಟ ಖಾತೆ ಹಾಗೂ ಲೆಕ್ಕಪರಿಶೋಧಕರ ವರದಿಗಳು).", "ಅರ್ಜಿದಾರ ಸಂಸ್ಥೆಯ ‘ನಿಮ್ಮ ಗ್ರಾಹಕರನ್ನು ತಿಳಿದುಕೊಳ್ಳಿ’ (KYC) ದಾಖಲೆಗಳು. (ಸಂಸ್ಥೆಯ ಗುರುತು ಮತ್ತು ವಿಳಾಸದ ಪುರಾವೆಗಳಾದ ಕಂಪನಿ ಪ್ಯಾನ್ ಕಾರ್ಡ್, ವಿದ್ಯುತ್ ಬಿಲ್ ಇತ್ಯಾದಿಗಳನ್ನು ಒಳಗೊಂಡಿರಬೇಕು.)", "ಅರ್ಜಿದಾರ ಸಂಸ್ಥೆಯ ಅಧಿಕೃತ ಲೆಟರ್"]', NULL, NULL, '3362');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('59a0866f-6bab-4371-897e-2ba4ad2b4f7f', 'DEPARTMENT-OF-ELECTR-39', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'GCC amendment', 'General', 0, '', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3401');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('1111b69b-9e99-4b9d-a548-e535848523ea', 'DEPARTMENT-OF-ELECTR-40', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Proposal Based Incentives', 'General', 0, '', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3402');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('8af665d6-e557-48d9-b94f-93c3f793d038', 'THE-DEPARTMENT-OF-FO-7', '98c19fd4-7019-42a5-9af1-39cd53b9d099', 'Renewal Manufacture Licence', 'General', 7, 'Renewal Of Manufacture Licence – Application for renewing an existing manufacturer licence to continue manufacturing activities legally without interruption.', '["This service has been enabled for automatic renewal. Therefore, applicants only need to submit a recent photograph and pay the prescribed fee. No other documents are required."]', '["As per Govt Notification No: AaNaSa 223 EeBaTha 19 (e-office) Dated: 10-12-2020 available in website"]', '[]', '["Applicant need to register in E-mapan > Applicant Need to Fill the application >", "Applicant need to upload the Required Documents>", "Applicant has to make Payment >", "Applicant has to make E-Sign>", "Applicant will Submit the application", "and Should take the approval from department"]', NULL, NULL, 'https://emapan.karnataka.gov.in/Homepage_Sevaone.aspx??DepartmentID=14&ServiceID=3006&SevaOneUserID=<<sevaOneUserID>>&Token=<<token>>', true, '2026-10-30 16:55:56.458552+00', 'ef8e63a7-734d-4bc0-91ff-71ba8aa95423', 'ತೂಕ, ಅಳತೆ, ತೂಕ ಮತ್ತು ಅಳತೆ ಸಾಧನಗಳ ತಯಾರಕರ ರಾಜ್ಯವ್ಯಾಪ್ತಿ ಪರವಾನಗಿಗಳ ನವೀಕರಣ.', 'Renewal Manufacture Licence – Renewal of an existing manufacturer licence.', NULL, 'State', NULL, NULL, NULL, NULL, 'ತಯಾರಿಕಾ ಪರವಾನಗಿ ನವೀಕರಣ – ಕಾನೂನುಬದ್ಧವಾಗಿ ಯಾವುದೇ ಅಡಚಣೆ ಇಲ್ಲದೆ ತಯಾರಿಕಾ ಚಟುವಟಿಕೆಗಳನ್ನು ಮುಂದುವರಿಸಲು ಈಗಿರುವ ತೂಕ, ಅಳತೆ, ತೂಕ ಮತ್ತು ಅಳತೆ ಸಾಧನಗಳ ತಯಾರಕರ ರಾಜ್ಯವ್ಯಾಪ್ತಿ ಪರವಾನಗಿಯನ್ನು ನವೀಕರಿಸುವ ಅರ್ಜಿ.', NULL, NULL, NULL, true, 'Yes', '["ಸರ್ಕಾರದ ಅಧಿಸೂಚನೆ ಸಂಖ್ಯೆ: ಆನಾಸ 223 ಇಭತ 19 (ಇ-ಆಫೀಸ್) ದಿನಾಂಕ:10-12-2020 ರಲ್ಲಿ ತಿಳಿಸಿರುವ ಕಾರ್ಯವಿಧಾನದಂತೆ ವೆಬ್"]', '["ಅರ್ಜಿದಾರರು ಇ-ಮಾಪನ್ (E-Mapan) ಪೋರ್ಟಲ್"]', 1, '["ಈ ಸೇವೆಯನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ನವೀಕರಿಸುವ ವ್ಯವಸ್ಥೆ ಮಾಡಲಾಗಿದೆ. ಆದ್ದರಿಂದ, ಇತ್ತೀಚಿನ ಭಾವಚಿತ್ರವನ್ನು ಸಲ್ಲಿಸಿ ನಿಗದಿತ ಶುಲ್ಕವನ್ನು ಪಾವತಿಸಿದರೆ ಸಾಕು. ಬೇರೆ ಯಾವುದೇ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸುವ ಅಗತ್ಯವಿಲ್ಲ."]', NULL, NULL, '2291');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('bba4f9b2-4c8f-4c4c-8979-88ce098d2b51', 'THE-DEPARTMENT-OF-FO-8', '98c19fd4-7019-42a5-9af1-39cd53b9d099', 'Renewal Dealer Licence', 'General', 7, 'Renewal Of Dealer Licence – Application for renewing an existing dealer licence to continue dealing in weights and measures as per Legal Metrology regulations.', '["This service has been enabled for automatic renewal. Therefore, applicants only need to submit a recent photograph and pay the prescribed fee. No other documents are required."]', '["As per Govt Notification No: AaNaSa 223 EeBaTha 19 (e-office) Dated: 10-12-2020 available in website"]', '[]', '["Applicant need to register in E-mapan > Applicant Need to Fill the application >", "Applicant need to upload the Required Documents>", "Applicant has to make Payment >", "Applicant has to make E-Sign>", "Applicant will Submit the application", "and Should take the approval from department"]', NULL, NULL, 'https://emapan.karnataka.gov.in/Homepage_Sevaone.aspx??DepartmentID=14&ServiceID=3000&SevaOneUserID=<<sevaOneUserID>>&Token=<<token>>', true, '2026-10-30 16:55:56.458552+00', 'ef8e63a7-734d-4bc0-91ff-71ba8aa95423', 'ತೂಕ, ಅಳತೆ, ತೂಕ ಮತ್ತು ಅಳತೆ ಸಾಧನಗಳ ಮಾರಾಟಗಾರರ ರಾಜ್ಯವ್ಯಾಪ್ತಿ ಪರವಾನಗಿಗಳ ನವೀಕರಣ.', 'Renewal Dealer Licence – Renewal of an existing dealer licence.', NULL, 'State', NULL, NULL, NULL, NULL, 'ಮಾರಾಟಗಾರರ ಪರವಾನಗಿ ನವೀಕರಣ – ಕಾನೂನು ಮಾಪನಶಾಸ್ತ್ರ ನಿಯಮಾವಳಿಗಳ ಪ್ರಕಾರ ತೂಕ ಮತ್ತು ಅಳತೆಗಳ ವ್ಯವಹಾರವನ್ನು ಮುಂದುವರಿಸಲು ಈಗಿರುವ ತೂಕ, ಅಳತೆ, ತೂಕ ಮತ್ತು ಅಳತೆ ಸಾಧನಗಳ ಮಾರಾಟಗಾರರ ರಾಜ್ಯವ್ಯಾಪ್ತಿ ಪರವಾನಗಿಯನ್ನು ನವೀಕರಿಸುವ ಅರ್ಜಿ.', NULL, NULL, NULL, true, 'Yes', '["ಸರ್ಕಾರದ ಅಧಿಸೂಚನೆ ಸಂಖ್ಯೆ: ಆನಾಸ 223 ಇಭತ 19 (ಇ-ಆಫೀಸ್) ದಿನಾಂಕ:10-12-2020 ರಲ್ಲಿ ತಿಳಿಸಿರುವ ಕಾರ್ಯವಿಧಾನದಂತೆ ವೆಬ್"]', '["ಅರ್ಜಿದಾರರು ಇ-ಮಾಪನ್ (E-Mapan) ಪೋರ್ಟಲ್"]', 1, '["ಈ ಸೇವೆಯನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ನವೀಕರಿಸುವ ವ್ಯವಸ್ಥೆ ಮಾಡಲಾಗಿದೆ. ಆದ್ದರಿಂದ, ಇತ್ತೀಚಿನ ಭಾವಚಿತ್ರವನ್ನು ಸಲ್ಲಿಸಿ ನಿಗದಿತ ಶುಲ್ಕವನ್ನು ಪಾವತಿಸಿದರೆ ಸಾಕು. ಬೇರೆ ಯಾವುದೇ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸುವ ಅಗತ್ಯವಿಲ್ಲ."]', NULL, NULL, '2292');
