INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('25ce9708-4b1e-4af7-ac96-b06febaa50ce', 'SCHEDULED-TRIBES-WEL-6', '3639208c-68b3-4afd-b526-9ba51fe3f226', 'Stipend to Law Graduates', 'Stipend', 60, '', '["Income & Caste Certificate, Aadhar Card & Law Degree Certificate"]', '["00 lakh Family Income limit"]', '[]', '[]', NULL, NULL, 'https://twd.karnataka.gov.in/twincentive/LAW/LAWHome.aspx', true, '2026-10-30 16:55:56.458552+00', '10bbe8f2-3183-4b94-93c4-70b9d94c09ba', 'ಕಾನೂನು ಪದವೀಧರರಿಗೆ ಶಿಷ್ಯವೇತನ', 'Law Stipend', NULL, 'In-house portal of the TWD. Hosted in KSDC and periodic Audit are being carried out by the ISECRON a', 'Online', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["00 ಲಕ್ಷ ಕುಟುಂಬ ಆದಾಯ ಮಿತಿ"]', '[]', 1, '["ಆದಾಯ ಮತ್ತು ಜಾತಿ ಪ್ರಮಾಣ ಪತ್ರ, ಆಧಾರ್ ಕಾರ್ಡ್ ಮತ್ತು ಕಾನೂನು ಪದವಿ ಪ್ರಮಾಣ ಪತ್ರ"]', NULL, NULL, NULL);
