INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('e9499c72-bcac-4dfb-9fa0-a002595b134c', 'RURAL-DEVELOPMENT-AN-13', 'd1a5f9ed-d991-4f3a-81be-0215ecf4e378', 'Maintenance of Drinking Water', 'Household Utilities', 0, 'Using this option, Citizen can avail the Household Utility service Maintenance of Drinking Water.', '[]', '["Resident/property owner requiring water maintenance."]', '[]', '["Citizen drafts the application.", "Applicant submits the application.", "Stage 1 - Field Verification Report is prepared by the department.", "Stage 2 - Application is reviewed for approval.", "If Approved -> Service is Completed.", "If Rejected -> Application is rejected and returned to the citizen/applicant."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಕುಡಿಯುವ ನೀರಿನ ನಿರ್ವಹಣೆ', 'Application for the permission to Avail Maintenance of Drinking Water', NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, NULL, NULL, 'ಈ ಆಯ್ಕೆಯನ್ನು ಬಳಸಿಕೊಂಡು, ನಾಗರಿಕರು ಗೃಹೋಪಯೋಗಿ ಉಪಯುಕ್ತತೆ ಸೇವೆಯಾದ ಕುಡಿಯುವ ನೀರಿನ ನಿರ್ವಹಣೆಯನ್ನು ಪಡೆಯಬಹುದು.', NULL, NULL, NULL, NULL, 'Sakala', '["ನೀರಿನ ನಿರ್ವಹಣೆ ಅಗತ್ಯವಿರುವ ನಿವಾಸಿ/ಆಸ್ತಿ ಮಾಲೀಕ."]', '["ನಾಗರಿಕರು ಅರ್ಜಿಯ ಕರಡು ಸಿದ್ಧಪಡಿಸುತ್ತಾರೆ.", "ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸುತ್ತಾರೆ.", "ಹಂತ 1 - ಇಲಾಖೆಯು ಕ್ಷೇತ್ರ ಪರಿಶೀಲನಾ ವರದಿಯನ್ನು ಸಿದ್ಧಪಡಿಸುತ್ತದೆ.", "ಹಂತ 2 - ಅರ್ಜಿಯನ್ನು ಅನುಮೋದನೆಗಾಗಿ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ.", "ಅನುಮೋದನೆಯಾದರೆ -> ಸೇವೆ ಪೂರ್ಣಗೊಳ್ಳುತ್ತದೆ.", "ತಿರಸ್ಕರಿಸಿದರೆ -> ಅರ್ಜಿಯನ್ನು ತಿರಸ್ಕರಿಸಿ ನಾಗರಿಕ/ಅರ್ಜಿದಾರರಿಗೆ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ."]', 1, '[]', NULL, NULL, '1894');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('0a64ad8a-192b-42fe-bea8-d1a3bcedd82d', 'LABOUR-DEPARTMENT-12', '754e71d9-6fb5-4948-9726-3527641d0db8', 'Registration of the construction worker', 'General', 0, '', '["Aadhar card", "Self Declaration Form", "90Days Work Certificate"]', '["The worker must have worked in building or construction work for at least 90 days during the preceding 12 months."]', '[]', '["18 years or above."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'c1959caa-8b90-4d77-ac4e-621e337ae728', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["ಕಾರ್ಮಿಕನು ಕಳೆದ 12 ತಿಂಗಳುಗಳ ಅವಧಿಯಲ್ಲಿ ಕನಿಷ್ಠ 90 ದಿನಗಳ ಕಾಲ ಕಟ್ಟಡ ಅಥವಾ ನಿರ್ಮಾಣ ಕಾರ್ಯದಲ್ಲಿ ಕೆಲಸ ಮಾಡಿರಬೇಕು."]', '["18 ವರ್ಷ ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ವಯಸ್ಸು."]', 1, '["ಆಧಾರ್ ಕಾರ್ಡ್", "ಸ್ವಯಂ ಘೋಷಣಾ ನಮೂನೆ", "90 ದಿನಗಳ ಕೆಲಸದ ಪ್ರಮಾಣಪತ್ರ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('8a11c4d1-90d6-4709-b15a-773326cf6e3a', 'RURAL-DEVELOPMENT-AN-12', 'd1a5f9ed-d991-4f3a-81be-0215ecf4e378', 'Disconnection of Water Supply', 'Household Utilities', 0, 'Citizen can avail the Household Utility services for Disconnecting Water Supply Connection by seeking this Service.', '["E-Swathu Form", "Property Tax Paid Receipt", "Ownership Declaration Certificate"]', '["Existing water connection holder/property owner or authorized applicant."]', '[]', '["Citizen drafts the application.", "Applicant submits the application.", "Stage 1 - Document Verification is carried out. If Rejected -> application is returned to the citizen/applicant (process ends). If Approved -> proceeds to Stage 2.", "Stage 2 - Field Verification Report is prepared.", "Stage 3 - Application goes for Approval. If Rejected -> application is returned to the citizen/applicant (process ends). If Approved -> proceeds.", "Citizen pays the Service Fee.", "Stage 4 - Digital Signature is applied by the authorised officer.", "Service is Completed."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ನೀರು ಸರಬರಾಜು ಸಂಪರ್ಕ ಕಡಿತ', 'Application for the permission to Disconnect of Water Supply', NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, NULL, NULL, 'ಈ ಸೇವೆಯನ್ನು ಪಡೆಯುವ ಮೂಲಕ ನಾಗರಿಕರು ನೀರು ಸರಬರಾಜು ಸಂಪರ್ಕ ಕಡಿತಗೊಳಿಸುವ ಗೃಹೋಪಯೋಗಿ ಸೇವೆಗಳನ್ನು ಪಡೆಯಬಹುದು.', NULL, NULL, NULL, NULL, 'Sakala', '["ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ನೀರಿನ ಸಂಪರ್ಕ ಹೊಂದಿರುವವರು/ಆಸ್ತಿ ಮಾಲೀಕ ಅಥವಾ ಅಧಿಕೃತ ಅರ್ಜಿದಾರ."]', '["ನಾಗರಿಕರು ಅರ್ಜಿಯ ಕರಡು ಸಿದ್ಧಪಡಿಸುತ್ತಾರೆ.", "ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸುತ್ತಾರೆ.", "ಹಂತ 1 - ದಾಖಲೆ ಪರಿಶೀಲನೆ ನಡೆಸಲಾಗುತ್ತದೆ. ತಿರಸ್ಕರಿಸಿದರೆ -> ಅರ್ಜಿಯನ್ನು ನಾಗರಿಕ/ಅರ್ಜಿದಾರರಿಗೆ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ (ಪ್ರಕ್ರಿಯೆ ಮುಗಿಯುತ್ತದೆ). ಅನುಮೋದಿಸಿದರೆ -> ಹಂತ 2ಕ್ಕೆ ಮುಂದುವರಿಯುತ್ತದೆ.", "ಹಂತ 2 - ಕ್ಷೇತ್ರ ಪರಿಶೀಲನಾ ವರದಿಯನ್ನು ಸಿದ್ಧಪಡಿಸಲಾಗುತ್ತದೆ.", "ಹಂತ 3 - ಅರ್ಜಿಯನ್ನು ಅನುಮೋದನೆಗಾಗಿ ಕಳುಹಿಸಲಾಗುತ್ತದೆ. ತಿರಸ್ಕರಿಸಿದರೆ -> ಅರ್ಜಿಯನ್ನು ನಾಗರಿಕ/ಅರ್ಜಿದಾರರಿಗೆ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ. ಅನುಮೋದಿಸಿದರೆ -> ಮುಂದುವರಿಯುತ್ತದೆ.", "ನಾಗರಿಕರು ಸೇವಾ ಶುಲ್ಕವನ್ನು ಪಾವತಿಸುತ್ತಾರೆ.", "ಹಂತ 4 - ಅಧಿಕೃತ ಅಧಿಕಾರಿ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡುತ್ತಾರೆ.", "ಸೇವೆ ಪೂರ್ಣಗೊಳ್ಳುತ್ತದೆ."]', 1, '["ಇ-ಸ್ವಾತು ಫಾರ್ಮ್", "ಆಸ್ತಿ ತೆರಿಗೆ ಪಾವತಿಸಿದ ರಸೀದಿ", "ಮಾಲೀಕತ್ವ ಘೋಷಣೆ ಪ್ರಮಾಣಪತ್ರ"]', NULL, NULL, '1934');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('289ef129-cb20-4194-b199-302f4da866ea', 'RURAL-DEVELOPMENT-AN-8', 'd1a5f9ed-d991-4f3a-81be-0215ecf4e378', 'Permission for Establishment of Industrial/ Agriculture-Based Production Unit', 'Business Related', 0, 'Any individual/organization who wishes to establish or seek Post Facto Sanction for Industrial/ Agriculture-Based Production Unit within the Grama Panchayat jurisdiction needs to apply for the permission from the respective Grama Panchayat.', '["E-Swathu Form/RTC related to agriculture land", "No Objection Certificate from concerned Authority", "Rent/ Lease Agreement", "Property Tax Paid Receipt", "Ownership Certificate"]', '["Applicant proposing to establish or operate an industrial/agro-based production unit."]', '[]', '["Citizen & BSK Portal - Application Filling and Submission: Citizen fills the application in 6 steps, uploads the required documents, and submits the application through the BSK Portal.", "Application Fee Payment: Citizen pays the application fee. After successful payment, the application moves to Secretary Login.", "Secretary Login - Document Verification: Secretary performs document verification and has two options - Approve or Reject. If rejected, the application is considered finally rejected. If approved, it moves to Field Verification.", "Secretary Login - Field Verification: Secretary performs and approves the field verification. After approval, the application moves to Raise Objection.", "Secretary Login - Raise Objection: Secretary reviews the application and raises an objection if required (only option here is Approve). After approval, the application moves to PDO Login.", "PDO Login - Application Approval / Rejection: PDO reviews the application and has two options - Approve or Reject. If rejected, it is considered finally rejected. If approved, PDO enters the decided service fee.", "Citizen - Service Fee Payment: Citizen views the decided service fee and pays it for the application.", "PDO Login - DSC / Digital Signature: After service fee payment, the application moves to PDO for DSC. PDO digitally signs the certificate and can download the digitally signed certificate.", "Citizen - Receive Completed Application: Citizen receives the completed application/service result.", "Citizen - Feedback: Citizen submits the feedback form after receiving the service result."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಕೈಗಾರಿಕಾ/ಕೃಷಿ ಆಧಾರಿತ ಉತ್ಪಾದನಾ ಘಟಕ ಸ್ಥಾಪನೆಗೆ ಅನುಮತಿ', 'Application for the Permission to Start Industrial or Agro Based Production Unit.', NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, NULL, NULL, 'ಗ್ರಾಮ ಪಂಚಾಯತ್ ವ್ಯಾಪ್ತಿಯಲ್ಲಿ ಕೈಗಾರಿಕಾ/ಕೃಷಿ ಆಧಾರಿತ ಉತ್ಪಾದನಾ ಘಟಕವನ್ನು ಸ್ಥಾಪಿಸಲು ಅಥವಾ ಪೋಸ್ಟ್ ಫ್ಯಾಕ್ಟೊ ಅನುಮೋದನೆಯನ್ನು ಪಡೆಯಲು ಬಯಸುವ ಯಾವುದೇ ವ್ಯಕ್ತಿ/ಸಂಸ್ಥೆಯು ಆಯಾ ಗ್ರಾಮ ಪಂಚಾಯತ್', NULL, NULL, NULL, NULL, 'Sakala', '["ಕೈಗಾರಿಕಾ/ಕೃಷಿ ಆಧಾರಿತ ಉತ್ಪಾದನಾ ಘಟಕವನ್ನು ಸ್ಥಾಪಿಸಲು ಅಥವಾ ನಡೆಸಲು ಉದ್ದೇಶಿಸಿರುವ ಅರ್ಜಿದಾರ."]', '["ನಾಗರಿಕ ಮತ್ತು BSK ಪೋರ್ಟಲ್ - ಅರ್ಜಿ ಭರ್ತಿ ಮತ್ತು ಸಲ್ಲಿಕೆ: ನಾಗರಿಕರು 6 ಹಂತಗಳಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಭರ್ತಿ ಮಾಡಿ, ಅಗತ್ಯ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ, BSK ಪೋರ್ಟಲ್ ಮೂಲಕ ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸುತ್ತಾರೆ.", "ಅರ್ಜಿ ಶುಲ್ಕ ಪಾವತಿ: ನಾಗರಿಕರು ಅರ್ಜಿ ಶುಲ್ಕವನ್ನು ಪಾವತಿಸುತ್ತಾರೆ. ಯಶಸ್ವಿ ಪಾವತಿಯ ನಂತರ, ಅರ್ಜಿ ಕಾರ್ಯದರ್ಶಿ ಲಾಗಿನ್‌ಗೆ ಸಾಗುತ್ತದೆ.", "ಕಾರ್ಯದರ್ಶಿ ಲಾಗಿನ್ - ದಾಖಲೆ ಪರಿಶೀಲನೆ: ಕಾರ್ಯದರ್ಶಿ ದಾಖಲೆ ಪರಿಶೀಲನೆ ನಡೆಸುತ್ತಾರೆ ಮತ್ತು ಎರಡು ಆಯ್ಕೆಗಳಿರುತ್ತವೆ - ಅನುಮೋದಿಸು ಅಥವಾ ತಿರಸ್ಕರಿಸು. ತಿರಸ್ಕರಿಸಿದರೆ, ಅರ್ಜಿ ಅಂತಿಮವಾಗಿ ತಿರಸ್ಕೃತವಾಗಿದೆ ಎಂದು ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ. ಅನುಮೋದಿಸಿದರೆ, ಅದು ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆಗೆ ಸಾಗುತ್ತದೆ.", "ಕಾರ್ಯದರ್ಶಿ ಲಾಗಿನ್ - ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ: ಕಾರ್ಯದರ್ಶಿ ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ ನಡೆಸಿ ಅನುಮೋದಿಸುತ್ತಾರೆ. ಅನುಮೋದನೆಯ ನಂತರ, ಅರ್ಜಿ ಆಕ್ಷೇಪಣೆ ಎತ್ತುವ ಹಂತಕ್ಕೆ ಸಾಗುತ್ತದೆ.", "ಕಾರ್ಯದರ್ಶಿ ಲಾಗಿನ್ - ಆಕ್ಷೇಪಣೆ ಎತ್ತುವುದು: ಕಾರ್ಯದರ್ಶಿ ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸಿ ಅಗತ್ಯವಿದ್ದರೆ ಆಕ್ಷೇಪಣೆ ಎತ್ತುತ್ತಾರೆ (ಇಲ್ಲಿ ಇರುವ ಏಕೈಕ ಆಯ್ಕೆ ಅನುಮೋದನೆ). ಅನುಮೋದನೆಯ ನಂತರ, ಅರ್ಜಿ PDO ಲಾಗಿನ್‌ಗೆ ಸಾಗುತ್ತದೆ.", "PDO ಲಾಗಿನ್ - ಅರ್ಜಿ ಅನುಮೋದನೆ / ತಿರಸ್ಕರಣೆ: PDO ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸುತ್ತಾರೆ ಮತ್ತು ಎರಡು ಆಯ್ಕೆಗಳಿರುತ್ತವೆ - ಅನುಮೋದಿಸು ಅಥವಾ ತಿರಸ್ಕರಿಸು. ತಿರಸ್ಕರಿಸಿದರೆ, ಅದು ಅಂತಿಮವಾಗಿ ತಿರಸ್ಕೃತವಾಗಿದೆ ಎಂದು ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ. ಅನುಮೋದಿಸಿದರೆ, PDO ನಿರ್ಧರಿಸಿದ ಸೇವಾ ಶುಲ್ಕವನ್ನು ನಮೂದಿಸುತ್ತಾರೆ.", "ನಾಗರಿಕರು - ಸೇವಾ ಶುಲ್ಕ ಪಾವತಿ: ನಾಗರಿಕರು ನಿರ್ಧರಿಸಿದ ಸೇವಾ ಶುಲ್ಕವನ್ನು ನೋಡಿ ಅರ್ಜಿಗಾಗಿ ಪಾವತಿಸುತ್ತಾರೆ.", "PDO ಲಾಗಿನ್ - DSC / ಡಿಜಿಟಲ್ ಸಹಿ: ಸೇವಾ ಶುಲ್ಕ ಪಾವತಿಯ ನಂತರ, ಅರ್ಜಿ DSCಗಾಗಿ PDOಗೆ ಸಾಗುತ್ತದೆ. PDO ಪ್ರಮಾಣಪತ್ರಕ್ಕೆ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡುತ್ತಾರೆ ಮತ್ತು ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡಿದ ಪ್ರಮಾಣಪತ್ರವನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಬಹುದು.", "ನಾಗರಿಕರು - ಪೂರ್ಣಗೊಂಡ ಅರ್ಜಿಯನ್ನು ಸ್ವೀಕರಿಸುವುದು: ನಾಗರಿಕರು ಪೂರ್ಣಗೊಂಡ ಅರ್ಜಿ/ಸೇವಾ ಫಲಿತಾಂಶವನ್ನು ಸ್ವೀಕರಿಸುತ್ತಾರೆ.", "ನಾಗರಿಕರು - ಪ್ರತಿಕ್ರಿಯೆ: ಸೇವಾ ಫಲಿತಾಂಶವನ್ನು ಸ್ವೀಕರಿಸಿದ ನಂತರ ನಾಗರಿಕರು ಪ್ರತಿಕ್ರಿಯೆ ಫಾರ್ಮ್ ಅನ್ನು ಸಲ್ಲಿಸುತ್ತಾರೆ."]', 1, '["ಕೃಷಿ ಭೂಮಿಗೆ ಸಂಬಂಧಿಸಿದ ಇ-ಸ್ವಾತು ಫಾರ್ಮ್/ಆರ್"]', NULL, NULL, '2500');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('36158863-8183-42d5-8c6e-ba5838edae63', 'RURAL-DEVELOPMENT-AN-16', 'd1a5f9ed-d991-4f3a-81be-0215ecf4e378', 'Providing Employment to Labours', 'MGNREGA', 0, 'Demand for Work: By availing this service option, a citizen can submit and track online application to raise demand for work under MGNREGA', '[]', '["Rural household member seeking MGNREGA employment."]', '[]', '["Applicant drafts and submits the application.", "PDO Decision (Stage 123) - PDO reviews the application. If Rejected -> moves to EO Decision. If Approved -> moves directly to the ''Returned to PDO'' step.", "EO Decision (Stage 125) - (only when PDO rejects) EO reviews the application. If Rejected -> Application is finally Rejected / Request Cancelled (process ends). If Approved -> moves to ''Returned to PDO'' step.", "Returned to PDO (Stage 126) - Application is sent back to PDO; PDO cannot reject the application at this stage.", "PDO Approves Application (Stage 127) - PDO gives final approval.", "Application Approved / Service Completed (Final)."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಕಾರ್ಮಿಕರಿಗೆ ಉದ್ಯೋಗ ಒದಗಿಸುವುದು', 'Application for the permission to demand Work Under MGNREGA', NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, NULL, NULL, 'ಕೆಲಸಕ್ಕೆ ಬೇಡಿಕೆ: ಈ ಸೇವಾ ಆಯ್ಕೆಯನ್ನು ಪಡೆಯುವ ಮೂಲಕ, ನಾಗರಿಕರು MGNREGA ಅಡಿಯಲ್ಲಿ ಕೆಲಸಕ್ಕೆ ಬೇಡಿಕೆ ಹೆಚ್ಚಿಸಲು ಆನ್', NULL, NULL, NULL, NULL, 'Sakala', '["MGNREGA ಉದ್ಯೋಗವನ್ನು ಹುಡುಕುತ್ತಿರುವ ಗ್ರಾಮೀಣ ಕುಟುಂಬದ ಸದಸ್ಯ."]', '["ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಿದ್ಧಪಡಿಸಿ ಸಲ್ಲಿಸುತ್ತಾರೆ.", "ಪಿಡಿಒ ನಿರ್ಣಯ (123) - ಪಿಡಿಒ ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸುತ್ತಾರೆ. ತಿರಸ್ಕರಿಸಿದರೆ -> ಇಒ ನಿರ್ಣಯಕ್ಕೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ. ಅನುಮೋದಿಸಿದರೆ -> ನೇರವಾಗಿ ''ಪಿಡಿಒಗೆ ಹಿಂತಿರುಗಿಸುವುದು'' ಹಂತಕ್ಕೆ ಹೋಗುತ್ತದೆ.", "ಇಒ ನಿರ್ಣಯ (125) - (ಪಿಡಿಒ ತಿರಸ್ಕರಿಸಿದಾಗ ಮಾತ್ರ) ಇಒ ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸುತ್ತಾರೆ. ತಿರಸ್ಕರಿಸಿದರೆ -> ಅರ್ಜಿ ಅಂತಿಮವಾಗಿ ತಿರಸ್ಕರಿಸಲ್ಪಡುತ್ತದೆ / ರದ್ದುಗೊಳ್ಳುತ್ತದೆ (ಪ್ರಕ್ರಿಯೆ ಮುಗಿಯುತ್ತದೆ). ಅನುಮೋದಿಸಿದರೆ -> ''ಪಿಡಿಒಗೆ ಹಿಂತಿರುಗಿಸುವುದು'' ಹಂತಕ್ಕೆ ಹೋಗುತ್ತದೆ.", "ಪಿಡಿಒಗೆ ಹಿಂತಿರುಗಿಸುವುದು (126) - ಅರ್ಜಿಯನ್ನು ಪಿಡಿಒಗೆ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ; ಈ ಹಂತದಲ್ಲಿ ಪಿಡಿಒ ಅರ್ಜಿಯನ್ನು ತಿರಸ್ಕರಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.", "ಪಿಡಿಒ ಅರ್ಜಿಯನ್ನು ಅನುಮೋದಿಸುತ್ತಾರೆ (127) - ಪಿಡಿಒ ಅಂತಿಮ ಅನುಮೋದನೆ ನೀಡುತ್ತಾರೆ.", "ಅರ್ಜಿ ಅನುಮೋದಿಸಲಾಗಿದೆ / ಸೇವೆ ಪೂರ್ಣಗೊಂಡಿದೆ (ಅಂತಿಮ)."]', 1, '[]', NULL, NULL, '1393');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('f3fa67b1-f4d9-455b-8162-488a6b31fdbd', 'REVENUE-DEPARTMENT-46', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'TIPPAN', 'General', 7, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (TIPPAN)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಟಿಪ್ಪಣಿ', NULL, NULL, NULL, NULL, NULL, 35.00, NULL, 'ಟಿಪ್ಪಣಿ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3049');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('54c7f460-7a3d-4d7a-866b-5fef1cbc0665', 'RURAL-DEVELOPMENT-AN-17', 'd1a5f9ed-d991-4f3a-81be-0215ecf4e378', 'Issue of Job card to Labours under MGNREGA', 'MGNREGA', 0, 'Job Card Application: By availing this service option, a citizen can submit and track online application to raise a request for the issuance of a Job Card under MGNREGA', '[]', '["Rural household member eligible for MGNREGA employment."]', '[]', '["Applicant drafts and submits the application.", "PDO Decision (Stage 123) - PDO reviews the application. If Rejected -> moves to EO Decision. If Approved -> moves directly to the ''Returned to PDO'' step.", "EO Decision (Stage 125) - (only when PDO rejects) EO reviews the application. If Rejected -> Application is finally Rejected / Request Cancelled (process ends). If Approved -> moves to ''Returned to PDO'' step.", "Returned to PDO (Stage 126) - Application is sent back to PDO; PDO cannot reject the application at this stage.", "PDO Approves Application (Stage 127) - PDO gives final approval.", "Application Approved / Service Completed (Final)."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'MGNREGA ಅಡಿಯಲ್ಲಿ ಕಾರ್ಮಿಕರಿಗೆ ಉದ್ಯೋಗ ಚೀಟಿ ವಿತರಣೆ', 'application to raise a request for the issuance of a Job Card under MGNREGA', NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, NULL, NULL, 'ಜಾಬ್ ಕಾರ್ಡ್ ಅರ್ಜಿ: ಈ ಸೇವಾ ಆಯ್ಕೆಯನ್ನು ಪಡೆಯುವ ಮೂಲಕ, ನಾಗರಿಕರು MGNREGA ಅಡಿಯಲ್ಲಿ ಜಾಬ್ ಕಾರ್ಡ್ ವಿತರಣೆಗಾಗಿ ವಿನಂತಿಯನ್ನು ಸಲ್ಲಿಸಲು ಆನ್', NULL, NULL, NULL, NULL, 'Sakala', '["MGNREGA ಉದ್ಯೋಗಕ್ಕೆ ಅರ್ಹರಾಗಿರುವ ಗ್ರಾಮೀಣ ಕುಟುಂಬದ ಸದಸ್ಯ."]', '["ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಿದ್ಧಪಡಿಸಿ ಸಲ್ಲಿಸುತ್ತಾರೆ.", "ಪಿಡಿಒ ನಿರ್ಣಯ (123) - ಪಿಡಿಒ ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸುತ್ತಾರೆ. ತಿರಸ್ಕರಿಸಿದರೆ -> ಇಒ ನಿರ್ಣಯಕ್ಕೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ. ಅನುಮೋದಿಸಿದರೆ -> ನೇರವಾಗಿ ''ಪಿಡಿಒಗೆ ಹಿಂತಿರುಗಿಸುವುದು'' ಹಂತಕ್ಕೆ ಹೋಗುತ್ತದೆ.", "ಇಒ ನಿರ್ಣಯ (125) - (ಪಿಡಿಒ ತಿರಸ್ಕರಿಸಿದಾಗ ಮಾತ್ರ) ಇಒ ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸುತ್ತಾರೆ. ತಿರಸ್ಕರಿಸಿದರೆ -> ಅರ್ಜಿ ಅಂತಿಮವಾಗಿ ತಿರಸ್ಕರಿಸಲ್ಪಡುತ್ತದೆ / ರದ್ದುಗೊಳ್ಳುತ್ತದೆ (ಪ್ರಕ್ರಿಯೆ ಮುಗಿಯುತ್ತದೆ). ಅನುಮೋದಿಸಿದರೆ -> ''ಪಿಡಿಒಗೆ ಹಿಂತಿರುಗಿಸುವುದು'' ಹಂತಕ್ಕೆ ಹೋಗುತ್ತದೆ.", "ಪಿಡಿಒಗೆ ಹಿಂತಿರುಗಿಸುವುದು (126) - ಅರ್ಜಿಯನ್ನು ಪಿಡಿಒಗೆ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ; ಈ ಹಂತದಲ್ಲಿ ಪಿಡಿಒ ಅರ್ಜಿಯನ್ನು ತಿರಸ್ಕರಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.", "ಪಿಡಿಒ ಅರ್ಜಿಯನ್ನು ಅನುಮೋದಿಸುತ್ತಾರೆ (127) - ಪಿಡಿಒ ಅಂತಿಮ ಅನುಮೋದನೆ ನೀಡುತ್ತಾರೆ.", "ಅರ್ಜಿ ಅನುಮೋದಿಸಲಾಗಿದೆ / ಸೇವೆ ಪೂರ್ಣಗೊಂಡಿದೆ (ಅಂತಿಮ)."]', 1, '[]', NULL, NULL, '1890');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('e9391d88-c858-47a3-87ba-6d13efa88f8b', 'RURAL-DEVELOPMENT-AN-14', 'd1a5f9ed-d991-4f3a-81be-0215ecf4e378', 'Maintenance of Street Light', 'Household Utilities', 0, 'Using this option, Citizen can avail the Household Utility service Maintenance of Street Light.', '[]', '["Resident/property owner requiring street light maintenance."]', '[]', '["Citizen drafts the application.", "Applicant submits the application.", "Stage 1 - Field Verification Report is prepared by the department.", "Stage 2 - Application is reviewed for approval.", "If Approved -> Service is Completed.", "If Rejected -> Application is rejected and returned to the citizen/applicant."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಬೀದಿ ದೀಪಗಳ ನಿರ್ವಹಣೆ', 'Application for the permission to Avail Maintenance of Street Light', NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, NULL, NULL, 'ಈ ಆಯ್ಕೆಯನ್ನು ಬಳಸಿಕೊಂಡು, ನಾಗರಿಕರು ಬೀದಿ ದೀಪಗಳ ನಿರ್ವಹಣೆಗಾಗಿ ಗೃಹೋಪಯೋಗಿ ಸೇವೆಯನ್ನು ಪಡೆಯಬಹುದು.', NULL, NULL, NULL, NULL, 'Sakala', '["ಬೀದಿ ದೀಪ ನಿರ್ವಹಣೆ ಅಗತ್ಯವಿರುವ ನಿವಾಸಿ/ಆಸ್ತಿ ಮಾಲೀಕ."]', '["ನಾಗರಿಕರು ಅರ್ಜಿಯ ಕರಡು ಸಿದ್ಧಪಡಿಸುತ್ತಾರೆ.", "ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸುತ್ತಾರೆ.", "ಹಂತ 1 - ಇಲಾಖೆಯು ಕ್ಷೇತ್ರ ಪರಿಶೀಲನಾ ವರದಿಯನ್ನು ಸಿದ್ಧಪಡಿಸುತ್ತದೆ.", "ಹಂತ 2 - ಅರ್ಜಿಯನ್ನು ಅನುಮೋದನೆಗಾಗಿ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ.", "ಅನುಮೋದನೆಯಾದರೆ -> ಸೇವೆ ಪೂರ್ಣಗೊಳ್ಳುತ್ತದೆ.", "ತಿರಸ್ಕರಿಸಿದರೆ -> ಅರ್ಜಿಯನ್ನು ತಿರಸ್ಕರಿಸಿ ನಾಗರಿಕ/ಅರ್ಜಿದಾರರಿಗೆ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ."]', 1, '[]', NULL, NULL, '1578');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('0e16c510-b812-4dc2-90f5-b7c82bf35f7b', 'RURAL-DEVELOPMENT-AN-15', 'd1a5f9ed-d991-4f3a-81be-0215ecf4e378', 'Maintenance of Village Sanitation', 'Household Utilities', 0, 'Using this option, Citizen can avail the Household Utility service Maintenance of Village sanitation.', '[]', '["Village resident requiring sanitation services."]', '[]', '["Citizen drafts the application.", "Applicant submits the application.", "Stage 1 - Field Verification Report is prepared by the department.", "Stage 2 - Application is reviewed for approval.", "If Approved -> Service is Completed.", "If Rejected -> Application is rejected and returned to the citizen/applicant."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಗ್ರಾಮ ನೈರ್ಮಲ್ಯ ನಿರ್ವಹಣೆ', 'Application for the permission to Avail Maintenance of Village Sanitation', NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, NULL, NULL, 'ಈ ಆಯ್ಕೆಯನ್ನು ಬಳಸಿಕೊಂಡು, ನಾಗರಿಕರು ಗೃಹೋಪಯೋಗಿ ಸೇವೆಯನ್ನು ಗ್ರಾಮ ನೈರ್ಮಲ್ಯ ನಿರ್ವಹಣೆಯನ್ನು ಪಡೆಯಬಹುದು.', NULL, NULL, NULL, NULL, 'Sakala', '["ಸ್ವಚ್ಛತಾ ಸೇವೆಗಳು ಅಗತ್ಯವಿರುವ ಗ್ರಾಮದ ನಿವಾಸಿ."]', '["ನಾಗರಿಕರು ಅರ್ಜಿಯ ಕರಡು ಸಿದ್ಧಪಡಿಸುತ್ತಾರೆ.", "ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸುತ್ತಾರೆ.", "ಹಂತ 1 - ಇಲಾಖೆಯು ಕ್ಷೇತ್ರ ಪರಿಶೀಲನಾ ವರದಿಯನ್ನು ಸಿದ್ಧಪಡಿಸುತ್ತದೆ.", "ಹಂತ 2 - ಅರ್ಜಿಯನ್ನು ಅನುಮೋದನೆಗಾಗಿ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ.", "ಅನುಮೋದನೆಯಾದರೆ -> ಸೇವೆ ಪೂರ್ಣಗೊಳ್ಳುತ್ತದೆ.", "ತಿರಸ್ಕರಿಸಿದರೆ -> ಅರ್ಜಿಯನ್ನು ತಿರಸ್ಕರಿಸಿ ನಾಗರಿಕ/ಅರ್ಜಿದಾರರಿಗೆ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ."]', 1, '[]', NULL, NULL, '1576');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('39cb7e6b-f16c-48c6-90a9-f6029de50162', 'LABOUR-DEPARTMENT-4', '754e71d9-6fb5-4948-9726-3527641d0db8', 'Disability Pension & Ex-Gratia', 'General', 30, '1. The Board or authorized officer may Sanction an amount of Rs. 2000/- (Govt of Karnataka Notification) per month as disability pension to a beneficiary, who is partially disabled due to any disease or accident at worksite and for an ex¬gratia payment of not more than Rs. 2,00,000/- (Rupees two lakhs only) depending upon the percentage of disability and subject to the following conditions, namely- The beneficiary cannot avail this assistance in case he has availed benefit under rule-47.
