INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('d51c9d0a-fdab-4ec6-a767-6980a4723529', 'LABOUR-DEPARTMENT-3', '754e71d9-6fb5-4948-9726-3527641d0db8', 'Continuation of Pension', 'General', 30, 'Every registered building or other construction worker, can avail this scheme who has paid subscription fee for a continuous period of (not less than three years) and remain as such construction worker until he attains the age of sixty years.
