INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('c641613e-8fa8-4be8-9811-457d87fa2406', 'RURAL-DEVELOPMENT-AN-11', 'd1a5f9ed-d991-4f3a-81be-0215ecf4e378', 'New Water Supply Connection', 'Household Utilities', 0, 'Citizen can avail the Household Utility services for New Water Supply Connection by seeking this Service', '["Ownership Certificate", "E-Swathu Form", "Property Tax Paid Receipt"]', '["Property owner/authorized applicant."]', '[]', '["Citizen drafts the application.", "Applicant submits the application.", "Stage 1 - Document Verification is carried out. If Rejected -> application is returned to the citizen/applicant (process ends). If Approved -> proceeds to Stage 2.", "Stage 2 - Field Verification Report is prepared.", "Stage 3 - Application goes for Approval. If Rejected -> application is returned to the citizen/applicant (process ends). If Approved -> proceeds.", "Citizen pays the Service Fee.", "Stage 4 - Digital Signature is applied by the authorised officer.", "Service is Completed."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಹೊಸ ನೀರು ಸರಬರಾಜು ಸಂಪರ್ಕ', 'Application for the permission to Avail New Water Supply Connection.', NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, NULL, NULL, 'ನಾಗರಿಕರು ಈ ಸೇವೆಯನ್ನು ಪಡೆಯುವ ಮೂಲಕ ಹೊಸ ನೀರು ಸರಬರಾಜು ಸಂಪರ್ಕಕ್ಕಾಗಿ ಗೃಹೋಪಯೋಗಿ ಸೇವೆಗಳನ್ನು ಪಡೆಯಬಹುದು.', NULL, NULL, NULL, NULL, 'Sakala', '["ಆಸ್ತಿ ಮಾಲೀಕ/ಅಧಿಕೃತ ಅರ್ಜಿದಾರ."]', '["ನಾಗರಿಕರು ಅರ್ಜಿಯ ಕರಡು ಸಿದ್ಧಪಡಿಸುತ್ತಾರೆ.", "ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸುತ್ತಾರೆ.", "ಹಂತ 1 - ದಾಖಲೆ ಪರಿಶೀಲನೆ ನಡೆಸಲಾಗುತ್ತದೆ. ತಿರಸ್ಕರಿಸಿದರೆ -> ಅರ್ಜಿಯನ್ನು ನಾಗರಿಕ/ಅರ್ಜಿದಾರರಿಗೆ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ (ಪ್ರಕ್ರಿಯೆ ಮುಗಿಯುತ್ತದೆ). ಅನುಮೋದಿಸಿದರೆ -> ಹಂತ 2ಕ್ಕೆ ಮುಂದುವರಿಯುತ್ತದೆ.", "ಹಂತ 2 - ಕ್ಷೇತ್ರ ಪರಿಶೀಲನಾ ವರದಿಯನ್ನು ಸಿದ್ಧಪಡಿಸಲಾಗುತ್ತದೆ.", "ಹಂತ 3 - ಅರ್ಜಿಯನ್ನು ಅನುಮೋದನೆಗಾಗಿ ಕಳುಹಿಸಲಾಗುತ್ತದೆ. ತಿರಸ್ಕರಿಸಿದರೆ -> ಅರ್ಜಿಯನ್ನು ನಾಗರಿಕ/ಅರ್ಜಿದಾರರಿಗೆ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ. ಅನುಮೋದಿಸಿದರೆ -> ಮುಂದುವರಿಯುತ್ತದೆ.", "ನಾಗರಿಕರು ಸೇವಾ ಶುಲ್ಕವನ್ನು ಪಾವತಿಸುತ್ತಾರೆ.", "ಹಂತ 4 - ಅಧಿಕೃತ ಅಧಿಕಾರಿ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡುತ್ತಾರೆ.", "ಸೇವೆ ಪೂರ್ಣಗೊಳ್ಳುತ್ತದೆ."]', 1, '["ಮಾಲೀಕತ್ವ ಪ್ರಮಾಣಪತ್ರ", "ಇ-ಸ್ವಾತು ಫಾರ್ಮ್", "ಆಸ್ತಿ ತೆರಿಗೆ ಪಾವತಿಸಿದ ರಸೀದಿ"]', NULL, NULL, '1895');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('f0ea3327-143f-4806-9eab-20d2adb162e8', 'RURAL-DEVELOPMENT-AN-2', 'd1a5f9ed-d991-4f3a-81be-0215ecf4e378', 'Old Building Renovation/Repair', 'Property Related', 0, 'Building Licence is a type of authorization that is issued by the Grama Panchayat before the Old building Renovation/Repair for the Residence,Commercial and Non-residential Purposes.', '["Building Sketch", "E-Swathu Format (Form 9/11A/11B)", "Estimate Copy", "Commencement Letter of Local Planning Authority"]', '["Property owner / Authorized applicant with valid property/ownership documents."]', '[]', '["Citizen & BSK Portal - Application Filling and Submission: Citizen fills the application in 6 steps, uploads the required documents, and submits the application through the BSK Portal.", "Application Fee Payment: Citizen pays the application fee. After successful payment, the application moves to Secretary Login.", "Secretary Login - Document Verification: Secretary performs document verification and has two options - Approve or Reject. If rejected, the application is considered finally rejected. If approved, it moves to Field Verification.", "Secretary Login - Field Verification: Secretary performs and approves the field verification. After approval, the application moves to Raise Objection.", "Secretary Login - Raise Objection: Secretary reviews the application and raises an objection if required (only option here is Approve). After approval, the application moves to PDO Login.", "PDO Login - Application Approval / Rejection: PDO reviews the application and has two options - Approve or Reject. If rejected, it is considered finally rejected. If approved, PDO enters the decided service fee.", "Citizen - Service Fee Payment: Citizen views the decided service fee and pays it for the application.", "PDO Login - DSC / Digital Signature: After service fee payment, the application moves to PDO for DSC. PDO digitally signs the certificate and can download the digitally signed certificate.", "Citizen - Receive Completed Application: Citizen receives the completed application/service result.", "Citizen - Feedback: Citizen submits the feedback form after receiving the service result."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಹಳೆಯ ಕಟ್ಟಡ ನವೀಕರಣ/ದುರಸ್ತಿ', 'Apply for Permission to Renovation of old building.', NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, NULL, NULL, 'ಕಟ್ಟಡ ಪರವಾನಗಿಯು ನಿವಾಸ, ವಾಣಿಜ್ಯ ಮತ್ತು ವಸತಿಯೇತರ ಉದ್ದೇಶಗಳಿಗಾಗಿ ಹಳೆಯ ಕಟ್ಟಡ ನವೀಕರಣ/ದುರಸ್ತಿ ಮಾಡುವ ಮೊದಲು ಗ್ರಾಮ ಪಂಚಾಯತ್ ನೀಡುವ ಒಂದು ರೀತಿಯ ಅಧಿಕಾರವಾಗಿದೆ.', NULL, NULL, NULL, NULL, 'Sakala', '["ಮಾನ್ಯ ಆಸ್ತಿ/ಮಾಲೀಕತ್ವದ ದಾಖಲೆಗಳನ್ನು ಹೊಂದಿರುವ ಆಸ್ತಿ ಮಾಲೀಕ / ಅಧಿಕೃತ ಅರ್ಜಿದಾರ."]', '["ನಾಗರಿಕ ಮತ್ತು BSK ಪೋರ್ಟಲ್ - ಅರ್ಜಿ ಭರ್ತಿ ಮತ್ತು ಸಲ್ಲಿಕೆ: ನಾಗರಿಕರು 6 ಹಂತಗಳಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಭರ್ತಿ ಮಾಡಿ, ಅಗತ್ಯ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ, BSK ಪೋರ್ಟಲ್ ಮೂಲಕ ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸುತ್ತಾರೆ.", "ಅರ್ಜಿ ಶುಲ್ಕ ಪಾವತಿ: ನಾಗರಿಕರು ಅರ್ಜಿ ಶುಲ್ಕವನ್ನು ಪಾವತಿಸುತ್ತಾರೆ. ಯಶಸ್ವಿ ಪಾವತಿಯ ನಂತರ, ಅರ್ಜಿ ಕಾರ್ಯದರ್ಶಿ ಲಾಗಿನ್‌ಗೆ ಸಾಗುತ್ತದೆ.", "ಕಾರ್ಯದರ್ಶಿ ಲಾಗಿನ್ - ದಾಖಲೆ ಪರಿಶೀಲನೆ: ಕಾರ್ಯದರ್ಶಿ ದಾಖಲೆ ಪರಿಶೀಲನೆ ನಡೆಸುತ್ತಾರೆ ಮತ್ತು ಎರಡು ಆಯ್ಕೆಗಳಿರುತ್ತವೆ - ಅನುಮೋದಿಸು ಅಥವಾ ತಿರಸ್ಕರಿಸು. ತಿರಸ್ಕರಿಸಿದರೆ, ಅರ್ಜಿ ಅಂತಿಮವಾಗಿ ತಿರಸ್ಕೃತವಾಗಿದೆ ಎಂದು ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ. ಅನುಮೋದಿಸಿದರೆ, ಅದು ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆಗೆ ಸಾಗುತ್ತದೆ.", "ಕಾರ್ಯದರ್ಶಿ ಲಾಗಿನ್ - ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ: ಕಾರ್ಯದರ್ಶಿ ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ ನಡೆಸಿ ಅನುಮೋದಿಸುತ್ತಾರೆ. ಅನುಮೋದನೆಯ ನಂತರ, ಅರ್ಜಿ ಆಕ್ಷೇಪಣೆ ಎತ್ತುವ ಹಂತಕ್ಕೆ ಸಾಗುತ್ತದೆ.", "ಕಾರ್ಯದರ್ಶಿ ಲಾಗಿನ್ - ಆಕ್ಷೇಪಣೆ ಎತ್ತುವುದು: ಕಾರ್ಯದರ್ಶಿ ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸಿ ಅಗತ್ಯವಿದ್ದರೆ ಆಕ್ಷೇಪಣೆ ಎತ್ತುತ್ತಾರೆ (ಇಲ್ಲಿ ಇರುವ ಏಕೈಕ ಆಯ್ಕೆ ಅನುಮೋದನೆ). ಅನುಮೋದನೆಯ ನಂತರ, ಅರ್ಜಿ PDO ಲಾಗಿನ್‌ಗೆ ಸಾಗುತ್ತದೆ.", "PDO ಲಾಗಿನ್ - ಅರ್ಜಿ ಅನುಮೋದನೆ / ತಿರಸ್ಕರಣೆ: PDO ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸುತ್ತಾರೆ ಮತ್ತು ಎರಡು ಆಯ್ಕೆಗಳಿರುತ್ತವೆ - ಅನುಮೋದಿಸು ಅಥವಾ ತಿರಸ್ಕರಿಸು. ತಿರಸ್ಕರಿಸಿದರೆ, ಅದು ಅಂತಿಮವಾಗಿ ತಿರಸ್ಕೃತವಾಗಿದೆ ಎಂದು ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ. ಅನುಮೋದಿಸಿದರೆ, PDO ನಿರ್ಧರಿಸಿದ ಸೇವಾ ಶುಲ್ಕವನ್ನು ನಮೂದಿಸುತ್ತಾರೆ.", "ನಾಗರಿಕರು - ಸೇವಾ ಶುಲ್ಕ ಪಾವತಿ: ನಾಗರಿಕರು ನಿರ್ಧರಿಸಿದ ಸೇವಾ ಶುಲ್ಕವನ್ನು ನೋಡಿ ಅರ್ಜಿಗಾಗಿ ಪಾವತಿಸುತ್ತಾರೆ.", "PDO ಲಾಗಿನ್ - DSC / ಡಿಜಿಟಲ್ ಸಹಿ: ಸೇವಾ ಶುಲ್ಕ ಪಾವತಿಯ ನಂತರ, ಅರ್ಜಿ DSCಗಾಗಿ PDOಗೆ ಸಾಗುತ್ತದೆ. PDO ಪ್ರಮಾಣಪತ್ರಕ್ಕೆ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡುತ್ತಾರೆ ಮತ್ತು ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡಿದ ಪ್ರಮಾಣಪತ್ರವನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಬಹುದು.", "ನಾಗರಿಕರು - ಪೂರ್ಣಗೊಂಡ ಅರ್ಜಿಯನ್ನು ಸ್ವೀಕರಿಸುವುದು: ನಾಗರಿಕರು ಪೂರ್ಣಗೊಂಡ ಅರ್ಜಿ/ಸೇವಾ ಫಲಿತಾಂಶವನ್ನು ಸ್ವೀಕರಿಸುತ್ತಾರೆ.", "ನಾಗರಿಕರು - ಪ್ರತಿಕ್ರಿಯೆ: ಸೇವಾ ಫಲಿತಾಂಶವನ್ನು ಸ್ವೀಕರಿಸಿದ ನಂತರ ನಾಗರಿಕರು ಪ್ರತಿಕ್ರಿಯೆ ಫಾರ್ಮ್ ಅನ್ನು ಸಲ್ಲಿಸುತ್ತಾರೆ."]', 1, '["ಕಟ್ಟಡ ರೇಖಾಚಿತ್ರ", "ಇ-ಸ್ವಾತು ಸ್ವರೂಪ (ಫಾರ್ಮ್ 9/11A/11B)", "ಅಂದಾಜು ಪ್ರತಿ", "ಸ್ಥಳೀಯ ಯೋಜನಾ ಪ್ರಾಧಿಕಾರದ ಪ್ರಾರಂಭ ಪತ್ರ"]', NULL, NULL, '2777');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('1d5669e8-637d-4f70-ae1b-8d943138b0ac', 'RURAL-DEVELOPMENT-AN-3', 'd1a5f9ed-d991-4f3a-81be-0215ecf4e378', 'Old Building Expansion', 'Property Related', 0, 'Building Licence is a type of authorization that is issued by the Grama Panchayat before the Old building Expansion for the Residence,Commercial and Non-residential Purposes.', '["Building Sketch", "E-Swathu Format (Form 9/11A/11B)", "Estimate Copy", "Commencement Letter of Local Planning Authority"]', '["Property owner / Authorized applicant with valid property/ownership documents."]', '[]', '["Citizen & BSK Portal - Application Filling and Submission: Citizen fills the application in 6 steps, uploads the required documents, and submits the application through the BSK Portal.", "Application Fee Payment: Citizen pays the application fee. After successful payment, the application moves to Secretary Login.", "Secretary Login - Document Verification: Secretary performs document verification and has two options - Approve or Reject. If rejected, the application is considered finally rejected. If approved, it moves to Field Verification.", "Secretary Login - Field Verification: Secretary performs and approves the field verification. After approval, the application moves to Raise Objection.", "Secretary Login - Raise Objection: Secretary reviews the application and raises an objection if required (only option here is Approve). After approval, the application moves to PDO Login.", "PDO Login - Application Approval / Rejection: PDO reviews the application and has two options - Approve or Reject. If rejected, it is considered finally rejected. If approved, PDO enters the decided service fee.", "Citizen - Service Fee Payment: Citizen views the decided service fee and pays it for the application.", "PDO Login - DSC / Digital Signature: After service fee payment, the application moves to PDO for DSC. PDO digitally signs the certificate and can download the digitally signed certificate.", "Citizen - Receive Completed Application: Citizen receives the completed application/service result.", "Citizen - Feedback: Citizen submits the feedback form after receiving the service result."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಹಳೆಯ ಕಟ್ಟಡ ವಿಸ್ತರಣೆ', 'Apply for Permission to Expansion of old Building.', NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, NULL, NULL, 'ಕಟ್ಟಡ ಪರವಾನಗಿಯು ಹಳೆಯ ಕಟ್ಟಡ ವಿಸ್ತರಣೆಗೆ ಮೊದಲು ಗ್ರಾಮ ಪಂಚಾಯತ್', NULL, NULL, NULL, NULL, 'Sakala', '["ಮಾನ್ಯ ಆಸ್ತಿ/ಮಾಲೀಕತ್ವದ ದಾಖಲೆಗಳನ್ನು ಹೊಂದಿರುವ ಆಸ್ತಿ ಮಾಲೀಕ / ಅಧಿಕೃತ ಅರ್ಜಿದಾರ."]', '["ನಾಗರಿಕ ಮತ್ತು BSK ಪೋರ್ಟಲ್ - ಅರ್ಜಿ ಭರ್ತಿ ಮತ್ತು ಸಲ್ಲಿಕೆ: ನಾಗರಿಕರು 6 ಹಂತಗಳಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಭರ್ತಿ ಮಾಡಿ, ಅಗತ್ಯ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ, BSK ಪೋರ್ಟಲ್ ಮೂಲಕ ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸುತ್ತಾರೆ.", "ಅರ್ಜಿ ಶುಲ್ಕ ಪಾವತಿ: ನಾಗರಿಕರು ಅರ್ಜಿ ಶುಲ್ಕವನ್ನು ಪಾವತಿಸುತ್ತಾರೆ. ಯಶಸ್ವಿ ಪಾವತಿಯ ನಂತರ, ಅರ್ಜಿ ಕಾರ್ಯದರ್ಶಿ ಲಾಗಿನ್‌ಗೆ ಸಾಗುತ್ತದೆ.", "ಕಾರ್ಯದರ್ಶಿ ಲಾಗಿನ್ - ದಾಖಲೆ ಪರಿಶೀಲನೆ: ಕಾರ್ಯದರ್ಶಿ ದಾಖಲೆ ಪರಿಶೀಲನೆ ನಡೆಸುತ್ತಾರೆ ಮತ್ತು ಎರಡು ಆಯ್ಕೆಗಳಿರುತ್ತವೆ - ಅನುಮೋದಿಸು ಅಥವಾ ತಿರಸ್ಕರಿಸು. ತಿರಸ್ಕರಿಸಿದರೆ, ಅರ್ಜಿ ಅಂತಿಮವಾಗಿ ತಿರಸ್ಕೃತವಾಗಿದೆ ಎಂದು ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ. ಅನುಮೋದಿಸಿದರೆ, ಅದು ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆಗೆ ಸಾಗುತ್ತದೆ.", "ಕಾರ್ಯದರ್ಶಿ ಲಾಗಿನ್ - ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ: ಕಾರ್ಯದರ್ಶಿ ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ ನಡೆಸಿ ಅನುಮೋದಿಸುತ್ತಾರೆ. ಅನುಮೋದನೆಯ ನಂತರ, ಅರ್ಜಿ ಆಕ್ಷೇಪಣೆ ಎತ್ತುವ ಹಂತಕ್ಕೆ ಸಾಗುತ್ತದೆ.", "ಕಾರ್ಯದರ್ಶಿ ಲಾಗಿನ್ - ಆಕ್ಷೇಪಣೆ ಎತ್ತುವುದು: ಕಾರ್ಯದರ್ಶಿ ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸಿ ಅಗತ್ಯವಿದ್ದರೆ ಆಕ್ಷೇಪಣೆ ಎತ್ತುತ್ತಾರೆ (ಇಲ್ಲಿ ಇರುವ ಏಕೈಕ ಆಯ್ಕೆ ಅನುಮೋದನೆ). ಅನುಮೋದನೆಯ ನಂತರ, ಅರ್ಜಿ PDO ಲಾಗಿನ್‌ಗೆ ಸಾಗುತ್ತದೆ.", "PDO ಲಾಗಿನ್ - ಅರ್ಜಿ ಅನುಮೋದನೆ / ತಿರಸ್ಕರಣೆ: PDO ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸುತ್ತಾರೆ ಮತ್ತು ಎರಡು ಆಯ್ಕೆಗಳಿರುತ್ತವೆ - ಅನುಮೋದಿಸು ಅಥವಾ ತಿರಸ್ಕರಿಸು. ತಿರಸ್ಕರಿಸಿದರೆ, ಅದು ಅಂತಿಮವಾಗಿ ತಿರಸ್ಕೃತವಾಗಿದೆ ಎಂದು ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ. ಅನುಮೋದಿಸಿದರೆ, PDO ನಿರ್ಧರಿಸಿದ ಸೇವಾ ಶುಲ್ಕವನ್ನು ನಮೂದಿಸುತ್ತಾರೆ.", "ನಾಗರಿಕರು - ಸೇವಾ ಶುಲ್ಕ ಪಾವತಿ: ನಾಗರಿಕರು ನಿರ್ಧರಿಸಿದ ಸೇವಾ ಶುಲ್ಕವನ್ನು ನೋಡಿ ಅರ್ಜಿಗಾಗಿ ಪಾವತಿಸುತ್ತಾರೆ.", "PDO ಲಾಗಿನ್ - DSC / ಡಿಜಿಟಲ್ ಸಹಿ: ಸೇವಾ ಶುಲ್ಕ ಪಾವತಿಯ ನಂತರ, ಅರ್ಜಿ DSCಗಾಗಿ PDOಗೆ ಸಾಗುತ್ತದೆ. PDO ಪ್ರಮಾಣಪತ್ರಕ್ಕೆ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡುತ್ತಾರೆ ಮತ್ತು ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡಿದ ಪ್ರಮಾಣಪತ್ರವನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಬಹುದು.", "ನಾಗರಿಕರು - ಪೂರ್ಣಗೊಂಡ ಅರ್ಜಿಯನ್ನು ಸ್ವೀಕರಿಸುವುದು: ನಾಗರಿಕರು ಪೂರ್ಣಗೊಂಡ ಅರ್ಜಿ/ಸೇವಾ ಫಲಿತಾಂಶವನ್ನು ಸ್ವೀಕರಿಸುತ್ತಾರೆ.", "ನಾಗರಿಕರು - ಪ್ರತಿಕ್ರಿಯೆ: ಸೇವಾ ಫಲಿತಾಂಶವನ್ನು ಸ್ವೀಕರಿಸಿದ ನಂತರ ನಾಗರಿಕರು ಪ್ರತಿಕ್ರಿಯೆ ಫಾರ್ಮ್ ಅನ್ನು ಸಲ್ಲಿಸುತ್ತಾರೆ."]', 1, '["ಕಟ್ಟಡ ರೇಖಾಚಿತ್ರ", "ಇ-ಸ್ವಾತು ಸ್ವರೂಪ (ಫಾರ್ಮ್ 9/11A/11B)", "ಅಂದಾಜು ಪ್ರತಿ", "ಸ್ಥಳೀಯ ಯೋಜನಾ ಪ್ರಾಧಿಕಾರದ ಪ್ರಾರಂಭ ಪತ್ರ"]', NULL, NULL, '2783');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('792f5374-01ef-438b-8707-e11698dc9683', 'RURAL-DEVELOPMENT-AN-6', 'd1a5f9ed-d991-4f3a-81be-0215ecf4e378', 'Occupancy Certificate', 'Property Related', 0, 'Occupancy certificate issued by Grama Panchayat, declares that the building is constructed as per the plans approved by the concerned authorities.', '["Completion Certificate"]', '["Owner/authorized applicant of a completed building."]', '[]', '["Citizen drafts the application.", "Applicant submits the application.", "Stage 1 - Document Verification is carried out. If Rejected -> application is returned to the citizen/applicant (process ends). If Approved -> proceeds to Stage 2.", "Stage 2 - Field Verification Report is prepared.", "Stage 3 - Application goes for Approval. If Rejected -> application is returned to the citizen/applicant (process ends). If Approved -> proceeds.", "Citizen pays the Service Fee.", "Stage 4 - Digital Signature is applied by the authorised officer.", "Service is Completed."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಆಕ್ಯುಪೆನ್ಸಿ ಪ್ರಮಾಣಪತ್ರ', 'Occupancy certificate is issued when a property is ready to be occupied.', NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, NULL, NULL, 'ಗ್ರಾಮ ಪಂಚಾಯತ್ ನೀಡುವ ಆಕ್ಯುಪೆನ್ಸಿ ಪ್ರಮಾಣಪತ್ರವು, ಸಂಬಂಧಪಟ್ಟ ಅಧಿಕಾರಿಗಳು ಅನುಮೋದಿಸಿದ ಯೋಜನೆಗಳ ಪ್ರಕಾರ ಕಟ್ಟಡವನ್ನು ನಿರ್ಮಿಸಲಾಗಿದೆ ಎಂದು ಘೋಷಿಸುತ್ತದೆ.', NULL, NULL, NULL, NULL, 'Sakala', '["ಪೂರ್ಣಗೊಂಡ ಕಟ್ಟಡದ ಮಾಲೀಕ/ಅಧಿಕೃತ ಅರ್ಜಿದಾರ."]', '["ನಾಗರಿಕರು ಅರ್ಜಿಯ ಕರಡು ಸಿದ್ಧಪಡಿಸುತ್ತಾರೆ.", "ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸುತ್ತಾರೆ.", "ಹಂತ 1 - ದಾಖಲೆ ಪರಿಶೀಲನೆ ನಡೆಸಲಾಗುತ್ತದೆ. ತಿರಸ್ಕರಿಸಿದರೆ -> ಅರ್ಜಿಯನ್ನು ನಾಗರಿಕ/ಅರ್ಜಿದಾರರಿಗೆ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ (ಪ್ರಕ್ರಿಯೆ ಮುಗಿಯುತ್ತದೆ). ಅನುಮೋದಿಸಿದರೆ -> ಹಂತ 2ಕ್ಕೆ ಮುಂದುವರಿಯುತ್ತದೆ.", "ಹಂತ 2 - ಕ್ಷೇತ್ರ ಪರಿಶೀಲನಾ ವರದಿಯನ್ನು ಸಿದ್ಧಪಡಿಸಲಾಗುತ್ತದೆ.", "ಹಂತ 3 - ಅರ್ಜಿಯನ್ನು ಅನುಮೋದನೆಗಾಗಿ ಕಳುಹಿಸಲಾಗುತ್ತದೆ. ತಿರಸ್ಕರಿಸಿದರೆ -> ಅರ್ಜಿಯನ್ನು ನಾಗರಿಕ/ಅರ್ಜಿದಾರರಿಗೆ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ. ಅನುಮೋದಿಸಿದರೆ -> ಮುಂದುವರಿಯುತ್ತದೆ.", "ನಾಗರಿಕರು ಸೇವಾ ಶುಲ್ಕವನ್ನು ಪಾವತಿಸುತ್ತಾರೆ.", "ಹಂತ 4 - ಅಧಿಕೃತ ಅಧಿಕಾರಿ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡುತ್ತಾರೆ.", "ಸೇವೆ ಪೂರ್ಣಗೊಳ್ಳುತ್ತದೆ."]', 1, '["ಪೂರ್ಣಗೊಳಿಸುವಿಕೆಯ ಪ್ರಮಾಣಪತ್ರ"]', NULL, NULL, '2243');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('813c3656-c506-4177-bb31-617b21ed331a', 'REVENUE-DEPARTMENT-105', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'KAVAL PODI TIPPAN', 'General', 0, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (KAVAL PODI TIPPAN)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಕಾವಲ್ ಪೋಡಿ ಟಿಪ್ಪಣಿ', NULL, NULL, NULL, NULL, NULL, 35.00, NULL, 'ಕಾವಲ್ ಪೋಡಿ ಟಿಪ್ಪಣಿ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3149');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('dd9b12a6-691f-4903-a1b8-e474eeb31bae', 'RURAL-DEVELOPMENT-AN-10', 'd1a5f9ed-d991-4f3a-81be-0215ecf4e378', 'Road Cutting Permission', 'Business Related', 0, 'Any Individual/Organisation who wish to cut the road in the Grama Panchayat jurisdiction needs to take the permission from Grama Panchayat Office.', '["Tax Paid Receipt", "E-Swathu Form", "Location Map"]', '["Applicant requiring road cutting for authorized construction or utility work."]', '[]', '["Citizen drafts the application.", "Applicant submits the application.", "Stage 1 - Document Verification is carried out. If Rejected -> application is returned to the citizen/applicant (process ends). If Approved -> proceeds to Stage 2.", "Stage 2 - Field Verification Report is prepared.", "Stage 3 - Application goes for Approval. If Rejected -> application is returned to the citizen/applicant (process ends). If Approved -> proceeds.", "Citizen pays the Service Fee.", "Stage 4 - Digital Signature is applied by the authorised officer.", "Service is Completed."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ರಸ್ತೆ ಕತ್ತರಿಸುವ ಅನುಮತಿ', 'Application for the permission of Road Cutting.', NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, NULL, NULL, 'ಗ್ರಾಮ ಪಂಚಾಯಿತಿ ವ್ಯಾಪ್ತಿಯಲ್ಲಿ ರಸ್ತೆ ಕತ್ತರಿಸಲು ಬಯಸುವ ಯಾವುದೇ ವ್ಯಕ್ತಿ/ಸಂಸ್ಥೆಯು ಗ್ರಾಮ ಪಂಚಾಯಿತಿ ಕಚೇರಿಯಿಂದ ಅನುಮತಿ ಪಡೆಯಬೇಕು.', NULL, NULL, NULL, NULL, 'Sakala', '["ಅಧಿಕೃತ ನಿರ್ಮಾಣ ಅಥವಾ ಉಪಯುಕ್ತತೆ ಕಾಮಗಾರಿಗಾಗಿ ರಸ್ತೆ ಕತ್ತರಿಸುವಿಕೆ ಅಗತ್ಯವಿರುವ ಅರ್ಜಿದಾರ."]', '["ನಾಗರಿಕರು ಅರ್ಜಿಯ ಕರಡು ಸಿದ್ಧಪಡಿಸುತ್ತಾರೆ.", "ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸುತ್ತಾರೆ.", "ಹಂತ 1 - ದಾಖಲೆ ಪರಿಶೀಲನೆ ನಡೆಸಲಾಗುತ್ತದೆ. ತಿರಸ್ಕರಿಸಿದರೆ -> ಅರ್ಜಿಯನ್ನು ನಾಗರಿಕ/ಅರ್ಜಿದಾರರಿಗೆ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ (ಪ್ರಕ್ರಿಯೆ ಮುಗಿಯುತ್ತದೆ). ಅನುಮೋದಿಸಿದರೆ -> ಹಂತ 2ಕ್ಕೆ ಮುಂದುವರಿಯುತ್ತದೆ.", "ಹಂತ 2 - ಕ್ಷೇತ್ರ ಪರಿಶೀಲನಾ ವರದಿಯನ್ನು ಸಿದ್ಧಪಡಿಸಲಾಗುತ್ತದೆ.", "ಹಂತ 3 - ಅರ್ಜಿಯನ್ನು ಅನುಮೋದನೆಗಾಗಿ ಕಳುಹಿಸಲಾಗುತ್ತದೆ. ತಿರಸ್ಕರಿಸಿದರೆ -> ಅರ್ಜಿಯನ್ನು ನಾಗರಿಕ/ಅರ್ಜಿದಾರರಿಗೆ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ. ಅನುಮೋದಿಸಿದರೆ -> ಮುಂದುವರಿಯುತ್ತದೆ.", "ನಾಗರಿಕರು ಸೇವಾ ಶುಲ್ಕವನ್ನು ಪಾವತಿಸುತ್ತಾರೆ.", "ಹಂತ 4 - ಅಧಿಕೃತ ಅಧಿಕಾರಿ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡುತ್ತಾರೆ.", "ಸೇವೆ ಪೂರ್ಣಗೊಳ್ಳುತ್ತದೆ."]', 1, '["ತೆರಿಗೆ ಪಾವತಿಸಿದ ರಶೀದಿ", "ಇ-ಸ್ವಾತು ಫಾರ್ಮ್", "ಸ್ಥಳ ನಕ್ಷೆ"]', NULL, NULL, '1943');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('01fccbc2-95b1-41c7-8c4a-49604c8eeadf', 'RURAL-DEVELOPMENT-AN-5', 'd1a5f9ed-d991-4f3a-81be-0215ecf4e378', 'Demolition of Building', 'Property Related', 0, 'Building Licence is a type of authorization that is issued by the Grama Panchayat before the Demolition of Building for the Residence,Commercial and Non-residential Purposes.', '["Building Sketch", "E-Swathu Format (Form 9/11A/11B)", "Estimate Copy", "Commencement Letter of Local Planning Authority"]', '["Property owner / Authorized applicant with valid property/ownership documents."]', '[]', '["Citizen & BSK Portal - Application Filling and Submission: Citizen fills the application in 6 steps, uploads the required documents, and submits the application through the BSK Portal.", "Application Fee Payment: Citizen pays the application fee. After successful payment, the application moves to Secretary Login.", "Secretary Login - Document Verification: Secretary performs document verification and has two options - Approve or Reject. If rejected, the application is considered finally rejected. If approved, it moves to Field Verification.", "Secretary Login - Field Verification: Secretary performs and approves the field verification. After approval, the application moves to Raise Objection.", "Secretary Login - Raise Objection: Secretary reviews the application and raises an objection if required (only option here is Approve). After approval, the application moves to PDO Login.", "PDO Login - Application Approval / Rejection: PDO reviews the application and has two options - Approve or Reject. If rejected, it is considered finally rejected. If approved, PDO enters the decided service fee.", "Citizen - Service Fee Payment: Citizen views the decided service fee and pays it for the application.", "PDO Login - DSC / Digital Signature: After service fee payment, the application moves to PDO for DSC. PDO digitally signs the certificate and can download the digitally signed certificate.", "Citizen - Receive Completed Application: Citizen receives the completed application/service result.", "Citizen - Feedback: Citizen submits the feedback form after receiving the service result."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಕಟ್ಟಡ ಕೆಡವುವಿಕೆ', 'Apply for Permission to Demolition of old Building.', NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, NULL, NULL, 'ಕಟ್ಟಡ ಪರವಾನಗಿಯು ನಿವಾಸ, ವಾಣಿಜ್ಯ ಮತ್ತು ವಸತಿಯೇತರ ಉದ್ದೇಶಗಳಿಗಾಗಿ ಕಟ್ಟಡವನ್ನು ಕೆಡವುವ ಮೊದಲು ಗ್ರಾಮ ಪಂಚಾಯತ್ ನೀಡುವ ಒಂದು ರೀತಿಯ ಅಧಿಕಾರ ಪತ್ರವಾಗಿದೆ.', NULL, NULL, NULL, NULL, 'Sakala', '["ಮಾನ್ಯ ಆಸ್ತಿ/ಮಾಲೀಕತ್ವದ ದಾಖಲೆಗಳನ್ನು ಹೊಂದಿರುವ ಆಸ್ತಿ ಮಾಲೀಕ / ಅಧಿಕೃತ ಅರ್ಜಿದಾರ."]', '["ನಾಗರಿಕ ಮತ್ತು BSK ಪೋರ್ಟಲ್ - ಅರ್ಜಿ ಭರ್ತಿ ಮತ್ತು ಸಲ್ಲಿಕೆ: ನಾಗರಿಕರು 6 ಹಂತಗಳಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಭರ್ತಿ ಮಾಡಿ, ಅಗತ್ಯ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ, BSK ಪೋರ್ಟಲ್ ಮೂಲಕ ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸುತ್ತಾರೆ.", "ಅರ್ಜಿ ಶುಲ್ಕ ಪಾವತಿ: ನಾಗರಿಕರು ಅರ್ಜಿ ಶುಲ್ಕವನ್ನು ಪಾವತಿಸುತ್ತಾರೆ. ಯಶಸ್ವಿ ಪಾವತಿಯ ನಂತರ, ಅರ್ಜಿ ಕಾರ್ಯದರ್ಶಿ ಲಾಗಿನ್‌ಗೆ ಸಾಗುತ್ತದೆ.", "ಕಾರ್ಯದರ್ಶಿ ಲಾಗಿನ್ - ದಾಖಲೆ ಪರಿಶೀಲನೆ: ಕಾರ್ಯದರ್ಶಿ ದಾಖಲೆ ಪರಿಶೀಲನೆ ನಡೆಸುತ್ತಾರೆ ಮತ್ತು ಎರಡು ಆಯ್ಕೆಗಳಿರುತ್ತವೆ - ಅನುಮೋದಿಸು ಅಥವಾ ತಿರಸ್ಕರಿಸು. ತಿರಸ್ಕರಿಸಿದರೆ, ಅರ್ಜಿ ಅಂತಿಮವಾಗಿ ತಿರಸ್ಕೃತವಾಗಿದೆ ಎಂದು ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ. ಅನುಮೋದಿಸಿದರೆ, ಅದು ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆಗೆ ಸಾಗುತ್ತದೆ.", "ಕಾರ್ಯದರ್ಶಿ ಲಾಗಿನ್ - ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ: ಕಾರ್ಯದರ್ಶಿ ಕ್ಷೇತ್ರ ಪರಿಶೀಲನೆ ನಡೆಸಿ ಅನುಮೋದಿಸುತ್ತಾರೆ. ಅನುಮೋದನೆಯ ನಂತರ, ಅರ್ಜಿ ಆಕ್ಷೇಪಣೆ ಎತ್ತುವ ಹಂತಕ್ಕೆ ಸಾಗುತ್ತದೆ.", "ಕಾರ್ಯದರ್ಶಿ ಲಾಗಿನ್ - ಆಕ್ಷೇಪಣೆ ಎತ್ತುವುದು: ಕಾರ್ಯದರ್ಶಿ ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸಿ ಅಗತ್ಯವಿದ್ದರೆ ಆಕ್ಷೇಪಣೆ ಎತ್ತುತ್ತಾರೆ (ಇಲ್ಲಿ ಇರುವ ಏಕೈಕ ಆಯ್ಕೆ ಅನುಮೋದನೆ). ಅನುಮೋದನೆಯ ನಂತರ, ಅರ್ಜಿ PDO ಲಾಗಿನ್‌ಗೆ ಸಾಗುತ್ತದೆ.", "PDO ಲಾಗಿನ್ - ಅರ್ಜಿ ಅನುಮೋದನೆ / ತಿರಸ್ಕರಣೆ: PDO ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸುತ್ತಾರೆ ಮತ್ತು ಎರಡು ಆಯ್ಕೆಗಳಿರುತ್ತವೆ - ಅನುಮೋದಿಸು ಅಥವಾ ತಿರಸ್ಕರಿಸು. ತಿರಸ್ಕರಿಸಿದರೆ, ಅದು ಅಂತಿಮವಾಗಿ ತಿರಸ್ಕೃತವಾಗಿದೆ ಎಂದು ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ. ಅನುಮೋದಿಸಿದರೆ, PDO ನಿರ್ಧರಿಸಿದ ಸೇವಾ ಶುಲ್ಕವನ್ನು ನಮೂದಿಸುತ್ತಾರೆ.", "ನಾಗರಿಕರು - ಸೇವಾ ಶುಲ್ಕ ಪಾವತಿ: ನಾಗರಿಕರು ನಿರ್ಧರಿಸಿದ ಸೇವಾ ಶುಲ್ಕವನ್ನು ನೋಡಿ ಅರ್ಜಿಗಾಗಿ ಪಾವತಿಸುತ್ತಾರೆ.", "PDO ಲಾಗಿನ್ - DSC / ಡಿಜಿಟಲ್ ಸಹಿ: ಸೇವಾ ಶುಲ್ಕ ಪಾವತಿಯ ನಂತರ, ಅರ್ಜಿ DSCಗಾಗಿ PDOಗೆ ಸಾಗುತ್ತದೆ. PDO ಪ್ರಮಾಣಪತ್ರಕ್ಕೆ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡುತ್ತಾರೆ ಮತ್ತು ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡಿದ ಪ್ರಮಾಣಪತ್ರವನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಬಹುದು.", "ನಾಗರಿಕರು - ಪೂರ್ಣಗೊಂಡ ಅರ್ಜಿಯನ್ನು ಸ್ವೀಕರಿಸುವುದು: ನಾಗರಿಕರು ಪೂರ್ಣಗೊಂಡ ಅರ್ಜಿ/ಸೇವಾ ಫಲಿತಾಂಶವನ್ನು ಸ್ವೀಕರಿಸುತ್ತಾರೆ.", "ನಾಗರಿಕರು - ಪ್ರತಿಕ್ರಿಯೆ: ಸೇವಾ ಫಲಿತಾಂಶವನ್ನು ಸ್ವೀಕರಿಸಿದ ನಂತರ ನಾಗರಿಕರು ಪ್ರತಿಕ್ರಿಯೆ ಫಾರ್ಮ್ ಅನ್ನು ಸಲ್ಲಿಸುತ್ತಾರೆ."]', 1, '["ಕಟ್ಟಡ ರೇಖಾಚಿತ್ರ", "ಇ-ಸ್ವಾತು ಸ್ವರೂಪ (ಫಾರ್ಮ್ 9/11A/11B)", "ಅಂದಾಜು ಪ್ರತಿ", "ಸ್ಥಳೀಯ ಯೋಜನಾ ಪ್ರಾಧಿಕಾರದ ಪ್ರಾರಂಭ ಪತ್ರ"]', NULL, NULL, '2785');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('5e6acc55-8c03-4e14-9dd3-d2ebd2871baa', 'ENERGY-DEPARTMENT-11', 'e0b8deb9-4426-4525-a8e5-aab3f707df7c', 'Line breakdown- Rural areas', 'General', 0, '', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '665dc58e-475b-4883-93a4-8761c3bf0063', 'ವಿದ್ಯುತ್', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3008');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('69d69d85-6ea3-4944-b25c-3c3b929aa7d0', 'DEPARTMENT-OF-ELECTR-29', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Recruitment Assistance', 'General', 60, 'GoK will provide recruitment assistance to GCCs that are setting up new operations or expanding existing ones in the Beyond Bengaluru area.', '["i. CA-certified letter on expenditure incurred towards ‘Rental Reimbursement’, comprising a break-up of the total Recruitment Assistance Cost (as applicable):", "a. Advertisement/communication for inviting applications for new employment (which may include print, paid social media, or other digital platforms)", "b. Recruitment consultants/agencies", "c. Campus visits", "d. Total new employees selected under the Recruitment Assistance Incentive", "e. Total boarding and lodging cost", "ii. Copy of original invoices, bills for the expenses incurred (as applicable)."]', '["Applicable to New GCCs setting up with 100+ employees in Beyond Bengaluru District", "The No. of employees recruited shall be new unique employment created by the GCC.", "The Expenses shall be Fee paid to recruitment agencies and/ or participation fee in campus programs.", "The Applicant shall avail the incentive only once under the Policy.", "Claim for reimbursement shall be filed before the end of 12 months from the date of commencement of commercial operations."]', '[]', '["The applicant Company should be registered with KITS under GCC Policy 2024-29", "Company should submit the incentive application along with supporting documents as prescribed in the OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/gcc/recruitment-assistance', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ನೇಮಕಾತಿ ಸಹಾಯಧನ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '"ಬಿಯಾಂಡ್ ಬೆಂಗಳೂರು" ಪ್ರದೇಶದಲ್ಲಿ ಹೊಸ ಕಾರ್ಯಾಚರಣೆಗಳನ್ನು ಸ್ಥಾಪಿಸುವ ಅಥವಾ ಪ್ರಸ್ತುತ ಇರುವ ಕಾರ್ಯಾಚರಣೆಗಳನ್ನು ವಿಸ್ತರಿಸುವ GCC ಗಳಿಗೆ ಕರ್ನಾಟಕ ಸರ್ಕಾರವು ನೇಮಕಾತಿ ನೆರವನ್ನು ನೀಡುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಬೆಂಗಳೂರು ಹೊರವಲಯ ಜಿಲ್ಲೆಗಳಲ್ಲಿ 100 ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ಉದ್ಯೋಗಿಗಳನ್ನು ಹೊಂದಿರುವ ಹೊಸದಾಗಿ ಸ್ಥಾಪಿಸಲಾದ ಜಾಗತಿಕ ಸಾಮರ್ಥ್ಯ ಕೇಂದ್ರಗಳಿಗೆ (GCCs) ಅನ್ವಯಿಸುತ್ತದೆ.", "ನೇಮಕಗೊಂಡ ಉದ್ಯೋಗಿಗಳ ಸಂಖ್ಯೆಯು ಜಿಸಿಸಿ (GCC) ಯಿಂದ ಹೊಸದಾಗಿ ಸೃಷ್ಟಿಸಲಾದ ವಿಶಿಷ್ಟ (Unique) ಉದ್ಯೋಗಗಳಾಗಿರಬೇಕು.", "ಮರುಪಾವತಿಗೆ ಪರಿಗಣಿಸಲ್ಪಡುವ ವೆಚ್ಚಗಳಲ್ಲಿ ನೇಮಕಾತಿ ಸಂಸ್ಥೆಗಳಿಗೆ (Recruitment Agencies) ಪಾವತಿಸಿದ ಶುಲ್ಕ ಮತ್ತು/ಅಥವಾ ಕ್ಯಾಂಪಸ್ ನೇಮಕಾತಿ ಕಾರ್ಯಕ್ರಮಗಳಲ್ಲಿ (Campus Recruitment Programs) ಭಾಗವಹಿಸಲು ಪಾವತಿಸಿದ ಶುಲ್ಕ ಒಳಗೊಂಡಿರುತ್ತದೆ.", "ಅರ್ಜಿದಾರರು ಈ ನೀತಿಯಡಿ ನೇಮಕಾತಿ ಸಹಾಯಧನ ಪ್ರೋತ್ಸಾಹಧನವನ್ನು ಕೇವಲ ಒಂದು ಬಾರಿ ಮಾತ್ರ ಪಡೆಯಲು ಅರ್ಹರಾಗಿರುತ್ತಾರೆ.", "ಮರುಪಾವತಿಗಾಗಿ ಅರ್ಜಿಯನ್ನು ವಾಣಿಜ್ಯ ಕಾರ್ಯಾಚರಣೆ ಆರಂಭಗೊಂಡ ದಿನಾಂಕದಿಂದ ಹನ್ನೆರಡು (12) ತಿಂಗಳೊಳಗೆ ಸಲ್ಲಿಸಬೇಕು."]', '["ಅರ್ಜಿದಾರ ಕಂಪನಿಯು GCC ನೀತಿಯಡಿ ಕರ್ನಾಟಕ ನವೋದ್ಯಮ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ಯಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["ನೇಮಕಾತಿ ಸಹಾಯಧನಕ್ಕೆ ಸಂಬಂಧಿಸಿದಂತೆ ಉಂಟಾದ ವೆಚ್ಚಗಳ ವಿವರಗಳನ್ನು ಒಳಗೊಂಡ ಚಾರ್ಟರ್ಡ್ ಅಕೌಂಟೆಂಟ್ (CA) ದೃಢೀಕರಿಸಿದ ಪತ್ರ, ಇದರಲ್ಲಿ ಒಟ್ಟು ನೇಮಕಾತಿ ಸಹಾಯಧನ ವೆಚ್ಚದ ವಿಭಾಗವಾರು ವಿವರಗಳು (ಅನ್ವಯವಾಗುವಂತೆ) ಒಳಗೊಂಡಿರಬೇಕು:", "a. ಹೊಸ ಉದ್ಯೋಗಗಳ ನೇಮಕಾತಿಗಾಗಿ ಅರ್ಜಿಗಳನ್ನು ಆಹ್ವಾನಿಸಲು ನೀಡಿದ ಜಾಹೀರಾತು/ಸಂವಹನ ವೆಚ್ಚಗಳು (ಮುದ್ರಣ ಮಾಧ್ಯಮ, ಪಾವತಿಸಿದ ಸಾಮಾಜಿಕ ಮಾಧ್ಯಮ ಅಥವಾ ಇತರೆ ಡಿಜಿಟಲ್ ವೇದಿಕೆಗಳನ್ನು ಒಳಗೊಂಡಂತೆ).", "b. ನೇಮಕಾತಿ ಸಲಹೆಗಾರರು / ನೇಮಕಾತಿ ಸಂಸ್ಥೆಗಳಿಗೆ (Recruitment Consultants/Agencies) ಪಾವತಿಸಿದ ಶುಲ್ಕ.", "c. ಕ್ಯಾಂಪಸ್ ನೇಮಕಾತಿ ಭೇಟಿಗಳಿಗೆ ಸಂಬಂಧಿಸಿದ ವೆಚ್ಚಗಳು.", "d. ನೇಮಕಾತಿ ಸಹಾಯಧನ ಪ್ರೋತ್ಸಾಹಧನದಡಿ ಆಯ್ಕೆಯಾದ ಒಟ್ಟು ಹೊಸ ಉದ್ಯೋಗಿಗಳ ಸಂಖ್ಯೆ.", "e. ಒಟ್ಟು ವಸತಿ ಮತ್ತು ಊಟ (Boarding & Lodging) ವೆಚ್ಚ.", "ಉಂಟಾದ ವೆಚ್ಚಗಳಿಗೆ ಸಂಬಂಧಿಸಿದ ಮೂಲ ಸರಕುಪಟ್ಟಿಗಳು (Invoices) ಮತ್ತು ಬಿಲ್ಲುಗಳ ಪ್ರತಿಗಳು (ಅನ್ವಯವಾಗುವಂತೆ)."]', NULL, NULL, NULL);
