INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('9780b07d-e3b6-442a-b7ed-c3990d535ab6', 'REVENUE-DEPARTMENT-111', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'BHAGAYTHU TAKTHA', 'General', 0, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (BHAGAYTHU TAKTHA)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಬಾಗಾಯತ್ ತಖ್ತಾ', NULL, NULL, NULL, NULL, NULL, 35.00, NULL, 'ಬಾಗಾಯತ್ ತಖ್ತಾ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3156');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('22789a47-0697-4d7d-b9c3-94db2705b1c6', 'DEPARTMENT-OF-ELECTR-25', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Property Tax Reimbursement', 'General', 60, 'GoK will provide reimbursement of property tax for GCCs operating in Beyond Bengaluru District area', '["Property ownership (sale deed, lease agreement, or equivalent) of the GCC unit that owns the property and had paid the property tax in its own name.", "Property tax payment receipts for the claim period (only applicable for a period of 3 years from the commencement of GCC operations)", "Property tax assessment notices issued by the competitive authority.", "CA Certified letter verifying the total property tax paid during the claim period."]', '["Applicable to New GCCs setting up with 100+ employees in Beyond Bengaluru District", "The Applicant shall have completed at least 1 years of commercial operations.", "Reimbursement of property tax shall be applicable only to the GCC unit that owns the property and has paid the property tax in its own name. A self-declaration confirming ownership and tax payment must be submitted on the applicant’s official letterhead."]', '[]', '["The applicant Company should be registered with KITS under GCC Policy 2024-29", "Company should submit the incentive application along with supporting documents as prescribed in the OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/gcc/property-tax-reimbursement', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಆಸ್ತಿ ತೆರಿಗೆ ಮರುಪಾವತಿ ಪ್ರೋತ್ಸಾಹಧನ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '"ಬಿಯಾಂಡ್ ಬೆಂಗಳೂರು" ಜಿಲ್ಲಾ ಪ್ರದೇಶದಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿರುವ GCC ಗಳಿಗೆ ಕರ್ನಾಟಕ ಸರ್ಕಾರವು ಆಸ್ತಿ ತೆರಿಗೆಯ ಮರುಪಾವತಿಯನ್ನು ನೀಡುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಬೆಂಗಳೂರು ಹೊರವಲಯ ಜಿಲ್ಲೆಗಳಲ್ಲಿ 100 ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ಉದ್ಯೋಗಿಗಳನ್ನು ಹೊಂದಿರುವ ಹೊಸದಾಗಿ ಸ್ಥಾಪಿಸಲಾದ ಜಾಗತಿಕ ಸಾಮರ್ಥ್ಯ ಕೇಂದ್ರಗಳಿಗೆ (GCCs) ಅನ್ವಯಿಸುತ್ತದೆ.", "ಅರ್ಜಿದಾರರು ಕನಿಷ್ಠ ಒಂದು (1) ವರ್ಷದ ವಾಣಿಜ್ಯ ಕಾರ್ಯಾಚರಣೆಯನ್ನು ಪೂರ್ಣಗೊಳಿಸಿರಬೇಕು.", "ಆಸ್ತಿ ತೆರಿಗೆ ಮರುಪಾವತಿಯು ತನ್ನ ಸ್ವಂತ ಹೆಸರಿನಲ್ಲಿ ಆಸ್ತಿಯನ್ನು ಹೊಂದಿರುವ ಹಾಗೂ ತನ್ನ ಹೆಸರಿನಲ್ಲಿಯೇ ಆಸ್ತಿ ತೆರಿಗೆಯನ್ನು ಪಾವತಿಸಿರುವ ಜಿಸಿಸಿ (GCC) ಘಟಕಕ್ಕೆ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ. ಅರ್ಜಿದಾರರು ಆಸ್ತಿಯ ಮಾಲೀಕತ್ವ ಮತ್ತು ಆಸ್ತಿ ತೆರಿಗೆ ಪಾವತಿಯನ್ನು ದೃಢೀಕರಿಸುವ ಸ್ವಯಂ ಘೋಷಣಾಪತ್ರವನ್ನು ಸಂಸ್ಥೆಯ ಅಧಿಕೃತ ಲೆಟರ್"]', '["ಅರ್ಜಿದಾರ ಕಂಪನಿಯು GCC ನೀತಿಯಡಿ ಕರ್ನಾಟಕ ನವೋದ್ಯಮ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ಯಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["ತನ್ನ ಸ್ವಂತ ಹೆಸರಿನಲ್ಲಿ ಆಸ್ತಿಯನ್ನು ಹೊಂದಿದ್ದು, ಆಸ್ತಿ ತೆರಿಗೆಯನ್ನು ತನ್ನ ಹೆಸರಿನಲ್ಲಿಯೇ ಪಾವತಿಸಿರುವ ಜಿಸಿಸಿ (GCC) ಘಟಕದ ಆಸ್ತಿ ಮಾಲೀಕತ್ವದ ದಾಖಲೆಗಳಾದ ಮಾರಾಟ ಪತ್ರ (Sale Deed), ಗುತ್ತಿಗೆ ಒಪ್ಪಂದ (Lease Agreement) ಅಥವಾ ಸಮಾನ ದಾಖಲೆಗಳ ಪ್ರತಿಗಳು.", "ಹಕ್ಕು ಕೋರಿರುವ ಅವಧಿಗೆ ಸಂಬಂಧಿಸಿದ ಆಸ್ತಿ ತೆರಿಗೆ ಪಾವತಿ ರಸೀದಿಗಳ ಪ್ರತಿಗಳು (ಜಿಸಿಸಿ (GCC) ಕಾರ್ಯಾಚರಣೆ ಆರಂಭಗೊಂಡ ದಿನಾಂಕದಿಂದ ಮೂರು (3) ವರ್ಷಗಳ ಅವಧಿಗೆ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ).", "ಸಮರ್ಥ ಪ್ರಾಧಿಕಾರದಿಂದ (Competent Authority) ನೀಡಲಾದ ಆಸ್ತಿ ತೆರಿಗೆ ಮೌಲ್ಯಮಾಪನ ಅಧಿಸೂಚನೆಗಳ (Property Tax Assessment Notices) ಪ್ರತಿಗಳು.", "ಹಕ್ಕು ಕೋರಿರುವ ಅವಧಿಯಲ್ಲಿ ಪಾವತಿಸಲಾದ ಒಟ್ಟು ಆಸ್ತಿ ತೆರಿಗೆಯನ್ನು ದೃಢೀಕರಿಸುವ ಚಾರ್ಟರ್ಡ್ ಅಕೌಂಟೆಂಟ್ (CA) ದೃಢೀಕರಿಸಿದ ಪತ್ರ."]', NULL, NULL, NULL);
