INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('933103e6-885c-4c54-9982-6b7a94b336b8', 'REVENUE-DEPARTMENT-117', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', '2ND RECLASS PRATHI BOOK', 'General', 0, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (2ND RECLASS PRATHI BOOK)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಎರಡನೇ ರಿಕ್ಲಾಸಿಫಿಕೇಷನ್ ಪ್ರತಿ ಪುಸ್ತಕ', NULL, NULL, NULL, NULL, NULL, 100.00, NULL, 'ಎರಡನೇ ರಿಕ್ಲಾಸಿಫಿಕೇಷನ್ ಪ್ರತಿ ಪುಸ್ತಕ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3127');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('ce5e0c75-cb40-42a9-848c-fc6ea455ea88', 'DEPARTMENT-OF-ELECTR-24', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Power Tariff Concession', 'General', 60, 'GoK shall provide Power related incentive in the form of a Power Tariff Concession (PTC) for GCC entities registered with KITS', '["i. Copy of the Registration Certificate issued by KITS.", "ii. Self-attested copy of registered rent/ lease agreement", "iii. Self-attested copy of ESCOMs power service letter with R.R. No. and date", "iv. Self- attested copies of the last 3 months of electricity bills since the date of submission of the application", "v. Power Tariff Sanction Letter Copy (as applicable)", "vi. Copy of the letter / order - Electricity Duty Reimbursement (as applicable)", "vii. A self-attested copy on letterhead stating the reimbursement requested for the electricity duty (complete calculation along with the breakup) for the period being claimed."]', '["Applicable to New GCCs across Karnataka", "This incentive shall be in accordance with the enabling notification/ tariffs order from the Karnataka Electricity Regulatory Commission (KERC), Government of Karnataka, issued from time to time.", "The applicant or any of their associated subsidiary/affiliates should not be under litigation/Court Cases with respect to ESCOMs or Department of IT & Bt.", "In case the applicant is availing PTC, the following conditions shall be applicable:", "o Where RR No. is in the name of the applicant and the applicant is also the owner of the premise, the applicant shall be eligible for this incentive.", "o Where RR No. is not under applicant’s name but in the name of the developer / owner owning the premise and applicant is the sole occupant of the premise, the applicant shall be eligible for this incentive.", "o Where RR No. is in the name of the developer/ owner having multiple tenants and applicant being one of them and the applicant has a submeter installed by the ESCOM, then the applicant shall be eligible for this incentive.", "o Where RR No. is in the name of the developer/ owner having multiple tenants and applicant being one of them and the applicant is not having a submeter installed by the ESCOM, then the applicant shall not be eligible for this incentive."]', '[]', '["The applicant Company should be registered with KITS under GCC Policy 2024-29", "Company should submit the incentive application along with supporting documents as prescribed in the OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/gcc/power-tariff-concession', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ವಿದ್ಯುತ್ ದರ ರಿಯಾಯಿತಿ ಪ್ರೋತ್ಸಾಹಧನ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'KITS ನಲ್ಲಿ ನೋಂದಾಯಿತವಾದ GCC ಸಂಸ್ಥೆಗಳಿಗೆ ಕರ್ನಾಟಕ ಸರ್ಕಾರವು ವಿದ್ಯುತ್ ದರ ವಿನಾಯಿತಿ (Power Tariff Concession - PTC) ರೂಪದಲ್ಲಿ ವಿದ್ಯುತ್ ಸಂಬಂಧಿತ ಪ್ರೋತ್ಸಾಹಕವನ್ನು ಒದಗಿಸುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕದಾದ್ಯಂತ ಹೊಸದಾಗಿ ಸ್ಥಾಪಿಸಲಾದ ಜಾಗತಿಕ ಸಾಮರ್ಥ್ಯ ಕೇಂದ್ರಗಳಿಗೆ (GCCs) ಅನ್ವಯಿಸುತ್ತದೆ.", "ಈ ಪ್ರೋತ್ಸಾಹಧನವು ಕರ್ನಾಟಕ ಸರ್ಕಾರದ ಕರ್ನಾಟಕ ವಿದ್ಯುತ್ ನಿಯಂತ್ರಣ ಆಯೋಗ (KERC) ಕಾಲಕಾಲಕ್ಕೆ ಹೊರಡಿಸುವ ಸಕ್ರಿಯಗೊಳಿಸುವ ಅಧಿಸೂಚನೆ / ವಿದ್ಯುತ್ ದರ ಆದೇಶಗಳಿಗೆ ಅನುಗುಣವಾಗಿರುತ್ತದೆ.", "ಅರ್ಜಿದಾರರು ಅಥವಾ ಅವರ ಯಾವುದೇ ಅಂಗಸಂಸ್ಥೆಗಳು / ಸಹಸಂಸ್ಥೆಗಳು (Subsidiaries / Affiliates) ವಿದ್ಯುತ್ ಸರಬರಾಜು ಸಂಸ್ಥೆಗಳು (ESCOMs) ಅಥವಾ ಎಲೆಕ್ಟ್ರಾನಿಕ್ಸ್, ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ಮತ್ತು ಜೈವಿಕ ತಂತ್ರಜ್ಞಾನ ಇಲಾಖೆ (E, IT & Bt) ವಿರುದ್ಧ ಯಾವುದೇ ವ್ಯಾಜ್ಯ ಅಥವಾ ನ್ಯಾಯಾಲಯದ ಪ್ರಕರಣಗಳಲ್ಲಿ ತೊಡಗಿಸಿಕೊಂಡಿರಬಾರದು.", "ಅರ್ಜಿದಾರರು ವಿದ್ಯುತ್ ದರ ರಿಯಾಯಿತಿ (Power Tariff Concession - PTC) ಪಡೆಯುತ್ತಿರುವಲ್ಲಿ, ಕೆಳಕಂಡ ಷರತ್ತುಗಳು ಅನ್ವಯವಾಗುತ್ತವೆ:", "I. ಆರ್.ಆರ್. ಸಂಖ್ಯೆ (RR No.) ಅರ್ಜಿದಾರರ ಹೆಸರಿನಲ್ಲಿದ್ದು, ಅರ್ಜಿದಾರರು ಕಟ್ಟಡದ ಮಾಲೀಕರಾಗಿದ್ದರೆ, ಅವರು ಈ ಪ್ರೋತ್ಸಾಹಧನಕ್ಕೆ ಅರ್ಹರಾಗಿರುತ್ತಾರೆ.", "II. ಆರ್.ಆರ್. ಸಂಖ್ಯೆ (RR No.) ಅರ್ಜಿದಾರರ ಹೆಸರಿನಲ್ಲಿರದೆ, ಕಟ್ಟಡದ ಮಾಲೀಕ/ಅಭಿವೃದ್ಧಿಪಡಿಸುವವರ ಹೆಸರಿನಲ್ಲಿದ್ದು, ಅರ್ಜಿದಾರರು ಆ ಕಟ್ಟಡದ ಏಕೈಕ ಬಳಕೆದಾರರಾಗಿದ್ದರೆ, ಅವರು ಈ ಪ್ರೋತ್ಸಾಹಧನಕ್ಕೆ ಅರ್ಹರಾಗಿರುತ್ತಾರೆ.", "III. ಆರ್.ಆರ್. ಸಂಖ್ಯೆ (RR No.) ಕಟ್ಟಡದ ಮಾಲೀಕ/ಅಭಿವೃದ್ಧಿಪಡಿಸುವವರ ಹೆಸರಿನಲ್ಲಿದ್ದು, ಕಟ್ಟಡದಲ್ಲಿ ಅನೇಕ ಬಾಡಿಗೆದಾರರು ಇದ್ದು, ಅರ್ಜಿದಾರರು ಅವರಲ್ಲಿ ಒಬ್ಬರಾಗಿದ್ದು, ವಿದ್ಯುತ್ ಸರಬರಾಜು ಸಂಸ್ಥೆ (ESCOM) ಅಳವಡಿಸಿರುವ ಉಪ-ಮೀಟರ್ (Sub-meter) ಹೊಂದಿದ್ದರೆ, ಅವರು ಈ ಪ್ರೋತ್ಸಾಹಧನಕ್ಕೆ ಅರ್ಹರಾಗಿರುತ್ತಾರೆ.", "IV. ಆರ್.ಆರ್. ಸಂಖ್ಯೆ (RR No.) ಕಟ್ಟಡದ ಮಾಲೀಕ/ಅಭಿವೃದ್ಧಿಪಡಿಸುವವರ ಹೆಸರಿನಲ್ಲಿದ್ದು, ಕಟ್ಟಡದಲ್ಲಿ ಅನೇಕ ಬಾಡಿಗೆದಾರರು ಇದ್ದು, ಅರ್ಜಿದಾರರು ಅವರಲ್ಲಿ ಒಬ್ಬರಾಗಿದ್ದು, ವಿದ್ಯುತ್ ಸರಬರಾಜು ಸಂಸ್ಥೆ (ESCOM) ಅಳವಡಿಸಿರುವ ಉಪ-ಮೀಟರ್ (Sub-meter) ಹೊಂದಿರದಿದ್ದರೆ, ಅವರು ಈ ಪ್ರೋತ್ಸಾಹಧನಕ್ಕೆ ಅರ್ಹರಾಗಿರುವುದಿಲ್ಲ."]', '["ಅರ್ಜಿದಾರ ಕಂಪನಿಯು GCC ನೀತಿಯಡಿ ಕರ್ನಾಟಕ ನವೋದ್ಯಮ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ಯಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["i. ಕರ್ನಾಟಕ ಇನ್ನೋವೇಷನ್ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ವತಿಯಿಂದ ನೀಡಲಾದ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರದ ಪ್ರತಿ.", "ii. ನೋಂದಾಯಿತ ಬಾಡಿಗೆ / ಗುತ್ತಿಗೆ (Rent/Lease) ಒಪ್ಪಂದದ ಸ್ವಯಂ ದೃಢೀಕರಿಸಿದ ಪ್ರತಿ.", "iii. ವಿದ್ಯುತ್ ಸರಬರಾಜು ಸಂಸ್ಥೆ (ESCOM) ನೀಡಿರುವ ವಿದ್ಯುತ್ ಸೇವಾ ಮಂಜೂರಾತಿ ಪತ್ರದ (Power Service Letter) ಸ್ವಯಂ ದೃಢೀಕರಿಸಿದ ಪ್ರತಿ, ಇದರಲ್ಲಿ ಆರ್.ಆರ್. ಸಂಖ್ಯೆ (R.R. No.) ಹಾಗೂ ಮಂಜೂರಾತಿ ದಿನಾಂಕದ ವಿವರಗಳಿರಬೇಕು.", "iv. ಅರ್ಜಿ ಸಲ್ಲಿಸಿದ ದಿನಾಂಕದವರೆಗೆ ಕಳೆದ ಮೂರು ತಿಂಗಳ ವಿದ್ಯುತ್ ಬಿಲ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('a6eda642-098c-4fbc-bdfb-a55e80ea8ca0', 'FOOD-CIVIL-SUPPLIES-2', '98c19fd4-7019-42a5-9af1-39cd53b9d099', 'Issue of authorization to run Fair Price Shops (FPS) under Karnataka Essential Commodities (Public Distribution System) Control Order 1992. Running of Fair Price Shops. 1) Issue of Authorization 2) Issue of induplicate authorization 3) Surrender 4) Renewal', 'Sanction of Authorization', 30, 'This service enables eligible applicants to apply for authorization to operate a Fair Price Shop, duplicate authorization, surrender of authorization and renewal of authorization as per applicable rules.', '["If it is Individual Person: 1) Apllication \"A\" 2) Candidates'' SSLC marks card (Must have passed SSLC). 3)Certified audit reports for the last three years (in the case of cooperative societies/institutions). 4)A copy of the business premises account record and a copy of the rental agreement (if the premises are rented). 5) 3 Passport size photos 6) Adhara Card Xerox 7)Bank Passbook Xerox 8)Pan card Xerox copy 9)A certificate from the Police Department stating that there are no police cases against the applicant. If it is Society: 1)Proforma \"A\" 2) Society Registration Certificate 3) latest 3 Years Audit Report of Society 4) Bi-la copy of Society 5)Copy of the resolution appointing a representative authorized to operate the fair price shop and submit certificates on behalf of the cooperative society/institution, along with a confirmation letter regarding the appointment from the competent authority. 6) 3 Passport size photos 7) Bank Passbook Xerox 8) Pan card Xerox 9)Adhara Card Xerox"]', '["I. State Government Owned,", "Corporations/Institutions/Gram Panchayats and Government Institutions.", "II. Co-operative Societies.", "Taluk Agricultural Produce Cooperative Society/Agricultural Service Cooperative Society (N)", "Primary Agricultural Cooperative Societies (PACS)", "Horticultural Produce Cooperative Society Sales Board Limited.", "Registered Cooperative Societies", "Registered Primary User Cooperative Societies.", "Large-scale tribal multipurpose cooperative societies.", "Registered Weavers'' Cooperative Societies.", "Registered Women''s Multipurpose Cooperative Societies", "Registered Development Cooperative Societies", "Disabled Welfare Cooperative Societies", "Cooperative societies or cooperative banks run by banks", "III. others.", "Mentally challenged (as per government rules)", "Transgender people.", "Cooperative societies must have been registered for at least three years and must have been in continuous operation for three years and must have a bank balance of at least two lakh rupees for two years."]', '[]', '["The applicant can Submit the physical application form along with the required documents to the local Tehsildar, Food Supply Officer (FSO), or Joint Director office"]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಕರ್ನಾಟಕ ಅಗತ್ಯ ವಸ್ತುಗಳ (ಸಾರ್ವಜನಿಕ ವಿತರಣಾ ವ್ಯವಸ್ಥೆ) ನಿಯಂತ್ರಣ ಆದೇಶ, 1992ರ ಅಡಿಯಲ್ಲಿ ನ್ಯಾಯಬೆಲೆ ಅಂಗಡಿಯನ್ನು (FPS) ನಡೆಸಲು 1) ಪ್ರಾಧಿಕಾರಣ ಪತ್ರ ನೀಡುವುದು 2) ನಕಲು ಪ್ರಾಧಿಕಾರಣ ಪತ್ರ ನೀಡುವುದು 3) ಪ್ರಾಧಿಕಾರಣ ಪತ್ರ ಹಿಂತಿರುಗಿಸುವುದು 4) ಪ್ರಾಧಿಕಾರಣ ಪತ್ರ ನವೀಕರಣಕ್ಕೆ ಸಂಬಂಧಿಸಿದ ಸೇವೆ', 'To obtain authorization to operate a Fair Price Shop (FPS), including issue of new authorization, duplicate authorization, surrender of authorization, and renewal under the Karnataka Essential Commodities (Public Distribution System) Control Order, 1992', NULL, 'Concerned Districts', 'Offline', NULL, NULL, 500.00, 'ಈ ಸೇವೆಯ ಮೂಲಕ ಅರ್ಹ ಅರ್ಜಿದಾರರು ಹೊಸ ನ್ಯಾಯಬೆಲೆ ಅಂಗಡಿ ನಡೆಸಲು, ನಕಲು ಪ್ರಾಧಿಕಾರಣ ಪತ್ರ ಪಡೆಯಲು, ಪ್ರಾಧಿಕಾರಣ ನವೀಕರಣಕ್ಕಾಗಿ ಹಾಗೂ ಪ್ರಾಧಿಕಾರಣ ಆರ್ಧ್ಯಪಿಸಲು ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು.', NULL, NULL, NULL, false, 'No', '["I. ರಾಜ್ಯ ಸರ್ಕಾರಿ ಸ್ವಾಮ್ಯದ,", "ನಿಗಮಗಳು/ಸಂಸ್ಥೆಗಳು/ಗ್ರಾಮ ಪಂಚಾಯಿತಿಗಳು ಮತ್ತು ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಗಳು.", "II. ಸಹಕಾರ ಸಂಘಗಳು.", "ತಾಲ್ಲೂಕು ವ್ಯವಸಾಯ ಉತ್ಪನ್ನ ಸಹಕಾರ ಸಂಘ/ವ್ಯವಸಾಯ ಸೇವಾ ಸಹಕಾರ ಸಂಘ (ನಿ)", "ಪ್ರಾಥಮಿಕ ಕೃಷಿ ಪತ್ತಿನ ಸಹಕಾರ ಸಂಘಗಳು (PACS)", "ತೋಟಗಾರಿಕಾ ಉತ್ಪನ್ನಗಳ ಸಹಕಾರ ಸಂಘದ ಮಾರಾಟ ಮಂಡಳಿ ನಿಯಮಿತ.", "ನೊಂದಾಯಿತ ಸಹಕಾರ ಸಂಘಗಳು", "ನೊಂದಾಯಿತ ಪ್ರಾಥಮಿಕ ಬಳಕೆದಾರ ಸಹಕಾರ ಸಂಘಗಳು.", "ದೊಡ್ಡ ಪ್ರಮಾಣದ ಆದಿವಾಸಿಗಳ ವಿವಿಧೋದ್ದೇಶ ಸಹಕಾರ ಸಂಘಗಳು.", "ನೊಂದಾಯಿತ ನೇಕಾರರ ಸಹಕಾರ ಸಂಘಗಳು.", "ನೊಂದಾಯಿತ ಮಹಿಳಾ ವಿವಿಧೋದ್ದೇಶ ಸಹಕಾರ ಸಂಘಗಳು", "ನೊಂದಾಯಿತ ಅಭಿವೃದ್ಧಿ ಸಹಕಾರ ಸಂಘಗಳು", "ಅಂಗವಿಕಲರ ಕಲ್ಯಾಣ ಸಹಕಾರ ಸಂಘಗಳು", "ಬ್ಯಾಂಕಿನಿಂದ ನಡೆಸಲ್ಪಡುವ ಸಹಕಾರ ಸಂಘಗಳು ಅಥವಾ ಸಹಕಾರ ಬ್ಯಾಂಕ್", "III. ಇತರರು.", "ವಿಕಲ ಚೇತನರು (ಸರ್ಕಾರದ ನಿಯಮಾನುಸಾರ)", "ತೃತೀಯ ಲಿಂಗಿಗಳು.", "ಸಹಕಾರ ಸಂಘಗಳು ಕನಿಷ್ಠ ಮೂರು ವರ್ಷಗಳ ಹಿಂದೆ ನೋಂದಾಯಿತವಾಗಿರತಕ್ಕದ್ದು ಮತ್ತು ಮೂರು ವರ್ಷಗಳ ನಿರಂತರ ಚಟುವಟಿಕೆಯಲ್ಲಿದ್ದು ಎರಡು ವರ್ಷಗಳಿಂದ ಕನಿಷ್ಠ ಎರಡು ಲಕ್ಷ ರೂಪಾಯಿಗಳ ಮೊತ್ತದ ಬ್ಯಾಂಕ್ ಬ್ಯಾಲೆನ್ಸ್ ಹೊಂದಿರತಕ್ಕದ್ದು."]', '["ಅರ್ಜಿದಾರರು ಅಗತ್ಯ ದಾಖಲೆಗಳೊಂದಿಗೆ ಭೌತಿಕ ಅರ್ಜಿ ನಮೂನೆಯನ್ನು ಸ್ಥಳೀಯ ತಹಸೀಲ್ದಾರ್, ಆಹಾರ ಸರಬರಾಜು ಅಧಿಕಾರಿ (FSO) ಅಥವಾ ಜಂಟಿ ನಿರ್ದೇಶಕರ ಕಚೇರಿಗೆ ಸಲ್ಲಿಸಬಹುದು"]', 1, '["ವೈಯಕ್ತಿಕ ವ್ಯಕ್ತಿಯಾಗಿದ್ದಲ್ಲಿ 1) ಅರ್ಜಿ ನಮೂನೆ \"ಎ\" 2) ಅಭ್ಯರ್ತಿಗಳ ʼಎಸ್,ಎಸ್"]', NULL, NULL, '2950');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('87ab28cf-65a3-4c5d-9910-082652babacd', 'DEPARTMENT-OF-ELECTR-22', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Supporting Telecom Infrastructure Development', 'General', 60, 'Available for first 3 years from date of operations.25% of internet expenses, capped at INR 12 Lakh per year', '["i. Self-Declaration: Company/Entity declaration for availing incentives for GCC.", "ii. Cross charge declaration to be submitted by the entity.", "iii. Monthly or quarterly invoices for internet usage charges", "iv. Bank Statement for the period.", "v. Self-attested declaration on the official letterhead stating that internet expenses have not been cross charged/ recovered from any other entity which is not undertaking GCC activities"]', '["Applicable to New GCCs setting up with 100+ employees in Beyond Bengaluru District", "Reimbursement of up to 25% of internet expenses for the first three years of GCC operations.", "The Applicant shall have completed at least 1 years of commercial operations."]', '[]', '["The applicant Company should be registered with KITS under GCC Policy 2024-29", "Company should submit the incentive application along with supporting documents as prescribed in the OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/gcc/telecom-infrastructure', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ದೂರಸಂಪರ್ಕ ಮೂಲಸೌಕರ್ಯ ಅಭಿವೃದ್ಧಿಗೆ ಬೆಂಬಲ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಕಾರ್ಯಾಚರಣೆ ಪ್ರಾರಂಭವಾದ ದಿನಾಂಕದಿಂದ ಮೊದಲ 3 ವರ್ಷಗಳವರೆಗೆ ಲಭ್ಯವಿದೆ. ಇಂಟರ್ನೆಟ್ ವೆಚ್ಚದ ಶೇ. 25, ವರ್ಷಕ್ಕೆ ಗರಿಷ್ಠ 12 ಲಕ್ಷ ರೂಪಾಯಿಗಳ ಮಿತಿಗೊಳಿಸಲಾಗಿದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಬೆಂಗಳೂರು ಹೊರವಲಯ ಜಿಲ್ಲೆಗಳಲ್ಲಿ 100 ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ಉದ್ಯೋಗಿಗಳನ್ನು ಹೊಂದಿರುವ ಹೊಸದಾಗಿ ಸ್ಥಾಪಿಸಲಾದ ಜಾಗತಿಕ ಸಾಮರ್ಥ್ಯ ಕೇಂದ್ರಗಳಿಗೆ (GCCs) ಅನ್ವಯಿಸುತ್ತದೆ.", "ಜಿಸಿಸಿ (GCC) ಕಾರ್ಯಾಚರಣೆಯ ಮೊದಲ ಮೂರು (3) ವರ್ಷಗಳ ಅವಧಿಯಲ್ಲಿ ಇಂಟರ್ನೆಟ್ ವೆಚ್ಚದ ಶೇಕಡಾ 25% ರವರೆಗೆ ಮರುಪಾವತಿ ನೀಡಲಾಗುತ್ತದೆ.", "ಅರ್ಜಿದಾರರು ಕನಿಷ್ಠ ಒಂದು (1) ವರ್ಷದ ವಾಣಿಜ್ಯ ಕಾರ್ಯಾಚರಣೆಯನ್ನು ಪೂರ್ಣಗೊಳಿಸಿರಬೇಕು"]', '["ಅರ್ಜಿದಾರ ಕಂಪನಿಯು GCC ನೀತಿಯಡಿ ಕರ್ನಾಟಕ ನವೋದ್ಯಮ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ಯಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["i. ಜಿಸಿಸಿ (GCC) ಪ್ರೋತ್ಸಾಹಧನ ಪಡೆಯಲು ಸಂಸ್ಥೆ/ಘಟಕದಿಂದ ನೀಡಲಾದ ಸ್ವಯಂ ಘೋಷಣಾಪತ್ರ.", "ii. ಇಂಟರ್ನೆಟ್ ವೆಚ್ಚವನ್ನು ಯಾವುದೇ ಇತರೆ ಘಟಕಕ್ಕೆ ವರ್ಗಾಯಿಸಲಾಗಿಲ್ಲ (Cross Charge) ಎಂಬುದನ್ನು ದೃಢೀಕರಿಸುವ ಘೋಷಣಾಪತ್ರ.", "iii. ಇಂಟರ್ನೆಟ್ ಬಳಕೆಗೆ ಸಂಬಂಧಿಸಿದ ಮಾಸಿಕ ಅಥವಾ ತ್ರೈಮಾಸಿಕ (Monthly/Quarterly) ಸರಕುಪಟ್ಟಿಗಳ (Invoices) ಪ್ರತಿಗಳು.", "iv. ಹಕ್ಕು ಕೋರಿರುವ ಅವಧಿಗೆ ಸಂಬಂಧಿಸಿದ ಬ್ಯಾಂಕ್ ಖಾತೆ ವಿವರಗಳ (Bank Statement) ಪ್ರತಿಗಳು.", "v. ಇಂಟರ್ನೆಟ್ ವೆಚ್ಚವನ್ನು ಜಿಸಿಸಿ (GCC) ಚಟುವಟಿಕೆಗಳನ್ನು ಕೈಗೊಳ್ಳದ ಯಾವುದೇ ಇತರೆ ಘಟಕದಿಂದ ವಸೂಲಿ ಮಾಡಿಲ್ಲ ಅಥವಾ ವರ್ಗಾಯಿಸಲಾಗಿಲ್ಲ (Cross Charged/Recovered) ಎಂಬುದನ್ನು ದೃಢೀಕರಿಸುವ ಸಂಸ್ಥೆಯ ಅಧಿಕೃತ ಲೆಟರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('43fed311-1b02-49ea-b104-a211175be430', 'REVENUE-DEPARTMENT-119', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Second Reclassification Tippan', 'General', 0, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (Second Reclassification Tippan)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಎರಡನೇ ರೀಕ್ಲಾಸಿಫಿಕೇಷನ್ ಟಿಪ್ಪಣಿ', NULL, NULL, NULL, NULL, NULL, 35.00, NULL, 'ಎರಡನೇ ರೀಕ್ಲಾಸಿಫಿಕೇಷನ್ ಟಿಪ್ಪಣಿ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3130');
