INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('9da734ab-bd41-4b56-9bf4-adb158c38193', 'REVENUE-DEPARTMENT-121', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'RECLASS PAKKA', 'General', 0, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (RECLASS PAKKA', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ರೀಕ್ಲಾಸ್ ಬಾಬ್ತು ಪಕ್ಕಾ ಪುಸ್ತಕ', NULL, NULL, NULL, NULL, NULL, 70.00, NULL, 'ರೀಕ್ಲಾಸ್ ಬಾಬ್ತು ಪಕ್ಕಾ ಪುಸ್ತಕ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3123');
