INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('96b35a44-8523-444d-9ff5-56b438725066', 'DEPARTMENT-OF-ELECTR-20', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Intellectual Property Incentive', 'General', 60, 'GoK shall reimburse cost of filing and securing patents for GCC entities registered with KITS in the State', '["Property ownership (sale deed, lease agreement, or equivalent) of the GCC unit that owns the property and had paid the property tax in its own name.", "Property tax payment receipts for the claim period (only applicable for a period of 3 years from the commencement of GCC operations)", "Property tax assessment notices issued by the competitive authority.", "CA Certified letter verifying the total property tax paid during the claim period."]', '["Applicable to GCCs across Karnataka", "The Applicant should have been awarded the patent within the policy period, for which reimbursement is being claimed.", "Applicants will be eligible for a maximum of five reimbursements during the policy period.", "The applicant shall submit the application for reimbursement within twelve (12) months from the date of the award of the patent.", "The reimbursement shall be made on actuals, up to the maximum limit as mentioned in the OPG.", "Provisional patent application expenses will not be considered for reimbursement.", "Applicant shall be eligible to file one (1) claim per year for reimbursement of patent fees."]', '[]', '["The applicant Company should be registered with KITS under GCC Policy 2024-29", "Company should submit the incentive application along with supporting documents as prescribed in the OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/gcc/rental-assistance', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಬೌದ್ಧಿಕ ಆಸ್ತಿ ಪ್ರೋತ್ಸಾಹಧನ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ರಾಜ್ಯದಲ್ಲಿ KITS ನಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರುವ GCC ಸಂಸ್ಥೆಗಳಿಗೆ ಪೇಟೆಂಟ್', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕದಾದ್ಯಂತ ಸ್ಥಾಪಿತವಾಗಿರುವ ಜಾಗತಿಕ ಸಾಮರ್ಥ್ಯ ಕೇಂದ್ರಗಳಿಗೆ (GCCs) ಅನ್ವಯಿಸುತ್ತದೆ.", "ಮರುಪಾವತಿಯನ್ನು ಕೋರುತ್ತಿರುವ ಪೇಟೆಂಟ್"]', '["ಅರ್ಜಿದಾರ ಕಂಪನಿಯು GCC ನೀತಿಯಡಿ ಕರ್ನಾಟಕ ನವೋದ್ಯಮ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ಯಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["ಜಿಸಿಸಿ (GCC) ಘಟಕವು ತನ್ನ ಹೆಸರಿನಲ್ಲಿ ಆಸ್ತಿಯನ್ನು ಹೊಂದಿದ್ದು, ಆಸ್ತಿ ತೆರಿಗೆಯನ್ನು ತನ್ನ ಹೆಸರಿನಲ್ಲಿಯೇ ಪಾವತಿಸಿರುವುದನ್ನು ದೃಢೀಕರಿಸುವ ಆಸ್ತಿ ಮಾಲೀಕತ್ವದ ದಾಖಲೆಗಳು (ಮಾರಾಟ ಪತ್ರ (Sale Deed), ಗುತ್ತಿಗೆ ಒಪ್ಪಂದ (Lease Agreement) ಅಥವಾ ಸಮಾನ ದಾಖಲೆಗಳು).", "ಹಕ್ಕು ಕೋರಿರುವ ಅವಧಿಗೆ ಸಂಬಂಧಿಸಿದ ಆಸ್ತಿ ತೆರಿಗೆ ಪಾವತಿ ರಸೀದಿಗಳು (ಜಿಸಿಸಿ (GCC) ಕಾರ್ಯಾಚರಣೆ ಆರಂಭಗೊಂಡ ದಿನಾಂಕದಿಂದ ಮೂರು ವರ್ಷಗಳ ಅವಧಿಗೆ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ).", "ಸಮರ್ಥ ಪ್ರಾಧಿಕಾರದಿಂದ (Competent Authority) ನೀಡಲಾದ ಆಸ್ತಿ ತೆರಿಗೆ ಮೌಲ್ಯಮಾಪನ ಅಧಿಸೂಚನೆಗಳ (Property Tax Assessment Notices) ಪ್ರತಿಗಳು.", "ಹಕ್ಕು ಕೋರಿರುವ ಅವಧಿಯಲ್ಲಿ ಪಾವತಿಸಲಾದ ಒಟ್ಟು ಆಸ್ತಿ ತೆರಿಗೆಯನ್ನು ದೃಢೀಕರಿಸುವ ಚಾರ್ಟರ್ಡ್ ಅಕೌಂಟೆಂಟ್ (CA) ದೃಢೀಕರಿಸಿದ ಪತ್ರ."]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('0099ffa3-52b8-4fab-8137-02b9621a508e', 'DEPARTMENT-OF-ELECTR-17', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Power Tariff Concession', 'General', 60, 'In order to reduce energy costs and improve operational efficiency, the option to transition from commercial to industrial power tariffs shall be made available to IT/ITeS units across the state.', '["i. Copy of the Registration Certificate issued by KITS.", "ii. Self-attested copy of registered rent/ lease agreement", "iii. Self-attested copy of ESCOMs power service letter with R.R. No. and date", "iv. Self- attested copies of the last 3 months of electricity bills since the date of submission of the application", "v. Power Tariff Sanction Letter Copy (as applicable)", "vi. Copy of the letter / order - Electricity Duty Reimbursement (as applicable)", "vii. A self-attested copy on letterhead stating the reimbursement requested for the electricity duty (complete calculation along with the breakup) for the period being claimed.", "viii. Applicable for Electricity Duty Incentive : Applicants are requested to furnish complete bank account details (Account Holder Name, Bank Name, Account Number, Account type, IFSC Code, Branch Address) to facilitate the reimbursement."]', '["§ The applicant or any of their associated subsidiary/affiliates should not be under litigation/Court Cases with respect to ESCOMs or Department of IT & Bt.", "§ Where RR No. is in the name of the applicant and the applicant is also the owner of the premise, the applicant shall be eligible for this incentive.", "§ Where RR No. is not under applicant’s name but in the name of the developer / owner owning the premise and applicant is the sole occupant of the premise, the applicant shall be eligible for this incentive.", "§ Where RR No. is in the name of the developer/ owner having multiple tenants and applicant being one of them and the applicant has a submeter installed by the ESCOM, then the applicant shall be eligible for this incentive.", "§ Where RR No. is in the name of the developer/ owner having multiple tenants and applicant being one of them and the applicant is not having a submeter installed by the ESCOM, then the applicant shall not be eligible for this incentive."]', '[]', '["Company should be registered under the policy", "Company should submit the incentive application along with supporting documents as prescribed in the Policy OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/itpolicy/power-tariff-concession', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ವಿದ್ಯುತ್', NULL, NULL, NULL, NULL, NULL, '["ಅರ್ಜಿದಾರರು ಅಥವಾ ಅವರ ಅಂಗಸಂಸ್ಥೆಗಳು/ಸಹ ಸಂಸ್ಥೆಗಳು, ESCOMಗಳು ಅಥವಾ ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ಮತ್ತು ಜೈವಿಕ ತಂತ್ರಜ್ಞಾನ ಇಲಾಖೆಗೆ ಸಂಬಂಧಿಸಿದ ಯಾವುದೇ ನ್ಯಾಯಾಲಯದ ವ್ಯಾಜ್ಯ/ಪ್ರಕರಣವನ್ನು ಹೊಂದಿರಬಾರದು.", "RR ಸಂಖ್ಯೆ ಅರ್ಜಿದಾರರ ಹೆಸರಿನಲ್ಲಿ ಮತ್ತು ಆವರಣವು ಅರ್ಜಿದಾರರ ಸ್ವಂತ ಮಾಲೀಕತ್ವದಲ್ಲಿದ್ದಲ್ಲಿ, ಅರ್ಜಿದಾರರು ಈ ಪ್ರೋತ್ಸಾಹಧನಕ್ಕೆ ಅರ್ಹರಾಗಿರುತ್ತಾರೆ.", "RR ಸಂಖ್ಯೆ ಅರ್ಜಿದಾರರ ಹೆಸರಿನಲ್ಲಿ ಇಲ್ಲದೆ, ಆವರಣದ ಮಾಲೀಕ/ಡೆವಲಪರ್ ಹೆಸರಿನಲ್ಲಿದ್ದು, ಅರ್ಜಿದಾರರು ಆವರಣದ ಏಕೈಕ ಬಳಕೆದಾರರಾಗಿದ್ದಲ್ಲಿ, ಅರ್ಜಿದಾರರು ಈ ಪ್ರೋತ್ಸಾಹಧನಕ್ಕೆ ಅರ್ಹರಾಗಿರುತ್ತಾರೆ.", "RR ಸಂಖ್ಯೆ ಮಾಲೀಕ/ಡೆವಲಪರ್ ಹೆಸರಿನಲ್ಲಿದ್ದು, ಆವರಣದಲ್ಲಿ ಬಹು ಬಾಡಿಗೆದಾರರಿದ್ದು, ಅರ್ಜಿದಾರರು ಅವರಲ್ಲಿ ಒಬ್ಬರಾಗಿದ್ದು, ESCOMನಿಂದ ಸಬ್"]', '["ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ-2025-30 ರಡಿಯಲ್ಲಿ ನೋಂದಣಿಯಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["i. KITS ನಿಂದ ನೀಡಲಾದ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರದ ಪ್ರತಿ.", "ii. ನೋಂದಾಯಿತ ಬಾಡಿಗೆ/ಗುತ್ತಿಗೆ ಒಪ್ಪಂದದ ಸ್ವಯಂ-ದೃಢೀಕೃತ ಪ್ರತಿ", "iii. ಆರ್.ಆರ್. ಸಂಖ್ಯೆ ಮತ್ತು ದಿನಾಂಕದೊಂದಿಗೆ ESCOM ನ ವಿದ್ಯುತ್ ಸೇವಾ ಪತ್ರದ ಸ್ವಯಂ-ದೃಢೀಕೃತ ಪ್ರತಿ", "iv. ಅರ್ಜಿ ಸಲ್ಲಿಸಿದ ದಿನಾಂಕದಿಂದ ಕಳೆದ 3 ತಿಂಗಳ ವಿದ್ಯುತ್ ಬಿಲ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('181923fb-33cf-4a21-b39e-d5ef21c30349', 'ENERGY-DEPARTMENT-4', 'e0b8deb9-4426-4525-a8e5-aab3f707df7c', 'Application for additional load / New connection- Supply of electricity does not require any extension of distribution mains, or commissioning of new substations- Metro Cities', 'General', 0, '', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '665dc58e-475b-4883-93a4-8761c3bf0063', 'ಹೊಸ ಸಂಪರ್ಕ/ ಹೆಚ್ಚುವರಿ ಲೋಡ್', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '2991');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('5ab88d71-a15a-450d-b33a-e96386bab9ef', 'REVENUE-DEPARTMENT-123', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'DETAIL SURVEY TIPPAN', 'General', 0, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (DETAIL SURVEY TIPPAN)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಡಿಟೈಲ್ ಸರ್ವೆ ಟಿಪ್ಪಣಿ ಪುಸ್ತಕ', NULL, NULL, NULL, NULL, NULL, 35.00, NULL, 'ಡಿಟೈಲ್ ಸರ್ವೆ ಟಿಪ್ಪಣಿ ಪುಸ್ತಕ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3128');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('e7d70913-845f-4e1c-bccb-f58629ebc2f4', 'DEPARTMENT-OF-ELECTR-13', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Supporting Telecom Infrastructure Development', 'General', 60, 'Reimbursement of operational expenses shall be provided by GoK to eligible IT/ITeS units for availing internet & telecommunication services.', '["i. Self-Declaration: Company/Entity declaration for availing incentives for IT/ITeS unit.", "ii. Cross charge declaration to be submitted by the entity.", "iii. Monthly or quarterly invoices for internet usage charges", "iv. Bank Statement for the period.", "v. Self-attested copy of Service agreement/contract", "vi. Self-attested declaration on the official letterhead stating that internet expenses have not been cross charged/ recovered from any other entity which is not undertaking IT/ITeS activities.", "vii. Applicants are requested to furnish complete bank account details (Account Holder Name, Bank Name, Account Number, Account type, IFSC Code, Branch Address) to facilitate the reimbursement."]', '["The IT/ITeS should be incorporated or registered in Karnataka as Private Limited Companies, / LLP/ Partnership Firms", "The IT/ ITeS entity must have at least 50% of its total workforce (employees) based in Karnataka. This count shall exclude contract employees.", "A minimum employment threshold of 10 employees in Beyound Bengaluru region and 25 employees in Bengaluru.", "The applicant shall have established a new IT/ITeS Unit in Beyond Bengaluru during the policy period.", "The Applicant shall have completed at least 1 years of commercial operations"]', '[]', '["Company should be registered under the policy", "Company should submit the incentive application along with supporting documents as prescribed in the Policy OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/itpolicy/supporting-telecom-infrastructure-development', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಟೆಲಿಕಾಂ ಮೂಲಸೌಕರ್ಯ ಅಭಿವೃದ್ಧಿಯನ್ನು ಬೆಂಬಲಿಸುವುದು', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಅರ್ಹ ಐಟಿ/ಐಟಿಇಎಸ್ ಘಟಕಗಳು ಇಂಟರ್ನೆಟ್ ಮತ್ತು ದೂರಸಂಪರ್ಕ ಸೇವೆಗಳನ್ನು ಪಡೆಯಲು ಭರಿಸುವ ಕಾರ್ಯಾಚರಣಾ ವೆಚ್ಚಗಳನ್ನು ಕರ್ನಾಟಕ ಸರ್ಕಾರದಿಂದ (GoK) ಮರುಪಾವತಿಸಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಐಟಿ/ಐಟಿಇಎಸ್"]', '["ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ-2025-30 ರಡಿಯಲ್ಲಿ ನೋಂದಣಿಯಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["i. ಸ್ವಯಂ ಘೋಷಣೆ: ಐಟಿ/ಐಟಿಇಎಸ್ ಘಟಕಕ್ಕೆ ಪ್ರೋತ್ಸಾಹ ಧನ ಪಡೆಯಲು ಕಂಪನಿ/ಘಟಕದ ಘೋಷಣೆ.", "ii. ಘಟಕವು ಸಲ್ಲಿಸಬೇಕಾದ ಕ್ರಾಸ್ ಚಾರ್ಜ್ ಘೋಷಣೆ.", "iii. ಇಂಟರ್ನೆಟ್ ಬಳಕೆಯ ಶುಲ್ಕಗಳಿಗೆ ಮಾಸಿಕ ಅಥವಾ ತ್ರೈಮಾಸಿಕ ಇನ್"]', NULL, NULL, '3334');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('4ad600d5-60fa-4720-851a-6159479d289d', 'ENERGY-DEPARTMENT-1', 'e0b8deb9-4426-4525-a8e5-aab3f707df7c', 'Line breakdown- City/Town areas', 'General', 0, '', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '665dc58e-475b-4883-93a4-8761c3bf0063', 'ವಿದ್ಯುತ್', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '2984');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('1e38ae2d-058c-44d3-a7c7-a76a4c1a3a85', 'REVENUE-DEPARTMENT-128', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'DETAIL SURVEY TIPPAN BOOK', 'General', 0, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (DETAIL SURVEY TIPPAN BOOK)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಡೀಟೈಲ್ ಸರ್ವೆ ಬಾಬ್ತು ಟಿಪ್ಪಣಿ ಪುಸ್ತಕ', NULL, NULL, NULL, NULL, NULL, 35.00, NULL, 'ಡೀಟೈಲ್ ಸರ್ವೆ ಬಾಬ್ತು ಟಿಪ್ಪಣಿ ಪುಸ್ತಕ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3099');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('ea99fef5-3421-4154-9eff-9f95568d1fc1', 'DEPARTMENT-OF-ELECTR-9', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Recruitment Assistance', 'General', 60, 'GoK will provide recruitment assistance to IT/ITeS Units that are setting up new operations or expanding existing ones in Beyond Bengaluru.', '["i. CA-certified letter on expenditure incurred towards ‘Rental Reimbursement’, comprising a break-up of the total Recruitment Assistance Cost (as applicable):", "Advertisement/communication for inviting applications for new employment (which may include print, paid social media, or other digital platforms)", "Recruitment consultants/agencies", "Campus visits", "Total new employees selected under the Recruitment Assistance Incentive", "Total boarding and lodging cost", "ii. Copy of original invoices, bills for the expenses incurred (as applicable).", "iii. Applicants are requested to furnish complete bank account details (Account Holder Name, Bank Name, Account Number, Account type, IFSC Code, Branch Address) to facilitate the reimbursement."]', '["The IT/ITeS should be incorporated or registered in Karnataka as Private Limited Companies, / LLP/ Partnership Firms", "The IT/ ITeS entity must have at least 50% of its total workforce (employees) based in Karnataka. This count shall exclude contract employees.", "A minimum employment threshold of 10 employees in Beyound Bengaluru region and 25 employees in Bengaluru.", "The IT/ITeS Unit shall be located in Beyond Bengaluru.", "The applicant shall have created new employment during the policy period."]', '[]', '["Company should be registered under the policy", "Company should submit the incentive application along with supporting documents as prescribed in the Policy OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/itpolicy/recruitment-assistance', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ನೇಮಕಾತಿ ನೆರವು', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಬೆಂಗಳೂರಿನ ಹೊರಗೆ ಹೊಸ ಕಾರ್ಯಾಚರಣೆಗಳನ್ನು ಸ್ಥಾಪಿಸುತ್ತಿರುವ ಅಥವಾ ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ಕಾರ್ಯಾಚರಣೆಗಳನ್ನು ವಿಸ್ತರಿಸುತ್ತಿರುವ ಐಟಿ/ಐಟಿಇಎಸ್ (IT/ITeS) ಘಟಕಗಳಿಗೆ ಕರ್ನಾಟಕ ಸರ್ಕಾರವು ನೇಮಕಾತಿ ನೆರವನ್ನು ಒದಗಿಸುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಐಟಿ/ಐಟಿಇಎಸ್"]', '["ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ-2025-30 ರಡಿಯಲ್ಲಿ ನೋಂದಣಿಯಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["i. ‘ಬಾಡಿಗೆ ಮರುಪಾವತಿ’ಗೆ ಮಾಡಿದ ವೆಚ್ಚದ ಕುರಿತು CA-ಪ್ರಮಾಣೀಕೃತ ಪತ್ರ, ಒಟ್ಟು ನೇಮಕಾತಿ ಸಹಾಯ ವೆಚ್ಚದ ವಿವರಣೆಯನ್ನು ಒಳಗೊಂಡಿದೆ (ಅನ್ವಯಿಸಿದಂತೆ):", "ಹೊಸ ಉದ್ಯೋಗಕ್ಕಾಗಿ ಅರ್ಜಿಗಳನ್ನು ಆಹ್ವಾನಿಸಲು ಜಾಹೀರಾತು/ಸಂವಹನ (ಇದರಲ್ಲಿ ಮುದ್ರಣ, ಪಾವತಿಸಿದ ಸಾಮಾಜಿಕ ಮಾಧ್ಯಮ ಅಥವಾ ಇತರ ಡಿಜಿಟಲ್ ಪ್ಲಾಟ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('e3a373e0-a1d3-4556-a9e6-74a542a5a58a', 'DEPARTMENT-OF-ELECTR-6', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Property tax reimbursement', 'General', 60, 'To ease the financial burden on businesses operating Beyond Bengaluru, the GoK shall provide reimbursement of property tax payments as mentioned below.', '["i. Property ownership (sale deed) of the IT/ITeS unit that owns the property and had paid the property tax in its own name.", "ii. Property tax payment receipts for the claim period (only applicable for a period of 3 years from the commencement of IT/ITeS operations).", "iii. Property tax assessment notices issued by the competitive authority.", "iv. CA Certified letter verifying the total property tax paid during the claim period.", "v. Furnish complete bank account details (Account Holder Name, Bank Name, Account Number, Account type, IFSC Code, Branch Address) to facilitate the reimbursement."]', '["The IT/ITeS should be incorporated or registered in Karnataka as Private Limited Companies, / LLP/ Partnership Firms", "The IT/ ITeS entity must have at least 50% of its total workforce (employees) based in Karnataka. This count shall exclude contract employees.", "A minimum employment threshold of 10 employees in Beyound Bengaluru region and 25 employees in Bengaluru.", "The applicant shall have established a new IT/ITeS Unit in Beyond Bengaluru during the policy period.", "Reimbursement of property tax shall be applicable only to the applicant that owns the property and has paid the property tax in its own name. A self-declaration confirming ownership and tax payment must be submitted on the applicant’s official letterhead."]', '[]', '["Company should be registered under the policy", "Company should submit the incentive application along with supporting documents as prescribed in the Policy OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/itpolicy/property-tax-reimbursement', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಆಸ್ತಿ ತೆರಿಗೆ ಮರುಪಾವತಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಬೆಂಗಳೂರಿನ ಹೊರಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿರುವ ಉದ್ಯಮಗಳ ಮೇಲಿನ ಆರ್ಥಿಕ ಹೊರೆಯನ್ನು ಕಡಿಮೆ ಮಾಡಲು, ಕರ್ನಾಟಕ ಸರ್ಕಾರವು ಈ ಕೆಳಗೆ ತಿಳಿಸಿದಂತೆ ಆಸ್ತಿ ತೆರಿಗೆ ಪಾವತಿಗಳ ಮರುಪಾವತಿಯನ್ನು ಒದಗಿಸುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಐಟಿ/ಐಟಿಇಎಸ್"]', '["ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ-2025-30 ರಡಿಯಲ್ಲಿ ನೋಂದಣಿಯಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["i. ಆಸ್ತಿಯನ್ನು ಹೊಂದಿರುವ ಮತ್ತು ತನ್ನದೇ ಹೆಸರಿನಲ್ಲಿ ಆಸ್ತಿ ತೆರಿಗೆಯನ್ನು ಪಾವತಿಸಿದ ಐಟಿ/ಐಟಿಇಎಸ್ ಘಟಕದ ಆಸ್ತಿ ಮಾಲೀಕತ್ವ (ಮಾರಾಟ ಪತ್ರ).", "ii. ಕ್ಲೈಮ್ ಅವಧಿಗೆ ಆಸ್ತಿ ತೆರಿಗೆ ಪಾವತಿ ರಶೀದಿಗಳು (ಐಟಿ/ಐಟಿಇಎಸ್ ಕಾರ್ಯಾಚರಣೆಗಳು ಪ್ರಾರಂಭವಾದ 3 ವರ್ಷಗಳ ಅವಧಿಗೆ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ).", "iii. ಸ್ಪರ್ಧಾತ್ಮಕ ಪ್ರಾಧಿಕಾರದಿಂದ ನೀಡಲಾದ ಆಸ್ತಿ ತೆರಿಗೆ ಮೌಲ್ಯಮಾಪನ ಸೂಚನೆಗಳು.", "iv. ಕ್ಲೈಮ್ ಅವಧಿಯಲ್ಲಿ ಪಾವತಿಸಿದ ಒಟ್ಟು ಆಸ್ತಿ ತೆರಿಗೆಯನ್ನು ಪರಿಶೀಲಿಸುವ ಸಿಎ ಪ್ರಮಾಣೀಕೃತ ಪತ್ರ.", "v. ಅರ್ಜಿದಾರರು ಸಂಪೂರ್ಣ ಬ್ಯಾಂಕ್ ಖಾತೆ ವಿವರಗಳನ್ನು (ಖಾತೆದಾರರ ಹೆಸರು, ಬ್ಯಾಂಕ್ ಹೆಸರು, ಖಾತೆ ಸಂಖ್ಯೆ, ಖಾತೆ ಪ್ರಕಾರ, ಐಎಫ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('58a461e1-b58d-4496-888f-ec0ba3e94462', 'HORTICULTURE-AND-SER-14', '7fc7181a-5bee-4a83-b61b-bd3c78da95b2', 'Programmes implemented by Price Stabilization Fund- Pure Mysore Bonus', 'General', 0, 'Programmes implemented by Price Stabilization Fund- Pure Mysore Bonus', '["Application", "Rearer Pass bookAadhaar Card", "Aadhaar Card", "FRUITS ID", "Aadhaar Linked Bank Account details ( First Page of the Bank Passbook )", "Dfl''s Purchase bill", "Bidding slip for Pure Bivoltine seed Cocoons transacted in Govt.Cocoon Markets"]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '2486ba28-e160-4a76-8df1-ce8e643a84c9', 'ಬೆಲೆ ಸ್ಥಿರೀಕರಣ ನಿಧಿ ಅನುದಾನದಿಂದ ಅನುಷ್ಟಾನಗೊಳಿಸುವ ಕಾರ್ಯಕ್ರಮಗಳು- ಶುದ್ದ ಮೈಸೂರು ತಳಿ ಬಿತ್ತನೆ ಗೂಡಿಗೆ ಬೋನಸ್', 'Programmes implemented by Price Stabilization Fund- Pure Mysore Bonus', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಬೆಲೆ ಸ್ಥಿರೀಕರಣ ನಿಧಿ ಅನುದಾನದಿಂದ ಅನುಷ್ಟಾನಗೊಳಿಸುವ ಕಾರ್ಯಕ್ರಮಗಳು- ಶುದ್ದ ಮೈಸೂರು ತಳಿ ಬಿತ್ತನೆ ಗೂಡಿಗೆ ಬೋನಸ್', NULL, NULL, NULL, false, 'No', '[]', '[]', 1, '["ಅರ್ಜಿ", "ರೇಷ್ಮೆ ಬೆಳೆಗಾರರ ಪಾಸು ಪುಸ್ತಕ", "ಆಧಾರ್"]', NULL, NULL, '3416');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('767191b6-4369-4281-b2ce-459473fffa08', 'URBAN-DEVELOPMENT-DE-7', 'ec54831c-9747-4f90-b64d-a98f1f175b6a', 'Granting approval for residential/non-residential Development Plan. Under Section 17 of KTCP Act, 1961.', 'General', 0, 'Granting approval for residential/non-residential Development Plan. Under Section 17 of KTCP Act, 1961.', '["Ownership records (Sale Deed/Partition Deed/GPA/etc.)", "Recent Encumbrance Certificate (EC).", "Recent Pahani (R.T.C.).", "Recent Mutation Register copy (M.R.).", "Akarband.", "Hissa and Note.", "Conversion Order copies.", "Survey sketch certified by the Assistant Director of Land Records.", "Draft Development Plan prepared as per the Survey sketch in accordance with sketch", "provided by Assistant Director of Land Records and Zonal Regulations.", "No Objection Certificate in connection with water supply and maintenance of infrastructure", "facilities obtained from the concerned Local Body.", "Part of Master Plan.", "Google map.", "Village map.", "Declaration letter duly notarized in a stamp paper with a face value of Rs.100/- declaring that", "all the documents submitted are true and correct.", "Notarised Stamp Paper for Joint Development, if required.", "Copy of Aadhar Card along with the signature of all the owners of survey numbers consisted", "in the proposal."]', '["Applicant seeking approval for Single Plot LayoutPlanshall be the owner/GPA Holder of the land proposed for approval."]', '[]', '["No online service is available."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'a766e78f-05f2-440a-8461-a06c5b738719', 'ವಸತಿ /ವಸತಿವಯೇತರ ಅಭಿವೃದ್ಧಿ ಯೋಜನಾ ನಕ್ಷೆಗೆ ಅನುಮೋದನೆ ನೀಡುವುದು ಕ.ನ.ಗ್ರಾ.ಯೋ. ಕಾಯ್ದೆ.1961ರ ಕಲಂ 17.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ವಸತಿ /ವಸತಿವಯೇತರ ಅಭಿವೃದ್ಧಿ ಯೋಜನಾ ನಕ್ಷೆಗೆ ಅನುಮೋದನೆ ನೀಡುವುದು ಕ.ನ.ಗ್ರಾ.ಯೋ. ಕಾಯ್ದೆ.1961ರ ಕಲಂ 17.', NULL, NULL, NULL, NULL, NULL, '["ವಿನ್ಯಾಸ ಅನುಮೋದನೆಗಾಗಿ ಸಲ್ಲಿಸುವ ಅರ್ಜಿದಾರರು ವಿನ್ಯಾಸ ಅನುಮೋದನೆಗಾಗಿ ಪ್ರಸ್ತಾಪಿಸಿರುವ ಜಮೀನಿನ ಮಾಲೀಕರು ಅಥವಾ ಜಿಪಿಎ ದಾರರು ಆಗಿರಬೇಕಾಗಿರುತ್ತದೆ."]', '["ಸದರಿ ಸೇವೆಯು ಆನ್ಲೈನ್ ನಲ್ಲಿ ಲಭ್ಯವಿರುವುದಿಲ್ಲ."]', 1, '["ಮಾಲಿಕತ್ವದ ದಾಖಲಾತಿಗಳು (ಕ್ರಯಪತ್ರ ಅಥವ ವಿಭಾಗಪತ್ರ ಅಥವ ಜಿಪಿಎ ಅಥವ ಇತರೆ)", "ಇತ್ತೀಚಿನ ಋಣಭಾರರಾಹಿತ್ಯ ಪ್ರಮಾಣಪತ್ (ಇ.ಸಿ.)", "ಇತ್ತೀಚಿನ ಪಹಣಿ (ಆರ್.ಟಿ.ಸಿ.),", "ಇತ್ತೀಚಿನ ಮ್ಯುಟೇಷನ್ ರಿಜಿಸ್ಟರ್ ಪ್ರತಿ (ಎಂ.ಆರ್.)", "ಆಕಾರ್ ಬಂದ್", "ಹಿಸ್ಸಾ ಮತ್ತು ಟಿಪ್ಪಣಿ", "ಭೂ ಪರಿವರ್ತನಾ ಆದೇಶದ ಪ್ರತಿಗಳು", "ಭೂ ದಾಖಲೆಗಳ ಸಹಾಯಕ ನಿರ್ದೇಶಕರು ದೃಢೀಕರಿಸಿದ ಸರ್ವೆ ನಕ್ಷೆ", "ಭೂ ದಾಖಲೆಗಳ ಸಹಾಯಕ ನಿರ್ದೇಶಕರು ದೃಢೀಕರಿಸಿದ ಸರ್ವೆ ನಕ್ಷೆಗೆ ಅನುಗುಣವಾಗಿ ವಲಯ ನಿಯಮಾವಳಿಗಳಂತೆ ತಯಾರಿಸಿರುವ ಕರಡು ಏಕ ನಿವೇಶನ ವಿನ್ಯಾಸ ನಕ್ಷೆ,", "ನೀರು ಸರಬರಾಜು ಸಂಬಂಧಪಟ್ಟ ಸ್ಥಳೀಯ ಸಂಸ್ಥೆಯಿಂದ ಪಡೆದ ನಿರಾಕ್ಷೇಪಣಾ ಪತ್ರ", "ಮಹಾಯೋಜನೆಯ ಉಧೃತ ಭಾಗ,", "ಗೂಗಲ್ ನಕ್ಷೆ", "ಗೂಗಲ್ ನಕ್ಷೆ", "ಸಲ್ಲಿಸಿರುವ ಎಲ್ಲಾ ದಾಖಲಾತಿಗಳು ಸರಿಯಾಗಿರುತ್ತವೆ ಎಂಬ ಬಗ್ಗೆ ರೂ.100 ಮುಖಬೆಲೆಯ ನೋಟರೀಕೃತ ಘೋಷಣಾಪತ್ರ", "ಪ್ರಸ್ತಾವನೆಯಲ್ಲಿರುವ ಜಮೀನುಗಳ ಸರ್ವೆ ನಂ.ಗಳ ಎಲ್ಲಾ ಭೂ ಮಾಲೀಕರ ಸಹಿಯೊಂದಿಗೆ ಆಧಾರ್ ಕಾರ್ಡ್ ಪ್ರತಿ", "ಅರ್ಜಿದಾರರ ಅಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('d4a1230d-4950-44ae-9e99-42d628f2ef01', 'DEPARTMENT-OF-ELECTR-4', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Intellectual property incentive', 'General', 60, 'Financial support shall be extended by GoK to encourage IT/ITeS companies in filing intellectual property, thereby fostering innovation and protecting proprietary assets.', '["i. Copy of the patent filing application, filing receipts, and patent grant (if granted).", "ii. Copy of Engagement, Cost Incurred towards Power of Attorney if a lawyer was involved in filing the patent.", "iii. Copy of the Letter of Patent received from the competent authority.", "iv. Self-Attested Copy detailing the expenses Incurred towards Patent Office Fee, Application Fee, Request for Examination Fee, Annual Fee, Attorney Drafting Charges, Consultancy Charges along with the supporting receipts to be submitted.", "v. Self- attested copy of the certificate of patent awarded.", "vi. English translation of the patent if the original is in another language.", "vii. Furnish complete bank account details (Account Holder Name, Bank Name, Account Number, Account type, IFSC Code, Branch Address) to facilitate the reimbursement"]', '["The IT/ITeS should be incorporated or registered in Karnataka as Private Limited Companies, / LLP/ Partnership Firms", "The IT/ ITeS entity must have at least 50% of its total workforce (employees) based in Karnataka. This count shall exclude contract employees.", "A minimum employment threshold of 10 employees in Beyound Bengaluru region and 25 employees in Bengaluru.", "The applicant shall have established a new/expansion IT/ITeS Unit in state during the policy period.", "The Applicant should have been awarded the patent within the policy period", "The applicant shall submit the application for reimbursement within twelve (12) months from the date of the award of the patent"]', '[]', '["Company should be registered under the policy", "Company should submit the incentive application along with supporting documents as prescribed in the Policy OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/itpolicy/intellectual-property-incentive', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಬೌದ್ಧಿಕ ಆಸ್ತಿ ಪ್ರೋತ್ಸಾಹಧನ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಬೌದ್ಧಿಕ ಆಸ್ತಿ ಹಕ್ಕುಗಳನ್ನು ನೋಂದಾಯಿಸಲು ಐಟಿ/ಐಟಿಇಎಸ್ (IT/ITeS) ಕಂಪನಿಗಳನ್ನು ಪ್ರೋತ್ಸಾಹಿಸುವ ಮೂಲಕ, ಆವಿಷ್ಕಾರವನ್ನು ಉತ್ತೇಜಿಸಲು ಮತ್ತು ಸ್ವಾಮ್ಯದ ಆಸ್ತಿಗಳನ್ನು ರಕ್ಷಿಸಲು ಕರ್ನಾಟಕ ಸರ್ಕಾರವು ಆರ್ಥಿಕ ನೆರವನ್ನು ಒದಗಿಸುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಐಟಿ/ಐಟಿಇಎಸ್"]', '["ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ-2025-30 ರಡಿಯಲ್ಲಿ ನೋಂದಣಿಯಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["I. ಪೇಟೆಂಟ್ ಅರ್ಜಿ ಸಲ್ಲಿಸಿರುವ ಪ್ರತಿಗಳು, ಅರ್ಜಿ ಸಲ್ಲಿಕೆ ರಸೀದಿಗಳು ಹಾಗೂ (ಮಂಜೂರಾಗಿದ್ದಲ್ಲಿ) ಪೇಟೆಂಟ್ ಮಂಜೂರಾತಿ ಪತ್ರದ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿಗಳು.", "II. ಪೇಟೆಂಟ್ ಅರ್ಜಿ ಸಲ್ಲಿಸುವ ಸಂದರ್ಭದಲ್ಲಿ ವಕೀಲರ ಸೇವೆಯನ್ನು ಬಳಸಿದ್ದಲ್ಲಿ, ಅವರ ನೇಮಕಾತಿ ದಾಖಲೆ ಹಾಗೂ ಪವರ್ ಆಫ್ ಅಟಾರ್ನಿ (Power of Attorney) ಸಂಬಂಧಿತ ವೆಚ್ಚದ ದಾಖಲೆಗಳು ಮತ್ತು ಪಾವತಿ ಪುರಾವೆಗಳು.", "III. ಸಮರ್ಥ ಪ್ರಾಧಿಕಾರದಿಂದ ನೀಡಲಾದ ಪೇಟೆಂಟ್ ಮಂಜೂರಾತಿ ಪತ್ರ (Letter of Patent)ದ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ.", "IV. ಪೇಟೆಂಟ್ ಕಚೇರಿ ಶುಲ್ಕ, ಅರ್ಜಿ ಶುಲ್ಕ, ಪರೀಕ್ಷೆಗಾಗಿ ಸಲ್ಲಿಸಿದ ವಿನಂತಿ ಶುಲ್ಕ (Request for Examination Fee), ವಾರ್ಷಿಕ ಶುಲ್ಕ, ವಕೀಲರ ಕರಡು ತಯಾರಿಕಾ ಶುಲ್ಕ (Attorney Drafting Charges), ಸಲಹಾ ಶುಲ್ಕ (Consultancy Charges) ಸೇರಿದಂತೆ ಪೇಟೆಂಟ್ ಪಡೆಯಲು ಭರಿಸಿದ ವೆಚ್ಚಗಳ ವಿವರ ಹಾಗೂ ಸಂಬಂಧಿತ ಪಾವತಿ ರಸೀದಿಗಳ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿಗಳು.", "V. ಪೇಟೆಂಟ್ ಮಂಜೂರಾಗಿರುವ ಪ್ರಮಾಣಪತ್ರದ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ.", "VI. ಪೇಟೆಂಟ್ ಮೂಲ ದಾಖಲೆ ಇಂಗ್ಲಿಷ್ ಹೊರತಾದ ಇತರೆ ಭಾಷೆಯಲ್ಲಿದ್ದಲ್ಲಿ, ಅದರ ಅಧಿಕೃತ ಇಂಗ್ಲಿಷ್ ಅನುವಾದದ ಪ್ರತಿ.", "VII. ಬ್ಯಾಂಕ್ ಖಾತೆಯ ಸಂಪೂರ್ಣ ವಿವರಗಳನ್ನು (ಖಾತೆದಾರರ ಹೆಸರು, ಬ್ಯಾಂಕ್ ಹೆಸರು, ಖಾತೆ ಸಂಖ್ಯೆ, ಖಾತೆಯ ಪ್ರಕಾರ, IFSC ಕೋಡ್ ಹಾಗೂ ಬ್ಯಾಂಕ್ ಶಾಖೆಯ ವಿಳಾಸ) ಸಲ್ಲಿಸಬೇಕು."]', NULL, NULL, '3374');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('a9eeb8ee-a3f4-4380-8156-9c49b733c80c', 'LABOUR-DEPARTMENT-13', '754e71d9-6fb5-4948-9726-3527641d0db8', 'Continuation of registration of the construction worker', 'General', 0, '', '["Self Declaration Form", "90Days Work Certificate"]', '["The worker must have worked in building or construction work for at least 90 days during the preceding 12 months."]', '[]', '["18 years or above."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', 'c1959caa-8b90-4d77-ac4e-621e337ae728', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["ಕಾರ್ಮಿಕನು ಕಳೆದ 12 ತಿಂಗಳುಗಳ ಅವಧಿಯಲ್ಲಿ ಕನಿಷ್ಠ 90 ದಿನಗಳ ಕಾಲ ಕಟ್ಟಡ ಅಥವಾ ನಿರ್ಮಾಣ ಕಾರ್ಯದಲ್ಲಿ ಕೆಲಸ ಮಾಡಿರಬೇಕು."]', '["18 ವರ್ಷ ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ವಯಸ್ಸು."]', 1, '["ಸ್ವಯಂ ಘೋಷಣಾ ನಮೂನೆ", "90 ದಿನಗಳ ಕೆಲಸದ ಪ್ರಮಾಣಪತ್ರ"]', NULL, NULL, '2957');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('3cdc7213-5e08-4eb0-9463-5e8f98888f9d', 'LABOUR-DEPARTMENT-2', '754e71d9-6fb5-4948-9726-3527641d0db8', 'Thayi Magu Sahaya Hasta', 'General', 30, '1. A registered woman construction worker who has delivered a child is eligible to avail this assistance for a period of 3 years from the date of delivery as pre-school education & Nutritional Support of the child
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('8641e02a-68a1-4d20-a844-a393fa6b544c', 'DEPARTMENT-OF-ANIMAL-5', 'e23b839a-6708-4a52-8bfd-d4e4c0a9691f', 'Vaccination Certificate for Transport of Animals', 'General', 0, 'Vaccination Certificate for Transport of Animals', '[]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '991c91bb-dda9-4d33-983e-ad37b41fc4bf', 'ಪ್ರಾಣಿಗಳ ಸಾಗಣೆಗಾಗಿ ವ್ಯಾಕ್ಸಿನೇಷನ್ ಪ್ರಮಾಣಪತ್ರ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಪ್ರಾಣಿಗಳ ಸಾಗಣೆಗಾಗಿ ವ್ಯಾಕ್ಸಿನೇಷನ್ ಪ್ರಮಾಣಪತ್ರ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, NULL);
