INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('f670cd53-8f46-43bf-afc0-0ac62bb3f73d', 'BACKWARD-CLASSES-WEL-65', '59d7c155-e129-436a-b747-c5cb6abba051', 'Loan Scheme for Higher Education in Foreign Universities:', 'Education loan', 0, '', '["Pasport Size Photo", "Study Certificate", "Passport", "Visa", "Fee Structure", "aadhaar card,ration card, caste and income certificate", "Collateral Letter", "Parent Approval Letter", "Admission Confirmation Intimation Letter Provided by the Foreign University", "document_icon", "Aadhar linked PassBook Front Page Photo"]', '["The applicant must be between 18 and 35 years of age.", "The annual family income of the applicant must be within Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas."]', '[]', '["Beneficiaries were selected through a selection committee chaired by the Chief Executive Officer of the Zilla Panchayat."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'b5963b68-1da3-4d3a-a8c1-e392b85bb32e', 'ವಿದೇಶಿ ವಿಶ್ವವಿದ್ಯಾಲಯಗಳಲ್ಲಿ ಉನ್ನತ ಶಿಕ್ಷಣ ವ್ಯಾಸಂಗಕ್ಕೆ ಸಾಲ', 'To provide loan facility up to Rs.25.00 lakhs per annum maximum of Rs.50.00 lakhs for a period of 2 years without interest to the students of vishwakarma community who are admitted to Master Degree, PhD, Post-Doctoral courses for higher education in foreign universities With QS World Ranking below 1000.', NULL, NULL, NULL, NULL, NULL, 30.00, NULL, NULL, NULL, NULL, false, 'No', '["ಅರ್ಜಿದಾರರವಯಸ್ಸು18 ರಿಂದ 35 ವರ್ಷದ ಒಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬ ವಾರ್ಷಿಕವರಮಾನ ಗ್ರಾಮಾಂತರ ಪ್ರದೇಶದವರಿಗೆರೂ.98,000/- ಹಾಗೂ ಪಟ್ಟಣಪ್ರದೇಶದವರಿಗೆರೂ.1,20,000/- ಒಳಗಿರಬೇಕು."]', '["ಮಾನ್ಯ ಮುಖ್ಯ ಕಾರ್ಯ ನಿರ್ವಹಣಾಧಿಕಾರಿಗಳು, ಜಿಲ್ಲಾ ಪಂಚಾಯತ್ ರವರ ಅಧ್ಯಕ್ಷತೆಯ ಆಯ್ಕೆ ಸಮಿತಿಯಮೂಲಕ ಫಲಾನುಭವಿಗಳನ್ನುಆಯ್ಕೆ ಮಾಡಲಾಗುವುದು."]', 1, '["ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('7f939a00-f2d0-4c8f-bdf3-b536cdb11878', 'BACKWARD-CLASSES-WEL-64', '59d7c155-e129-436a-b747-c5cb6abba051', 'Ganga Kalyana Scheme', 'Irrigational purpose to help farmers', 0, '', '["Ration card,aadhaar card,Small and Marginal Farmer Certificate,RTC,Passport size photo of the applicant"]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'b5963b68-1da3-4d3a-a8c1-e392b85bb32e', 'ಗಂಗಾ ಕಲ್ಯಾಣ ಯೋಜನೆ', 'Irrigation facilities will be provided to the small and very small farmers lands belonging to the vishwakarma community and whose annual income is below the limit of Rs.98,000/-.Bangalore North, Bangalore South, Bangalore Rural, Kolar, Chikkaballapur, Tumkur and Ramnagar unit cost Rs.4.75 lakhs for individual tube well project Rs.4.25 lakhs subsidy out of which Rs.75,000/- will be paid to ESCOM’s for electrification. In case the unit cannot be completed, a loan of Rs.50,000/- will be sanctioned at an interest rate of 4%.For the remaining districts, the unit cost is Rs.3.75 lakh in which subsidy is Rs.3.25 lakh and loan of Rs.50,000/- will be sanctioned at 4% interest rate. Out of the subsidy amount, Rs.75,000/- per tube well will be paid to the ESCOM’s for electrification.
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('3edef872-ba9f-4926-b702-850ba224cd74', 'BACKWARD-CLASSES-WEL-63', '59d7c155-e129-436a-b747-c5cb6abba051', 'Swavalambi SarathiScheme', 'self employment through taxi /goods vehicle', 0, '', '["Passport Size Photo of the applicant", "Driving Licence", "Vehicle Quotation", "Aadhar linked PassBook Front Page Photo,Ration card,aadhaar card"]', '["The applicant must be between 15 and 30 years of age.", "The annual family income of the applicant must be within Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the Chief Executive Officer of the Zilla Panchayat."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'b5963b68-1da3-4d3a-a8c1-e392b85bb32e', 'ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ ಯೋಜನೆಗೆ ಅರ್ಜಿ', 'Members of the vishwakarma community in both urban and rural areas will be encouraged to take up self-employment through the provision of a subsidy—covering 50% of the cost up to a maximum of ₹3.00 lakh—for the purchase of four-wheeled vehicles. Under the ''Swavalambi Sarathi'' scheme, this assistance will be extended to unemployed youths from the vishwakarma community who hold a valid driving license and have secured bank loans to purchase such vehicles.', NULL, NULL, NULL, NULL, NULL, 30.00, NULL, NULL, NULL, NULL, false, 'No', '["ಅರ್ಜಿದಾರರವಯಸ್ಸು15 ರಿಂದ 30 ವರ್ಷದ ಒಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬ ವಾರ್ಷಿಕವರಮಾನ ಗ್ರಾಮಾಂತರ ಪ್ರದೇಶದವರಿಗೆರೂ.98,000/- ಹಾಗೂ ಪಟ್ಟಣಪ್ರದೇಶದವರಿಗೆರೂ.1,20,000/- ಒಳಗಿರಬೇಕು."]', '["ಜಿಲ್ಲಾ ಪಂಚಾಯತ್"]', 1, '["ಅರ್ಜಿದಾರರ ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('00333947-4ab8-4665-acb3-f3b5b6f335b3', 'BACKWARD-CLASSES-WEL-62', '59d7c155-e129-436a-b747-c5cb6abba051', 'Application for Self Employment Direct Loan Scheme', 'self employment loan', 0, '', '["Pasport Size Photo", "Ration card", "Aadhar linked PassBook Front Page PhotoPasport Size Photo", "Ration card,adhaar card"]', '["The applicant must be between 15 and 30 years of age.", "The annual family income of the applicant must be within Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the Chief Executive Officer of the Zilla Panchayat."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'b5963b68-1da3-4d3a-a8c1-e392b85bb32e', 'ಸ್ವಯಂ
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('758f310c-461e-4bef-8700-77af3e92fbca', 'BACKWARD-CLASSES-WEL-61', '59d7c155-e129-436a-b747-c5cb6abba051', 'Arivu Educational Loan Scheme(renewal)', 'Education loan', 0, '', '["Caste and income certificate,Aadhaar card,Ration card,Fees structure, PUC Marks Card,CET /NEET order copy,Study Certificate(12th or PUC),Aadhar linked PassBook Front Page Photo,Admission Letter"]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'b5963b68-1da3-4d3a-a8c1-e392b85bb32e', 'ಅರಿವು ಶೈಕ್ಷಣಿಕ ಸಾಲ ಯೋಜನೆ (ನವೀಕರಣ)', 'In this scheme the selected beneficiaries in arivu fresh scheme have to apply for renewal for next academic year''s installment', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ, ಆಧಾರ್ ಕಾರ್ಡ್, ಪಡಿತರ ಚೀಟಿ, ಶುಲ್ಕದ ವಿವರ, ಪಿಯುಸಿ (PUC) ಅಂಕಪಟ್ಟಿ, ಸಿಇಟಿ (CET)/ನೀಟ್ (NEET) ಆದೇಶದ ಪ್ರತಿ, ವ್ಯಾಸಂಗ ಪ್ರಮಾಣಪತ್ರ (12ನೇ ತರಗತಿ ಅಥವಾ ಪಿಯುಸಿ), ಆಧಾರ್ ಜೋಡಣೆಯಾಗಿರುವ ಬ್ಯಾಂಕ್ ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('715ed882-cd08-4742-b9fa-ceef9bb3ab14', 'BACKWARD-CLASSES-WEL-60', '59d7c155-e129-436a-b747-c5cb6abba051', 'Arivu Educational Loan Scheme (Fresh)', 'Education loan', 0, '', '["Caste and income certificate,Aadhaar card,Ration card,Fees structure, PUC Marks Card,CET /NEET order copy,Study Certificate(12th or PUC),Aadhar linked PassBook Front Page Photo,Admission Letter"]', '["The annual income of the candidate and their family must be within the limit of ₹3.50 lakh.Age limit is 15-30 years"]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the Chief Executive Officer of the Zilla Panchayat."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'b5963b68-1da3-4d3a-a8c1-e392b85bb32e', 'ಅರಿವು ಶೈ ಕ್ಷಣಿಕ ಸಾಲ ಯೋಜನೆ (ಹೊಸ)', 'Under this scheme, an educational loan of up to ₹1,00,000—at an annual interest rate of 2%—will be sanctioned to students from the vishwakarma community who have secured admission to professional higher education courses (such as engineering, medicine, and dentistry) through CET or NEET. The annual income of the candidate and their family must be within the limit of ₹3.50 lakh.', NULL, NULL, NULL, NULL, NULL, 30.00, NULL, NULL, NULL, NULL, false, 'No', '["ಅಭ್ಯರ್ಥಿ ಮತ್ತು ಅವರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯವು ₹3.50 ಲಕ್ಷದ ಮಿತಿಯೊಳಗೆ ಇರಬೇಕು. ವಯಸ್ಸಿನ ಮಿತಿ 15 ರಿಂದ 30 ವರ್ಷಗಳು."]', '["ಜಿಲ್ಲಾ ಪಂಚಾಯತ್"]', 1, '["ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ, ಆಧಾರ್ ಕಾರ್ಡ್, ಪಡಿತರ ಚೀಟಿ, ಶುಲ್ಕದ ವಿವರ, ಪಿಯುಸಿ (PUC) ಅಂಕಪಟ್ಟಿ, ಸಿಇಟಿ (CET)/ನೀಟ್ (NEET) ಆದೇಶದ ಪ್ರತಿ, ವ್ಯಾಸಂಗ ಪ್ರಮಾಣಪತ್ರ (12ನೇ ತರಗತಿ ಅಥವಾ ಪಿಯುಸಿ), ಆಧಾರ್ ಜೋಡಣೆಯಾಗಿರುವ ಬ್ಯಾಂಕ್ ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('f0bba183-18a8-42bb-8af6-9222b01c6cb0', 'URBAN-DEVELOPMENT-DE-6', 'ec54831c-9747-4f90-b64d-a98f1f175b6a', 'change of land use', 'General', 0, 'change of land use', '["SALE DEED OR PARTITION DEED", "LATEST EC FORM NO 15 AND 16", "ORIGINAL SURVEY SKETCH SHOWING THE ALL-ROUND DIMENSIONS, VILLAGE MAP,AKARBAND DULY CERTIFIED BY COMPETENT AUTHORITY", "LATEST COPY OF RECORDS OF RIGHT RTC, COPY OF MUTATION KHATA CERTIFICATE AND LAND ACQUISITION DETAILS IF ANY", "SITE PLAN PREPARED USING TOTAL STATION SHOWING THE DIMENSIONS OF LAND, CONTOURS AND SURROUNDING DETAILS WITH IN 100 MTS. FROM THE EDGE OF THE PROPERTY", "CERTIFICATION FROM CONCERNED REVENUE AUTHORITY REGARDING PTCL 79 A B CASE UNDER KARNATAKA LAND REFORMS ACT, 1964", "GOOGLE EARTH IMAGE SHOWING LAND IN QUESTION AND SURROUNDING DEVELOPMENTS UPTO 100MTS. FROM THE EDGE OF THE PROPERTY", "APPROACH ROAD DETAILS VIZ. CLASSIFICATION OF ROAD, WIDTH OF ROAD ETC.", "APPROVED MASTER PLAN EXTRACT SHOWING THE LAND IN QUESTION"]', '["Applicant seeking approval for Single Plot LayoutPlanshall be the owner/GPA Holder of the land proposed for approval."]', '[]', '["No online service is available."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'a766e78f-05f2-440a-8461-a06c5b738719', 'ಭೂಉಪಯೋಗ ಬದಲಾವಣೆ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಭೂಉಪಯೋಗ ಬದಲಾವಣೆ', NULL, NULL, NULL, NULL, NULL, '["ವಿನ್ಯಾಸ ಅನುಮೋದನೆಗಾಗಿ ಸಲ್ಲಿಸುವ ಅರ್ಜಿದಾರರು ವಿನ್ಯಾಸ ಅನುಮೋದನೆಗಾಗಿ ಪ್ರಸ್ತಾಪಿಸಿರುವ ಜಮೀನಿನ ಮಾಲೀಕರು ಅಥವಾ ಜಿಪಿಎ ದಾರರು ಆಗಿರಬೇಕಾಗಿರುತ್ತದೆ."]', '["ಸದರಿ ಸೇವೆಯು ಆನ್ಲೈನ್ ನಲ್ಲಿ ಲಭ್ಯವಿರುವುದಿಲ್ಲ."]', 1, '["ಕ್ರಯಪತ್ರ ಅಥವಾ ವಿಭಜನಾ ಪತ್ರ", "ಇತ್ತೀಚಿನ ಇಸಿ ಫಾರ್ಮ್ ಸಂಖ್ಯೆ 15 ಮತ್ತು 16", "ಮೂಲ ಸಮೀಕ್ಷೆ ಸ್ಕೆಚ್ (ಸರ್ವಾಂಗೀಣ ಆಯಾಮಗಳನ್ನು ತೋರಿಸುತ್ತದೆ), ಗ್ರಾಮ ನಕ್ಷೆ, ಅಕರಬಂದ ಸಮರ್ಥ ಪ್ರಾಧಿಕಾರದಿಂದ ಪ್ರಮಾಣೀಕರಿಸಲ್ಪಟ್ಟಿದೆ", "ರೆಕಾರ್ಡ್ಸ್ ಆಫ್ ರೈಟ್ ಆರ್.ಟಿ.ಸಿ ಯ ಇತ್ತೀಚಿನ ಪ್ರತಿ, ರೂಪಾಂತರ ಅಥವಾ ಖಾತ ಪ್ರಮಾಣಪತ್ರದ ಪ್ರತಿ ಮತ್ತು ಭೂಸ್ವಾಧೀನ ವಿವರಗಳು ಯಾವುದಾದರೂ ಇದ್ದರೆ", "ಸೈಟ್ ಯೋಜನೆ ಸಿದ್ಧಪಡಿಸಲು ಒಟ್ಟು ಕೇಂದ್ರವನ್ನು ಬಳಸಿಕೊಂಡು 100 ಮೀಟರ್ ಳಲ್ಲಿ ಭೂಮಿ, ಬಾಹ್ಯರೇಖೆಗಳು ಮತ್ತು ಸುತ್ತಮುತ್ತಲಿನ ವಿವರಗಳನ್ನು ತೋರಿಸುವುದು", "ಪಿ.ಟಿ.ಸಿ.ಎಲ್. ಮತ್ತು 79 ಎ, ಬಿ ಕರ್ನಾಟಕ ಭೂ ಸುಧಾರಣಾ ಕಾಯ್ದೆ, 1964 ರ ಅಡಿಯಲ್ಲಿ ಸಂಬಂಧಿತ ಆದಾಯ ಪ್ರಾಧಿಕಾರದಿಂದ ಪ್ರಮಾಣೀಕರಣ", "ಗೂಗಲ್ ಅರ್ಥ್ ಚಿತ್ರವು 100 ಮೀಟರ್ ವರೆಗೆ ಪ್ರಶ್ನಾರ್ಹ ಮತ್ತು ಸುತ್ತಮುತ್ತಲಿನ ಬೆಳವಣಿಗೆಗಳನ್ನು ತೋರಿಸುವುದು", "ರಸ್ತೆ ವಿವರಗಳನ್ನು ಅಂದರೆ ರಸ್ತೆಯ ವರ್ಗೀಕರಣ, ರಸ್ತೆಯ ಅಗಲ ಇತ್ಯಾದಿ", "ಪ್ರಶ್ನಾರ್ಹ ಭೂಮಿಯನ್ನು ತೋರಿಸುವ ಅನುಮೋದಿತ ಮಾಸ್ಟರ್ ಪ್ಲಾನ್ ಸಾರ"]', NULL, NULL, NULL);
