INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('71e55db4-6219-4202-89de-8855100b88e7', 'URBAN-DEVELOPMENT-DE-8', 'ec54831c-9747-4f90-b64d-a98f1f175b6a', 'Granting of plan approval for Amalgamation & Bifurcation of residential/non-residential sites.', 'General', 0, 'Granting of plan approval for Amalgamation & Bifurcation of residential/non-residential sites.', '["Ownership records (Sale Deed/Partition Deed/GPA/etc.)", "Recent Encumbrance Certificate (EC).", "Approved layout plan/Certificate confirming the sites are within Gram Thana limits.", "Site release certificate.", "Certificate of khata registration in the local body.", "Revenue receipt.", "06 Blue print copies of sub-division and amalgation site plans prepared to the scale certified by the Engineer and Site Owner."]', '["Applicant seeking approval for Single Plot LayoutPlanshall be the owner/GPA Holder of the land proposed for approval."]', '[]', '["No online service is available."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'a766e78f-05f2-440a-8461-a06c5b738719', 'ವಸತಿ ಮತ್ತು ವಸತಿಯೇತರ ಉದ್ದೇಶದ ನಿವೇಶನಗಳಿಗೆ ಉಪವಿಭಜನೆ ಹಾಗೂ ಒಟ್ಟುಗೂಡಿಸುವಿಕೆ ನಕ್ಷೆ ಅನುಮೋದನೆ.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ವಸತಿ ಮತ್ತು ವಸತಿಯೇತರ ಉದ್ದೇಶದ ನಿವೇಶನಗಳಿಗೆ ಉಪವಿಭಜನೆ ಹಾಗೂ ಒಟ್ಟುಗೂಡಿಸುವಿಕೆ ನಕ್ಷೆ ಅನುಮೋದನೆ.', NULL, NULL, NULL, NULL, NULL, '["ವಿನ್ಯಾಸ ಅನುಮೋದನೆಗಾಗಿ ಸಲ್ಲಿಸುವ ಅರ್ಜಿದಾರರು ವಿನ್ಯಾಸ ಅನುಮೋದನೆಗಾಗಿ ಪ್ರಸ್ತಾಪಿಸಿರುವ ಜಮೀನಿನ ಮಾಲೀಕರು ಅಥವಾ ಜಿಪಿಎ ದಾರರು ಆಗಿರಬೇಕಾಗಿರುತ್ತದೆ."]', '["ಸದರಿ ಸೇವೆಯು ಆನ್ಲೈನ್ ನಲ್ಲಿ ಲಭ್ಯವಿರುವುದಿಲ್ಲ."]', 1, '["ನಿವೇಶನಗಳ ಮಾಲಿಕತ್ವದ ದಾಖಲಾತಿಗಳು (ಕ್ರಯಪತ್ರ/ವಿಭಾಗಪತ್ರ/ಜಿಪಿಎ/ಇತರೆ),", "ಇತ್ತೀಚಿನ ಋಣಭಾರರಾಹಿತ್ಯ ಪ್ರಮಾಣ ಪತ್ರ (ಇ.ಸಿ.)", "ಅನುಮೋದಿತ ವಿನ್ಯಾಸ ನಕ್ಷೆ/ನಿವೇಶನ ಗ್ರಾಮಠಾಣ ಪ್ರದೇಶದಲ್ಲಿ ಇರುವ ಬಗ್ಗೆ ದೃಢೀಕರಣ ಪತ್ರ.", "ನಿವೇಶನ ಬಿಡುಗಡೆ ಪ್ರಮಾಣ ಪತ್ರ", "ಸ್ಥಳೀಯ ಸಂಸ್ಥೆಯಲ್ಲಿ ನಿವೇಶನದ ಖಾತಾ ನೋಂದಣಿಯಾದ ದಾಖಲೆ", "ಕಂದಾಯ ರಶೀದಿ", "ಉಪವಿಭಜನೆ/ಒಟ್ಟುಗೂಡಿಸುವಿಕೆ ಬಗ್ಗೆ ಆಳತೆಗೆ ತಯಾರಿಸಿದ ಅಭಿಯಂತರರು ಮತ್ತು ನಿವೇಶನ ಮಾಲೀಕರು ದೃಢೀಕರಿಸಿದ ನೀಲ ನಕ್ಷೆಗಳ 06 ಪ್ರತಿಗಳು"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('81e39be2-3715-4e6c-9be9-7fb34a945879', 'URBAN-DEVELOPMENT-DE-5', 'ec54831c-9747-4f90-b64d-a98f1f175b6a', 'Granting Final approval to residential/nonresidential layouts. Under Section 17-2(b) of KTCP Act, 1961.', 'General', 0, 'Granting Final approval to residential/nonresidential layouts. Under Section 17-2(b) of KTCP Act, 1961.', '["No Objection Certificate/Confirmation letter obtained from the concerned Rural Drinking Water & Sanitary Department in respect of completion of water supply, storm water drain and drainage works of the layout.", "No Objection Certificate/Confirmation letter obtained from Panchayat Raj Engineering Department in respect of completion of road works of the layout.", "No Objection Certificate/Confirmation letter obtained from Horticulture Department in respect of development of park.", "Confirmation letter/service certificate obtained from BESCOM in respect of obtaining electricity connection.", "No Objection Certificate/Confirmation letter obtained from the concerned local body in respect of completion of all development works of the layout as per rules and non-registration of khatas of the sites of the residential/non-residential layout.", "No Objection Certificate obtained from Karnataka State Pollution Control Board in respect of erection of Sewage Treatment Plant (For proposals consisting more than 10.00 acres).", "Photographs showing development works and erection of chainlink fencing around civic amenity sites and park areas."]', '["Applicant seeking approval for Single Plot LayoutPlanshall be the owner/GPA Holder of the land proposed for approval."]', '[]', '["No online service is available."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'a766e78f-05f2-440a-8461-a06c5b738719', 'ತಾತ್ಕಾಲಿಕ ವಸತಿ ವಸತಿಯೇತರ ವಿನ್ಯಾಸ ನಕ್ಷೆಗೆ ಅಂತಿಮ ಅನುಮೋದನೆ ನೀಡುವುದು ಕ.ನ.ಗ್ರಾ.ಯೋ. ಕಾಯ್ದೆ.1961ರ ಕಲಂ 17(2ಬಿ).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ತಾತ್ಕಾಲಿಕ ವಸತಿ ವಸತಿಯೇತರ ವಿನ್ಯಾಸ ನಕ್ಷೆಗೆ ಅಂತಿಮ ಅನುಮೋದನೆ ನೀಡುವುದು ಕ.ನ.ಗ್ರಾ.ಯೋ. ಕಾಯ್ದೆ.1961ರ ಕಲಂ 17(2ಬಿ).', NULL, NULL, NULL, NULL, NULL, '["ವಿನ್ಯಾಸ ಅನುಮೋದನೆಗಾಗಿ ಸಲ್ಲಿಸುವ ಅರ್ಜಿದಾರರು ವಿನ್ಯಾಸ ಅನುಮೋದನೆಗಾಗಿ ಪ್ರಸ್ತಾಪಿಸಿರುವ ಜಮೀನಿನ ಮಾಲೀಕರು ಅಥವಾ ಜಿಪಿಎ ದಾರರು ಆಗಿರಬೇಕಾಗಿರುತ್ತದೆ."]', '["ಸದರಿ ಸೇವೆಯು ಆನ್ಲೈನ್ ನಲ್ಲಿ ಲಭ್ಯವಿರುವುದಿಲ್ಲ."]', 1, '["ನೀರು ಸರಬರಾಜು, ಮಳೆನೀರು ಚರಂಡಿ ಮತ್ತು ಒಳಚರಂಡಿ ಕಾಮಗಾರಿಗಳನ್ನು ಪೂರ್ಣಗೊಳಿಸುವ ಬಗ್ಗೆ ಗ್ರಾಮೀಣ ಕುಡಿಯುವ ನೀರು ಮತ್ತು ನೈರ್ಮಲ್ಯ ಇಲಾಖೆಯಿಂದ ಪಡೆದ ನಿರಾಕ್ಷೇಪಣಾ/ದೃಢೀಕರಣ ಪತ್ರ,", "ವಿನ್ಯಾಸದಲ್ಲಿನ ರಸ್ತೆ ಕಾಮಗಾರಿಗಳನ್ನು ಪೂರ್ಣಗೊಳಿಸಿರುವ ಬಗ್ಗೆ ಪಂಚಾಯತ್ ರಾಜ್ ಇಂಜಿನಿಯರಿಂಗ್ ಇಲಾಖೆಯಿಂದ ಪಡೆದ ನಿರಾಕ್ಷೇಪಣಾ/ದೃಢೀಕರಣ ಪತ್ರ,", "ವಿನ್ಯಾಸದಲ್ಲಿನ ಉದ್ಯಾನವನವನ್ನು ಅಭಿವೃದ್ಧಿಪಡಿಸಿರುವ ಬಗ್ಗೆ ತೋಟಗಾರಿಕೆ ಇಲಾಖೆಯಿಂದ ಪಡೆದ ನಿರಾಕ್ಷೇಪಣಾ/ದೃಢೀಕರಣ ಪತ್ರ,", "ವಿದ್ಯುತ್ ಸಂಪರ್ಕ ಪಡೆದ ಬಗ್ಗೆ ಬೆಸ್ಕಾಂನಿಂದ ಪಡೆದ ಸೇವಾ ದೃಢೀಕರಣ ಪತ್ರ,", "ವಿನ್ಯಾಸದ ಎಲ್ಲಾ ಅಭಿವೃದ್ಧಿ ಕಾಮಗಾರಿಗಳನ್ನು ನಿಯಮಾನುಸಾರ ಅಭಿವೃದ್ಧಿಪಡಿಸಿರುವ ಬಗ್ಗೆ ಮತ್ತು ಸದರಿ ವಸತಿ/ವಸತಿಯೇತರ ವಿನ್ಯಾಸದಲ್ಲಿನ ನಿವೇಶನಗಳ ಖಾತಾ ದಾಖಲಾಗದೇ ಇರುವ ಬಗ್ಗೆ ಸಂಬಂಧಪಟ್ಟ ಸ್ಥಳೀಯ ಸಂಸ್ಥೆಯಿಂದ ಪಡೆದ ಪಡೆದ ನಿರಾಕ್ಷೇಪಣಾ/ದೃಢೀಕರಣ ಪತ್ರ,", "ತ್ಯಾಜ್ಯ ನೀರು ಸಂಸ್ಕರಣಾ ಘಟಕ (Sewage Treatment Plant) ನಿರ್ಮಾಣ ಮಾಡಿರುವ ಬಗ್ಗೆ ಕರ್ನಾಟಕ ರಾಜ್ಯ ಮಾಲಿನ್ಯ ನಿಯಂತ್ರಣ ಮಂಡಳಿಯ ನಿರಾಕ್ಷೇಪಣಾ ಪತ್ರ (10 ಎಕರೆ ವಿಸ್ತೀರ್ಣ ಮೇಲ್ಪಟ್ಟ ಪ್ರಸ್ತಾವನೆಗಳಿಗೆ),", "ಅಭಿವೃದ್ಧಿ ಕಾಮಗಾರಿಗಳನ್ನು ತೋರಿಸುವ ಹಾಗೂ ನಾಗರೀಕ ಸೌಲಭ್ಯ ನಿವೇಶನ ಮತ್ತು ಉದ್ಯಾನವನ ಪ್ರದೇಶಗಳಿಗೆ ಚೈನ್ ಲಿಂಗ್ ಫೆನ್ಸಿಂಗ್ ಅಳವಡಿಸಿರುವ ಬಗ್ಗೆ ಛಾಯಾಚಿತ್ರಗಳು,"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('c617d83a-febc-44c0-b79b-85c39942995c', 'URBAN-DEVELOPMENT-DE-4', 'ec54831c-9747-4f90-b64d-a98f1f175b6a', 'After 1st Instalment of 40% site released in the Provisionally approved layout plan or granting Final Approval of residential/non residential layout (subdivision) and release of 60% remaining sites. Under Section 17 (2b) of KTCP Act, 1961.', 'General', 0, 'After 1st Instalment of 40% site released in the Provisionally approved layout plan or granting Final Approval of residential/non residential layout (subdivision) and release of 60% remaining sites. Under Section 17 (2b) of KTCP Act, 1961.', '["No Objection Certificate/Confirmation letter obtained from the concerned Rural Drinking Water & Sanitary Department in respect of completion of water supply, storm water drain and drainage works of the layout.", "No Objection Certificate/Confirmation letter obtained from Panchayat Raj Engineering Department in respect of completion of road works of the layout.", "No Objection Certificate/Confirmation letter obtained from Horticulture Department in respect of development of park.", "Confirmation letter/service certificate obtained from BESCOM in respect of obtaining electricity connection.", "No Objection Certificate/Confirmation letter obtained from the concerned local body in respect of completion of all development works of the layout as per rules and non-registration of khatas of the sites of the residential/non-residential layout.", "No Objection Certificate obtained from Karnataka State Pollution Control Board in respect of erection of Sewage Treatment Plant (For proposals consisting more than 10.00 acres).", "Photographs showing development works and erection of chainlink fencing around civic amenity sites and park areas."]', '["Applicant seeking approval for Single Plot LayoutPlanshall be the owner/GPA Holder of the land proposed for approval."]', '[]', '["No online service is available."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'a766e78f-05f2-440a-8461-a06c5b738719', 'ಮೊದಲನೇ ಹಂತದ ಶೇ.40ರಷ್ಟು ನಿವೇಶನಗಳನ್ನು ಬಿಡುಗಡೆಗೊಳಿಸಿರುವ ತಾತ್ಕಾಲಿಕ ಅನುಮೋದಿತ ವಸತಿ/ವಸತಿಯೇತರ ವಿನ್ಯಾಸ ನಕ್ಷೆಗೆ ಶೇ.60ರಷ್ಟು ಅಂತಿಮ ಹಂತದ ನಿವೇಶನಗಳ ಬಿಡುಗಡೆಯೊಂದಿಗೆ ಅಂತಿಮ ಅನುಮೋದನೆ ನೀಡುವುದು. ಕ.ನ.ಗ್ರಾ.ಯೋ. ಕಾಯ್ದೆ, 1961ರ ಕಲಂ 17(2ಬಿ)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಮೊದಲನೇ ಹಂತದ ಶೇ.40ರಷ್ಟು ನಿವೇಶನಗಳನ್ನು ಬಿಡುಗಡೆಗೊಳಿಸಿರುವ ತಾತ್ಕಾಲಿಕ ಅನುಮೋದಿತ ವಸತಿ/ವಸತಿಯೇತರ ವಿನ್ಯಾಸ ನಕ್ಷೆಗೆ ಶೇ.60ರಷ್ಟು ಅಂತಿಮ ಹಂತದ ನಿವೇಶನಗಳ ಬಿಡುಗಡೆಯೊಂದಿಗೆ ಅಂತಿಮ ಅನುಮೋದನೆ ನೀಡುವುದು. ಕ.ನ.ಗ್ರಾ.ಯೋ. ಕಾಯ್ದೆ, 1961ರ ಕಲಂ 17(2ಬಿ)', NULL, NULL, NULL, NULL, NULL, '["ವಿನ್ಯಾಸ ಅನುಮೋದನೆಗಾಗಿ ಸಲ್ಲಿಸುವ ಅರ್ಜಿದಾರರು ವಿನ್ಯಾಸ ಅನುಮೋದನೆಗಾಗಿ ಪ್ರಸ್ತಾಪಿಸಿರುವ ಜಮೀನಿನ ಮಾಲೀಕರು ಅಥವಾ ಜಿಪಿಎ ದಾರರು ಆಗಿರಬೇಕಾಗಿರುತ್ತದೆ."]', '["ಸದರಿ ಸೇವೆಯು ಆನ್ಲೈನ್ ನಲ್ಲಿ ಲಭ್ಯವಿರುವುದಿಲ್ಲ."]', 1, '["ನೀರು ಸರಬರಾಜು, ಮಳೆನೀರು ಚರಂಡಿ ಮತ್ತು ಒಳಚರಂಡಿ ಕಾಮಗಾರಿಗಳನ್ನು ಪೂರ್ಣಗೊಳಿಸುವ ಬಗ್ಗೆ ಗ್ರಾಮೀಣ ಕುಡಿಯುವ ನೀರು ಮತ್ತು ನೈರ್ಮಲ್ಯ ಇಲಾಖೆಯಿಂದ ಪಡೆದ ನಿರಾಕ್ಷೇಪಣಾ/ದೃಢೀಕರಣ ಪತ್ರ,", "ವಿನ್ಯಾಸದಲ್ಲಿನ ರಸ್ತೆ ಕಾಮಗಾರಿಗಳನ್ನು ಪೂರ್ಣಗೊಳಿಸಿರುವ ಬಗ್ಗೆ ಪಂಚಾಯತ್ ರಾಜ್ ಇಂಜಿನಿಯರಿಂಗ್ ಇಲಾಖೆಯಿಂದ ಪಡೆದ ನಿರಾಕ್ಷೇಪಣಾ/ದೃಢೀಕರಣ ಪತ್ರ,", "ವಿನ್ಯಾಸದಲ್ಲಿನ ಉದ್ಯಾನವನವನ್ನು ಅಭಿವೃದ್ಧಿಪಡಿಸಿರುವ ಬಗ್ಗೆ ತೋಟಗಾರಿಕೆ ಇಲಾಖೆಯಿಂದ ಪಡೆದ ನಿರಾಕ್ಷೇಪಣಾ/ದೃಢೀಕರಣ ಪತ್ರ,", "ವಿದ್ಯುತ್ ಸಂಪರ್ಕ ಪಡೆದ ಬಗ್ಗೆ ಬೆಸ್ಕಾಂನಿಂದ ಪಡೆದ ಸೇವಾ ದೃಢೀಕರಣ ಪತ್ರ,", "ವಿನ್ಯಾಸದ ಎಲ್ಲಾ ಅಭಿವೃದ್ಧಿ ಕಾಮಗಾರಿಗಳನ್ನು ನಿಯಮಾನುಸಾರ ಅಭಿವೃದ್ಧಿಪಡಿಸಿರುವ ಬಗ್ಗೆ ಮತ್ತು ಸದರಿ ವಸತಿ/ವಸತಿಯೇತರ ವಿನ್ಯಾಸದಲ್ಲಿನ ನಿವೇಶನಗಳ ಖಾತಾ ದಾಖಲಾಗದೇ ಇರುವ ಬಗ್ಗೆ ಸಂಬಂಧಪಟ್ಟ ಸ್ಥಳೀಯ ಸಂಸ್ಥೆಯಿಂದ ಪಡೆದ ಪಡೆದ ನಿರಾಕ್ಷೇಪಣಾ/ದೃಢೀಕರಣ ಪತ್ರ,", "ತ್ಯಾಜ್ಯ ನೀರು ಸಂಸ್ಕರಣಾ ಘಟಕ (Sewage Treatment Plant) ನಿರ್ಮಾಣ ಮಾಡಿರುವ ಬಗ್ಗೆ ಕರ್ನಾಟಕ ರಾಜ್ಯ ಮಾಲಿನ್ಯ ನಿಯಂತ್ರಣ ಮಂಡಳಿಯ ನಿರಾಕ್ಷೇಪಣಾ ಪತ್ರ (10 ಎಕರೆ ವಿಸ್ತೀರ್ಣ ಮೇಲ್ಪಟ್ಟ ಪ್ರಸ್ತಾವನೆಗಳಿಗೆ),", "ಅಭಿವೃದ್ಧಿ ಕಾಮಗಾರಿಗಳನ್ನು ತೋರಿಸುವ ಹಾಗೂ ನಾಗರೀಕ ಸೌಲಭ್ಯ ನಿವೇಶನ ಮತ್ತು ಉದ್ಯಾನವನ ಪ್ರದೇಶಗಳಿಗೆ ಚೈನ್ ಲಿಂಗ್ ಫೆನ್ಸಿಂಗ್ ಅಳವಡಿಸಿರುವ ಬಗ್ಗೆ ಛಾಯಾಚಿತ್ರಗಳು,"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('0a56003c-57f5-489e-ab64-9f96df3c17a9', 'URBAN-DEVELOPMENT-DE-3', 'ec54831c-9747-4f90-b64d-a98f1f175b6a', 'Releasing 1st instalment of 40% sites for registration if the Applicant has requested to release in the layout provisionally approved for residential/non-residential (sub-division). Under Section 17 of KTCP Act, 1961.', 'General', 0, 'Releasing 1st instalment of 40% sites for registration if the Applicant has requested to release in the layout provisionally approved for residential/non-residential (sub-division). Under Section 17 of KTCP Act, 1961.', '["Registration letter from RERA.", "Copy of the provisionally approved residential/non-residential layout plan.", "Copy of map showing the 40% release of sites in dispersed manner as per provisionally approved residential/non-residential layout plan"]', '["Applicant seeking approval for Single Plot LayoutPlanshall be the owner/GPA Holder of the land proposed for approval."]', '[]', '["No online service is available."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'a766e78f-05f2-440a-8461-a06c5b738719', 'ವಸತಿ /ವಸತಿಯೇತರ ಉದ್ದೇಶಕ್ಕಾಗಿ (ಉಪ ವಿಭಜನೆ) ವಿನ್ಯಾಸ ನಕ್ಷೆಗೆ ತಾತ್ಕಾಲಿಕ ಅನುಮೋದನೆ ನೀಡುವುದರಲ್ಲಿ ಅರ್ಜಿದಾರರು ಮೋದಲನೇ ಹಂತದ ಶೇ.40ರಷ್ಟು ನಿವೇಶನೆಗಳನ್ನು ನೋಂದಾವಣೆಗಾಗಿ ಬಿಡುಗಡೆ ಮಾಡಲು ಕೋರಿದಲ್ಲಿ ಬಿಡುಗಡೆ ಮಾಡುವ ಬಗ್ಗೆ. ಕ.ನ.ಗ್ರಾ.ಯೋ. ಕಾಯ್ದೆ 1961ರ ಕಲಂ 17 (2ಸಿ).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ವಸತಿ /ವಸತಿಯೇತರ ಉದ್ದೇಶಕ್ಕಾಗಿ (ಉಪ ವಿಭಜನೆ) ವಿನ್ಯಾಸ ನಕ್ಷೆಗೆ ತಾತ್ಕಾಲಿಕ ಅನುಮೋದನೆ ನೀಡುವುದರಲ್ಲಿ ಅರ್ಜಿದಾರರು ಮೋದಲನೇ ಹಂತದ ಶೇ.40ರಷ್ಟು ನಿವೇಶನೆಗಳನ್ನು ನೋಂದಾವಣೆಗಾಗಿ ಬಿಡುಗಡೆ ಮಾಡಲು ಕೋರಿದಲ್ಲಿ ಬಿಡುಗಡೆ ಮಾಡುವ ಬಗ್ಗೆ. ಕ.ನ.ಗ್ರಾ.ಯೋ. ಕಾಯ್ದೆ 1961ರ ಕಲಂ 17 (2ಸಿ).', NULL, NULL, NULL, NULL, NULL, '["ವಿನ್ಯಾಸ ಅನುಮೋದನೆಗಾಗಿ ಸಲ್ಲಿಸುವ ಅರ್ಜಿದಾರರು ವಿನ್ಯಾಸ ಅನುಮೋದನೆಗಾಗಿ ಪ್ರಸ್ತಾಪಿಸಿರುವ ಜಮೀನಿನ ಮಾಲೀಕರು ಅಥವಾ ಜಿಪಿಎ ದಾರರು ಆಗಿರಬೇಕಾಗಿರುತ್ತದೆ."]', '["ಸದರಿ ಸೇವೆಯು ಆನ್ಲೈನ್ ನಲ್ಲಿ ಲಭ್ಯವಿರುವುದಿಲ್ಲ."]', 1, '["ರೇರಾ ಪ್ರಾಧಿಕಾರದ ನೋಂದಣಿ ಪತ್ರ,", "ತಾತ್ಕಾಲಿಕ ಅನುಮೋದಿತ ವಸತಿ/ವಸತಿಯೇತರ ವಿನ್ಯಾಸ ನಕ್ಷೆ ಪ್ರತಿ,", "ತಾತ್ಕಾಲಿಕ ಅನುಮೋದಿತ ವಸತಿ/ವಸತಿಯೇತರ ವಿನ್ಯಾಸ ನಕ್ಷೆಯಂತೆ ಶೇ.40ರಷ್ಟು ಚದುರಿದಂತೆ ನಿವೇಶನಗಳನ್ನು ಬಿಡುಗಡೆಗೊಳಿಸಲು ಉದ್ದೇಶಿಸಿ ಗುರುತಿಸಿರುವ ನಕ್ಷೆ,"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('f961318c-dac4-412a-8b35-f32025f1bab3', 'URBAN-DEVELOPMENT-DE-2', 'ec54831c-9747-4f90-b64d-a98f1f175b6a', 'Multiple plot layout approval', 'General', 0, 'Approval of Multi plot layout for residencial and other use', '["Ownership records (Sale Deed/Partition Deed/GPA/etc.)", "Recent Encumbrance Certificate (EC).", "Recent Pahani (R.T.C.).", "Recent Mutation Register copy (M.R.).", "Akarband.", "Hissa and Note.", "Conversion Order copies.", "Survey sketch certified by the Assistant Director of Land Records.", "Draft layout plan prepared as per the Survey sketch in accordance with sketch provided by Assistant Director of Land Records and Zonal Regulations.", "No Objection Certificate in connection with water supply and maintenance of infrastructure facilities obtained from the concerned Local Body.", "No Objection Certificate obtained from Karnataka State Pollution Control Board (CFE) (For proposals consisting more than 10.00 acres).", "Part of Master Plan.", "Google map.", "Village map.", "Declaration letter duly notarized in a stamp paper with a face value of Rs.100/- declaring that all the documents submitted are true and correct.", "Notarised Stamp Paper for Joint Development, if required.", "Copy of Aadhar Card along with the signature of all the owners of survey numbers consisted in the proposal."]', '["Applicant seeking approval for Single Plot LayoutPlanshall be the owner/GPA Holder of the land proposed for approval."]', '[]', '["No online service is available."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'a766e78f-05f2-440a-8461-a06c5b738719', 'ಬಹು ನಿವೇಶನ ವಿನ್ಯಾಸ ಅನುಮೋದನೆ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಬಹು ನಿವೇಶನ ವಸತಿ ಹಾಗೂ ಇತರೆ ಉದ್ದೇಶಕ್ಕಾಗಿ ವಿನ್ಯಾಸ ಅನುಮೋದನೆ', NULL, NULL, NULL, NULL, NULL, '["ವಿನ್ಯಾಸ ಅನುಮೋದನೆಗಾಗಿ ಸಲ್ಲಿಸುವ ಅರ್ಜಿದಾರರು ವಿನ್ಯಾಸ ಅನುಮೋದನೆಗಾಗಿ ಪ್ರಸ್ತಾಪಿಸಿರುವ ಜಮೀನಿನ ಮಾಲೀಕರು ಅಥವಾ ಜಿಪಿಎ ದಾರರು ಆಗಿರಬೇಕಾಗಿರುತ್ತದೆ."]', '["ಸದರಿ ಸೇವೆಯು ಆನ್ಲೈನ್ ನಲ್ಲಿ ಲಭ್ಯವಿರುವುದಿಲ್ಲ."]', 1, '["ಮಾಲಿಕತ್ವದ ದಾಖಲಾತಿಗಳು (ಕ್ರಯಪತ್ರ ಅಥವ ವಿಭಾಗಪತ್ರ ಅಥವ ಜಿಪಿಎ ಅಥವ ಇತರೆ)", "ಇತ್ತೀಚಿನ ಋಣಭಾರರಾಹಿತ್ಯ ಪ್ರಮಾಣಪತ್ (ಇ.ಸಿ.)", "ಇತ್ತೀಚಿನ ಪಹಣಿ (ಆರ್.ಟಿ.ಸಿ.),", "ಇತ್ತೀಚಿನ ಮ್ಯುಟೇಷನ್ ರಿಜಿಸ್ಟರ್ ಪ್ರತಿ (ಎಂ.ಆರ್.)", "ಆಕಾರ್ ಬಂದ್", "ಹಿಸ್ಸಾ ಮತ್ತು ಟಿಪ್ಪಣಿ", "ಭೂ ಪರಿವರ್ತನಾ ಆದೇಶದ ಪ್ರತಿಗಳು", "ಭೂ ದಾಖಲೆಗಳ ಸಹಾಯಕ ನಿರ್ದೇಶಕರು ದೃಢೀಕರಿಸಿದ ಸರ್ವೆ ನಕ್ಷೆ", "ಭೂ ದಾಖಲೆಗಳ ಸಹಾಯಕ ನಿರ್ದೇಶಕರು ದೃಢೀಕರಿಸಿದ ಸರ್ವೆ ನಕ್ಷೆಗೆ ಅನುಗುಣವಾಗಿ ವಲಯ ನಿಯಮಾವಳಿಗಳಂತೆ ತಯಾರಿಸಿರುವ ಕರಡು ಏಕ ನಿವೇಶನ ವಿನ್ಯಾಸ ನಕ್ಷೆ,", "ನೀರು ಸರಬರಾಜು ಸಂಬಂಧಪಟ್ಟ ಸ್ಥಳೀಯ ಸಂಸ್ಥೆಯಿಂದ ಪಡೆದ ನಿರಾಕ್ಷೇಪಣಾ ಪತ್ರ", "ಕರ್ನಾಟಕ ರಾಜ್ಯ ಮಾಲಿನ್ಯ ನಿಯಂತ್ರಣ ಮಂಡಳಿಯ ನಿರಾಕ್ಷೇಪಣಾ ಪತ್ರ (ವಸತಿಯೇತರ ಏಕ ನಿವೇಶನ ವಿನ್ಯಾಸ ನಕ್ಷೆ ಅನುಮೋದನೆಗೆ ಸಂಬಂಧಿಸಿದಂತೆ 10 ಎಕರೆ ವಿಸ್ತೀರ್ಣ ಮೇಲ್ಪಟ್ಟ ಪ್ರಸ್ತಾವನೆಗಳಿಗೆ),", "ಮಹಾಯೋಜನೆಯ ಉಧೃತ ಭಾಗ,", "ಗೂಗಲ್ ನಕ್ಷೆ", "ಗೂಗಲ್ ನಕ್ಷೆ", "ಸಲ್ಲಿಸಿರುವ ಎಲ್ಲಾ ದಾಖಲಾತಿಗಳು ಸರಿಯಾಗಿರುತ್ತವೆ ಎಂಬ ಬಗ್ಗೆ ರೂ.100 ಮುಖಬೆಲೆಯ ನೋಟರೀಕೃತ ಘೋಷಣಾಪತ್ರ", "ಪ್ರಸ್ತಾವನೆಯಲ್ಲಿರುವ ಜಮೀನುಗಳ ಸರ್ವೆ ನಂ.ಗಳ ಎಲ್ಲಾ ಭೂ ಮಾಲೀಕರ ಸಹಿಯೊಂದಿಗೆ ಆಧಾರ್ ಕಾರ್ಡ್ ಪ್ರತಿ", "ಅರ್ಜಿದಾರರ ಅಧಾರ್"]', NULL, NULL, NULL);
