INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('c2415ee7-ff7a-45a8-9901-63efa262007c', 'DEPARTMENT-OF-ANIMAL-16', 'e23b839a-6708-4a52-8bfd-d4e4c0a9691f', 'Application for issue of permit for purchase of kerosene to motorized fishing boats', 'General', 7, 'This service provides Permit to purchase kerosene to motorized fishing boats.', '["Boat registration certificate copy", "License fee", "Transponder installation certificate"]', '["Should be owner of Motorized fishing boat which has been registered in the Department."]', '[]', '["Applicant logs into Seva Sindhu portal or approaches CSC operator.", "Portal will provide the user credentials to the Applicant", "Applicant will fill the application in the Portal and submit.", "Application will be verified by the Concerned authority and approves if correect or reject if not correct.", "Applicant to provide clarification through re-submission of documents if requested by the Department", "The approving authority approves and applicant collects the digitally signed certificate or the approving authority rejects stating reasons for rejection and applicant collects the endorsement ."]', NULL, NULL, 'https://frims.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', 'a5eb9149-3a3c-4821-b7d0-06c387671e85', 'ಮೋಟರೀಕೃತ ನಾಡದೋಣಿಗಳಿಗೆ ಸೀಮೆಎಣ್ಣೆ ಖರೀದಿಗೆ ಪರವಾನಗಿ ನೀಡಲು ಅರ್ಜಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಈ ಸೇವೆಯು ಮೋಟಾರೀಕೃತ ಮೀನುಗಾರಿಕೆ ದೋಣಿಗಳಿಗೆ ಸೀಮೆಎಣ್ಣೆ ಖರೀದಿಗೆ ಪರ್ಮಿಟ್', NULL, NULL, NULL, NULL, NULL, '["ಇಲಾಖೆಯಲ್ಲಿ ನೋಂದಣಿಗೊಂಡ ಮೋಟರೀಕೃತ ದೋಣಿಯ ಮಾಲೀಕರಾಗಿರಬೇಕು"]', '["ಅರ್ಜಿದಾರರು ಸೇವಾ ಸಿಂಧು ಪೋರ್ಟಲ್"]', 1, '["ದೋಣಿ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರದ ಪ್ರತಿ", "ಪರವಾನಗಿ ಶುಲ್ಕ", "ಟ್ರಾನ್ಸ್"]', NULL, NULL, NULL);
