INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('7cd42538-eb7a-4d3d-932f-9064588b646d', 'DEPARTMENT-OF-ANIMAL-14', 'e23b839a-6708-4a52-8bfd-d4e4c0a9691f', 'Approval of Beneficiary for Assistance to purchase of life saving equipments', 'General', 60, 'This service provides assistance to fishermen for the purchase of life-saving equipment. The applicant must possess a valid boat registration number and fishing licence.', '["Address proof document", "Applicant’s photograph", "Identity proof", "Boat Registration Certificate", "Licence", "Caste Certificate"]', '["Need to have boat registration number and license letter"]', '[]', '["Applicant logs into Seva Sindhu portal or approaches CSC operator.", "Portal will provide the user credentials to the Applicant", "Applicant will fill the application in the Portal and submit.", "Application will be verified by the Concerned authority and approves if correect or reject if not correct.", "Applicant to provide clarification through re-submission of documents if requested by the Department", "The approving authority approves and applicant collects the digitally signed certificate or the approving authority rejects stating reasons for rejection and applicant collects the endorsement ."]', NULL, NULL, 'https://frims.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', 'a5eb9149-3a3c-4821-b7d0-06c387671e85', 'ಜೀವ ರಕ್ಷಕ ಸಾಧನ ಖರೀದಿಸಲು ಸಹಾಯಧನ ವಿತರಣೆಗೆ ಫಲಾನುಭವಿಗಳ ಪಟ್ಟಿಗೆ ಅನುಮೋದನೆ ನೀಡುವುದು', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಈ ಸೇವೆಯು ಜೀವ ಉಳಿಸುವ ಉಪಕರಣಗಳನ್ನು ಖರೀದಿಸಲು ಮೀನುಗಾರಿಕೆಗೆ ಸಹಾಯವನ್ನು ಒದಗಿಸುತ್ತದೆ. ದೋಣಿ ನೋಂದಣಿ ಸಂಖ್ಯೆ ಮತ್ತು ಪರವಾನಗಿ ಪತ್ರವನ್ನು ಹೊಂದಿರಬೇಕು', NULL, NULL, NULL, NULL, NULL, '["ದೋಣಿ ನೋಂದಣಿ ಸಂಖ್ಯೆ ಮತ್ತು ಪರವಾನಗಿ ಪತ್ರವನ್ನು ಹೊಂದಿರಬೇಕು"]', '["ಅರ್ಜಿದಾರರು ಸೇವಾ ಸಿಂಧು ಪೋರ್ಟಲ್"]', 1, '["ವಿಳಾಸದೃಡೀಕರಿ ಸಲು ದಾಖಲೆ", "ಅರ್ಜಿದಾರರ ಫೋಟೋ", "ಗುರುತಿನ ಪುರಾವೆ", "ಬೋಟ್ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರ", "ಪರವಾನಗಿ ಪತ್ರ", "ಜಾತಿ ಪ್ರಮಾಣಪತ್ರ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('eb561519-6347-4267-b74b-0df4e4c3a6a4', 'DEPARTMENT-OF-ANIMAL-13', 'e23b839a-6708-4a52-8bfd-d4e4c0a9691f', 'Providing Relief to distress fishermen', 'General', 90, 'This Service provides relief to fisher who are in distress in case of death or loss of boat/nets', '["Eligibility / Required Documents:", "Photograph of the deceased", "Photograph of the applicant", "Identity proof", "Copy of the FIR", "Inquest report", "Post-mortem report", "Police case diary", "Final police report", "Genealogy/family tree or details of family members", "No-Objection Certificate (NOC) from family members for payment of compensation to one person only", "Newspaper report", "Original purchase bill of the boat/net", "Details of expenditure incurred for repair of the boat", "Original bills for repair expenses", "Medical report"]', '["Nominee of fisher (in case of death) or fisher who lost his /her boat/net and any medical expenses incurred"]', '[]', '["Applicant logs into Seva Sindhu portal or approaches CSC operator.", "Portal will provide the user credentials to the Applicant", "Applicant will fill the application in the Portal and submit.", "Application will be verified by the Concerned authority and approves if correect or reject if not correct.", "Applicant to provide clarification through re-submission of documents if requested by the Department", "The approving authority approves and applicant collects the digitally signed certificate or the approving authority rejects stating reasons for rejection and applicant collects the endorsement ."]', NULL, NULL, 'https://frims.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', 'a5eb9149-3a3c-4821-b7d0-06c387671e85', 'ಸಂಕಷ್ಟದಲ್ಲಿರುವ ಮೀನುಗಾರರಿಗೆ ಪರಿಹಾರ ನೀಡುವುದು', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಈ ಸೇವೆಯು ತೊಂದರೆಗೀಡಾದ (ಮೃತ/ ದೋಣಿ ಹಾನಿ/ಬಲೆ ಹಾನಿ) ಮೀನುಗಾರರಿಗೆ ಪರಿಹಾರವನ್ನು ಒದಗಿಸುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '["ಮರಣ ಸಂಭವಿಸಿದಲ್ಲಿ, ದೋಣಿ ಅಥವಾ ಬಲೆ ಕಳೆದುಕೊಂಡಲ್ಲಿ ಹಾಗೂ ಉಂಟಾದ ಯಾವುದೇ ವೈದ್ಯಕೀಯ ವೆಚ್ಚಗಳ ಸಂದರ್ಭದಲ್ಲಿ"]', '["ಅರ್ಜಿದಾರರು ಸೇವಾ ಸಿಂಧು ಪೋರ್ಟಲ್"]', 1, '["ಅರ್ಹತೆ: 1.ಮೃತರ ಫೋಟೋ", "ಅರ್ಜಿದಾರರ ಫೋಟೋ", "ಗುರುತಿನ ಪುರಾವೆ", "ಎಫ್ಐಆರ್ ಕಾಪಿ", "ಇನ್ವೆಸ್ಟ್ ರಿಪೋರ್ಟ್", "ಪೋಸ್ಟ್ಮಾರ್ಟಂವರದಿ", "ಪೊಲೀಸ್ ಕೇಸ್ ಡೈರಿ", "ಪೊಲೀಸ್ ಅಂತಿಮ ವರದಿ", "ಸಂತತಿನಕ್ಷೆ/ಕುಟುಂಬ ಸದಸ್ಯರ ಮಾಹಿತಿ", "ಒಬ್ಬವ್ಯಕ್ತಿಗೆ ಮಾತ್ರಪರಿಹಾರ ಮೊತ್ತವನ್ನುನೀಡಲು ಕುಟುಂಬದ ಸದಸ್ಯರ ನಿರಪೇಕ್ಷಣಾಪತ್ರ.", "ವೃತ್ತಪತ್ರಿಕೆ ವರದಿ", "ಬೋಟ್/ನೆಟ್ಖ ರೀದಿಸಿದ ಬಿಲ್ಲ್ ನ ಮೂಲಪ್ರತಿ", "ದೋಣಿಗಳ ದುರಸ್ತಿ ಕಾರ್ಯಕ್ಕೆ ತಗುಲಿದವೆಚ್ಚ", "ದುರಸ್ಥಿಯ ಖರ್ಚಿನ ಮೂಲಬಿಲ್", "ವೈದ್ಯರವರದಿ"]', NULL, NULL, NULL);
