INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('cebabd78-3877-4bcb-aea5-cd3818410b92', 'LABOUR-DEPARTMENT-6', '754e71d9-6fb5-4948-9726-3527641d0db8', 'Marriage Assistance', 'General', 60, '1. The Secretary or any other authorized in this behalf by the Board, shall on an application from a registered construction worker, sanction a sum of Rs.60,000/- (Rupees Fifty Thousand Only) as assistance to meet the marriage expenses of the worker or his/her two dependent children
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('a6e03c24-55cf-4c57-9857-434510a4c512', 'LABOUR-DEPARTMENT-7', '754e71d9-6fb5-4948-9726-3527641d0db8', 'Assistance for Major Ailments', 'General', 45, 'This scheme provides financial assistance up to ₹2,00,000 for registered construction workers or their dependents undergoing treatment for major ailments, as defined by the Board. The amount is based on CGHS rates and is subject to approval by the Secretary or authorized officer. The application process is digital, with strict validation of eligibility, documents, and hospital recognition.', '["Medical Report (Detailed diagnosis from the treating hospital)", "Discharge Summary (Summary issued post-treatment)", "Form 22-A (Certified by Assistant Surgeon / Hospital Head)", "Self-Declaration by Applicant (Confirms authenticity of claim)", "90 Days Work Certificate (Proof of work duration)"]', '["Applicant must be a registered worker with KBOCWWB.", "Minimum 90 days of work in the past 1 year.", "Treatment must be for a covered major ailment.", "Form XXII (claim) and Form XXII-A (medical certification) must be submitted."]', '[]', '["Fill digital application form with all required uploads.", "System validates eligibility, documents, and hospital recognition.", "Application is reviewed by Secretary/authorized officer.", "If approved, benefit is disbursed as per CGHS rates (max ₹2,00,000)."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', 'c1959caa-8b90-4d77-ac4e-621e337ae728', 'ಗಂಭೀರ ರೋಗಗಳ ಚಿಕಿತ್ಸಾ ನೆರವು', 'This scheme provides financial assistance up to ₹2,00,000 for registered construction workers or their dependents undergoing treatment for major ailments, as defined by the Board. The amount is based on CGHS rates and is subject to approval by the Secretary or authorized officer. The application process is digital, with strict validation of eligibility, documents, and hospital recognition.', NULL, NULL, NULL, NULL, NULL, NULL, 'ಈ ಯೋಜನೆಯು ನೋಂದಾಯಿತ ಕಟ್ಟಡ ಕಾರ್ಮಿಕರು ಅಥವಾ ಅವರ ಅವಲಂಬಿತರು ಗಂಭೀರ ಕಾಯಿಲೆಗಳ ಚಿಕಿತ್ಸೆಗಾಗಿ ₹2,00,000 ವರೆಗೆ ಆರ್ಥಿಕ ಸಹಾಯವನ್ನು ಒದಗಿಸುತ್ತದೆ, ಇದು ಮಂಡಳಿಯ ಮೂಲಕ ವ್ಯಾಖ್ಯಾನಿಸಲಾಗಿದೆ. ಈ ಮೊತ್ತವು CGHS ದರಗಳ ಆಧಾರದ ಮೇಲೆ ಇದೆ ಮತ್ತು ಕಾರ್ಯದರ್ಶಿ ಅಥವಾ ಅಧಿಕಾರಿಯ ಅನುಮೋದನೆಗೆ ಒಳಪಟ್ಟಿದೆ. ಅರ್ಜಿಯ ಪ್ರಕ್ರಿಯೆ ಡಿಜಿಟಲ್ ಆಗಿದ್ದು, ಅರ್ಹತೆ, ದಾಖಲೆಗಳು ಮತ್ತು ಆಸ್ಪತ್ರೆ ಗುರುತಿನ ಕಠಿಣ ಪರಿಶೀಲನೆ ಇದೆ.', NULL, NULL, NULL, true, 'Yes', '["ಅರ್ಜಿದಾರನು ಕೆಬಿಒಸಿಡಬ್ಲ್ಯೂಡಬ್ಲ್ಯೂಬಿ ನೊಂದಿಗೆ ನೋಂದಾಯಿತ ಕಾರ್ಮಿಕನಾಗಿರಬೇಕು.", "ಕನಿಷ್ಠ 1 ವರ್ಷದ ಅವಧಿಯಲ್ಲಿ 90 ದಿನಗಳ ಕೆಲಸದ ಅವಶ್ಯಕತೆ ಇದೆ.", "ಚಿಕಿತ್ಸೆ ಕವರ್ ಮಾಡಿದ ಗಂಭೀರ ಕಾಯಿಲೆಗೆ ಸಂಬಂಧಿಸಿದಂತೆ ಇರಬೇಕು.", "ನಮೂನೆ XXII (ಕ್ಲೇಮ್) ಮತ್ತು ನಮೂನೆ XXII-A (ವೈದ್ಯಕೀಯ ಪ್ರಮಾಣೀಕರಣ) ಸಲ್ಲಿಸಬೇಕು."]', '["ದಾಖಲೆಗಳೊಂದಿಗೆ ಡಿಜಿಟಲ್ ಅರ್ಜಿ ನಮೂನೆಯನ್ನು ಭರ್ತಿ ಮಾಡಿ.", "ಸಿಸ್ಟಮ್ ಅರ್ಹತೆ, ದಾಖಲೆಗಳು ಮತ್ತು ಆಸ್ಪತ್ರೆ ಮಾನ್ಯತೆಯನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ.", "ಅರ್ಜಿ ಕಾರ್ಯದರ್ಶಿ/ಅಧಿಕೃತ ಅಧಿಕಾರಿಯು ಪರಿಶೀಲಿಸುತ್ತಾನೆ.", "ಅನುಮೋದಿತ হলে, CGHS ದರಗಳ ಪ್ರಕಾರ (ಗರಿಷ್ಠ ₹2,00,000) ಪ್ರಯೋಜನವನ್ನು ವಿತರಿಸಲಾಗುತ್ತದೆ."]', 1, '["ವೈದ್ಯಕೀಯ ವರದಿ (ಚಿಕಿತ್ಸೆ ನೀಡುವ ಆಸ್ಪತ್ರೆಯಿಂದ ವಿವರವಾದ ನಿರ್ಣಯ)", "ಆಸ್ಪತ್ರೆ ಬಿಡುಗಡೆ ಸಾರಾಂಶ (ಚಿಕಿತ್ಸೆಯ ನಂತರ ನೀಡುವ ಸಾರಾಂಶ)", "ನಮೂನೆ 22-A (ಸಹಾಯಕ ಶಸ್ತ್ರಚಿಕಿತ್ಸಕ / ಆಸ್ಪತ್ರೆ ಮುಖ್ಯಸ್ಥರಿಂದ ಪ್ರಮಾಣಿತ)", "ಅರ್ಜಿದಾರನಿಂದ ಸ್ವಯಂ-ಘೋಷಣೆ (ಕ್ಲೇಮ್"]', NULL, NULL, '2960');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('8ff14857-4dc0-46c9-b1c1-c0a8f1e34371', 'LABOUR-DEPARTMENT-8', '754e71d9-6fb5-4948-9726-3527641d0db8', 'Continuation of Disability Pension', 'General', 30, 'The Board or authorized officer may Sanction an amount of Rs. 2000/- (Govt of Karnataka Notification NO 106 LET 2019,Bengaluru, Dated:14-11-2019) per month as disability pension to a beneficiary, who is partially disabled due to any disease or accident at worksite and for an ex¬gratia payment of not more than Rs. 2,00,000/- (Rupees two lakhs only) depending upon the percentage of disability
