INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('a5662f7e-f3f8-4d62-80ae-de06901ca6cc', 'LABOUR-DEPARTMENT-10', '754e71d9-6fb5-4948-9726-3527641d0db8', 'Funeral and Ex-Gratia', 'General', 45, '1. If registered construction worker dies, the Secretary, or any other officer authorized in this behalf by the Board, shall pay a sum of [Rs. 4,000(Rupees four thousand only)] to the nominee of the deceased registered construction worker to meet the funeral expenses of the deceased registered construction worker [and an ex gratia amount of Rs. 1,46,000 (One Lakh Forty Six Thousand Rupees Only) shall also be paid to the nominee of the deceased registered construction worker to mitigate the financial hardship caused by the sudden demise
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('e3fe8065-e2db-4c75-9978-694a3f4de090', 'LABOUR-DEPARTMENT-11', '754e71d9-6fb5-4948-9726-3527641d0db8', 'Pension', 'General', 30, '1. Every registered building or other construction worker beneficiary, who has completed sixty years of age and A registered construction worker must have continued as a beneficiary of the Board for at least 03 years before the age of 60
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('936861a0-8f2c-49fb-9f60-4286e2f1c2c8', 'REVENUE-DEPARTMENT-50', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'KARAB LAND EXTRACT/UTAR', 'General', 7, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (KARAB LAND EXTRACT/UTAR)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಖರಾಬ್', NULL, NULL, NULL, NULL, NULL, 70.00, NULL, 'ಖರಾಬ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3053');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('4f0294ef-0d35-4c62-ad2e-f1fa7038648c', 'EDUCATION-DEPARTMENT-5', 'bd235dfc-9efa-4507-aaf0-f78a93e05e6a', 'Online Photocopy Software', 'General', 0, 'After the results are announced, students can apply for a photocopy of their answer scripts using their Register Number. This allows them to review their answers and verify the marks given.', '["Register Number"]', '["Students who has written exams in that particular academic year"]', '[]', '["KSEAB Website → Online Services → SSLC → Photocopy/Scanned Copy of Answer Script → Enter Register Number → Select Subject(s) → Pay the prescribed fee → Submit Application → Receive SMS when the answer script is uploaded → Download the scanned answer script."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', 'e61a6e68-d61f-4782-a4e6-388fca3e3652', 'ಆನ್', 'After the results are announced, students can apply for a photocopy of their answer scripts using their Register Number. This allows them to review their answers and verify the marks given.', NULL, 'Urban & Rural', NULL, NULL, 400.00, NULL, 'ಫಲಿತಾಂಶ ಪ್ರಕಟವಾದ ನಂತರ, ವಿದ್ಯಾರ್ಥಿಗಳು ತಮ್ಮ ನೋಂದಣಿ ಸಂಖ್ಯೆಯನ್ನು (Register Number) ಬಳಸಿ ಉತ್ತರ ಪತ್ರಿಕೆಯ ಛಾಯಾಪ್ರತಿಗಾಗಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು. ಇದರ ಮೂಲಕ ವಿದ್ಯಾರ್ಥಿಗಳು ತಮ್ಮ ಉತ್ತರಗಳನ್ನು ಪರಿಶೀಲಿಸಿ, ನೀಡಲಾಗಿರುವ ಅಂಕಗಳನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಬಹುದು.', NULL, NULL, NULL, true, 'YES', '["ಶೈಕ್ಷಣಿಕ ವರ್ಷದಲ್ಲಿ ಪರೀಕ್ಷೆ ಬರೆದ ವಿದ್ಯಾರ್ಥಿಗಳು"]', '["KSEAB ವೆಬ್"]', 1, '["ನೋಂದಣಿ ಸಂಖ್ಯೆ"]', NULL, NULL, '3433');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('34a8bf60-025e-4599-abe3-9c6a426a9ea8', 'BACKWARD-CLASSES-WEL-19', '59d7c155-e129-436a-b747-c5cb6abba051', 'Application for Self Employment Direct Loan Scheme', 'self employment loan', 0, '', '["Pasport Size Photo", "Ration card", "Aadhar linked PassBook Front Page PhotoPasport Size Photo", "Ration card,adhaar card"]', '["The applicant must be between 15 and 30 years of age.", "The annual family income of the applicant must be within Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the Chief Executive Officer of the Zilla Panchayat."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'd83d205e-20ba-4379-8718-eb4c4fc2452f', 'ಸ್ವಯಂ
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('efbc85f3-dcce-4dd7-8876-ee0e3359b054', 'BACKWARD-CLASSES-WEL-18', '59d7c155-e129-436a-b747-c5cb6abba051', 'Arivu Educational Loan Scheme(renewal)', 'Education loan', 0, '', '["Caste and income certificate,Aadhaar card,Ration card,Fees structure, PUC Marks Card,CET /NEET order copy,Study Certificate(12th or PUC),Aadhar linked PassBook Front Page Photo,Admission Letter"]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'd83d205e-20ba-4379-8718-eb4c4fc2452f', 'ಅರಿವು ಶೈಕ್ಷಣಿಕ ಸಾಲ ಯೋಜನೆ (ನವೀಕರಣ)', 'In this scheme the selected beneficiaries in arivu fresh scheme have to apply for renewal for next academic year''s installment', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ, ಆಧಾರ್ ಕಾರ್ಡ್, ಪಡಿತರ ಚೀಟಿ, ಶುಲ್ಕದ ವಿವರ, ಪಿಯುಸಿ (PUC) ಅಂಕಪಟ್ಟಿ, ಸಿಇಟಿ (CET)/ನೀಟ್ (NEET) ಆದೇಶದ ಪ್ರತಿ, ವ್ಯಾಸಂಗ ಪ್ರಮಾಣಪತ್ರ (12ನೇ ತರಗತಿ ಅಥವಾ ಪಿಯುಸಿ), ಆಧಾರ್ ಜೋಡಣೆಯಾಗಿರುವ ಬ್ಯಾಂಕ್ ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('b25fc80c-a0e9-4026-a85c-cc3bd7ed6043', 'BACKWARD-CLASSES-WEL-17', '59d7c155-e129-436a-b747-c5cb6abba051', 'Arivu Educational Loan Scheme (Fresh)', 'Education loan', 0, '', '["Caste and income certificate,Aadhaar card,Ration card,Fees structure, PUC Marks Card,CET /NEET order copy,Study Certificate(12th or PUC),Aadhar linked PassBook Front Page Photo,Admission Letter"]', '["The annual income of the candidate and their family must be within the limit of ₹3.50 lakh.Age limit is 15-30 years"]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the Chief Executive Officer of the Zilla Panchayat."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'd83d205e-20ba-4379-8718-eb4c4fc2452f', 'ಅರಿವು ಶೈ ಕ್ಷಣಿಕ ಸಾಲ ಯೋಜನೆ (ಹೊಸ)', 'Under this scheme, an educational loan of up to ₹1,00,000—at an annual interest rate of 2%—will be sanctioned to students from the savitha community who have secured admission to professional higher education courses (such as engineering, medicine, and dentistry) through CET or NEET. The annual income of the candidate and their family must be within the limit of ₹3.50 lakh.', NULL, NULL, NULL, NULL, NULL, 30.00, NULL, NULL, NULL, NULL, false, 'No', '["ಅಭ್ಯರ್ಥಿ ಮತ್ತು ಅವರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯವು ₹3.50 ಲಕ್ಷದ ಮಿತಿಯೊಳಗೆ ಇರಬೇಕು. ವಯಸ್ಸಿನ ಮಿತಿ 15 ರಿಂದ 30 ವರ್ಷಗಳು."]', '["ಜಿಲ್ಲಾ ಪಂಚಾಯತ್"]', 1, '["ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ, ಆಧಾರ್ ಕಾರ್ಡ್, ಪಡಿತರ ಚೀಟಿ, ಶುಲ್ಕದ ವಿವರ, ಪಿಯುಸಿ (PUC) ಅಂಕಪಟ್ಟಿ, ಸಿಇಟಿ (CET)/ನೀಟ್ (NEET) ಆದೇಶದ ಪ್ರತಿ, ವ್ಯಾಸಂಗ ಪ್ರಮಾಣಪತ್ರ (12ನೇ ತರಗತಿ ಅಥವಾ ಪಿಯುಸಿ), ಆಧಾರ್ ಜೋಡಣೆಯಾಗಿರುವ ಬ್ಯಾಂಕ್ ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('c642de38-a565-4989-ac90-fdeca098064f', 'REVENUE-DEPARTMENT-138', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Aacharya traya Jayanti Celebration', 'Achievers from the Brahmin community who have made significant contributions in various fields will be felicitated and honored.', 0, 'Achievers from the Brahmin community who have made significant contributions in various fields will be felicitated and honored.', '[]', '["Belongs to Karnataka"]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'e7e36aba-85e5-4c55-9f21-2324bd60deb0', 'ಆಚಾರ್ಯ ತ್ರಯ ಜಯಂತಿ ಆಚರಣೆ', 'On behalf of the Board, the birth anniversaries of Sri Shankaracharya, Sri Ramanujacharya, and Sri Madhvacharya are celebrated annually under the program titled "Acharya Trayara Jayanti."', NULL, 'All over Karnataka', NULL, NULL, 0.00, 0.00, 'ವಿವಿಧ ಕ್ಷೇತ್ರದಲ್ಲಿ ಗಣನೀಯ ಸಾಧನೆಗೈದ ಬ್ರಾಹ್ಮಣ ಸಮುದಾಯದ ಸಾಧಕರನ್ನು ಸನ್ಮಾನಿಸಿ ಗೌರವಿಸಲಾಗುವುದು.', NULL, NULL, NULL, false, 'NO', '["ಕರ್ನಾಟಕದ ಖಾಯಂ ನಿವಾಸಿಯಾಗಿರಬೇಕು"]', '[]', 1, '[]', NULL, NULL, NULL);
