INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('5cf40081-bfa4-4662-bfaa-6b8363579b91', 'BACKWARD-CLASSES-WEL-54', '59d7c155-e129-436a-b747-c5cb6abba051', 'Swavalambi Sarathi Scheme', 'Subsidy', 0, 'Under Swabalambi Sarathi Scheme, Unemployed Youths Belonging To Backward Classes Will Get A 50% Or Up To A Maximum Of Rs.300000/- Subsidy For The Purchase Of Four-Wheelers Through Bank Loan', '["Caste and family annual income certificate obtained from the concerned Taluk Tahsildar (Mandatory)", "Attested xerox copy of the light motor vehicle driving licence (Mandatory)", "Ration card / voter ID card / Aadhaar card issued by competent authorities as proof of residence (Mandatory)", "Three recent passport size photographs of the applicant (Mandatory)", "Quotation obtained from the supplier of the four-wheeler the applicant intends to purchase (Mandatory)", "Name and address of the bank / financial institution branch from which the loan is sought, with a xerox copy of the pass book (Mandatory)", "Additional documents sought by the bank / financial institution for loan sanction, to be provided to the bank / financial institution (Mandatory)", "Xerox copy of the applicant''s Aadhaar card (Mandatory)"]', '["Applicant must be an unemployed youth belonging to Alemari /arey alemari caste and its sub castes", "Applicant must hold a light motor vehicle driving licence.", "Family annual income must not exceed Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas.", "Must be a permanent resident of Karnataka State.", "Applicant''s age must be between 21 and 45 years.", "Must not have previously availed benefits under the Corporation''s schemes.", "Must compulsorily hold an account in a bank branch within the area where the applicant resides.", "Only one member per family is eligible.", "Must compulsorily hold an Aadhaar-linked account in a nationalised bank.", "Priority is given to women under this scheme.", "Priority is also given to transgender persons under this scheme.", "The beneficiary must register the vehicle for self-driven taxi (Yellow Board) purpose."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the MLA of the respective constituency"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '3e2c95ab-7236-462d-95bc-42da1aaef8ac', 'ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ ಯೋಜನೆ', 'Swavalambi Sarathi', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ ಯೋಜನೆಯಡಿ ನಿಗಮವು ಹಿಂದುಳಿದ ವರ್ಗಗಳಿಗೆ ಸೇರಿದ ನಿರುದ್ಯೋಗಿ ಯುವಜನರು ನಾಲ್ಕು ಚಕ್ರ ವಾಹನ ಖರೀದಿಗೆ ಪಡೆಯುವ ಸಾಲಕ್ಕೆ ಶೇ.50 ರಷ್ಟು ಅಥವಾ ಗರಿಷ್ಠ ರೂ.300000/- ಸಹಾಯಧನ.', NULL, NULL, NULL, NULL, NULL, '["ಅರ್ಜಿದಾರರು ಅಲೆಮಾರಿ ಹಾಗೂ ಅರೆ ಅಲೆಮಾರಿ ಜಾತಿಗೆ ಸೇರಿದ ನಿರುದ್ಯೋಗಿ ಯುವಕರಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಲಘು ವಾಹನ ಚಾಲನಾ ಪರವಾನಗಿಯನ್ನು ಹೊಂದಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ವರಮಾನ ಗ್ರಾಮಾಂತರ ಪ್ರದೇಶದವರಿಗೆ ರೂ. 98,000/-ಗಳು ಪಟ್ಟಣ ಪ್ರದೇಶದವರಿಗೆ ರೂ. 1,20,000/-ಗಳನ್ನು ಮೀರಿರಬಾರದು.", "ಕರ್ನಾಟಕ ರಾಜ್ಯದ ಖಾಯಂ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು ಕನಿಷ್ಠ 21 ರಿಂದ 45 ವರ್ಷಗಳ ಮಿತಿಯೊಳಗಿರಬೇಕು.", "ಈ ಹಿಂದೆ ನಿಗಮದ ಯೋಜನೆಗಳಲ್ಲಿ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಈ ಯೋಜನೆಯಲ್ಲಿ ಸವಲತ್ತು ಪಡೆಯ ಬಯಸುವ ಅರ್ಜಿದಾರರು ವಾಸಿಸುತ್ತಿರುವ ವ್ಯಾಪ್ತಿಗೆ ಬರುವ ಬ್ಯಾಂಕ್ ಶಾಖೆಯಲ್ಲಿ ಖಾತೆಯನ್ನು ಕಡ್ಡಾಯವಾಗಿ ಹೊಂದಿರಬೇಕು.", "ಒಂದು ಕುಟುಂಬದ ಒಬ್ಬ ಸದಸ್ಯರಿಗೆ ಮಾತ್ರ ಸೌಲಭ್ಯ ಒದಗಿಸಲಾಗುವುದು.", "ಕಡ್ಡಾಯವಾಗಿ ರಾಷ್ಟ್ರೀಕೃತ ಬ್ಯಾಂಕುಗಳಲ್ಲಿ ಆಧಾರ್ ಸಂಯೋಜನೆಯಾಗಿರುವ ಖಾತೆ ಹೊಂದಿರಬೇಕು.", "ಈ ಯೋಜನೆಯಲ್ಲಿ ಮಹಿಳೆಯರಿಗೆ ಆದ್ಯತೆ ನೀಡುವುದು.", "ಈ ಯೋಜನೆಯಲ್ಲಿ ಮಂಗಳಮುಖಿಯರಿಗೂ ಸಹ ಆದ್ಯತೆ ನೀಡುವುದು.", "ಈ ಯೋಜನೆಯಲ್ಲಿ ಸೌಲಭ್ಯ ಪಡೆಯುವ ಫಲಾನುಭವಿಯು ಸ್ವಯಂ ಟ್ಯಾಕ್ಸಿ ಚಾಲನೆ (Yellow Board) ಉದ್ದೇಶಕ್ಕೆ ವಾಹನವನ್ನು ನೋಂದಾಯಿಸತಕ್ಕದ್ದು."]', '["ಸಂಬಂಧಿತ ಕ್ಷೇತ್ರದ ಶಾಸಕರ ಅಧ್ಯಕ್ಷತೆಯ ಆಯ್ಕೆ ಸಮಿತಿಯ ಮೂಲಕ ಫಲಾನುಭವಿಗಳನ್ನು ಆಯ್ಕೆ ಮಾಡಲಾಗುವುದು."]', 1, '["ಸಂಬಂಧಿಸಿದ ತಾಲ್ಲೂಕು ತಹಶೀಲ್ದಾರರಿಂದ ಪಡೆದ ಜಾತಿ / ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಪ್ರಮಾಣ ಪತ್ರ (ಕಡ್ಡಾಯ)", "ಲಘು ವಾಹನ ಚಾಲನಾ ಪರವಾನಗಿಯ ದೃಢೀಕೃತ ಜೆರಾಕ್ಸ್ ಪ್ರತಿ (ಕಡ್ಡಾಯ)", "ಅರ್ಜಿದಾರರ ವಾಸದ ಪುರಾವೆಗಾಗಿ ಸಕ್ಷಮ ಪ್ರಾಧಿಕಾರಿಗಳು ನೀಡಿದ ಪಡಿತರ ಚೀಟಿ / ಚುನಾವಣಾ ಗುರುತಿನ ಚೀಟಿ / ಆಧಾರ್ ಕಾರ್ಡ್ (ಕಡ್ಡಾಯ)", "ಅರ್ಜಿದಾರರ ಪಾಸ್"]', NULL, NULL, NULL);
