INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('78b84fea-39a3-4d8d-b832-526dfa9cfdec', 'ENERGY-DEPARTMENT-20', 'e0b8deb9-4426-4525-a8e5-aab3f707df7c', 'Application for additional load / New connection- Supply of electricity does not require any extension of distribution mains, or commissioning of new substations-Rural Areas', 'General', 0, '', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '665dc58e-475b-4883-93a4-8761c3bf0063', 'ಹೊಸ ಸಂಪರ್ಕ/ ಹೆಚ್ಚುವರಿ ಲೋಡ್', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '2996');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('9bab34fc-f826-4ba7-8c6f-9df63591a9bd', 'BACKWARD-CLASSES-WEL-53', '59d7c155-e129-436a-b747-c5cb6abba051', 'Self Employment Direct Loan Scheme', 'Loan with Subsidy', 0, 'Based on the self-employment/economic activity undertaken by persons belonging to backward classes, loans of a minimum of Rs. 1.00 lakh and a maximum of Rs. 2.00 lakhs shall be sanctioned at an annual interest rate of 4%. The scheme includes a subsidy of 20% (Rs. 20,000/-) on loans of Rs. 1.00 lakh, and a subsidy of 15%, subject to a maximum of Rs. 30,000/-, on loan amounts ranging from Rs. 1.00 lakh to Rs. 2.00 lakhs', '["Aadhaar card (Mandatory)", "Caste Certificate (Mandatory)", "Income certificate (Mandatory)"]', '["Applicant must belong to Alemari /arey alemari caste and sub castes and must produce a caste certificate obtained from the concerned Tahsildar.", "Family annual income must be within Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas.", "Applicant''s age must be above 18 years and within 55 years.", "Should be a permanent resident of Karnataka State.", "Those who have received a subsidy or loan under any other scheme of the Corporation are not eligible for this scheme.", "Only one candidate per family is eligible."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the MLA of the respective constituency"]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '3e2c95ab-7236-462d-95bc-42da1aaef8ac', 'ಸ್ವಯಂ
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('70770452-cd86-4732-9a2f-18c8a87b0b5a', 'BACKWARD-CLASSES-WEL-52', '59d7c155-e129-436a-b747-c5cb6abba051', 'Ganga Kalyana Irrigation Scheme', 'Loan with Subsidy', 0, 'Backward class small and marginal farmers should have minimum 1 acre of land in Udupi, Dakshina Kannada, Kodagu, Uttara Kannada, Chikkamagaluru, Shimoga and Hassan districts under individual irrigation scheme. Subsidy of Rs.2.00 lakhs and loan of Rs.50,000/- at an interest rate of 4% per annum for those having at least 2 acres of contiguous land in the remaining districts. Under Collective Irrigation Borewell Scheme 8-15 acres of land owned by at least 3 small and micro farmers 2 borewells at a cost of Rs.4.00 lakhs and for units covering more than 15 acres of land at fixed unit cost of Rs.6.00 lakhs Drill 3 borewells and supply pumpset and equipment and pay deposit for electrification Providing electricity connection and irrigation facility, fully subsidised.', '["Small Farmer & Marginal Farmers Certificate (Mandatory)", "Other Document (Mandatory)"]', '["Applicant must belong toAlemari /arey alemaricaste and its sub castes must be a small or marginal farmer, and must produce a caste certificate obtained from the concerned Tahsildar.", "The existing land must be rain-fed and must not have irrigation facility from any source.", "Under the individual irrigation borewell scheme, the applicant must hold at least 2 acres of land.", "Under the collective irrigation borewell scheme, at least 3 small and marginal farmers must jointly hold 8 acres or more of land.", "Must not have availed a loan or other financial assistance under any scheme of the corporations coming under the Backward Classes Welfare Department.", "Family annual income must be within Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas.", "Only one candidate per family is eligible.", "Must possess a ration card."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the MLA of the respective constituency"]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '3e2c95ab-7236-462d-95bc-42da1aaef8ac', 'ಗಂಗಾ ಕಲ್ಯಾಣ ನೀರಾವರಿ ಯೋಜನೆ', 'Ganga Kalyana', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಹಿಂದುಳಿದ ವರ್ಗಗಳ ಸಣ್ಣ ಮತ್ತು ಅತಿಸಣ್ಣ ರೈತರ ವೈಯುಕ್ತಿಕ ನೀರಾವರಿ ಯೋಜನೆಯಲ್ಲಿ ಉಡುಪಿ, ದಕ್ಷಿಣ ಕನ್ನಡ, ಕೊಡಗು, ಉತ್ತರ ಕನ್ನಡ, ಚಿಕ್ಕಮಗಳೂರು, ಶಿವಮೊಗ್ಗ ಮತ್ತು ಹಾಸನ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಕನಿಷ್ಠ 1 ಎಕರೆ ಜಮೀನು ಹೊಂದಿರಬೇಕು. ಉಳಿಕೆ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಒಂದೇ ಸ್ಥಳದಲ್ಲಿ ಹೊಂದಿಕೊಂಡಂತೆ ಇರುವ ಕನಿಷ್ಠ 2 ಎಕರೆ ಜಮೀನು ಹೊಂದಿರುವವರಿಗೆ ರೂ.2.00ಲಕ್ಷಗಳ ಸಹಾಯಧನ (ಸಬ್ಸಿಡಿ) ಹಾಗೂ ವಾರ್ಷಿಕ ಶೇ.4ರ ಬಡ್ಡಿದರದಲ್ಲಿ ರೂ.50,000/-ಗಳ ಸಾಲ. ಸಾಮೂಹಿಕ ನೀರಾವರಿ ಕೊಳವೆಬಾವಿ ಯೋಜನೆಯಡಿ ಕನಿಷ್ಠ 3 ಜನ ಸಣ್ಣ ಮತ್ತು ಅತಿಸಣ್ಣ ರೈತರು ಹೊಂದಿರುವ 8-15 ಎಕರೆ ಜಮೀನಿಗೆ ರೂ.4.00ಲಕ್ಷಗಳ ವೆಚ್ಚದಲ್ಲಿ 2 ಕೊಳವೆಬಾವಿ ಹಾಗೂ 15 ಎಕರೆಗಿಂತ ಹೆಚ್ಚು ಜಮೀನು ಒಳಪಡುವ ಘಟಕಗಳಿಗೆ ನಿಗದಿತ ಘಟಕವೆಚ್ಚ ರೂ.6.00ಲಕ್ಷಗಳ ವೆಚ್ಚದಲ್ಲಿ 3 ಕೊಳವೆಬಾವಿಗಳನ್ನು ಕೊರೆಯಿಸಿ ಪಂಪ್ಸೆಟ್ ಮತ್ತು ಉಪಕರಣಗಳನ್ನು ಸರಬರಾಜು ಮಾಡುವುದು ಹಾಗೂ ವಿದ್ಯುದ್ದೀಕರಣಕ್ಕೆ ಠೇವಣಿ ಪಾವತಿಸಿ ವಿದ್ಯುತ್ ಸಂಪರ್ಕ ಕಲ್ಪಿಸಿ ನೀರಾವರಿ ಸೌಲಭ್ಯ ಒದಗಿಸುವುದು. ಇದು ಪೂರ್ಣ ಅನುದಾನವಾಗಿರುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಅರ್ಜಿದಾರರು ಅಲೆಮಾರಿ ಹಾಗೂ ಅರೆ ಅಲೆಮಾರಿ ಜಾತಿಗೆ ಸೇರಿದವರಾಗಿರಬೇಕು ಮತ್ತು ಸಮರ್ಥ ಪ್ರಾಧಿಕಾರದಿಂದ ಪಡೆದ ಜಾತಿ ಪ್ರಮಾಣಪತ್ರವನ್ನು ಸಲ್ಲಿಸಬೇಕು..", "ಹಾಲಿ ಜಮೀನುಗಳಿಗೆ ಯಾವುದೇ ಮೂಲದಿಂದ ನೀರಾವರಿ ಸೌಲಭ್ಯ ಹೊಂದಿಲ್ಲದೆ ಮಳೆ ಆಧಾರಿತವಾಗಿ ಖುಷ್ಕಿಯಾಗಿರಬೇಕು.", "ವೈಯಕ್ತಿಕ ನೀರಾವರಿ ಕೊಳವೆ ಬಾವಿ ಯೋಜನೆಯಡಿ ಅರ್ಜಿದಾರರು ಕನಿಷ್ಠ ಎರಡು ಎಕರೆ ಜಮೀನು ಹೊಂದಿರಬೇಕು.", "ಸಾಮೂಹಿಕ ನೀರಾವರಿ ಕೊಳವೆ ಬಾವಿ ಯೋಜನೆಯಡಿ ಕನಿಷ್ಠ 3 ಜನ ಸಣ್ಣ ಮತ್ತು ಅತಿಸಣ್ಣ ರೈತರು ಒಟ್ಟಾಗಿ 8 ಎಕರೆ ಅಥವಾ ಹೆಚ್ಚು ಜಮೀನು ಹೊಂದಿರಬೇಕು.", "ಹಿಂದುಳಿದ ವರ್ಗಗಳ ಇಲಾಖೆ ವ್ಯಾಪ್ತಿಯಲ್ಲಿ ಒಳಪಡುವ ನಿಗಮಗಳಲ್ಲಿ ಬೇರೆ ಯಾವುದೇ ಯೋಜನೆಗಳಲ್ಲಿ ಸಾಲ ಅಥವಾ ಇತರೆ ಆರ್ಥಿಕ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಕುಟುಂಬದ ವಾರ್ಷಿಕ ವರಮಾನ ಗ್ರಾಮಾಂತರ ಪ್ರದೇಶದವರಿಗೆ ರೂ. 98,000/- ಹಾಗೂ ಪಟ್ಟಣ ಪ್ರದೇಶದವರಿಗೆ ರೂ. 1,20,000/-ಗಳ ಮಿತಿಯಲ್ಲಿರಬೇಕು.", "ಒಂದು ಕುಟುಂಬದಲ್ಲಿ ಒಬ್ಬ ಅಭ್ಯರ್ಥಿಗೆ ಮಾತ್ರ ಅವಕಾಶವಿರುತ್ತದೆ.", "ರೇಷನ್ ಕಾರ್ಡ್ ಹೊಂದಿರಬೇಕು."]', '["ಸಂಬಂಧಿತ ಕ್ಷೇತ್ರದ ಶಾಸಕರ ಅಧ್ಯಕ್ಷತೆಯ ಆಯ್ಕೆ ಸಮಿತಿಯ ಮೂಲಕ ಫಲಾನುಭವಿಗಳನ್ನು ಆಯ್ಕೆ ಮಾಡಲಾಗುವುದು."]', 1, '["ಸಣ್ಣ ಮತ್ತು ಅತಿ ಸಣ್ಣ ರೈತ ಪ್ರಮಾಣಪತ್ರ (ಕಡ್ಡಾಯ)", "ಇತರ ದಾಖಲೆ (ಕಡ್ಡಾಯ)"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('49754146-5c93-4d05-8b9f-97c63f58a0a8', 'BACKWARD-CLASSES-WEL-51', '59d7c155-e129-436a-b747-c5cb6abba051', 'Arivu Educational Loan Scheme (Fresh)', 'Loan', 0, 'Students belonging to Backward Classes, admitted through Common Entrance Test (CET) will be given a loan of Rs.1.00 lakhs per annum for academic development up to a maximum of Rs.4.00 to Rs.5.00 lakhs for the duration of the course at an interest rate of 2% per annum.', '["Aadhar Card (Mandatory)", "Caste certificate (Mandatory)", "Income certificate (Mandatory)", "Parent Approval Letter (Mandatory)", "Colleteral Letter (Mandatory)"]', '["Applicant must belong to Alemari /arey alemari caste and its sub caste and must produce a caste certificate obtained from the competent authority.", "Must have secured admission to a degree or postgraduate degree course through a common entrance examination (CET / NEET etc.).", "The candidate''s family annual income must be within Rs. 3.50 lakhs.", "Applicant''s age must be between 18 and 30 years."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '3e2c95ab-7236-462d-95bc-42da1aaef8ac', 'ಅರಿವು ಶೈಕ್ಷಣಿಕ ಸಾಲ ಯೋಜನೆ (ಹೊಸತು)', 'Arivu Fresh Loan', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಸಾಮಾನ್ಯ ಪ್ರವೇಶ ಪರೀಕ್ಷೆ ಮೂಲಕ(ಸಿ.ಇ.ಟಿ.) ಪ್ರವೇಶ ಪಡೆದ ಹಿಂದುಳಿದ ವರ್ಗಗಳ ಸೇರಿದ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ಶೈಕ್ಷಣಿಕಾಭಿವೃದ್ಧಿಗಾಗಿ ಅರಿವು ಶೈಕ್ಷಣಿಕ ಸಾಲ ಯೋಜನೆಯಡಿ ವಾರ್ಷಿಕ ರೂ.1.00ಲಕ್ಷಗಳಂತೆ ಕೋರ್ಸ್ ಅವಧಿಗೆ ಗರಿಷ್ಠ ರೂ.4.00 ರಿಂದ ರೂ.5.00 ಲಕ್ಷಗಳ ವರೆಗೆ ವಾರ್ಷಿಕ ಶೇ.2 ಬಡ್ಡಿದರದಲ್ಲಿ ಸಾಲ ನೀಡಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಅರ್ಜಿದಾರರು ಅಲೆಮಾರಿ ಹಾಗೂ ಅರೆ ಅಲೆಮಾರಿ ಜಾತಿಗೆ ಸೇರಿರಬೇಕು ಹಾಗೂ ಸಂಬಂಧಪಟ್ಟ ಪ್ರಾಧಿಕಾರದಿಂದ ಪಡೆದ ಜಾತಿ ಪ್ರಮಾಣ ಪತ್ರವನ್ನು ಹಾಜರುಪಡಿಸಬೇಕು.", "ಸಾಮಾನ್ಯ ಪ್ರವೇಶ ಪರೀಕ್ಷೆ ಮೂಲಕ (ಸಿ.ಇ.ಟಿ. / ನೀಟ್ / ಇತ್ಯಾದಿ) ಪದವಿ / ಸ್ನಾತಕೋತ್ತರ ಪದವಿ ಕೋರ್ಸ್"]', '[]', 1, '["ಆಧಾರ್ ಕಾರ್ಡ್ (ಕಡ್ಡಾಯ)", "ಜಾತಿ ಪ್ರಮಾಣ ಪತ್ರ (ಕಡ್ಡಾಯ)", "ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ (ಕಡ್ಡಾಯ)", "ಪೋಷಕರ ಅನುಮೋದನೆ ಪತ್ರ (ಕಡ್ಡಾಯ)", "ಪೂರಕ ಜಾಮೀನು ಪತ್ರ (ಕಡ್ಡಾಯ)"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('2e0eefc3-d7ac-4f24-acad-395fb8c61c06', 'BACKWARD-CLASSES-WEL-50', '59d7c155-e129-436a-b747-c5cb6abba051', 'Arivu Educational Loan Scheme (Renewal)', 'Loan', 0, 'Students belonging to Backward Classes, admitted through Common Entrance Test (CET) will be given a loan of Rs.1.00 lakhs per annum for academic development up to a maximum of Rs.4.00 to Rs.5.00 lakhs for the duration of the course at an interest rate of 2% per annum.', '["Study Certificate (Mandatory)", "Fee Receipt (Mandatory)", "Study Certificate (Mandatory)", "Upload Claim Letter including Sanction Order (Mandatory)", "Previous Year Marksheet (Mandatory)", "Parent Approval Letter (Mandatory)", "Collateral Letter (Mandatory)"]', '["Applicant must belong to Alemari /arey alemari caste and sub caste must produce a caste certificate obtained from the competent authority.", "Must have secured admission to a degree or postgraduate degree course through a common entrance examination (CET / NEET etc.).", "The candidate''s family annual income must be within Rs. 3.50 lakhs."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the Chief Executive Officer of the Zilla Panchayat."]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '3e2c95ab-7236-462d-95bc-42da1aaef8ac', 'ಅರಿವು ಶೈಕ್ಷಣಿಕ ಸಾಲ ಯೋಜನೆ (ನವೀಕರಣ)', 'Arivu Renewal Loan', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಸಾಮಾನ್ಯ ಪ್ರವೇಶ ಪರೀಕ್ಷೆ ಮೂಲಕ(ಸಿ.ಇ.ಟಿ.) ಪ್ರವೇಶ ಪಡೆದ ಹಿಂದುಳಿದ ವರ್ಗಗಳ ಸೇರಿದ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ಶೈಕ್ಷಣಿಕಾಭಿವೃದ್ಧಿಗಾಗಿ ಅರಿವು ಶೈಕ್ಷಣಿಕ ಸಾಲ ನವೀಕರಣ ಯೋಜನೆಯಡಿ ವಾರ್ಷಿಕ ರೂ.1.00ಲಕ್ಷಗಳಂತೆ ಕೋರ್ಸ್ ಅವಧಿಗೆ ಗರಿಷ್ಠ ರೂ.4.00 ರಿಂದ ರೂ.5.00 ಲಕ್ಷಗಳ ವರೆಗೆ ವಾರ್ಷಿಕ ಶೇ.2 ಬಡ್ಡಿದರದಲ್ಲಿ ಸಾಲ ನೀಡಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಅರ್ಜಿದಾರರು ಅಲೆಮಾರಿ ಹಾಗೂ ಅರೆ ಅಲೆಮಾರಿ ಜಾತಿಗೆ ಸೇರಿದವರಾಗಿರಬೇಕು ಮತ್ತು ಸಮರ್ಥ ಪ್ರಾಧಿಕಾರದಿಂದ ಪಡೆದ ಜಾತಿ ಪ್ರಮಾಣಪತ್ರವನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಸಾಮಾನ್ಯ ಪ್ರವೇಶ ಪರೀಕ್ಷೆ ಮೂಲಕ (ಸಿ.ಇ.ಟಿ. / ನೀಟ್ / ಇತ್ಯಾದಿ) ಪದವಿ / ಸ್ನಾತಕೋತ್ತರ ಪದವಿ ಕೋರ್ಸ್"]', '["ಜಿಲ್ಲಾ ಪಂಚಾಯತ್"]', 1, '["Study Certificate (ಕಡ್ಡಾಯ)", "ಶುಲ್ಕ ರಶೀದಿ (ಕಡ್ಡಾಯ)", "ಅಧ್ಯಯನ ಪ್ರಮಾಣಪತ್ರ (ಕಡ್ಡಾಯ)", "ಮಂಜೂರಾತಿ ಆದೇಶ ಸೇರಿದಂತೆ ಹಕ್ಕು ಪತ್ರವನ್ನುಅಪ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('4b1f59c5-74db-4567-a865-28290c7e0cc5', 'ENERGY-DEPARTMENT-21', 'e0b8deb9-4426-4525-a8e5-aab3f707df7c', 'Application for additional load / New connection- Supply of electricity which requires extension of distribution mains, or commissioning of new substations', 'General', 0, '', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '665dc58e-475b-4883-93a4-8761c3bf0063', 'ಹೊಸ ಸಂಪರ್ಕ ಹೆಚ್ಚುವರಿ ಲೋಡ್', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '2999');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('0666eede-a36b-4c41-a121-a3d5439d3da1', 'ENERGY-DEPARTMENT-23', 'e0b8deb9-4426-4525-a8e5-aab3f707df7c', 'Transfer of Ownership and Conversion- Change of category', 'General', 0, '', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '665dc58e-475b-4883-93a4-8761c3bf0063', 'ಮಾಲೀಕತ್ವದ ವರ್ಗಾವಣೆ ಮತ್ತು ಬದಲಾವಣೆ - ಪ್ರವರ್ಗದ ಬದಲಾವಣೆ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3007');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('a22bd119-a02c-4f7c-8f2f-e81b7e93c090', 'SOCIAL-WELFARE-DEPAR-48', '81b60538-519f-4131-bd38-c390f2d882d6', 'Dr. Babu Jagjeevan Ram Two Wheeler Cargo Transport Scheme', 'General', 0, '', '["In 2022-23, a scheme will be implemented to promote self-employment and increase self-confidence among Scheduled Castes and Scheduled Tribes youth. This scheme is designed to facilitate e-commerce businesses and create employment in other services. Under this scheme, beneficiaries who purchase electric or other two-wheeler/three-wheeler goods transport vehicles will receive a subsidy of Rs. 50,000 and a loan of Rs. 20,000."]', '["Online"]', '[]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Applicant Age should be between 21 to 60 years.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '6c2e1b24-4f87-468c-8a58-46665d8b9c7b', 'ಡಾ. ಬಾಬು ಜಗಜೀವನ ರಾಂ ದ್ವಿಚಕ್ರ ವಾಹನ ಸರಕು ಸಾಗಾಣಿಕೆ ಯೋಜನೆ', 'Dr. Babu Jagjeevan Ram Two Wheeler Cargo Transport Scheme', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ದ್ವಿಚಕ್ರ ವಾಹನ ಸರಕು ಸಾಗಾಣಿಕೆ ಯೋಜನೆ', '["ಆನ್"]', '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 60 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', 1, '["2022-23 ನೇ ಸಾಲಿನಲ್ಲಿ ಪರಿಶಿಷ್ಟ ಜಾತಿ ಮತ್ತು ವರಿಶಿಷ್ಟ ಪಂಗಡದ ಯುವಕರಲ್ಲಿ ಸ್ವಯಂ ಉದ್ಯೋಗವನ್ನು ಉತ್ತೇಜಿಸಲು ಮತ್ತು ಆತ್ಮವಿಶ್ವಾಸವನ್ನು ಹೆಚ್ಚಿಸಲು , ಇ-ಕಾಮರ್ಸ್ ವ್ಯವಹಾರಗಳನ್ನು ಸುಲಭಗೊಳಿಸಲು ಮತ್ತು ಇತರ ಸೇವೆಗಳಲ್ಲಿ ಉದ್ಯೋಗವನ್ನು ಸೃಷ್ಟಿಸಲು ಈ ಯೋಜನೆಯನ್ನು ವಿನ್ಯಾಸಗೊಳಿಸಲಾಗಿದೆ. ಈ ಯೋಜನೆಯಡಿಯಲ್ಲಿ, ವಿದ್ಯುತ್ ಅಥವಾ ಇತರೆ ಎರಡು/ಮೂರು ಚಕ್ರದ ಸರಕು ಸಾಗಣೆ ವಾಹನಗಳನ್ನು ಖರೀದಿಸುವ ಫಲಾನುಭವಿಗಳಿಗೆ ರೂ. 50,000 ಸಹಾಯಧನ ಹಾಗೂ ರೂ. 20,000 ಸಾಲವನ್ನು ನೀಡಲಾಗುತ್ತದೆ."]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('3eab8ab0-30ce-4b6c-a64c-1e22027dfe12', 'SOCIAL-WELFARE-DEPAR-47', '81b60538-519f-4131-bd38-c390f2d882d6', 'Swavalambi Sarathi Scheme', 'General', 0, '', '["Under Swalambi Sarathi Yojana, the scheme will be implemented in collaboration with banks by sanctioning 75% subsidy or maximum Rs.4.00 lakhs for goods transport/taxi (yellow board) vehicles."]', '["Online"]', '[]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 56 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '6c2e1b24-4f87-468c-8a58-46665d8b9c7b', 'ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ ಯೋಜನೆ', 'Swavalambi Sarathi Scheme', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ/ISB 3.5', '["ಆನ್"]', '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 56 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು."]', 1, '["ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ ಯೋಜನೆಯಡಿ ಸರಕು ಸಾಗಾಣಿಕೆ/ಟ್ಯಾಕ್ಸಿ (ಹಳದಿ ಬೋರ್ಡ್) ವಾಹನಗಳಿಗೆ ಘಟಕ ವೆಚ್ಚದ ಶೇ.75ರಷ್ಟು ಅಥವಾ ಗರಿಷ್ಟ ರೂ.4.00 ಲಕ್ಷಗಳವರೆಗೆ ಸಹಾಯಧನವನ್ನು ಮಂಜೂರು ಮಾಡಿ ಬ್ಯಾಂಕ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('1dbaa25e-6617-4a4a-90ee-d538fa8ad8f2', 'SOCIAL-WELFARE-DEPAR-46', '81b60538-519f-4131-bd38-c390f2d882d6', 'Micro Credit Prerana Scheme 5 Lakh', 'General', 0, '', '["Loans and grants will be extended to support various economic activities undertaken by Self-Help Groups of Scheduled Caste women. Each female member will receive Rs. 25,000, comprising a subsidy of Rs. 15,000 and a loan of Rs. 10,000. Self-help groups with a minimum of 10 women members and a unit cost of Rs. 2.50 lakhs will be eligible for loan assistance as per regulations. The loan must be repaid to the Corporation in 36 equal installments with a 4% interest rate"]', '["Online"]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '6c2e1b24-4f87-468c-8a58-46665d8b9c7b', 'ಪ್ರೇರಣಾ (ಮೈಕ್ರೋ ಕ್ರೆಡಿಟ್) ಯೋಜನೆ 5 ಲಕ್ಷ', 'Micro Credit Prerana Scheme 5 Lakh', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಪ್ರೇರಣಾ (ಮೈಕ್ರೋ ಕ್ರೆಡಿಟ್)', '["ಆನ್"]', '[]', 1, '["ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯದ ಮಹಿಳಾ ಸ್ವಸಹಾಯ ಸಂಘಗಳ ವಿವಿಧ ಉದ್ದೇಶದ ಆರ್ಥಿಕ ಚಟುವಟಿಕೆಗಳಿಗೆ ಸಾಲ ಮತ್ತು ಸಹಾಯಧನ ನೀಡಲಾಗುವುದು. ಪ್ರತಿ ಮಹಿಳಾ ಸದಸ್ಯರಿಗೆ ರೂ 25000. ಇದರಲ್ಲಿ ಸಹಾಯಧನ ರೂ15000 ಹಾಗೂ ಸಾಲ ರೂ10000 ಗಳಾಗಿರುತ್ತದೆ. ಕನಿಷ್ಠ 10 ಜನ ಮಹಿಳಾ ಸದಸ್ಯರು ಇರುವ ಸ್ವ-ಸಹಾಯ ಗುಂಪಿಗೆ ಘಟಕ ವೆಚ್ಛ ರೂ 2.50 ಲಕ್ಷಗಳಂತೆ ನಿಯಮಾನುಸಾರ ಅರ್ಹರಿರುವ ಗುಂಪಿಗೆ ಸಾಲ ಸೌಲಭ್ಯ ಒದಗಿಸಲಾಗುವುದು. ಸದರಿ ಸಾಲದ ಹಣವನ್ನು 36 ಸಮ ಕಂತುಗಳಲ್ಲಿ ಶೇ 4 ರ ಬಡ್ಡಿ ದರದಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಮರುಪಾವತಿ ಮಾಡ ಬೇಕಾಗಿರುತ್ತದೆ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('0d85ea31-aafc-4631-a54d-678bcd108f85', 'SOCIAL-WELFARE-DEPAR-45', '81b60538-519f-4131-bd38-c390f2d882d6', 'Micro Credit Prerana Scheme', 'General', 0, '', '["Loans and grants will be extended to support various economic activities undertaken by Self-Help Groups of Scheduled Caste women. Each female member will receive Rs. 25,000, comprising a subsidy of Rs. 15,000 and a loan of Rs. 10,000. Self-help groups with a minimum of 10 women members and a unit cost of Rs. 2.50 lakhs will be eligible for loan assistance as per regulations. The loan must be repaid to the Corporation in 36 equal installments with a 4% interest rate"]', '["Online"]', '[]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 60 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability.", "Registered Copy of Self Help Group.", "Out of the 60% Scheduled Caste members of the association, 40% of the members should belong to the sub-castes belonging to the corporation.", "Members of the SHG should have ration card."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '6c2e1b24-4f87-468c-8a58-46665d8b9c7b', 'ಪ್ರೇರಣಾ (ಮೈಕ್ರೋ ಕ್ರೆಡಿಟ್) ಯೋಜನೆ', 'Micro Credit Prerana Scheme', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಪ್ರೇರಣಾ (ಮೈಕ್ರೋ ಕ್ರೆಡಿಟ್)', '["ಆನ್"]', '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 60 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು.", "ಚಾಲ್ತಿಯಲ್ಲಿರುವ ಸಂಘದ ನೊಂದಣಿ ಪತ್ರ.", "ಸಂಘದ ಶೇ 60 ರ ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸದಸ್ಯರುಗಳ ಪೈಕಿ ಶೇ 40 ರಷ್ಟು ಸದಸ್ಯರು ನಿಗಮಕ್ಕೆ ಸೇರಿದ ಉಪ ಜಾತಿಯವರಾಗಿರಬೇಕು.", "ಸಂಘದ ಸದಸ್ಯರು ಪಡಿತರ ಚೀಟಿಯನ್ನು ಹೊಂದಿರಬೇಕು."]', 1, '["ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯದ ಮಹಿಳಾ ಸ್ವಸಹಾಯ ಸಂಘಗಳ ವಿವಿಧ ಉದ್ದೇಶದ ಆರ್ಥಿಕ ಚಟುವಟಿಕೆಗಳಿಗೆ ಸಾಲ ಮತ್ತು ಸಹಾಯಧನ ನೀಡಲಾಗುವುದು. ಪ್ರತಿ ಮಹಿಳಾ ಸದಸ್ಯರಿಗೆ ರೂ.25000. ಇದರಲ್ಲಿ ಸಹಾಯಧನ ರೂ.15000 ಹಾಗೂ ಸಾಲ ರೂ.10000 ಗಳಾಗಿರುತ್ತದೆ. ಕನಿಷ್ಠ 10 ಜನ ಮಹಿಳಾ ಸದಸ್ಯರು ಇರುವ ಸ್ವ-ಸಹಾಯ ಗುಂಪಿಗೆ ಘಟಕ ವೆಚ್ಛ ರೂ. 2.50 ಲಕ್ಷಗಳಂತೆ ನಿಯಮಾನುಸಾರ ಅರ್ಹರಿರುವ ಗುಂಪಿಗೆ ಸಾಲ ಸೌಲಭ್ಯ ಒದಗಿಸಲಾಗುವುದು. ಸದರಿ ಸಾಲದ ಹಣವನ್ನು 36 ಸಮ ಕಂತುಗಳಲ್ಲಿ ಶೇ 4 ರ ಬಡ್ಡಿ ದರದಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಮರುಪಾವತಿ ಮಾಡಬೇಕಾಗಿರುತ್ತದೆ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('a7a0ac5b-522f-40eb-a7e0-66fab9befa08', 'SOCIAL-WELFARE-DEPAR-44', '81b60538-519f-4131-bd38-c390f2d882d6', 'Self Employment Direct Loan Scheme', 'General', 0, '', '["Scheduled caste individuals can engage in small-scale economic activities such as selling fruits, vegetables, fish, and rearing livestock like cows, sheep, pigs, or rabbits. The unit cost for these endeavors is Rs.1.00 lakh, with financial support comprising a Rs.50,000 subsidy and a Rs.50,000 loan. Beneficiaries are required to repay the loan to the corporation in 36 equal installments, with an interest rate of 4%."]', '["Online"]', '[]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 60 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '6c2e1b24-4f87-468c-8a58-46665d8b9c7b', 'ಸ್ವಯಂ ಉದ್ಯೋಗ (ನೇರಸಾಲ) ಯೋಜನೆ', 'Self Employment Direct Loan Scheme', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಸ್ವಯಂ ಉದ್ಯೋಗ ಯೋಜನೆ', '["ಆನ್"]', '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 60 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', 1, '["ಪರಿಶಿಷ್ಟ ಜಾತಿ ನಿರುದ್ಯೋಗಿಗಳಿಗೆ ಹಣ್ಣು,, ತರಕಾರಿ, ಮೀನು, ಮಾಂಸ ಮಾರಾಟ, ಹಸು/ಕುರಿ/ಹಂದಿ/ಮೊಲ ಸಾಕಾಣಿಕೆ ಇತ್ಯಾದಿ ಕಿರು ಆರ್ಥಿಕ ಚಟುವಟಿಕೆಗಳಿಗೆ ಘಟಕ ವೆಚ್ಚ ರೂ.1.00ಲಕ್ಷಗಳಾಗಿದ್ದು, ಈ ಪೈಕಿ ರೂ.50,000/- ಸಹಾಯಧನ ಹಾಗೂ ರೂ.50,000/- ಸಾಲದ ರೂಪದಲ್ಲಿ ಆರ್ಥಿಕ ನೆರವನ್ನು ಕಲ್ಪಿಸಲಾಗುತ್ತಿದೆ. ಸಾಲದ ಮೊತ್ತವನ್ನು 36 ಸಮಾನ ಕಂತುಗಳಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಶೇ.4ರ ಬಡ್ಡಿದರದೊಂದಿಗೆ ಮರುಪಾವತಿಸಬೇಕಾಗಿರುತ್ತದೆ."]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('b189658a-6f63-4d1b-9ace-0236233de80c', 'SOCIAL-WELFARE-DEPAR-43', '81b60538-519f-4131-bd38-c390f2d882d6', 'ISB - Fast Food Truck Trailer/Mobile Food Kitchen - Rs. 4.00 Lakhs', 'General', 0, '', '["Under the ISB (Industrial Service Business) scheme, this fully subsidized Fast Food Truck Trailer/Mobile Kitchen is a mobile food service unit worth ₹4.00 lakhs."]', '["Online"]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '6c2e1b24-4f87-468c-8a58-46665d8b9c7b', 'ಐಎಸ್ಬಿ - ಫಾಸ್ಟ್ ಫುಡ್ ಟ್ರಕ್ ಟ್ರೇಲರ್/ಮೊಬೈಲ್ ಫುಡ್ ಕಿಚನ್ - ₹4.00 ಲಕ್ಷಗಳು', 'ISB - Fast Food Truck Trailer/Mobile Food Kitchen - Rs. 4.00 Lakhs', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಐಎಸ್ಬಿ - ಫಾಸ್ಟ್ ಫುಡ್ ಟ್ರಕ್ ಟ್ರೇಲರ್/ಮೊಬೈಲ್ ಫುಡ್ ಕಿಚನ್ - ₹4 ಲಕ್ಷಗಳು', '["ಆನ್"]', '[]', 1, '["ಐಎಸ್ಬಿ (ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ) ಯೋಜನೆಯ ಅಡಿಯಲ್ಲಿ ಸಂಪೂರ್ಣ ಸಹಾಯಧನದೊಂದಿಗೆ ನೀಡಲಾಗುವ ಈ ಫಾಸ್ಟ್ ಫುಡ್ ಟ್ರಕ್ ಟ್ರೇಲರ್/ಮೊಬೈಲ್ ಕಿಚನ್ ₹4.00 ಲಕ್ಷ ಮೌಲ್ಯದ ಚಲಿಸುವ ಆಹಾರ ಸೇವಾ ಘಟಕವಾಗಿದೆ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('b38bfadf-473b-41e6-b80b-72a0aa56a2bc', 'SOCIAL-WELFARE-DEPAR-42', '81b60538-519f-4131-bd38-c390f2d882d6', 'Land Purchase scheme', 'General', 0, '', '["Under the Land-Ownership Scheme, land will be purchased from non-Scheduled Caste/Scheduled Tribe landowners. Landless women agricultural labourers belonging to the Scheduled Caste community will receive Rs. 20 lakh for 27 districts and Rs. 25 lakh for 4 districts (Bangalore City, Bangalore Rural, Chikkaballapur, and Ramanagara), with 50% subsidy and 50% loan. Khushki/Tari/Bagaitu land within a maximum distance of 10 km from the beneficiary''s residence will be provided. The loan must be repaid to the Corporation in 10 annual equal installments at an interest rate of 6% per annum."]', '["Online"]', '[]', '["Applicants must belong to scheduled castes and its related community.", "The applicant must be a land less agriculture labour family.", "Self-declaration certificate must be submitted in case of caste certificate.", "Should be resident of Karnataka state.", "The applicant and no member of his family should not be in employment in any Govt./Semi Govt organization.", "The beneficiaries eligible to avail of facilities under the land ownership scheme must be landless women agricultural laborers.", "Additionally, the landowners selling the land should not belong to Scheduled Castes and Scheduled Tribes.", "The land to be purchased is a maximum of 10 km from the place where the beneficiary lives. m. should be within range."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '6c2e1b24-4f87-468c-8a58-46665d8b9c7b', 'ಭೂ-ಒಡೆತನ ಯೋಜನೆ', 'Land Purchase scheme', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಭೂ-ಒಡೆತನ ಯೋಜನೆ', '["ಆನ್"]', '["ಅರ್ಜಿದಾರರು ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸಂಬಂಧಿತ ಜಾತಿಗಳಿಗೆ ಸೇರಿದವರಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಭೂ ರಹಿತ ಕೃಷಿ ಕಾರ್ಮಿಕ ಕುಟುಂಬದವರಾಗಿರಬೇಕು.", "ಜಾತಿ ಪ್ರಮಾಣ ಪತ್ರವನ್ನು ಸಲ್ಲಿಸಿದಲ್ಲಿ ಕಡ್ಡಾಯವಾಗಿ ಸ್ವಯಂ ಘೋಷಣೆ ಪ್ರಮಾಣ ಪತ್ರವನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು/ ಕುಟುಂಬದ ಅವಲಂಬಿತ ಯಾವುದೇ ಸದಸ್ಯರು ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ನೌಕರಿಯಲ್ಲಿರಬಾರದು.", "ಭೂಒಡೆತನ ಯೋಜನೆಯಡಿ ಸೌಲಭ್ಯ ಪಡೆಯಲು ಫಲಾಪೇಕ್ಷಿಯು ಭೂರಹಿತ ಮಹಿಳಾ ಕೃಷಿ ಕಾರ್ಮಿಕರಾಗಿರಬೇಕು.", "ಜಮೀನು ಮಾರಾಟ ಮಾಡುವ ಭೂಮಾಲೀಕರು ಪರಿಶಿಷ್ಟಜಾತಿ ಮತ್ತು ಪರಿಶಿಷ್ಟ ಪಂಗಡಕ್ಕೆ ಸೇರಿರಬಾರದು.", "ಖರೀದಿಸುವ ಜಮೀನು ಫಲಾನುಭವಿಯು ವಾಸಿಸುತ್ತಿರುವ ಸ್ಥಳದಿಂದ ಗರಿಷ್ಠ 10 ಕಿ. ಮೀ. ವ್ಯಾಪ್ತಿಯೊಳಗೆ ಇರಬೇಕು."]', 1, '["ಭೂ -ಒಡೆತನ ಯೋಜನೆಯಡಿ ಪರಿಶಿಷ್ಟ ಜಾತಿ / ಪರಿಶಿಷ್ಟ ಪಂಗಡಕ್ಕೆ ಸೇರದ ಭೂ ಮಾಲೀಕರಿಂದ ಜಮೀನನ್ನು ಖರೀದಿಸಿ, ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸಮುದಾಯದ ಭೂ ರಹಿತ ಮಹಿಳಾ ಕೃಷಿ ಕಾರ್ಮಿಕರಿಗೆ 27 ಜಿಲ್ಲೆಗಳಿಗೆ ರೂ 20 ಲಕ್ಷ ಮತ್ತು 4 ಜಿಲ್ಲೆಗಳಿಗೆ (ಬೆಂಗಳೂರು ನಗರ, ಬೆಂಗಳೂರು ಗ್ರಾಮಾಂತರ, ಚಿಕ್ಕಬಳ್ಳಾಪುರ ಮತ್ತು ರಾಮನಗರ) ರೂ 25 ಲಕ್ಷಗಳಿಗೆ (ಸಹಾಯಧನ ಶೇ 50 ಮತ್ತು ಸಾಲ ಶೇ 50 ರಷ್ಟು) ಖುಷ್ಕಿ/ತರಿ/ಬಾಗಾಯ್ತು ಜಮೀನನ್ನು ಫಲಾನುಭವಿಯು ವಾಸಿಸುತ್ತಿರುವ ಸ್ಥಳದಿಂದ ಗರಿಷ್ಠ 10 ಕಿ. ಮೀ. ವ್ಯಾಪ್ತಿಯೊಳಗೆ ಖರೀದಿಸಿ, ಭೂರಹಿತ ಮಹಿಳಾ ಕೃಷಿ ಕಾರ್ಮಿಕರಿಗೆ ಒದಗಿಸಲಾಗುವುದು ಮತ್ತು ಸಾಲದ ಮೊತ್ತವನ್ನು 10 ವಾರ್ಷಿಕ ಸಮ ಕಂತುಗಳಲ್ಲಿ ವಾರ್ಷಿಕ ಶೇ 6 ರ ಬಡ್ಡಿ ದರದಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಮರುಪಾವತಿ ಮಾಡ ಬೇಕಾಗಿರುತ್ತದೆ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('5eab020a-7776-41fb-af56-b6228dc679a9', 'SOCIAL-WELFARE-DEPAR-41', '81b60538-519f-4131-bd38-c390f2d882d6', 'Sheep/Goat Farming Scheme', 'General', 0, '', '["Under the Sheep Farming Scheme, beneficiaries receive a loan of ₹50,000 along with a subsidy of ₹50,000 to support sustainable sheep rearing and income generation"]', '["Online"]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '6c2e1b24-4f87-468c-8a58-46665d8b9c7b', 'ಕುರಿ/ಮೇಖೆ ಸಾಕಾಣಿಕೆ ಯೋಜನೆ', 'Sheep/Goat Farming Scheme', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಕುರಿ/ಮೇಖೆ ಸಾಕಾಣಿಕೆ ಯೋಜನೆ', '["ಆನ್"]', '[]', 1, '["ಈ ಯೋಜನೆಯ ಅಡಿಯಲ್ಲಿ ಫಲಾನುಭವಿಗಳಿಗೆ ₹50,000 ರ ঋಣ ಮತ್ತು ₹50,000 ರ ಸಹಾಯಧನವನ್ನು ಒದಗಿಸಲಾಗುತ್ತದೆ, ಇದು ಸ್ಥಿರ ಕುರಿ ಸಾಕಾಣಿಕೆ ಮತ್ತು ಆದಾಯ ಉತ್ಪಾದನೆಗೆ ನೆರವಾಗುತ್ತದೆ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('dfb6120e-034e-43c5-830f-8ddaf9912812', 'SOCIAL-WELFARE-DEPAR-40', '81b60538-519f-4131-bd38-c390f2d882d6', 'Industrial Service Business - ISB (in association with Bank) Maximum Rs. 2 lakh subsidy', 'General', 0, '', '["Industrial Service Business (in collaboration with the Bank) development scheme, assistance from the Corporation to start self-employment units for unemployed youths and women of the Scheduled Caste community in small scale industry, service sector and business sectors and the rest is loan from the bank. Subsidy of 70% of the unit cost or a maximum of Rs 2 lakh"]', '["Online"]', '[]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 56 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '6c2e1b24-4f87-468c-8a58-46665d8b9c7b', 'ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್', 'Industrial Service Business - ISB (in association with Bank) Maximum Rs. 2 lakh subsidy', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಉದ್ಯಮ ಶೀಲತಾ ಯೋಜನೆ 2.0', '["ಆನ್"]', '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 56 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', 1, '["ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('106df267-5b90-442f-a5ee-50c49ff07f65', 'ENERGY-DEPARTMENT-26', 'e0b8deb9-4426-4525-a8e5-aab3f707df7c', 'Application for new connection under EoDB where RoW permission and extension of Electrical infrastructure is required (Single Installations only)', 'General', 0, '', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '665dc58e-475b-4883-93a4-8761c3bf0063', 'EoDB ಅಡಿಯಲ್ಲಿ ಹೊಸ ವಿದ್ಯುತ್', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3014');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('84c427d1-ccb2-4e4a-9b67-0024bbc7530e', 'REVENUE-DEPARTMENT-60', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'A DAFTAR REVISION PRATHI', 'General', 0, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (A DAFTAR REVISION PRATHI)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಎ ದಪ್ತರ್ ರಿವಿಜನ್ ಪ್ರತಿ', NULL, NULL, NULL, NULL, NULL, 35.00, NULL, 'ಎ ದಪ್ತರ್ ರಿವಿಜನ್ ಪ್ರತಿ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3064');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('3a867b50-534d-48ca-beea-a03d42cf77c2', 'SOCIAL-WELFARE-DEPAR-39', '81b60538-519f-4131-bd38-c390f2d882d6', 'Industrial Service Business - ISB (in association with Bank) Maximum Rs. 1 lakh subsidy', 'General', 0, '', '["Industrial Service Busines (in collaboration with the Bank) development scheme, assistance from the Corporation to start self-employment units for unemployed youths and women of the Scheduled Caste community in small scale industry, service sector and business sectors and the rest is loan from the bank. Subsidy of 20% of the unit cost or a maximum of Rs 1 lakh"]', '["Online"]', '[]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 56 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '6c2e1b24-4f87-468c-8a58-46665d8b9c7b', 'ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್', 'Industrial Service Business - ISB (in association with Bank) Maximum Rs. 1 lakh subsidy', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಉದ್ಯಮ ಶೀಲತಾ ಯೋಜನೆ 1.0', '["ಆನ್"]', '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 56 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', 1, '["ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('14e7897b-f801-48b1-9b95-68c31adaa2a2', 'SOCIAL-WELFARE-DEPAR-38', '81b60538-519f-4131-bd38-c390f2d882d6', 'Ganga Kalyana', 'General', 0, '', '["Under this scheme, irrigation facilities are provided to small and very small scheduled caste farmers with 1½ to 5.00 acres of land by drilling boreholes, installing pump sets, and electrifying them. In certain districts such as Kolar, Chikkaballapur, Bangalore (Rural), Bangalore (City), Tumkur, and Ramnagar, the unit cost has been increased to Rs.4.75 lakh due to declining groundwater levels. Of this amount, Rs.4.25 lakh will be subsidized, and the remaining Rs.50,000/- will be provided as a term loan.In other districts, the unit cost is fixed at Rs.3.75 lakh, with Rs.3.25 lakh provided as a subsidy and Rs.50,000/- lakh as a term loan. Additionally, out of the unit cost, Rs.75,000 per borehole will be allocated to the respective Escom for electrification, within the subsidy limit of the unit cost."]', '["Online"]', '[]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicants must be at least 21 years old and there is no upper age limit.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability.", "The applicants must be small and medium marginal farmers and should not have access to irrigation facilities."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '6c2e1b24-4f87-468c-8a58-46665d8b9c7b', 'ಗಂಗಾ ಕಲ್ಯಾಣ ಯೋಜನೆ', 'Ganga Kalyana', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಗಂಗಾ ಕಲ್ಯಾಣ ಯೋಜನೆ', '["ಆನ್"]', '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಕನಿಷ್ಠ 21 ವರ್ಷಗಳು ಪೂರ್ಣಗೊಂಡಿರಬೇಕು ಗರಿಷ್ಠ ವಯೋಮಿತಿ ತೆಗೆದು ಹಾಕಲಾಗಿದೆ.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು.", "ಅರ್ಜಿದಾರರು ಸಣ್ಣ ಮತ್ತು ಅತಿ ಸಣ್ಣ ರೈತರಾಗಿರಬೇಕು ಹಾಗೂ ನೀರಾವರಿ ಸೌಲಭ್ಯ ಹೊಂದಿರಬಾರದು."]', 1, '["ಈ ಯೋಜನೆಯಡಿ 1½ ಎಕರೆಯಿಂದ 5.00 ಎಕರೆ ಜಮೀನು ಹೊಂದಿರುವ ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸಣ್ಣ ಮತ್ತು ಅತೀ ಸಣ್ಣ ರೈತರ ಜಮೀನಿನಲ್ಲಿ ಕೊಳವೆಬಾವಿ ಕೊರೆಸಿ, ಪಂಪ್ ಸೆಟ್ ಅಳವಡಿಸಿ ವಿದ್ಯುದ್ಧೀಕರಣಗೊಳಿಸಿ ನೀರಾವರಿ ಸೌಲಭ್ಯ ಕಲ್ಪಿಸಲಾಗುತ್ತಿದೆ. ಈ ಯೋಜನೆಯಡಿ ಕೋಲಾರ, ಚಿಕ್ಕಬಳ್ಳಾಪುರ, ಬೆಂಗಳೂರು(ಗ್ರಾ), ಬೆಂಗಳೂರು(ನಗರ), ತುಮಕೂರು ಮತ್ತು ರಾಮನಗರ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಅಂತರ್ಜಲ ಮಟ್ಟ ಕೆಳಗೆ ಕುಸಿದಿರುವುದರಿಂದ ಈ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಘಟಕ ವೆಚ್ಚ ರೂ.4.75 ಲಕ್ಷಕ್ಕೆ ಹೆಚ್ಚಿಸಲಾಗಿದ್ದು, ಇದರಲ್ಲಿ ರೂ.4.25 ಲಕ್ಷ ಸಹಾಯಧನವಿದ್ದು, ಉಳಿದ ರೂ.50,000/- ಅವಧಿಸಾಲವಾಗಿರುತ್ತದೆ. ಇತರೆ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಘಟಕ ವೆಚ್ಚ ರೂ.3.75 ಲಕ್ಷ ನಿಗದಿಪಡಿಸಿದ್ದು, ಇದರಲ್ಲಿ ರೂ.3.25 ಲಕ್ಷ ಸಹಾಯಧನ ಮತ್ತು ರೂ.50,000/- ಅವಧಿಸಾಲವಾಗಿರುತ್ತದೆ. ಘಟಕ ವೆಚ್ಚದ ಪೈಕಿ ವಿದ್ಯುದ್ದೀಕರಣಕ್ಕೆ ಘಟಕ ವೆಚ್ಚದ ಸಹಾಯಧನದ ಮಿತಿಯಲ್ಲಿ ಪ್ರತಿ ಕೊಳವೆಬಾವಿಗೆ ರೂ.75,000/-ಗಳನ್ನು ಸಂಬಂಧಿಸಿದ ಎಸ್ಕಾಂಗಳಿಗೆ ಬಿಡುಗಡೆ ಮಾಡಲಾಗುವುದು."]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('193fd003-f9e4-46eb-9314-01d4a366cbd2', 'SOCIAL-WELFARE-DEPAR-37', '81b60538-519f-4131-bd38-c390f2d882d6', 'Dairy Farming Scheme', 'General', 0, '', '["Under the Dairy Farming Scheme, beneficiaries are provided a subsidy of ₹1.25 lakhs to support the establishment and development of dairy farming for sustainable livelihood and milk production"]', '["Online"]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '6c2e1b24-4f87-468c-8a58-46665d8b9c7b', 'ಹೈನುಗಾರಿಕೆ ಯೋಜನೆ', 'Dairy Farming Scheme', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಹೈನುಗಾರಿಕೆ ಯೋಜನೆ', '["ಆನ್"]', '[]', 1, '["ಈ ಯೋಜನೆಯ ಅಡಿಯಲ್ಲಿ ಫಲಾನುಭವಿಗಳಿಗೆ ಹೈನುಗಾರಿಕೆಯನ್ನು ಸ್ಥಾಪಿಸಲು ಮತ್ತು ಅಭಿವೃದ್ಧಿಪಡಿಸಲು ₹1.25 ಲಕ್ಷಗಳ ಸಹಾಯಧನವನ್ನು ನೀಡಲಾಗುತ್ತದೆ, ಇದು ಸ್ಥಿರ ಜೀವನೋಪಾಯ ಮತ್ತು ಹಾಲು ಉತ್ಪಾದನೆಗೆ ನೆರವಾಗುತ್ತದೆ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('154b3b37-2cc8-487b-87e9-77d4a6564138', 'BACKWARD-CLASSES-WEL-32', '59d7c155-e129-436a-b747-c5cb6abba051', 'Self-Employment Loan Scheme (Commercial Bank)', 'General', 0, '', '[]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '3e791161-f615-4934-979e-626057e986b7', 'ಸ್ವಯಂ ಉದ್ಯೋಗ ಸಾಲ (ಬ್ಯಾಂಕುಗಳ ಸಹಯೋಗದೊಂದಿಗೆ)', 'Corporation assisted to Vokkaliga communities whose annual family income is Rs.1,20,000/- for urban areas and Rs.98,000/- for rural areas and in the age group of 18 to 55 for self-employment, taking agricultural / non-agricultural activities, trade, transport and purchase of machinery economic activities. Corporation will grant subsidy of 20% up to a maximum of Rs.1.00 lakhs in case of obtaining loan through commercial banks.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('bfd2a011-56a0-4ac6-b673-1f5c58d9819a', 'BACKWARD-CLASSES-WEL-31', '59d7c155-e129-436a-b747-c5cb6abba051', 'Loan Scheme for Higher Education in Foreign Universities:', 'Education loan', 0, '', '["Pasport Size Photo", "Study Certificate", "Passport", "Visa", "Fee Structure", "aadhaar card,ration card, caste and income certificate", "Collateral Letter", "Parent Approval Letter", "Admission Confirmation Intimation Letter Provided by the Foreign University", "document_icon", "Aadhar linked PassBook Front Page Photo"]', '["The annual income limit for the student''s family is Rs. 15.00 lakhs. Regarding the age limit, a maximum age of 32 years has been fixed for postgraduates and 35 years for Ph.D. holders. As collateral security for the loan, immovable property owned by the student''s father or a guarantor must be pledged to the Corporation. The student must have passed the qualifying examination in the First Class."]', '[]', '["Beneficiaries were selected through a selection committee chaired by the Managing Director"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '3e791161-f615-4934-979e-626057e986b7', 'ವಿದೇಶಿ ವಿಶ್ವವಿದ್ಯಾಲಯಗಳಲ್ಲಿ ಉನ್ನತ ಶಿಕ್ಷಣ ವ್ಯಾಸಂಗಕ್ಕೆ ಸಾಲ', 'To provide loan facility up to Rs.25.00 lakhs per annum maximum of Rs.50.00 lakhs for a period of 2 years at without interest to the students of Vokkaliga community who are admitted to Master Degree, PhD, Post Doctoral courses for higher education in foreign universities With QS / THE World Ranking below 1000.', NULL, NULL, NULL, NULL, NULL, 30.00, NULL, NULL, NULL, NULL, false, 'No', '["ವಿದ್ಯಾರ್ಥಿಯಕುಟುಂಬದವಾರ್ಷಿಕಆದಾಯಮಿತಿ ರೂ.15.00 ಲಕ್ಷಗಳು.ವಯೋಮಿತಿ:ವಿದ್ಯಾರ್ಥಿಯವಯಸ್ಸು 32 (ಸ್ನಾತಕೋತ್ತರಪದವೀಧರರಿಗೆ) ಮತ್ತುಪಿ.ಎಚ್.ಡಿ. ಪದವೀಧವಿದರರಿಗೆ 35 ವರ್ಷಗಳವಯೋಮಿತಿಯನ್ನುನಿಗಧಿಪಡಿಸಲಾಗಿದೆ. ಸಾಲದಭದ್ರತೆಗೆವಿದ್ಯಾರ್ಥಿಯತಂದೆಅಥವಾಜಾಮೀನುದಾರರುಹೊಂದಿರುವಸ್ಥಿರಾಸ್ತಿಯನ್ನುನಿಗಮಕ್ಕೆಆಧಾರದಮಾಡಬೇಕು (ಕೊಲ್ಯಾಟರಲ್‌ ಸೆಕ್ಯೂರಿಟಿ)ಅರ್ಹತಾಪರೀಕ್ಷೆಯಲ್ಲಿಪ್ರಥಮದರ್ಜೆಯಲ್ಲಿಉತ್ತೀರ್ಣರಾಗಿರಬೇಕು."]', '["ವ್ಯವಸ್ಥಾಪಕ ನಿರ್ದೇಶಕರ ಅಧ್ಯಕ್ಷತೆಯ ಆಯ್ಕೆ ಸಮಿತಿಯ ಮೂಲಕ ಫಲಾನುಭವಿಗಳನ್ನು ಆಯ್ಕೆ ಮಾಡಲಾಯಿತು."]', 1, '["ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('2aa06981-5d1c-4413-b025-6b25d37b89ef', 'BACKWARD-CLASSES-WEL-30', '59d7c155-e129-436a-b747-c5cb6abba051', 'Ganga Kalyana Irrigation Scheme', 'Irrigational purpose to help farmers', 0, '', '["Ration card,aadhaar card,Small and Marginal Farmer Certificate,RTC,Passport size photo of the applicant"]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '3e791161-f615-4934-979e-626057e986b7', 'ಗಂಗಾ ಕಲ್ಯಾಣ ನೀರಾವರಿ ಯೋಜನೆ', 'Irrigation facilities will be provided to the small and very small farmers'' lands belonging to the Okkaliga community and whose annual income is below the limit of Rs.98,000/-. Bangalore North, Bangalore South, Bangalore Rural, Kolar, Chikkaballapur, Tumkur and Ramnagar unit cost Rs.4.75 lakhs for individual tube well project Rs.4.25 lakhs subsidy out of which Rs.75,000/- will be made to ESKs for electrification. In case the unit cannot be completed, a loan of Rs.50,000/- will be sanctioned at an interest rate of 4%. For the remaining districts, the unit cost is Rs.3.75 lakh in which subsidy is Rs.3.25 lakh and loan of Rs.50,000/- will be sanctioned at 4% interest rate. Out of the subsidy amount, Rs.75,000/- per tube well will be made to the Eskoms for electrification.', NULL, NULL, NULL, NULL, NULL, 30.00, NULL, NULL, NULL, NULL, false, 'No', '[]', '[]', 1, '["ಪಡಿತರ ಚೀಟಿ, ಆಧಾರ್ ಕಾರ್ಡ್, ಸಣ್ಣ ಮತ್ತು ಅತಿ ಸಣ್ಣ ರೈತರ ಪ್ರಮಾಣಪತ್ರ, ಆರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('d39aee75-06a2-4d29-82a1-63f374b0d51a', 'BACKWARD-CLASSES-WEL-29', '59d7c155-e129-436a-b747-c5cb6abba051', 'Swavalambi SarathiScheme', 'self employment through taxi /goods vehicle', 0, '', '["Passport Size Photo of the applicant", "Driving Licence", "Vehicle Quotation", "Aadhar linked PassBook Front Page Photo,Ration card,aadhaar card"]', '["The applicant must be between 15 and 30 years of age.", "The annual family income of the applicant must be within Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the Chief Executive Officer of the Zilla Panchayat."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '3e791161-f615-4934-979e-626057e986b7', 'ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ ಯೋಜನೆ', 'Corporation assisted to Vokkaliga community, whose annual family income is Rs.1,20,000/- for urban area and Rs.98,000/- for rural area with 50% maximum subsidy of 3.00 lakhs for the loan for purchase of four wheeler under Swavalambi Sarathi Yojana for self-employment for unemployed persons in the age group of 18 to 45 years. will be sanctioned. Balance loan amount through Banks at the prevailing interest rate charged by them getting a loan.', NULL, NULL, NULL, NULL, NULL, 30.00, NULL, NULL, NULL, NULL, false, 'No', '["ಅರ್ಜಿದಾರರವಯಸ್ಸು15 ರಿಂದ 30 ವರ್ಷದ ಒಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬ ವಾರ್ಷಿಕವರಮಾನ ಗ್ರಾಮಾಂತರ ಪ್ರದೇಶದವರಿಗೆರೂ.98,000/- ಹಾಗೂ ಪಟ್ಟಣಪ್ರದೇಶದವರಿಗೆರೂ.1,20,000/- ಒಳಗಿರಬೇಕು."]', '["ಜಿಲ್ಲಾ ಪಂಚಾಯತ್"]', 1, '["ಅರ್ಜಿದಾರರ ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('f2b0f508-63b6-4d8f-93ff-ba0467119bbf', 'BACKWARD-CLASSES-WEL-28', '59d7c155-e129-436a-b747-c5cb6abba051', 'Self Employment Direct Loan Scheme', 'self employment loan', 0, '', '["Pasport Size Photo", "Ration card", "Aadhar linked PassBook Front Page PhotoPasport Size Photo", "Ration card,adhaar card"]', '["The applicant must be between 15 and 30 years of age.", "The annual family income of the applicant must be within Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the Chief Executive Officer of the Zilla Panchayat."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '3e791161-f615-4934-979e-626057e986b7', 'ಸ್ವಯಂ
