INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('51f45343-29c1-4cb2-bb1e-4ad6566cff30', 'BACKWARD-CLASSES-WEL-39', '59d7c155-e129-436a-b747-c5cb6abba051', 'Sewing Machine Disbursement scheme', 'self enpowerment', 0, '', '["Pasport Size Photo", "Ration card", "Aadhar linked PassBook Front Page PhotoPasport Size Photo", "Ration card,adhaar card"]', '["The applicant must be between 18 and 55 years of age.", "The annual family income of the applicant must be within Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the MLA of the respective constituency"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '476a6123-f199-4c2d-bda8-630b3484175c', 'ಹೊಲಿಗೆ ಯಂತ್ರ ವಿತರಣಾ ಯೋಜನೆ', 'The scheme was introduced to provide financial independence to the backward class communities by free distribution of sewing machine', NULL, NULL, NULL, NULL, NULL, 30.00, NULL, NULL, NULL, NULL, false, 'No', '["ಅರ್ಜಿದಾರರವಯಸ್ಸು18 ರಿಂದ 55 ವರ್ಷದ ಒಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬ ವಾರ್ಷಿಕವರಮಾನ ಗ್ರಾಮಾಂತರ ಪ್ರದೇಶದವರಿಗೆರೂ.98,000/- ಹಾಗೂ ಪಟ್ಟಣಪ್ರದೇಶದವರಿಗೆರೂ.1,20,000/- ಒಳಗಿರಬೇಕು."]', '["ಸಂಬಂಧಿತ ಕ್ಷೇತ್ರದ ಶಾಸಕರ ಅಧ್ಯಕ್ಷತೆಯ ಆಯ್ಕೆ ಸಮಿತಿಯ ಮೂಲಕ ಫಲಾನುಭವಿಗಳನ್ನು ಆಯ್ಕೆ ಮಾಡಲಾಗುವುದು."]', 1, '["ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('a7282d10-08aa-4f3e-81b8-e2de0d200542', 'BACKWARD-CLASSES-WEL-38', '59d7c155-e129-436a-b747-c5cb6abba051', 'Ganga Kalyana Scheme', 'Irrigational purpose to help farmers', 0, '', '["Ration card,aadhaar card,Small and Marginal Farmer Certificate,RTC,Passport size photo of the applicant"]', '["The annual family income of the applicant must be within Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas.No age limit"]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the MLA of the respective constituency"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '476a6123-f199-4c2d-bda8-630b3484175c', 'ಗಂಗಾ ಕಲ್ಯಾಣ ಯೋಜನೆ', 'Irrigation facilities will be provided to the small and very small farmers lands belonging to the Uppara community and whose annual income is below the limit of Rs.98,000/-.Bangalore North, Bangalore South, Bangalore Rural, Kolar, Chikkaballapur, Tumkur and Ramnagar unit cost Rs.4.75 lakhs for individual tube well project Rs.4.25 lakhs subsidy out of which Rs.75,000/- will be paid to ESCOM’s for electrification. In case the unit cannot be completed, a loan of Rs.50,000/- will be sanctioned at an interest rate of 4%.For the remaining districts, the unit cost is Rs.3.75 lakh in which subsidy is Rs.3.25 lakh and loan of Rs.50,000/- will be sanctioned at 4% interest rate. Out of the subsidy amount, Rs.75,000/- per tube well will be paid to the ESCOM’s for electrification.
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('776891cb-7966-4f14-b116-733344aff0d7', 'BACKWARD-CLASSES-WEL-37', '59d7c155-e129-436a-b747-c5cb6abba051', 'Swavalambi SarathiScheme', 'self employment through taxi /goods vehicle', 0, '', '["Passport Size Photo of the applicant", "Driving Licence", "Vehicle Quotation", "Aadhar linked PassBook Front Page Photo,Ration card,aadhaar card"]', '["The applicant must be between 18 and 45 years of age.", "The annual family income of the applicant must be within Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the MLA of the respective constituency"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '476a6123-f199-4c2d-bda8-630b3484175c', 'ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ ಯೋಜನೆಗೆ ಅರ್ಜಿ', 'Members of the backward class community in both urban and rural areas will be encouraged to take up self-employment through the provision of a subsidy—covering 50% of the cost up to a maximum of ₹3.00 lakh—for the purchase of four-wheeled vehicles. Under the ''Swavalambi Sarathi'' scheme, this assistance will be extended to unemployed youths who hold a valid driving license and have secured bank loans to purchase such vehicles.', NULL, NULL, NULL, NULL, NULL, 30.00, NULL, NULL, NULL, NULL, false, 'No', '["ಅರ್ಜಿದಾರರವಯಸ್ಸು18 ರಿಂದ 45 ವರ್ಷದ ಒಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬ ವಾರ್ಷಿಕವರಮಾನ ಗ್ರಾಮಾಂತರ ಪ್ರದೇಶದವರಿಗೆರೂ.98,000/- ಹಾಗೂ ಪಟ್ಟಣಪ್ರದೇಶದವರಿಗೆರೂ.1,20,000/- ಒಳಗಿರಬೇಕು."]', '["ಸಂಬಂಧಿತ ಕ್ಷೇತ್ರದ ಶಾಸಕರ ಅಧ್ಯಕ್ಷತೆಯ ಆಯ್ಕೆ ಸಮಿತಿಯ ಮೂಲಕ ಫಲಾನುಭವಿಗಳನ್ನು ಆಯ್ಕೆ ಮಾಡಲಾಗುವುದು."]', 1, '["ಅರ್ಜಿದಾರರ ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('cd12503d-e02c-41fc-8c0c-08b0154b7a2e', 'BACKWARD-CLASSES-WEL-36', '59d7c155-e129-436a-b747-c5cb6abba051', 'Loan Scheme for Higher Education in Foreign Universities', 'Education loan', 0, '', '["Pasport Size Photo", "Study Certificate", "Passport", "Visa", "Fee Structure", "aadhaar card,ration card, caste and income certificate", "Collateral Letter", "Parent Approval Letter", "Admission Confirmation Intimation Letter Provided by the Foreign University", "document_icon", "Aadhar linked PassBook Front Page Photo"]', '["The annual income limit for the student''s family is Rs. 15.00 lakhs. Regarding the age limit, a maximum age of 32 years has been fixed for postgraduates and 35 years for Ph.D. holders. As collateral security for the loan, immovable property owned by the student''s father or a guarantor must be pledged to the Corporation. The student must have passed the qualifying examination in the First Class."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the MLA of the respective constituency"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '476a6123-f199-4c2d-bda8-630b3484175c', 'ವಿದೇಶಿ ವಿಶ್ವವಿದ್ಯಾಲಯಗಳಲ್ಲಿ ಉನ್ನತ ಶಿಕ್ಷಣ ವ್ಯಾಸಂಗಕ್ಕೆ ಸಾಲ', 'To provide loan facility up to Rs.25.00 lakhs per annum maximum of Rs.50.00 lakhs for a period of 2 years without interest to the students of Uppara community who are admitted to Master Degree, PhD, Post-Doctoral courses for higher education in foreign universities With QS World Ranking below 1000.', NULL, NULL, NULL, NULL, NULL, 30.00, NULL, NULL, NULL, NULL, false, 'No', '["ವಿದ್ಯಾರ್ಥಿಯಕುಟುಂಬದವಾರ್ಷಿಕಆದಾಯಮಿತಿ ರೂ.15.00 ಲಕ್ಷಗಳು.ವಯೋಮಿತಿ:ವಿದ್ಯಾರ್ಥಿಯವಯಸ್ಸು 32 (ಸ್ನಾತಕೋತ್ತರಪದವೀಧರರಿಗೆ) ಮತ್ತುಪಿ.ಎಚ್.ಡಿ. ಪದವೀಧವಿದರರಿಗೆ 35 ವರ್ಷಗಳವಯೋಮಿತಿಯನ್ನುನಿಗಧಿಪಡಿಸಲಾಗಿದೆ. ಸಾಲದಭದ್ರತೆಗೆವಿದ್ಯಾರ್ಥಿಯತಂದೆಅಥವಾಜಾಮೀನುದಾರರುಹೊಂದಿರುವಸ್ಥಿರಾಸ್ತಿಯನ್ನುನಿಗಮಕ್ಕೆಆಧಾರದಮಾಡಬೇಕು (ಕೊಲ್ಯಾಟರಲ್‌ ಸೆಕ್ಯೂರಿಟಿ)ಅರ್ಹತಾಪರೀಕ್ಷೆಯಲ್ಲಿಪ್ರಥಮದರ್ಜೆಯಲ್ಲಿಉತ್ತೀರ್ಣರಾಗಿರಬೇಕು."]', '["ಸಂಬಂಧಿತ ಕ್ಷೇತ್ರದ ಶಾಸಕರ ಅಧ್ಯಕ್ಷತೆಯ ಆಯ್ಕೆ ಸಮಿತಿಯ ಮೂಲಕ ಫಲಾನುಭವಿಗಳನ್ನು ಆಯ್ಕೆ ಮಾಡಲಾಗುವುದು."]', 1, '["ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('4e09db49-352a-43b1-aea1-dfea784a271b', 'BACKWARD-CLASSES-WEL-35', '59d7c155-e129-436a-b747-c5cb6abba051', 'Application for Self Employment Direct Loan Scheme', 'self employment loan', 0, '', '["Pasport Size Photo", "Ration card", "Aadhar linked PassBook Front Page PhotoPasport Size Photo", "Ration card,adhaar card"]', '["The applicant must be between 18 and 55 years of age.", "The annual family income of the applicant must be within Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the MLA of the respective constituency"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '476a6123-f199-4c2d-bda8-630b3484175c', 'ಸ್ವಯಂ
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('3a5e55e3-66d7-4ce0-924a-9de62bb9020f', 'BACKWARD-CLASSES-WEL-34', '59d7c155-e129-436a-b747-c5cb6abba051', 'Arivu Educational Loan Scheme(renewal)', 'Education loan', 0, '', '["Caste and income certificate,Aadhaar card,Ration card,Fees structure, PUC Marks Card,CET /NEET order copy,Study Certificate(12th or PUC),Aadhar linked PassBook Front Page Photo,Admission Letter"]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '476a6123-f199-4c2d-bda8-630b3484175c', 'ಅರಿವು ಶೈಕ್ಷಣಿಕ ಸಾಲ ಯೋಜನೆ (ನವೀಕರಣ)', 'In this scheme the selected beneficiaries in arivu fresh scheme have to apply for renewal for next academic year''s installment', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ, ಆಧಾರ್ ಕಾರ್ಡ್, ಪಡಿತರ ಚೀಟಿ, ಶುಲ್ಕದ ವಿವರ, ಪಿಯುಸಿ (PUC) ಅಂಕಪಟ್ಟಿ, ಸಿಇಟಿ (CET)/ನೀಟ್ (NEET) ಆದೇಶದ ಪ್ರತಿ, ವ್ಯಾಸಂಗ ಪ್ರಮಾಣಪತ್ರ (12ನೇ ತರಗತಿ ಅಥವಾ ಪಿಯುಸಿ), ಆಧಾರ್ ಜೋಡಣೆಯಾಗಿರುವ ಬ್ಯಾಂಕ್ ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('7169cc85-17ef-4bd8-9ca1-fed454403b89', 'BACKWARD-CLASSES-WEL-33', '59d7c155-e129-436a-b747-c5cb6abba051', 'Arivu Educational Loan Scheme (Fresh)', 'Education loan', 0, '', '["Caste and income certificate,Aadhaar card,Ration card,Fees structure, PUC Marks Card,CET /NEET order copy,Study Certificate(12th or PUC),Aadhar linked PassBook Front Page Photo,Admission Letter"]', '["The annual income of the candidate and their family must be within the limit of ₹3.50 lakh.Age limit is 15-30 years"]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the Chief Executive Officer of the Zilla Panchayat."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '476a6123-f199-4c2d-bda8-630b3484175c', 'ಅರಿವು ಶೈ ಕ್ಷಣಿಕ ಸಾಲ ಯೋಜನೆ (ಹೊಸ)', 'Under this scheme, an educational loan of up to ₹1,00,000—at an annual interest rate of 2%—will be sanctioned to students from the backward class Communities who have secured admission to professional higher education courses (such as engineering, medicine, and dentistry) through CET or NEET. The annual income of the candidate and their family must be within the limit of ₹3.50 lakh.', NULL, NULL, NULL, NULL, NULL, 30.00, NULL, NULL, NULL, NULL, false, 'No', '["ಅಭ್ಯರ್ಥಿ ಮತ್ತು ಅವರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯವು ₹3.50 ಲಕ್ಷದ ಮಿತಿಯೊಳಗೆ ಇರಬೇಕು. ವಯಸ್ಸಿನ ಮಿತಿ 15 ರಿಂದ 30 ವರ್ಷಗಳು."]', '["ಜಿಲ್ಲಾ ಪಂಚಾಯತ್"]', 1, '["ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ, ಆಧಾರ್ ಕಾರ್ಡ್, ಪಡಿತರ ಚೀಟಿ, ಶುಲ್ಕದ ವಿವರ, ಪಿಯುಸಿ (PUC) ಅಂಕಪಟ್ಟಿ, ಸಿಇಟಿ (CET)/ನೀಟ್ (NEET) ಆದೇಶದ ಪ್ರತಿ, ವ್ಯಾಸಂಗ ಪ್ರಮಾಣಪತ್ರ (12ನೇ ತರಗತಿ ಅಥವಾ ಪಿಯುಸಿ), ಆಧಾರ್ ಜೋಡಣೆಯಾಗಿರುವ ಬ್ಯಾಂಕ್ ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('82bcfe9e-5365-4b7a-8297-dc60ef8c4412', 'BACKWARD-CLASSES-WEL-72', '59d7c155-e129-436a-b747-c5cb6abba051', 'Swavalambi Sarathi Scheme', 'General', 0, '', '["ge Limitation:- age should be above 21 Years and below 45 Years.", "➤ Income limit should be less than 1,20,000/- per annum.", "➤ BPL ration Card is Mandatory", "➤ Candidate should have LMV driving licence", "➤ DL Should not be expired", "➤ Candidate should be unemployed and submit self declaration letter. ಕಾನನದಾ"]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'a1bbd14e-10a3-4d9b-b099-d046df803ef8', 'ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ ಯೋಜನೆ', 'The scheme provides financial assistance to unemployed youth belonging to the Veerashaiva Lingayat community through the Karnataka Veerashaiva Lingayat Development Corporation for the purchase of four-wheeler light motor vehicles.
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('8b2d8f4d-9e2b-4d70-9438-52a126dbd495', 'BACKWARD-CLASSES-WEL-71', '59d7c155-e129-436a-b747-c5cb6abba051', 'Swatantrya Amrutha Mahotsavada Munnade Scheme', 'General', 0, '', '["Marks card related to the educational qualification."]', '[]', '[]', '["ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ವರ್ಷಕ್ಕಿಂತ ಮೇಲ್ಪಟ್ಟಿದ್ದು, 45 ವರ್ಷಕ್ಕಿಂತ ಕಡಿಮೆ ಇರಬೇಕು.", "ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯವು ₹1,20,000/- ಕ್ಕಿಂತ ಕಡಿಮೆ ಇರಬೇಕು."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'a1bbd14e-10a3-4d9b-b099-d046df803ef8', 'ಸ್ವಾತಂತ್ರ್ಯ ಅಮೃತ ಮಹೋತ್ಸವದ ಮುನ್ನಡೆ ಯೋಜನೆಯ', 'To provide free skill development training through short-term courses and create employment opportunities for youth belonging to the Veerashaiva Lingayat community.Eligibility Criteria: Candidates must belong to Category 3(B), be between 18 and 25 years of age, and have completed 10th Standard, PUC, or a Degree.', NULL, NULL, NULL, NULL, NULL, 30.00, NULL, NULL, NULL, NULL, false, 'No', '[]', '["ಆಯಾ ವಿಧಾನ ಸಭಾ ಕ್ಷೇತ್ರದ ಶಾಸಕರ ಅಧ್ಯಕ್ಷರ ಸಮಿತಿಯಲ್ಲಿ ಆಯ್ಕೆ ಮಾಡಲಾಗುವುದು."]', 1, '["ವಿದ್ಯಾರ್ಹತೆಗೆ ಸಂಬಂಧಪಟ್ಟಂತಹ ಅಂಕಪಟ್ಟಿ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('28bfb797-3cb1-414b-aa9e-730916cf607c', 'BACKWARD-CLASSES-WEL-70', '59d7c155-e129-436a-b747-c5cb6abba051', 'Ganga Kalyana Irrigation scheme/', 'General', 0, '', '["A certified copy of the Ration Card / Voter ID Card / Aadhaar Card issued by the competent authority must be submitted as proof of the applicant’s residence.", "Three recent passport-size photographs of the applicant.", "A certificate issued by the Revenue Officer confirming that the applicant is a small or marginal farmer.", "Land revenue records of the land owned by the applicant, such as RTC/Pahani, Khata Extract, Patta Book, Mutation, EC (Encumbrance Certificate), Family Tree, and Land Boundary Certificate.", "A self-declaration stating that the applicant does not have irrigation facilities.", "If the unit cost exceeds ₹1,50,000/-, a consent letter from the beneficiary agreeing to obtain a loan must be submitted.", "The applicant’s annual income in rural areas must not exceed ₹98,000/-. The family’s annual income must be less than ₹1,20,000/-.", "The farmer’s FRUITS ID is mandatory.", "A BPL (Below Poverty Line) Ration Card is mandatory."]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'a1bbd14e-10a3-4d9b-b099-d046df803ef8', 'ಗಂಗಾ ಕಲ್ಯಾಣ ನೀರಾವರಿ ಯೋಜನೆ/ಜೀವ ಜಲ', 'Keeping in mind the principle that “Farmers are the backbone of the country,” the Jeevajala (Ganga Kalyana) Scheme has been formulated to support farmers and improve their agricultural activities.
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('20adc5ad-982a-430c-9e6e-b550b7a4b212', 'BACKWARD-CLASSES-WEL-69', '59d7c155-e129-436a-b747-c5cb6abba051', 'Loan Scheme for Higher Education in Foreign Universities: (Renewal)', 'General', 0, '', '["Pasport Size Photo", "Study Certificate", "Passport", "Visa", "Fee Structure", "aadhaar card,ration card, caste and income certificate", "Collateral Letter", "Parent Approval Letter", "Admission Confirmation Intimation Letter Provided by the Foreign University", "document_icon", "Aadhar linked PassBook Front Page Photo"]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'a1bbd14e-10a3-4d9b-b099-d046df803ef8', 'ವಿದೇಶಿ ವಿಶ್ವವಿದ್ಯಾಲಯಗಳಲ್ಲಿ ಉನ್ನತ ಶಿಕ್ಷಣ ವ್ಯಾಸಂಗಕ್ಕೆ ಸಾಲ (ನವೀಕರಣ)', 'To provide loan facility up to Rs.25.00 lakhs per annum maximum of Rs.50.00 lakhs for a period of 2 years without interest to the students of Uppara community who are admitted to Master Degree, PhD, Post-Doctoral courses for higher education in foreign universities With QS World Ranking below 1000. In this scheme the selected beneficiaries have to apply for renewal for next academic year''s installment', NULL, NULL, NULL, NULL, NULL, 30.00, NULL, NULL, NULL, NULL, false, 'No', '[]', '["ಆಯಾ ವಿಧಾನ ಸಭಾ ಕ್ಷೇತ್ರದ ಶಾಸಕರ ಅಧ್ಯಕ್ಷರ ಸಮಿತಿಯಲ್ಲಿ ಆಯ್ಕೆ ಮಾಡಲಾಗುವುದು."]', 1, '["ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('1e81d6c0-45f0-4239-a32f-bfe6f2303312', 'BACKWARD-CLASSES-WEL-68', '59d7c155-e129-436a-b747-c5cb6abba051', 'Self-Employment Programme / Kayaka Kirana', 'Education loan', 0, '', '["Pasport Size Photo", "Ration card", "Aadhar linked PassBook Front Page PhotoPasport Size Photo", "Ration card,adhaar card"]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'a1bbd14e-10a3-4d9b-b099-d046df803ef8', 'ಸ್ವಯಂ ಉದ್ಯೋಗ ಕಾರ್ಯಕ್ರಮ/ಕಾಯಕ ಕಿರಣ', 'Financial assistance will be provided to economic activities such as business, transport and service sectors. 
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('6b693540-e8ac-455e-9125-7cfbfd9ef645', 'BACKWARD-CLASSES-WEL-67', '59d7c155-e129-436a-b747-c5cb6abba051', 'Arivu Educational Loan Scheme / Basavabelagu (Renewal)', 'self employment loan', 0, '', '["Caste and income certificate,Aadhaar card,Ration card,Fees structure, PUC Marks Card,CET /NEET order copy,Study Certificate(12th or PUC),Aadhar linked PassBook Front Page Photo,Admission Letter"]', '["The applicant must be between 18 to 55 years of age.", "The annual family income of the applicant must be within Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the MLA."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'a1bbd14e-10a3-4d9b-b099-d046df803ef8', 'ಅರಿವು ಶೈಕ್ಷಣಿಕ ಸಾಲ ಯೋಜನೆ/ ಬಸವಬೆಳಗು (ನವೀಕರಣ)', 'In this scheme the selected beneficiaries in arivu fresh scheme have to apply for renewal for next academic year''s installment', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["ಅರ್ಜಿದಾರರವಯಸ್ಸು18 ರಿಂದ 55 ವರ್ಷದ ಒಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬ ವಾರ್ಷಿಕವರಮಾನ ಗ್ರಾಮಾಂತರ ಪ್ರದೇಶದವರಿಗೆರೂ.98,000/- ಹಾಗೂ ಪಟ್ಟಣಪ್ರದೇಶದವರಿಗೆರೂ.1,20,000/- ಒಳಗಿರಬೇಕು."]', '["ಆಯಾ ವಿಧಾನ ಸಭಾ ಕ್ಷೇತ್ರದ ಶಾಸಕರ ಅಧ್ಯಕ್ಷರ ಸಮಿತಿಯಲ್ಲಿ ಆಯ್ಕೆ ಮಾಡಲಾಗುವುದು."]', 1, '["ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ, ಆಧಾರ್ ಕಾರ್ಡ್, ಪಡಿತರ ಚೀಟಿ, ಶುಲ್ಕದ ವಿವರ, ಪಿಯುಸಿ (PUC) ಅಂಕಪಟ್ಟಿ, ಸಿಇಟಿ (CET)/ನೀಟ್ (NEET) ಆದೇಶದ ಪ್ರತಿ, ವ್ಯಾಸಂಗ ಪ್ರಮಾಣಪತ್ರ (12ನೇ ತರಗತಿ ಅಥವಾ ಪಿಯುಸಿ), ಆಧಾರ್ ಜೋಡಣೆಯಾಗಿರುವ ಬ್ಯಾಂಕ್ ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('e4dddfce-ae42-4447-984f-04b08d94db9b', 'BACKWARD-CLASSES-WEL-66', '59d7c155-e129-436a-b747-c5cb6abba051', 'Arivu Educational Loan Scheme / Basavabelagu (Fresh)', 'Education loan', 0, '', '["Caste and income certificate,Aadhaar card,Ration card,Fees structure, PUC Marks Card,CET /NEET order copy,Study Certificate(12th or PUC),Aadhar linked PassBook Front Page Photo,Admission Letter"]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'a1bbd14e-10a3-4d9b-b099-d046df803ef8', 'ಅರಿವು ಶೈ ಕ್ಷಣಿಕ ಸಾಲ ಯೋಜನೆ/ ಬಸವಬೆಳಗು (ಹೊಸ)', 'Under this scheme, an educational loan of up to ₹1,00,000—at an annual interest rate of 2%—will be sanctioned to students from the Uppara community who have secured admission to professional higher education courses (such as engineering, medicine, and dentistry) through CET or NEET. The annual income of the candidate and their family must be within the limit of ₹3.50 lakh.', NULL, NULL, NULL, NULL, NULL, 30.00, NULL, NULL, NULL, NULL, false, 'No', '[]', '[]', 1, '["ಜಾತಿ ಮತ್ತು ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ, ಆಧಾರ್ ಕಾರ್ಡ್, ಪಡಿತರ ಚೀಟಿ, ಶುಲ್ಕದ ವಿವರ, ಪಿಯುಸಿ (PUC) ಅಂಕಪಟ್ಟಿ, ಸಿಇಟಿ (CET)/ನೀಟ್ (NEET) ಆದೇಶದ ಪ್ರತಿ, ವ್ಯಾಸಂಗ ಪ್ರಮಾಣಪತ್ರ (12ನೇ ತರಗತಿ ಅಥವಾ ಪಿಯುಸಿ), ಆಧಾರ್ ಜೋಡಣೆಯಾಗಿರುವ ಬ್ಯಾಂಕ್ ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('d4d477a6-dc92-4c68-ae2e-eea92f1a9b14', 'FINANCE-DEPARTMENT-7', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Shifting of licenses as per Karnataka Excise (General Conditions of licenses) rules, 1967 in accordance with the rule 23.', 'Retailer', 18, 'The Shifting of License as per Rule 23 module enables license holders to apply online for shifting an excise license to a new location in accordance with the Karnataka Excise (General Condition of Licenses) Rules, 1966. The module supports end-to-end digital processing, including application submission, payment, document upload, departmental verification, and final approval through the Excise E-Services portal.', '["Other Documents", "Approved Blueprint", "Copy of License", "Request Letter", "Signature Photo", "Vehicle Parking Area Photos", "PAN Card Issued by the Income Tax Department", "Any Other Address Proof", "Front Elevation", "Store Room/Store Area Photo", "Main Counter + 4 Additional Counters", "Kitchen Photo", "Dining Hall Photo", "Indoor Games Area Photo", "Outdoor Games Area Photo", "Library/Reading Room Photo", "Toilets Photo", "Counters Photo", "Representative Room", "Receipt"]', '["Valid retailer Licence"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಕರ್ನಾಟಕ ಅಬಕಾರಿ (ಪರವಾನಗಿಗಳ ಸಾಮಾನ್ಯ ಷರತ್ತುಗಳು) ನಿಯಮಗಳು, 1967ರ ನಿಯಮ 23ರನ್ವಯ ಪರವಾನಗಿಗಳ ಸ್ಥಳಾಂತರ.', 'The Shifting of License as per Rule 23 module enables license holders to apply online for shifting an excise license to a new location in accordance with the Karnataka Excise (General Condition of Licenses) Rules, 1966. The module supports end-to-end digital processing, including application submission, payment, document upload, departmental verification, and final approval through the Excise E-Services portal.', NULL, 'District Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ನಿಯಮ 23ರ ಪ್ರಕಾರ ಪರವಾನಗಿ ಸ್ಥಳಾಂತರ ಘಟಕವು ಕರ್ನಾಟಕ ಅಬಕಾರಿ (ಪರವಾನಗಿಗಳ ಸಾಮಾನ್ಯ ಷರತ್ತುಗಳು) ನಿಯಮಗಳು, 1966ರ ಅನುಸಾರ ಅಬಕಾರಿ ಪರವಾನಗಿಯನ್ನು ಹೊಸ ಸ್ಥಳಕ್ಕೆ ಸ್ಥಳಾಂತರಿಸಲು ಪರವಾನಗಿದಾರರಿಗೆ ಆನ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಇತರೆ ದಾಖಲೆಗಳು", "ಅನುಮೋದಿತ ನೀಲನಕ್ಷೆ", "ಪರವಾನಗಿಯ ಪ್ರತಿ", "ವಿನಂತಿ ಪತ್ರ", "ಸಹಿಯ ಛಾಯಾಚಿತ್ರ", "ವಾಹನ ನಿಲುಗಡೆ ಪ್ರದೇಶದ ಛಾಯಾಚಿತ್ರಗಳು", "ಆದಾಯ ತೆರಿಗೆ ಇಲಾಖೆಯಿಂದ ನೀಡಲಾದ ಪ್ಯಾನ್ ಕಾರ್ಡ್", "ಇತರೆ ಯಾವುದೇ ವಿಳಾಸದ ಪುರಾವೆ", "ಕಟ್ಟಡದ ಮುಂಭಾಗದ ನೋಟ", "ಉಗ್ರಾಣ ಕೊಠಡಿ/ಸಂಗ್ರಹಣಾ ಪ್ರದೇಶದ ಛಾಯಾಚಿತ್ರ", "ಮುಖ್ಯ ಕೌಂಟರ್ + 4 ಹೆಚ್ಚುವರಿ ಕೌಂಟರ್"]', NULL, NULL, '1266');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('b228bb16-615d-4408-abf5-ceb170c4370d', 'FINANCE-DEPARTMENT-17', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Grant of a Unit: IML Distillery/Bottling Plant/Brewery/Fortified Winery/Microbrewery License', 'Public', 45, 'The Grant of a Unit Licence service enables eligible Public registered applicants to apply for a licence to establish an IML distillery, bottling plant, brewery, fortified winery, or microbrewery, subject to applicable excise rules and regulations. The application is submitted to the Excise Department for scrutiny and approval in accordance with the prescribed requirements.', '["Calibration Certificate of Storage Tank", "Others", "Bottling Area", "Trade Licence", "Warehouse Area Photograph", "Bottle Washing Area", "GST Registration Certificate", "PAN Card Issued by the Income Tax Department", "List of Directors/Partners", "Memorandum of Association and Articles of Association or Partnership Deed, as Applicable", "Project Report with Flow Chart", "Clearance Certificate Issued by the Karnataka State Pollution Control Board", "NOC/Licence Issued by the Inspector of Factories and Boilers", "Any Other Licences or Documents Obtained from the Commercial Taxes Department or the Department of Industries and Commerce", "FSSAI Licence Issued by the Food Safety and Standards Authority of India", "Application in the Prescribed Form", "Proposed Blueprint Submitted for Approval", "Proposed Premises Documents (Khata Extract, Latest Tax-Paid Receipt, Building Owner''s Consent)", "Documents Showing the Availability of Resources (Water and Electricity)", "Undertaking as per Rule 5(B) of the Karnataka Excise (Brewery) Rules, 1967", "Latest Income Tax Returns Filing Document", "NOC from the Labour Department", "Machine Purchase Order/Invoice Copy", "Malt Grinding Area", "Mash Tun Area", "Lauter Tun Area", "Wort Kettle", "Whirlpool Area", "Fermentation Vessel Area", "Filtration Area", "Chemistry Laboratory", "Loading Bay Area", "Empty Bottle Area", "Challan for Payment of Licence Fee of ₹2,00,000 per Annum Plus Additional Licence Fee", "Challan for Payment of Additional Excise Duty", "Building Owner''s Consent/Tax-Paid Receipt", "Challan for Payment of Excise Duty", "Blueprint Showing a 100-Metre Radius, in Triplicate", "Photographs of Machinery to Be Installed", "BBMP Trade Licence Certificate", "Details of Machinery to Be Installed in the Unit", "Architect''s Report", "In-House Chemist Details, Including Educational Qualifications and Academic Certificates", "Certificate from an Engineer Regarding the Area of the Microbrewery", "Certificate from the Brewery Installation Engineer Regarding the Annual Installed Capacity of the Installed Microbrewery System", "Certificate of Verification from the Department of Legal Metrology", "Form \"C\" Issued by the Food Safety and Standards Authority of India", "Undertaking as per Rule 6(A) of the Karnataka Excise (Distillery and Warehouse) Rules, 1967", "Challan for Payment of Licence Fee of ₹45,00,000 per Annum + 15% Additional Licence Fee of ₹6,75,000 per Annum + Bottling Licence Fee of ₹1,00,000 per Annum", "Challan for Payment of Licence Fee (₹50,000 per Annum + 15% Additional Licence Fee of ₹7,500 per Annum) + Bottling Licence Fee of ₹25,000 per Annum", "Undertaking as per Rule 5(A) of the Karnataka Excise (Manufacture of Fortified Wine from Grapes) Rules, 1968", "Water Tank", "BBT", "Fermentation Tank", "Legal Metrology Certificate of Verification", "Trade/General Licence", "Challan (Fees, ED and AED)", "Disqualification Affidavit as per Rule 5B", "Fire Safety Certificate/Report", "Brewmaster Qualification Certificate", "Photographs of the Premises and Equipment Installation", "Certificate from the Department of Labour", "Certificate of Registration of Firm (Form C)/Company Incorporation Certificate, as Applicable", "Income Tax Return Filing Document"]', '["Public Regestration required"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಘಟಕ ಮಂಜೂರಾತಿ: ಐಎಂಎಲ್ (IML) ಡಿಸ್ಟಿಲರಿ/ಬಾಟಲಿ ತುಂಬುವ ಘಟಕ/ಬ್ರೂವರಿ/ಫಾರ್ಟಿಫೈಡ್ ವೈನರಿ/ಮೈಕ್ರೋಬ್ರೂವರಿ ಪರವಾನಗಿ', 'The Grant of a Unit Licence service enables eligible Public registered applicants to apply for a licence to establish an IML distillery, bottling plant, brewery, fortified winery, or microbrewery, subject to applicable excise rules and regulations. The application is submitted to the Excise Department for scrutiny and approval in accordance with the prescribed requirements.', NULL, 'State Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಘಟಕ ಪರವಾನಗಿಯನ್ನು ಮಂಜೂರು ಮಾಡುವ ಸೇವೆಯು ಅರ್ಹ ಸಾರ್ವಜನಿಕ ಅರ್ಜಿದಾರರಿಗೆ ಅನ್ವಯವಾಗುವ ಅಬಕಾರಿ ನಿಯಮಗಳು ಮತ್ತು ನಿಬಂಧನೆಗಳಿಗೆ ಒಳಪಟ್ಟು IML ಡಿಸ್ಟಿಲರಿ, ಬಾಟ್ಲಿಂಗ್ ಪ್ಲಾಂಟ್, ಬ್ರೂವರಿ, ಫೋರ್ಟಿಫೈಡ್ ವೈನರಿ ಅಥವಾ ಮೈಕ್ರೋಬ್ರೂವರಿ ಸ್ಥಾಪಿಸಲು ಪರವಾನಗಿಗಾಗಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಲು ಅವಕಾಶ ನೀಡುತ್ತದೆ. ನಿಗದಿತ ಅವಶ್ಯಕತೆಗಳಿಗೆ ಅನುಗುಣವಾಗಿ ಪರಿಶೀಲನೆ ಮತ್ತು ಅನುಮೋದನೆಗಾಗಿ ಅರ್ಜಿಯನ್ನು ಅಬಕಾರಿ ಇಲಾಖೆಗೆ ಸಲ್ಲಿಸಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಸಂಗ್ರಹಣಾ ಟ್ಯಾಂಕ್"]', NULL, NULL, '1267');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('c8f2277d-7152-42ad-a8c0-43279542e987', 'FINANCE-DEPARTMENT-4', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Relaxation as per Rule 5', 'Retailer', 25, 'The Relaxation as per Rule 5 service facilitates the online processing of applications related to relaxation from the restrictions prescribed under Rule 5. The service supports two types of applications: New Relaxation and Rejection due to Rule 5 Relaxation.', '["Blueprints", "Other Documents", "Copy of License", "NOC from Objectionable Place", "Request Letter by Licensee"]', '["Valid retailer Licence"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ನಿಯಮ 5 ರ ಪ್ರಕಾರ ವಿನಾಯಿತಿ', 'The Relaxation as per Rule 5 service facilitates the online processing of applications related to relaxation from the restrictions prescribed under Rule 5. The service supports two types of applications: New Relaxation and Rejection due to Rule 5 Relaxation.', NULL, 'State Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ನಿಯಮ 5ರ ಪ್ರಕಾರ ವಿನಾಯಿತಿ ಸೇವೆಯು ನಿಯಮ 5ರ ಅಡಿಯಲ್ಲಿ ವಿಧಿಸಲಾದ ನಿರ್ಬಂಧಗಳಿಂದ ವಿನಾಯಿತಿ ಕೋರುವ ಅರ್ಜಿಗಳನ್ನು ಆನ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ನೀಲನಕ್ಷೆಗಳು", "ಇತರೆ ದಾಖಲೆಗಳು", "ಪರವಾನಗಿಯ ಪ್ರತಿ", "ಆಕ್ಷೇಪಾರ್ಹ ಸ್ಥಳಕ್ಕೆ ಸಂಬಂಧಿಸಿದ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC)", "ಪರವಾನಗಿದಾರರ ವಿನಂತಿ ಪತ್ರ"]', NULL, NULL, '1268');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('90c518c3-854e-403b-9218-8d18b2199818', 'FINANCE-DEPARTMENT-6', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'To authorize by a general or special order to possess, import or transport of opium derivatives and medicinal hemp, for eligible persons as per Rule-29 of NDPS (Karnataka) Rules, 1985', 'Supplier', 37, 'The module is designed to facilitate the authorization, through a general or special order, for eligible persons to possess, import, or transport opium derivatives and medicinal hemp. This service is provided in accordance with Rule 29 of the NDPS (Karnataka) Rules, 1985.', '["Blueprints", "GST Certificate", "Project Report", "PAN Card", "Building Owner Consent/Rent Agreement/Katha", "Aadhaar Card", "Katha/Tax Paid Receipt", "Karnataka Pollution Control Board Clearance Certificate", "Certificate of Incorporation", "Karnataka State Medical Council Certificate of Registration / Pharmacy Council Certificate of Registration", "Memorandum of Association (MOA)", "Details of Principal Investigator/Researcher Who Is Conducting Research", "Drug Control Licence", "Company Details", "Articles of Association (AOA)", "Purpose for Research", "Name/Names of the Proprietor/Partners of the Firm/Company", "Full Address of Premises", "Photos of Lab/Facilities (If Any)", "General Purpose Licence/Trade Licence", "Form-37 Issued by Drug Control Department, Government of Karnataka", "Central Drugs Standard Control Organization (CDSCO) Form-CT17", "Blueprint - Plan/Diagram of Narcotics/Controlled Substance Storage Area", "Drug Testing Licence (DTL)", "Ministry of Environment, Forests and Climate Change, Government of India (Permission to Conduct Research in Animals - CCSEA)", "Drugs Specified Under Schedule C and C(1) or Any Other Schedule", "List of Competent Technical Persons", "Certificate of Accreditation Issued by National Accreditation Board for Testing and Calibration Laboratories", "Detailed List of Equipment and Instruments"]', '["Valid NDPS License"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'NDPS (ಕರ್ನಾಟಕ) ನಿಯಮಗಳು, 1985ರ ನಿಯಮ-29ರ ಪ್ರಕಾರ ಅರ್ಹ ವ್ಯಕ್ತಿಗಳಿಗೆ ಅಫೀಮು ಉತ್ಪನ್ನಗಳು ಮತ್ತು ವೈದ್ಯಕೀಯ ಸೆಣಬನ್ನು ಹೊಂದಲು, ಆಮದು ಮಾಡಿಕೊಳ್ಳಲು ಅಥವಾ ಸಾಗಿಸಲು ಸಾಮಾನ್ಯ ಅಥವಾ ವಿಶೇಷ ಆದೇಶದ ಮೂಲಕ ಅಧಿಕಾರ ನೀಡುವುದು.', 'The module is designed to facilitate the authorization, through a general or special order, for eligible persons to possess, import, or transport opium derivatives and medicinal hemp. This service is provided in accordance with Rule 29 of the NDPS (Karnataka) Rules, 1985.', NULL, 'State Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಈ ಘಟಕವು ಅರ್ಹ ವ್ಯಕ್ತಿಗಳಿಗೆ ಅಫೀಮಿನ ಉತ್ಪನ್ನಗಳು ಮತ್ತು ಔಷಧೀಯ ಗಾಂಜಾವನ್ನು ಹೊಂದಲು, ಆಮದು ಮಾಡಿಕೊಳ್ಳಲು ಅಥವಾ ಸಾಗಿಸಲು ಸಾಮಾನ್ಯ ಅಥವಾ ವಿಶೇಷ ಆದೇಶದ ಮೂಲಕ ಅಧಿಕೃತ ಅನುಮತಿ ನೀಡುವ ಪ್ರಕ್ರಿಯೆಯನ್ನು ಸುಗಮಗೊಳಿಸಲು ವಿನ್ಯಾಸಗೊಳಿಸಲಾಗಿದೆ. ಈ ಸೇವೆಯನ್ನು NDPS (ಕರ್ನಾಟಕ) ನಿಯಮಗಳು, 1985ರ ನಿಯಮ 29ರ ಅನುಸಾರ ಒದಗಿಸಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ನೀಲನಕ್ಷೆಗಳು", "ಜಿಎಸ್"]', NULL, NULL, '1269');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('1617333d-b31a-4ed1-b68d-8c1adfb2b4da', 'RAJIV-GANDHI-UNIVERS-1', '36019975-6c52-4695-ac9b-bb10fcfdb011', 'MIGRATION CERTIFICATE', 'General', 6, 'A migration certificate is essential for admission to another university or other higher education institution.', '["Documents not required, UG/PG Degree completion only(The auto check in the application software wether the degree completed or not)"]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '2e068fbc-04bb-4a0f-ac96-f924621ce46e', 'ವಲಸೆ ಪ್ರಮಾಣಪತ್ರ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಬೇರೆ ವಿಶ್ವವಿದ್ಯಾಲಯ ಅಥವಾ ಬೇರೆ ಉನ್ನತ ಶಿಕ್ಷಣ ಸಂಸ್ಥೆಗೆ ಪ್ರವೇಶ ಪಡೆಯಲು ವಲಸೆ ಪ್ರಮಾಣಪತ್ರವು ಅತ್ಯಗತ್ಯ.', NULL, NULL, NULL, true, 'YES', '[]', '[]', 1, '["ದಾಖಲೆಗಳು ಅಗತ್ಯವಿಲ್ಲ,(ಪದವಿ/ಸ್ನಾತಕೋತ್ತರ ಪದವಿ ಪೂರ್ಣಗೊಳಿಸಿರುವುದನ್ನು ತಂತ್ರಾಂಶವು ಸ್ವಯಂ ಪರಿಶೀಲಿಸುವುದು)."]', NULL, NULL, '1503');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('1b735b17-c893-4870-bd1d-d740e8d4b85c', 'FINANCE-DEPARTMENT-5', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Issue of Occasional License [See Rule 3(5)]', 'Public', 0, 'The Issue of Occasional License module enables applicants to apply online for an Occasional License by entering the required application details and selecting the event location on the map. Based on the selected location, the system automatically fetches the corresponding District, Sub-Division, Range, Latitude, and Longitude.', '["PAN Card", "Applicant Aadhaar Card"]', '["Public Regestration required"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಅಪರೂಪದ ಪರವಾನಗಿ ನೀಡಿಕೆ [ನಿಯಮ 3(5) ನೋಡಿ]', 'The Issue of Occasional License module enables applicants to apply online for an Occasional License by entering the required application details and selecting the event location on the map. Based on the selected location, the system automatically fetches the corresponding District, Sub-Division, Range, Latitude, and Longitude.', NULL, 'District Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಸಾಂದರ್ಭಿಕ ಪರವಾನಗಿ ವಿತರಣೆ ಘಟಕವು ಅಗತ್ಯ ಅರ್ಜಿ ವಿವರಗಳನ್ನು ನಮೂದಿಸಿ, ನಕ್ಷೆಯಲ್ಲಿ ಕಾರ್ಯಕ್ರಮದ ಸ್ಥಳವನ್ನು ಆಯ್ಕೆ ಮಾಡುವ ಮೂಲಕ ಅರ್ಜಿದಾರರಿಗೆ ಆನ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಪ್ಯಾನ್ ಕಾರ್ಡ್", "ಅರ್ಜಿದಾರರ ಆಧಾರ್ ಕಾರ್ಡ್"]', NULL, NULL, '1285');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('0eb4c76d-41d9-4c06-8074-9f7df633678e', 'FINANCE-DEPARTMENT-21', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Installation of Molasses Tank', 'Supplier', 15, 'The Installation of Molasses Tank service enables applicants to submit an online application for installing molasses storage tanks through the Excise e-Services portal. The applicant can enter the required application details, specify the number of tanks, provide storage details such as SS/MS tank type and capacity, and upload the necessary supporting documents.After submission, the application is assigned an application number for future reference. The application is then processed through the respective Department Officer logins and moves through the defined approval hierarchy. Officers can review the application, complete the required fields, view file movement details, and submit the application for further processing. At the final approval stage, the authorized officer applies a Digital Signature and submits the application to complete the process.', '["Other Documents", "Approved Blueprint", "Request Letter", "Blueprint Submitted for Approval", "Calibration Certificate of Storage Tank (If Applicable)", "Current Year''s Molasses Licence"]', '["Valid Molasses Licence"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಮೊಲಾಸಿಸ್ ಟ್ಯಾಂಕ್ ಅಳವಡಿಕೆ', 'The Installation of Molasses Tank service enables applicants to submit an online application for installing molasses storage tanks through the Excise e-Services portal. The applicant can enter the required application details, specify the number of tanks, provide storage details such as SS/MS tank type and capacity, and upload the necessary supporting documents.After submission, the application is assigned an application number for future reference. The application is then processed through the respective Department Officer logins and moves through the defined approval hierarchy. Officers can review the application, complete the required fields, view file movement details, and submit the application for further processing. At the final approval stage, the authorized officer applies a Digital Signature and submits the application to complete the process.', NULL, 'State Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಕಾಕಂಬಿ ಟ್ಯಾಂಕ್ ಸ್ಥಾಪನೆ ಸೇವೆಯು ಅಬಕಾರಿ ಇ-ಸೇವೆಗಳ ಪೋರ್ಟಲ್ ಮೂಲಕ ಕಾಕಂಬಿ ಸಂಗ್ರಹಣಾ ಟ್ಯಾಂಕ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಇತರೆ ದಾಖಲೆಗಳು", "ಅನುಮೋದಿತ ನೀಲನಕ್ಷೆ", "ಕೋರಿಕೆ ಪತ್ರ", "ಅನುಮೋದನೆಗಾಗಿ ಸಲ್ಲಿಸಿದ ನೀಲನಕ್ಷೆ", "ಸಂಗ್ರಹಣಾ ಟ್ಯಾಂಕ್"]', NULL, NULL, '1412');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('a278340a-5258-4d44-9db7-a7453bf1b3ca', 'KARNATAKA-SCHOOL-EXA-6', 'bba5409a-66e4-4b2c-a172-f0e00d3829cd', 'II PUC Markscard Verification for Foreign University', 'PUC OFFLINE SERVICES', 0, 'II PUC Markscard Verification for Foreign University', '["UNIVERSITY REQUEST LETTER", "CANDIDATE MARKS CARD COPY"]', '["II PUC PASS"]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'a869b224-41fb-4943-b01a-66927eac9e7e', 'ವಿದೇಶ ವಿಶ್ವವಿದ್ಯಾಲಯ ರವರಿಗೆ ದ್ವಿತೀಯ ಪಿಯುಸಿ ನೈಜ್ಯತೆ ಪ್ರಮಾಣ ಪತ್ರ', 'II PUC MVF', NULL, NULL, 'Offline', NULL, 2000.00, NULL, NULL, NULL, NULL, NULL, false, 'NO', '["ದ್ವಿತೀಯ ಪಿ ಯು ಸಿ ಪರೀಕ್ಷೆ ಉತ್ತೀರ್ಣರಾಗಿರಬೇಕು"]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('cca642cf-81a7-4646-bd5d-f66187d700e7', 'BACKWARD-CLASSES-WEL-59', '59d7c155-e129-436a-b747-c5cb6abba051', 'Swavalambi Sarathi Scheme', 'Subsidy', 0, 'Under Swabalambi Sarathi Scheme, Unemployed Youths Belonging To Backward Classes Will Get A 50% Or Up To A Maximum Of Rs.300000/- Subsidy For The Purchase Of Four-Wheelers Through Bank Loan', '["Caste and family annual income certificate obtained from the concerned Taluk Tahsildar (Mandatory)", "Attested xerox copy of the light motor vehicle driving licence (Mandatory)", "Ration card / voter ID card / Aadhaar card issued by competent authorities as proof of residence (Mandatory)", "Three recent passport size photographs of the applicant (Mandatory)", "Quotation obtained from the supplier of the four-wheeler the applicant intends to purchase (Mandatory)", "Name and address of the bank / financial institution branch from which the loan is sought, with a xerox copy of the pass book (Mandatory)", "Additional documents sought by the bank / financial institution for loan sanction, to be provided to the bank / financial institution (Mandatory)", "Xerox copy of the applicant''s Aadhaar card (Mandatory)"]', '["Applicant must be an unemployed youth belonging to Madiwala caste and its sub castes", "Applicant must hold a light motor vehicle driving licence.", "Family annual income must not exceed Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas.", "Must be a permanent resident of Karnataka State.", "Applicant''s age must be between 21 and 45 years.", "Must not have previously availed benefits under the Corporation''s schemes.", "Must compulsorily hold an account in a bank branch within the area where the applicant resides.", "Only one member per family is eligible.", "Must compulsorily hold an Aadhaar-linked account in a nationalised bank.", "Priority is given to women under this scheme.", "Priority is also given to transgender persons under this scheme.", "The beneficiary must register the vehicle for self-driven taxi (Yellow Board) purpose."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the MLA of the respective constituency"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '7a90ef2b-7e34-4b28-bfc7-47326c44cebe', 'ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ ಯೋಜನೆ', 'Swavalambi Sarathi', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ ಯೋಜನೆಯಡಿ ನಿಗಮವು ಹಿಂದುಳಿದ ವರ್ಗಗಳಿಗೆ ಸೇರಿದ ನಿರುದ್ಯೋಗಿ ಯುವಜನರು ನಾಲ್ಕು ಚಕ್ರ ವಾಹನ ಖರೀದಿಗೆ ಪಡೆಯುವ ಸಾಲಕ್ಕೆ ಶೇ.50 ರಷ್ಟು ಅಥವಾ ಗರಿಷ್ಠ ರೂ.300000/- ಸಹಾಯಧನ.', NULL, NULL, NULL, NULL, NULL, '["ಅರ್ಜಿದಾರರು ಮಡಿವಾಳ ಜಾತಿ ಮತ್ತು ಅದರ ಉಪಜಾತಿಗಳಿಗೆ ಸೇರಿದ ನಿರುದ್ಯೋಗಿ ಯುವಕರಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಲಘು ವಾಹನ ಚಾಲನಾ ಪರವಾನಗಿಯನ್ನು ಹೊಂದಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ವರಮಾನ ಗ್ರಾಮಾಂತರ ಪ್ರದೇಶದವರಿಗೆ ರೂ. 98,000/-ಗಳು ಪಟ್ಟಣ ಪ್ರದೇಶದವರಿಗೆ ರೂ. 1,20,000/-ಗಳನ್ನು ಮೀರಿರಬಾರದು.", "ಕರ್ನಾಟಕ ರಾಜ್ಯದ ಖಾಯಂ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು ಕನಿಷ್ಠ 21 ರಿಂದ 45 ವರ್ಷಗಳ ಮಿತಿಯೊಳಗಿರಬೇಕು.", "ಈ ಹಿಂದೆ ನಿಗಮದ ಯೋಜನೆಗಳಲ್ಲಿ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಈ ಯೋಜನೆಯಲ್ಲಿ ಸವಲತ್ತು ಪಡೆಯ ಬಯಸುವ ಅರ್ಜಿದಾರರು ವಾಸಿಸುತ್ತಿರುವ ವ್ಯಾಪ್ತಿಗೆ ಬರುವ ಬ್ಯಾಂಕ್ ಶಾಖೆಯಲ್ಲಿ ಖಾತೆಯನ್ನು ಕಡ್ಡಾಯವಾಗಿ ಹೊಂದಿರಬೇಕು.", "ಒಂದು ಕುಟುಂಬದ ಒಬ್ಬ ಸದಸ್ಯರಿಗೆ ಮಾತ್ರ ಸೌಲಭ್ಯ ಒದಗಿಸಲಾಗುವುದು.", "ಕಡ್ಡಾಯವಾಗಿ ರಾಷ್ಟ್ರೀಕೃತ ಬ್ಯಾಂಕುಗಳಲ್ಲಿ ಆಧಾರ್ ಸಂಯೋಜನೆಯಾಗಿರುವ ಖಾತೆ ಹೊಂದಿರಬೇಕು.", "ಈ ಯೋಜನೆಯಲ್ಲಿ ಮಹಿಳೆಯರಿಗೆ ಆದ್ಯತೆ ನೀಡುವುದು.", "ಈ ಯೋಜನೆಯಲ್ಲಿ ಮಂಗಳಮುಖಿಯರಿಗೂ ಸಹ ಆದ್ಯತೆ ನೀಡುವುದು.", "ಈ ಯೋಜನೆಯಲ್ಲಿ ಸೌಲಭ್ಯ ಪಡೆಯುವ ಫಲಾನುಭವಿಯು ಸ್ವಯಂ ಟ್ಯಾಕ್ಸಿ ಚಾಲನೆ (Yellow Board) ಉದ್ದೇಶಕ್ಕೆ ವಾಹನವನ್ನು ನೋಂದಾಯಿಸತಕ್ಕದ್ದು."]', '["ಸಂಬಂಧಿತ ಕ್ಷೇತ್ರದ ಶಾಸಕರ ಅಧ್ಯಕ್ಷತೆಯ ಆಯ್ಕೆ ಸಮಿತಿಯ ಮೂಲಕ ಫಲಾನುಭವಿಗಳನ್ನು ಆಯ್ಕೆ ಮಾಡಲಾಗುವುದು."]', 1, '["ಸಂಬಂಧಿಸಿದ ತಾಲ್ಲೂಕು ತಹಶೀಲ್ದಾರರಿಂದ ಪಡೆದ ಜಾತಿ / ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಪ್ರಮಾಣ ಪತ್ರ (ಕಡ್ಡಾಯ)", "ಲಘು ವಾಹನ ಚಾಲನಾ ಪರವಾನಗಿಯ ದೃಢೀಕೃತ ಜೆರಾಕ್ಸ್ ಪ್ರತಿ (ಕಡ್ಡಾಯ)", "ಅರ್ಜಿದಾರರ ವಾಸದ ಪುರಾವೆಗಾಗಿ ಸಕ್ಷಮ ಪ್ರಾಧಿಕಾರಿಗಳು ನೀಡಿದ ಪಡಿತರ ಚೀಟಿ / ಚುನಾವಣಾ ಗುರುತಿನ ಚೀಟಿ / ಆಧಾರ್ ಕಾರ್ಡ್ (ಕಡ್ಡಾಯ)", "ಅರ್ಜಿದಾರರ ಪಾಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('3c26425a-a24e-4dff-9164-0f7d916b3938', 'BACKWARD-CLASSES-WEL-58', '59d7c155-e129-436a-b747-c5cb6abba051', 'Self Employment Direct Loan Scheme', 'Loan with Subsidy', 0, 'Based on the self-employment/economic activity undertaken by persons belonging to backward classes, loans of a minimum of Rs. 1.00 lakh and a maximum of Rs. 2.00 lakhs shall be sanctioned at an annual interest rate of 4%. The scheme includes a subsidy of 20% (Rs. 20,000/-) on loans of Rs. 1.00 lakh, and a subsidy of 15%, subject to a maximum of Rs. 30,000/-, on loan amounts ranging from Rs. 1.00 lakh to Rs. 2.00 lakhs', '["Aadhaar card (Mandatory)", "Caste Certificate (Mandatory)", "Income certificate (Mandatory)"]', '["Applicant must belong to Madiwala caste and sub castes and must produce a caste certificate obtained from the concerned Tahsildar.", "Family annual income must be within Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas.", "Applicant''s age must be above 18 years and within 55 years.", "Should be a permanent resident of Karnataka State.", "Those who have received a subsidy or loan under any other scheme of the Corporation are not eligible for this scheme.", "Only one candidate per family is eligible."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the MLA of the respective constituency"]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '7a90ef2b-7e34-4b28-bfc7-47326c44cebe', 'ಸ್ವಯಂ
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('c1df2bd2-8df5-4a12-9582-acd349330736', 'BACKWARD-CLASSES-WEL-57', '59d7c155-e129-436a-b747-c5cb6abba051', 'Ganga Kalyana Irrigation Scheme', 'Loan with Subsidy', 0, 'Backward class small and marginal farmers should have minimum 1 acre of land in Udupi, Dakshina Kannada, Kodagu, Uttara Kannada, Chikkamagaluru, Shimoga and Hassan districts under individual irrigation scheme. Subsidy of Rs.2.00 lakhs and loan of Rs.50,000/- at an interest rate of 4% per annum for those having at least 2 acres of contiguous land in the remaining districts. Under Collective Irrigation Borewell Scheme 8-15 acres of land owned by at least 3 small and micro farmers 2 borewells at a cost of Rs.4.00 lakhs and for units covering more than 15 acres of land at fixed unit cost of Rs.6.00 lakhs Drill 3 borewells and supply pumpset and equipment and pay deposit for electrification Providing electricity connection and irrigation facility, fully subsidised.', '["Small Farmer & Marginal Farmers Certificate (Mandatory)", "Other Document (Mandatory)"]', '["Applicant must belong to Madiwala caste and its sub castes must be a small or marginal farmer, and must produce a caste certificate obtained from the concerned Tahsildar.", "The existing land must be rain-fed and must not have irrigation facility from any source.", "Under the individual irrigation borewell scheme, the applicant must hold at least 2 acres of land.", "Under the collective irrigation borewell scheme, at least 3 small and marginal farmers must jointly hold 8 acres or more of land.", "Must not have availed a loan or other financial assistance under any scheme of the corporations coming under the Backward Classes Welfare Department.", "Family annual income must be within Rs. 98,000 for rural areas and Rs. 1,20,000 for urban areas.", "Only one candidate per family is eligible.", "Must possess a ration card."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the MLA of the respective constituency"]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '7a90ef2b-7e34-4b28-bfc7-47326c44cebe', 'ಗಂಗಾ ಕಲ್ಯಾಣ ನೀರಾವರಿ ಯೋಜನೆ', 'Ganga Kalyana', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಹಿಂದುಳಿದ ವರ್ಗಗಳ ಸಣ್ಣ ಮತ್ತು ಅತಿಸಣ್ಣ ರೈತರ ವೈಯುಕ್ತಿಕ ನೀರಾವರಿ ಯೋಜನೆಯಲ್ಲಿ ಉಡುಪಿ, ದಕ್ಷಿಣ ಕನ್ನಡ, ಕೊಡಗು, ಉತ್ತರ ಕನ್ನಡ, ಚಿಕ್ಕಮಗಳೂರು, ಶಿವಮೊಗ್ಗ ಮತ್ತು ಹಾಸನ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಕನಿಷ್ಠ 1 ಎಕರೆ ಜಮೀನು ಹೊಂದಿರಬೇಕು. ಉಳಿಕೆ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಒಂದೇ ಸ್ಥಳದಲ್ಲಿ ಹೊಂದಿಕೊಂಡಂತೆ ಇರುವ ಕನಿಷ್ಠ 2 ಎಕರೆ ಜಮೀನು ಹೊಂದಿರುವವರಿಗೆ ರೂ.2.00ಲಕ್ಷಗಳ ಸಹಾಯಧನ (ಸಬ್ಸಿಡಿ) ಹಾಗೂ ವಾರ್ಷಿಕ ಶೇ.4ರ ಬಡ್ಡಿದರದಲ್ಲಿ ರೂ.50,000/-ಗಳ ಸಾಲ. ಸಾಮೂಹಿಕ ನೀರಾವರಿ ಕೊಳವೆಬಾವಿ ಯೋಜನೆಯಡಿ ಕನಿಷ್ಠ 3 ಜನ ಸಣ್ಣ ಮತ್ತು ಅತಿಸಣ್ಣ ರೈತರು ಹೊಂದಿರುವ 8-15 ಎಕರೆ ಜಮೀನಿಗೆ ರೂ.4.00ಲಕ್ಷಗಳ ವೆಚ್ಚದಲ್ಲಿ 2 ಕೊಳವೆಬಾವಿ ಹಾಗೂ 15 ಎಕರೆಗಿಂತ ಹೆಚ್ಚು ಜಮೀನು ಒಳಪಡುವ ಘಟಕಗಳಿಗೆ ನಿಗದಿತ ಘಟಕವೆಚ್ಚ ರೂ.6.00ಲಕ್ಷಗಳ ವೆಚ್ಚದಲ್ಲಿ 3 ಕೊಳವೆಬಾವಿಗಳನ್ನು ಕೊರೆಯಿಸಿ ಪಂಪ್ಸೆಟ್ ಮತ್ತು ಉಪಕರಣಗಳನ್ನು ಸರಬರಾಜು ಮಾಡುವುದು ಹಾಗೂ ವಿದ್ಯುದ್ದೀಕರಣಕ್ಕೆ ಠೇವಣಿ ಪಾವತಿಸಿ ವಿದ್ಯುತ್ ಸಂಪರ್ಕ ಕಲ್ಪಿಸಿ ನೀರಾವರಿ ಸೌಲಭ್ಯ ಒದಗಿಸುವುದು. ಇದು ಪೂರ್ಣ ಅನುದಾನವಾಗಿರುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಅರ್ಜಿದಾರರು ಮಡಿವಾಳ ಜಾತಿ ಹಾಗೂ ಉಪಜಾತಿಗೆ ಸೇರಿದವರಾಗಿರಬೇಕು ಮತ್ತು ಸಮರ್ಥ ಪ್ರಾಧಿಕಾರದಿಂದ ಪಡೆದ ಜಾತಿ ಪ್ರಮಾಣಪತ್ರವನ್ನು ಸಲ್ಲಿಸಬೇಕು..", "ಹಾಲಿ ಜಮೀನುಗಳಿಗೆ ಯಾವುದೇ ಮೂಲದಿಂದ ನೀರಾವರಿ ಸೌಲಭ್ಯ ಹೊಂದಿಲ್ಲದೆ ಮಳೆ ಆಧಾರಿತವಾಗಿ ಖುಷ್ಕಿಯಾಗಿರಬೇಕು.", "ವೈಯಕ್ತಿಕ ನೀರಾವರಿ ಕೊಳವೆ ಬಾವಿ ಯೋಜನೆಯಡಿ ಅರ್ಜಿದಾರರು ಕನಿಷ್ಠ ಎರಡು ಎಕರೆ ಜಮೀನು ಹೊಂದಿರಬೇಕು.", "ಸಾಮೂಹಿಕ ನೀರಾವರಿ ಕೊಳವೆ ಬಾವಿ ಯೋಜನೆಯಡಿ ಕನಿಷ್ಠ 3 ಜನ ಸಣ್ಣ ಮತ್ತು ಅತಿಸಣ್ಣ ರೈತರು ಒಟ್ಟಾಗಿ 8 ಎಕರೆ ಅಥವಾ ಹೆಚ್ಚು ಜಮೀನು ಹೊಂದಿರಬೇಕು.", "ಹಿಂದುಳಿದ ವರ್ಗಗಳ ಇಲಾಖೆ ವ್ಯಾಪ್ತಿಯಲ್ಲಿ ಒಳಪಡುವ ನಿಗಮಗಳಲ್ಲಿ ಬೇರೆ ಯಾವುದೇ ಯೋಜನೆಗಳಲ್ಲಿ ಸಾಲ ಅಥವಾ ಇತರೆ ಆರ್ಥಿಕ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಕುಟುಂಬದ ವಾರ್ಷಿಕ ವರಮಾನ ಗ್ರಾಮಾಂತರ ಪ್ರದೇಶದವರಿಗೆ ರೂ. 98,000/- ಹಾಗೂ ಪಟ್ಟಣ ಪ್ರದೇಶದವರಿಗೆ ರೂ. 1,20,000/-ಗಳ ಮಿತಿಯಲ್ಲಿರಬೇಕು.", "ಒಂದು ಕುಟುಂಬದಲ್ಲಿ ಒಬ್ಬ ಅಭ್ಯರ್ಥಿಗೆ ಮಾತ್ರ ಅವಕಾಶವಿರುತ್ತದೆ.", "ರೇಷನ್ ಕಾರ್ಡ್ ಹೊಂದಿರಬೇಕು."]', '["ಸಂಬಂಧಿತ ಕ್ಷೇತ್ರದ ಶಾಸಕರ ಅಧ್ಯಕ್ಷತೆಯ ಆಯ್ಕೆ ಸಮಿತಿಯ ಮೂಲಕ ಫಲಾನುಭವಿಗಳನ್ನು ಆಯ್ಕೆ ಮಾಡಲಾಗುವುದು."]', 1, '["ಸಣ್ಣ ಮತ್ತು ಅತಿ ಸಣ್ಣ ರೈತ ಪ್ರಮಾಣಪತ್ರ (ಕಡ್ಡಾಯ)", "ಇತರ ದಾಖಲೆ (ಕಡ್ಡಾಯ)"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('ceef96e5-f9ce-4cd4-8161-12932ca22d45', 'BACKWARD-CLASSES-WEL-56', '59d7c155-e129-436a-b747-c5cb6abba051', 'Arivu Educational Loan Scheme (Fresh)', 'Loan', 0, 'Students belonging to Backward Classes, admitted through Common Entrance Test (CET) will be given a loan of Rs.1.00 lakhs per annum for academic development up to a maximum of Rs.4.00 to Rs.5.00 lakhs for the duration of the course at an interest rate of 2% per annum.', '["Aadhar Card (Mandatory)", "Caste certificate (Mandatory)", "Income certificate (Mandatory)", "Parent Approval Letter (Mandatory)", "Colleteral Letter (Mandatory)"]', '["Applicant must belong toMadiwala caste and its sub caste and must produce a caste certificate obtained from the competent authority.", "Must have secured admission to a degree or postgraduate degree course through a common entrance examination (CET / NEET etc.).", "The candidate''s family annual income must be within Rs. 3.50 lakhs.", "Applicant''s age must be between 18 and 30 years."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '7a90ef2b-7e34-4b28-bfc7-47326c44cebe', 'ಅರಿವು ಶೈಕ್ಷಣಿಕ ಸಾಲ ಯೋಜನೆ (ಹೊಸತು)', 'Arivu Fresh Loan', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಸಾಮಾನ್ಯ ಪ್ರವೇಶ ಪರೀಕ್ಷೆ ಮೂಲಕ(ಸಿ.ಇ.ಟಿ.) ಪ್ರವೇಶ ಪಡೆದ ಹಿಂದುಳಿದ ವರ್ಗಗಳ ಸೇರಿದ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ಶೈಕ್ಷಣಿಕಾಭಿವೃದ್ಧಿಗಾಗಿ ಅರಿವು ಶೈಕ್ಷಣಿಕ ಸಾಲ ಯೋಜನೆಯಡಿ ವಾರ್ಷಿಕ ರೂ.1.00ಲಕ್ಷಗಳಂತೆ ಕೋರ್ಸ್ ಅವಧಿಗೆ ಗರಿಷ್ಠ ರೂ.4.00 ರಿಂದ ರೂ.5.00 ಲಕ್ಷಗಳ ವರೆಗೆ ವಾರ್ಷಿಕ ಶೇ.2 ಬಡ್ಡಿದರದಲ್ಲಿ ಸಾಲ ನೀಡಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಅರ್ಜಿದಾರರು ಹಿಂದುಳಿದ ವರ್ಗಗಳ ಪ್ರವರ್ಗ-1, 2ಎ, 3ಎ ಅಥವಾ 3ಬಿಗೆ ಸೇರಿರಬೇಕು ಹಾಗೂ ಸಂಬಂಧಪಟ್ಟ ಪ್ರಾಧಿಕಾರದಿಂದ ಪಡೆದ ಜಾತಿ ಪ್ರಮಾಣ ಪತ್ರವನ್ನು ಹಾಜರುಪಡಿಸಬೇಕು.", "ಸಾಮಾನ್ಯ ಪ್ರವೇಶ ಪರೀಕ್ಷೆ ಮೂಲಕ (ಸಿ.ಇ.ಟಿ. / ನೀಟ್ / ಇತ್ಯಾದಿ) ಪದವಿ / ಸ್ನಾತಕೋತ್ತರ ಪದವಿ ಕೋರ್ಸ್"]', '[]', 1, '["ಆಧಾರ್ ಕಾರ್ಡ್ (ಕಡ್ಡಾಯ)", "ಜಾತಿ ಪ್ರಮಾಣ ಪತ್ರ (ಕಡ್ಡಾಯ)", "ಆದಾಯ ಪ್ರಮಾಣಪತ್ರ (ಕಡ್ಡಾಯ)", "ಪೋಷಕರ ಅನುಮೋದನೆ ಪತ್ರ (ಕಡ್ಡಾಯ)", "ಪೂರಕ ಜಾಮೀನು ಪತ್ರ (ಕಡ್ಡಾಯ)"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('5ebbbf9e-b789-4f97-aabf-a0d01b849da8', 'KARNATAKA-SCHOOL-EXA-5', 'bba5409a-66e4-4b2c-a172-f0e00d3829cd', 'II PUC Markscard Verification for DGCA', 'PUC OFFLINE SERVICES', 0, 'II PUC Markscard Verification for DGCA', '["DGCA REQUEST LETTER", "CANDIDATE MARKS CARD COPY"]', '["II PUC PASS"]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'a869b224-41fb-4943-b01a-66927eac9e7e', 'DGCA ಗಾಗಿ ದ್ವಿತೀಯ ಪಿಯುಸಿ ನೈಜ್ಯತೆ ಪ್ರಮಾಣ ಪತ್ರ', 'II PUC MVD', NULL, NULL, 'Offline', NULL, 2000.00, NULL, NULL, NULL, NULL, NULL, false, 'NO', '["ದ್ವಿತೀಯ ಪಿ ಯು ಸಿ ಪರೀಕ್ಷೆ ಉತ್ತೀರ್ಣರಾಗಿರಬೇಕು"]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('546ab78d-9028-47d8-8ee4-49eebd695984', 'BACKWARD-CLASSES-WEL-55', '59d7c155-e129-436a-b747-c5cb6abba051', 'Arivu Educational Loan Scheme (Renewal)', 'Loan', 0, 'Students belonging to Backward Classes, admitted through Common Entrance Test (CET) will be given a loan of Rs.1.00 lakhs per annum for academic development up to a maximum of Rs.4.00 to Rs.5.00 lakhs for the duration of the course at an interest rate of 2% per annum.', '["Study Certificate (Mandatory)", "Fee Receipt (Mandatory)", "Study Certificate (Mandatory)", "Upload Claim Letter including Sanction Order (Mandatory)", "Previous Year Marksheet (Mandatory)", "Parent Approval Letter (Mandatory)", "Collateral Letter (Mandatory)"]', '["Applicant must belong to Madiwala caste and sub caste must produce a caste certificate obtained from the competent authority.", "Must have secured admission to a degree or postgraduate degree course through a common entrance examination (CET / NEET etc.).", "The candidate''s family annual income must be within Rs. 3.50 lakhs."]', '[]', '["Beneficiaries will be selected through a selection committee chaired by the Chief Executive Officer of the Zilla Panchayat."]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '7a90ef2b-7e34-4b28-bfc7-47326c44cebe', 'ಅರಿವು ಶೈಕ್ಷಣಿಕ ಸಾಲ ಯೋಜನೆ (ನವೀಕರಣ)', 'Arivu Renewal Loan', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಸಾಮಾನ್ಯ ಪ್ರವೇಶ ಪರೀಕ್ಷೆ ಮೂಲಕ(ಸಿ.ಇ.ಟಿ.) ಪ್ರವೇಶ ಪಡೆದ ಹಿಂದುಳಿದ ವರ್ಗಗಳ ಸೇರಿದ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ಶೈಕ್ಷಣಿಕಾಭಿವೃದ್ಧಿಗಾಗಿ ಅರಿವು ಶೈಕ್ಷಣಿಕ ಸಾಲ ನವೀಕರಣ ಯೋಜನೆಯಡಿ ವಾರ್ಷಿಕ ರೂ.1.00ಲಕ್ಷಗಳಂತೆ ಕೋರ್ಸ್ ಅವಧಿಗೆ ಗರಿಷ್ಠ ರೂ.4.00 ರಿಂದ ರೂ.5.00 ಲಕ್ಷಗಳ ವರೆಗೆ ವಾರ್ಷಿಕ ಶೇ.2 ಬಡ್ಡಿದರದಲ್ಲಿ ಸಾಲ ನೀಡಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಅರ್ಜಿದಾರರು ಮಡಿವಾಳ ಜಾತಿ ಹಾಗೂ ಉಪಜಾತಿಗೆ ಸೇರಿದವರಾಗಿರಬೇಕು ಮತ್ತು ಸಮರ್ಥ ಪ್ರಾಧಿಕಾರದಿಂದ ಪಡೆದ ಜಾತಿ ಪ್ರಮಾಣಪತ್ರವನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಸಾಮಾನ್ಯ ಪ್ರವೇಶ ಪರೀಕ್ಷೆ ಮೂಲಕ (ಸಿ.ಇ.ಟಿ. / ನೀಟ್ / ಇತ್ಯಾದಿ) ಪದವಿ / ಸ್ನಾತಕೋತ್ತರ ಪದವಿ ಕೋರ್ಸ್"]', '["ಜಿಲ್ಲಾ ಪಂಚಾಯತ್"]', 1, '["Study Certificate (ಕಡ್ಡಾಯ)", "ಶುಲ್ಕ ರಶೀದಿ (ಕಡ್ಡಾಯ)", "ಅಧ್ಯಯನ ಪ್ರಮಾಣಪತ್ರ (ಕಡ್ಡಾಯ)", "ಮಂಜೂರಾತಿ ಆದೇಶ ಸೇರಿದಂತೆ ಹಕ್ಕು ಪತ್ರವನ್ನುಅಪ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('23b89ae1-f601-495c-879e-aee7369d461e', 'DIRECTORATE-OF-MEDIC-8', '5c2bc993-9659-49cf-a242-03691b9969e6', 'Photo Copiesof 1st Year, 2nd Year and 3rd Year Student’s Answer Scripts', 'General', 2, 'Photo Copies of Student’s Answer Scripts will be issued to students who apply for the Photo Copies.', '["College No Objection Cetificate with Principal Seal and Signature", "Student Request Letter with Valid Reasone"]', '["Individuals who have appeared for the particular examination are eligible for this service."]', '[]', '["Through SEVASINDHU / SEVA ONE"]', NULL, NULL, 'https://www.pmbkarnataka.org/', true, '2026-10-30 16:55:56.458552+00', '740881c4-5f6f-424b-9f42-074c698b1c28', 'ಪ್ರಥಮ ದ್ವಿತೀಯ ಮತ್ತು ತೃತೀಯ ವರ್ಷದ ವಿದ್ಯಾರ್ಥಿಯು ಪರೀಕ್ಷೆ ಬರೆದ ಉತ್ತರ ಪತ್ರಿಕೆಗಳ ಛಾಯಾ ಪ್ರತಿ', NULL, NULL, NULL, NULL, NULL, 300.00, NULL, 'ವಿದ್ಯಾರ್ಥಿಗಳ ಉತ್ತರ ಪತ್ರಿಕೆಗಳ ಛಾಯಾಪ್ರತಿಗಾಗಿ ಅರ್ಜಿ ಸಲ್ಲಿಸುವ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ಉತ್ತರ ಪತ್ರಿಕೆಗಳ ಛಾಯಾಪ್ರತಿಗಳನ್ನು ನೀಡಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ನಿರ್ದಿಷ್ಟ ಪರೀಕ್ಷೆಗೆ ಹಾಜರಾದ ವ್ಯಕ್ತಿಗಳು ಈ ಸೇವೆಗೆ ಅರ್ಹರಾಗಿರುತ್ತಾರೆ."]', '["ಸೇವಾಸಿಂಧು / ಸೇವಾ ಒನ್ ಮೂಲಕ"]', 1, '["ಪ್ರಾಂಶುಪಾಲರ ಮುದ್ರೆ ಮತ್ತು ಸಹಿಯೊಂದಿಗೆ ಕಾಲೇಜಿನ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC)", "ಸೂಕ್ತ ಕಾರಣವನ್ನು ಒಳಗೊಂಡ ವಿದ್ಯಾರ್ಥಿಯ ಮನವಿ ಪತ್ರ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('588e536b-c43a-4bcf-b935-65cb3dcf7068', 'DIRECTORATE-OF-MEDIC-7', '5c2bc993-9659-49cf-a242-03691b9969e6', 'Provisional Certificate', 'General', 15, 'Provisional Certificate will be issued to students who apply for the Provisional Certificate.', '["Student Request Letter / College Request Letter", "SSLC Marks Card Copy"]', '["Para Medical Diploma Passed Students"]', '[]', '["Through SEVASINDHU / SEVA ONE"]', NULL, NULL, 'https://www.pmbkarnataka.org/', true, '2026-10-30 16:55:56.458552+00', '740881c4-5f6f-424b-9f42-074c698b1c28', 'ತಾತ್ಕಾಲಿಕ ಪ್ರಮಾಣ ಪತ್ರ', NULL, NULL, NULL, NULL, NULL, 0.00, NULL, 'ತಾತ್ಕಾಲಿಕ ಪ್ರಮಾಣಪತ್ರಕ್ಕಾಗಿ ಅರ್ಜಿ ಸಲ್ಲಿಸುವ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ತಾತ್ಕಾಲಿಕ ಪ್ರಮಾಣಪತ್ರವನ್ನು ನೀಡಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಪ್ಯಾರಾಮೆಡಿಕಲ್ ಡಿಪ್ಲೊಮಾ ಉತ್ತೀರ್ಣರಾದ ವಿದ್ಯಾರ್ಥಿಗಳು"]', '["ಸೇವಾಸಿಂಧು / ಸೇವಾ ಒನ್ ಮೂಲಕ"]', 1, '["ವಿದ್ಯಾರ್ಥಿಯ ಮನವಿ ಪತ್ರ / ಕಾಲೇಜಿನ ಮನವಿ ಪತ್ರ", "ಎಸ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('d29cd24f-3333-4ed9-a8ef-41471f251d95', 'DIRECTORATE-OF-MEDIC-6', '5c2bc993-9659-49cf-a242-03691b9969e6', 'Good Standing Certificate', 'General', 10, 'Good Standing Certificate will be issued to students who apply for the Good Standing Certificate.', '["1st, 2nd and Final Year Marks Card Copy", "Diploma Certificate Copy", "Student Request Letter (If student want Attestation on their documents copy)", "or", "Company Request Letter (If Campany want to know about student genuineness of Documents)"]', '["Para Medical Diploma Passed Students"]', '[]', '["Through SEVASINDHU / SEVA ONE"]', NULL, NULL, 'https://www.pmbkarnataka.org/', true, '2026-10-30 16:55:56.458552+00', '740881c4-5f6f-424b-9f42-074c698b1c28', 'ಗುಡ್ ಸ್ಟ್ಯಾಂಡಿಂಗ್ ಪ್ರಮಾಣ ಪತ್ರ', NULL, NULL, NULL, NULL, NULL, 1000.00, NULL, 'ಗುಡ್ ಸ್ಟ್ಯಾಂಡಿಂಗ್ ಪ್ರಮಾಣಪತ್ರಕ್ಕಾಗಿ ಅರ್ಜಿ ಸಲ್ಲಿಸುವ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ಗುಡ್ ಸ್ಟ್ಯಾಂಡಿಂಗ್ ಪ್ರಮಾಣಪತ್ರವನ್ನು ನೀಡಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಪ್ಯಾರಾಮೆಡಿಕಲ್ ಡಿಪ್ಲೊಮಾ ಉತ್ತೀರ್ಣರಾದ ವಿದ್ಯಾರ್ಥಿಗಳು"]', '["ಸೇವಾಸಿಂಧು / ಸೇವಾ ಒನ್ ಮೂಲಕ"]', 1, '["1ನೇ, 2ನೇ ಹಾಗೂ ಅಂತಿಮ ವರ್ಷದ ಅಂಕಪಟ್ಟಿಗಳ ಪ್ರತಿ", "ಡಿಪ್ಲೊಮಾ ಪ್ರಮಾಣಪತ್ರದ ಪ್ರತಿ", "ವಿದ್ಯಾರ್ಥಿಯ ಮನವಿ ಪತ್ರ (ವಿದ್ಯಾರ್ಥಿಯು ತನ್ನ ದಾಖಲೆಗಳ ಪ್ರತಿಗಳಿಗೆ ದೃಢೀಕರಣ/ಅಟೆಸ್ಟೇಶನ್ ಬಯಸಿದಲ್ಲಿ)", "ಅಥವಾ", "ಕಂಪನಿಯ ಮನವಿ ಪತ್ರ (ವಿದ್ಯಾರ್ಥಿಯ ದಾಖಲೆಗಳ ನೈಜತೆ/ಸತ್ಯಾಸತ್ಯತೆಯನ್ನು ತಿಳಿದುಕೊಳ್ಳಲು ಕಂಪನಿಗೆ ಅಗತ್ಯವಿದ್ದಲ್ಲಿ)"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('c561aaa4-d573-4be4-989b-a79a90d24e09', 'KARNATAKA-SCHOOL-EXA-4', 'bba5409a-66e4-4b2c-a172-f0e00d3829cd', 'II PUC Verification of Markscard (Excluding GOI, GOK and Public Sector Departments)', 'PUC ONLINE SERVICES', 0, 'II PUC Verification of Markscard (Excluding GOI, GOK and Public Sector Departments)', '["DEPARTMENT/ APPOINTING AUTHORITY LETTER", "CANDIDATE MARKS CARD COPY"]', '["II PUC PASS"]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', 'a869b224-41fb-4943-b01a-66927eac9e7e', 'ದ್ವಿತೀಯ ಪಿಯುಸಿ ನೈಜ್ಯತೆ ಪ್ರಮಾಣ ಪತ್ರ (ಭಾರತ ಸರ್ಕಾರ, ಕರ್ನಾಟಕ ಸರ್ಕಾರ ಹಾಗೂ ಸಾರ್ವಜನಿಕ ಕ್ಷೇತ್ರದ ಇಲಾಖೆಗಳನ್ನು ಹೊರತುಪಡಿಸಿ)', 'II PUC MV', NULL, NULL, 'Online', NULL, 300.00, NULL, NULL, NULL, NULL, NULL, false, 'NO', '["ದ್ವಿತೀಯ ಪಿ ಯು ಸಿ ಪರೀಕ್ಷೆ ಉತ್ತೀರ್ಣರಾಗಿರಬೇಕು"]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('192a8429-c478-4112-8912-beb250f4bb09', 'DIRECTORATE-OF-MEDIC-5', '5c2bc993-9659-49cf-a242-03691b9969e6', 'Verification Certificate/HRD Attestation', 'General', 10, 'Verification Certificate will be issued to students who apply for the Verification Certificate.', '["1st, 2nd and Final Year Marks Card Copy", "Diploma Certificate Copy", "Student Request Letter (If student want Attestation on their documents copy)", "or", "Company Request Letter (If Campany want to know about student genuineness of Documents)"]', '["Para Medical Diploma Passed Students"]', '[]', '["Through SEVASINDHU / SEVA ONE"]', NULL, NULL, 'https://www.pmbkarnataka.org/', true, '2026-10-30 16:55:56.458552+00', '740881c4-5f6f-424b-9f42-074c698b1c28', 'ನೈಜತೆ ಪ್ರಮಾಣ ಪತ್ರ', NULL, NULL, NULL, NULL, NULL, 1000.00, NULL, 'ಪರಿಶೀಲನಾ ಪ್ರಮಾಣಪತ್ರಕ್ಕಾಗಿ ಅರ್ಜಿ ಸಲ್ಲಿಸುವ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ಪರಿಶೀಲನಾ ಪ್ರಮಾಣಪತ್ರವನ್ನು ನೀಡಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಪ್ಯಾರಾಮೆಡಿಕಲ್ ಡಿಪ್ಲೊಮಾ ಉತ್ತೀರ್ಣರಾದ ವಿದ್ಯಾರ್ಥಿಗಳು"]', '["ಸೇವಾಸಿಂಧು / ಸೇವಾ ಒನ್ ಮೂಲಕ"]', 1, '["1ನೇ, 2ನೇ ಹಾಗೂ ಅಂತಿಮ ವರ್ಷದ ಅಂಕಪಟ್ಟಿಗಳ ಪ್ರತಿ", "ಡಿಪ್ಲೊಮಾ ಪ್ರಮಾಣಪತ್ರದ ಪ್ರತಿ", "ವಿದ್ಯಾರ್ಥಿಯ ಮನವಿ ಪತ್ರ (ವಿದ್ಯಾರ್ಥಿಯು ತನ್ನ ದಾಖಲೆಗಳ ಪ್ರತಿಗಳಿಗೆ ದೃಢೀಕರಣ/ಅಟೆಸ್ಟೇಶನ್ ಬಯಸಿದಲ್ಲಿ)", "ಅಥವಾ", "ಕಂಪನಿಯ ಮನವಿ ಪತ್ರ (ವಿದ್ಯಾರ್ಥಿಯ ದಾಖಲೆಗಳ ನೈಜತೆ/ಸತ್ಯಾಸತ್ಯತೆಯನ್ನು ತಿಳಿದುಕೊಳ್ಳಲು ಕಂಪನಿಗೆ ಅಗತ್ಯವಿದ್ದಲ್ಲಿ)"]', NULL, NULL, NULL);
