INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('0b414833-5708-4a95-a457-6c34e5411c13', 'SOCIAL-WELFARE-DEPAR-36', '81b60538-519f-4131-bd38-c390f2d882d6', 'Dr. Babu Jagjeevan Ram Two Wheeler Cargo Transport Scheme', 'Loan with Subsidy', 0, 'In 2022-23, a scheme will be implemented to promote self-employment and increase self-confidence among Scheduled Castes and Scheduled Tribes youth. This scheme is designed to facilitate e-commerce businesses and create employment in other services. Under this scheme, beneficiaries who purchase electric or other two-wheeler/three-wheeler goods transport vehicles will receive a subsidy of Rs. 50,000 and a loan of Rs. 20,000.', '["Applicant Aadhar Card (Mandatory)", "Applicant Photo (Mandatory)", "Applicant Voter ID (Mandatory)", "Applicant Ration Card (Mandatory)", "Caste & Income Certificate issued by competent authority (Mandatory)", "Must Possess Relevant Vehicle Driving License (Mandatory)", "Must Possess Relevant Vehicle Quotation (Mandatory)", "In E-Commerce, submit proof of employment or a self-affidavit for selling goods (Mandatory)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)", "The applicant must declare they have not received prior assistance from the Corporation (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Applicant Age should be between 21 to 60 years.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '00098d28-e660-4ddf-a9c1-e1aee150c3ed', 'ಡಾ. ಬಾಬು ಜಗಜೀವನ ರಾಂ ದ್ವಿಚಕ್ರ ವಾಹನ ಸರಕು ಸಾಗಾಣಿಕೆ ಯೋಜನೆ', 'Two Wheeler Cargo Transport Scheme', NULL, NULL, 'Online', NULL, NULL, NULL, '2022-23 ನೇ ಸಾಲಿನಲ್ಲಿ ಪರಿಶಿಷ್ಟ ಜಾತಿ ಮತ್ತು ವರಿಶಿಷ್ಟ ಪಂಗಡದ ಯುವಕರಲ್ಲಿ ಸ್ವಯಂ ಉದ್ಯೋಗವನ್ನು ಉತ್ತೇಜಿಸಲು ಮತ್ತು ಆತ್ಮವಿಶ್ವಾಸವನ್ನು ಹೆಚ್ಚಿಸಲು , ಇ-ಕಾಮರ್ಸ್ ವ್ಯವಹಾರಗಳನ್ನು ಸುಲಭಗೊಳಿಸಲು ಮತ್ತು ಇತರ ಸೇವೆಗಳಲ್ಲಿ ಉದ್ಯೋಗವನ್ನು ಸೃಷ್ಟಿಸಲು ಈ ಯೋಜನೆಯನ್ನು ವಿನ್ಯಾಸಗೊಳಿಸಲಾಗಿದೆ. ಈ ಯೋಜನೆಯಡಿಯಲ್ಲಿ, ವಿದ್ಯುತ್ ಅಥವಾ ಇತರೆ ಎರಡು/ಮೂರು ಚಕ್ರದ ಸರಕು ಸಾಗಣೆ ವಾಹನಗಳನ್ನು ಖರೀದಿಸುವ ಫಲಾನುಭವಿಗಳಿಗೆ ರೂ. 50,000 ಸಹಾಯಧನ ಹಾಗೂ ರೂ. 20,000 ಸಾಲವನ್ನು ನೀಡಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 60 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('37341a1f-a0ab-4ad0-9562-497ef9a2ee56', 'SOCIAL-WELFARE-DEPAR-35', '81b60538-519f-4131-bd38-c390f2d882d6', 'Swavalambi Sarathi Scheme', 'Subsidy', 0, 'Under Swalambi Sarathi Yojana, the scheme will be implemented in collaboration with banks by sanctioning 75% subsidy or maximum Rs.4.00 lakhs for goods transport/taxi (yellow board) vehicles.', '["Applicant Aadhar Cards (Mandatory)", "Applicant Ration Card (Mandatory)", "Applicant Voter ID (Mandatory)", "Caste & Income Certificate issued by competent authority (Mandatory)", "Vehicle Quotation (Mandatory)", "The applicant must declare they have not received prior assistance from the Corporation (Mandatory)", "Applicant Photo (Mandatory)", "Bank Pass Book (with Cover Page) (Mandatory)", "Vehicle Driving License(DL) (Mandatory)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 56 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '00098d28-e660-4ddf-a9c1-e1aee150c3ed', 'ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ ಯೋಜನೆ', 'Swavalambi Sarathi /ISB 3.5', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಸ್ವಾವಲಂಬಿ ಸಾರಥಿ ಯೋಜನೆಯಡಿ ಸರಕು ಸಾಗಾಣಿಕೆ/ಟ್ಯಾಕ್ಸಿ (ಹಳದಿ ಬೋರ್ಡ್) ವಾಹನಗಳಿಗೆ ಘಟಕ ವೆಚ್ಚದ ಶೇ.75ರಷ್ಟು ಅಥವಾ ಗರಿಷ್ಟ ರೂ.4.00 ಲಕ್ಷಗಳವರೆಗೆ ಸಹಾಯಧನವನ್ನು ಮಂಜೂರು ಮಾಡಿ ಬ್ಯಾಂಕ್', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 56 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('54558480-6ee4-4de0-ab7d-87ab2ab23376', 'SOCIAL-WELFARE-DEPAR-34', '81b60538-519f-4131-bd38-c390f2d882d6', 'Micro Credit Prerana Scheme 5 Lakh', 'Loan with Subsidy', 0, 'Loans and grants will be extended to support various economic activities undertaken by Self-Help Groups of Scheduled Caste women. Each female member will receive Rs. 25,000, comprising a subsidy of Rs. 15,000 and a loan of Rs. 10,000. Self-help groups with a minimum of 10 women members and a unit cost of Rs. 2.50 lakhs will be eligible for loan assistance as per regulations. The loan must be repaid to the Corporation in 36 equal installments with a 4% interest rate', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '00098d28-e660-4ddf-a9c1-e1aee150c3ed', 'ಪ್ರೇರಣಾ (ಮೈಕ್ರೋ ಕ್ರೆಡಿಟ್) ಯೋಜನೆ 5 ಲಕ್ಷ', 'Prerana (Micro Credit) 5 Lakh', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯದ ಮಹಿಳಾ ಸ್ವಸಹಾಯ ಸಂಘಗಳ ವಿವಿಧ ಉದ್ದೇಶದ ಆರ್ಥಿಕ ಚಟುವಟಿಕೆಗಳಿಗೆ ಸಾಲ ಮತ್ತು ಸಹಾಯಧನ ನೀಡಲಾಗುವುದು. ಪ್ರತಿ ಮಹಿಳಾ ಸದಸ್ಯರಿಗೆ ರೂ 25000. ಇದರಲ್ಲಿ ಸಹಾಯಧನ ರೂ15000 ಹಾಗೂ ಸಾಲ ರೂ10000 ಗಳಾಗಿರುತ್ತದೆ. ಕನಿಷ್ಠ 10 ಜನ ಮಹಿಳಾ ಸದಸ್ಯರು ಇರುವ ಸ್ವ-ಸಹಾಯ ಗುಂಪಿಗೆ ಘಟಕ ವೆಚ್ಛ ರೂ 2.50 ಲಕ್ಷಗಳಂತೆ ನಿಯಮಾನುಸಾರ ಅರ್ಹರಿರುವ ಗುಂಪಿಗೆ ಸಾಲ ಸೌಲಭ್ಯ ಒದಗಿಸಲಾಗುವುದು. ಸದರಿ ಸಾಲದ ಹಣವನ್ನು 36 ಸಮ ಕಂತುಗಳಲ್ಲಿ ಶೇ 4 ರ ಬಡ್ಡಿ ದರದಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಮರುಪಾವತಿ ಮಾಡ ಬೇಕಾಗಿರುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('f0b73b37-2c3b-48f2-a07a-e73751ff06d9', 'SOCIAL-WELFARE-DEPAR-33', '81b60538-519f-4131-bd38-c390f2d882d6', 'Micro Credit Prerana Scheme', 'Loan with Subsidy', 0, 'Loans and grants will be extended to support various economic activities undertaken by Self-Help Groups of Scheduled Caste women. Each female member will receive Rs. 25,000, comprising a subsidy of Rs. 15,000 and a loan of Rs. 10,000. Self-help groups with a minimum of 10 women members and a unit cost of Rs. 2.50 lakhs will be eligible for loan assistance as per regulations. The loan must be repaid to the Corporation in 36 equal installments with a 4% interest rate', '["Applicant''s Aadhar Cards (Mandatory)", "Applicant''s Ration Card (Mandatory)", "Applicant''s Voter ID (Mandatory)", "Caste & Income Certificate issued by competent authority (Mandatory)", "The applicant must declare they have not received prior assistance from the Corporation (Mandatory)", "Applicant''s Photo (Mandatory)", "Bank Pass Book (with Cover Page) (Mandatory)", "Should Have Valid Association Registration Copy (Mandatory)", "Copy of at least 3 months'' worth of recent association meeting minutes (Mandatory)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 60 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability.", "Registered Copy of Self Help Group.", "Out of the 60% Scheduled Caste members of the association, 40% of the members should belong to the sub-castes belonging to the corporation.", "Members of the SHG should have ration card."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '00098d28-e660-4ddf-a9c1-e1aee150c3ed', 'ಪ್ರೇರಣಾ (ಮೈಕ್ರೋ ಕ್ರೆಡಿಟ್) ಯೋಜನೆ', 'Prerana (Micro Credit)', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯದ ಮಹಿಳಾ ಸ್ವಸಹಾಯ ಸಂಘಗಳ ವಿವಿಧ ಉದ್ದೇಶದ ಆರ್ಥಿಕ ಚಟುವಟಿಕೆಗಳಿಗೆ ಸಾಲ ಮತ್ತು ಸಹಾಯಧನ ನೀಡಲಾಗುವುದು. ಪ್ರತಿ ಮಹಿಳಾ ಸದಸ್ಯರಿಗೆ ರೂ.25000. ಇದರಲ್ಲಿ ಸಹಾಯಧನ ರೂ.15000 ಹಾಗೂ ಸಾಲ ರೂ.10000 ಗಳಾಗಿರುತ್ತದೆ. ಕನಿಷ್ಠ 10 ಜನ ಮಹಿಳಾ ಸದಸ್ಯರು ಇರುವ ಸ್ವ-ಸಹಾಯ ಗುಂಪಿಗೆ ಘಟಕ ವೆಚ್ಛ ರೂ. 2.50 ಲಕ್ಷಗಳಂತೆ ನಿಯಮಾನುಸಾರ ಅರ್ಹರಿರುವ ಗುಂಪಿಗೆ ಸಾಲ ಸೌಲಭ್ಯ ಒದಗಿಸಲಾಗುವುದು. ಸದರಿ ಸಾಲದ ಹಣವನ್ನು 36 ಸಮ ಕಂತುಗಳಲ್ಲಿ ಶೇ 4 ರ ಬಡ್ಡಿ ದರದಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಮರುಪಾವತಿ ಮಾಡಬೇಕಾಗಿರುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 60 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು.", "ಚಾಲ್ತಿಯಲ್ಲಿರುವ ಸಂಘದ ನೊಂದಣಿ ಪತ್ರ.", "ಸಂಘದ ಶೇ 60 ರ ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸದಸ್ಯರುಗಳ ಪೈಕಿ ಶೇ 40 ರಷ್ಟು ಸದಸ್ಯರು ನಿಗಮಕ್ಕೆ ಸೇರಿದ ಉಪ ಜಾತಿಯವರಾಗಿರಬೇಕು.", "ಸಂಘದ ಸದಸ್ಯರು ಪಡಿತರ ಚೀಟಿಯನ್ನು ಹೊಂದಿರಬೇಕು."]', '[]', 1, '["ಎಲ್ಲಾ ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('b5335720-c093-47e1-ad27-78c31d441054', 'SOCIAL-WELFARE-DEPAR-32', '81b60538-519f-4131-bd38-c390f2d882d6', 'Self Employment Direct Loan Scheme', 'Loan with Subsidy', 0, 'Scheduled caste individuals can engage in small-scale economic activities such as selling fruits, vegetables, fish, and rearing livestock like cows, sheep, pigs, or rabbits. The unit cost for these endeavors is Rs.1.00 lakh, with financial support comprising a Rs.50,000 subsidy and a Rs.50,000 loan. Beneficiaries are required to repay the loan to the corporation in 36 equal installments, with an interest rate of 4%.', '["Applicant Aadhar Card (Optional)", "Ration card (Optional)", "Aadhar linked PassBook Front Page Photo (Optional)", "Caste & Income Certificate issued by competent authority (Optional)", "The applicant must declare they have not received prior assistance from the Corporation (Optional)", "Passport size Photo (Optional)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)", "Project Report / Quotation (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 60 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '00098d28-e660-4ddf-a9c1-e1aee150c3ed', 'ಸ್ವಯಂ ಉದ್ಯೋಗ (ನೇರಸಾಲ) ಯೋಜನೆ', 'Self Employment Scheme', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಪರಿಶಿಷ್ಟ ಜಾತಿ ನಿರುದ್ಯೋಗಿಗಳಿಗೆ ಹಣ್ಣು,, ತರಕಾರಿ, ಮೀನು, ಮಾಂಸ ಮಾರಾಟ, ಹಸು/ಕುರಿ/ಹಂದಿ/ಮೊಲ ಸಾಕಾಣಿಕೆ ಇತ್ಯಾದಿ ಕಿರು ಆರ್ಥಿಕ ಚಟುವಟಿಕೆಗಳಿಗೆ ಘಟಕ ವೆಚ್ಚ ರೂ.1.00ಲಕ್ಷಗಳಾಗಿದ್ದು, ಈ ಪೈಕಿ ರೂ.50,000/- ಸಹಾಯಧನ ಹಾಗೂ ರೂ.50,000/- ಸಾಲದ ರೂಪದಲ್ಲಿ ಆರ್ಥಿಕ ನೆರವನ್ನು ಕಲ್ಪಿಸಲಾಗುತ್ತಿದೆ. ಸಾಲದ ಮೊತ್ತವನ್ನು 36 ಸಮಾನ ಕಂತುಗಳಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಶೇ.4ರ ಬಡ್ಡಿದರದೊಂದಿಗೆ ಮರುಪಾವತಿಸಬೇಕಾಗಿರುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 60 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('b2f61a49-64c7-42b2-84e7-8b8b9ed7b592', 'SOCIAL-WELFARE-DEPAR-31', '81b60538-519f-4131-bd38-c390f2d882d6', 'ISB - Fast Food Truck Trailer/Mobile Food Kitchen - Rs. 4.00 Lakhs', 'Subsidy', 0, 'Under the ISB (Industrial Service Business) scheme, this fully subsidized Fast Food Truck Trailer/Mobile Kitchen is a mobile food service unit worth ₹4.00 lakhs.', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '00098d28-e660-4ddf-a9c1-e1aee150c3ed', 'ಐಎಸ್ಬಿ - ಫಾಸ್ಟ್ ಫುಡ್ ಟ್ರಕ್ ಟ್ರೇಲರ್/ಮೊಬೈಲ್ ಫುಡ್ ಕಿಚನ್ - ₹4.00 ಲಕ್ಷಗಳು', 'Fast Food Truck Trailer/Mobile Food Kitchen - 4 Lakh', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಐಎಸ್ಬಿ (ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ) ಯೋಜನೆಯ ಅಡಿಯಲ್ಲಿ ಸಂಪೂರ್ಣ ಸಹಾಯಧನದೊಂದಿಗೆ ನೀಡಲಾಗುವ ಈ ಫಾಸ್ಟ್ ಫುಡ್ ಟ್ರಕ್ ಟ್ರೇಲರ್/ಮೊಬೈಲ್ ಕಿಚನ್ ₹4.00 ಲಕ್ಷ ಮೌಲ್ಯದ ಚಲಿಸುವ ಆಹಾರ ಸೇವಾ ಘಟಕವಾಗಿದೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('e7662c55-f989-4b43-9ce6-f1091f63b42c', 'SOCIAL-WELFARE-DEPAR-30', '81b60538-519f-4131-bd38-c390f2d882d6', 'Land Purchase scheme', 'Loan with Subsidy', 0, 'Under the Land-Ownership Scheme, land will be purchased from non-Scheduled Caste/Scheduled Tribe landowners. Landless women agricultural labourers belonging to the Scheduled Caste community will receive Rs. 20 lakh for 27 districts and Rs. 25 lakh for 4 districts (Bangalore City, Bangalore Rural, Chikkaballapur, and Ramanagara), with 50% subsidy and 50% loan. Khushki/Tari/Bagaitu land within a maximum distance of 10 km from the beneficiary''s residence will be provided. The loan must be repaid to the Corporation in 10 annual equal installments at an interest rate of 6% per annum.', '["Beneficiary Aadhaar Card As Residential Proof (Mandatory)", "Beneficiary Caste Certificate Issued by the competent authority (Mandatory)", "Beneficiary Income Certificate Issued by the competent authority (Mandatory)", "Letter of Landless Agricultural labourers (from Tahsildar) (Mandatory)", "Beneficiary Ration Card (Mandatory)", "Land Owners Cover letter for sale of land (To be notarized and submitted on Stamp paper.) (Mandatory)", "land owner Family Tree (To be verified and submitted by village accountants.) (Mandatory)", "Letter of No Objection (NOC) from Family Members (should be notarized and submitted.) (Mandatory)", "Latest pahani and mutation copy (Mandatory)", "Land Owners Last 13 years E.C. (Encumbrance Certificate should be submitted.) (Mandatory)", "Beneficiary Photo (Mandatory)"]', '["Applicants must belong to scheduled castes and its related community.", "The applicant must be a land less agriculture labour family.", "Self-declaration certificate must be submitted in case of caste certificate.", "Should be resident of Karnataka state.", "The applicant and no member of his family should not be in employment in any Govt./Semi Govt organization.", "The beneficiaries eligible to avail of facilities under the land ownership scheme must be landless women agricultural laborers.", "Additionally, the landowners selling the land should not belong to Scheduled Castes and Scheduled Tribes.", "The land to be purchased is a maximum of 10 km from the place where the beneficiary lives. m. should be within range."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '00098d28-e660-4ddf-a9c1-e1aee150c3ed', 'ಭೂ-ಒಡೆತನ ಯೋಜನೆ', 'Land Purchase scheme', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಭೂ -ಒಡೆತನ ಯೋಜನೆಯಡಿ ಪರಿಶಿಷ್ಟ ಜಾತಿ / ಪರಿಶಿಷ್ಟ ಪಂಗಡಕ್ಕೆ ಸೇರದ ಭೂ ಮಾಲೀಕರಿಂದ ಜಮೀನನ್ನು ಖರೀದಿಸಿ, ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸಮುದಾಯದ ಭೂ ರಹಿತ ಮಹಿಳಾ ಕೃಷಿ ಕಾರ್ಮಿಕರಿಗೆ 27 ಜಿಲ್ಲೆಗಳಿಗೆ ರೂ 20 ಲಕ್ಷ ಮತ್ತು 4 ಜಿಲ್ಲೆಗಳಿಗೆ (ಬೆಂಗಳೂರು ನಗರ, ಬೆಂಗಳೂರು ಗ್ರಾಮಾಂತರ, ಚಿಕ್ಕಬಳ್ಳಾಪುರ ಮತ್ತು ರಾಮನಗರ) ರೂ 25 ಲಕ್ಷಗಳಿಗೆ (ಸಹಾಯಧನ ಶೇ 50 ಮತ್ತು ಸಾಲ ಶೇ 50 ರಷ್ಟು) ಖುಷ್ಕಿ/ತರಿ/ಬಾಗಾಯ್ತು ಜಮೀನನ್ನು ಫಲಾನುಭವಿಯು ವಾಸಿಸುತ್ತಿರುವ ಸ್ಥಳದಿಂದ ಗರಿಷ್ಠ 10 ಕಿ. ಮೀ. ವ್ಯಾಪ್ತಿಯೊಳಗೆ ಖರೀದಿಸಿ, ಭೂರಹಿತ ಮಹಿಳಾ ಕೃಷಿ ಕಾರ್ಮಿಕರಿಗೆ ಒದಗಿಸಲಾಗುವುದು ಮತ್ತು ಸಾಲದ ಮೊತ್ತವನ್ನು 10 ವಾರ್ಷಿಕ ಸಮ ಕಂತುಗಳಲ್ಲಿ ವಾರ್ಷಿಕ ಶೇ 6 ರ ಬಡ್ಡಿ ದರದಲ್ಲಿ ನಿಗಮಕ್ಕೆ ಮರುಪಾವತಿ ಮಾಡ ಬೇಕಾಗಿರುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '["ಅರ್ಜಿದಾರರು ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸಂಬಂಧಿತ ಜಾತಿಗಳಿಗೆ ಸೇರಿದವರಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಭೂ ರಹಿತ ಕೃಷಿ ಕಾರ್ಮಿಕ ಕುಟುಂಬದವರಾಗಿರಬೇಕು.", "ಜಾತಿ ಪ್ರಮಾಣ ಪತ್ರವನ್ನು ಸಲ್ಲಿಸಿದಲ್ಲಿ ಕಡ್ಡಾಯವಾಗಿ ಸ್ವಯಂ ಘೋಷಣೆ ಪ್ರಮಾಣ ಪತ್ರವನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು/ ಕುಟುಂಬದ ಅವಲಂಬಿತ ಯಾವುದೇ ಸದಸ್ಯರು ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ನೌಕರಿಯಲ್ಲಿರಬಾರದು.", "ಭೂಒಡೆತನ ಯೋಜನೆಯಡಿ ಸೌಲಭ್ಯ ಪಡೆಯಲು ಫಲಾಪೇಕ್ಷಿಯು ಭೂರಹಿತ ಮಹಿಳಾ ಕೃಷಿ ಕಾರ್ಮಿಕರಾಗಿರಬೇಕು.", "ಜಮೀನು ಮಾರಾಟ ಮಾಡುವ ಭೂಮಾಲೀಕರು ಪರಿಶಿಷ್ಟಜಾತಿ ಮತ್ತು ಪರಿಶಿಷ್ಟ ಪಂಗಡಕ್ಕೆ ಸೇರಿರಬಾರದು.", "ಖರೀದಿಸುವ ಜಮೀನು ಫಲಾನುಭವಿಯು ವಾಸಿಸುತ್ತಿರುವ ಸ್ಥಳದಿಂದ ಗರಿಷ್ಠ 10 ಕಿ. ಮೀ. ವ್ಯಾಪ್ತಿಯೊಳಗೆ ಇರಬೇಕು."]', '[]', 1, '["ಫಲಾನುಭವಿಯ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('7e32eb66-945c-49c2-9fd9-ea74b8bbc09f', 'SOCIAL-WELFARE-DEPAR-29', '81b60538-519f-4131-bd38-c390f2d882d6', 'Sheep/Goat Farming Scheme', 'Loan with Subsidy', 0, 'Under the Sheep Farming Scheme, beneficiaries receive a loan of ₹50,000 along with a subsidy of ₹50,000 to support sustainable sheep rearing and income generation', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '00098d28-e660-4ddf-a9c1-e1aee150c3ed', 'ಕುರಿ/ಮೇಖೆ ಸಾಕಾಣಿಕೆ ಯೋಜನೆ', 'Sheep/Goat Farming Scheme', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಈ ಯೋಜನೆಯ ಅಡಿಯಲ್ಲಿ ಫಲಾನುಭವಿಗಳಿಗೆ ₹50,000 ರ ঋಣ ಮತ್ತು ₹50,000 ರ ಸಹಾಯಧನವನ್ನು ಒದಗಿಸಲಾಗುತ್ತದೆ, ಇದು ಸ್ಥಿರ ಕುರಿ ಸಾಕಾಣಿಕೆ ಮತ್ತು ಆದಾಯ ಉತ್ಪಾದನೆಗೆ ನೆರವಾಗುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('0f237acb-fec1-47cb-b45b-77d4238f903e', 'SOCIAL-WELFARE-DEPAR-28', '81b60538-519f-4131-bd38-c390f2d882d6', 'Industrial Service Business - ISB (in association with Bank) Maximum Rs. 2 lakh subsidy', 'Subsidy', 0, 'Industrial Service Business (in collaboration with the Bank) development scheme, assistance from the Corporation to start self-employment units for unemployed youths and women of the Scheduled Caste community in small scale industry, service sector and business sectors and the rest is loan from the bank. Subsidy of 70% of the unit cost or a maximum of Rs 2 lakh', '["Applicant''s Aadhar Cards (Optional)", "Ration Card (Mandatory)", "Aadhar linked PassBook Front Page Photo (Mandatory)", "Caste & Income Certificate issued by competent authority (Optional)", "Project Report / Quotation (Optional)", "The applicant must declare they have not received prior assistance from the Corporation (Optional)", "Applicant Photo (Mandatory)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 56 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '00098d28-e660-4ddf-a9c1-e1aee150c3ed', 'ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್', 'Industrial Service Business 2.0', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 56 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('e2d87e54-9fcc-45fc-84e3-141ce2541841', 'SOCIAL-WELFARE-DEPAR-27', '81b60538-519f-4131-bd38-c390f2d882d6', 'Industrial Service Business - ISB (in association with Bank) Maximum Rs. 1 lakh subsidy', 'Subsidy', 0, 'Industrial Service Busines (in collaboration with the Bank) development scheme, assistance from the Corporation to start self-employment units for unemployed youths and women of the Scheduled Caste community in small scale industry, service sector and business sectors and the rest is loan from the bank. Subsidy of 20% of the unit cost or a maximum of Rs 1 lakh', '["Applicant Aadhar Cards (Mandatory)", "Applicant Ration Card (Mandatory)", "Applicant Voter ID (Mandatory)", "Caste & Income Certificate issued by competent authority (Mandatory)", "Project Report / Quotation (Mandatory)", "The applicant must declare they have not received prior assistance from the Corporation (Mandatory)", "Applicant Aadhar Card (Mandatory)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicant Age should be between 21 to 56 years.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '00098d28-e660-4ddf-a9c1-e1aee150c3ed', 'ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್', 'Industrial Service Business 1.0', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಉದ್ಯಮ ಶೀಲತಾ ಅಭಿವೃದ್ದಿ ಯೋಜನೆ -ಐ.ಎಸ್.ಬಿ (ಬ್ಯಾಂಕ್', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ವಯಸ್ಸು 21 ರಿಂದ 56 ವರ್ಷದೊಳಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('5a4b57a8-1c89-4655-9600-c217866ad2aa', 'SOCIAL-WELFARE-DEPAR-26', '81b60538-519f-4131-bd38-c390f2d882d6', 'Ganga Kalyana', 'Loan with Subsidy', 0, 'Under this scheme, irrigation facilities are provided to small and very small scheduled caste farmers with 1½ to 5.00 acres of land by drilling boreholes, installing pump sets, and electrifying them. In certain districts such as Kolar, Chikkaballapur, Bangalore (Rural), Bangalore (City), Tumkur, and Ramnagar, the unit cost has been increased to Rs.4.75 lakh due to declining groundwater levels. Of this amount, Rs.4.25 lakh will be subsidized, and the remaining Rs.50,000/- will be provided as a term loan.In other districts, the unit cost is fixed at Rs.3.75 lakh, with Rs.3.25 lakh provided as a subsidy and Rs.50,000/- lakh as a term loan. Additionally, out of the unit cost, Rs.75,000 per borehole will be allocated to the respective Escom for electrification, within the subsidy limit of the unit cost.', '["Applicant Aadhar Cards (Optional)", "Ration Card (Mandatory)", "Aadhar linked PassBook Front Page Photo (Mandatory)", "Caste & Income Certificate issued by competent authority (Optional)", "The applicant must declare they have not received prior assistance from the Corporation (Optional)", "Passport size photo of the applicant (Mandatory)", "Small and Marginal Farmer Certificate (Mandatory)", "RTC (Mandatory)", "Submission of certificate attested by The Disability Welfare Officer is required in disability cases (Optional)"]', '["Applicant should be resident of Karnataka state.", "Applicant should belong to a Scheduled Caste.", "Applicants must be at least 21 years old and there is no upper age limit.", "None of the applicant''s family members should be employed in a government or semi-government position.", "The applicant or their family should not have availed any benefits or facilities from the Corporation previously.", "The applicant''s family annual income should not exceed Rs 1.5 lakh for rural areas and Rs 2.00 lakh for urban area.", "Submission of a certificate attested by the District Disability Welfare Officer is required in case of disability.", "The applicants must be small and medium marginal farmers and should not have access to irrigation facilities."]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '00098d28-e660-4ddf-a9c1-e1aee150c3ed', 'ಗಂಗಾ ಕಲ್ಯಾಣ ಯೋಜನೆ', 'Ganga Kalyana', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಈ ಯೋಜನೆಯಡಿ 1½ ಎಕರೆಯಿಂದ 5.00 ಎಕರೆ ಜಮೀನು ಹೊಂದಿರುವ ಪರಿಶಿಷ್ಟ ಜಾತಿಯ ಸಣ್ಣ ಮತ್ತು ಅತೀ ಸಣ್ಣ ರೈತರ ಜಮೀನಿನಲ್ಲಿ ಕೊಳವೆಬಾವಿ ಕೊರೆಸಿ, ಪಂಪ್ ಸೆಟ್ ಅಳವಡಿಸಿ ವಿದ್ಯುದ್ಧೀಕರಣಗೊಳಿಸಿ ನೀರಾವರಿ ಸೌಲಭ್ಯ ಕಲ್ಪಿಸಲಾಗುತ್ತಿದೆ. ಈ ಯೋಜನೆಯಡಿ ಕೋಲಾರ, ಚಿಕ್ಕಬಳ್ಳಾಪುರ, ಬೆಂಗಳೂರು(ಗ್ರಾ), ಬೆಂಗಳೂರು(ನಗರ), ತುಮಕೂರು ಮತ್ತು ರಾಮನಗರ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಅಂತರ್ಜಲ ಮಟ್ಟ ಕೆಳಗೆ ಕುಸಿದಿರುವುದರಿಂದ ಈ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಘಟಕ ವೆಚ್ಚ ರೂ.4.75 ಲಕ್ಷಕ್ಕೆ ಹೆಚ್ಚಿಸಲಾಗಿದ್ದು, ಇದರಲ್ಲಿ ರೂ.4.25 ಲಕ್ಷ ಸಹಾಯಧನವಿದ್ದು, ಉಳಿದ ರೂ.50,000/- ಅವಧಿಸಾಲವಾಗಿರುತ್ತದೆ. ಇತರೆ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಘಟಕ ವೆಚ್ಚ ರೂ.3.75 ಲಕ್ಷ ನಿಗದಿಪಡಿಸಿದ್ದು, ಇದರಲ್ಲಿ ರೂ.3.25 ಲಕ್ಷ ಸಹಾಯಧನ ಮತ್ತು ರೂ.50,000/- ಅವಧಿಸಾಲವಾಗಿರುತ್ತದೆ. ಘಟಕ ವೆಚ್ಚದ ಪೈಕಿ ವಿದ್ಯುದ್ದೀಕರಣಕ್ಕೆ ಘಟಕ ವೆಚ್ಚದ ಸಹಾಯಧನದ ಮಿತಿಯಲ್ಲಿ ಪ್ರತಿ ಕೊಳವೆಬಾವಿಗೆ ರೂ.75,000/-ಗಳನ್ನು ಸಂಬಂಧಿಸಿದ ಎಸ್ಕಾಂಗಳಿಗೆ ಬಿಡುಗಡೆ ಮಾಡಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ನಿವಾಸಿಯಾಗಿರಬೇಕು.", "ಪರಿಶಿಷ್ಟ ಜಾತಿ ಸಮುದಾಯಕ್ಕೆ ಸೇರಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಕನಿಷ್ಠ 21 ವರ್ಷಗಳು ಪೂರ್ಣಗೊಂಡಿರಬೇಕು ಗರಿಷ್ಠ ವಯೋಮಿತಿ ತೆಗೆದು ಹಾಕಲಾಗಿದೆ.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ಯಾವುದೇ ಸದಸ್ಯರು, ಸರ್ಕಾರಿ/ಅರೆ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯಲ್ಲಿ ಉದ್ಯೋಗಿಯಾಗಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಅಥವಾ ಅವರ ಕುಟುಂಬದವರು ಈ ಹಿಂದೆ ನಿಗಮದಿಂದ ಯಾವುದೇ ಸೌಲಭ್ಯ ಪಡೆದಿರಬಾರದು.", "ಅರ್ಜಿದಾರರ ಕುಟುಂಬದ ವಾರ್ಷಿಕ ಆದಾಯ ಗ್ರಾಮೀಣ ಭಾಗಕ್ಕೆ ರೂ 1.5 ಲಕ್ಷ ಹಾಗೂ ನಗರ ಪ್ರದೇಶದಲ್ಲಿರುವವರಿಗೆ ರೂ 2.00 ಲಕ್ಷ ಮೀರಿರಬಾರದು.", "ವಿಕಲಚೇತನರಾಗಿದ್ದಲ್ಲಿ ಜಿಲ್ಲಾ ಅಂಗವಿಕಲ ಕಲ್ಯಾಣಾಧಿಕಾರಿಗಳಿಂದ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಪ್ರಮಾಣ ಪತ್ರ ಸಲ್ಲಿಸುವುದು.", "ಅರ್ಜಿದಾರರು ಸಣ್ಣ ಮತ್ತು ಅತಿ ಸಣ್ಣ ರೈತರಾಗಿರಬೇಕು ಹಾಗೂ ನೀರಾವರಿ ಸೌಲಭ್ಯ ಹೊಂದಿರಬಾರದು."]', '[]', 1, '["ಅರ್ಜಿದಾರರ ಆಧಾರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('f0bf60fc-02cc-4d02-a2b4-c9d7a0cce1ee', 'SOCIAL-WELFARE-DEPAR-25', '81b60538-519f-4131-bd38-c390f2d882d6', 'Dairy Farming Scheme', 'Subsidy', 0, 'Under the Dairy Farming Scheme, beneficiaries are provided a subsidy of ₹1.25 lakhs to support the establishment and development of dairy farming for sustainable livelihood and milk production', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhuservices.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '00098d28-e660-4ddf-a9c1-e1aee150c3ed', 'ಹೈನುಗಾರಿಕೆ ಯೋಜನೆ', 'Dairy Farming Scheme', NULL, NULL, 'Online', NULL, NULL, NULL, 'ಈ ಯೋಜನೆಯ ಅಡಿಯಲ್ಲಿ ಫಲಾನುಭವಿಗಳಿಗೆ ಹೈನುಗಾರಿಕೆಯನ್ನು ಸ್ಥಾಪಿಸಲು ಮತ್ತು ಅಭಿವೃದ್ಧಿಪಡಿಸಲು ₹1.25 ಲಕ್ಷಗಳ ಸಹಾಯಧನವನ್ನು ನೀಡಲಾಗುತ್ತದೆ, ಇದು ಸ್ಥಿರ ಜೀವನೋಪಾಯ ಮತ್ತು ಹಾಲು ಉತ್ಪಾದನೆಗೆ ನೆರವಾಗುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('cc8fbe22-2d73-4890-a3a3-aec17a5b3613', 'COMMERCE-INDUSTRIES-10', '27b672ee-4244-4ffb-8336-ad57bb125eaf', 'Subsidy for Technology Adoption', 'General', 0, 'The Existing Micro, Small & Medium Enterprises who have adopted Technology from recognized National Laboratories are eligible to claim incentives under this scheme.', '["Self- attested Copy of Udyam Registration.", "A Brief Note on the technology adopted from recognized National Laboratories.", "An agreement copies between transferor and transferee for adoption/ transfer of technology.", "Statement of expenditure incurred for adoption/ transfer of technology along with Invoices and receipts in the prescribed format in Annexure -20."]', '["The Existing Micro, Small & Medium Enterprises who have adopted Technology from recognized National Laboratories are eligible to claim incentives under this scheme.", "The scheme shall provide one time incentive/assistance only."]', '[]', '["MSME units to submit the duly filled application in the prescribed format along with the documents mentioned to respective Joint Director DIC.", "The Joint Director, DIC on receipt of duly filled application with complete documents mentioned shall inspect the MSME units and verify the working condition and submit the application to KCTU for sanction of financial assistance.", "The Managing Director, KCTU shall verify the proposal and place the valid proposals before the State Level Sanction Committee (SLSC) for consideration."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '274071de-bd69-4364-b834-7a576335d6d0', 'ತಂತ್ರಜ್ಞಾನ ಅಳವಡಿಕೆಗೆ ಸಹಾಯಧನ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಮಾನ್ಯತೆ ಪಡೆದ ರಾಷ್ಟ್ರೀಯ ಪ್ರಯೋಗಾಲಯಗಳಿಂದ ತಂತ್ರಜ್ಞಾನವನ್ನು ಅಳವಡಿಸಿಕೊಂಡಿರುವ ರಾಜ್ಯದಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿರುವ ಎಂಎಸ್ಎಂಇ ಘಟಕಗಳು ಈ ಯೋಜನೆಯಡಿ ಸಹಾಯಧನ ಪಡೆಯಬಹುದು.', NULL, NULL, NULL, NULL, NULL, '["ಮಾನ್ಯತೆ ಪಡೆದ ರಾಷ್ಟ್ರೀಯ ಪ್ರಯೋಗಾಲಯಗಳಿಂದ ತಂತ್ರಜ್ಞಾನವನ್ನು ಅಳವಡಿಸಿಕೊಂಡಿರುವ ರಾಜ್ಯದಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿರುವ ಎಂಎಸ್ಎಂಇ ಘಟಕಗಳು ಈ ಯೋಜನೆಯಡಿ ಸಹಾಯಧನ ಪಡೆಯಬಹುದು.", "ಯೋಜನೆಯು ಕೇವಲ ಒಂದು ಬಾರಿ ಪ್ರೋತ್ಸಾಹ / ಸಹಾಯಧನವನ್ನು ಮಾತ್ರ ಒದಗಿಸುತ್ತದೆ."]', '["ಎಂಎಸ್ ಎಂ ಇ ಘಟಕಗಳು ನಿಗದಿತ ನಮೂನೆಯಲ್ಲಿ ಪೂರ್ಣವಾಗಿ ಭರ್ತಿ ಮಾಡಿದ ಅರ್ಜಿಯನ್ನು ನಮೂದಿಸಿದ ಸಂಪೂರ್ಣ ದಾಖಲೆಗಳೊಂದಿಗೆ ಸಂಬಂಧಿಸಿದ ಜಿಲ್ಲೆಯ ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರಿಗೆ ಸಲ್ಲಿಸುವುದು.", "ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರು ಎಂಎಸ್ ಎಂ ಇ ಘಟಕಗಳು ಪೂರ್ಣವಾಗಿ ಭರ್ತಿಮಾಡಿದ ಅರ್ಜಿ ಹಾಗೂ ನಮೂದಿಸಿದ ಸಂಪೂರ್ಣ ದಾಖಲೆಗಳು ಸ್ವೀಕೃತವಾದ ನಂತರ ಘಟಕಕ್ಕೆ ಭೇಟಿ ನೀಡಿ ಘಟಕದ ಕಾರ್ಯನಿರ್ವಹಣೆ ಬಗ್ಗೆ ಪರಿಶೀಲಿಸಿ ಅರ್ಜಿಯನ್ನು ಸಹಾಯಧನ ಮಂಜೂರಾತಿಗಾಗಿ ಕೆ.ಸಿ.ಟಿ.ಯು. ಸಂಸ್ಥೆಗೆ ಸಲ್ಲಿಸುವುದು", "ವ್ಯವಸ್ಥಾಪಕ ನಿರ್ದೇಶಕರು, ಕೆ.ಸಿಟಿಯುರವರು ಪ್ರಸ್ತಾವನೆಯನ್ನು ಪರಿಶೀಲಿಸುವುದು ಮತ್ತು ಮಾನ್ಯವಾದ ಪ್ರಸ್ತಾವನೆಗಳನ್ನು ರಾಜ್ಯ ಮಟ್ಟದ ಮಂಜೂರಾತಿ ಸಮಿತಿಯ (SLSC) ಮುಂದೆ ಪರಿಗಣನೆಗೆ ಸಲ್ಲಿಸುವುದು."]', 1, '["ಉದ್ಯಮ್ ನೋಂದಣಿಯ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ.", "ಮಾನ್ಯತೆ ಪಡೆದ ರಾಷ್ಟ್ರೀಯ ಪ್ರಯೋಗಾಲಯಗಳಿಂದ ಅಳವಡಿಸಿಕೊಂಡ ತಂತ್ರಜ್ಞಾನದ ಕುರಿತು ಸಂಕ್ಷಿಪ್ತ ಟಿಪ್ಪಣಿ", "ತಂತ್ರಜ್ಞಾನದ ಅಳವಡಿಕೆ/ವರ್ಗಾವಣೆಗಾಗಿ ವರ್ಗಾವಣೆದಾರ ಮತ್ತು ವರ್ಗಾವಣೆದಾರರ ನಡುವಿನ ಒಪ್ಪಂದದ ಪ್ರತಿಗಳು.", "ತಂತ್ರಜ್ಞಾನದ ಅಳವಡಿಕೆ/ವರ್ಗಾವಣೆಗಾಗಿ ಮಾಡಿದ ವೆಚ್ಚದ ಪಟ್ಟಿ ಅನುಬಂಧ-20 ರಲ್ಲಿ ಇನ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('89bb12dd-a674-4ac1-b294-62563cb22558', 'COMMERCE-INDUSTRIES-9', '27b672ee-4244-4ffb-8336-ad57bb125eaf', 'Reimbursement of expenses incurred for water audit', 'General', 0, 'The new/ existing Micro, Small & Medium Enterprises who have conducted Water audit are eligible to claim incentives under this scheme.', '["Self -attested Copy of Udyam Registration.", "Water Audit Report from accredited water auditors.", "Copy of Certificate/ registration issued to water auditor from International water association or its chapter in India.", "4. Statement of expenditure with invoices and receipts in Annexure-20."]', '["The new/ existing Micro, Small & Medium Enterprises who have conducted Water audit are eligible to claim incentives under this scheme.", "Water Audit must be done by an individual or a firm who are registered with international water association or its chapter in India.", "The scheme shall provide one time incentives / assistance only."]', '[]', '["The new/ existing Micro, Small & Medium Enterprises who have conducted Water audit are eligible to claim incentives under this scheme.", "Water Audit must be done by an individual or a firm who are registered with international water association or its chapter in India.", "The scheme shall provide one time incentives / assistance only."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '274071de-bd69-4364-b834-7a576335d6d0', 'ನೀರಿನ ಲೆಕ್ಕಪರಿಶೋಧನೆ (ಆಡಿಟ್)ಗೆ ತಗುಲಿದ ವೆಚ್ಚ ಮರುಪಾವತಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ನೀರಿನ ಲೆಕ್ಕಪರಿಶೋಧನೆ (ಆಡಿಟ್) ವಿಧಾನ ಅಳವಡಿಸಿಕೊಂಡ ರಾಜ್ಯದ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿರುವ ಸೂಕ್ಷ್ಮ, ಸಣ್ಣ ಮತ್ತು ಮಧ್ಯಮ ಘಟಕಗಳು ಈ ಯೋಜನೆಯಡಿ ಪ್ರೋತ್ಸಾಹ ಧನ ಪಡೆಯಲು ಅರ್ಹವಾಗಿವೆ.', NULL, NULL, NULL, NULL, NULL, '["ನೀರಿನ ಲೆಕ್ಕಪರಿಶೋಧನೆ (ಆಡಿಟ್) ವಿಧಾನ ಅಳವಡಿಸಿಕೊಂಡ ರಾಜ್ಯದ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿರುವ ಸೂಕ್ಷ್ಮ, ಸಣ್ಣ ಮತ್ತು ಮಧ್ಯಮ ಘಟಕಗಳು ಈ ಯೋಜನೆಯಡಿ ಪ್ರೋತ್ಸಾಹ ಧನ ಪಡೆಯಲು ಅರ್ಹವಾಗಿವೆ.", "ನೀರಿನ ಲೆಕ್ಕಪರಿಶೋಧನೆ (ಆಡಿಟ್) ಯನ್ನು ಅಂತರ್"]', '["ಎಂಎಸ್ ಎಂ ಇ ಘಟಕಗಳು ನಿಗದಿತ ನಮೂನೆಯಲ್ಲಿ ಪೂರ್ಣವಾಗಿ ಭರ್ತಿ ಮಾಡಿದ ಅರ್ಜಿಯನ್ನು ನಮೂದಿಸಿದ ದಾಖಲೆಗಳೊಂದಿಗೆ ಸಂಬಂಧಿಸಿದ ಜಿಲ್ಲೆಯ ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರಿಗೆ ಸಲ್ಲಿಸುವುದು.", "ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರು ಪೂರ್ಣವಾಗಿ ಭರ್ತಿಮಾಡಿದ ಅರ್ಜಿ ಹಾಗೂ ನಮೂದಿಸಿದ ಸಂಪೂರ್ಣ ದಾಖಲೆಗಳು ಸ್ವೀಕೃತವಾದ ನಂತರ ಘಟಕಕ್ಕೆ ಭೇಟಿ ನೀಡಿ ಘಟಕದ ಕಾರ್ಯನಿರ್ವಹಣೆ ಬಗ್ಗೆ ಪರಿಶೀಲಿಸಿ ಅರ್ಜಿಯನ್ನು ಸಹಾಯಧನ ಮಂಜೂರಾತಿಗಾಗಿ ಕೆ.ಸಿ.ಟಿ.ಯು. ಸಂಸ್ಥೆಗೆ ಸಲ್ಲಿಸುವುದು", "ವ್ಯವಸ್ಥಾಪಕ ನಿರ್ದೇಶಕರು, ಕೆ.ಸಿಟಿಯುರವರು ಪ್ರಸ್ತಾವನೆಯನ್ನು ಪರಿಶೀಲಿಸುವುದು ಮತ್ತು ಮಾನ್ಯವಾದ ಪ್ರಸ್ತಾವನೆಗಳನ್ನು ರಾಜ್ಯ ಮಟ್ಟದ ಮಂಜೂರಾತಿ ಸಮಿತಿಯ (SLSC) ಮುಂದೆ ಪರಿಗಣನೆಗೆ ಸಲ್ಲಿಸುವುದು."]', 1, '["ಉದ್ಯಮ್ ನೋಂದಣಿಯ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ", "ಮಾನ್ಯತೆ ಪಡೆದ ನೀರಿನ ಲೆಕ್ಕಪರಿಶೋಧಕರಿಂದ ನೀರಿನ ಲೆಕ್ಕಪರಿಶೋಧನಾ (ಆಡಿಟ್) ವರದಿ.", "ನೀರಿನ ಲೆಕ್ಕಪರಿಶೋಧಕರಿಗೆ ಅಂತರ್''ರಾಷ್ಟ್ರೀಯ ನೀರಿನ ಸಂಘ ಅಥವಾ ಭಾರತದಲ್ಲಿನ ಅದರ ಅಂಗ ಸಂಸ್ಥೆಯಿಂದ ನೀಡಿದ ಪ್ರಮಾಣ ಪತ್ರ / ನೋಂದಣಿ ಪ್ರಮಾಣ ಪತ್ರ", "ಅನುಬಂಧ-20 ರಲ್ಲಿ ವೆಚ್ಚದ ಪಟ್ಟಿ ಇನವಾಯ್ಸ್ ಮತ್ತು ರಶೀದಿಗಳೊಂದಿಗೆ."]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('34547779-738c-4507-98e1-7155ca1a554e', 'COMMERCE-INDUSTRIES-8', '27b672ee-4244-4ffb-8336-ad57bb125eaf', 'Subsidy for adopting Waste Water Recycling Measures', 'General', 0, 'The New / Existing Micro, Small & Medium Enterprises who have adopted Waste water recycling measures are eligible to claim incentives under this scheme.', '["Self -attested Copy of Udyam Registration.", "Statement of expenditure with invoices and receipts in Annexure-20.", "Self-attested copy of the Concept for operation issued by KSPCB.", "Chartered Engineer Certificate for expenditures incurred for adopting Waste Water Recycling measures."]', '["The New / Existing Micro, Small & Medium Enterprises who have adopted Waste water recycling measures are eligible to claim incentives under this scheme.", "The scheme shall provide one time incentive/assistance only."]', '[]', '["MSME units to submit the duly filled application in the prescribed format along with the documents mentioned to respective DIC.", "The Joint Director, DIC on receipt of duly filled application with complete documents mentioned shall inspect the MSME units and verify the working condition and submit the application to KCTU for sanction of financial assistance.", "The Managing Director, KCTU shall verify the proposal and place the valid proposals before the State Level Sanction Committee (SLSC) for consideration."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '274071de-bd69-4364-b834-7a576335d6d0', 'ತ್ಯಾಜ್ಯ ನೀರು ಪುನರ್', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ತ್ಯಾಜ್ಯ ನೀರು ಪುನರ್', NULL, NULL, NULL, NULL, NULL, '["ತ್ಯಾಜ್ಯ ನೀರು ಪುನರ್"]', '["ಎಂಎಸ್ ಎಂ ಇ ಘಟಕಗಳು ನಿಗದಿತ ನಮೂನೆಯಲ್ಲಿ ಪೂರ್ಣವಾಗಿ ಭರ್ತಿ ಮಾಡಿದ ಅರ್ಜಿಯನ್ನು ನಮೂದಿಸಿದ ದಾಖಲೆಗಳೊಂದಿಗೆ ಸಂಬಂಧಿಸಿದ ಜಿಲ್ಲೆಯ ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರಿಗೆ ಸಲ್ಲಿಸುವುದು.", "ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರು ಪೂರ್ಣವಾಗಿ ಭರ್ತಿಮಾಡಿದ ಅರ್ಜಿ ಹಾಗೂ ನಮೂದಿಸಿದ ಸಂಪೂರ್ಣ ದಾಖಲೆಗಳು ಸ್ವೀಕೃತವಾದ ನಂತರ ಘಟಕಕ್ಕೆ ಭೇಟಿ ನೀಡಿ ಘಟಕದ ಕಾರ್ಯನಿರ್ವಹಣೆ ಬಗ್ಗೆ ಪರಿಶೀಲಿಸಿ ಅರ್ಜಿಯನ್ನು ಸಹಾಯಧನ ಮಂಜೂರಾತಿಗಾಗಿ ಕೆ.ಸಿ.ಟಿ.ಯು. ಸಂಸ್ಥೆಗೆ ಸಲ್ಲಿಸುವುದು", "ವ್ಯವಸ್ಥಾಪಕ ನಿರ್ದೇಶಕರು, ಕೆ.ಸಿಟಿಯುರವರು ಪ್ರಸ್ತಾವನೆಯನ್ನು ಪರಿಶೀಲಿಸುವುದು ಮತ್ತು ಮಾನ್ಯವಾದ ಪ್ರಸ್ತಾವನೆಗಳನ್ನು ರಾಜ್ಯ ಮಟ್ಟದ ಮಂಜೂರಾತಿ ಸಮಿತಿಯ (SLSC) ಮುಂದೆ ಪರಿಗಣನೆಗೆ ಸಲ್ಲಿಸುವುದು."]', 1, '["ಉದ್ಯಮ್ ನೋಂದಣಿಯ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ", "ಅನುಬಂಧ-20 ರಲ್ಲಿ ವೆಚ್ಚದ ಪಟ್ಟಿ ಇನವಾಯ್ಸ್ ಮತ್ತು ರಶೀದಿಗಳೊಂದಿಗೆ.", "ಕರ್ನಾಟಕ ರಾಜ್ಯ ಮಾಲೀನ್ಯ ನಿಯಂತ್ರಣ ಮಂಡಳಿಯಿಂದ ಘಟಕ ಕಾರ್ಯನಿರ್ವಹಿಸಲು ಪಡೆದ ಪ್ರಮಾಣ ಪತ್ರದ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ.", "ಘಟಕದವರು ತ್ಯಾಜ್ಯ ನೀರು ಪುನರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('84761866-b680-4d98-943a-e0b3d3f314bb', 'COMMERCE-INDUSTRIES-7', '27b672ee-4244-4ffb-8336-ad57bb125eaf', 'Subsidy for adopting Zero Discharge Process', 'General', 0, 'The New / Existing Micro, Small & Medium Enterprises who have adopted Zero Discharge Processing are eligible to claim incentives under this scheme.', '["Self -attested Copy of Udyam Registration.", "Statement of expenditure with invoices and receipts in Annexure-20.", "Self-attested copy of the Concept for operation issued by KSPCB.", "Chartered Engineer Certificate for expenditures incurred for adopting Zero Discharge Process.", "Photograph of Zero Discharge plant."]', '["The New / Existing Micro, Small & Medium Enterprises who have adopted Zero Discharge Processing are eligible to claim incentives under this scheme.", "The scheme shall provide one time incentive/assistance only"]', '[]', '["MSME units to submit the duly filled application in the prescribed format along with the documents mentioned to respective DIC.", "The Joint Director, DIC on receipt of duly filled application with complete documents mentioned shall inspect the MSME units and verify the working condition and submit the application to KCTU for sanction of financial assistance.", "The Managing Director, KCTU shall verify the proposal and place the valid proposals before the State Level Sanction Committee (SLSC) for consideration."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '274071de-bd69-4364-b834-7a576335d6d0', 'ಶೂನ್ಯ ತ್ಯಾಜ್ಯ ನಿರ್ವಹಣಾ ವಿಧಾನ ಅಳವಡಿಕೆಗೆ ಸಹಾಯಧನ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಶೂನ್ಯ ತ್ಯಾಜ್ಯ ನಿರ್ವಹಣಾ ವಿಧಾನವನ್ನು ಅಳವಡಿಸಿಕೊಂಡ ರಾಜ್ಯದ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿರುವ ಸೂಕ್ಷ್ಮ, ಸಣ್ಣ ಮತ್ತು ಮಧ್ಯಮ ಘಟಕಗಳು ಈ ಯೋಜನೆಯಡಿ ಪ್ರೋತ್ಸಾಹ ಧನ ಪಡೆಯಲು ಅರ್ಹವಾಗಿವೆ.', NULL, NULL, NULL, NULL, NULL, '["ಶೂನ್ಯ ತ್ಯಾಜ್ಯ ನಿರ್ವಹಣಾ ವಿಧಾನವನ್ನು ಅಳವಡಿಸಿಕೊಂಡ ರಾಜ್ಯದ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿರುವ ಸೂಕ್ಷ್ಮ, ಸಣ್ಣ ಮತ್ತು ಮಧ್ಯಮ ಘಟಕಗಳು ಈ ಯೋಜನೆಯಡಿ ಪ್ರೋತ್ಸಾಹ ಧನ ಪಡೆಯಲು ಅರ್ಹವಾಗಿವೆ.", "ಯೋಜನೆಯು ಕೇವಲ ಒಂದು ಬಾರಿ ಪ್ರೋತ್ಸಾಹ / ಸಹಾಯವನ್ನು ಮಾತ್ರ ಒದಗಿಸುತ್ತದೆ."]', '["ಎಂಎಸ್ ಎಂ ಇ ಘಟಕಗಳು ನಿಗದಿತ ನಮೂನೆಯಲ್ಲಿ ಪೂರ್ಣವಾಗಿ ಭರ್ತಿ ಮಾಡಿದ ಅರ್ಜಿಯನ್ನು ನಮೂದಿಸಿದ ದಾಖಲೆಗಳೊಂದಿಗೆ ಸಂಬಂಧಿಸಿದ ಜಿಲ್ಲೆಯ ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರಿಗೆ ಸಲ್ಲಿಸುವುದು.", "ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರು ಪೂರ್ಣವಾಗಿ ಭರ್ತಿಮಾಡಿದ ಅರ್ಜಿ ಹಾಗೂ ನಮೂದಿಸಿದ ಸಂಪೂರ್ಣ ದಾಖಲೆಗಳು ಸ್ವೀಕೃತವಾದ ನಂತರ ಘಟಕಕ್ಕೆ ಭೇಟಿ ನೀಡಿ ಘಟಕದ ಕಾರ್ಯನಿರ್ವಹಣೆ ಬಗ್ಗೆ ಪರಿಶೀಲಿಸಿ ಅರ್ಜಿಯನ್ನು ಸಹಾಯಧನ ಮಂಜೂರಾತಿಗಾಗಿ ಕೆ.ಸಿ.ಟಿ.ಯು. ಸಂಸ್ಥೆಗೆ ಸಲ್ಲಿಸುವುದು", "ವ್ಯವಸ್ಥಾಪಕ ನಿರ್ದೇಶಕರು, ಕೆ.ಸಿಟಿಯುರವರು ಪ್ರಸ್ತಾವನೆಯನ್ನು ಪರಿಶೀಲಿಸುವುದು ಮತ್ತು ಮಾನ್ಯವಾದ ಪ್ರಸ್ತಾವನೆಗಳನ್ನು ರಾಜ್ಯ ಮಟ್ಟದ ಮಂಜೂರಾತಿ ಸಮಿತಿಯ (SLSC) ಮುಂದೆ ಪರಿಗಣನೆಗೆ ಸಲ್ಲಿಸುವುದು."]', 1, '["ಉದ್ಯಮ್ ನೋಂದಣಿಯ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ", "ಅನುಬಂಧ-20 ರಲ್ಲಿ ವೆಚ್ಚದ ಪಟ್ಟಿ ಇನವಾಯ್ಸ್ ಮತ್ತು ರಶೀದಿಗಳೊಂದಿಗೆ.", "ಕರ್ನಾಟಕ ರಾಜ್ಯ ಮಾಲೀನ್ಯ ನಿಯಂತ್ರಣ ಮಂಡಳಿಯಿಂದ ಘಟಕ ಕಾರ್ಯನಿರ್ವಹಿಸಲು ಪಡೆದ ಪ್ರಮಾಣ ಪತ್ರದ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ.", "ಘಟಕದವರು ಶೂನ್ಯ ತ್ಯಾಜ್ಯ ನಿರ್ವಹಣಾ ವಿಧಾನವನ್ನು ಅಳವಡಿಸಲು ವೆಚ್ಚವಾಗಿರುವ ಮೊತ್ತಕ್ಕೆ ಚಾರ್ಟೆಡ್ ಇಂಜಿನಿಯರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('be9c653e-4486-4aa5-8faf-7270b40d9eed', 'COMMERCE-INDUSTRIES-6', '27b672ee-4244-4ffb-8336-ad57bb125eaf', 'Subsidy for adopting Rain water Harvesting (R.W.H) measures', 'General', 0, 'The New / Existing Micro, Small & Medium Enterprises who have adopted RWH methods are eligible to claim incentives under this scheme.', '["Self- attested Copy of Udyam Registration.", "Photographs of RWH measures.", "Statement of expenditure with invoices and receipts in Annexure-20.", "Chartered Engineer Certificate for expenditures incurred on equipment for adopting RWH measures."]', '["The New / Existing Micro, Small & Medium Enterprises who have adopted RWH methods are eligible to claim incentives under this scheme.", "The scheme provides incentives to expenditure made for procurement of equipments for adopting RWH measures.", "The scheme shall provide one time incentive/assistance only."]', '[]', '["MSME units to submit the duly filled application in the prescribed format along with the documents mentioned to respective Joint Director DIC.", "The Joint Director, DIC on receipt of duly filled application with complete documents mentioned shall inspect the MSME units and verify the working condition and submit the application to KCTU for sanction of financial assistance.", "The Managing Director, KCTU shall verify the proposal and place the valid proposals before the State Level Sanction Committee (SLSC) for consideration."]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '274071de-bd69-4364-b834-7a576335d6d0', 'ಮಳೆ ನೀರು ಕೊಯ್ಲು ಅಳವಡಿಕೆಗೆ ಸಹಾಯಧನ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಮಳೆನೀರು ಕೊಯ್ಲು ವಿಧಾನ ಅಳವಡಿಸಿಕೊಂಡ ಕರ್ನಾಟಕ ರಾಜ್ಯದ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿರುವ ಸೂಕ್ಷ್ಮ, ಸಣ್ಣ ಮತ್ತು ಮಧ್ಯಮ ಘಟಕಗಳು ಈ ಯೋಜನೆಯಡಿ ಪ್ರೋತ್ಸಾಹ ಧನ ಪಡೆಯಲು ಅರ್ಹವಾಗಿವೆ.', NULL, NULL, NULL, NULL, NULL, '["ಮಳೆನೀರು ಕೊಯ್ಲು ವಿಧಾನ ಅಳವಡಿಸಿಕೊಂಡ ಕರ್ನಾಟಕ ರಾಜ್ಯದ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿರುವ ಸೂಕ್ಷ್ಮ, ಸಣ್ಣ ಮತ್ತು ಮಧ್ಯಮ ಘಟಕಗಳು ಈ ಯೋಜನೆಯಡಿ ಪ್ರೋತ್ಸಾಹ ಧನ ಪಡೆಯಲು ಅರ್ಹವಾಗಿವೆ.", "ಈ ಯೋಜನೆಯಡಿ ಮಳೆನೀರು ಕೊಯ್ಲು ವಿಧಾನ ಅಳವಡಿಸಲು ವೆಚ್ಚವಾಗುವ ಮೊತ್ತಕ್ಕೆ ಅನುದಾನ ನೀಡಲಾಗುವುದು.", "ಯೋಜನೆಯು ಕೇವಲ ಒಂದು ಬಾರಿ ಪ್ರೋತ್ಸಾಹ / ಸಹಾಯವನ್ನು ಮಾತ್ರ ಒದಗಿಸುತ್ತದೆ."]', '["ಎಂಎಸ್ ಎಂ ಇ ಘಟಕಗಳು ನಿಗದಿತ ನಮೂನೆಯಲ್ಲಿ ಪೂರ್ಣವಾಗಿ ಭರ್ತಿ ಮಾಡಿದ ಅರ್ಜಿಯನ್ನು ನಮೂದಿಸಿದ ದಾಖಲೆಗಳೊಂದಿಗೆ ಸಂಬಂಧಿಸಿದ ಜಿಲ್ಲೆಯ ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರಿಗೆ ಸಲ್ಲಿಸುವುದು.", "ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರು ಪೂರ್ಣವಾಗಿ ಭರ್ತಿಮಾಡಿದ ಅರ್ಜಿ ಹಾಗೂ ನಮೂದಿಸಿದ ಸಂಪೂರ್ಣ ದಾಖಲೆಗಳು ಸ್ವೀಕೃತವಾದ ನಂತರ ಘಟಕಕ್ಕೆ ಭೇಟಿ ನೀಡಿ ಘಟಕದ ಕಾರ್ಯನಿರ್ವಹಣೆ ಬಗ್ಗೆ ಪರಿಶೀಲಿಸಿ ಅರ್ಜಿಯನ್ನು ಸಹಾಯಧನ ಮಂಜೂರಾತಿಗಾಗಿ ಕೆ.ಸಿ.ಟಿ.ಯು. ಸಂಸ್ಥೆಗೆ ಸಲ್ಲಿಸುವುದು", "ವ್ಯವಸ್ಥಾಪಕ ನಿರ್ದೇಶಕರು, ಕೆ.ಸಿಟಿಯುರವರು ಪ್ರಸ್ತಾವನೆಯನ್ನು ಪರಿಶೀಲಿಸುವುದು ಮತ್ತು ಮಾನ್ಯವಾದ ಪ್ರಸ್ತಾವನೆಗಳನ್ನು ರಾಜ್ಯ ಮಟ್ಟದ ಮಂಜೂರಾತಿ ಸಮಿತಿಯ (SLSC) ಮುಂದೆ ಪರಿಗಣನೆಗೆ ಸಲ್ಲಿಸುವುದು."]', 1, '["ಉದ್ಯಮ್ ನೋಂದಣಿಯ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ", "ಮಳೆನೀರು ಕೊಯ್ಲು ವಿಧಾನ ಅಳವಡಿಸಿಕೊಂಡಿರುವುದಕ್ಕೆ ಛಾಯಾ ಚಿತ್ರಗಳು.", "ಅನುಬಂಧ-20 ರಲ್ಲಿ ವೆಚ್ಚದ ಪಟ್ಟಿ ಇನವಾಯ್ಸ್ ಮತ್ತು ರಶೀದಿಗಳೊಂದಿಗೆ.", "ಘಟಕದವರು ಮಳೆನೀರು ಕೊಯ್ಲು ವಿಧಾನ ಅಳವಡಿಸಲು ಉಪಕರಣ ಖರೀದಿಗಾಗಿ ವೆಚ್ಚವಾಗಿರುವ ಮೊತ್ತಕ್ಕೆ ಚಾರ್ಟೆಡ್ ಇಂಜಿನಿಯರ್''ರವರಿಂದ ಪ್ರಮಾಣೀಕರಿಸಿದ ಪ್ರಮಾಣ ಪತ್ರ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('0c708762-9de8-40bc-8d97-50ea4285daf1', 'COMMERCE-INDUSTRIES-5', '27b672ee-4244-4ffb-8336-ad57bb125eaf', 'Incentives for Quality certification- WE -CONNECT Certification', 'General', 0, 'The Existing Micro, Small & Medium Enterprises who have acquired the We-connect certification from We-connect international are eligible to claim incentives under this scheme.', '["Self-attested copy of Udyam Registration.", "The copy of the WE-CONNECT Certificate.", "Statement of expenditure with invoices and receipts In Annexure-20.", "Self attested copy of partnership deed/ certificate of incorporation / By-laws (If Applicable).", "Self attested copy of Minority/ SC / ST/PH/Ex Service (If Applicable)."]', '["The Existing Micro, Small & Medium Enterprises who have acquired the We-connect certification from We-connect international are eligible to claim incentives under this scheme.", "The Unit has to claim the incentives within the validity of the We-connect certification.", "The scheme shall provide incentive / subsidy only for the first three years."]', '[]', '["MSME units to submit the duly filled application in the prescribed format along with the documents mentioned to respective Joint Director DIC.", "The Joint Director, DIC on receipt of duly filled application with complete documents mentioned shall inspect the MSME units and verify the working condition and submit the application to KCTU for sanction of financial assistance.", "The Managing Director, KCTU shall verify the proposal and place the valid proposals before the State Level Sanction"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '274071de-bd69-4364-b834-7a576335d6d0', 'ಗುಣಮಟ್ಟ ಪ್ರಮಾಣೀಕರಣಕ್ಕೆ ಉತ್ತೇಜನ- ವಿ-ಕನೆಕ್ಟ್ ಪ್ರಮಾಣೀಕರಣ', NULL, NULL, NULL, NULL, NULL, NULL, 100.00, 'ವಿ-ಕನೆಕ್ಟ್ ಇಂಟರ್''ನ್ಯಾಷಿನಲ್ ವತಿಯಿಂದ ವಿ-ಕನೆಕ್ಟ್ ಪ್ರಮಾಣ ಪತ್ರ ಪಡೆದ ರಾಜ್ಯದ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿರುವ ಮಹಿಳಾ ಒಡೆತನದ ಸೂಕ್ಷ್ಮ ಸಣ್ಣ ಮತ್ತು ಮಧ್ಯಮ ಉದ್ಯಮಗಳು ಈ ಯೋಜನೆಯಡಿ ಸಹಾಯಧನ ಪಡೆಯಬಹುದಾಗಿರುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ವಿ-ಕನೆಕ್ಟ್ ಇಂಟರ್''ನ್ಯಾಷಿನಲ್ ವತಿಯಿಂದ ವಿ-ಕನೆಕ್ಟ್ ಪ್ರಮಾಣ ಪತ್ರ ಪಡೆದ ರಾಜ್ಯದ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿರುವ ಮಹಿಳಾ ಒಡೆತನದ ಸೂಕ್ಷ್ಮ ಸಣ್ಣ ಮತ್ತು ಮಧ್ಯಮ ಉದ್ಯಮಗಳು ಈ ಯೋಜನೆಯಡಿ ಸಹಾಯಧನ ಪಡೆಯಲು ಅರ್ಹವಾಗಿವೆ.", "ವಿ-ಕನೆಕ್ಟ್ ಪ್ರಮಾಣೀಕರಣದ ಮಾನ್ಯತೆಯೊಳಗೆ ಘಟಕವು ಪ್ರೋತ್ಸಾಹಕಗಳನ್ನು ಪಡೆಯಬೇಕಾಗುತ್ತದೆ.", "ಯೋಜನೆಯು ಮೊದಲ ಮೂರು ವರ್ಷಗಳವರೆಗೆ ಮಾತ್ರ ಪ್ರೋತ್ಸಾಹ / ಸಹಾಯ ಧನವನ್ನು ಒದಗಿಸುತ್ತದೆ."]', '["ಎಂಎಸ್ ಎಂ ಇ ಘಟಕಗಳು ನಿಗದಿತ ನಮೂನೆಯಲ್ಲಿ ಪೂರ್ಣವಾಗಿ ಭರ್ತಿ ಮಾಡಿದ ಅರ್ಜಿಯನ್ನು ನಮೂದಿಸಿದ ದಾಖಲೆಗಳೊಂದಿಗೆ ಸಂಬಂಧಿಸಿದ ಜಿಲ್ಲೆಯ ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರಿಗೆ ಸಲ್ಲಿಸುವುದು.", "ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರು ಪೂರ್ಣವಾಗಿ ಭರ್ತಿಮಾಡಿದ ಅರ್ಜಿ ಹಾಗೂ ನಮೂದಿಸಿದ ಸಂಪೂರ್ಣ ದಾಖಲೆಗಳು ಸ್ವೀಕೃತವಾದ ನಂತರ ಘಟಕಕ್ಕೆ ಭೇಟಿ ನೀಡಿ ಘಟಕದ ಕಾರ್ಯನಿರ್ವಹಣೆ ಬಗ್ಗೆ ಪರಿಶೀಲಿಸಿ ಅರ್ಜಿಯನ್ನು ಸಹಾಯಧನ ಮಂಜೂರಾತಿಗಾಗಿ ಕೆ.ಸಿ.ಟಿ.ಯು. ಸಂಸ್ಥೆಗೆ ಸಲ್ಲಿಸುವುದು", "ವ್ಯವಸ್ಥಾಪಕ ನಿರ್ದೇಶಕರು, ಕೆ.ಸಿಟಿಯುರವರು ಪ್ರಸ್ತಾವನೆಯನ್ನು ಪರಿಶೀಲಿಸುವುದು ಮತ್ತು ಮಾನ್ಯವಾದ ಪ್ರಸ್ತಾವನೆಗಳನ್ನು ರಾಜ್ಯ ಮಟ್ಟದ ಮಂಜೂರಾತಿ ಸಮಿತಿಯ (SLSC) ಮುಂದೆ ಪರಿಗಣನೆಗೆ ಸಲ್ಲಿಸುವುದು"]', 1, '["ಉದ್ಯಮ್ ನೋಂದಣಿಯ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ", "ವಿ-ಕನೆಕ್ಟ್ ಪ್ರಮಾಣಪತ್ರದ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ.", "ಅನುಬಂಧ-20 ರಲ್ಲಿ ವೆಚ್ಚದ ಪಟ್ಟಿ ಇನವಾಯ್ಸ್ ಮತ್ತು ರಶೀದಿಗಳೊಂದಿಗೆ.", "ಪಾಲುದಾರಿಕೆ ಪತ್ರ/ಸಂಘಟನಾ ಪ್ರಮಾಣಪತ್ರ/ಉಪ-ಕಾನೂನುಗಳ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ (ಅನ್ವಯಿಸಿದಲ್ಲಿ).", "ಅಲ್ಪಸಂಖ್ಯಾತ/ಪ.ಜಾ./ ಪ.ಪಂ./ವಿ.ಕ/ ಮಾಜಿ ಸೈನಿಕರು ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ (ಅನ್ವಯಿಸಿದಲ್ಲಿ)."]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('23d43795-7cad-4784-a469-f330807ffd49', 'COMMERCE-INDUSTRIES-4', '27b672ee-4244-4ffb-8336-ad57bb125eaf', 'Incentives for Quality certification- BIS Certification', 'General', 0, 'The Existing Micro, Small & Medium Enterprises who have acquired the BIS product certifications are eligible to claim incentives under this scheme.', '["Self-attested copy of Udyam Registration.", "The copy of the BIS Certificate.", "Statement of expenditure with invoices and receipts In Annexure-20.", "Self attested copy of partnership deed/ certificate of incorporation / By-laws (If Applicable).", "Self attested copy of Minority/ SC / ST/PH/Ex Service (If Applicable)."]', '["The Existing Micro, Small & Medium Enterprises who have acquired the BIS product certifications are eligible to claim incentives under this scheme.", "The Unit has to claim the incentives within the validity of the BIS certification (i.e within 1 Year from the date of issue of certificate).", "The scheme shall provide one time incentive/assistance only."]', '[]', '["MSME units to submit the duly filled application in the prescribed format along with the documents mentioned to respective Joint Director DIC.", "The Joint Director, DIC on receipt of duly filled application with complete documents mentioned shall inspect the MSME units and verify the working condition and submit the application to KCTU for sanction of financial assistance.", "The Managing Director, KCTU shall verify the proposal and place the valid proposals before the State Level Sanction"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '274071de-bd69-4364-b834-7a576335d6d0', 'ಗುಣಮಟ್ಟ ಪ್ರಮಾಣೀಕರಣಕ್ಕೆ ಉತ್ತೇಜನ- ಬಿ.ಐ.ಎಸ್. ಪ್ರಮಾಣಿಕರಣ', NULL, NULL, NULL, NULL, NULL, NULL, 100.00, 'ಬಿಐಎಸ್ ಉತ್ಪನ್ನ ಪ್ರಮಾಣೀಕರಣ ಪ್ರಮಾಣ ಪತ್ರ ಪಡೆದ ರಾಜ್ಯದ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿರುವ ಸೂಕ್ಷ್ಮ, ಸಣ್ಣ ಮತ್ತು ಮಧ್ಯಮ ಘಟಕಗಳು ಈ ಯೋಜನೆಯಡಿ ಪ್ರೋತ್ಸಾಹ ಧನ ಪಡೆಯಬಹುದಾಗಿರುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಬಿಐಎಸ್ ಉತ್ಪನ್ನ ಪ್ರಮಾಣೀಕರಣ ಪ್ರಮಾಣ ಪತ್ರ ಪಡೆದ ರಾಜ್ಯದ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿರುವ ಸೂಕ್ಷ್ಮ, ಸಣ್ಣ ಮತ್ತು ಮಧ್ಯಮ ಘಟಕಗಳು ಈ ಯೋಜನೆಯಡಿ ಪ್ರೋತ್ಸಾಹ ಧನ ಪಡೆಯಲು ಅರ್ಹವಾಗಿವೆ.", "ಬಿಐಎಸ್ ಪ್ರಮಾಣೀಕರಣದ ಮಾನ್ಯತೆಯೊಳಗೆ ಘಟಕವು ಪ್ರೋತ್ಸಾಹಕಗಳನ್ನು ಪಡೆಯಬೇಕಾಗಿದೆ (ಅಂದರೆ ಪ್ರಮಾಣಪತ್ರದ ದಿನಾಂಕದ ವಿತರಣೆಯಿಂದ 1 ವರ್ಷಗಳವರೆಗೆ).", "ಯೋಜನೆಯು ಕೇವಲ ಒಂದು ಬಾರಿ ಪ್ರೋತ್ಸಾಹ / ಸಹಾಯವನ್ನು ಮಾತ್ರ ಒದಗಿಸುತ್ತದೆ."]', '["ಎಂಎಸ್ ಎಂ ಇ ಘಟಕಗಳು ನಿಗದಿತ ನಮೂನೆಯಲ್ಲಿ ಪೂರ್ಣವಾಗಿ ಭರ್ತಿ ಮಾಡಿದ ಅರ್ಜಿಯನ್ನು ನಮೂದಿಸಿದ ದಾಖಲೆಗಳೊಂದಿಗೆ ಸಂಬಂಧಿಸಿದ ಜಿಲ್ಲೆಯ ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರಿಗೆ ಸಲ್ಲಿಸುವುದು.", "ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರು ಪೂರ್ಣವಾಗಿ ಭರ್ತಿಮಾಡಿದ ಅರ್ಜಿ ಹಾಗೂ ನಮೂದಿಸಿದ ಸಂಪೂರ್ಣ ದಾಖಲೆಗಳು ಸ್ವೀಕೃತವಾದ ನಂತರ ಘಟಕಕ್ಕೆ ಭೇಟಿ ನೀಡಿ ಘಟಕದ ಕಾರ್ಯನಿರ್ವಹಣೆ ಬಗ್ಗೆ ಪರಿಶೀಲಿಸಿ ಅರ್ಜಿಯನ್ನು ಸಹಾಯಧನ ಮಂಜೂರಾತಿಗಾಗಿ ಕೆ.ಸಿ.ಟಿ.ಯು. ಸಂಸ್ಥೆಗೆ ಸಲ್ಲಿಸುವುದು", "ವ್ಯವಸ್ಥಾಪಕ ನಿರ್ದೇಶಕರು, ಕೆ.ಸಿಟಿಯುರವರು ಪ್ರಸ್ತಾವನೆಯನ್ನು ಪರಿಶೀಲಿಸುವುದು ಮತ್ತು ಮಾನ್ಯವಾದ ಪ್ರಸ್ತಾವನೆಗಳನ್ನು ರಾಜ್ಯ ಮಟ್ಟದ ಮಂಜೂರಾತಿ ಸಮಿತಿಯ (SLSC) ಮುಂದೆ ಪರಿಗಣನೆಗೆ ಸಲ್ಲಿಸುವುದು."]', 1, '["ಉದ್ಯಮ್ ನೋಂದಣಿಯ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ", "ಬಿ.ಐ.ಎಸ್. ಪ್ರಮಾಣಪತ್ರದ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ.", "ಅನುಬಂಧ-20 ರಲ್ಲಿ ವೆಚ್ಚದ ಪಟ್ಟಿ ಇನವಾಯ್ಸ್ ಮತ್ತು ರಶೀದಿಗಳೊಂದಿಗೆ.", "ಪಾಲುದಾರಿಕೆ ಪತ್ರ/ಸಂಘಟನಾ ಪ್ರಮಾಣಪತ್ರ/ಉಪ-ಕಾನೂನುಗಳ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ (ಅನ್ವಯಿಸಿದಲ್ಲಿ).", "ಅಲ್ಪಸಂಖ್ಯಾತ/ಪ.ಜಾ./ ಪ.ಪಂ./ವಿ.ಕ/ ಮಾಜಿ ಸೈನಿಕರು ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ (ಅನ್ವಯಿಸಿದಲ್ಲಿ)."]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('f7291ecf-dcd8-4a5a-8044-16ca3d724080', 'COMMERCE-INDUSTRIES-3', '27b672ee-4244-4ffb-8336-ad57bb125eaf', 'Incentives for Quality certification-- ISO Series Certification', 'General', 0, 'Micro, Small & Medium Enterprises operating in districts of state who have acquired the ISO series certifications from NABCB accredited agencies are eligible to claim incentive under this scheme.', '["Self-attested copy of Udyam Registration.", "Statement of expenditure with invoices and receipts In Annexure-20", "Self- attested copy of the ISO Certificate obtained from NABCB accredited agencies.", "Self- attested copy of Quality Manual .", "Self attested copy of partnership deed/ certificate of incorporation / By-laws (If Applicable).", "Self attested copy of Minority/ SC / ST/PH/Ex Service (If Applicable)."]', '["Micro, Small & Medium Enterprises operating in districts of state who have acquired the ISO series certifications from NABCB accredited agencies are eligible to claim incentive under this scheme.", "The Unit has to claim the incentive within the validity of the ISO series certification (i.e upto 3 Years from the date of issue of certificate).", "In case the unit has obtained different types of ISO certification, the benefit of this incentive will be to only one type of ISO certification which is financially beneficial to the unit.", "The scheme shall provide one time incentive / assistance only."]', '[]', '["MSME units to submit the duly filled application in the prescribed format along with the documents mentioned to respective Joint Director DIC.", "The Joint Director, DIC on receipt of duly filled application with complete documents mentioned shall inspect the MSME units and verify the working condition and submit the application to KCTU for sanction of financial assistance.", "The Managing Director, KCTU shall verify the proposal and place the valid proposals before the State Level Sanction Committee (SLSC) for consideration"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '274071de-bd69-4364-b834-7a576335d6d0', 'ಗುಣಮಟ್ಟ ಪ್ರಮಾಣೀಕರಣಕ್ಕೆ ಉತ್ತೇಜನ- ಐ.ಎಸ್.ಓ. ಸರಣಿ ಪ್ರಮಾಣಿಕರಣ', NULL, NULL, NULL, NULL, NULL, NULL, 100.00, 'ಎನ್', NULL, NULL, NULL, NULL, NULL, '["ಎನ್"]', '["ಎಂಎಸ್ ಎಂ ಇ ಘಟಕಗಳು ನಿಗದಿತ ನಮೂನೆಯಲ್ಲಿ ಪೂರ್ಣವಾಗಿ ಭರ್ತಿ ಮಾಡಿದ ಅರ್ಜಿಯನ್ನು ನಮೂದಿಸಿದ ದಾಖಲೆಗಳೊಂದಿಗೆ ಸಂಬಂಧಿಸಿದ ಜಿಲ್ಲೆಯ ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರಿಗೆ ಸಲ್ಲಿಸುವುದು.", "ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರು ಪೂರ್ಣವಾಗಿ ಭರ್ತಿಮಾಡಿದ ಅರ್ಜಿ ಹಾಗೂ ನಮೂದಿಸಿದ ಸಂಪೂರ್ಣ ದಾಖಲೆಗಳು ಸ್ವೀಕೃತವಾದ ನಂತರ ಘಟಕಕ್ಕೆ ಭೇಟಿ ನೀಡಿ ಘಟಕದ ಕಾರ್ಯನಿರ್ವಹಣೆ ಬಗ್ಗೆ ಪರಿಶೀಲಿಸಿ ಅರ್ಜಿಯನ್ನು ಸಹಾಯಧನ ಮಂಜೂರಾತಿಗಾಗಿ ಕೆ.ಸಿ.ಟಿ.ಯು. ಸಂಸ್ಥೆಗೆ ಸಲ್ಲಿಸುವುದು", "ವ್ಯವಸ್ಥಾಪಕ ನಿರ್ದೇಶಕರು, ಕೆ.ಸಿಟಿಯುರವರು ಪ್ರಸ್ತಾವನೆಯನ್ನು ಪರಿಶೀಲಿಸುವುದು ಮತ್ತು ಮಾನ್ಯವಾದ ಪ್ರಸ್ತಾವನೆಗಳನ್ನು ರಾಜ್ಯ ಮಟ್ಟದ ಮಂಜೂರಾತಿ ಸಮಿತಿಯ (SLSC) ಮುಂದೆ ಪರಿಗಣನೆಗೆ ಸಲ್ಲಿಸುವುದು."]', 1, '["ಉದ್ಯಮ್ ನೋಂದಣಿಯ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ", "ಅನುಬಂಧ-20 ರಲ್ಲಿ ವೆಚ್ಚದ ಪಟ್ಟಿ ಇನವಾಯ್ಸ್ ಮತ್ತು ರಶೀದಿಗಳೊಂದಿಗೆ.", "ಎನ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('fd1482de-b495-4427-b04c-66f6606d00ef', 'COMMERCE-INDUSTRIES-2', '27b672ee-4244-4ffb-8336-ad57bb125eaf', 'Incentives for Quality certification - NADCAP Series Certification', 'General', 0, 'The Existing Micro, Small & Medium Enterprises in Aerospace and Defense sector located in the districts of Karnataka who have acquired the NADCAP Certification are eligible to claim incentives under this scheme.', '["Self attested Copy of Udyam Registration.", "Self attested Copy of NADCAP series Certificate.", "Statement of expenditure with invoices and receipts in Annexure-2.", "Chartered Accountant certificate of Plant & Machinery and Turn over in Annexure -3.", "An affidavit stating that this incentive has not been availed earlier from any Government Agency Annexure - 4.", "Self- attested copy of Quality Manual.", "Self attested copy of partnership deed/ certificate of incorporation / By-laws (If Applicable).", "Self attested copy of Minority/ SC / ST/PH/Ex Service (If Applicable)."]', '["The Existing Micro, Small & Medium Enterprises in Aerospace and Defense sector located in the districts of Karnataka who have acquired the NADCAP Certification are eligible to claim incentives under this scheme.", "The Unit has to claim the incentives within the validity of the NADCAP Certification (i.e upto 3 Years from the date of issue of certificate).", "The scheme shall provide one time incentive/assistance only."]', '[]', '["MSME units to submit the duly filled application in the prescribed format along with the documents mentioned to respective Joint Director DIC.", "The Joint Director, DIC on receipt of duly filled application with complete documents mentioned shall inspect the MSME units and verify the working condition and submit the application to KCTU for sanction of financial assistance.", "The Managing Director, KCTU shall verify the proposal and place the valid proposals before the State Level Sanction Committee (SLSC) for consideration"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '274071de-bd69-4364-b834-7a576335d6d0', 'ಗುಣಮಟ್ಟ ಪ್ರಮಾಣೀಕರಣಕ್ಕೆ ಉತ್ತೇಜನ - NADCAP ಸರಣಿ ಪ್ರಮಾಣಿಕರಣ', NULL, NULL, NULL, NULL, NULL, NULL, 100.00, 'NADCAP ಸರಣಿ ಪ್ರಮಾಣ ಪತ್ರ ಪಡೆದ ರಾಜ್ಯದ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಏರೋಸ್ಪೇಸ್', NULL, NULL, NULL, NULL, NULL, '["NADCAP ಸರಣಿ ಪ್ರಮಾಣ ಪತ್ರ ಪಡೆದ ರಾಜ್ಯದ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಏರೋಸ್ಪೇಸ್"]', '["ಎಂಎಸ್ ಎಂ ಇ ಘಟಕಗಳು ನಿಗದಿತ ನಮೂನೆಯಲ್ಲಿ ಸಂಪೂರ್ಣವಾಗಿ ಭರ್ತಿ ಮಾಡಿದ ಅರ್ಜಿಯನ್ನು ನಮೂದಿಸಿದ ದಾಖಲೆಗಳೊಂದಿಗೆ ಸಂಬಂಧಿಸಿದ ಜಿಲ್ಲೆಯ ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರಿಗೆ ಸಲ್ಲಿಸುವುದು.", "ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರು ಎಂಎಸ್ ಎಂ ಇ ಘಟಕಗಳು ಪೂರ್ಣವಾಗಿ ಭರ್ತಿಮಾಡಿದ ಅರ್ಜಿ ಹಾಗೂ ನಮೂದಿಸಿದ ಸಂಪೂರ್ಣ ದಾಖಲೆಗಳು ಸ್ವೀಕೃತವಾದ ನಂತರ ಘಟಕಕ್ಕೆ ಭೇಟಿ ನೀಡಿ ಘಟಕದ ಕಾರ್ಯನಿರ್ವಹಣೆ ಬಗ್ಗೆ ಪರಿಶೀಲಿಸಿ ಅರ್ಜಿಯನ್ನು ಸಹಾಯಧನ ಮಂಜೂರಾತಿಗಾಗಿ ಕೆ.ಸಿ.ಟಿ.ಯು. ಸಂಸ್ಥೆಗೆ ಸಲ್ಲಿಸುವುದು", "ವ್ಯವಸ್ಥಾಪಕ ನಿರ್ದೇಶಕರು, ಕೆ.ಸಿಟಿಯುರವರು ಪ್ರಸ್ತಾವನೆಯನ್ನು ಪರಿಶೀಲಿಸುವುದು ಮತ್ತು ಮಾನ್ಯವಾದ ಪ್ರಸ್ತಾವನೆಗಳನ್ನು ರಾಜ್ಯ ಮಟ್ಟದ ಮಂಜೂರಾತಿ ಸಮಿತಿಯ (SLSC) ಮುಂದೆ ಪರಿಗಣನೆಗೆ ಸಲ್ಲಿಸುವುದು."]', 1, '["ಉದ್ಯಮ್ ನೋಂದಣಿಯ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ", "NADCAP ಪ್ರಮಾಣ ಪತ್ರದ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ.", "ಅನುಬಂಧ- 2 ರಲ್ಲಿ ವೆಚ್ಚದ ಪಟ್ಟಿ ಇನವಾಯ್ಸ್ ಮತ್ತು ರಶೀದಿಗಳೊಂದಿಗೆ.", "ಅನುಬಂಧ- 3 ರಲ್ಲಿ ಯಂತ್ರೋಪಕರಣಗಳನ್ನು ಅಳವಡಿಸಲು ವೆಚ್ಚವಾಗಿರುವ ಮೊತ್ತಕ್ಕೆ ಹಾಗೂ ವಹಿವಾಟಿನ ವಿವರಗಳಿಗೆ ಚಾರ್ಟೆಡ್ ಅಕೌಂಟೆಂಟ್ ರವರಿಂದ ಪ್ರಮಾಣ ಪತ್ರ.", "ಅನುಬಂಧ- 4 ರಲ್ಲಿ NADCAP ಪ್ರಮಾಣ ಪತ್ರ ಪಡೆದುದಕ್ಕೆ ಸಹಾಯಧನವನ್ನು ಬೇರೆ ಯಾವುದೇ ಸರ್ಕಾರದ ಏಜೆನ್ಸಿಗಳಿಂದ ಪಡೆದಿಲ್ಲವೆಂದು ಸ್ವಯಂದೃಢೀಕೃತ ಪ್ರಮಾಣ ಪತ್ರ.", "ಗುಣಮಟ್ಟದ ಕೈಪಿಡಿಯ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ.", "ಪಾಲುದಾರಿಕೆ ಪತ್ರ/ಸಂಘಟನಾ ಪ್ರಮಾಣಪತ್ರ/ಉಪ-ಕಾನೂನುಗಳ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ (ಅನ್ವಯಿಸಿದಲ್ಲಿ).", "ಅಲ್ಪಸಂಖ್ಯಾತ/ಪ.ಜಾ./ ಪ.ಪಂ./ವಿ.ಕ/ ಮಾಜಿ ಸೈನಿಕರು ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ (ಅನ್ವಯಿಸಿದಲ್ಲಿ)."]', NULL, NULL, NULL);
