INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('2ce0cb05-3229-4c8c-9203-03787686555d', 'COMMERCE-INDUSTRIES-1', '27b672ee-4244-4ffb-8336-ad57bb125eaf', 'Incentives for Quality certification - AS 9100 Series Certification', 'General', 0, 'The Existing Micro, Small & Medium Enterprises in Aerospace and Defense sector located in the districts of Karnataka who have acquired the AS9100 are eligible to claim incentives under this scheme.', '["Self attested Copy of Udyam Registration.", "Self attested Copy of AS9100series Certificate.", "Statement of expenditure with invoices and receipts in Annexure-2.", "Chartered Accountant certificate of Plant & Machinery and Turn over in Annexure -3.", "An affidavit stating that AS9100 incentive has not been availed earlier from any Government Agency Annexure - 4.", "Self- attested copy of Quality Manual.", "Self attested copy of partnership deed/ certificate of incorporation / By-laws (If Applicable).", "Self attested copy of Minority/ SC / ST/PH/Ex Service (If Applicable)."]', '["The Existing Micro, Small & Medium Enterprises in Aerospace and Defense sector located in the districts of Karnataka who have acquired the AS9100 are eligible to claim incentives under this scheme.", "The Unit has to claim the incentives within the validity of the AS9100 series certification (i.e upto 3 Years from the date of issue of certificate).", "The scheme shall provide one time incentive/assistance only."]', '[]', '["MSME units to submit the duly filled application in the prescribed format along with the documents mentioned to respective Joint Director DIC.", "The Joint Director, DIC on receipt of duly filled application with complete documents mentioned shall inspect the MSME units and verify the working condition and submit the application to KCTU for sanction of financial assistance.", "The Managing Director, KCTU shall verify the proposal and place the valid proposals before the State Level Sanction Committee (SLSC) for consideration"]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', '274071de-bd69-4364-b834-7a576335d6d0', 'ಗುಣಮಟ್ಟ ಪ್ರಮಾಣೀಕರಣಕ್ಕೆ ಉತ್ತೇಜನ - ಎ.ಎಸ್. - 9100 ಸರಣಿ ಪ್ರಮಾಣಿಕರಣ', NULL, NULL, NULL, NULL, NULL, NULL, 100.00, 'ಎಎಸ್-9100 ಸರಣಿ ಪ್ರಮಾಣ ಪತ್ರ ಪಡೆದ ರಾಜ್ಯದ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಏರೋಸ್ಪೇಸ್', NULL, NULL, NULL, NULL, NULL, '["ಎಎಸ್-9100 ಸರಣಿ ಪ್ರಮಾಣ ಪತ್ರ ಪಡೆದ ರಾಜ್ಯದ ಜಿಲ್ಲೆಗಳಲ್ಲಿ ಏರೋಸ್ಪೇಸ್"]', '["ಎಂಎಸ್ ಎಂ ಇ ಘಟಕಗಳು ನಿಗದಿತ ನಮೂನೆಯಲ್ಲಿ ಸಂಪೂರ್ಣವಾಗಿ ಭರ್ತಿ ಮಾಡಿದ ಅರ್ಜಿಯನ್ನು ನಮೂದಿಸಿದ ದಾಖಲೆಗಳೊಂದಿಗೆ ಸಂಬಂಧಿಸಿದ ಜಿಲ್ಲೆಯ ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರಿಗೆ ಸಲ್ಲಿಸುವುದು.", "ಜಂಟಿ ನಿರ್ದೇಶಕರು, ಜಿಲ್ಲಾ ಕೈಗಾರಿಕಾ ಕೇಂದ್ರರವರು ಎಂಎಸ್ ಎಂ ಇ ಘಟಕಗಳು ಪೂರ್ಣವಾಗಿ ಭರ್ತಿಮಾಡಿದ ಅರ್ಜಿ ಹಾಗೂ ನಮೂದಿಸಿದ ಸಂಪೂರ್ಣ ದಾಖಲೆಗಳು ಸ್ವೀಕೃತವಾದ ನಂತರ ಘಟಕಕ್ಕೆ ಭೇಟಿ ನೀಡಿ ಘಟಕದ ಕಾರ್ಯನಿರ್ವಹಣೆ ಬಗ್ಗೆ ಪರಿಶೀಲಿಸಿ ಅರ್ಜಿಯನ್ನು ಸಹಾಯಧನ ಮಂಜೂರಾತಿಗಾಗಿ ಕೆ.ಸಿ.ಟಿ.ಯು. ಸಂಸ್ಥೆಗೆ ಸಲ್ಲಿಸುವುದು", "ವ್ಯವಸ್ಥಾಪಕ ನಿರ್ದೇಶಕರು, ಕೆ.ಸಿಟಿಯುರವರು ಪ್ರಸ್ತಾವನೆಯನ್ನು ಪರಿಶೀಲಿಸುವುದು ಮತ್ತು ಮಾನ್ಯವಾದ ಪ್ರಸ್ತಾವನೆಗಳನ್ನು ರಾಜ್ಯ ಮಟ್ಟದ ಮಂಜೂರಾತಿ ಸಮಿತಿಯ (SLSC) ಮುಂದೆ ಪರಿಗಣನೆಗೆ ಸಲ್ಲಿಸುವುದು."]', 1, '["ಉದ್ಯಮ್ ನೋಂದಣಿಯ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ", "ಎ.ಎಸ್.- 9100 ಪ್ರಮಾಣ ಪತ್ರದ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ.", "ಅನುಬಂಧ- 2 ರಲ್ಲಿ ವೆಚ್ಚದ ಪಟ್ಟಿ ಇನವಾಯ್ಸ್ ಮತ್ತು ರಶೀದಿಗಳೊಂದಿಗೆ.", "ಅನುಬಂಧ- 3 ರಲ್ಲಿ ಯಂತ್ರೋಪಕರಣಗಳನ್ನು ಅಳವಡಿಸಲು ವೆಚ್ಚವಾಗಿರುವ ಮೊತ್ತಕ್ಕೆ ಹಾಗೂ ವಹಿವಾಟಿನ ವಿವರಗಳಿಗೆ ಚಾರ್ಟೆಡ್ ಅಕೌಂಟೆಂಟ್ ರವರಿಂದ ಪ್ರಮಾಣ ಪತ್ರ.", "ಅನುಬಂಧ- 4 ರಲ್ಲಿ ಎ.ಎಸ್.- 9100 ಪ್ರಮಾಣ ಪತ್ರ ಪಡೆದುದಕ್ಕೆ ಸಹಾಯಧನವನ್ನು ಬೇರೆ ಯಾವುದೇ ಸರ್ಕಾರದ ಏಜೆನ್ಸಿಗಳಿಂದ ಪಡೆದಿಲ್ಲವೆಂದು ಸ್ವಯಂದೃಢೀಕೃತ ಪ್ರಮಾಣ ಪತ್ರ.", "ಗುಣಮಟ್ಟದ ಕೈಪಿಡಿಯ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ.", "ಪಾಲುದಾರಿಕೆ ಪತ್ರ/ಸಂಘಟನಾ ಪ್ರಮಾಣಪತ್ರ/ಉಪ-ಕಾನೂನುಗಳ ಸ್ವಯಂ ದೃಢೀಕೃ ಪ್ರತಿ (ಅನ್ವಯಿಸಿದಲ್ಲಿ).", "ಅಲ್ಪಸಂಖ್ಯಾತ/ಪ.ಜಾ./ ಪ.ಪಂ./ವಿ.ಕ/ ಮಾಜಿ ಸೈನಿಕರು ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ (ಅನ್ವಯಿಸಿದಲ್ಲಿ)."]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('16b79bc4-3bf2-441a-ac69-955e0d76a26f', 'DEPARTMENT-OF-YOUTH-8', '7f8d398a-7ac3-425b-bdc4-df5bd5944b47', 'Application for Life time Achivement Award', 'General', 0, 'Coaches who have been Coaching Trining for 20 years and Producing the Athletes of Karnataka who represent Karnataka and achieve the highest achievements in the field of sports.', '["Details of Trained Athletes and there Achivements Sports certificates Issued by Competitions Authority and Relevant Documents to be Attached"]', '["Coaches of Karnataka who have served for 20 years to Trained and Coaching to develop and contribute athletes, who will bring glory to the state/Nation in National/International sports Competitions and continuously working for the development of the sports with hard work, leadership qualities, sportsmanship and life dedicated Service in the filed of Sports"]', '[]', '["Application Should be Submitted With in the Stapled Date"]', NULL, NULL, 'https://dyes.karnataka.gov.in/en', true, '2026-10-30 16:55:56.458552+00', '378bd4e7-0daf-4a9b-bb60-7e75795b0603', 'ಜೀವಮಾನ ಸಾಧನೆ ಪ್ರಶಸ್ತಿ ಗೆ ಅರ್ಜಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಕರ್ನಾಟಕವನ್ನು ಪ್ರತಿನಿಧಿಸಿ ಕ್ರೀಡೆಯಲ್ಲಿ ಅತ್ಯುನ್ನತ ಸಾಧನೆ ಮಾಡುವ ಕರ್ನಾಟಕದ ಕ್ರೀಡಾಪಟುಗಳಿಗೆ 20 ವರ್ಷಗಳು ತರಬೇತಿ ನೀಡಿ ಸಾಧನೆ ಮಾಡುವ ತರಬೇತುದಾರರರಿಗೆ', NULL, NULL, NULL, NULL, NULL, '["ಕ್ರೀಡಾ ಕ್ಷೇತ್ರದಲ್ಲಿ ರಾಷ್ಟ್ರೀಯ/ಅಂತರಾಷ್ಟ್ರೀಯ ಕ್ರೀಡೆಗಳಲ್ಲಿ ರಾಜ್ಯ/ರಾಷ್ಟ ಕ್ಕೆ ಕೀರ್ತಿ ತರುವ ಕ್ರೀಡಾಪಟುಗಳನ್ನು ರೂಪಿಸಿ ಕೊಡುಗೆಯಾಗಿ ನೀಡಿ ಹಾಗೂ ಕ್ರೀಡಾ ಕ್ಷೇತ್ರದ ಅಭಿವೃದ್ದಿಗಾಗಿ ನಿರಂತರವಾಗಿ ಶ್ರಮಿಸುತ್ತಿರುವ, ನಾಯಕತ್ವ ಗುಣ ಕ್ರೀಡಾ ಮನೋಭವ ಶಿಸ್ತು ಬದ್ದ ಜೀವನಕ್ಕೆ ಮಾದರಿಯಾದ 20 ವರ್ಷಗಳ ಅವಧಿಯಲ್ಲಿ ಸೇವೆ ಸಲ್ಲಿಸಿದ ಕರ್ನಾಟಕದ ತರಬೇತುದಾರರಿಗೆ."]', '["ನಿಗಧಿತ ದಿನಾಂಕದೊಳಗೆ ಅರ್ಜಿಸಲ್ಲಿಸಬೇಕು"]', 1, '["ತರಬೇತಿ ನೀಡಿದ ಕ್ರೀಡಾಟಪುಗಳ ಸಾಧನೆ, ಅಧಿಕೃತ ಕ್ರೀಡಾಕೂಟಗಳಲ್ಲಿ ವಿತರಿಸಲಾದ ಕ್ರೀಡಾ ಪ್ರಮಾಣ ಪತ್ರಗಳು / ಪೂರಕ ದಾಖಲೆಗಳು"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('ba3ba5d3-2154-4b21-85ba-146dd6140427', 'DEPARTMENT-OF-YOUTH-7', '7f8d398a-7ac3-425b-bdc4-df5bd5944b47', 'Application for Sports Scholarship', 'General', 0, 'for Sports Person Studying 6th Standard to 10th Standard', '["Sports certificates Issued by Competitions Authority and Relevant Documents to be Attached"]', '["Athletes Studying in 6th Standard to 10 Standard should win Gold Medal in State Level Recognized Competition , Representing Karnataka at National and International level and won any medals/ Participation"]', '[]', '["Application Should be Submitted With in the Stapled Date"]', NULL, NULL, 'https://dyes.karnataka.gov.in/en', true, '2026-10-30 16:55:56.458552+00', '378bd4e7-0daf-4a9b-bb60-7e75795b0603', 'ಕ್ರೀಡಾ ವಿದ್ಯಾರ್ಥಿ ವೇತನ ಅರ್ಜಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '6 ರಿಂದ 10 ನೇ ತರಗತಿ ಓದುತ್ತಿರುವ ವಿದ್ಯಾರ್ಥಿ ಗಳಿಗೆ ಮಾತ್ರ', NULL, NULL, NULL, NULL, NULL, '["ರಾಜ್ಯ ಮಟ್ಟದಲ್ಲಿ ಚಿನ್ನದ ಪದಕ ವಿಜೇತರಾದ ಕ್ರೀಡಾಪಟುಗಳು ಹಾಗೂ ರಾಷ್ಟ್ರೀಯ /ಅಂತರಾಷ್ಟ್ರೀಯ ಮಟ್ಟದಲ್ಲಿ ಭಾಗವಹಿಸುವುದು/ಪದಕ ವಿಜೇತರಾದ ಕರ್ನಾಟಕದ ಕ್ರೀಡಾಪಟುಗಳಿಗೆ ನೀಡಲಾಗುವುದು."]', '["ನಿಗಧಿತ ದಿನಾಂಕದೊಳಗೆ ಅರ್ಜಿಸಲ್ಲಿಸಬೇಕು"]', 1, '["ಅಧಿಕೃತ ಕ್ರೀಡಾಕೂಟಗಳಲ್ಲಿ ವಿತರಿಸಲಾದ ಕ್ರೀಡಾ ಪ್ರಮಾಣ ಪತ್ರಗಳು / ಪೂರಕ ದಾಖಲೆಗಳು"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('26aedfc6-b93a-4611-9c70-750b03756464', 'DEPARTMENT-OF-YOUTH-6', '7f8d398a-7ac3-425b-bdc4-df5bd5944b47', 'Application for Fess Reimbursment', 'General', 0, 'for Sports Person Studying PUC to Post Graduation', '["Sports certificates Issued by Competitions Authority and Relevant Documents to be Attached"]', '["Athletes Representing Karnataka. who have won any medals at the National level / Athletes won medals at the International level/ Participation are Considered"]', '[]', '["Application Should be Submitted With in the Stapled Date"]', NULL, NULL, 'https://dyes.karnataka.gov.in/en', true, '2026-10-30 16:55:56.458552+00', '378bd4e7-0daf-4a9b-bb60-7e75795b0603', 'ಶೈಕ್ಷಣಿಕ ಶುಲ್ಕ ಮರು ಪಾವತಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಪಿಯುಸಿ ಹಂತದಿಂದ ಸ್ನಾತಕೋತ್ತರ ಪದವಿ ಹಂತದ ಕ್ರೀಡಾಪಟುಗಳಿಗೆ ಮಾತ್ರ', NULL, NULL, NULL, NULL, NULL, '["ರಾಷ್ಟ್ರೀಯ ಮಟ್ಟದಲ್ಲಿ ಪದಕ ವಿಜೇತರಾದ ಕ್ರೀಡಾಪಟುಗಳು ಹಾಗೂ ಅಂತರಾಷ್ಟ್ರೀಯ ಮಟ್ಟದಲ್ಲಿ ಭಾಗವಹಿಸುವುದು/ಪದಕ ವಿಜೇತರಾದ ಕರ್ನಾಟಕದ ಕ್ರೀಡಾಪಟುಗಳಿಗೆ ನೀಡಲಾಗುವುದು."]', '["ನಿಗಧಿತ ದಿನಾಂಕದೊಳಗೆ ಅರ್ಜಿಸಲ್ಲಿಸಬೇಕು"]', 1, '["ಅಧಿಕೃತ ಕ್ರೀಡಾಕೂಟಗಳಲ್ಲಿ ವಿತರಿಸಲಾದ ಕ್ರೀಡಾ ಪ್ರಮಾಣ ಪತ್ರಗಳು / ಪೂರಕ ದಾಖಲೆಗಳು"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('0ece0b16-7762-4f82-a746-35ac1e9f6ae6', 'DEPARTMENT-OF-YOUTH-5', '7f8d398a-7ac3-425b-bdc4-df5bd5944b47', 'Karnataka Kreda Rathna Award', 'General', 0, 'To Encourage and Honor Rural Sports and Athletes in the state along with other sports.', '["Certificate of Participation in Rural Sports, Photographs, Media reports, letters from organizers Sports certificates/supporting documents distributed at official sports events in other sports"]', '["For Sportspersons who have made achievements in 5 years in Indigenous, traditional sports in the Rural area of the State in other Games Athletes Represnting Karnataka Achived higst Performnac in Last 5 Years Winning Medals /participating in Reconzied National / International Sports Compettion Best Highst Performance of 3 Years of the Athletes to be Considered"]', '[]', '["Application Should be Submitted With in the Stapled Date"]', NULL, NULL, 'https://dyes.karnataka.gov.in/en', true, '2026-10-30 16:55:56.458552+00', '378bd4e7-0daf-4a9b-bb60-7e75795b0603', 'ಕರ್ನಾಟಕ ಕ್ರೀಡಾ ರತ್ನ ಪ್ರಶಸ್ತಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ರಾಜ್ಯದ ಗ್ರಾಮೀಣ ಕ್ರೀಡೆ ಮತ್ತು ಕ್ರೀಡಾಪಟುಗಳಿಗೆ ಇತರೆ ಕ್ರೀಡೆಗಳೊಡನೆ ಪ್ರೋತ್ಸಾಹ ನೀಡಿ ಗೌರವಿಸುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ರಾಜ್ಯದ ಗ್ರಾಮೀಣ ಕ್ರೀಡೆಯ ಅಭಿವೃದ್ದಿಗಾಗಿ ಸ್ಥಳೀಯ ಮತ್ತು ಪಾರಂಪರಿಕ ಕ್ರೀಡೆಗಳ ಲ್ಲಿ ಸಾಧಬೆ ಮಾಡಿದ ಕ್ರೀಡಾಟಪುಗಳಿಗೆ ಹಾಗೂ ಇತರೆ ಕ್ರೀಡೆಗಲ್ಲಿ ರಾಷ್ಟ್ರೀಯ ಮತ್ತು ಅಂತರಾಷ್ಟ್ರೀಯ ಮಟ್ಟದಲ್ಲಿ 5 ವರ್ಷಗಳ ಕ್ರೀಡಾ ಸಾಧನೆಗಳಲ್ಲಿ 3 ವರ್ಷಗಳ ಅತ್ಯುನ್ನತ ಕ್ರೀಡಾ ಸಾಧನೆ ಯನ್ನ ಮಾಡುವ ಪದಕ ವಿಜೇತ/ ಭಾಗವಹಿಸುವ ಕರ್ನಾಟಕದ ಕ್ರೀಡಾಪಟುಗಳಿಗೆ ನೀಡಲಾಗುವುದು"]', '["ನಿಗಧಿತ ದಿನಾಂಕದೊಳಗೆ ಅರ್ಜಿಸಲ್ಲಿಸಬೇಕು"]', 1, '["ಗ್ರಾಮೀಣ ಕ್ರೀಡೆಯಲ್ಲಿ ಭಾಗವಹಿಸಿದ ಬಗ್ಗೆ ಪ್ರಮಾಣ ಪತ್ರ , ಛಾಯಾಚಿತ್ರ, ಮಾಧ್ಯಮ ವರದಿ, ಸಂಘಟಕರಿಂದ ಪತ್ರಗಳು ಇತರೆ ಕ್ರೀಡೆಗಳಲ್ಲಿ ಅಧಿಕೃತ ಕ್ರೀಡಾಕೂಟಗಳಲ್ಲಿ ವಿತರಿಸಲಾದ ಕ್ರೀಡಾ ಪ್ರಮಾಣ ಪತ್ರಗಳು / ಪೂರಕ ದಾಖಲೆಗಳು"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('fa304be1-cac4-430b-8c9d-7299f8beb836', 'DEPARTMENT-OF-YOUTH-4', '7f8d398a-7ac3-425b-bdc4-df5bd5944b47', 'Karnataka Kreda Poshaka Award', 'General', 0, 'The Karnataka Posaka Award will be given to Recognize and encourage Institutions who Contributed in over all Development of Sports', '["Relevant certificate of National International Sports Person under training , Identify Talent National / International Athletes , Training Creation of Sports infrastructure Financial Assistance, Scholarship and Employment"]', '["The Karnataka Posaka Award will be given to Recognize and encourage Institutions who Contributed in over all Development of (Identify Talent National / International Athletes , Training Creation of Sports infrastructure Financial Assistance, Scholarship and Employment, Orginising Sports Meet ) in the Field Sports in Karnataka."]', '[]', '["Application Should be Submitted With in the Stapled Date"]', NULL, NULL, 'https://dyes.karnataka.gov.in/en', true, '2026-10-30 16:55:56.458552+00', '378bd4e7-0daf-4a9b-bb60-7e75795b0603', 'ಕರ್ನಾಟಕ ಕ್ರೀಡಾ ಪೋಷಕ ಪ್ರಶಸ್ತಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಕರ್ನಾಟಕ ರಾಜ್ಯದ ಕ್ರೀಡಾ ಪೋಷಕರಿಗೆ ಪ್ರೋತ್ಸಾಹ ನೀಡುವ ಉದ್ದೇಶದಿಂದ ಕರ್ನಾಟಕ ಕ್ರೀಡಾ ಪೋಷಕ ಪ್ರಶಸ್ತಿಯನ್ನು ನೀಡಿ ಗೌರವಿಸಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕ ರಾಜ್ಯದ ಕ್ರೀಡಾ ಕ್ಷೇತ್ರದಲ್ಲಿನ ಪ್ರತಿಭೆಯನ್ನು ಗುರುತಿಸುವುದು, ರಾಷ್ಟ್ರೀಯ ಮಟ್ಟದಲ್ಲಿ ಹಾಗೂ ಅಂತರಾಷ್ಟ್ರೀಯ ಮಟ್ಟದಲ್ಲಿ ಕ್ರೀಡಾಪಟುಗಳ ತರಬೇತಿ, ಕ್ರೀಡಾ ಮೂಲಸೌಕರ್ಯ ಸೃಷ್ಟಿ, ಆರ್ಥಿಕ ನೆರವು, ವಿದ್ಯಾರ್ಥಿವೇತನ ಮತ್ತು ಉದ್ಯೋಗ ದಲ್ಲಿ ಕೊಡುಗೆ ನೀಡಿ ಕ್ರೀಡಾಕೂಟಗಳ ಸಂಘಟನೆ, ಕ್ರೀಡಾ ಅಭಿವೃದ್ದಿಗೆ ತೊಡಗಿಸಿಕೊಂಡಿರುವ ಸಂಸ್ಥೆಗಳನ್ನು ಗುರುತಿಸಿ ಪ್ರೋತ್ಸಾಹಿಸಲು ಕರ್ನಾಟಕ ಪೋಷಕ ಪ್ರಶಸ್ತಿಯನ್ನು ನೀಡಲಾಗುವುದು."]', '["ನಿಗಧಿತ ದಿನಾಂಕದೊಳಗೆ ಅರ್ಜಿಸಲ್ಲಿಸಬೇಕು"]', 1, '["ತರಬೇತಿ ಪಡೆಯುತ್ತಿರುವ ರಾಷ್ಟ್ರೀಯ ಅಂತರರಾಷ್ಟ್ರೀಯ ಕ್ರೀಡಾಪಟುವಿನ ಸಂಬಂಧಿತ ಪ್ರಮಾಣಪತ್ರ, ಪ್ರತಿಭೆ ಗುರುತಿಸುವಿಕೆ ರಾಷ್ಟ್ರೀಯ / ಅಂತರರಾಷ್ಟ್ರೀಯ ಕ್ರೀಡಾಪಟುಗಳು, ತರಬೇತಿ ಕ್ರೀಡಾ ಮೂಲಸೌಕರ್ಯಗಳ ಸೃಷ್ಟಿ ಆರ್ಥಿಕ ನೆರವು, ವಿದ್ಯಾರ್ಥಿವೇತನ ಮತ್ತು ಉದ್ಯೋಗ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('85d46eff-f82b-4237-a3f4-bb7ccc2e4bf8', 'DEPARTMENT-OF-YOUTH-3', '7f8d398a-7ac3-425b-bdc4-df5bd5944b47', 'Application for Ekalavya Award', 'General', 0, 'Athletes Representing Karnataka. who have Achieved Highest Performance in the national / international level', '["Sports certificates Issued by Competitions Authority and Relevant Documents to be Attached"]', '["Athletes Representing Karnataka Achieved highest Performance in Last 5 Years Winning Medals /participating in Recognized National / International Sports Competition Best Highest Performance of 3 Years of the Athletes to be Considered"]', '[]', '["Application Should be Submitted With in the Stapled Date"]', NULL, NULL, 'https://dyes.karnataka.gov.in/en', true, '2026-10-30 16:55:56.458552+00', '378bd4e7-0daf-4a9b-bb60-7e75795b0603', 'ಏಕಲವ್ಯ ಪ್ರಶಸ್ತಿ ಗೆ ಅರ್ಜಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಕರ್ನಾಟಕವನ್ನು ಪ್ರತಿನಿಧಿಸಿ ಕ್ರೀಡೆಯಲ್ಲಿ ಅತ್ಯುನ್ನತ ಸಾಧನೆ ಮಾಡಿದ ಕರ್ನಾಟಕದ ಕ್ರೀಡಾಪಟುಗಳಿಗೆ .', NULL, NULL, NULL, NULL, NULL, '["ರಾಷ್ಟ್ರೀಯ ಮತ್ತು ಅಂತರಾಷ್ಟ್ರೀಯ ಮಟ್ಟದಲ್ಲಿ 5 ವರ್ಷಗಳ ಕ್ರೀಡಾ ಸಾಧನೆಗಳಲ್ಲಿ 3 ವರ್ಷಗಳ ಅತ್ಯುನ್ನತ ಕ್ರೀಡಾ ಸಾಧನೆ ಯನ್ನ ಮಾಡುವ ಪದಕ ವಿಜೇತ/ ಭಾಗವಹಿಸುವ ಕರ್ನಾಟಕದ ಕ್ರೀಡಾಪಟುಗಳಿಗೆ ನೀಡಲಾಗುವುದು."]', '["ನಿಗಧಿತ ದಿನಾಂಕದೊಳಗೆ ಅರ್ಜಿಸಲ್ಲಿಸಬೇಕು"]', 1, '["ಅಧಿಕೃತ ಕ್ರೀಡಾಕೂಟಗಳಲ್ಲಿ ವಿತರಿಸಲಾದ ಕ್ರೀಡಾ ಪ್ರಮಾಣ ಪತ್ರಗಳು / ಪೂರಕ ದಾಖಲೆಗಳು"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('6b389b40-b175-43c4-bd1c-1118530cca82', 'DEPARTMENT-OF-YOUTH-2', '7f8d398a-7ac3-425b-bdc4-df5bd5944b47', 'Cash Award', 'General', 0, 'Cash awards to sportspersons who participated in official sports events at national and international level and won medals', '["Sports certificates Issued by Competitions Authority and Relevant Documents to be Attached"]', '["Cash awards will be given to the sportspersons who represent Karnataka in official sports events at national and international level and win medals for the years invited by the Department from time to time."]', '[]', '["Application Should be Submitted With in the Stapled Date"]', NULL, NULL, 'https://dyes.karnataka.gov.in/en', true, '2026-10-30 16:55:56.458552+00', '378bd4e7-0daf-4a9b-bb60-7e75795b0603', 'ನಗದು ಪುರಸ್ಕಾರ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ರಾಷ್ಟ್ರೀಯ ಮತ್ತು ಅಂತರಾಷ್ಟ್ರೀಯ ಮಟ್ಟದ ಅಧೀಕೃತ ಕ್ರೀಡಾಕೂಟಗಳಲ್ಲಿ ಭಾಗವಹಿಸಿ ಪದಕ ಪಡೆದ ಕ್ರೀಡಾಪಟುಗಳಿಗೆ ನಗದು ಪುರಸ್ಕಾರ', NULL, NULL, NULL, NULL, NULL, '["ರಾಷ್ಟ್ರೀಯ ಮತ್ತು ಅಂತರಾಷ್ಟ್ರೀಯ ಮಟ್ಟದ ಅಧೀಕೃತ ಕ್ರೀಡಾಕೂಟಗಳಲ್ಲಿ ಕರ್ನಾಟಕವನ್ನು ಪ್ರತಿನಿಧಿಸಿ ಪದಕ ಪಡೆಯುವಂತಹ ಕ್ರೀಡಾಪಟುಗಳಿಗೆ ಇಲಾಖೆಯಿಂದ ಕಾಲಕಾಲಕ್ಕೆ ಆಹ್ವಾನಿಸುವ ವರ್ಷಗಳಿಗೆ ನಗದು ಪುರಸ್ಕಾರವನ್ನು ನೀಡಲಾಗುವುದು."]', '["ನಿಗಧಿತ ದಿನಾಂಕದೊಳಗೆ ಅರ್ಜಿಸಲ್ಲಿಸಬೇಕು"]', 1, '["ಅಧಿಕೃತ ಕ್ರೀಡಾಕೂಟಗಳಲ್ಲಿ ವಿತರಿಸಲಾದ ಕ್ರೀಡಾ ಪ್ರಮಾಣ ಪತ್ರಗಳು / ಪೂರಕ ದಾಖಲೆಗಳು"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('e972ae98-9a48-40e3-b6d2-25c09848371a', 'DEPARTMENT-OF-YOUTH-1', '7f8d398a-7ac3-425b-bdc4-df5bd5944b47', 'Target Olympics', 'General', 0, 'Selection of most talented athletes of the state to target the and prepare them for the Olympics-2028. Performance based annual grant of Rs. 10.00 lakhs each for till 2028.', '["Sports certificates Issued by Competitions Authority and Relevant Documents to be Attached"]', '["Identify Talented Athletes in the state who have Potential to Perform to win Medals in the Olympic-2028 by nurturing them systematically with Financial and human resources to provided necessary training incentives to develop Identify sports talents through Sports Authority. Identify sports talents with National Medal Winners and International Medal Winners/ Participation considering there Previous 5 Year Performance"]', '[]', '["Application Should be Submitted With in the Stapled Date"]', NULL, NULL, 'https://dyes.karnataka.gov.in/en', true, '2026-10-30 16:55:56.458552+00', '378bd4e7-0daf-4a9b-bb60-7e75795b0603', 'ಗುರಿ ಒಲಂಪಿಕ್', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ರಾಜ್ಯದ ಅತ್ಯಂತ ಪ್ರತಿಭಾನ್ವಿತ ಕ್ರೀಡಾಪಟುಗಳನ್ನು ಗುರಿತಿಸಿ ಒಲಂಪಿಕ್ಸ್-2028ಕ್ಕೆ ಸಿದ್ದಗೊಳಿಸಲು ವಾರ್ಷಿಕ ತಲಾ 10.00 ಲಕ್ಷಗಳನ್ನು ಕ್ರೀಡಾ ಸಾಧನೆಗೆ ಅನುಗುಣವಾಗಿ ಅನುದಾನ ನೀಡುವುದು', NULL, NULL, NULL, NULL, NULL, '["ರಾಜ್ಯದಲ್ಲಿ ಪ್ರತಿಭಾನ್ವಿತ ಕ್ರೀಡಾಪಟುಗಳನ್ನು ಗುರುತಿಸಿ ಪದಕ ಸಾಧನೆ ಮಾಡುವ ಗುರಿ ಹೊಂದಿರುವ ಉತ್ತಮ ಸಾಧನೆ ತೊರುವ ಸಾಮರ್ಥ್ಯ ಹೊಂದಿರುವ ಕ್ರೀಡಾಪಟುಗಳನ್ನು ರೂಪಿಸಲು ಅಗತ್ಯವಾದ ತರಬೇತಿ ಪ್ರೋತ್ಸಾಹ ಕಲ್ಪಿಸುವ ನಿಟ್ಟಿನಲ್ಲಿ ಆರ್ಥಿಕ ಮತ್ತು ಮಾನವ ಸಂಪನ್ಮೂಲವನ್ನು ಪರಿಣಮಕಾರಿಯಾಗಿ ಬಳಸಿಕೊಂಡು ಕ್ರೀಡಾ ಪ್ರಾಧಿಕಾರದಿಂದ ಮಾನ್ಯತೆ ಪಡೆದ ಸಂಸ್ಥೆಗಳ ಮೂಲಕ ಕ್ರೀಡಾ ಪ್ರತಿಭೆಗಳನ್ನು ಗುರುತಿಸಿ ವ್ಯವಸ್ಥಿತ ರೀತಿಯಲ್ಲಿ ಪೋಷಣೆ ಮಾಡಿ ರಾಷ್ಟ್ರ ಮತ್ತು ಅಂತಾರಾಷ್ಟ್ರ ಮಟ್ಟದಲ್ಲಿ ಪ್ರತಿನಿಧಿಸುವ ಮೂಲಕ ಒಲಂಪಿಕ್ಸ್ ನಲ್ಲಿ ಪದಕ ಸಾಧನೆ ಮಾಡುವುದು."]', '["ನಿಗಧಿತ ದಿನಾಂಕದೊಳಗೆ ಅರ್ಜಿಸಲ್ಲಿಸಬೇಕು"]', 1, '["ಅಧಿಕೃತ ಕ್ರೀಡಾಕೂಟಗಳಲ್ಲಿ ವಿತರಿಸಲಾದ ಕ್ರೀಡಾ ಪ್ರಮಾಣ ಪತ್ರಗಳು / ಪೂರಕ ದಾಖಲೆಗಳು"]', NULL, NULL, NULL);
