INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('a594ddcb-eefa-437a-8f66-9c66c22e7dff', 'REVENUE-DEPARTMENT-48', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'ATLAS', 'General', 7, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (ATLAS)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಅಟ್ಲಾಸ್', NULL, NULL, NULL, NULL, NULL, 35.00, NULL, 'ಅಟ್ಲಾಸ್ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3051');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('a43edd39-8919-4787-ac22-e6821a365ff6', 'FINANCE-DEPARTMENT-3', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Renewal of Discontinued Licences', 'Public', 45, 'The Renewal of Discontinued License module facilitates the online renewal or revival of discontinued licences through the Excise E-Services application. This service enables a licence holder whose licence has been discontinued to continue the licence by submitting a renewal application and paying the applicable renewal amount, including the renewal amount due for the discontinued year. The applicant can enter the required details, upload supporting documents, and submit the application online.', '["Other Documents", "Original/Duplicate Copy of the License for the Discontinued Year", "A Notarized Affidavit Sworn by the Licensee Confirming That the License Has Not Been Transferred as per Rule 17-A and B", "Certificate Issued by the Deputy Commissioner of Excise Regarding the License Not Being Shifted Within the District Jurisdiction", "License Fee Payment Details as per Rules 8 and 8-B (Original Challan)", "Applicant PAN Card (PDF)", "Blueprint of Old Licensed Place", "In Case the License Is Lost, a Copy of the First Information Report (FIR) and a Report Regarding Actions Taken to Issue a Duplicate License", "Certificate Issued by the Range Inspector and Deputy Commissioner of Excise Regarding Authentication of the Discontinued License", "Certificate of License Surrendered After Expiry of the License Period", "Applicant Address Proof", "Added Photo Signature", "Licensee Photo", "Blueprint of Buildings Within a 100-Meter Radius", "Building Owner Consent / Rent Agreement / Katha", "A Notarized Affidavit Sworn by the Licensee", "Family Tree / Surviving Member Certificate (If Applicable)", "Succession Certificates (If Applicable)"]', '["Valid retailer Licence"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ನವೀಕರಣಗೊಳ್ಳದೆ ರದ್ದಾದ ಪರವಾನಗಿಗಳ ನವೀಕರಣ', 'The Renewal of Discontinued License module facilitates the online renewal or revival of discontinued licences through the Excise E-Services application. This service enables a licence holder whose licence has been discontinued to continue the licence by submitting a renewal application and paying the applicable renewal amount, including the renewal amount due for the discontinued year. The applicant can enter the required details, upload supporting documents, and submit the application online.', NULL, 'State Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಸ್ಥಗಿತಗೊಂಡ ಪರವಾನಗಿಗಳ ನವೀಕರಣ ಘಟಕವು ಅಬಕಾರಿ ಇ-ಸೇವೆಗಳ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ಸ್ಥಗಿತಗೊಂಡ ಪರವಾನಗಿಗಳನ್ನು ಆನ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಇತರೆ ದಾಖಲೆಗಳು", "ಸ್ಥಗಿತಗೊಂಡ ವರ್ಷದ ಪರವಾನಗಿಯ ಮೂಲ ಪ್ರತಿ/ನಕಲಿ ಪ್ರತಿ", "ನಿಯಮ 17-A ಮತ್ತು 17-Bರ ಪ್ರಕಾರ ಪರವಾನಗಿಯನ್ನು ವರ್ಗಾಯಿಸಿಲ್ಲ ಎಂದು ಪರವಾನಗಿದಾರರು ಪ್ರಮಾಣೀಕರಿಸಿದ ನೋಟರಿಯಿಂದ ದೃಢೀಕರಿಸಿದ ಪ್ರಮಾಣಪತ್ರ (ಅಫಿಡವಿಟ್)", "ಜಿಲ್ಲಾ ವ್ಯಾಪ್ತಿಯೊಳಗೆ ಪರವಾನಗಿಯನ್ನು ಸ್ಥಳಾಂತರಿಸಿಲ್ಲ ಎಂಬುದಕ್ಕೆ ಅಬಕಾರಿ ಉಪ ಆಯುಕ್ತರು ನೀಡಿದ ಪ್ರಮಾಣಪತ್ರ", "ನಿಯಮ 8 ಮತ್ತು 8-Bರ ಪ್ರಕಾರ ಪಾವತಿಸಿದ ಪರವಾನಗಿ ಶುಲ್ಕದ ವಿವರಗಳು (ಮೂಲ ಚಲನ್)", "ಅರ್ಜಿದಾರರ ಪ್ಯಾನ್ ಕಾರ್ಡ್ (PDF)", "ಹಳೆಯ ಪರವಾನಗಿ ಪಡೆದ ಸ್ಥಳದ ನೀಲನಕ್ಷೆ", "ಪರವಾನಗಿ ಕಳೆದುಹೋಗಿದ್ದಲ್ಲಿ, ಪ್ರಥಮ ಮಾಹಿತಿ ವರದಿಯ (FIR) ಪ್ರತಿ ಹಾಗೂ ನಕಲಿ ಪರವಾನಗಿ ನೀಡಲು ಕೈಗೊಂಡ ಕ್ರಮಗಳ ವರದಿ", "ಸ್ಥಗಿತಗೊಂಡ ಪರವಾನಗಿಯ ದೃಢೀಕರಣಕ್ಕೆ ಸಂಬಂಧಿಸಿದಂತೆ ಅಬಕಾರಿ ವಲಯ ನಿರೀಕ್ಷಕರು ಮತ್ತು ಅಬಕಾರಿ ಉಪ ಆಯುಕ್ತರು ನೀಡಿದ ಪ್ರಮಾಣಪತ್ರ", "ಪರವಾನಗಿ ಅವಧಿ ಮುಗಿದ ನಂತರ ಪರವಾನಗಿಯನ್ನು ಹಿಂತಿರುಗಿಸಿರುವುದಕ್ಕೆ ಸಂಬಂಧಿಸಿದ ಪ್ರಮಾಣಪತ್ರ", "ಅರ್ಜಿದಾರರ ವಿಳಾಸದ ಪುರಾವೆ", "ಸೇರಿಸಲಾದ ಛಾಯಾಚಿತ್ರ ಮತ್ತು ಸಹಿ", "ಪರವಾನಗಿದಾರರ ಛಾಯಾಚಿತ್ರ", "100 ಮೀಟರ್ ವ್ಯಾಪ್ತಿಯಲ್ಲಿರುವ ಕಟ್ಟಡಗಳ ನೀಲನಕ್ಷೆ", "ಕಟ್ಟಡದ ಮಾಲೀಕರ ಒಪ್ಪಿಗೆ ಪತ್ರ / ಬಾಡಿಗೆ ಒಪ್ಪಂದ / ಖಾತಾ", "ಪರವಾನಗಿದಾರರು ಸಲ್ಲಿಸಿದ ನೋಟರಿಯಿಂದ ದೃಢೀಕರಿಸಿದ ಪ್ರಮಾಣಪತ್ರ (ಅಫಿಡವಿಟ್)", "ವಂಶವೃಕ್ಷ / ಉಳಿದಿರುವ ಕುಟುಂಬ ಸದಸ್ಯರ ಪ್ರಮಾಣಪತ್ರ (ಅನ್ವಯಿಸಿದಲ್ಲಿ)", "ವಾರಸುದಾರಿಕೆ ಪ್ರಮಾಣಪತ್ರಗಳು (ಅನ್ವಯಿಸಿದಲ್ಲಿ)"]', NULL, NULL, '1287');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('9d86bfa8-1397-43b1-847e-ffee4dfc8a6e', 'FINANCE-DEPARTMENT-2', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Transfer of licenses as per rule 17(A) & 17(B) of Karnataka Excise (General Conditions of Licenses) rules, 1967', 'Retailer', 40, 'The Transfer of Licences service under Rules 17(A) and 17(B) of the Karnataka Excise (General Conditions of Licences) Rules, 1967, allows the transfer of a licence while keeping the licensed shop unchanged and updating the licensee’s details.
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('105b2a1e-b538-45cf-9e9d-9851cefda0ff', 'FINANCE-DEPARTMENT-22', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'No-Objection Certificate to Export molasses to other states/UT', 'Supplier', 15, 'The No-Objection Certificate to Lift Molasses (Export) module enables licensees to submit an application for obtaining an NOC to lift molasses for export. The module supports online application submission, document upload, final submission, application tracking, and sequential processing through the concerned Excise Department officers.', '["Other Documents", "Request Letter", "Present Stock of Molasses at the Sugar Factory", "Sale Consent Letter from the Sugar Factory"]', '["Valid Molasses Licence"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಇತರ ರಾಜ್ಯಗಳು/ಕೇಂದ್ರಾಡಳಿತ ಪ್ರದೇಶಗಳಿಗೆ ಮೊಲಾಸಿಸ್ (ಕಬ್ಬಿನ ಕಾಕಂಬಿ) ರಫ್ತು ಮಾಡಲು ನಿರಾಕ್ಷೇಪಣಾ ಪತ್ರ', 'The No-Objection Certificate to Lift Molasses (Export) module enables licensees to submit an application for obtaining an NOC to lift molasses for export. The module supports online application submission, document upload, final submission, application tracking, and sequential processing through the concerned Excise Department officers.', NULL, 'State Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಕಾಕಂಬಿಯನ್ನು ರಫ್ತು ಮಾಡಲು ಎತ್ತುವಳಿ ಮಾಡುವ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC) ಘಟಕವು ಪರವಾನಗಿದಾರರಿಗೆ ರಫ್ತಿಗಾಗಿ ಕಾಕಂಬಿಯನ್ನು ಎತ್ತುವಳಿ ಮಾಡಲು NOC ಪಡೆಯುವ ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಲು ಅವಕಾಶ ಕಲ್ಪಿಸುತ್ತದೆ. ಈ ಘಟಕವು ಆನ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಇತರೆ ದಾಖಲೆಗಳು", "ಕೋರಿಕೆ ಪತ್ರ", "ಸಕ್ಕರೆ ಕಾರ್ಖಾನೆಯಲ್ಲಿರುವ ಪ್ರಸ್ತುತ ಮೊಲಾಸಿಸ್ ದಾಸ್ತಾನು", "ಸಕ್ಕರೆ ಕಾರ್ಖಾನೆಯಿಂದ ನೀಡಲಾದ ಮಾರಾಟ ಒಪ್ಪಿಗೆ ಪತ್ರ"]', NULL, NULL, '1390');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('5282d1be-2b19-4cae-a0fe-4aa6a2f31a28', 'FINANCE-DEPARTMENT-25', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Concurrence for Winery for Export of Wine(Outside the Country)', 'Supplier', 10, 'The Concurrence Module enables Wineries to obtain prior concurrence approval for the export of liquor/products outside the country. The approved concurrence remains valid for one year, and export permits can be generated only against the available approved concurrence quantity. Based on previous concurrence utilization, the approving authority may review and reduce the requested concurrence quantity before granting approval. This module streamlines the concurrence approval process, ensures regulatory compliance, prevents unauthorized exports, and enhances transparency and efficiency in export management.', '["--NA----"]', '["Valid Winery License"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ವೈನ್ ರಫ್ತಿಗಾಗಿ (ದೇಶದ ಹೊರಗೆ) ವೈನರಿಗೆ ಒಪ್ಪಿಗೆ', 'The Concurrence Module enables Wineries to obtain prior concurrence approval for the export of liquor/products outside the country. The approved concurrence remains valid for one year, and export permits can be generated only against the available approved concurrence quantity. Based on previous concurrence utilization, the approving authority may review and reduce the requested concurrence quantity before granting approval. This module streamlines the concurrence approval process, ensures regulatory compliance, prevents unauthorized exports, and enhances transparency and efficiency in export management.', NULL, 'State Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಕನ್ಕರೆನ್ಸ್ (Concurrence) ಘಟಕವು ವೈನರಿಗಳಿಗೆ ಮದ್ಯ ಮತ್ತು ಇತರ ಉತ್ಪನ್ನಗಳನ್ನು ದೇಶದ ಹೊರಗೆ ರಫ್ತು ಮಾಡಲು ಪೂರ್ವಾನುಮೋದನೆ ಪಡೆಯಲು ಅವಕಾಶ ಕಲ್ಪಿಸುತ್ತದೆ. ಅನುಮೋದಿತ ಕನ್ಕರೆನ್ಸ್ ಒಂದು ವರ್ಷದವರೆಗೆ ಮಾನ್ಯವಾಗಿರುತ್ತದೆ. ಲಭ್ಯವಿರುವ ಅನುಮೋದಿತ ಕನ್ಕರೆನ್ಸ್ ಪ್ರಮಾಣದ ಮಿತಿಯೊಳಗೆ ಮಾತ್ರ ರಫ್ತು ಪರವಾನಗಿಗಳನ್ನು ಸೃಷ್ಟಿಸಬಹುದು. ಹಿಂದಿನ ಕನ್ಕರೆನ್ಸ್ ಬಳಕೆಯ ಆಧಾರದ ಮೇಲೆ, ಅನುಮೋದನೆ ನೀಡುವ ಮೊದಲು ಸಂಬಂಧಪಟ್ಟ ಪ್ರಾಧಿಕಾರವು ಕೋರಲಾದ ಕನ್ಕರೆನ್ಸ್ ಪ್ರಮಾಣವನ್ನು ಪರಿಶೀಲಿಸಿ ಕಡಿಮೆ ಮಾಡಬಹುದು. ಈ ಘಟಕವು ಕನ್ಕರೆನ್ಸ್ ಅನುಮೋದನಾ ಪ್ರಕ್ರಿಯೆಯನ್ನು ಸರಳಗೊಳಿಸುವುದರ ಜೊತೆಗೆ, ನಿಯಮಗಳ ಪಾಲನೆಯನ್ನು ಖಚಿತಪಡಿಸುತ್ತದೆ, ಅನಧಿಕೃತ ರಫ್ತನ್ನು ತಡೆಯುತ್ತದೆ ಮತ್ತು ರಫ್ತು ನಿರ್ವಹಣೆಯಲ್ಲಿ ಪಾರದರ್ಶಕತೆ ಹಾಗೂ ಕಾರ್ಯಕ್ಷಮತೆಯನ್ನು ಹೆಚ್ಚಿಸುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '1411');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('664be495-fb37-4b56-8631-971fb9841beb', 'REVENUE-DEPARTMENT-70', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'CONSOLIDATION KJP', 'General', 0, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (CONSOLIDATION KJP)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಕನ್ಸೊಲಿಡೇಷನ್ ಕೆ.ಜೆ.ಪಿ', NULL, NULL, NULL, NULL, NULL, 20.00, NULL, 'ಕನ್ಸೊಲಿಡೇಷನ್ ಕೆ.ಜೆ.ಪಿ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3087');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('b0de91e5-af06-4df1-bb2c-c5c73d8a0330', 'FINANCE-DEPARTMENT-28', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Concurrence for Distillery for Export of Liquor(Outside the State)', 'Supplier', 7, 'The Concurrence Module enables Distilleries to obtain prior concurrence approval for the export of liquor/products outside the state. During the application process, the user must select the applicable Concurrence Type, such as Civilian,Defence ,Paramilitary, based on the export requirement. The approved concurrence remains valid for one year, and export permits can be generated only against the available approved concurrence quantity. Based on previous concurrence utilization, the approving authority may review and reduce the requested concurrence quantity before granting approval. This module streamlines the concurrence approval process, ensures regulatory compliance, prevents unauthorized exports, and enhances transparency and efficiency in export management.', '["--NA----"]', '["Valid Distillery License"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಮದ್ಯ ರಫ್ತಿಗಾಗಿ (ರಾಜ್ಯದ ಹೊರಗೆ) ಡಿಸ್ಟಿಲರಿಗೆ ಒಪ್ಪಿಗೆ', 'The Concurrence Module enables Distilleries to obtain prior concurrence approval for the export of liquor/products outside the state. During the application process, the user must select the applicable Concurrence Type, such as Civilian,Defence ,Paramilitary, based on the export requirement. The approved concurrence remains valid for one year, and export permits can be generated only against the available approved concurrence quantity. Based on previous concurrence utilization, the approving authority may review and reduce the requested concurrence quantity before granting approval. This module streamlines the concurrence approval process, ensures regulatory compliance, prevents unauthorized exports, and enhances transparency and efficiency in export management.', NULL, 'District Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಕನ್ಕರೆನ್ಸ್ (Concurrence) ಘಟಕವು ಡಿಸ್ಟಿಲರಿಗಳಿಗೆ ರಾಜ್ಯದ ಹೊರಗೆ ಮದ್ಯ ಮತ್ತು ಇತರ ಉತ್ಪನ್ನಗಳನ್ನು ರಫ್ತು ಮಾಡಲು ಪೂರ್ವಾನುಮೋದನೆ ಪಡೆಯಲು ಅವಕಾಶ ಕಲ್ಪಿಸುತ್ತದೆ. ಅರ್ಜಿ ಸಲ್ಲಿಸುವ ಸಂದರ್ಭದಲ್ಲಿ, ರಫ್ತು ಅವಶ್ಯಕತೆಗೆ ಅನುಗುಣವಾಗಿ ಬಳಕೆದಾರರು ಸಿವಿಲಿಯನ್ (Civilian), ಡಿಫೆನ್ಸ್ (Defence) ಅಥವಾ ಅರೆಸೈನಿಕ ಪಡೆ (Paramilitary) ಮುಂತಾದ ಸೂಕ್ತ ಕನ್ಕರೆನ್ಸ್ ಪ್ರಕಾರವನ್ನು ಆಯ್ಕೆ ಮಾಡಬೇಕು. ಅನುಮೋದಿತ ಕನ್ಕರೆನ್ಸ್ ಒಂದು ವರ್ಷದವರೆಗೆ ಮಾನ್ಯವಾಗಿರುತ್ತದೆ. ಲಭ್ಯವಿರುವ ಅನುಮೋದಿತ ಕನ್ಕರೆನ್ಸ್ ಪ್ರಮಾಣದ ಮಿತಿಯೊಳಗೆ ಮಾತ್ರ ರಫ್ತು ಪರವಾನಗಿಗಳನ್ನು ಸೃಷ್ಟಿಸಬಹುದು. ಹಿಂದಿನ ಕನ್ಕರೆನ್ಸ್ ಬಳಕೆಯ ಆಧಾರದ ಮೇಲೆ, ಅನುಮೋದನೆ ನೀಡುವ ಮೊದಲು ಸಂಬಂಧಪಟ್ಟ ಪ್ರಾಧಿಕಾರವು ಕೋರಲಾದ ಕನ್ಕರೆನ್ಸ್ ಪ್ರಮಾಣವನ್ನು ಪರಿಶೀಲಿಸಿ ಕಡಿಮೆ ಮಾಡಬಹುದು. ಈ ಘಟಕವು ಕನ್ಕರೆನ್ಸ್ ಅನುಮೋದನಾ ಪ್ರಕ್ರಿಯೆಯನ್ನು ಸರಳಗೊಳಿಸುವುದರ ಜೊತೆಗೆ, ನಿಯಮಗಳ ಪಾಲನೆಯನ್ನು ಖಚಿತಪಡಿಸುತ್ತದೆ, ಅನಧಿಕೃತ ರಫ್ತನ್ನು ತಡೆಯುತ್ತದೆ ಮತ್ತು ರಫ್ತು ನಿರ್ವಹಣೆಯಲ್ಲಿ ಪಾರದರ್ಶಕತೆ ಹಾಗೂ ಕಾರ್ಯಕ್ಷಮತೆಯನ್ನು ಹೆಚ್ಚಿಸುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '1413');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('97dc76de-9a47-4fbc-855e-684e98149c36', 'FINANCE-DEPARTMENT-37', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Import Permit of spirit', 'Supplier', 5, 'The Import Permit of Spirit service enables applicants to submit an online application for obtaining an import permit for spirit through the Excise e-Services portal. The applicant can fill in the required details, submit the application, upload supporting documents, and track the application status. The submitted application is processed through the concerned Department login, where officers can review the application, verify the required details, update necessary information, and complete the approval process using Digital Signature For importing spirit from outside the for use in distillery production.', '["Request Letter", "Authorization from KSBCL", "NOC for Import", "Export NOC"]', '["Valid Supplier License"]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', NULL, 'ಸ್ಪಿರಿಟ್ ಆಮದು ಪರವಾನಗಿ', 'The Import Permit of Spirit service enables applicants to submit an online application for obtaining an import permit for spirit through the Excise e-Services portal. The applicant can fill in the required details, submit the application, upload supporting documents, and track the application status. The submitted application is processed through the concerned Department login, where officers can review the application, verify the required details, update necessary information, and complete the approval process using Digital Signature For importing spirit from outside the for use in distillery production.', NULL, 'Excise level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಸ್ಪಿರಿಟ್ ಆಮದು ಪರವಾನಗಿ ಸೇವೆಯು ಡಿಸ್ಟಿಲರಿ ಉತ್ಪಾದನೆಯಲ್ಲಿ ಬಳಸಲು ರಾಜ್ಯದ ಹೊರಗಿನಿಂದ ಸ್ಪಿರಿಟ್ ಆಮದು ಮಾಡಿಕೊಳ್ಳುವ ಉದ್ದೇಶಕ್ಕಾಗಿ ಅಬಕಾರಿ ಇ-ಸೇವೆಗಳ (Excise E-Services) ಪೋರ್ಟಲ್ ಮೂಲಕ ಆನ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ವಿನಂತಿ ಪತ್ರ", "KSBCL ನಿಂದ ಅಧಿಕೃತ ಅನುಮತಿ ಪತ್ರ", "ಆಮದು ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC)", "ರಫ್ತು ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC)"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('763be3e0-d9aa-40c1-b4bf-1ad8326158d6', 'FINANCE-DEPARTMENT-36', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Export Permit - Outside Country', 'Supplier', 8, 'This module facilitates Distilleries, Breweries, and Wineries in applying for export permits for the dispatch of liquor products outside the country. The system ensures that export permit applications are submitted only against valid Concurrence Permits with available approved quantity balances. It validates concurrence details, manages the export permit application process, and supports regulatory verification, approval, and issuance of permits in accordance with applicable excise rules.', '["Import Permit Document", "Concurrence for Export", "Export Duty Challan", "Warehouse Stock Position as on Date", "Chemical Report"]', '["Valid Molasses Licence"]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', NULL, 'ರಫ್ತು ಪರವಾನಗಿ - ದೇಶದ ಹೊರಗೆ', 'This module facilitates Distilleries, Breweries, and Wineries in applying for export permits for the dispatch of liquor products outside the country. The system ensures that export permit applications are submitted only against valid Concurrence Permits with available approved quantity balances. It validates concurrence details, manages the export permit application process, and supports regulatory verification, approval, and issuance of permits in accordance with applicable excise rules.', NULL, 'District Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ದೇಶದ ಹೊರಗೆ ರಫ್ತು ಪರವಾನಗಿ (Export Permit Outside Country) ಘಟಕವು ಡಿಸ್ಟಿಲರಿಗಳು, ಬ್ರೂವರಿಗಳು ಮತ್ತು ವೈನರಿಗಳಿಗೆ ಮದ್ಯದ ಉತ್ಪನ್ನಗಳನ್ನು ವಿದೇಶಗಳಿಗೆ ರವಾನಿಸಲು ರಫ್ತು ಪರವಾನಗಿಗಾಗಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಲು ಅವಕಾಶ ಕಲ್ಪಿಸುತ್ತದೆ. ಸಾಕಷ್ಟು ಅನುಮೋದಿತ ಪ್ರಮಾಣದ ಬಾಕಿ ಹೊಂದಿರುವ ಮಾನ್ಯ ಕನ್ಕರೆನ್ಸ್ ಪರವಾನಗಿಗಳ ಆಧಾರದ ಮೇಲೆ ಮಾತ್ರ ರಫ್ತು ಪರವಾನಗಿ ಅರ್ಜಿಗಳನ್ನು ಸಲ್ಲಿಸುವುದನ್ನು ಈ ವ್ಯವಸ್ಥೆಯು ಖಚಿತಪಡಿಸುತ್ತದೆ. ಇದು ಕನ್ಕರೆನ್ಸ್ ವಿವರಗಳನ್ನು ಪರಿಶೀಲಿಸುವುದರ ಜೊತೆಗೆ, ರಫ್ತು ಪರವಾನಗಿ ಅರ್ಜಿ ಪ್ರಕ್ರಿಯೆಯನ್ನು ನಿರ್ವಹಿಸುತ್ತದೆ ಹಾಗೂ ಅನ್ವಯಿಸುವ ಅಬಕಾರಿ ನಿಯಮಗಳಿಗೆ ಅನುಗುಣವಾಗಿ ನಿಯಂತ್ರಣಾತ್ಮಕ ಪರಿಶೀಲನೆ, ಅನುಮೋದನೆ ಮತ್ತು ಪರವಾನಗಿ ವಿತರಣೆಗೆ ಅನುಕೂಲ ಕಲ್ಪಿಸುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಆಮದು ಪರವಾನಗಿ ದಾಖಲೆ", "ರಫ್ತಿಗೆ ಸಮ್ಮತಿ ಪತ್ರ", "ರಫ್ತು ಸುಂಕ ಪಾವತಿ ಚಲನ್", "ದಿನಾಂಕದಂದು ಗೋದಾಮಿನಲ್ಲಿರುವ ದಾಸ್ತಾನು ಸ್ಥಿತಿಯ ವರದಿ", "ರಾಸಾಯನಿಕ ವರದಿ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('e3f0e5f7-36f6-4f1a-858e-104f2ee62cf7', 'FINANCE-DEPARTMENT-33', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'EVC - Excise Verification Certificate', '-----', 0, '-----', '["----"]', '["------"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'EVC - ಅಬಕಾರಿ ಪರಿಶೀಲನಾ ಪ್ರಮಾಣಪತ್ರ', '-----', NULL, '-------', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '2918');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('148b6a74-a540-4bde-b45e-b10a0c143176', 'REVENUE-DEPARTMENT-49', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'VILLAGE MAP', 'General', 7, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (VILLAGE MAP)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಗ್ರಾಮ ನಕಾಶೆ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಗ್ರಾಮ ನಕಾಶೆ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3052');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('fd26ab59-484e-4d3e-b402-735996faff96', 'FINANCE-DEPARTMENT-26', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Concurrence for Brewery for Export of Beer(Outside the Country)', 'Supplier', 10, 'The Concurrence Module enables Breweries to obtain prior concurrence approval for the export of liquor/products outside the country. The approved concurrence remains valid for one year, and export permits can be generated only against the available approved concurrence quantity. Based on previous concurrence utilization, the approving authority may review and reduce the requested concurrence quantity before granting approval. This module streamlines the concurrence approval process, ensures regulatory compliance, prevents unauthorized exports, and enhances transparency and efficiency in export management.', '["--NA----"]', '["Valid Brewery License"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಬಿಯರ್ ರಫ್ತಿಗಾಗಿ (ದೇಶದ ಹೊರಗೆ) ಬ್ರೂವರಿಯ ಸ್ಥಾಪನೆಗೆ ಒಪ್ಪಿಗೆ', 'The Concurrence Module enables Breweries to obtain prior concurrence approval for the export of liquor/products outside the country. The approved concurrence remains valid for one year, and export permits can be generated only against the available approved concurrence quantity. Based on previous concurrence utilization, the approving authority may review and reduce the requested concurrence quantity before granting approval. This module streamlines the concurrence approval process, ensures regulatory compliance, prevents unauthorized exports, and enhances transparency and efficiency in export management.', NULL, 'State Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಕನ್ಕರೆನ್ಸ್ (Concurrence) ಘಟಕವು ಬ್ರೂವರಿಗಳಿಗೆ ಮದ್ಯ ಮತ್ತು ಇತರ ಉತ್ಪನ್ನಗಳನ್ನು ದೇಶದ ಹೊರಗೆ ರಫ್ತು ಮಾಡಲು ಪೂರ್ವಾನುಮೋದನೆ ಪಡೆಯಲು ಅವಕಾಶ ಕಲ್ಪಿಸುತ್ತದೆ. ಅನುಮೋದಿತ ಕನ್ಕರೆನ್ಸ್ ಒಂದು ವರ್ಷದವರೆಗೆ ಮಾನ್ಯವಾಗಿರುತ್ತದೆ. ಲಭ್ಯವಿರುವ ಅನುಮೋದಿತ ಕನ್ಕರೆನ್ಸ್ ಪ್ರಮಾಣದ ಮಿತಿಯೊಳಗೆ ಮಾತ್ರ ರಫ್ತು ಪರವಾನಗಿಗಳನ್ನು ಸೃಷ್ಟಿಸಬಹುದು. ಹಿಂದಿನ ಕನ್ಕರೆನ್ಸ್ ಬಳಕೆಯ ಆಧಾರದ ಮೇಲೆ, ಅನುಮೋದನೆ ನೀಡುವ ಮೊದಲು ಸಂಬಂಧಪಟ್ಟ ಪ್ರಾಧಿಕಾರವು ಕೋರಲಾದ ಕನ್ಕರೆನ್ಸ್ ಪ್ರಮಾಣವನ್ನು ಪರಿಶೀಲಿಸಿ ಕಡಿಮೆ ಮಾಡಬಹುದು. ಈ ಘಟಕವು ಕನ್ಕರೆನ್ಸ್ ಅನುಮೋದನಾ ಪ್ರಕ್ರಿಯೆಯನ್ನು ಸರಳಗೊಳಿಸುವುದರ ಜೊತೆಗೆ, ನಿಯಮಗಳ ಪಾಲನೆಯನ್ನು ಖಚಿತಪಡಿಸುತ್ತದೆ, ಅನಧಿಕೃತ ರಫ್ತನ್ನು ತಡೆಯುತ್ತದೆ ಮತ್ತು ರಫ್ತು ನಿರ್ವಹಣೆಯಲ್ಲಿ ಪಾರದರ್ಶಕತೆ ಹಾಗೂ ಕಾರ್ಯಕ್ಷಮತೆಯನ್ನು ಹೆಚ್ಚಿಸುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '1414');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('66f4898b-d471-494e-b839-5fe61207b2f7', 'FINANCE-DEPARTMENT-32', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'NOC for Import of Spirits for Distillery', 'Supplier', 10, 'The NOC to Import of Spirits for Distillery module facilitates the online submission and processing of applications for obtaining an NOC to import spirits through the Excise E-Services application. The module enables applicants to submit the required application details, spirits details and supporting documents online. The application is processed through multiple levels of Excise Department authorities, and after approval by the Excise Commissioner, the NOC is completed through Digital Signature (DSC) and the signed certificate is generated.', '["Other Documents", "Request Letter", "Consent Letter from the Source Distillery"]', '["Valid Distillery License"]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', NULL, 'ಡಿಸ್ಟಿಲರಿಗಾಗಿ ಸ್ಪಿರಿಟ್', 'The NOC to Import of Spirits for Distillery module facilitates the online submission and processing of applications for obtaining an NOC to import spirits through the Excise E-Services application. The module enables applicants to submit the required application details, spirits details and supporting documents online. The application is processed through multiple levels of Excise Department authorities, and after approval by the Excise Commissioner, the NOC is completed through Digital Signature (DSC) and the signed certificate is generated.', NULL, 'State Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಡಿಸ್ಟಿಲರಿಗಳಿಗೆ ಸ್ಪಿರಿಟ್ ಆಮದು ಮಾಡಲು ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC) ಪಡೆಯುವ ಘಟಕವು ಅಬಕಾರಿ ಇ-ಸೇವೆಗಳ (Excise E-Services) ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ಅರ್ಜಿಗಳನ್ನು ಆನ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಇತರೆ ದಾಖಲೆಗಳು", "ಕೋರಿಕೆ ಪತ್ರ", "ಮೂಲ ಡಿಸ್ಟಿಲರಿಯಿಂದ ನೀಡಲಾದ ಒಪ್ಪಿಗೆ ಪತ್ರ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('9a041d45-7920-40fb-be6e-f387851ad213', 'REVENUE-DEPARTMENT-51', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'ORIGINAL SURVEY TIPPAN BOOK', 'General', 0, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (ORIGINAL SURVEY TIPPAN BOOK)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಮೂಲ ಸರ್ವೆ ಟಿಪ್ಪಣಿ ಪುಸ್ತಕ', NULL, NULL, NULL, NULL, NULL, 35.00, NULL, 'ಮೂಲ ಸರ್ವೆ ಟಿಪ್ಪಣಿ ಪುಸ್ತಕ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3054');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('69fcf6e5-a68e-40e3-94c0-7cf3dd3dab76', 'REVENUE-DEPARTMENT-52', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'ORIGINAL SURVEY PAKKA BOOK', 'General', 0, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (ORIGINAL SURVEY PAKKA BOOK)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಮೂಲ ಸರ್ವೆ ಪಕ್ಕಾ ಪುಸ್ತಕ', NULL, NULL, NULL, NULL, NULL, 70.00, NULL, 'ಮೂಲ ಸರ್ವೆ ಪಕ್ಕಾ ಪುಸ್ತಕ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3055');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('b3c1989a-e86e-4f50-9abf-747a18775d69', 'FINANCE-DEPARTMENT-24', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Concurrence for Distillery for Export of Liquor(Outside the Country)', 'Supplier', 10, 'The Concurrence Module enables Distilleriesto obtain prior concurrence approval for the export of liquor/products outside the country. The approved concurrence remains valid for one year, and export permits can be generated only against the available approved concurrence quantity. Based on previous concurrence utilization, the approving authority may review and reduce the requested concurrence quantity before granting approval. This module streamlines the concurrence approval process, ensures regulatory compliance, prevents unauthorized exports, and enhances transparency and efficiency in export management.', '["--NA----"]', '["Valid Distillery License"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಮದ್ಯ ರಫ್ತಿಗಾಗಿ (ದೇಶದ ಹೊರಗೆ) ಡಿಸ್ಟಿಲರಿಗೆ ಒಪ್ಪಿಗೆ', 'The Concurrence Module enables Distilleriesto obtain prior concurrence approval for the export of liquor/products outside the country. The approved concurrence remains valid for one year, and export permits can be generated only against the available approved concurrence quantity. Based on previous concurrence utilization, the approving authority may review and reduce the requested concurrence quantity before granting approval. This module streamlines the concurrence approval process, ensures regulatory compliance, prevents unauthorized exports, and enhances transparency and efficiency in export management.', NULL, 'State Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಕನ್ಕರೆನ್ಸ್ (Concurrence) ಘಟಕವು ಡಿಸ್ಟಿಲರಿಗಳಿಗೆ ಮದ್ಯ ಮತ್ತು ಇತರ ಉತ್ಪನ್ನಗಳನ್ನು ದೇಶದ ಹೊರಗೆ ರಫ್ತು ಮಾಡಲು ಪೂರ್ವಾನುಮೋದನೆ ಪಡೆಯಲು ಅವಕಾಶ ಕಲ್ಪಿಸುತ್ತದೆ. ಅನುಮೋದಿತ ಕನ್ಕರೆನ್ಸ್ ಒಂದು ವರ್ಷದವರೆಗೆ ಮಾನ್ಯವಾಗಿರುತ್ತದೆ. ಲಭ್ಯವಿರುವ ಅನುಮೋದಿತ ಕನ್ಕರೆನ್ಸ್ ಪ್ರಮಾಣದ ಮಿತಿಯೊಳಗೆ ಮಾತ್ರ ರಫ್ತು ಪರವಾನಗಿಗಳನ್ನು ಸೃಷ್ಟಿಸಬಹುದು. ಹಿಂದಿನ ಕನ್ಕರೆನ್ಸ್ ಬಳಕೆಯ ಆಧಾರದ ಮೇಲೆ, ಅನುಮೋದನೆ ನೀಡುವ ಮೊದಲು ಸಂಬಂಧಪಟ್ಟ ಪ್ರಾಧಿಕಾರವು ಕೋರಲಾದ ಪ್ರಮಾಣವನ್ನು ಪರಿಶೀಲಿಸಿ ಕಡಿಮೆ ಮಾಡಬಹುದು. ಈ ಘಟಕವು ಕನ್ಕರೆನ್ಸ್ ಅನುಮೋದನಾ ಪ್ರಕ್ರಿಯೆಯನ್ನು ಸರಳಗೊಳಿಸುವುದರ ಜೊತೆಗೆ, ನಿಯಮಗಳ ಪಾಲನೆಯನ್ನು ಖಚಿತಪಡಿಸುತ್ತದೆ, ಅನಧಿಕೃತ ರಫ್ತನ್ನು ತಡೆಯುತ್ತದೆ ಮತ್ತು ರಫ್ತು ನಿರ್ವಹಣೆಯಲ್ಲಿ ಪಾರದರ್ಶಕತೆ ಹಾಗೂ ಕಾರ್ಯಕ್ಷಮತೆಯನ್ನು ಹೆಚ್ಚಿಸುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '1415');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('63dc244a-e638-4ec9-941b-25f2e9acab49', 'FINANCE-DEPARTMENT-29', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Concurrence for Brewery for Export of Beer(Outside the State)', 'Supplier', 7, 'The Concurrence Module enables Breweries to obtain prior concurrence approval for the export of liquor/products outside the state. During the application process, the user must select the applicable Concurrence Type, such as Civilian,Defence ,Paramilitary, based on the export requirement. The approved concurrence remains valid for one year, and export permits can be generated only against the available approved concurrence quantity. Based on previous concurrence utilization, the approving authority may review and reduce the requested concurrence quantity before granting approval. This module streamlines the concurrence approval process, ensures regulatory compliance, prevents unauthorized exports, and enhances transparency and efficiency in export management.', '["--NA----"]', '["Valid Brewery License"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಬಿಯರ್ ರಫ್ತಿಗಾಗಿ (ರಾಜ್ಯದ ಹೊರಗೆ) ಬ್ರೂವರಿಯ ಸ್ಥಾಪನೆಗೆ ಒಪ್ಪಿಗೆ', 'The Concurrence Module enables Breweries to obtain prior concurrence approval for the export of liquor/products outside the state. During the application process, the user must select the applicable Concurrence Type, such as Civilian,Defence ,Paramilitary, based on the export requirement. The approved concurrence remains valid for one year, and export permits can be generated only against the available approved concurrence quantity. Based on previous concurrence utilization, the approving authority may review and reduce the requested concurrence quantity before granting approval. This module streamlines the concurrence approval process, ensures regulatory compliance, prevents unauthorized exports, and enhances transparency and efficiency in export management.', NULL, 'District Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಕನ್ಕರೆನ್ಸ್ (Concurrence) ಘಟಕವು ಬ್ರೂವರಿಗಳಿಗೆ ರಾಜ್ಯದ ಹೊರಗೆ ಮದ್ಯ ಮತ್ತು ಇತರ ಉತ್ಪನ್ನಗಳನ್ನು ರಫ್ತು ಮಾಡಲು ಪೂರ್ವಾನುಮೋದನೆ ಪಡೆಯಲು ಅವಕಾಶ ಕಲ್ಪಿಸುತ್ತದೆ. ಅರ್ಜಿ ಸಲ್ಲಿಸುವ ಸಂದರ್ಭದಲ್ಲಿ, ರಫ್ತು ಅವಶ್ಯಕತೆಗೆ ಅನುಗುಣವಾಗಿ ಬಳಕೆದಾರರು ಸಿವಿಲಿಯನ್ (Civilian), ಡಿಫೆನ್ಸ್ (Defence) ಅಥವಾ ಅರೆಸೈನಿಕ ಪಡೆ (Paramilitary) ಮುಂತಾದ ಸೂಕ್ತ ಕನ್ಕರೆನ್ಸ್ ಪ್ರಕಾರವನ್ನು ಆಯ್ಕೆ ಮಾಡಬೇಕು. ಅನುಮೋದಿತ ಕನ್ಕರೆನ್ಸ್ ಒಂದು ವರ್ಷದವರೆಗೆ ಮಾನ್ಯವಾಗಿರುತ್ತದೆ. ಲಭ್ಯವಿರುವ ಅನುಮೋದಿತ ಕನ್ಕರೆನ್ಸ್ ಪ್ರಮಾಣದ ಮಿತಿಯೊಳಗೆ ಮಾತ್ರ ರಫ್ತು ಪರವಾನಗಿಗಳನ್ನು ಸೃಷ್ಟಿಸಬಹುದು. ಹಿಂದಿನ ಕನ್ಕರೆನ್ಸ್ ಬಳಕೆಯ ಆಧಾರದ ಮೇಲೆ, ಅನುಮೋದನೆ ನೀಡುವ ಮೊದಲು ಸಂಬಂಧಪಟ್ಟ ಪ್ರಾಧಿಕಾರವು ಕೋರಲಾದ ಕನ್ಕರೆನ್ಸ್ ಪ್ರಮಾಣವನ್ನು ಪರಿಶೀಲಿಸಿ ಕಡಿಮೆ ಮಾಡಬಹುದು. ಈ ಘಟಕವು ಕನ್ಕರೆನ್ಸ್ ಅನುಮೋದನಾ ಪ್ರಕ್ರಿಯೆಯನ್ನು ಸರಳಗೊಳಿಸುವುದರ ಜೊತೆಗೆ, ನಿಯಮಗಳ ಪಾಲನೆಯನ್ನು ಖಚಿತಪಡಿಸುತ್ತದೆ, ಅನಧಿಕೃತ ರಫ್ತನ್ನು ತಡೆಯುತ್ತದೆ ಮತ್ತು ರಫ್ತು ನಿರ್ವಹಣೆಯಲ್ಲಿ ಪಾರದರ್ಶಕತೆ ಹಾಗೂ ಕಾರ್ಯಕ್ಷಮತೆಯನ್ನು ಹೆಚ್ಚಿಸುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '1416');
