INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('98e02f2e-11f0-42a2-b47d-f463f0174844', 'REVENUE-DEPARTMENT-54', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'STATEMENT', 'General', 0, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (STATEMENT)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಮಹಜರ್', NULL, NULL, NULL, NULL, NULL, 10.00, NULL, 'ಮಹಜರ್ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3058');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('49fdeff3-1ecf-4580-86cc-f601e8aef45f', 'FINANCE-DEPARTMENT-30', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Concurrence for Winery for Export of Wine(Outside the State)', 'Supplier', 7, 'The Concurrence Module enables Wineries to obtain prior concurrence approval for the export of liquor/products outside the state. During the application process, the user must select the applicable Concurrence Type, such as Civilian,Defence ,Paramilitary, based on the export requirement. The approved concurrence remains valid for one year, and export permits can be generated only against the available approved concurrence quantity. Based on previous concurrence utilization, the approving authority may review and reduce the requested concurrence quantity before granting approval. This module streamlines the concurrence approval process, ensures regulatory compliance, prevents unauthorized exports, and enhances transparency and efficiency in export management.', '["--NA----"]', '["Valid Winery License"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ವೈನ್ ರಫ್ತಿಗಾಗಿ (ರಾಜ್ಯದ ಹೊರಗೆ) ವೈನರಿಗೆ ಒಪ್ಪಿಗೆ', 'The Concurrence Module enables Wineries to obtain prior concurrence approval for the export of liquor/products outside the state. During the application process, the user must select the applicable Concurrence Type, such as Civilian,Defence ,Paramilitary, based on the export requirement. The approved concurrence remains valid for one year, and export permits can be generated only against the available approved concurrence quantity. Based on previous concurrence utilization, the approving authority may review and reduce the requested concurrence quantity before granting approval. This module streamlines the concurrence approval process, ensures regulatory compliance, prevents unauthorized exports, and enhances transparency and efficiency in export management.', NULL, 'District Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಕನ್ಕರೆನ್ಸ್ (Concurrence) ಘಟಕವು ವೈನರಿಗಳಿಗೆ ರಾಜ್ಯದ ಹೊರಗೆ ಮದ್ಯ ಮತ್ತು ಇತರ ಉತ್ಪನ್ನಗಳನ್ನು ರಫ್ತು ಮಾಡಲು ಪೂರ್ವಾನುಮೋದನೆ ಪಡೆಯಲು ಅವಕಾಶ ಕಲ್ಪಿಸುತ್ತದೆ. ಅರ್ಜಿ ಸಲ್ಲಿಸುವ ಸಂದರ್ಭದಲ್ಲಿ, ರಫ್ತು ಅವಶ್ಯಕತೆಗೆ ಅನುಗುಣವಾಗಿ ಬಳಕೆದಾರರು ಸಿವಿಲಿಯನ್ (Civilian), ಡಿಫೆನ್ಸ್ (Defence) ಅಥವಾ ಅರೆಸೈನಿಕ ಪಡೆ (Paramilitary) ಮುಂತಾದ ಸೂಕ್ತ ಕನ್ಕರೆನ್ಸ್ ಪ್ರಕಾರವನ್ನು ಆಯ್ಕೆ ಮಾಡಬೇಕು. ಅನುಮೋದಿತ ಕನ್ಕರೆನ್ಸ್ ಒಂದು ವರ್ಷದವರೆಗೆ ಮಾನ್ಯವಾಗಿರುತ್ತದೆ. ಲಭ್ಯವಿರುವ ಅನುಮೋದಿತ ಕನ್ಕರೆನ್ಸ್ ಪ್ರಮಾಣದ ಮಿತಿಯೊಳಗೆ ಮಾತ್ರ ರಫ್ತು ಪರವಾನಗಿಗಳನ್ನು ಸೃಷ್ಟಿಸಬಹುದು. ಹಿಂದಿನ ಕನ್ಕರೆನ್ಸ್ ಬಳಕೆಯ ಆಧಾರದ ಮೇಲೆ, ಅನುಮೋದನೆ ನೀಡುವ ಮೊದಲು ಸಂಬಂಧಪಟ್ಟ ಪ್ರಾಧಿಕಾರವು ಕೋರಲಾದ ಕನ್ಕರೆನ್ಸ್ ಪ್ರಮಾಣವನ್ನು ಪರಿಶೀಲಿಸಿ ಕಡಿಮೆ ಮಾಡಬಹುದು. ಈ ಘಟಕವು ಕನ್ಕರೆನ್ಸ್ ಅನುಮೋದನಾ ಪ್ರಕ್ರಿಯೆಯನ್ನು ಸರಳಗೊಳಿಸುವುದರ ಜೊತೆಗೆ, ನಿಯಮಗಳ ಪಾಲನೆಯನ್ನು ಖಚಿತಪಡಿಸುತ್ತದೆ, ಅನಧಿಕೃತ ರಫ್ತನ್ನು ತಡೆಯುತ್ತದೆ ಮತ್ತು ರಫ್ತು ನಿರ್ವಹಣೆಯಲ್ಲಿ ಪಾರದರ್ಶಕತೆ ಹಾಗೂ ಕಾರ್ಯಕ್ಷಮತೆಯನ್ನು ಹೆಚ್ಚಿಸುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '1418');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('e8dfb942-b609-4b37-ac73-293b763e9173', 'FINANCE-DEPARTMENT-15', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Transfer of Distillery, Brewery, Microbrewery, Fortified Winery licences (in other cases)', 'Supplier', 30, 'This module facilitates the online Transfer of Distillery, Brewery, Microbrewery, and Fortified Winery licences in other cases, including the transfer of a licence from one licence holder to another and changes in the name of the licensed unit, through the Excise E-Services application. The module provides an end-to-end digital workflow, beginning with application submission by the applicant and progressing through multiple levels of departmental review and processing, up to the Excise Commissioner, who takes the final decision before the application is sent back to the applicant.', '["Other Documents", "Approved Blueprint", "Consent Letter from Transferor", "Consent Letter from Transferee", "Licence Copy", "Bottling Licence Copy", "Clearance Certificate Issued by the Karnataka State Pollution Control Board", "Disqualification Declaration/Affidavit", "No Objection Certificate from the Board of Directors/Partners/Individuals/Society Members for Transfer of Licence", "Prescribed Application Form", "Certificate of Incorporation for Company/LLP Issued by the Ministry of Corporate Affairs", "Certificate of Registration of Firms/Form A Issued by the District Registrar", "PAN Card of Transferor", "PAN Card of Transferee", "GSTIN Certificate of Transferor", "GSTIN Certificate of Transferee", "Income Tax Returns Clearance Certificate of Transferor", "Latest ITR Filing Document of Transferee", "FSSAI Licence of Transferor", "FSSAI Licence of Transferee", "List of Machinery/Equipment/Tanks Installed in the Licensed Premises", "Property Ownership Documents (Khata Extract/Property Tax Paid Receipt, etc.)", "Rental/Lease Agreement of the Property", "Affidavit from the Transferor Regarding Any Dues Payable to the Government", "Power of Attorney Copy of Transferor", "Power of Attorney Copy of Transferee", "Calibration Certificate from Transferee", "Calibration Certificate from Transferor", "Blueprint of the Unit Submitted for Approval", "Pollution Control Board Clearance Certificate from Transferee", "MOA/AOA of the Company/LLP/Partnership Deed of the Transferor", "MOA/AOA of the Company/LLP/Partnership Deed of the Transferee", "Affidavit from the Transferee Regarding Any Dues Payable to the Government", "Licence Proceeding Order Copy Issued by the Excise Commissioner for the Transferor", "Trade Licence/General Licence of Transferor", "Trade Licence/General Licence of Transferee", "Copy of Project Report"]', '["Valid Distillery, Brewery, Microbrewery, Fortified Winery licences"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಡಿಸ್ಟಿಲರಿ, ಬ್ರೂವರಿ, ಮೈಕ್ರೋ-ಬ್ರೂವರಿ ಮತ್ತು ಫಾರ್ಟಿಫೈಡ್ ವೈನರಿ ಪರವಾನಗಿಗಳ ವರ್ಗಾವಣೆ (ಇತರ ಸಂದರ್ಭಗಳಲ್ಲಿ)', 'This module facilitates the online Transfer of Distillery, Brewery, Microbrewery, and Fortified Winery licences in other cases, including the transfer of a licence from one licence holder to another and changes in the name of the licensed unit, through the Excise E-Services application. The module provides an end-to-end digital workflow, beginning with application submission by the applicant and progressing through multiple levels of departmental review and processing, up to the Excise Commissioner, who takes the final decision before the application is sent back to the applicant.', NULL, 'State Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಈ ಘಟಕವು ಅಬಕಾರಿ ಇ-ಸೇವೆಗಳ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ಇತರೆ ಪ್ರಕರಣಗಳಲ್ಲಿ ಡಿಸ್ಟಿಲರಿ, ಬ್ರೂವರಿ, ಮೈಕ್ರೋಬ್ರೂವರಿ ಮತ್ತು ಫೋರ್ಟಿಫೈಡ್ ವೈನರಿ ಪರವಾನಗಿಗಳನ್ನು ಆನ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಇತರೆ ದಾಖಲೆಗಳು", "ಅನುಮೋದಿತ ನೀಲನಕ್ಷೆ", "ವರ್ಗಾವಣೆದಾರರಿಂದ ಒಪ್ಪಿಗೆ ಪತ್ರ", "ವರ್ಗಾವಣೆ ಸ್ವೀಕರಿಸುವವರಿಂದ ಒಪ್ಪಿಗೆ ಪತ್ರ", "ಪರವಾನಗಿಯ ಪ್ರತಿ", "ಬಾಟ್ಲಿಂಗ್ ಪರವಾನಗಿಯ ಪ್ರತಿ", "ಕರ್ನಾಟಕ ರಾಜ್ಯ ಮಾಲಿನ್ಯ ನಿಯಂತ್ರಣ ಮಂಡಳಿಯಿಂದ ನೀಡಲಾದ ಅನುಮತಿ ಪ್ರಮಾಣಪತ್ರ", "ಅನರ್ಹತೆ ಘೋಷಣೆ/ಅಫಿಡವಿಟ್", "ಪರವಾನಗಿ ವರ್ಗಾವಣೆಗೆ ನಿರ್ದೇಶಕ ಮಂಡಳಿ/ಪಾಲುದಾರರು/ವ್ಯಕ್ತಿಗಳು/ಸೊಸೈಟಿ ಸದಸ್ಯರಿಂದ ನೀಡಲಾದ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC)", "ನಿಗದಿತ ಅರ್ಜಿ ನಮೂನೆ", "ಕಾರ್ಪೊರೇಟ್ ವ್ಯವಹಾರಗಳ ಸಚಿವಾಲಯದಿಂದ ನೀಡಲಾದ ಕಂಪನಿ/LLP ಸ್ಥಾಪನಾ ಪ್ರಮಾಣಪತ್ರ", "ಜಿಲ್ಲಾ ನೋಂದಣಾಧಿಕಾರಿಯಿಂದ ನೀಡಲಾದ ಸಂಸ್ಥೆಗಳ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರ/ಫಾರ್ಮ್ A", "ವರ್ಗಾವಣೆದಾರರ PAN ಕಾರ್ಡ್", "ವರ್ಗಾವಣೆ ಸ್ವೀಕರಿಸುವವರ PAN ಕಾರ್ಡ್", "ವರ್ಗಾವಣೆದಾರರ GSTIN ಪ್ರಮಾಣಪತ್ರ", "ವರ್ಗಾವಣೆ ಸ್ವೀಕರಿಸುವವರ GSTIN ಪ್ರಮಾಣಪತ್ರ", "ವರ್ಗಾವಣೆದಾರರ ಆದಾಯ ತೆರಿಗೆ ರಿಟರ್ನ್ಸ್ ಕ್ಲಿಯರೆನ್ಸ್ ಪ್ರಮಾಣಪತ್ರ", "ವರ್ಗಾವಣೆ ಸ್ವೀಕರಿಸುವವರು ಇತ್ತೀಚೆಗೆ ಸಲ್ಲಿಸಿದ ITR ದಾಖಲೆ", "ವರ್ಗಾವಣೆದಾರರ FSSAI ಪರವಾನಗಿ", "ವರ್ಗಾವಣೆ ಸ್ವೀಕರಿಸುವವರ FSSAI ಪರವಾನಗಿ", "ಪರವಾನಗಿ ಪಡೆದ ಆವರಣದಲ್ಲಿ ಸ್ಥಾಪಿಸಲಾದ ಯಂತ್ರೋಪಕರಣಗಳು/ಉಪಕರಣಗಳು/ಟ್ಯಾಂಕ್"]', NULL, NULL, '1419');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('b3336c6c-c2a2-4288-a671-41ed61f6254b', 'FINANCE-DEPARTMENT-23', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Allotment of Spirits to Primary Distillery / Brewery / Winery', 'Supplier', 3, 'The Allotment of Spirits to Primary Distillery / Brewery / Winery application allows the user to submit an allotment request by entering the required application details and consent number. The system verifies whether the consent number already exists; if available, the related details are automatically fetched, otherwise the user must enter the required information manually. After submitting the application, it is forwarded to the concerned officers for further processing and approval.', '["--NA----"]', '["Valid Supplier License"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಪ್ರಾಥಮಿಕ ಮದ್ಯ ಬಟ್ಟಿ ಘಟಕ / ಬ್ರೂವರಿ / ವೈನರಿಗೆ ಸ್ಪಿರಿಟ್ಸ್ ಹಂಚಿಕೆ', 'The Allotment of Spirits to Primary Distillery / Brewery / Winery application allows the user to submit an allotment request by entering the required application details and consent number. The system verifies whether the consent number already exists; if available, the related details are automatically fetched, otherwise the user must enter the required information manually. After submitting the application, it is forwarded to the concerned officers for further processing and approval.', NULL, 'Range Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಪ್ರಾಥಮಿಕ ಡಿಸ್ಟಿಲರಿ / ಬ್ರೂವರಿ / ವೈನರಿಗೆ ಸ್ಪಿರಿಟ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '1422');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('fa6d53a0-079a-44c2-a36f-578a54f8f045', 'FINANCE-DEPARTMENT-19', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'No-Objection Certificate to lift molasses (Within the State within the quota limits)', 'Supplier', 8, 'The No-Objection Certificate (NOC) module enables eligible distilleries, sugar factories, and other authorized units to obtain approval for lifting molasses within the state and within their allotted quota limits. During the application process, the user must provide the current year''s allotted quota, the quantity already utilized, the remaining quota, the applicable grade of molasses, and the quantity proposed to be lifted. The user must then select the source sugar factory/distillery unit. Based on the selected unit, the corresponding Excise District, Excise Subdivision, Excise Range will be automatically fetched by the system. Supporting documents required for the NOC application can be uploaded through the module. The application ensures that the requested quantity does not exceed the available quota, streamlines the approval process, ensures regulatory compliance, prevents lifting beyond permitted limits, and enhances transparency and efficiency in molasses movement within the state.', '["Other Documents", "Request Letter", "Stock Position Report", "Sale Consent Letter from Sugar Factory", "Molasses Licence of Applicant", "Licence Copy of Supplier (M1)", "Quota Utilization Statement of Applicant"]', '["Valid Molasses Licence"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಮೊಲಾಸಿಸ್ (ಕಬ್ಬಿನ ಕಾಕಂಬಿ) ಸಾಗಿಸಲು ನಿರಾಕ್ಷೇಪಣಾ ಪತ್ರ (ರಾಜ್ಯದೊಳಗೆ, ನಿಗದಿತ ಕೋಟಾ ಮಿತಿಯೊಳಗೆ)', 'The No-Objection Certificate (NOC) module enables eligible distilleries, sugar factories, and other authorized units to obtain approval for lifting molasses within the state and within their allotted quota limits. During the application process, the user must provide the current year''s allotted quota, the quantity already utilized, the remaining quota, the applicable grade of molasses, and the quantity proposed to be lifted. The user must then select the source sugar factory/distillery unit. Based on the selected unit, the corresponding Excise District, Excise Subdivision, Excise Range will be automatically fetched by the system. Supporting documents required for the NOC application can be uploaded through the module. The application ensures that the requested quantity does not exceed the available quota, streamlines the approval process, ensures regulatory compliance, prevents lifting beyond permitted limits, and enhances transparency and efficiency in molasses movement within the state.', NULL, 'District Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC) ಘಟಕವು ಅರ್ಹ ಡಿಸ್ಟಿಲರಿಗಳು, ಸಕ್ಕರೆ ಕಾರ್ಖಾನೆಗಳು ಮತ್ತು ಇತರ ಅಧಿಕೃತ ಘಟಕಗಳಿಗೆ ರಾಜ್ಯದೊಳಗೆ ನಿಗದಿಪಡಿಸಲಾದ ಕೋಟಾ ಮಿತಿಯೊಳಗೆ ಕಾಕಂಬಿಯನ್ನು ಎತ್ತುವಳಿ ಮಾಡಲು ಅನುಮೋದನೆ ಪಡೆಯಲು ಅವಕಾಶ ಕಲ್ಪಿಸುತ್ತದೆ.
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('7435b611-8f14-4038-a6c8-9a575f4cfb35', 'FINANCE-DEPARTMENT-16', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Transfer of Distillery, Brewery, Microbrewery, Fortified Winery licences (in case of death of licensee)', 'Supplier', 30, 'This module facilitates the online transfer of Distillery, Brewery, Microbrewery, and Fortified Winery licences in Death cases, particularly in situations where the licence of a deceased licence holder is required to be transferred to their eligible legal heir, such as a son, daughter, mother, father, or wife, in accordance with the applicable legal provisions.
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('5b87764f-b245-47f3-a97c-60fec2146ee7', 'FINANCE-DEPARTMENT-40', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Local DP-MRP/ DRP-RMRP Intimation', 'Supplier', 0, 'Applicant will declare the DP and MRP for the labels (Brands), based on the entered DP, the MRP will be auto-calculated and displayed by the system. If the user needs to revise the price, the applicant applies for DRP, and RMRP in the application to submit the revised pricing details.', '["Cost Accountant Report", "Affidavit Document"]', '["Valid Supplier License"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಸ್ಥಳೀಯ DP-MRP/ DRP-RMRP ಕುರಿತಾದ ಮಾಹಿತಿ', 'Applicant will declare the DP and MRP for the labels (Brands), based on the entered DP, the MRP will be auto-calculated and displayed by the system. If the user needs to revise the price, the applicant applies for DRP, and RMRP in the application to submit the revised pricing details.', NULL, '---NA---', 'Online', NULL, NULL, NULL, 'ಅರ್ಜಿದಾರರು ಲೇಬಲ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ವೆಚ್ಚ ಲೆಕ್ಕಪರಿಶೋಧಕರ ವರದಿ", "ಪ್ರಮಾಣಪತ್ರದ ಅಫಿಡವಿಟ್ (ಪ್ರಮಾಣ ಪತ್ರ)"]', NULL, NULL, '2910');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('d9aec2e7-794f-4aee-a4de-d419085d49e8', 'FINANCE-DEPARTMENT-34', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Grant of ND-IV and ND-V to a Dealer and Chemist (NDPS)', 'Public', 37, 'The Grant of ND-IV and ND-V module enables Dealers and Medical Practitioner to apply online for NDPS licenses. It provides a digital workflow for application submission, document upload, departmental verification, and approval through multiple officer levels, ensuring transparency, faster processing, and complete application tracking.', '["Blueprints", "GST Certificate", "Other Documents", "PAN Card", "Building Owner''s Consent/Rent Agreement/Khata", "Form 20/Form 21", "Khata/Tax-Paid Receipt", "KSPCB Form 3 – Rule 10 Authorization under the Bio-Medical Waste Management Rules, 2016", "Recommendation by the District/State Assistant Drug Controller and Licensing Authority, Drugs Control Department", "General Purpose Licence/Trade Licence", "Certificate of Incorporation", "Karnataka State Pharmacy Council Certificate", "Karnataka State Medical Council Certificate of Registration/Pharmacy Council Certificate of Registration", "Karnataka State Pollution Control Board Certificate", "Employment Letter (Certificate)", "Bio-Medical Waste Certificate", "Chemist/Pharmacy Certificate Attached to the Hospital"]', '["Public Regestration required"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ವ್ಯಾಪಾರಿ ಮತ್ತು ರಸಾಯನಶಾಸ್ತ್ರಜ್ಞರಿಗೆ (NDPS) ND-IV ಮತ್ತು ND-V ಅನ್ನು ಮಂಜೂರು ಮಾಡುವುದು', 'The Grant of ND-IV and ND-V module enables Dealers and Medical Practitioner to apply online for NDPS licenses. It provides a digital workflow for application submission, document upload, departmental verification, and approval through multiple officer levels, ensuring transparency, faster processing, and complete application tracking.', NULL, 'State Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ND-IV ಮತ್ತು ND-V ಪರವಾನಗಿಗಳ ಮಂಜೂರಾತಿ ಘಟಕವು ವಿತರಕರು ಮತ್ತು ವೈದ್ಯಕೀಯ ವೃತ್ತಿಪರರಿಗೆ NDPS ಪರವಾನಗಿಗಳಿಗಾಗಿ ಆನ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ನೀಲನಕ್ಷೆಗಳು", "GST ಪ್ರಮಾಣಪತ್ರ", "ಇತರೆ ದಾಖಲೆಗಳು", "PAN ಕಾರ್ಡ್", "ಕಟ್ಟಡ ಮಾಲೀಕರ ಒಪ್ಪಿಗೆ ಪತ್ರ/ಬಾಡಿಗೆ ಒಪ್ಪಂದ/ಖಾತಾ", "ನಮೂನೆ 20/ನಮೂನೆ 21", "ಖಾತಾ/ತೆರಿಗೆ ಪಾವತಿ ರಸೀದಿ", "KSPCB ನಮೂನೆ 3 – ಜೈವಿಕ-ವೈದ್ಯಕೀಯ ತ್ಯಾಜ್ಯ ನಿರ್ವಹಣಾ ನಿಯಮಗಳು, 2016ರ ನಿಯಮ 10ರ ಅಡಿಯಲ್ಲಿ ನೀಡಲಾದ ಅಧಿಕೃತ ಅನುಮತಿ", "ಔಷಧ ನಿಯಂತ್ರಣ ಇಲಾಖೆಯ ಜಿಲ್ಲಾ/ರಾಜ್ಯ ಸಹಾಯಕ ಔಷಧ ನಿಯಂತ್ರಕರು ಮತ್ತು ಪರವಾನಗಿ ಪ್ರಾಧಿಕಾರದಿಂದ ನೀಡಲಾದ ಶಿಫಾರಸು", "ಸಾಮಾನ್ಯ ಉದ್ದೇಶದ ಪರವಾನಗಿ/ವ್ಯಾಪಾರ ಪರವಾನಗಿ", "ಸಂಸ್ಥಾಪನಾ ಪ್ರಮಾಣಪತ್ರ", "ಕರ್ನಾಟಕ ರಾಜ್ಯ ಫಾರ್ಮಸಿ ಕೌನ್ಸಿಲ್ ಪ್ರಮಾಣಪತ್ರ", "ಕರ್ನಾಟಕ ರಾಜ್ಯ ವೈದ್ಯಕೀಯ ಮಂಡಳಿಯ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರ/ಫಾರ್ಮಸಿ ಕೌನ್ಸಿಲ್ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರ", "ಕರ್ನಾಟಕ ರಾಜ್ಯ ಮಾಲಿನ್ಯ ನಿಯಂತ್ರಣ ಮಂಡಳಿಯ ಪ್ರಮಾಣಪತ್ರ", "ಉದ್ಯೋಗ ಪತ್ರ (ಪ್ರಮಾಣಪತ್ರ)", "ಜೈವಿಕ-ವೈದ್ಯಕೀಯ ತ್ಯಾಜ್ಯ ಪ್ರಮಾಣಪತ್ರ", "ಆಸ್ಪತ್ರೆಯೊಂದಿಗೆ ಸಂಯೋಜಿತವಾಗಿರುವ ರಸಾಯನಶಾಸ್ತ್ರಜ್ಞ/ಫಾರ್ಮಸಿ ಪ್ರಮಾಣಪತ್ರ"]', NULL, NULL, '1433');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('f179c195-cc6e-4dc9-9668-2142e0050350', 'FINANCE-DEPARTMENT-18', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Renewal of Molasses licences', 'Supplier', 25, 'The Renewal of Molasses License module in the Excise E-Services application provides a streamlined digital process for licensees to submit applications for renewal of their molasses license and enables Excise Department officials to review, verify, and process the application through different levels of approval. The module supports multiple user roles, including the Licensee, The applicant submits the renewal application and required documents, after which the application is processed through the designated departmental hierarchy for verification, forwarding, or reverting with remarks.', '["Calibration Certificate of Storage Tank", "MOA/AOA/Partnership Deed", "GST Certificate", "Project Report", "Other Documents", "Land Conversion Order", "Stock Position Report", "Poultry/Livestock/Veterinary Licence", "Molasses Request Certificate by Veterinary Department", "Industrial Licence", "Boiler Licence", "PAN Card Issued by the Income Tax Department", "List of Directors/Partners", "Aadhaar Card", "Memorandum of Understanding", "Memorandum of Association", "Appeal/Court Case/Other Court Orders", "M1 Details of Products Manufactured by the Unit", "Details of Products Manufactured by the Unit", "Quota Quantity", "Factory Licence", "Karnataka Pollution Control Board Clearance Certificate", "Electricity Supply Certificate", "Details of the Quantity of Sugarcane Lifted by Farmers", "Partnership Deed", "Approved Blueprint of the Unit", "Approved Blueprint of Tanks", "Blueprint Submitted for Approval", "Partnership Certificate/Company Certificate", "Manufacturer Licence under the Karnataka Poultry and Livestock Feed Rules", "Details of the Purpose for Which Molasses Is Exported", "NOC from the Department of Ports"]', '["Valid Molasses Licence"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಮೊಲಾಸಸ್ ಪರವಾನಗಿಗಳ ನವೀಕರಣ', 'The Renewal of Molasses License module in the Excise E-Services application provides a streamlined digital process for licensees to submit applications for renewal of their molasses license and enables Excise Department officials to review, verify, and process the application through different levels of approval. The module supports multiple user roles, including the Licensee, The applicant submits the renewal application and required documents, after which the application is processed through the designated departmental hierarchy for verification, forwarding, or reverting with remarks.', NULL, 'State Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಅಬಕಾರಿ ಇ-ಸೇವೆಗಳ ಅಪ್ಲಿಕೇಶನ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಸಂಗ್ರಹಣಾ ಟ್ಯಾಂಕ್"]', NULL, NULL, '1438');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('021a702e-2319-4c0e-bc97-a7d865ae43b6', 'FINANCE-DEPARTMENT-20', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'No-Objection Certificate to lift molasses (Outside State)', 'Supplier', 15, 'The No-Objection Certificate (NOC) module enables eligible distilleries, sugar factories, and other authorized units to obtain approval for lifting molasses within the state and within their allotted quota limits. During the application process, the user must provide the current year''s allotted quota, the quantity already utilized, the remaining quota, the applicable grade of molasses, and the quantity proposed to be lifted. The user must then select the source sugar factory/distillery unit. Based on the selected unit, the corresponding Excise District, Excise Subdivision, Excise Range will be automatically fetched by the system. Supporting documents required for the NOC application can be uploaded through the module. The application ensures that the requested quantity does not exceed the available quota, streamlines the approval process, ensures regulatory compliance, prevents lifting beyond permitted limits, and enhances transparency and efficiency in molasses movement within the state.', '["Other Documents", "NOC from the State of Origin", "Molasses Licence of the Concerned State", "Sale Consent Letter from the Sugar Factory", "Stock Position Report", "Request Letter from the Buyer"]', '["Valid Molasses Licence"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಮೊಲಾಸಿಸ್ (ಕಬ್ಬಿನ ಕಾಕಂಬಿ) ಸಾಗಿಸಲು ನಿರಾಕ್ಷೇಪಣಾ ಪತ್ರ (ರಾಜ್ಯದ ಹೊರಗೆ)', 'The No-Objection Certificate (NOC) module enables eligible distilleries, sugar factories, and other authorized units to obtain approval for lifting molasses within the state and within their allotted quota limits. During the application process, the user must provide the current year''s allotted quota, the quantity already utilized, the remaining quota, the applicable grade of molasses, and the quantity proposed to be lifted. The user must then select the source sugar factory/distillery unit. Based on the selected unit, the corresponding Excise District, Excise Subdivision, Excise Range will be automatically fetched by the system. Supporting documents required for the NOC application can be uploaded through the module. The application ensures that the requested quantity does not exceed the available quota, streamlines the approval process, ensures regulatory compliance, prevents lifting beyond permitted limits, and enhances transparency and efficiency in molasses movement within the state.', NULL, 'State Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC) ಘಟಕವು ಅರ್ಹ ಡಿಸ್ಟಿಲರಿಗಳು, ಸಕ್ಕರೆ ಕಾರ್ಖಾನೆಗಳು ಮತ್ತು ಇತರ ಅಧಿಕೃತ ಘಟಕಗಳಿಗೆ ರಾಜ್ಯದೊಳಗೆ ನಿಗದಿಪಡಿಸಲಾದ ಕೋಟಾ ಮಿತಿಯೊಳಗೆ ಕಾಕಂಬಿಯನ್ನು ಎತ್ತುವಳಿ ಮಾಡಲು ಅನುಮೋದನೆ ಪಡೆಯಲು ಅವಕಾಶ ಕಲ್ಪಿಸುತ್ತದೆ.
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('3fcc8351-9964-40cb-a545-189c0a2cafca', 'FINANCE-DEPARTMENT-27', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'NOC for export of Spirits for Distillery', 'Supplier', 10, 'The NOC for Export of Spirit for Distillery module facilitates the online submission and processing of applications for obtaining an NOC for exporting spirit through the Excise E-Services application. The module enables applicants to submit the required application details, EVC details and supporting documents online, and track the application status throughout the process. After verification and approval through the concerned Excise Department authorities, the Licence Copy is reviewed and signed by the Excise Commissioner, after which the approved application is sent back to the applicant.', '["Other Documents", "Request Letter", "NOC from the Authority of the Importing State", "Declaration Regarding Pending EVC", "Consent Letter from the Source Distillery"]', '["Valid Distillery License"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಮದ್ಯ ತಯಾರಿಕಾ ಘಟಕದಿಂದ ಮದ್ಯವನ್ನು ರಫ್ತು ಮಾಡಲು ನಿರಾಕ್ಷೇಪಣಾ ಪತ್ರ (NOC)', 'The NOC for Export of Spirit for Distillery module facilitates the online submission and processing of applications for obtaining an NOC for exporting spirit through the Excise E-Services application. The module enables applicants to submit the required application details, EVC details and supporting documents online, and track the application status throughout the process. After verification and approval through the concerned Excise Department authorities, the Licence Copy is reviewed and signed by the Excise Commissioner, after which the approved application is sent back to the applicant.', NULL, 'State Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಡಿಸ್ಟಿಲರಿಗಳಿಂದ ಸ್ಪಿರಿಟ್ ರಫ್ತು ಮಾಡಲು ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC) ಪಡೆಯುವ ಘಟಕವು ಅಬಕಾರಿ ಇ-ಸೇವೆಗಳ (Excise E-Services) ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ಅರ್ಜಿಗಳನ್ನು ಆನ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಇತರೆ ದಾಖಲೆಗಳು", "ಕೋರಿಕೆ ಪತ್ರ", "ಆಮದು ಮಾಡಿಕೊಳ್ಳುವ ರಾಜ್ಯದ ಪ್ರಾಧಿಕಾರದಿಂದ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC)", "ಬಾಕಿ ಇರುವ EVC ಕುರಿತು ಘೋಷಣೆ", "ಮೂಲ ಡಿಸ್ಟಿಲರಿಯಿಂದ ನೀಡಲಾದ ಒಪ್ಪಿಗೆ ಪತ್ರ"]', NULL, NULL, '1443');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('1ce93283-48dd-4c34-9f87-88cfa14fcf93', 'RAJIV-GANDHI-UNIVERS-12', '36019975-6c52-4695-ac9b-bb10fcfdb011', 'CONSOLIDATED MARKS CARD/ TRANSCRIPT – FOR STUDENTS BEFORE 2017', 'General', 35, 'Student seeking for Consolidated Markscard/ Transcript', '["Copy of Marks card"]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '2e068fbc-04bb-4a0f-ac96-f924621ce46e', 'ಏಕೀಕೃತ ಅಂಕಪಟ್ಟಿ/ಪ್ರತಿಲಿಪಿ - 2017 ರ ಮೊದಲ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ', NULL, NULL, NULL, NULL, NULL, 1500.00, NULL, 'ಏಕೀಕೃತ ಅಂಕಪಟ್ಟಿ /ಪ್ರತಿಲಿಪಿ ಬಯಸುವ ವಿದ್ಯಾರ್ಥಿ', NULL, NULL, NULL, true, 'YES', '[]', '[]', 1, '["ಅಂಕಪಟ್ಟಿಯ ಪ್ರತಿಗಳು"]', NULL, NULL, '2978');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('d967a421-3135-4d8b-b183-59a936145fb9', 'REVENUE-DEPARTMENT-71', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'GUT PLOT', 'General', 0, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (GUT PLOT)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಘಟ್ ಪ್ಲಾಟ್', NULL, NULL, NULL, NULL, NULL, 35.00, NULL, 'ಘಟ್ ಪ್ಲಾಟ್ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3091');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('8e86f745-213a-42ac-8608-2b1d84a6a069', 'FINANCE-DEPARTMENT-35', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Renewal of ND-IV and ND-V to a Dealer and Chemist (NDPS)', 'Supplier', 15, 'The Renewal of ND-IV and ND-V to Dealer and Chemist (NDPS) module enables dealers and chemists to submit applications for renewal of their ND-IV and ND-V licenses through the Excise ERP system. The applicant fills in the required application details and submits the form. After successful submission, an application number is generated and the applicant can upload the required supporting documents. Once the application is finally submitted, it is forwarded through the designated Excise officers for verification, processing, approval, and final action. The application status and movement can also be tracked through the system.', '["Blueprints", "Other Documents", "PAN Card", "Request Letter", "Form 20/Form 21", "Utilization and Balance Statement", "Previous Year''s Licence", "Trade Licence", "Karnataka State Pollution Control Board Certificate", "Employment Letter (Certificate)", "Service to Be Provided for Name Change", "GST Certificate", "KSPCB Certificate", "Bio-Medical Waste Certificate"]', '["Valid NDPS License"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ವಿತರಕರು ಮತ್ತು ರಸಾಯನಶಾಸ್ತ್ರಜ್ಞರಿಗೆ (NDPS) ND-IV ಮತ್ತು ND-V ಪರವಾನಗಿಗಳ ನವೀಕರಣ', 'The Renewal of ND-IV and ND-V to Dealer and Chemist (NDPS) module enables dealers and chemists to submit applications for renewal of their ND-IV and ND-V licenses through the Excise ERP system. The applicant fills in the required application details and submits the form. After successful submission, an application number is generated and the applicant can upload the required supporting documents. Once the application is finally submitted, it is forwarded through the designated Excise officers for verification, processing, approval, and final action. The application status and movement can also be tracked through the system.', NULL, 'District Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ವಿತರಕರು ಮತ್ತು ಕೆಮಿಸ್ಟ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ನೀಲನಕ್ಷೆಗಳು", "ಇತರೆ ದಾಖಲೆಗಳು", "PAN ಕಾರ್ಡ್", "ಕೋರಿಕೆ ಪತ್ರ", "ನಮೂನೆ 20/ನಮೂನೆ 21", "ಬಳಕೆ ಮತ್ತು ಬಾಕಿ ಉಳಿಕೆ ಪ್ರಮಾಣದ ಹೇಳಿಕೆ", "ಹಿಂದಿನ ವರ್ಷದ ಪರವಾನಗಿ", "ವ್ಯಾಪಾರ ಪರವಾನಗಿ", "ಕರ್ನಾಟಕ ರಾಜ್ಯ ಮಾಲಿನ್ಯ ನಿಯಂತ್ರಣ ಮಂಡಳಿಯ ಪ್ರಮಾಣಪತ್ರ", "ಉದ್ಯೋಗ ಪತ್ರ (ಪ್ರಮಾಣಪತ್ರ)", "ಹೆಸರು ಬದಲಾವಣೆಗೆ ಒದಗಿಸಬೇಕಾದ ಸೇವೆ", "GST ಪ್ರಮಾಣಪತ್ರ", "KSPCB ಪ್ರಮಾಣಪತ್ರ", "ಜೈವಿಕ-ವೈದ್ಯಕೀಯ ತ್ಯಾಜ್ಯ ಪ್ರಮಾಣಪತ್ರ"]', NULL, NULL, '1444');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('09b9d630-5c01-41e6-bcce-416625169f24', 'FINANCE-DEPARTMENT-1', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Grant of Licenses', 'Public', 35, 'The Grant of Licence module facilitates the online submission and processing of applications for obtaining various types of licences through the Excise E-Services application. The module covers licences such as CL-4, CL-7A, CL-7B, CL-7C, CL-8, CL-8A, CL-8B, CL-15, CL-16, CL-17, CL-18, and CL-11 (MSIL, WB, WT) with different ownership types.', '["Blueprints", "GST Certificate", "Other Documents", "Approved Blueprint", "Address Proof", "PAN Card", "Latest Income Tax Returns Submission as per Excise Laws/Rules", "Notarized Affidavit Rule 4B", "Vehicle Parking Area Photos", "Trade License", "GST Registration Certificate", "Brand List", "Calibration Certificate from Weight and Measures Department", "Labour Certificate from Labour Department (Non Mandatory)", "Fire Safety Certificate", "NOC for Smoking Zone from Concerned Authority", "Front Elevation", "Store Room/Store Area Photo", "Kitchen Photo", "Dining Hall Photo", "Indoor Games Area Photo", "Outdoor Games Area Photo", "Library/Reading Room Photo", "Toilets Photo", "Counters Photo", "Reception", "Representative Room", "Star Accreditation Certificate", "Certificate Approved by Minister of Tourism of India (GOI)", "Population Certificate Obtained by Tahsildar Based on the 2011 Census", "NOC from NH or SH Competent Authorities", "Registration Certificate Number (Company Act or Society Act or Trust Act Registration)", "Authorization Letter to Represent the Club", "4B Notarized Affidavit Declaration", "Photos", "KIG Supplier Company Consent Letter from Brewery Supplying Company", "NOC Granted by Indian Railway Authority to Serve Liquor", "Board of Directors", "NOC from Airport Authority", "Airport Authority Consent/Rent Agreement/Katha", "Receipt", "Building Documents", "Application as Rule 4", "List of 100 Permanent Members Photo", "NOC from Local Body", "Bylaw Copy", "Tax Paid Receipt", "Club-GST Certificate", "Highway NOC", "Partnership/Company Documents", "Rooms Photo", "Pollution Control Board - NOC", "Weight and Measurement Dept Certificate", "Labour Department Certificate", "Directors Share Holding Certificate", "List of Directors", "Directors PAN and Address Proof", "Company Related Documents", "Partnership/Company/LLP/Individual Related Documents", "Fire Safety Certificate / Fire Extinguisher Installation (If Building is 15 Meter Height)", "IRCTC PAN Card", "IRCTC - Joint General Manager ID Card", "Authorization Letter to Represent IRCTC", "Building Owner NOC", "Agreement Between IRCTC and KSTDC", "Building Photos", "4B Affidavit", "Building Related Documents", "Commandant PAN and Address Proof", "Authorization to Represent", "Authorized Person Address Proof", "Tourism Dept - PAN Card", "Tourism Dept - GST Certificate", "Fire Safety Certificate from Fire Dept", "Application", "Customs NOC", "Allotment of Building Letter from Airport Authority", "Affidavit Document", "Photo of Liquor Storage Place", "Blueprint Copy of the Premises", "100 Meters Radius Map", "Applicant Passport Size Photos", "Building Documents / Tax Paid Receipt"]', '["Public Regestration required"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', 'e9b98d2e-66d7-4b0a-b69f-436acc369a6d', 'ಪರವಾನಗಿಗಳ ಮಂಜೂರು', 'The Grant of Licence module facilitates the online submission and processing of applications for obtaining various types of licences through the Excise E-Services application. The module covers licences such as CL-4, CL-7A, CL-7B, CL-7C, CL-8, CL-8A, CL-8B, CL-15, CL-16, CL-17, CL-18, and CL-11 (MSIL, WB, WT) with different ownership types.', NULL, 'State Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಪರವಾನಗಿ ಮಂಜೂರು ಮಾಡುವ ಘಟಕವು ಅಬಕಾರಿ ಇ-ಸೇವೆಗಳ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ವಿವಿಧ ರೀತಿಯ ಪರವಾನಗಿಗಳನ್ನು ಪಡೆಯಲು ಅರ್ಜಿಗಳನ್ನು ಆನ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ನೀಲನಕ್ಷೆಗಳು", "ಜಿಎಸ್"]', NULL, NULL, '1445');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('c90b3e8b-e3fd-439c-9f89-9717b80f45f6', 'REVENUE-DEPARTMENT-55', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'A DAFTAR REVISION PAKKA BOOK', 'General', 0, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (A DAFTAR REVISION PAKKA BOOK)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಎ ದಪ್ತರ್ ರಿವಿಜನ್ ಪಕ್ಕಾ ಪುಸ್ತಕ', NULL, NULL, NULL, NULL, NULL, 70.00, NULL, 'ಎ ದಪ್ತರ್ ರಿವಿಜನ್ ಪಕ್ಕಾ ಪುಸ್ತಕ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3059');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('2a0b6f0e-f17c-4a5b-b663-f8b872c9d974', 'FINANCE-DEPARTMENT-14', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Grant of Molasses licences', 'Public', 30, 'The Grant of Molasses Licences service enables eligible Public registered applicants to apply for a licence to store, possess, or deal with molasses, subject to the applicable departmental rules and requirements. The application is submitted to the concerned Excise Department authorities for verification and approval.', '["Blueprints", "Project Report", "Other Documents", "Land Conversion Order", "GST Registration Certificate", "PAN Card Issued by the Income Tax Department", "Partnership/Company/LLP/Proprietorship Document", "List of Directors/Partners", "Aadhaar Card", "Memorandum of Understanding", "Attested Copy of Industrial Register", "Year of Establishment", "Factory Licence", "Karnataka Pollution Control Board Clearance Certificate", "Cane Crushing Licence Issued by the Director of Sugarcane Development and Sugar", "Licence Challan", "Blueprint Showing the Exact Location of the Tank", "Electricity Supply Certificate", "Blueprint of the Complete Property", "Calibration Certificate of Tanks Issued by Legal Metrology"]', '["Public Regestration required"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಮೊಲಾಸಸ್ ಪರವಾನಗಿಗಳ ಮಂಜೂರಾತಿ', 'The Grant of Molasses Licences service enables eligible Public registered applicants to apply for a licence to store, possess, or deal with molasses, subject to the applicable departmental rules and requirements. The application is submitted to the concerned Excise Department authorities for verification and approval.', NULL, 'State Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಮೊಲಾಸಿಸ್ ಪರವಾನಗಿಗಳನ್ನು ಮಂಜೂರು ಮಾಡುವ ಸೇವೆಯು ಅನ್ವಯವಾಗುವ ಇಲಾಖಾ ನಿಯಮಗಳು ಮತ್ತು ಅವಶ್ಯಕತೆಗಳಿಗೆ ಒಳಪಟ್ಟು ಮೊಲಾಸಿಸ್ ಸಂಗ್ರಹಿಸಲು, ಹೊಂದಿರಲು ಅಥವಾ ವ್ಯವಹರಿಸಲು ಅರ್ಹ ಅರ್ಜಿದಾರರಿಗೆ ಪರವಾನಗಿಗಾಗಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಲು ಅವಕಾಶ ನೀಡುತ್ತದೆ. ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲನೆ ಮತ್ತು ಅನುಮೋದನೆಗಾಗಿ ಸಂಬಂಧಪಟ್ಟ ಅಬಕಾರಿ ಇಲಾಖೆಯ ಅಧಿಕಾರಿಗಳಿಗೆ ಸಲ್ಲಿಸಲಾಗುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ನೀಲನಕ್ಷೆಗಳು", "ಯೋಜನಾ ವರದಿ", "ಇತರೆ ದಾಖಲೆಗಳು", "ಭೂ ಪರಿವರ್ತನೆ ಆದೇಶ", "GST ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರ", "ಆದಾಯ ತೆರಿಗೆ ಇಲಾಖೆಯಿಂದ ನೀಡಲಾದ PAN ಕಾರ್ಡ್", "ಪಾಲುದಾರಿಕೆ ಸಂಸ್ಥೆ/ಕಂಪನಿ/LLP/ಏಕಮಾಲೀಕತ್ವ ಸಂಸ್ಥೆಯ ದಾಖಲೆ", "ನಿರ್ದೇಶಕರು/ಪಾಲುದಾರರ ಪಟ್ಟಿ", "ಆಧಾರ್ ಕಾರ್ಡ್", "ತಿಳುವಳಿಕೆ ಒಪ್ಪಂದ", "ಕೈಗಾರಿಕಾ ನೋಂದಣಿಯ ದೃಢೀಕೃತ ಪ್ರತಿ", "ಸ್ಥಾಪನೆಯ ವರ್ಷ", "ಕಾರ್ಖಾನೆ ಪರವಾನಗಿ", "ಕರ್ನಾಟಕ ಮಾಲಿನ್ಯ ನಿಯಂತ್ರಣ ಮಂಡಳಿಯ ಅನುಮತಿ ಪ್ರಮಾಣಪತ್ರ", "ಕಬ್ಬು ಅಭಿವೃದ್ಧಿ ಮತ್ತು ಸಕ್ಕರೆ ನಿರ್ದೇಶಕರಿಂದ ನೀಡಲಾದ ಕಬ್ಬು ಅರೆಯುವ ಪರವಾನಗಿ", "ಪರವಾನಗಿ ಶುಲ್ಕ ಪಾವತಿ ಚಲನ್", "ಟ್ಯಾಂಕ್"]', NULL, NULL, '1447');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('1d0a83ae-3df5-4aa8-8578-7277a4c49d69', 'FINANCE-DEPARTMENT-9', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Apply for renewal of license (EOLRS)', 'Retailer', 28, 'After final submission, the application is forwarded through the departmental workflow for verification and processing by the concerned officers at various levels,After completion of the departmental processing, the application is submitted back to the applicant. The applicant can also view the application details and track the application status online.', '["Blueprints", "GST Certificate", "Other Documents", "Challan", "Last Year Blueprint", "Approved Blueprint", "Address Proof", "PAN Card", "Copy of License", "License Copy", "Income Tax Returns", "Property Ownership Details/Lease Deed/Rental Agreement/RTC/Khata Extract, etc.", "Latest Income Tax Returns Submission as per Excise Laws/Rules", "Approved Blueprint of Previous Year", "Trade License", "GST Registration Certificate", "PAN Card Issued by the Income Tax Department", "Partnership/Company/LLP/Proprietorship Document", "List of Directors/Partners", "Memorandum of Association and Articles of Association or Partnership Deed, Whichever Is Applicable", "Clearance Certificate Issued by Karnataka State Pollution Control Board", "NOC for Smoking Zone from BBPM", "Calibration Certificate from Weight and Measures Department", "Labour Certificate from Labour Department (Non-Mandatory)", "Fire Safety Certificate", "Latest Form-A Issued by the District Registrar", "FSSAI Licence Issued by Food Safety and Standards Authority of India", "If Property Is Leased on ROMT Basis, If Applicable", "Aadhaar Card", "Current Year Licence Copy", "NOC for Smoking Zone from Concerned Authority", "Copy of Star Category Issued by the Ministry of Tourism", "Indoor Games Area Photo", "Outdoor Games Area Photo", "Library/Reading Room Photo", "Toilets Photo", "Board of Directors", "FSSAI Certificate", "List of Directors", "Company Related Documents", "IRCTC PAN Card", "4B Affidavit", "4B Declaration", "Specimen Signature", "Purchase and Sale Statement", "Application", "IRCTC General Manager Address Proof", "NOC - Ministry of Railways/IRCTC", "IRCTC Memorandum of Association (MOA)", "IRCTC–KSTDC Approval Letter", "IRCTC Building Rent Agreement", "Building Blueprint", "Stock Room Photos", "Airport NOC/Allotment Letter", "Memorandum of Association (MOA)/Articles of Association (AOA)", "Trade Licence/General Licence", "Customs Department Clearance/NOC", "Authorization Letter from Board of Directors", "NOC for Smoking Zone (Only for Wine Tavern)", "Calibration Certificate", "Form-A", "Allotment of Building Letter from Airport Authority", "Property Tax", "Aadhaar Card"]', '["Valid retailer Licence"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಪರವಾನಗಿ ನವೀಕರಣಕ್ಕಾಗಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಿ (EOLRS)', 'After final submission, the application is forwarded through the departmental workflow for verification and processing by the concerned officers at various levels,After completion of the departmental processing, the application is submitted back to the applicant. The applicant can also view the application details and track the application status online.', NULL, 'District Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಅರ್ಜಿಯನ್ನು ಅಂತಿಮವಾಗಿ ಸಲ್ಲಿಸಿದ ನಂತರ, ಪರಿಶೀಲನೆ ಮತ್ತು ಪ್ರಕ್ರಿಯೆಗಾಗಿ ಅದನ್ನು ಇಲಾಖೆಯ ಕಾರ್ಯವಿಧಾನದ ಮೂಲಕ ವಿವಿಧ ಹಂತಗಳಲ್ಲಿರುವ ಸಂಬಂಧಪಟ್ಟ ಅಧಿಕಾರಿಗಳಿಗೆ ರವಾನಿಸಲಾಗುತ್ತದೆ. ಇಲಾಖಾ ಪ್ರಕ್ರಿಯೆ ಪೂರ್ಣಗೊಂಡ ನಂತರ, ಅರ್ಜಿಯನ್ನು ಅರ್ಜಿದಾರರಿಗೆ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ. ಅರ್ಜಿದಾರರು ಆನ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ನೀಲನಕ್ಷೆಗಳು", "ಜಿಎಸ್"]', NULL, NULL, '1538');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('7b4470ea-4438-427b-93ed-065c6c0f5bcb', 'FINANCE-DEPARTMENT-39', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Local Label Intimation', 'Supplier', 0, 'The Label Brand Approval for Distillery/Brewery/Winery service is a deemed approval service through which applicants can apply online for the approval of Brands, Labels, and Sale-In details.The applicant is required to provide the necessary application, brand, label, and sale-in details and select whether the application is for a New Label or an Existing Label. The applicable fee is calculated based on the selected application type, and the applicant must complete the required payment online.', '["--NA----"]', '["Valid Supplier License"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಸ್ಥಳೀಯ ಲೇಬಲ್ ಕುರಿತಾದ ಮಾಹಿತಿ', 'The Label Brand Approval for Distillery/Brewery/Winery service is a deemed approval service through which applicants can apply online for the approval of Brands, Labels, and Sale-In details.The applicant is required to provide the necessary application, brand, label, and sale-in details and select whether the application is for a New Label or an Existing Label. The applicable fee is calculated based on the selected application type, and the applicant must complete the required payment online.', NULL, '---NA---', 'Online', NULL, NULL, NULL, 'ಡಿಸ್ಟಿಲರಿ / ಬ್ರೂವರಿ / ವೈನರಿಗಳ ಬ್ರ್ಯಾಂಡ್ ಮತ್ತು ಲೇಬಲ್ ಅನುಮೋದನೆ ಸೇವೆಯು ಪರಿಗಣಿತ ಅನುಮೋದನೆ (Deemed Approval) ಸೇವೆಯಾಗಿದ್ದು, ಅರ್ಜಿದಾರರು ಬ್ರ್ಯಾಂಡ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '2907');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('ca1706a2-2bce-4c79-92ea-7206ec612f2b', 'REVENUE-DEPARTMENT-72', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'GUT BOOK', 'General', 0, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (GUT BOOK)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಘಟ್ಟ ಬುಕ್', NULL, NULL, NULL, NULL, NULL, 35.00, NULL, 'ಘಟ್ಟ ಬುಕ್ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3092');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('dca0f8a6-441b-43e2-8d77-4be55e23b750', 'FINANCE-DEPARTMENT-38', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Export Permit of Spirit', 'Supplier', 8, 'The Export Permit of Spirit module facilitates the online submission and processing of applications for obtaining an export permit for spirit through the Excise E-Services application. The module enables applicants to submit the required application details and supporting documents online and track the application status throughout the process.After verification and approval by the concerned department, the final approval is completed through Digital Signature (DSC). Where applicable, the Range Inspector generates Form 3 after approval from the DCE and proceeds with the digital signing process.', '["Other Documents", "Request Letter", "Stock Position Report", "Authorization from KSBCL", "NOC for Import", "Export NOC", "Import Permit", "Production and Sales Report (Excise Year as on Date)"]', '["Valid Molasses Licence"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಸ್ಪಿರಿಟ್ ರಫ್ತು ಪರವಾನಗಿ', 'The Export Permit of Spirit module facilitates the online submission and processing of applications for obtaining an export permit for spirit through the Excise E-Services application. The module enables applicants to submit the required application details and supporting documents online and track the application status throughout the process.After verification and approval by the concerned department, the final approval is completed through Digital Signature (DSC). Where applicable, the Range Inspector generates Form 3 after approval from the DCE and proceeds with the digital signing process.', NULL, 'District Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಸ್ಪಿರಿಟ್ ರಫ್ತು ಪರವಾನಗಿ ಘಟಕವು ಅಬಕಾರಿ ಇ-ಸೇವೆಗಳ (Excise E-Services) ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ಸ್ಪಿರಿಟ್ ರಫ್ತು ಪರವಾನಗಿ ಪಡೆಯಲು ಅರ್ಜಿಗಳನ್ನು ಆನ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಇತರೆ ದಾಖಲೆಗಳು", "ವಿನಂತಿ ಪತ್ರ", "ದಾಸ್ತಾನು ಸ್ಥಿತಿಯ ವರದಿ", "KSBCL ನಿಂದ ಅಧಿಕೃತ ಅನುಮತಿ ಪತ್ರ", "ಆಮದು ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC)", "ರಫ್ತು ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC)", "ಆಮದು ಪರವಾನಗಿ", "ಉತ್ಪಾದನೆ ಮತ್ತು ಮಾರಾಟದ ವರದಿ (ಪ್ರಸ್ತುತ ದಿನಾಂಕದವರೆಗಿನ ಅಬಕಾರಿ ವರ್ಷದ ವಿವರಗಳು)"]', NULL, NULL, '2917');
