INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('5aba97f4-1d6f-4859-8cb2-6cee17649024', 'FOREST-ECOLOGY-AND-E-4', '7f8f3b17-6d95-4ea5-b320-9f58b7d269ec', 'Permission for cutting of Rosewood Trees', 'General', 0, '', '["Opinion from Revenue Department regarding ownership of land and trees sought for felling", "RTC", "Survey Sketch of the Land", "NOC from all owners of the land", "List of trees for which felling permission is sought", "Application Form", "Unconditional Consent of co-owners if any", "Details pertaining to disposal of felled trees"]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', 'e33ed918-f689-40d5-8459-1767ca43b5bd', 'ಬೀಟೆ ಮರಗಳ ಕಟಾವಣೆ ಮಾಡಲು ಅನುಮತಿ ನೀಡುವುದು', 'Permission for cutting of Rosewood Trees', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, 'Yes', '[]', '[]', 1, '["ಭೂಮಿ ಮತ್ತು ಕತ್ತರಿಸಲು ಉದ್ದೇಶಿಸಿರುವ ಮರಗಳ ಮಾಲೀಕತ್ವಕ್ಕೆ ಸಂಬಂಧಿಸಿದಂತೆ ಕಂದಾಯ ಇಲಾಖೆಯಿಂದ ಅಭಿಪ್ರಾಯ", "ಪಹಣಿ / ಆರ್.ಟಿ.ಸಿ", "ಭೂಮಿಯ ಸರ್ವೆ ನಕ್ಷೆ", "ಭೂಮಿಯ ಎಲ್ಲಾ ಮಾಲೀಕರಿಂದ ನಿರಾಕ್ಷೇಪಣಾ ಪತ್ರ", "ಕತ್ತರಿಸಲು ಅನುಮತಿ ಕೋರಿರುವ ಮರಗಳ ಪಟ್ಟಿ", "ಕಟಾವಣೆ ಮಾಡಲು ಅನುಮತಿ ಕೋರಿರುವ ಮರಗಳ ಪಟ್ಟಿ", "ಅರ್ಜಿ ನಮೂನೆ.", "ಸಹ-ಮಾಲೀಕರು ಇದ್ದಲ್ಲಿ, ಅವರ ಬೇಷರತ್ ಒಪ್ಪಿಗೆ ಪತ್ರ", "ಕಡಿತಲೆ ಮಾಡಿದ ಮರಗಳನ್ನು ವಿಲೇವಾರಿ ಮಾಡುವ ಕುರಿತಾದ ವಿವರಗಳು"]', NULL, NULL, '3025');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('434466bf-6330-4a98-9cf0-d30503fa4d93', 'FOREST-ECOLOGY-AND-E-5', '7f8f3b17-6d95-4ea5-b320-9f58b7d269ec', 'Permission for Cutting of Sandalwood Trees Grown in Private Lands', 'General', 0, '', '["Opinion from Revenue Department regarding ownership of land and trees sought for felling and ADLR report", "RTC", "Survey Sketch of the Land", "NOC from all owners of the land", "List of trees for which felling permission is sought", "Application Form", "Unconditional Consent of co-owners if any", "Details pertaining Depot and means of disposal of felled trees"]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', 'e33ed918-f689-40d5-8459-1767ca43b5bd', 'ಖಾಸಗಿ ಜಮೀನಿನಲ್ಲಿ ಬೆಳೆದಿರುವ ಶ್ರೀಗಂಧದ ಮರಗಳನ್ನು ಕಟಾವಣೆ ಮಾಡಲು ಅನುಮತಿ ನೀಡುವುದು', 'Permission for Cutting of Sandalwood Trees Grown in Private Lands', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, 'Yes', '[]', '[]', 1, '["ಭೂಮಿ ಮತ್ತು ಕತ್ತರಿಸಲು ಉದ್ದೇಶಿಸಿರುವ ಮರಗಳ ಮಾಲೀಕತ್ವಕ್ಕೆ ಸಂಬಂಧಿಸಿದಂತೆ ಕಂದಾಯ ಇಲಾಖೆಯಿಂದ ಅಭಿಪ್ರಾಯ ಹಾಗೂ ಭೂ ದಾಖಲೆಗಳ ಸಹಾಯಕ ನಿರ್ದೇಶಕರ (ADLR - Assistant Director of Land Records) ವರದಿ.", "ಪಹಣಿ / ಆರ್.ಟಿ.ಸಿ", "ಜಮೀನಿನ ಸರ್ವೆ ನಕ್ಷೆ", "ಭೂಮಿಯ ಎಲ್ಲಾ ಮಾಲೀಕರಿಂದ ಆಕ್ಷೇಪಣಾ ರಹಿತ ಪತ್ರ", "ಕಟಾವಣೆಗೆ ಅನುಮತಿ ಕೋರಿರುವ ಮರಗಳ ಪಟ್ಟಿ.", "ಅರ್ಜಿ ನಮೂನೆ", "ಸಹ-ಮಾಲೀಕರು ಇದ್ದಲ್ಲಿ, ಅವರ ಬೇಷರತ್ ಒಪ್ಪಿಗೆ ಪತ್ರ", "ಕಡಿತಲೆ ಮಾಡಿದ ಮರಗಳನ್ನು ವಿಲೇವಾರಿ ಮಾಡುವ ಡಿಪೋ ಮತ್ತು ವಿಧದ ಕುರಿತಾದ ವಿವರಗಳು"]', NULL, NULL, '3018');
