INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('88461f16-3308-4bba-ab62-8c519c80149c', 'DEPARTMENT-OF-AGRICU-29', 'bd008e87-a9b3-45ce-94f9-5a97bb25a386', 'Trader Registration', 'General', 2, '', '["PAN CARD", "CST REGISTRATION DOCUMENT", "GST REGISTRATION", "PROOF OF ADDRESS", "BANK GUARANTEE CERTIFICATE FROM CONCERNED BANK", "TRADERS LICENCE ISSUED BY THE DIRECTOR OF AG.MKTG.(SINGLE/UNIFIED LICENCE)", "SOLVENCY CERTIFICATE", "BANK DETAILS BANK NAME AND ADDRESS ACCOUNT NUMBER (PASS BOOK ZEROX) IFSC CODE NO BRANCH CODE NO"]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', NULL, 'ವರ್ತಕರ ನೋಂದಣಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಪಾನ್ ಕಾರ್ಡ್", "ಸಿ.ಎಸ್.ಟಿ.ರಿಜಿಸ್ಟ್ರೇಶನ್ ಪ್ರಮಾಣ ಪತ್ರ", "ವ್ಯಾಟ್ ರಿಜಿಸ್ಟ್ರೇಶನ್", "ವಿಳಾಸದ ಬಗ್ಗೆ ದಾಖಲೆ", "ಸಂಬಂಧಪಟ್ಟ ಬ್ಯಾಂಕ್ ನಿಂದ ಬ್ಯಾಂಕ್ ಗ್ಯಾರಂಟಿ ಪ್ರಮಾಣ ಪತ್ರ", "ನಿರ್ದೇಶಕರು, ಕೃಷಿ ಮಾರಾಟ ಇಲಾಖೆ, ಬೆಂಗಳೂರು ಇವರು ನೀಡಿರುವ ವರ್ತಕರ ಪರವಾನಗಿ", "ಸಾಲ್ವೆನ್ಸಿ ಸರ್ಟಿಫೀಕೇಟ್", "ಬ್ಯಾಂಕ್ ವಿವರ ಬ್ಯಾಂಕಿನ ಹೆಸರು ಮತ್ತು ವಿಳಾಸ ಖಾತೆ ಸಂಖ್ಯೆ (ಪಾಸ್ ಪುಸ್ತಕದ ಜೆರಾಕ್ಸ್ ಲಗತ್ತಿಸಬೇಕು) ಐ.ಎಫ್.ಎಸ್.ಸಿ.ಕೋಡ್ ಶಾಖೆ ಕೋಡ್ ಸಂಖ್ಯೆ"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('ee81c939-484d-4e6d-8a66-b50532e80803', 'FINANCE-DEPARTMENT-12', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Renewal of a Unit: WINERY Licensee', 'Supplier', 45, 'The Winery Renewal Module (sublease/lease/Bottled tie-up) enables applicants to submit renewal applications for their respective licenses. Applicants can verify Unit Details and Production Details, select the applicable Partial Payment or Full Payment option, and provide Registered Case Details (Till Date).The system validates all uploaded documents. If any document has expired, the applicant must upload a new valid document before proceeding. Once all required details and valid documents are provided and successfully validated, the applicant can submit the renewal application.
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('0f959f39-ef08-47f9-9422-f7e38e38978f', 'RURAL-DEVELOPMENT-AN-9', 'd1a5f9ed-d991-4f3a-81be-0215ecf4e378', 'No Objection Certificate', 'Business Related', 0, 'The No Objection Certificate is required to be procured from the Grama Panchayat in cases such as for Obtaining Electrical Connection, Land Conversion, Permission for Stone Crusher Units etc', '["Tax Paid Receipt", "Work Estimation from Electric Supply Companies.", "E-Swathu Form", "RTC Copy", "Permission Letter from Concerned Department"]', '["Applicant requiring NOC for the proposed activity."]', '[]', '["Citizen drafts the application.", "Applicant submits the application.", "Stage 1 - Document Verification is carried out. If Rejected -> application is returned to the citizen/applicant (process ends). If Approved -> proceeds to Stage 2.", "Stage 2 - Field Verification Report is prepared.", "Stage 3 - Application goes for Approval. If Rejected -> application is returned to the citizen/applicant (process ends). If Approved -> proceeds.", "Citizen pays the Service Fee.", "Stage 4 - Digital Signature is applied by the authorised officer.", "Service is Completed."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ', 'Application for the Permission to Avail NOC.', NULL, 'Rural and Urban Local Body Jurisdiction', 'Both', NULL, NULL, NULL, 'ವಿದ್ಯುತ್ ಸಂಪರ್ಕ ಪಡೆಯುವುದು, ಭೂ ಪರಿವರ್ತನೆ, ಕಲ್ಲು ಪುಡಿಮಾಡುವ ಘಟಕಗಳಿಗೆ ಅನುಮತಿ ಮುಂತಾದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಗ್ರಾಮ ಪಂಚಾಯಿತಿಯಿಂದ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರವನ್ನು ಪಡೆಯುವುದು ಅಗತ್ಯವಾಗಿರುತ್ತದೆ.', NULL, NULL, NULL, NULL, 'Sakala', '["ಪ್ರಸ್ತಾವಿತ ಚಟುವಟಿಕೆಗೆ ನಿರಾಕ್ಷೇಪಣಾ ಪ್ರಮಾಣಪತ್ರ (NOC) ಅಗತ್ಯವಿರುವ ಅರ್ಜಿದಾರ."]', '["ನಾಗರಿಕರು ಅರ್ಜಿಯ ಕರಡು ಸಿದ್ಧಪಡಿಸುತ್ತಾರೆ.", "ಅರ್ಜಿದಾರರು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸುತ್ತಾರೆ.", "ಹಂತ 1 - ದಾಖಲೆ ಪರಿಶೀಲನೆ ನಡೆಸಲಾಗುತ್ತದೆ. ತಿರಸ್ಕರಿಸಿದರೆ -> ಅರ್ಜಿಯನ್ನು ನಾಗರಿಕ/ಅರ್ಜಿದಾರರಿಗೆ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ (ಪ್ರಕ್ರಿಯೆ ಮುಗಿಯುತ್ತದೆ). ಅನುಮೋದಿಸಿದರೆ -> ಹಂತ 2ಕ್ಕೆ ಮುಂದುವರಿಯುತ್ತದೆ.", "ಹಂತ 2 - ಕ್ಷೇತ್ರ ಪರಿಶೀಲನಾ ವರದಿಯನ್ನು ಸಿದ್ಧಪಡಿಸಲಾಗುತ್ತದೆ.", "ಹಂತ 3 - ಅರ್ಜಿಯನ್ನು ಅನುಮೋದನೆಗಾಗಿ ಕಳುಹಿಸಲಾಗುತ್ತದೆ. ತಿರಸ್ಕರಿಸಿದರೆ -> ಅರ್ಜಿಯನ್ನು ನಾಗರಿಕ/ಅರ್ಜಿದಾರರಿಗೆ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ. ಅನುಮೋದಿಸಿದರೆ -> ಮುಂದುವರಿಯುತ್ತದೆ.", "ನಾಗರಿಕರು ಸೇವಾ ಶುಲ್ಕವನ್ನು ಪಾವತಿಸುತ್ತಾರೆ.", "ಹಂತ 4 - ಅಧಿಕೃತ ಅಧಿಕಾರಿ ಡಿಜಿಟಲ್ ಸಹಿ ಮಾಡುತ್ತಾರೆ.", "ಸೇವೆ ಪೂರ್ಣಗೊಳ್ಳುತ್ತದೆ."]', 1, '["ತೆರಿಗೆ ಪಾವತಿಸಿದ ರಶೀದಿ", "ವಿದ್ಯುತ್ ಸರಬರಾಜು ಕಂಪನಿಗಳಿಂದ ಕೆಲಸದ ಅಂದಾಜು.", "ಇ-ಸ್ವಾತು ಫಾರ್ಮ್", "ಆರ್"]', NULL, NULL, '2401');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('f8c00331-c4c3-468a-996f-92c5b24e9d93', 'FINANCE-DEPARTMENT-13', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Renewal of a Unit: MICROBREWERY Licensee', 'Supplier', 45, 'The Microbrewery Renewal module enables applicants to submit renewal applications for their microbrewery license. In the application, the user can verify the Unit Details, Annual Installed Capacity, Consolidated Payment Details, Number of Storage Tanks, and their Types. The applicant must select whether the payment is Partial or Full Payment, as applicable. The system also validates the uploaded documents, and if any document has expired, uploading a new valid document is mandatory before proceeding with the application. The applicant is also required to provide the Registered Case Details (Till Date). Once all the required details and documents are provided and validated, the applicant can submit the renewal application.After submission, the application is forwarded through the approval workflow. Upon approval at the final stage, the applicant can download the digitally signed Proceeding Copy and Renewed License Copy. The renewed license will be valid for 5 years, while the applicable license fee is payable annually.', '["Other Documents", "List of Apparatus and Inventory of the Unit (Signed Copies) and Quantity", "Previous Year''s Approved Blueprint", "Blueprint Submitted for Approval", "Property Ownership Details/Lease Deed/Rental Agreement/RTC/Khata Extract, etc.", "Previous Year''s Pending Cases Disposal Details, Including Penalties and Copies of Orders", "Past Two Years'' Payment Details from the Unit to the Government Under Different Heads of Account", "Previous Two Years'' Raw Material Receipts/Utilization/Self-Declaration (OB, Lifted, Wastage/Utilized, CB)", "Self-Declaration/Affidavit/Statement Confirming That No Dues Are Pending to the Government from the Licensee", "Cost Accountant Report", "Latest Income Tax Returns Submission as per Excise Laws/Rules", "Last Year''s Licence Copy (All Types of Licences)", "Self-Declaration Regarding Cases Pending Against the Unit", "Last Two Years'' Production Details", "ED and AED Realization Statement for the Previous Two Years", "Audit Para Details, If Applicable", "Appointment Order Copy of In-House Chemist and Work Certificates", "Partnership/Company/LLP/Proprietorship Document", "Clearance Certificate Issued by the Karnataka State Pollution Control Board", "List of Tanks, Capacity and Type", "Disqualification Declaration/Affidavit", "Legal Metrology Certificate of Verification"]', '["Valid MICROBREWERY Licensee"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ಘಟಕದ ನವೀಕರಣ: ಮೈಕ್ರೋಬ್ರೂವರಿ (Microbrewery) ಪರವಾನಗಿದಾರ', 'The Microbrewery Renewal module enables applicants to submit renewal applications for their microbrewery license. In the application, the user can verify the Unit Details, Annual Installed Capacity, Consolidated Payment Details, Number of Storage Tanks, and their Types. The applicant must select whether the payment is Partial or Full Payment, as applicable. The system also validates the uploaded documents, and if any document has expired, uploading a new valid document is mandatory before proceeding with the application. The applicant is also required to provide the Registered Case Details (Till Date). Once all the required details and documents are provided and validated, the applicant can submit the renewal application.After submission, the application is forwarded through the approval workflow. Upon approval at the final stage, the applicant can download the digitally signed Proceeding Copy and Renewed License Copy. The renewed license will be valid for 5 years, while the applicable license fee is payable annually.', NULL, 'State Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ಮೈಕ್ರೋಬ್ರೂವರಿ ಪರವಾನಗಿ ನವೀಕರಣ ಘಟಕವು ಅರ್ಜಿದಾರರು ತಮ್ಮ ಮೈಕ್ರೋಬ್ರೂವರಿ ಪರವಾನಗಿಯನ್ನು ನವೀಕರಿಸಲು ಅರ್ಜಿಗಳನ್ನು ಸಲ್ಲಿಸಲು ಅವಕಾಶ ಕಲ್ಪಿಸುತ್ತದೆ. ಅರ್ಜಿಯಲ್ಲಿ ಅರ್ಜಿದಾರರು ಘಟಕದ ವಿವರಗಳು, ವಾರ್ಷಿಕ ಸ್ಥಾಪಿತ ಉತ್ಪಾದನಾ ಸಾಮರ್ಥ್ಯ, ಒಟ್ಟು ಪಾವತಿ ವಿವರಗಳು, ಸಂಗ್ರಹಣಾ ಟ್ಯಾಂಕ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಇತರೆ ದಾಖಲೆಗಳು", "ಘಟಕದಲ್ಲಿರುವ ಉಪಕರಣಗಳು ಮತ್ತು ದಾಸ್ತಾನುಗಳ ಪಟ್ಟಿ (ಸಹಿ ಮಾಡಿದ ಪ್ರತಿಗಳು) ಹಾಗೂ ಪ್ರಮಾಣ", "ಹಿಂದಿನ ವರ್ಷದ ಅನುಮೋದಿತ ನೀಲನಕ್ಷೆ", "ಅನುಮೋದನೆಗಾಗಿ ಸಲ್ಲಿಸಿದ ನೀಲನಕ್ಷೆ", "ಆಸ್ತಿ ಮಾಲೀಕತ್ವದ ವಿವರಗಳು/ಲೀಸ್ ಡೀಡ್/ಬಾಡಿಗೆ ಒಪ್ಪಂದ/RTC/ಖಾತಾ ಉತಾರ ಇತ್ಯಾದಿ", "ಹಿಂದಿನ ವರ್ಷದ ಬಾಕಿ ಪ್ರಕರಣಗಳ ಇತ್ಯರ್ಥದ ವಿವರಗಳು, ದಂಡದ ವಿವರಗಳು ಮತ್ತು ಆದೇಶಗಳ ಪ್ರತಿಗಳೊಂದಿಗೆ", "ಕಳೆದ ಎರಡು ವರ್ಷಗಳಲ್ಲಿ ಘಟಕದಿಂದ ಸರ್ಕಾರಕ್ಕೆ ವಿವಿಧ ಲೆಕ್ಕ ಶೀರ್ಷಿಕೆಗಳಡಿ ಪಾವತಿಸಿದ ಎಲ್ಲಾ ಮೊತ್ತಗಳ ವಿವರಗಳು", "ಹಿಂದಿನ ಎರಡು ವರ್ಷಗಳ ಕಚ್ಚಾ ವಸ್ತುಗಳ ಸ್ವೀಕೃತಿ/ಬಳಕೆ/ಸ್ವಯಂ ಘೋಷಣೆ (OB, ಸ್ವೀಕರಿಸಿದ ಪ್ರಮಾಣ, ವ್ಯರ್ಥವಾದ/ಬಳಸಿದ ಪ್ರಮಾಣ, CB)", "ಪರವಾನಗಿದಾರರಿಂದ ಸರ್ಕಾರಕ್ಕೆ ಯಾವುದೇ ಬಾಕಿ ಪಾವತಿಗಳು ಉಳಿದಿಲ್ಲವೆಂದು ದೃಢೀಕರಿಸುವ ಸ್ವಯಂ ಘೋಷಣೆ/ಅಫಿಡವಿಟ್/ಹೇಳಿಕೆ", "ವೆಚ್ಚ ಲೆಕ್ಕಪರಿಶೋಧಕರ ವರದಿ", "ಅಬಕಾರಿ ಕಾನೂನುಗಳು/ನಿಯಮಗಳ ಪ್ರಕಾರ ಇತ್ತೀಚಿನ ಆದಾಯ ತೆರಿಗೆ ರಿಟರ್ನ್ಸ್ ಸಲ್ಲಿಸಿದ ದಾಖಲೆ", "ಹಿಂದಿನ ವರ್ಷದ ಪರವಾನಗಿಯ ಪ್ರತಿ (ಎಲ್ಲಾ ವಿಧದ ಪರವಾನಗಿಗಳು)", "ಘಟಕದ ವಿರುದ್ಧ ಬಾಕಿ ಇರುವ ಪ್ರಕರಣಗಳಿಗೆ ಸಂಬಂಧಿಸಿದ ಸ್ವಯಂ ಘೋಷಣೆ", "ಕಳೆದ ಎರಡು ವರ್ಷಗಳ ಉತ್ಪಾದನಾ ವಿವರಗಳು", "ಹಿಂದಿನ ಎರಡು ವರ್ಷಗಳ ED ಮತ್ತು AED ವಸೂಲಾತಿ ವಿವರಗಳ ಹೇಳಿಕೆ", "ಅನ್ವಯಿಸಿದಲ್ಲಿ, ಲೆಕ್ಕಪರಿಶೋಧನಾ ಆಕ್ಷೇಪಣೆಗಳ ವಿವರಗಳು", "ಘಟಕದ ಆಂತರಿಕ ರಸಾಯನಶಾಸ್ತ್ರಜ್ಞರ ನೇಮಕಾತಿ ಆದೇಶದ ಪ್ರತಿ ಮತ್ತು ಕಾರ್ಯನಿರ್ವಹಣೆಯ ಪ್ರಮಾಣಪತ್ರಗಳು", "ಪಾಲುದಾರಿಕೆ ಸಂಸ್ಥೆ/ಕಂಪನಿ/LLP/ಏಕಮಾಲೀಕತ್ವ ಸಂಸ್ಥೆಯ ದಾಖಲೆ", "ಕರ್ನಾಟಕ ರಾಜ್ಯ ಮಾಲಿನ್ಯ ನಿಯಂತ್ರಣ ಮಂಡಳಿಯಿಂದ ನೀಡಲಾದ ಅನುಮತಿ ಪ್ರಮಾಣಪತ್ರ", "ಟ್ಯಾಂಕ್"]', NULL, NULL, '2941');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('1f193981-4af0-4a93-8d35-ced128698a1e', 'DEPARTMENT-OF-AGRICU-28', 'bd008e87-a9b3-45ce-94f9-5a97bb25a386', 'Grievances_weighment of commodities in market yard', 'General', 15, '', '["Farmers facing difficulties submitting applications"]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', NULL, 'ಮಾರುಕಟ್ಟೆ ಪ್ರಾಂಗಣದಲ್ಲಿ ರಿವಾಜುಗಳ ಕುರಿತು ಕುಂದು ಕೊರತೆ.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ತೊಂದರೆಗೊಳಪಟ್ಟ ರೈತರು ಅರ್ಜಿ ಸಲ್ಲಿಸುವುದು"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('d60ce966-be64-4a77-b426-4eba55da219c', 'FINANCE-DEPARTMENT-31', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Export Permit - Outside State', 'Supplier', 8, 'The Export Permit Outside State module enables eligible Distilleries, Breweries, Wineries, and other authorized Excise licensees to apply online for permits to transport excisable products from Karnataka to other States against an approved concurrence. The module facilitates online application submission, document verification, departmental approvals, and issuance of digitally signed Export Permits through a transparent, secure, and workflow-driven process.', '["Other Documents", "Import Permit Document", "Concurrence for Export", "Export Duty Challan", "Warehouse Stock Position as on Date", "Chemical Report"]', '["Valid Molasses Licence"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ರಫ್ತು ಪರವಾನಗಿ - ರಾಜ್ಯದ ಹೊರಗೆ', 'The Export Permit Outside State module enables eligible Distilleries, Breweries, Wineries, and other authorized Excise licensees to apply online for permits to transport excisable products from Karnataka to other States against an approved concurrence. The module facilitates online application submission, document verification, departmental approvals, and issuance of digitally signed Export Permits through a transparent, secure, and workflow-driven process.', NULL, 'District Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ರಾಜ್ಯದ ಹೊರಗೆ ರಫ್ತು ಪರವಾನಗಿ (Export Permit Outside State) ಘಟಕವು ಅರ್ಹ ಡಿಸ್ಟಿಲರಿಗಳು, ಬ್ರೂವರಿಗಳು, ವೈನರಿಗಳು ಮತ್ತು ಇತರ ಅಧಿಕೃತ ಅಬಕಾರಿ ಪರವಾನಗಿದಾರರಿಗೆ ಅನುಮೋದಿತ ಕನ್ಕರೆನ್ಸ್ ಆಧಾರದ ಮೇಲೆ ಕರ್ನಾಟಕದಿಂದ ಇತರ ರಾಜ್ಯಗಳಿಗೆ ಅಬಕಾರಿ ನಿಯಂತ್ರಣಕ್ಕೊಳಪಡುವ ಉತ್ಪನ್ನಗಳನ್ನು ಸಾಗಿಸಲು ಆನ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಇತರೆ ದಾಖಲೆಗಳು", "ಆಮದು ಪರವಾನಗಿ ದಾಖಲೆ", "ರಫ್ತಿಗೆ ಸಮ್ಮತಿ ಪತ್ರ", "ರಫ್ತು ಸುಂಕ ಪಾವತಿ ಚಲನ್", "ದಿನಾಂಕದಂದು ಗೋದಾಮಿನಲ್ಲಿರುವ ದಾಸ್ತಾನು ಸ್ಥಿತಿಯ ವರದಿ", "ರಾಸಾಯನಿಕ ವರದಿ"]', NULL, NULL, '2953');
