INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('cb063afb-8498-4a8b-9395-2eeb9fca2def', 'DEPARTMENT-OF-AGRICU-12', 'bd008e87-a9b3-45ce-94f9-5a97bb25a386', 'Retail Traders Licence', 'General', 45, '', '["APPLICATION TO BE SUBMITTED IN FORM NO.42 OF KARNATAKA AGRICULTURAL PRODUCE MARKET (DEVELOPMENT AND REGULATION) RULES 1968", "LICENCE FEE D.D OF RS.90/- PER ANNUM DRAWN IN FAVOUR OF SECRETARY APMC TO BE ENCLOSED.", "RENTAL AGREEMENT /OWNERSHIP DOCUMENTS ALONG WITH RECENT ENCUMBRANCE CERTIFICATE OF THE BUSINESS PREMISE TO BE ENCLOSED.", "LICENCE AGREEMENT ON STAMP PAPER BEARING FACE VALUE RS.100/- TO BE ENCLOSED.", "THREE RECENT PASSPORT SIZE PHOTOGRAPHS OF THE APPLICANT TO BE ENCLOSED. IN CASE OF PARTNERSHIP FIRM 03 RECENT PASSPORT SIZE PHOTOGRAPHS OF EACH OF THE PARTNER TO BE ENCLOSED.", "ANY ONE OF THE DOCUMENTS SUCH AS DRIVING LICENCE/VOTER ID/RATION CARD/ADHAR CARD/PASSPORT ABOUT PERMANENT RESIDENTIAL ADDRESS TO BE ENCLOSED. 6. ANY ONE OF THE DOCUMENTS SUCH AS DRIVING LICENCE/VOTER ID/RATION CARD/ADHAR CARD/PASSPORT ABOUT PERMANENT RESIDENTIAL ADDRESS TO BE ENCLOSED.", "IN CASE OF A COMPANY MEMORANDUM OF ARTICLE OF ASSOCIATION TO BE ENCLOSED RESPECTIVELY.", "CERTIFIED AFFIDAVIT COPY BY THE NOTARY TO BE ENCLOSED"]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', NULL, 'ಚಿಲ್ಲರೆ ವರ್ತಕರ ಪರವಾನಗಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಕರ್ನಾಟಕ ಕೃಷಿ ಉತ್ಪನ್ನ ಮಾರುಕಟ್ಟೆ (ಅಭಿವೃದ್ಧಿ ಮತ್ತು ನಿಯಂತ್ರಣ) ನಿಯಮಗಳು, 1968ರ ನಮೂನೆ ಸಂಖ್ಯೆ 42ರಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಎಪಿಎಂಸಿ (APMC) ಕಾರ್ಯದರ್ಶಿಯವರ ಹೆಸರಿನಲ್ಲಿ ಪಡೆದ ವಾರ್ಷಿಕ ರೂ. 90/- ರ ಪರವಾನಗಿ ಶುಲ್ಕದ ಡಿ.ಡಿ. (DD) ಯನ್ನು ಲಗತ್ತಿಸಬೇಕು.", "ವ್ಯಾಪಾರ ನಡೆಯುವ ಸ್ಥಳದ ಬಾಡಿಗೆ ಒಪ್ಪಂದ ಅಥವಾ ಮಾಲೀಕತ್ವದ ದಾಖಲೆಗಳು ಹಾಗೂ ಇತ್ತೀಚಿನ ಭಾರರಹಿತ ಪ್ರಮಾಣಪತ್ರವನ್ನು (Encumbrance Certificate) ಲಗತ್ತಿಸಬೇಕು.", "ರೂ. 100/- ಮುಖಬೆಲೆಯ ಸ್ಟಾಂಪ್ ಪೇಪರ್"]', NULL, NULL, NULL);
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('bdc782ac-52ea-43b0-bb50-75168b195e1c', 'DEPARTMENT-OF-AGRICU-11', 'bd008e87-a9b3-45ce-94f9-5a97bb25a386', 'Crusher Licence', 'General', 45, '', '["APPLICATION TO BE SUBMITTED IN FORM NO.41-D OF KARNATAKA AGRICULTURAL PRODUCE MARKET (DEVELOPMENT AND REGULATION) RULES 1968", "2. LICENCE FEE D.D OF RS.350/- PER ANNUM DRAWN IN FAVOUR OF SECRETARY APMC AND DD OF RS.1200/- DRAWN IN FAVOUR OF SECRETARY APMC TOWARDS SUBSCRIPTION OF KRISHI PETE MAGAZINE TO BE ENCLOSED.AGRICULTURAL PRODUCE MARKET (DEVELOPMENT AND REGULATION) RULES 1968", "3. RENTAL AGREEMENT /OWNERSHIP DOCUMENTS ALONG WITH RECENT ENCUMBRANCE CERTIFICATE OF THE BUSINESS PREMISE TO BE ENCLOSED.", "4. LICENCE AGREEMENT ON STAMP PAPER BEARING FACE VALUE RS.100/- TO BE ENCLOSED.", "5. COPY OF THE GST REGISTRATION CERTIFICATE TO BE ENCLOSED.", "6. THREE RECENT PASSPORT SIZE PHOTOGRAPHS OF THE APPLICANT TO BE ENCLOSED. IN CASE OF PARTNERSHIP FIRM 03 RECENT PASSPORT SIZE PHOTOGRAPHS OF EACH OF THE PARTNER TO BE ENCLOSED.", "7. ANY ONE OF THE DOCUMENTS SUCH AS DRIVING LICENCE/VOTER ID/RATION CARD/ADHAR CARD/PASSPORT ABOUT PERMANENT RESIDENTIAL ADDRESS TO BE ENCLOSED.", "8. IN CASE OF PARTNERSHIP FIRM, PARTNERSHIP FIRM AND A COMPANY A PARTNERSHIP DEED REGISTERED AT REGISTRAR OF FIRMS AND MEMORANDUM OF ARTICLE TO BE ENCLOSED RESPECTIVELY.", "9. NO OBJECTION CERTIFICATE ISSUED BY THE MARKET COMMITTEE TO BE ENCLOSED IF THE APPLICANT OBTAINED BUSINESS PREMISES ON RENTAL BASIS IN THE MARKET YARD."]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', NULL, 'ಕೃಷರ್ಸ್', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಕರ್ನಾಟಕ ಕೃಷಿ ಉತ್ಪನ್ನ ಮಾರುಕಟ್ಟೆ (ಅಭಿವೃದ್ಧಿ ಮತ್ತು ನಿಯಂತ್ರಣ) ನಿಯಮಗಳು, 1968ರ ನಮೂನೆ ಸಂಖ್ಯೆ 41-D ರಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ವಾರ್ಷಿಕ ಪರವಾನಗಿ ಶುಲ್ಕಕ್ಕಾಗಿ APMC ಕಾರ್ಯದರ್ಶಿಯವರ ಹೆಸರಿನಲ್ಲಿ ಪಡೆದ ರೂ. 350/- ರ ಡಿ.ಡಿ. (DD) ಹಾಗೂ ''ಕೃಷಿ ಪೇಟೆ'' (Krishi Pete) ಪತ್ರಿಕೆಯ ಚಂದಾದಾರಿಕೆಗಾಗಿ APMC ಕಾರ್ಯದರ್ಶಿಯವರ ಹೆಸರಿನಲ್ಲಿ ಪಡೆದ ರೂ. 1200/- ರ ಡಿ.ಡಿ.ಯನ್ನು ಲಗತ್ತಿಸಬೇಕು.", "ವ್ಯಾಪಾರ ನಡೆಯುವ ಸ್ಥಳದ ಬಾಡಿಗೆ ಒಪ್ಪಂದ ಅಥವಾ ಮಾಲೀಕತ್ವದ ದಾಖಲೆಗಳು ಹಾಗೂ ಇತ್ತೀಚಿನ ಭಾರರಹಿತ ಪ್ರಮಾಣಪತ್ರವನ್ನು (Encumbrance Certificate) ಲಗತ್ತಿಸಬೇಕು.", "ರೂ. 100/- ಮುಖಬೆಲೆಯ ಸ್ಟಾಂಪ್ ಪೇಪರ್"]', NULL, NULL, NULL);
