INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('76e4dcf7-2fa1-4043-83ef-d67c3eec845a', 'DEPARTMENT-OF-AGRICU-6', 'bd008e87-a9b3-45ce-94f9-5a97bb25a386', 'Processor Licence', 'General', 45, '', '["APPLICATION TO BE SUBMITTED IN FORM NO.41-D OF KARNATAKA AGRICULTURAL PRODUCE MARKET (DEVELOPMENT AND REGULATION) RULES 1968", "LICENCE FEE D.D OF RS.350/- PER ANNUM DRAWN IN FAVOUR OF SECRETARY APMC AND DD OF RS.1200/- DRAWN IN FAVOUR OF SECRETARY APMC TOWARDS SUBSCRIPTION OF KRISHI PETE MAGAZINE TO BE ENCLOSED.AGRICULTURAL PRODUCE MARKET (DEVELOPMENT AND REGULATION) RULES 1968", "RENTAL AGREEMENT /OWNERSHIP DOCUMENTS ALONG WITH RECENT ENCUMBRANCE CERTIFICATE OF THE BUSINESS PREMISE TO BE ENCLOSED.", ". LICENCE AGREEMENT ON STAMP PAPER BEARING FACE VALUE RS.100 TO BE ENCLOSED.", "COPY OF THE GST REGISTRATION CERTIFICATE TO BE ENCLOSED.", "THREE RECENT PASSPORT SIZE PHOTOGRAPH OF THE APPLICANT TO BE ENCLOSED. IN CASE OF PARTNERSHIP FIRM 03 RECENT PASSPORT SIZE PHOTOGRAPH OF EACH OF THE PARTNER TO BE ENCLOSED.", "ANY ONE OF THE DOCUMENT SUCH AS DRIVING LICENCE/VOTER ID/RATION CARD/ADHAR CARD/PASSPORT ABOUT PERMANENT RESIDENTIAL ADDRESS TO BE ENCLOSED.", ". IN CASE OF PARTNERSHIP FIRM, PARTNERSHIP FIRM AND A COMPANY A PARTNERSHIP DEED REGISTERED AT REGISTRAR OF FIRMS AND MEMORANDUM OF ARTICLE TO BE ENCLOSED RESPECTIVELY.", "NO OBJECTION CERTIFICATE ISSUED BY THE MARKET COMMITTEE TO BE ENCLOSED IF THE APPLICANT OBTAINED BUSINESS PREMISES ON RENTAL BASIS IN THE MARKET YARD."]', '[]', '[]', '[]', NULL, NULL, NULL, true, '2026-10-30 16:55:56.458552+00', NULL, 'ಪ್ರೊಸೆಸರ್ ಪರವಾನಗಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಕರ್ನಾಟಕ ಕೃಷಿ ಉತ್ಪನ್ನ ಮಾರುಕಟ್ಟೆ (ಅಭಿವೃದ್ಧಿ ಮತ್ತು ನಿಯಂತ್ರಣ) ನಿಯಮಗಳು, 1968ರ ನಮೂನೆ 41-ಡಿ (Form No. 41-D) ರಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಪರವಾನಗಿ ಶುಲ್ಕಕ್ಕಾಗಿ ಎಪಿಎಂಸಿ (APMC) ಕಾರ್ಯದರ್ಶಿಯವರ ಹೆಸರಿನಲ್ಲಿ ಪಡೆದ ರೂ. 350/- ರ ಡಿ.ಡಿ. (DD) ಹಾಗೂ ''ಕೃಷಿ ಪೇಟೆ'' (Krishi Pete) ಪತ್ರಿಕೆಯ ಚಂದಾದಾರಿಕೆಗಾಗಿ ಎಪಿಎಂಸಿ ಕಾರ್ಯದರ್ಶಿಯವರ ಹೆಸರಿನಲ್ಲಿ ಪಡೆದ ರೂ. 1200/- ರ ಡಿ.ಡಿ.ಯನ್ನು ಲಗತ್ತಿಸಬೇಕು.", "ವ್ಯಾಪಾರ ನಡೆಯುವ ಸ್ಥಳದ ಬಾಡಿಗೆ ಒಪ್ಪಂದ ಅಥವಾ ಮಾಲೀಕತ್ವದ ದಾಖಲೆಗಳು ಹಾಗೂ ಇತ್ತೀಚಿನ ಭಾರರಹಿತ ಪ್ರಮಾಣಪತ್ರವನ್ನು (Encumbrance Certificate) ಲಗತ್ತಿಸಬೇಕು.", "ರೂ. 100/- ಮುಖಬೆಲೆಯ ಸ್ಟಾಂಪ್ ಪೇಪರ್"]', NULL, NULL, NULL);
