INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('386e95ba-c4ec-4d5c-a646-764ddc2fa5aa', 'FINANCE-DEPARTMENT-8', '1ab71a02-d046-4bf1-bd69-f13fc385ea7a', 'Approval of Blueprint', 'Retailer', 20, 'The Approval of Blueprint module facilitates the online submission and processing of applications for approval of a proposed extension or modification of the approved blueprint through the Excise E-Services application. This service can be used when there is an alteration or extension of the licensed premises, and the applicant needs to update the corresponding premises details in the profile.', '["Other Documents", "Blueprint of Proposed Place", "Address Proof", "PAN Card", "Building Owner Consent/Rent Agreement/Katha", "License Copy", "Existing Blueprint of License"]', '["Valid retailer Licence"]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', NULL, 'ನಕ್ಷೆಯ ಅನುಮೋದನೆ', 'The Approval of Blueprint module facilitates the online submission and processing of applications for approval of a proposed extension or modification of the approved blueprint through the Excise E-Services application. This service can be used when there is an alteration or extension of the licensed premises, and the applicant needs to update the corresponding premises details in the profile.', NULL, 'District Level Jurisdiction', 'Online', NULL, NULL, NULL, 'ನಕ್ಷೆ ಅನುಮೋದನೆ ಘಟಕವು ಅಬಕಾರಿ ಇ-ಸೇವೆಗಳ ಅಪ್ಲಿಕೇಶನ್ ಮೂಲಕ ಅನುಮೋದಿತ ನಕ್ಷೆಯಲ್ಲಿ ಪ್ರಸ್ತಾಪಿತ ವಿಸ್ತರಣೆ ಅಥವಾ ಮಾರ್ಪಾಡಿಗೆ ಅನುಮೋದನೆ ಕೋರುವ ಅರ್ಜಿಗಳನ್ನು ಆನ್', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '["ಇತರೆ ದಾಖಲೆಗಳು", "ಪ್ರಸ್ತಾವಿತ ಸ್ಥಳದ ನೀಲನಕ್ಷೆ", "ವಿಳಾಸದ ಪುರಾವೆ", "ಪ್ಯಾನ್ ಕಾರ್ಡ್", "ಕಟ್ಟಡದ ಮಾಲೀಕರ ಒಪ್ಪಿಗೆ ಪತ್ರ/ಬಾಡಿಗೆ ಒಪ್ಪಂದ/ಖಾತಾ", "ಪರವಾನಗಿಯ ಪ್ರತಿ", "ಪ್ರಸ್ತುತ ಪರವಾನಗಿಗೆ ಸಂಬಂಧಿಸಿದ ನೀಲನಕ್ಷೆ"]', NULL, NULL, '1261');
