INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('99f60246-66fc-4727-b93b-fb8a2ad90b66', 'REVENUE-DEPARTMENT-133', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'Vipra Swa Udyama Nera saala scheme', 'Upliftment of economically weaker Brahmin Community', 0, 'The Board provides maximum 2lakh or minimum 1 lakh loan for self employment for Economically weaker section of the Brahmin community with 20% subsidy', '["EWS provided by Nadakacheri", "Aadhar"]', '["Belongs to Karnataka", "Age 18 to 65", "Brahmin with EWS certificate", "one applicant per family"]', '[]', '["User has to login using mobile (otp)", "User has to do aadhar ekyc", "User has to submit the EWS certificate number ( Validated with the name, year, caste & annual income)", "User has to fill the communication address and the purpose for the loan", "Use has to acknowledge the conditions and submit the application"]', NULL, NULL, 'https://ksbdb.co.in/Loan/', true, '2026-10-30 16:55:56.458552+00', 'e7e36aba-85e5-4c55-9f21-2324bd60deb0', 'ವಿಪ್ರ ಸ್ವ ಉದ್ಯಮ ನೇರ ಸಾಲ', 'Direct loan for self employment with 20% Subsidy', NULL, 'All over Karnataka', 'Online', NULL, 0.00, 0.00, 'ಬ್ರಾಹ್ಮಣ ಸಮುದಾಯದ ಆರ್ಥಿಕವಾಗಿ ದುರ್ಬಲ ವರ್ಗದವರಿಗೆ ಸ್ವಯಂ ಉದ್ಯೋಗಕ್ಕಾಗಿ, ಮಂಡಳಿಯು 20% ಸಹಾಯಧನದೊಂದಿಗೆ ಗರಿಷ್ಠ 2 ಲಕ್ಷ ಅಥವಾ ಕನಿಷ್ಠ 1 ಲಕ್ಷ ರೂಪಾಯಿಗಳ ಸಾಲವನ್ನು ಒದಗಿಸುತ್ತದೆ', NULL, NULL, NULL, false, 'NO', '["ಕರ್ನಾಟಕದ ಖಾಯಂ ನಿವಾಸಿಯಾಗಿರಬೇಕು", "ವಯಸ್ಸು 18 ರಿಂದ 65 ವರ್ಷಗಳ ಮಿತಿಯೊಳಗಿರಬೇಕು", "ಬ್ರಾಹ್ಮಣ ಸಮುದಾಯದವರಾಗಿದ್ದು, ಚಾಲ್ತಿಯಲ್ಲಿರುವ ಆರ್ಥಿಕವಾಗಿ ಹಿಂದುಳಿದ ಪ್ರಮಾಣ ಪತ್ರ ಹೊಂದಿರಬೇಕು", "ಪ್ರತಿ ಕುಟುಂಬಕ್ಕೆ ಒಬ್ಬ ಅರ್ಜಿದಾರರಾಗಿರಬೇಕು"]', '["ಬಳಕೆದಾರರು ಮೊಬೈಲ್ ಸಂಖ್ಯೆ (OTP) ಬಳಸಿ ಲಾಗಿನ್ ಆಗಬೇಕು.", "ಬಳಕೆದಾರರು ಆಧಾರ್ ಇ-ಕೆವೈಸಿ (eKYC) ಪ್ರಕ್ರಿಯೆಯನ್ನು ಪೂರ್ಣಗೊಳಿಸಬೇಕು.", "ಬಳಕೆದಾರರು EWS ಪ್ರಮಾಣಪತ್ರದ ಸಂಖ್ಯೆಯನ್ನು ಸಲ್ಲಿಸಬೇಕು (ಇದನ್ನು ಹೆಸರು, ವರ್ಷ, ಜಾತಿ ಮತ್ತು ವಾರ್ಷಿಕ ಆದಾಯದೊಂದಿಗೆ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ).", "ಬಳಕೆದಾರರು ಸಂಪರ್ಕ ವಿಳಾಸ ಮತ್ತು ಸಾಲ ಪಡೆಯುವ ಉದ್ದೇಶವನ್ನು ನಮೂದಿಸಬೇಕು.", "ಬಳಕೆದಾರರು ನಿಯಮಗಳು ಮತ್ತು ಷರತ್ತುಗಳನ್ನು ಒಪ್ಪಿಕೊಂಡು ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಬೇಕು."]', 1, '["ನಾಡಕಚೇರಿ ಒದಗಿಸಿದ EWS", "ಆಧಾರ್"]', NULL, NULL, '2932');
