INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('2ebe9f60-78ac-4c47-b19b-0a559098490e', 'FOREST-ECOLOGY-AND-E-3', '7f8f3b17-6d95-4ea5-b320-9f58b7d269ec', 'Renewal of Sawmill Licenses', 'General', 0, '', '["FORM 43 OF KARNATAKA FOREST RULES, 1969", "FORM 44 OF KARNATAKA FOREST RULES, 1969", "Existing License Copy", "PAN", "Contrivances Details", "Location details where sawmill is operated"]', '[]', '[]', '[]', NULL, NULL, 'https://evaluation.aranya.gov.in/SawMill/', true, '2026-10-30 16:55:56.458552+00', 'e33ed918-f689-40d5-8459-1767ca43b5bd', 'ಸಾಮಿಲ್', 'Sawmill Management System', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, 'Yes', '[]', '[]', 1, '["೧೯೬೯ರ ಕರ್ನಾಟಕ ಅರಣ್ಯ ನಿಯಮಗಳ ನಮೂನೆ ೪೩", "೧೯೬೯ರ ಕರ್ನಾಟಕ ಅರಣ್ಯ ನಿಯಮಗಳ ನಮೂನೆ ೪೪", "ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ಪರವಾನಗಿಯ ಪ್ರತಿ", "ಪ್ಯಾನ್ ಕಾರ್ಡ್", "ಸಾಧನಗಳು / ಯಂತ್ರೋಪಕರಣಗಳ ವಿವರಗಳು", "ಸಾ ಮಿಲ್ ಇರುವ ಸ್ಥಳದ ವಿವರಗಳು"]', NULL, NULL, '3026');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('4e2e1784-b952-4c57-875b-8de8f4e8e00c', 'DEPARTMENT-OF-ELECTR-1', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'IT Registration', 'General', 30, 'In order to facilitate the submission and processing of incentive claims, concessions and subsidies provided under the policy, all applicants are required to register with the KITS.', '["Applicants shall submit their online application for registration with KITS along with the following documents as mentioned below:", "Undertaking to be submitted by the Applicant in the prescribed format in Annexure 7.2.1.", "Submit financial details, as applicable:", "IT/ITeS Entities undergoing Expansion", "i. Audited financial statements for the last 01 year of operations.", "ii. Annual reports for the last 01 year.", "New Setups - IT/ITeS Entities", "i. Copy of Certificate of Incorporation and Supporting Documents:", "If the Applicant is a Public/ Private Company (under The Indian Companies Act, 1956/2013 and subsequent amendments):", "▪ Copy of Certificate of Incorporation", "▪ Copy of Memorandum of Association and Articles of Association", "ii. If the Applicant is a Partnership Firm or a Limited Liability Partnership (registered Partnership Firm under The Indian Partnership Act 1932 or Limited Liability Partnership Act 2008):", "Undertaking to be submitted by the Applicant in the prescribed format in Annexure 7.2.1.", "Submit financial details, as applicable:", "IT/ITeS Entities undergoing Expansion", "i. Audited financial statements for the last 01 year of operations.", "ii. Annual reports for the last 01 year.", "New Setups - IT/ITeS Entities", "i. Copy of Certificate of Incorporation and Supporting Documents:", "If the Applicant is a Public/ Private Company (under The Indian Companies Act, 1956/2013 and subsequent amendments):", "▪ Copy of Certificate of Incorporation", "▪ Copy of Memorandum of Association and Articles of Association", "ii. If the Applicant is a Partnership Firm or a Limited Liability Partnership (registered Partnership Firm under The Indian Partnership Act 1932 or Limited Liability Partnership Act 2008):", "▪ Copy of Registration Certificate", "▪ Copy of Partnership Deed▪", "Copy of Registration Certificate", "▪ Copy of Partnership Deed", "iii. If the Applicant is an Academia - Accreditation Certificate or a formal letter of recognition/approval from a government-recognized statutory regulatory authority.", "Self-attested Copy of Rental Agreement/Lease deed agreement/Khata/ Business Agreement/ Any other Registered Agreement.", "Authorization letter on company letterhead for the Person who would be coordinating with the KITS on behalf of the company / entity", "Passport sized photograph of the authorized signatory of the applicant.", "Self-attested copy of GST Registration Certificate.", "Self-attested copy of PAN Card.", "Self-attested copy of first sale invoice of services provided.", "Signed copy of application form on the applicant’s letterhead", "Additionally, Applicants are required to submit Shops and Establishment Certificate under The Karnataka Shops and Commercial Establishments Act 1961 And Rules 1963."]', '["The company shall have been established or shall have undertaken expansion on or after 17-11-2026.", "The company shall have a minimum of 10 employees.", "The applicant shall be an entity incorporated under the Companies Act, 2013, a Partnership Firm registered under the Partnership Act, 1932, or a Limited Liability Partnership (LLP) registered under the LLP Act, 2008. This shall also include State Government Universities, affiliated colleges, and industry associations."]', '[]', '["1 Registration Procedure (For New Applicants)", "IT/ITeS entities that are registered with KITS shall only be eligible for availing incentives and offerings under the Policy.", "Applicants registering for the first time shall sign up on the website (https://registration.eitbt.karnataka.gov.in/itpolicy/login ) by submitting all the required information.", "Upon successfully signing up on the website, the Applicant shall receive an activation link enabling them to activate their account. Applicants can then submit their application for registration in the prescribed format along with the supporting documents mentioned in Annexure 7.1.1.", "KITS shall assess the submitted documents and undertake physical verification/inspection of the Applicant’s operations (as applicable).", "Upon successful verification of the submitted application and confirmation of all the facts and information, a digital link shall be sent to the Applicant for making a one-time registration processing fees of INR 10,000 (Indian Rupees Ten Thousand only) and applicable GST.", "After successful payment of the registration processing fee, a digital / hardcopy Registration Certificate shall be generated and shall be sent on the registered email id of the Applicant. With this Registration Certificate, the Applicant is successfully registered with KITS.", "Once the applicant is successfully registered, online modules/functionalities for availing the incentives under the Policy shall be enabled for the Applicant’s account.", "Applicants with multiple units need to register each unit separately with KITS, However, they are not required to pay registration fees for additional units."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/itpolicy/it-register', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೋಂದಣಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ನೀತಿಯಡಿ ಒದಗಿಸಲಾಗುವ ಪ್ರೋತ್ಸಾಹಧನ, ರಿಯಾಯಿತಿಗಳು ಮತ್ತು ಸಹಾಯಧನಕ್ಕಾಗಿ ಅರ್ಜಿಗಳನ್ನು ಸಲ್ಲಿಸುವ ಹಾಗೂ ಅವುಗಳ ಪ್ರಕ್ರಿಯೆಯನ್ನು ಸುಗಮಗೊಳಿಸುವ ಉದ್ದೇಶದಿಂದ, ಎಲ್ಲಾ ಅರ್ಜಿದಾರರು KITSನಲ್ಲಿ ನೋಂದಾಯಿಸಿಕೊಳ್ಳುವುದು ಕಡ್ಡಾಯವಾಗಿರುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಕಂಪನಿಯು 17-11-2026 ರಂದು ಅಥವಾ ಆ ದಿನಾಂಕದ ನಂತರ ಸ್ಥಾಪಿತವಾಗಿರಬೇಕು ಅಥವಾ ವಿಸ್ತರಣಾ ಚಟುವಟಿಕೆಯನ್ನು ಕೈಗೊಂಡಿರಬೇಕು.", "ಕಂಪನಿಯು ಕನಿಷ್ಠ 10 ಉದ್ಯೋಗಿಗಳನ್ನು ಹೊಂದಿರಬೇಕು.", "ಅರ್ಜಿದಾರ ಸಂಸ್ಥೆಯು ಕಂಪನಿಗಳ ಕಾಯ್ದೆ, 2013ರ ಅಡಿಯಲ್ಲಿ ಸ್ಥಾಪಿತವಾದ ಕಂಪನಿಯಾಗಿರಬೇಕು ಅಥವಾ ಪಾಲುದಾರಿಕೆ ಕಾಯ್ದೆ, 1932ರ ಅಡಿಯಲ್ಲಿ ನೋಂದಾಯಿತವಾದ ಪಾಲುದಾರಿಕೆ ಸಂಸ್ಥೆಯಾಗಿರಬೇಕು ಅಥವಾ ಸೀಮಿತ ಹೊಣೆಗಾರಿಕೆ ಪಾಲುದಾರಿಕೆ ಕಾಯ್ದೆ (LLP Act), 2008ರ ಅಡಿಯಲ್ಲಿ ನೋಂದಾಯಿತವಾದ ಸೀಮಿತ ಹೊಣೆಗಾರಿಕೆ ಪಾಲುದಾರಿಕೆ ಸಂಸ್ಥೆಯಾಗಿರಬೇಕು. ಇದರ ವ್ಯಾಪ್ತಿಯಲ್ಲಿ ರಾಜ್ಯ ಸರ್ಕಾರದ ವಿಶ್ವವಿದ್ಯಾಲಯಗಳು, ಸಂಯೋಜಿತ ಕಾಲೇಜುಗಳು ಹಾಗೂ ಕೈಗಾರಿಕಾ ಸಂಘಗಳೂ ಒಳಗೊಂಡಿರುತ್ತ"]', '["1 ನೋಂದಣಿ ಪ್ರಕ್ರಿಯೆ (ಹೊಸ ಅರ್ಜಿದಾರರಿಗಾಗಿ)", "KITS ನಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರುವ ಐಟಿ/ಐಟಿಇಎಸ್ ಸಂಸ್ಥೆಗಳು ಮಾತ್ರ ಈ ನೀತಿಯಡಿ ಒದಗಿಸಲಾಗುವ ಪ್ರೋತ್ಸಾಹಧನ ಹಾಗೂ ಇತರ ಸೌಲಭ್ಯಗಳನ್ನು ಪಡೆಯಲು ಅರ್ಹರಾಗಿರುತ್ತಾರೆ.", "ಮೊದಲ ಬಾರಿಗೆ ನೋಂದಣಿ ಮಾಡಿಕೊಳ್ಳುವ ಅರ್ಜಿದಾರರು ಅಗತ್ಯವಿರುವ ಎಲ್ಲಾ ಮಾಹಿತಿಯನ್ನು ಸಲ್ಲಿಸುವ ಮೂಲಕ https://registration.eitbt.karnataka.gov.in/itpolicy/login ವೆಬ್"]', 1, '["ಅನುಬಂಧ 7.2.1 ರಲ್ಲಿರುವ ನಿಗದಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿದಾರರು ಸಲ್ಲಿಸಬೇಕಾದ ದೃಢೀಕರಣ ಪತ್ರ (Undertaking).", "ವಿಸ್ತರಣೆಗೊಳ್ಳುತ್ತಿರುವ IT/ITeS ಸಂಸ್ಥೆಗಳು", "i. ಕಳೆದ 01 ವರ್ಷದ ಕಾರ್ಯಾಚರಣೆಯ ಲೆಕ್ಕಪರಿಶೋಧಿತ ಆರ್ಥಿಕ ವರದಿಗಳು.", "ii. ಕಳೆದ 01 ವರ್ಷದ ವಾರ್ಷಿಕ ವರದಿಗಳು.", "ಹೊಸದಾಗಿ ಸ್ಥಾಪನೆಯಾದ IT/ITeS ಸಂಸ್ಥೆಗಳು", "i. ಸಂಸ್ಥೆಯ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರದ (Certificate of Incorporation) ಪ್ರತಿ ಮತ್ತು ಪೂರಕ ದಾಖಲೆಗಳು:", "ಅರ್ಜಿದಾರರು ಸಾರ್ವಜನಿಕ/ಖಾಸಗಿ ಕಂಪನಿಯಾಗಿದ್ದರೆ (ಭಾರತೀಯ ಕಂಪನಿಗಳ ಕಾಯಿದೆ, 1956/2013 ಮತ್ತು ನಂತರದ ತಿದ್ದುಪಡಿಗಳ ಅಡಿಯಲ್ಲಿ):", "▪ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರದ ಪ್ರತಿ", "▪ ಸಂಘಟನಾ ಜ್ಞಾಪಕ ಪತ್ರ (Memorandum of Association) ಮತ್ತು ಸಂಘಟನಾ ನಿಯಮಾವಳಿಗಳ (Articles of Association) ಪ್ರತಿ", "ii. ಅರ್ಜಿದಾರರು ಪಾಲುದಾರಿಕೆ ಸಂಸ್ಥೆ (Partnership Firm) ಅಥವಾ ಸೀಮಿತ ಹೊಣೆಗಾರಿಕೆ ಪಾಲುದಾರಿಕೆ (LLP) ಸಂಸ್ಥೆಯಾಗಿದ್ದರೆ (ಭಾರತೀಯ ಪಾಲುದಾರಿಕೆ ಕಾಯಿದೆ 1932 ಅಥವಾ ಸೀಮಿತ ಹೊಣೆಗಾರಿಕೆ ಪಾಲುದಾರಿಕೆ ಕಾಯಿದೆ 2008 ರ ಅಡಿಯಲ್ಲಿ ನೋಂದಾಯಿಸಲ್ಪಟ್ಟಿದ್ದರೆ):", "▪ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರದ ಪ್ರತಿ", "▪ ಪಾಲುದಾರಿಕೆ ಒಪ್ಪಂದ ಪತ್ರದ (Partnership Deed) ಪ್ರತಿ", "iii. ಅರ್ಜಿದಾರರು ಶೈಕ್ಷಣಿಕ ಸಂಸ್ಥೆಯಾಗಿದ್ದಲ್ಲಿ - ಮಾನ್ಯತಾ ಪ್ರಮಾಣಪತ್ರ ಅಥವಾ ಸರ್ಕಾರದಿಂದ ಮಾನ್ಯತೆ ಪಡೆದ ಶಾಸನಬದ್ಧ ನಿಯಂತ್ರಕ ಪ್ರಾಧಿಕಾರದಿಂದ ಅಧಿಕೃತ ಗುರುತಿಸುವಿಕೆ/ಅನುಮೋದನೆಯ ಪತ್ರ.", "ಬಾಡಿಗೆ ಒಪ್ಪಂದ / ಗುತ್ತಿಗೆ ಒಪ್ಪಂದ / ಖಾತಾ / ವ್ಯವಹಾರ ಒಪ್ಪಂದ ಅಥವಾ ನೋಂದಾಯಿತ ಒಪ್ಪಂದದ ಸ್ವಯಂ-ದೃಢೀಕೃತ ಪ್ರತಿ.", "ಕಂಪನಿ ಅಥವಾ ಸಂಸ್ಥೆಯ ಪರವಾಗಿ KITS ನೊಂದಿಗೆ ಸಮನ್ವಯ ಸಾಧಿಸುವ ವ್ಯಕ್ತಿಗೆ ಸಂಬಂಧಿಸಿದ, ಕಂಪನಿಯ ಲೆಟರ್‌ಹೆಡ್‌ನಲ್ಲಿರುವ ಅಧಿಕೃತ ಪತ್ರ (Authorization letter).", "ಅರ್ಜಿದಾರರ ಪರವಾಗಿ ಸಹಿ ಮಾಡುವ ಅಧಿಕೃತ ವ್ಯಕ್ತಿಯ ಪಾಸ್‌ಪೋರ್ಟ್ ಅಳತೆಯ ಭಾವಚಿತ್ರ.", "GST ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರದ ಸ್ವಯಂ-ದೃಢೀಕೃತ ಪ್ರತಿ.", "PAN ಕಾರ್ಡ್‌ನ ಸ್ವಯಂ-ದೃಢೀಕೃತ ಪ್ರತಿ.", "ಒದಗಿಸಿದ ಸೇವೆಗಳಿಗೆ ಸಂಬಂಧಿಸಿದ ಮೊದಲ ಮಾರಾಟದ ಇನ್‌ವಾಯ್ಸ್‌ನ (ಬಿಲ್‌ನ) ಸ್ವಯಂ-ದೃಢೀಕೃತ ಪ್ರತಿ.", "ಅರ್ಜಿದಾರರ ಲೆಟರ್‌ಹೆಡ್‌ನಲ್ಲಿರುವ, ಸಹಿ ಮಾಡಿದ ಅರ್ಜಿ ನಮೂನೆಯ ಪ್ರತಿ.", "ಹೆಚ್ಚುವರಿಯಾಗಿ, ಅರ್ಜಿದಾರರು ''ಕರ್ನಾಟಕ ಅಂಗಡಿಗಳು ಮತ್ತು ವಾಣಿಜ್ಯ ಸಂಸ್ಥೆಗಳ ಕಾಯಿದೆ 1961'' ಮತ್ತು ''ನಿಯಮಗಳು 1963'' ರ ಅಡಿಯಲ್ಲಿನ ಅಂಗಡಿ ಮತ್ತು ಸಂಸ್ಥೆಯ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರವನ್ನು ಸಲ್ಲಿಸುವುದು ಕಡ್ಡಾಯವಾಗಿದೆ."]', NULL, NULL, '3395');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('41b386cf-2220-4362-b7df-a76c7914470a', 'DEPARTMENT-OF-ELECTR-2', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Electricity duty reimbursement', 'General', 60, 'To reduce the financial burden on units setting up in Beyond Bengaluru regions, reimbursement of electricity duty shall be provided by GoK.', '["i. Copy of the Registration Certificate issued by KITS.", "ii. Self-attested copy of registered rent/ lease agreement", "iii. Self-attested copy of ESCOMs power service letter with R.R. No. and date", "iv. Self- attested copies of the last 3 months of electricity bills since the date of submission of the application", "v. Power Tariff Sanction Letter Copy (as applicable)", "vi. Copy of the letter / order - Electricity Duty Reimbursement (as applicable)", "vii. A self-attested copy on letterhead stating the reimbursement requested for the electricity duty (complete calculation along with the breakup) for the period being claimed.", "viii. Furnish complete bank account details (Account Holder Name, Bank Name, Account Number, Account type, IFSC Code, Branch Address) to facilitate the reimbursement."]', '["The IT/ITeS should be incorporated or registered in Karnataka as Private Limited Companies, / LLP/ Partnership Firms", "The IT/ ITeS entity must have at least 50% of its total workforce (employees) based in Karnataka. This count shall exclude contract employees.", "A minimum employment threshold of 10 employees in Beyound Bengaluru region and 25 employees in Bengaluru.", "The applicant shall have established a new IT/ITeS Unit in Beyond Bengaluru during the policy period.", "Where RR No. is in the name of the applicant and the applicant is also the owner of the premise, the applicant shall be eligible for this incentive.", "Where RR No. is not under applicant’s name but in the name of the developer / owner owning the premise and applicant is the sole occupant of the premise, the applicant shall be eligible for this incentive.", "Where RR No. is in the name of the developer/ owner having multiple tenants and applicant being one of them and the applicant has a sub-meter installed by the ESCOM, then the applicant shall be eligible for this incentive.", "Where RR No. is in the name of the developer/ owner having multiple tenants and applicant being one of them and the applicant is not having a sub-meter installed by the ESCOM, then the applicant shall not be eligible for this incentive."]', '[]', '["Company should be registered under the policy", "Company should submit the incentive application along with supporting documents as prescribed in the Policy OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/itpolicy/power-tariff-concession', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ವಿದ್ಯುತ್ ಸುಂಕ ಮರುಪಾವತಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಬೆಂಗಳೂರು ಹೊರಗಿನ ಪ್ರದೇಶಗಳಲ್ಲಿ ಘಟಕಗಳನ್ನು ಸ್ಥಾಪಿಸುವ ಸಂಸ್ಥೆಗಳ ಮೇಲಿನ ಆರ್ಥಿಕ ಹೊರೆಯನ್ನು ಕಡಿಮೆ ಮಾಡುವ ಉದ್ದೇಶದಿಂದ, ಕರ್ನಾಟಕ ಸರ್ಕಾರದಿಂದ ವಿದ್ಯುತ್ ಸುಂಕದ ಮರುಪಾವತಿ (Reimbursement) ಸೌಲಭ್ಯವನ್ನು ಒದಗಿಸಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಐಟಿ/ಐಟಿಇಎಸ್"]', '["ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ-2025-30 ರಡಿಯಲ್ಲಿ ನೋಂದಣಿಯಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["i. KITS ನಿಂದ ನೀಡಲಾದ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರದ ಪ್ರತಿ.", "ii. ನೋಂದಾಯಿತ ಬಾಡಿಗೆ/ಗುತ್ತಿಗೆ ಒಪ್ಪಂದದ ಸ್ವಯಂ-ದೃಢೀಕೃತ ಪ್ರತಿ", "iii. ಆರ್.ಆರ್. ಸಂಖ್ಯೆ ಮತ್ತು ದಿನಾಂಕದೊಂದಿಗೆ ESCOM ನ ವಿದ್ಯುತ್ ಸೇವಾ ಪತ್ರದ ಸ್ವಯಂ-ದೃಢೀಕೃತ ಪ್ರತಿ", "iv. ಅರ್ಜಿ ಸಲ್ಲಿಸಿದ ದಿನಾಂಕದಿಂದ ಕಳೆದ 3 ತಿಂಗಳ ವಿದ್ಯುತ್ ಬಿಲ್"]', NULL, NULL, '3396');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('d76cca76-6502-44c8-971e-abbbf1a0eaac', 'DEPARTMENT-OF-ELECTR-3', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'EPF reimbursement', 'General', 60, 'To support expenses incurred on employees of IT/ITeS companies in regions beyond Bengaluru, reimbursement of Employee Provident Fund (EPF) contributions shall be provided by the GoK.', '["i. Self-Declaration regarding the No. of new workforce/ employees being considered for the computation of the EPF contribution reimbursement incentive.", "ii. Company/Entity declaration for availing incentives for IT/ITeS unit.", "iii. CA Certified letter mentioning employee’s details, PF no., and PF contribution of the new employees recruited by the Applicant, along with Self-attested copies of the Employment record.", "iv. Self-attested copies of the Employment records for all new people employed for last 2 years: Self-attested copies of monthly employees and employer’s contribution statement from the official website of PF (https://www.epfindia.gov.in/site_en/index.php )", "v. Self-attested declaration on the official letterhead stating that appropriate recovery shall be made if the unit fails to maintain employment for a two-year period in accordance with the guidelines.", "vi. Applicants are requested to furnish complete bank account details (Account Holder Name, Bank Name, Account Number, Account type, IFSC Code, Branch Address) to facilitate the reimbursement."]', '["The IT/ITeS should be incorporated or registered in Karnataka as Private Limited Companies, / LLP/ Partnership Firms", "The IT/ ITeS entity must have at least 50% of its total workforce (employees) based in Karnataka. This count shall exclude contract employees.", "A minimum employment threshold of 10 employees in Beyound Bengaluru region and 25 employees in Bengaluru.", "The applicant shall have established a new IT/ITeS Unit in Beyond Bengaluru during the policy period.", "The applicant shall have completed at least two (2) years of commercial operations and shall have created new employment during the policy period."]', '[]', '["Company should be registered under the policy", "Company should submit the incentive application along with supporting documents as prescribed in the Policy OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/itpolicy/epf-reimbursement', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಉದ್ಯೋಗಿ ಭವಿಷ್ಯ ನಿಧಿ ಮರುಪಾವತಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಬೆಂಗಳೂರು ಹೊರಗಿನ ಪ್ರದೇಶಗಳಲ್ಲಿ IT/ITeS ಸಂಸ್ಥೆಗಳು ಉದ್ಯೋಗಿಗಳಿಗಾಗಿ ಭರಿಸುವ ಉದ್ಯೋಗಿಗಳ ಭವಿಷ್ಯ ನಿಧಿ (EPF) ಕೊಡುಗೆಯ ವೆಚ್ಚವನ್ನು ಕಡಿಮೆಗೊಳಿಸುವ ಉದ್ದೇಶದಿಂದ, IT/ITeS ಸಂಸ್ಥೆಗಳಿಗೆ EPF ಕೊಡುಗೆಯ ಮರುಪಾವತಿ ಸೌಲಭ್ಯವನ್ನು ಕರ್ನಾಟಕ ಸರ್ಕಾರವು ಒದಗಿಸುತ್ತದೆ', NULL, NULL, NULL, NULL, NULL, '["ಐಟಿ/ಐಟಿಇಎಸ್"]', '["ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ-2025-30 ರಡಿಯಲ್ಲಿ ನೋಂದಣಿಯಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["I. ಇಪಿಎಫ್ ಕೊಡುಗೆ ಮರುಪಾವತಿ ಪ್ರೋತ್ಸಾಹದ ಲೆಕ್ಕಾಚಾರಕ್ಕೆ ಪರಿಗಣಿಸಲಾಗುತ್ತಿರುವ ಹೊಸ ಉದ್ಯೋಗಿಗಳು/ಉದ್ಯೋಗಿಗಳ ಸಂಖ್ಯೆಯ ಬಗ್ಗೆ ಸ್ವಯಂ ಘೋಷಣೆ.", "II. ಐಟಿ/ಐಟಿಇಎಸ್ ಘಟಕಕ್ಕೆ ಪ್ರೋತ್ಸಾಹಕಗಳನ್ನು ಪಡೆಯಲು ಕಂಪನಿ/ಸಂಸ್ಥೆಯ ಘೋಷಣೆ.", "III. ಅರ್ಜಿದಾರರು ನೇಮಕ ಮಾಡಿಕೊಂಡ ಹೊಸ ಉದ್ಯೋಗಿಗಳ ವಿವರಗಳು, ಪಿಎಫ್ ಸಂಖ್ಯೆ ಮತ್ತು ಪಿಎಫ್ ಕೊಡುಗೆಯನ್ನು ಉಲ್ಲೇಖಿಸುವ ಸಿಎ ಪ್ರಮಾಣೀಕೃತ ಪತ್ರ, ಉದ್ಯೋಗ ದಾಖಲೆಯ ಸ್ವಯಂ-ದೃಢೀಕೃತ ಪ್ರತಿಗಳೊಂದಿಗೆ.", "IV. ಕಳೆದ 2 ವರ್ಷಗಳಿಂದ ಉದ್ಯೋಗದಲ್ಲಿರುವ ಎಲ್ಲಾ ಹೊಸ ಜನರಿಗೆ ಉದ್ಯೋಗ ದಾಖಲೆಗಳ ಸ್ವಯಂ-ದೃಢೀಕೃತ ಪ್ರತಿಗಳು: ಪಿಎಫ್"]', NULL, NULL, '3397');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('74ebe5f2-2914-4e6b-87b4-db144b04e792', 'DEPARTMENT-OF-ELECTR-5', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Internship cost reimbursement', 'General', 60, 'To encourage internship opportunities for students and fresh graduates to gain practical knowledge and work experience, financial assistance shall be provided by the GoK to eligible IT/ ITeS companies.', '["Copy of Internship Offer letters / Agreement/ Contract (as applicable)", "CA certified statement of claims submitted by the company detailing the number of interns, the stipend amount paid, and the period of reimbursement, details of the interns (name, university, date of joining & exit), completion certificate etc.,.", "Copy of documents indicating whether taxes have been deducted from the stipend, if applicable.", "A letter from the college authority stating that the internship is a part of the course curriculum.", "A detailed description of the internship program, including the nature of work, learning outcomes, and objectives.", "Applicants are requested to furnish complete bank account details (Account Holder Name, Bank Name, Account Number, Account type, IFSC Code, Branch Address) to facilitate the reimbursement."]', '["The IT/ITeS should be incorporated or registered in Karnataka as Private Limited Companies, / LLP/ Partnership Firms", "The IT/ ITeS entity must have at least 50% of its total workforce (employees) based in Karnataka. This count shall exclude contract employees.", "A minimum employment threshold of 10 employees in Beyound Bengaluru region and 25 employees in Bengaluru."]', '[]', '["Company should be registered under the policy", "Company should submit the incentive application along with supporting documents as prescribed in the Policy OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/itpolicy/internship-cost-reimbursement', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಇಂಟರ್ನ್', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ವಿದ್ಯಾರ್ಥಿಗಳು ಮತ್ತು ಇತ್ತೀಚೆಗೆ ಪದವಿ ಪಡೆದವರು ಪ್ರಾಯೋಗಿಕ ಜ್ಞಾನ ಹಾಗೂ ಕೆಲಸದ ಅನುಭವವನ್ನು ಪಡೆಯಲು ಅನುಕೂಲವಾಗುವಂತೆ ಇಂಟರ್ನ್', NULL, NULL, NULL, NULL, NULL, '["ಐಟಿ/ಐಟಿಇಎಸ್"]', '["ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ-2025-30 ರಡಿಯಲ್ಲಿ ನೋಂದಣಿಯಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["i. ಇಂಟರ್ನ್"]', NULL, NULL, '3400');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('50366382-96ef-4b78-85eb-2ca330880b27', 'DEPARTMENT-OF-ELECTR-7', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Reimbursement of Quality certifications', 'General', 60, 'Financial assistance shall be provided by the GoK to enable IT/ITeS companies to obtain quality certifications aimed at improving service standards.', '["I. Self-attested copy of the testing/certification certificate received, along with payment receipts.", "II. Copy of the certificate from accredited agencies confirming the validity of the certificate.", "III. For reimbursement for Quality Certificate - Self-attested copy of the Quality Certificate obtained from NABCB / any other accredited agencies (as applicable)", "IV. Furnish complete bank account details (Account Holder Name, Bank Name, Account Number, Account type, IFSC Code, Branch Address) to facilitate the reimbursement."]', '["The IT/ITeS should be incorporated or registered in Karnataka as Private Limited Companies, / LLP/ Partnership Firms", "The IT/ ITeS entity must have at least 50% of its total workforce (employees) based in Karnataka. This count shall exclude contract employees.", "A minimum employment threshold of 10 employees in Beyound Bengaluru region and 25 employees in Bengaluru.", "The applicant shall have established a new/expansion IT/ITeS Unit in state during the policy period.", "An applicant can avail reimbursement for certifications issued during the policy period only.", "The applicant should submit the application for reimbursement within twelve (12) months from the date of the receipt of quality certification."]', '[]', '["Company should be registered under the policy", "Company should submit the incentive application along with supporting documents as prescribed in the Policy OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/itpolicy/quality-certifications', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಗುಣಮಟ್ಟದ ಪ್ರಮಾಣೀಕರಣಗಳಿಗೆ ಮರುಪಾವತಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಸೇವಾ ಗುಣಮಟ್ಟವನ್ನು ಸುಧಾರಿಸುವ ಗುರಿಯನ್ನು ಹೊಂದಿರುವ ಗುಣಮಟ್ಟದ ಪ್ರಮಾಣೀಕರಣಗಳನ್ನು ಪಡೆಯಲು ಐಟಿ/ಐಟಿಇಎಸ್ (IT/ITeS) ಕಂಪನಿಗಳಿಗೆ ಕರ್ನಾಟಕ ಸರ್ಕಾರವು ಆರ್ಥಿಕ ನೆರವನ್ನು ಒದಗಿಸುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಐಟಿ/ಐಟಿಇಎಸ್"]', '["ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ-2025-30 ರಡಿಯಲ್ಲಿ ನೋಂದಣಿಯಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["i. ಪಾವತಿ ರಸೀದಿಗಳೊಂದಿಗೆ ಸ್ವೀಕರಿಸಿದ ಪರೀಕ್ಷೆ/ಪ್ರಮಾಣೀಕರಣ ಪ್ರಮಾಣಪತ್ರದ ಸ್ವಯಂ-ದೃಢೀಕೃತ ಪ್ರತಿ.", "ii. ಪ್ರಮಾಣಪತ್ರದ ಸಿಂಧುತ್ವವನ್ನು ದೃಢೀಕರಿಸುವ ಮಾನ್ಯತೆ ಪಡೆದ ಏಜೆನ್ಸಿಗಳಿಂದ ಪ್ರಮಾಣಪತ್ರದ ಪ್ರತಿ.", "iii. ಗುಣಮಟ್ಟ ಪ್ರಮಾಣಪತ್ರಕ್ಕಾಗಿ ಮರುಪಾವತಿಗಾಗಿ - NABCB / ಯಾವುದೇ ಇತರ ಮಾನ್ಯತೆ ಪಡೆದ ಏಜೆನ್ಸಿಗಳಿಂದ (ಅನ್ವಯಿಸುವಂತೆ) ಪಡೆದ ಗುಣಮಟ್ಟ ಪ್ರಮಾಣಪತ್ರದ ಸ್ವಯಂ-ದೃಢೀಕೃತ ಪ್ರತಿ", "iv. ಅರ್ಜಿದಾರರು ಬ್ಯಾಂಕ್ ಖಾತೆ ವಿವರಗಳನ್ನು (ಖಾತೆದಾರರ ಹೆಸರು, ಬ್ಯಾಂಕ್ ಹೆಸರು, ಖಾತೆ ಸಂಖ್ಯೆ, ಖಾತೆ ಪ್ರಕಾರ, IFSC ಕೋಡ್, ಶಾಖೆಯ ವಿಳಾಸ) ಒದಗಿಸುವಂತೆ ಕೋರಲಾಗಿದೆ."]', NULL, NULL, '3363');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('1ef2c0b7-3e8e-4464-800a-ce3ab8db10ce', 'DEPARTMENT-OF-ELECTR-8', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Advanced Innovation & R&D Incentive', 'General', 180, 'To promote innovation, research, and development in the IT/ITeS sector across the state, financial assistance is provided by GoK for the establishment of Advanced Innovation and R&D Setups.', '["Detailed Project Report (DPR) of the R&D project capturing the Objective, Market study, Need and Justification, Duration, Key R&D activities, Major Project Milestones with timelines under the Project, Outcome, IPRs generated.", "Technical, commercial, and financial justification for R&D activities undertaken in the R&D Project.", "Details of the Industry Partner/s with whom the Applicant has collaborated (If Any).", "Self-attested copy of the MoU/legal agreement/contract signed with the Industry Partner/s. The agreement should clearly indicate details of the funds being provided by the industry partner and the timelines for the funds disbursal for the project.", "Chartered/Cost Accountant Certificate certifying the following, along with copies of all expense and invoices incurred:", "i. Receipts and Payments Account for the amount received and utilized from Industry Partner/ s (as applicable) for R&D Project and head-wise payment of eligible project cost.", "ii. Employee expenditure statement capturing the following details for each technical employee-Employee Name, Qualification, Experience, Designation and their roles and responsibility, Salary: Monthly salary paid during the claim period along with total of each employee salary, Employee’s PF details,", "iii. Head wise detailed project expenditure other than salary.", "Self-attested copies of Bank Statement/Passbook as a proof of transfer of funds by the Industry Partner/s to the applicant for the R&D Project", "Proof of the IP associated with the R&D Project residing within the Applicant.", "Audited financial statement for the financial year during which the Applicant received the funds from the Industry Partner/s and utilized the same.", "Copies of invoices with a CA certificate confirming the expenses.", "Copy of KITS Registration Certificate", "Applicants are requested to furnish complete bank account details (Account Holder Name, Bank Name, Account Number, Account type, IFSC Code, Branch Address) to facilitate the reimbursement."]', '["The IT/ITeS should be incorporated or registered in Karnataka as Private Limited Companies, / LLP/ Partnership Firms", "The IT/ ITeS entity must have at least 50% of its total workforce (employees) based in Karnataka. This count shall exclude contract employees.", "A minimum employment threshold of 10 employees in Beyound Bengaluru region and 25 employees in Bengaluru."]', '[]', '["Company should be registered under the policy", "Company should submit the incentive application along with supporting documents as prescribed in the Policy OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/itpolicy/advanced-innovation-rd-incentive', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಸುಧಾರಿತ ನಾವೀನ್ಯತೆ ಮತ್ತು ಸಂಶೋಧನೆ ಮತ್ತು ಅಭಿವೃದ್ಧಿ ಪ್ರೋತ್ಸಾಹಧನ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ರಾಜ್ಯಾದ್ಯಂತ ಐಟಿ/ಐಟಿಇಎಸ್ (IT/ITeS) ವಲಯದಲ್ಲಿ ನಾವೀನ್ಯತೆ, ಸಂಶೋಧನೆ ಮತ್ತು ಅಭಿವೃದ್ಧಿಯನ್ನು ಉತ್ತೇಜಿಸಲು, ಸುಧಾರಿತ ನಾವೀನ್ಯತೆ ಹಾಗೂ ಸಂಶೋಧನೆ ಮತ್ತು ಅಭಿವೃದ್ಧಿ (R&D) ಘಟಕಗಳ ಸ್ಥಾಪನೆಗೆ ಕರ್ನಾಟಕ ಸರ್ಕಾರವು ಆರ್ಥಿಕ ನೆರವನ್ನು ಒದಗಿಸುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಐಟಿ/ಐಟಿಇಎಸ್"]', '["ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ-2025-30 ರಡಿಯಲ್ಲಿ ನೋಂದಣಿಯಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["I. ಸಂಶೋಧನೆ ಮತ್ತು ಅಭಿವೃದ್ಧಿ (R&D) ಯೋಜನೆಯ ವಿವರವಾದ ಯೋಜನಾ ವರದಿ (Detailed Project Report - DPR), ಇದರಲ್ಲಿ ಯೋಜನೆಯ ಉದ್ದೇಶ, ಮಾರುಕಟ್ಟೆ ಅಧ್ಯಯನ, ಅಗತ್ಯತೆ ಮತ್ತು ಸಮರ್ಥನೆ, ಯೋಜನೆಯ ಅವಧಿ, ಪ್ರಮುಖ R&D ಚಟುವಟಿಕೆಗಳು, ಯೋಜನೆಯ ಪ್ರಮುಖ ಮೈಲಿಗಲ್ಲುಗಳು ಹಾಗೂ ಅವುಗಳ ಕಾಲಮಿತಿ, ನಿರೀಕ್ಷಿತ ಫಲಿತಾಂಶಗಳು ಮತ್ತು ಯೋಜನೆಯಡಿ ಸೃಷ್ಟಿಯಾಗುವ ಬೌದ್ಧಿಕ ಸ್ವತ್ತಿನ ಹಕ್ಕುಗಳ (IPRs) ವಿವರಗಳನ್ನು ಒಳಗೊಂಡಿರಬೇಕು.", "II. R&D ಯೋಜನೆಯಡಿ ಕೈಗೊಳ್ಳಲಾದ ಚಟುವಟಿಕೆಗಳಿಗೆ ಸಂಬಂಧಿಸಿದ ತಾಂತ್ರಿಕ, ವಾಣಿಜ್ಯ ಮತ್ತು ಹಣಕಾಸಿನ ಸಮರ್ಥನಾ ವರದಿ.", "III. ಅರ್ಜಿದಾರರು ಸಹಯೋಗ ಹೊಂದಿರುವ ಕೈಗಾರಿಕಾ ಪಾಲುದಾರ(ರ) ವಿವರಗಳು (ಅನ್ವಯಿಸಿದಲ್ಲಿ).", "IV. ಕೈಗಾರಿಕಾ ಪಾಲುದಾರರೊಂದಿಗೆ ಸಹಿ ಮಾಡಲಾದ ತಿಳುವಳಿಕೆ ಒಪ್ಪಂದ (MoU)/ಕಾನೂನುಬದ್ಧ ಒಪ್ಪಂದ/ಕರಾರಿನ ಸ್ವಯಂ ದೃಢೀಕೃತ ಪ್ರತಿ. ಒಪ್ಪಂದದಲ್ಲಿ ಕೈಗಾರಿಕಾ ಪಾಲುದಾರರಿಂದ ಒದಗಿಸಲಾಗುವ ನಿಧಿಯ ವಿವರಗಳು ಹಾಗೂ ಯೋಜನೆಗೆ ನಿಧಿ ಬಿಡುಗಡೆ ಮಾಡುವ ಕಾಲಮಿತಿಯನ್ನು ಸ್ಪಷ್ಟವಾಗಿ ಉಲ್ಲೇಖಿಸಿರಬೇಕು.", "V. ಚಾರ್ಟರ್ಡ್ ಅಕೌಂಟೆಂಟ್ (CA) / ಕಾಸ್ಟ್ ಅಕೌಂಟೆಂಟ್ ಅವರ ಪ್ರಮಾಣಪತ್ರ, ಇದಕ್ಕೆ ಸಂಬಂಧಿಸಿದ ಎಲ್ಲಾ ವೆಚ್ಚಗಳ ಬಿಲ್"]', NULL, NULL, '3366');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('6a372563-d7cc-459b-a9ef-a392408f9934', 'DEPARTMENT-OF-ELECTR-10', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Setting up of IT/ ITeS Parks', 'General', 180, 'The policy aims to create vibrant, well-equipped IT/ ITeS hubs that not only catalyze collaboration and drive economic growth but also integrate green infrastructure principles such as energy-efficient buildings, renewable energy systems, sustainable water and waste management, and eco-friendly solutions.', '["i. self-declaration (on company’s letterhead) to validate occupancy of the IT/ ITeS Parks by IT/ITeS entities with details:", "Name of the IT/ITeS Entities occupying the IT/ ITeS Parks.", "Lease / Rent duration by each entity", "Area Occupancy details for each IT/ITeS Entity occupying the IT/ ITeS Parks (Total Build-up Area occupied by each entity).", "ii. Copies of rental agreement/lease deed agreements/ other business agreement / registered agreement documents with each the IT/ITeS Entity occupying the IT/ ITeS Parks.", "iii. Self-Declaration to validate total employment generated by the IT/ITeS Entity capturing the following details:", "Total No. of Employment generated.", "Breakup of the Employment generated.", "No of Male/female employees.", "No of employees", "No of Persons based out of Karnataka.", "iv. Certified letter from a Chartered Accountant mentioning all the employee’s details, PF/ESI no.", "General Documents required:", "Self-attested copy of the applicable SHLCC /SLSWCC /DLSWCC approval and the relevant Government Order for the IT/ ITeS Parks.", "Proof of procured land or executed lease deeds, lease-cum-sale agreements, sub-lease agreements, or absolute sale deeds with Karnataka Industrial Areas Development Board (KIADB), Karnataka State Small Scale Industries, KEONICS, or recognized Industrial Co-operative Societies.", "Copy of the Detailed Project Report (DPR) for the IT/ ITeS Parks.", "Total Capital Expenditure statement certified by Chartered Accountant or by KSFC/Any other Bank/Financial institution in case project financed by bank.", "Self-attested copy of letter from Financial Institution or Scheduled Bank or term loan sanction orders from KSFC/KSIIDC/Bank/Other financial institutions recognized by RBI etc.", "Self-attested Copy of approved building plan obtained from competent authority.", "Self-attested Copy of Power Service Letter/Certificate.", "Self-attested Copies of any other supporting documents for the investment made in the unit to be considered for the claim.", "Copies of statement with CA certificate (with valid UDIN) confirming the expenses.", "Copy of KITS Registration Certificate.", "Furnish complete bank account details (Account Holder Name, Bank Name, Account Number, Account type, IFSC Code, Branch Address) to facilitate the reimbursement."]', '["The IT/ITeS should be incorporated or registered in Karnataka as Private Limited Companies, / LLP/ Partnership Firms.", "The incentive shall be applicable to applicants who have procured land or executed lease deeds, lease-cum-sale agreements, sub-lease agreements, or absolute sale deeds with Karnataka Industrial Areas Development Board (KIADB), Karnataka State Small Scale Industries, KEONICS, or recognized Industrial Co-operative Societies"]', '[]', '["Company should be registered under the policy", "Company should submit the incentive application along with supporting documents as prescribed in the Policy OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/itpolicy/it-ites-parks', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಐಟಿ/ಐಟಿಇಎಸ್ ಪಾರ್ಕ್', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಈ ನೀತಿಯು ಚೈತನ್ಯಶೀಲ ಮತ್ತು ಸುಸಜ್ಜಿತ ಐಟಿ/ಐಟಿಇಎಸ್ (IT/ITeS) ಕೇಂದ್ರಗಳನ್ನು ಸೃಷ್ಟಿಸುವ ಗುರಿಯನ್ನು ಹೊಂದಿದೆ. ಇವು ಸಹಯೋಗವನ್ನು ಉತ್ತೇಜಿಸುವುದರೊಂದಿಗೆ ಆರ್ಥಿಕ ಬೆಳವಣಿಗೆಗೆ ಚಾಲನೆ ನೀಡುವುದಲ್ಲದೆ, ಇಂಧನ-ದಕ್ಷ ಕಟ್ಟಡಗಳು, ನವೀಕರಿಸಬಹುದಾದ ಇಂಧನ ವ್ಯವಸ್ಥೆಗಳು, ಸುಸ್ಥಿರ ನೀರು ಹಾಗೂ ತ್ಯಾಜ್ಯ ನಿರ್ವಹಣೆ ಮತ್ತು ಪರಿಸರ ಸ್ನೇಹಿ ಪರಿಹಾರಗಳಂತಹ ಹಸಿರು ಮೂಲಸೌಕರ್ಯ ತತ್ವಗಳನ್ನು ಸಹ ಅಳವಡಿಸಿಕೊಳ್ಳುತ್ತವೆ.', NULL, NULL, NULL, NULL, NULL, '["ಐಟಿ/ಐಟಿಇಎಸ್"]', '["ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ-2025-30 ರಡಿಯಲ್ಲಿ ನೋಂದಣಿಯಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["i. ಐಟಿ/ಐಟಿಇಎಸ್ ಪಾರ್ಕ್"]', NULL, NULL, '3375');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('595be96d-08ac-459e-afde-c078543b7879', 'DEPARTMENT-OF-ELECTR-11', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Skilling cost reimbursement', 'General', 60, 'To fulfil the growing need for skilled IT manpower and encouraging development, financial assistance shall be provided by GoK to upskill and expand knowledge of working professionals in emerging technologies.', '["i. Detailed proposal of the trainings and its duration that the employees have undergone (comprising of Deep Tech / Emerging Tech / Technical Subjects (domains, duration, target groups).", "ii. Detailed Budget.", "iii. Infrastructure and Delivery Model.", "iv. Monitoring and Outcome Evaluation Plan. (Assessment and certifications)", "v. Copy of Letters of Support from Partner Institutions", "vi. HR Certificate on a company letterhead confirming that the new recruits being trained are based in Karnataka", "vii. Trainer profiles or training partner agreements with credentials.", "viii. Post-training assessment reports & Certificates issued.", "ix. Attendance records (with details like name, email, mobile number, designation, employee number etc.,) and data showing number of employees trained.", "x. Copies of invoices with a CA certificate confirming the expenses.", "xi. Applicants are requested to furnish complete bank account details (Account Holder Name, Bank Name, Account Number, Account type, IFSC Code, Branch Address) to facilitate the reimbursement."]', '["The IT/ITeS should be incorporated or registered in Karnataka as Private Limited Companies, / LLP/ Partnership Firms", "The IT/ ITeS entity must have at least 50% of its total workforce (employees) based in Karnataka. This count shall exclude contract employees.", "A minimum employment threshold of 10 employees in Beyound Bengaluru region and 25 employees in Bengaluru.", "The applicant shall have established a new IT/ITeS Unit in Beyond Bengaluru during the policy period.", "The company must provide formal training or skill development programs to the recruited talent within 01 year of hiring. The training should aim to upgrade the employees’ skills to meet industry standards.", "The New recruits participating in the skilling program must be based in Karnataka."]', '[]', '["Company should be registered under the policy", "Company should submit the incentive application along with supporting documents as prescribed in the Policy OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/itpolicy/skilling-cost-reimbursement', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಕೌಶಲ್ಯ ವೆಚ್ಚ ಮರುಪಾವತಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'technologies.
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('ef2c08f0-46af-4270-a44d-fd5e8877d864', 'DEPARTMENT-OF-ELECTR-12', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Support for Faculty Development Programme', 'General', 60, 'To encourage faculty participation in advanced training, the following financial incentive is offered under the policy.', '["i. Detailed Training programme proposal, Detailed curriculum and schedule", "ii. Cohort participant details", "iii. Detailed Budget and Cost Breakup.", "iv. Proof of training completion (attendance logs, assessments, photographs, etc.) Final cohort report with participant completion details", "v. Copy of Letters of Support from Partner Institutions.", "vi. Trainer profiles or training partner agreements with credentials.", "vii. Post-training assessment reports & Certificates signed by the Head of Institution", "viii. Attendance records (with details like name, email, mobile number, designation, employee number etc.,) and data showing number of employees trained.", "ix. Copies of invoices with a CA certificate confirming the expenses.", "x. Declaration on a letterhead stating that these costs are not already funded by any other State/Central Government scheme", "xi. Supportingdocuments establishing affiliation status", "xii. Applicants are requested to furnish complete bank account details (Account Holder Name, Bank Name, Account Number, Account type, IFSC Code, Branch Address) to facilitate the reimbursement."]', '["The applicant shall be a State Government affiliated University or College located in Karnataka.", "The Faculty Development Programme (FDP) shall be conducted during the policy period and shall focus on Deep Tech and/or Emerging Technologies, with a minimum duration of 40 hours and a cohort size of at least 30 participants."]', '[]', '["Company should be registered under the policy", "Company should submit the incentive application along with supporting documents as prescribed in the Policy OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/itpolicy/faculty-development-programme', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಬೋಧಕ ಅಭಿವೃದ್ಧಿ ಕಾರ್ಯಕ್ರಮಕ್ಕೆ ಬೆಂಬಲ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಉನ್ನತ ಮಟ್ಟದ ತರಬೇತಿ ಕಾರ್ಯಕ್ರಮಗಳಲ್ಲಿ ಬೋಧಕವರ್ಗದವರ ಭಾಗವಹಿಸುವಿಕೆಯನ್ನು ಉತ್ತೇಜಿಸಲು, ಈ ನೀತಿಯಡಿ ಕೆಳಕಂಡ ಆರ್ಥಿಕ ಪ್ರೋತ್ಸಾಹಧನವನ್ನು ಒದಗಿಸಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಅರ್ಜಿದಾರರು ಕರ್ನಾಟಕದಲ್ಲಿರುವ ರಾಜ್ಯ ಸರ್ಕಾರಿ ಸಂಯೋಜಿತ ವಿಶ್ವವಿದ್ಯಾಲಯ ಅಥವಾ ಕಾಲೇಜಾಗಿರಬೇಕು.", "ಫ್ಯಾಕಲ್ಟಿ ಡೆವಲಪ್"]', '["ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ-2025-30 ರಡಿಯಲ್ಲಿ ನೋಂದಣಿಯಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["i. ವಿವರವಾದ ತರಬೇತಿ ಕಾರ್ಯಕ್ರಮದ ಪ್ರಸ್ತಾವನೆ, ವಿವರವಾದ ಪಠ್ಯಕ್ರಮ ಮತ್ತು ವೇಳಾಪಟ್ಟಿ", "ii. ಸಾಮೂಹಿಕ ಭಾಗವಹಿಸುವವರ ವಿವರಗಳು", "iii. ವಿವರವಾದ ಬಜೆಟ್ ಮತ್ತು ವೆಚ್ಚದ ವಿವರ.", "iv. ತರಬೇತಿ ಪೂರ್ಣಗೊಂಡ ಪುರಾವೆ (ಹಾಜರಾತಿ ದಾಖಲೆಗಳು, ಮೌಲ್ಯಮಾಪನಗಳು, ಛಾಯಾಚಿತ್ರಗಳು, ಇತ್ಯಾದಿ) ಭಾಗವಹಿಸುವವರ ಪೂರ್ಣಗೊಂಡ ವಿವರಗಳೊಂದಿಗೆ ಅಂತಿಮ ಸಮೂಹ ವರದಿ", "v. ಪಾಲುದಾರ ಸಂಸ್ಥೆಗಳಿಂದ ಬೆಂಬಲ ಪತ್ರಗಳ ಪ್ರತಿ.", "vi. ತರಬೇತುದಾರರ ಪ್ರೊಫೈಲ್"]', NULL, NULL, '3328');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('9794110e-80e3-4763-960d-2057acbbaa15', 'DEPARTMENT-OF-ELECTR-14', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Talent relocation reimbursement', 'General', 60, 'To support the decentralization of talent and foster regional development, relocation expenses shall be reimbursed by the GoK to encourage employment in Beyond Bengaluru regions.', '["i. Details of relocated employees (name, employee ID, designation, joining date)", "ii. CA-certified letter on expenditure incurred towards Relocation, comprising a break-up of the total Cost (as applicable).", "iii. Proof of employment, offer letters, or transfer orders", "iv. Date of relocation and joining confirmation at the new location", "v. Documentary evidence showing the previous work location", "vi. Supporting documents such as relocation letter by employer to employee as a part of joining perquisite with complete details (pre-relocation assistance, self and family travel, accommodation, shipment assistance etc., is clearly mentioned)", "vii. Copy of original invoices, bills for the expenses incurred (as applicable).", "viii. HR signed copy of proof for a continuous employment of at least 1-year post-relocation of the employees for which claim is submitted.", "ix. Applicants are requested to furnish complete bank account details (Account Holder Name, Bank Name, Account Number, Account type, IFSC Code, Branch Address) to facilitate the reimbursement."]', '["The IT/ITeS should be incorporated or registered in Karnataka as Private Limited Companies, / LLP/ Partnership Firms", "The IT/ ITeS entity must have at least 50% of its total workforce (employees) based in Karnataka. This count shall exclude contract employees.", "A minimum employment threshold of 10 employees in Beyound Bengaluru region and 25 employees in Bengaluru.", "The IT/ITeS Unit shall be located in Beyond Bengaluru.", "The relocated employees shall be full-time employees on the applicant''s payroll and shall have completed at least one year of continuous service after relocation.", "The relocated employees shall be full-time employees on the applicant''s payroll and shall have completed at least one year of continuous service after relocation."]', '[]', '["Company should be registered under the policy", "Company should submit the incentive application along with supporting documents as prescribed in the Policy OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/itpolicy/talent-relocation-reimbursement', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಪ್ರತಿಭಾ ಸ್ಥಳಾಂತರ ಮರುಪಾವತಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಪ್ರತಿಭಾವಂತ ಮಾನವ ಸಂಪನ್ಮೂಲದ ವಿಕೇಂದ್ರೀಕರಣವನ್ನು ಬೆಂಬಲಿಸಲು ಹಾಗೂ ಪ್ರಾದೇಶಿಕ ಅಭಿವೃದ್ಧಿಯನ್ನು ಉತ್ತೇಜಿಸಲು, ಬೆಂಗಳೂರಿನಾಚೆಗಿನ (Beyond Bengaluru) ಪ್ರದೇಶಗಳಲ್ಲಿ ಉದ್ಯೋಗಾವಕಾಶಗಳನ್ನು ಪ್ರೋತ್ಸಾಹಿಸುವ ಉದ್ದೇಶದಿಂದ ಸ್ಥಳಾಂತರಕ್ಕೆ ತಗಲುವ ವೆಚ್ಚಗಳನ್ನು ಕರ್ನಾಟಕ ಸರ್ಕಾರದಿಂದ (GoK) ಮರುಪಾವತಿಸಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಐಟಿ/ಐಟಿಇಎಸ್"]', '["ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ-2025-30 ರಡಿಯಲ್ಲಿ ನೋಂದಣಿಯಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["i. ಸ್ಥಳಾಂತರಗೊಂಡ ನೌಕರರ ವಿವರಗಳು (ಹೆಸರು, ಉದ್ಯೋಗಿ ಐಡಿ, ಹುದ್ದೆ, ಸೇರ್ಪಡೆ ದಿನಾಂಕ)", "ii. ಸ್ಥಳಾಂತರಕ್ಕಾಗಿ ಮಾಡಿದ ವೆಚ್ಚದ ಕುರಿತು CA-ಪ್ರಮಾಣೀಕೃತ ಪತ್ರ, ಒಟ್ಟು ವೆಚ್ಚದ ವಿವರ (ಅನ್ವಯಿಸಿದಂತೆ) ಒಳಗೊಂಡಿದೆ.", "iii. ಉದ್ಯೋಗದ ಪುರಾವೆ, ಆಫರ್ ಲೆಟರ್"]', NULL, NULL, '3340');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('0cc664d6-4cf8-4a9a-b829-e4ebf9f547e9', 'DEPARTMENT-OF-ELECTR-15', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Reimbursement of Hosting Events and Conferences', 'General', 60, 'Reimbursement of Hosting Events and Conferences', '["i. Detailed concept note of the event with the theme, agenda, Budget and expected outcome", "ii. Complete registration details (name, designation, company, email and phone numbers of the participants including speakers)", "iii. Proof of payment incurred towards organizing the event, along with event brochures, participation reports, complete registration details (name, designation, company, email and phone numbers of the participants/ speakers who have participated in the event media coverage etc.,", "iv. Post Event Report (impact, outcomes, event photographs)", "v. A letter or statement issued by a Chartered Accountant (CA) certifying the expenses incurred by the applicant, along with a certificate and copy of invoices/ proof of payments, clearly stating the amount received through income generated from sponsorships, registrations, participation fees, and other sources.", "vi. Furnish complete bank account details (Account Holder Name, Bank Name, Account Number, Account type, IFSC Code, Branch Address) to facilitate the reimbursement."]', '["The IT/ITeS should be incorporated or registered in Karnataka as Private Limited Companies, / LLP/ Partnership Firms", "The IT/ ITeS entity must have at least 50% of its total workforce (employees) based in Karnataka. This count shall exclude contract employees.", "A minimum employment threshold of 10 employees in Beyound Bengaluru region and 25 employees in Bengaluru.", "The applicant shall have established a new/ Expansion IT/ITeS Unit in Beyond Bengaluru during the policy period.", "The Applicant shall have completed at least 1 years of commercial operations"]', '[]', '["Company should be registered under the policy", "Company should submit the incentive application along with supporting documents as prescribed in the Policy OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/itpolicy/events-and-conferences', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಕಾರ್ಯಕ್ರಮಗಳು ಮತ್ತು ಸಮ್ಮೇಳನಗಳು ವೆಚ್ಚದಲ್ಲಿ ಮರುಪಾವತಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಕಾರ್ಯಕ್ರಮಗಳು ಮತ್ತು ಸಮ್ಮೇಳನಗಳ ಆಯೋಜನೆಗೆ ತಗಲುವ ವೆಚ್ಚಗಳ ಮರುಪಾವತಿ', NULL, NULL, NULL, NULL, NULL, '["ಐಟಿ/ಐಟಿಇಎಸ್"]', '["ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ-2025-30 ರಡಿಯಲ್ಲಿ ನೋಂದಣಿಯಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["i. ಥೀಮ್, ಕಾರ್ಯಸೂಚಿ, ಬಜೆಟ್ ಮತ್ತು ನಿರೀಕ್ಷಿತ ಫಲಿತಾಂಶದೊಂದಿಗೆ ಕಾರ್ಯಕ್ರಮದ ವಿವರವಾದ ಪರಿಕಲ್ಪನಾ ಟಿಪ್ಪಣಿ", "ii. ಸಂಪೂರ್ಣ ನೋಂದಣಿ ವಿವರಗಳು (ಹೆಸರು, ಹುದ್ದೆ, ಕಂಪನಿ, ಇಮೇಲ್ ಮತ್ತು ಭಾಷಣಕಾರರು ಸೇರಿದಂತೆ ಭಾಗವಹಿಸುವವರ ಫೋನ್ ಸಂಖ್ಯೆಗಳು)", "iii. ಕಾರ್ಯಕ್ರಮದ ಕರಪತ್ರಗಳು, ಭಾಗವಹಿಸುವಿಕೆ ವರದಿಗಳು, ಸಂಪೂರ್ಣ ನೋಂದಣಿ ವಿವರಗಳು (ಹೆಸರು, ಹುದ್ದೆ, ಕಂಪನಿ, ಇಮೇಲ್ ಮತ್ತು ಕಾರ್ಯಕ್ರಮದ ಮಾಧ್ಯಮ ವರದಿಯಲ್ಲಿ ಭಾಗವಹಿಸಿದ ಭಾಗವಹಿಸುವವರು/ ಭಾಷಣಕಾರರ ಫೋನ್ ಸಂಖ್ಯೆಗಳು ಇತ್ಯಾದಿ) ಜೊತೆಗೆ ಕಾರ್ಯಕ್ರಮವನ್ನು ಆಯೋಜಿಸಲು ಮಾಡಿದ ಪಾವತಿಯ ಪುರಾವೆ,", "iv. ಕಾರ್ಯಕ್ರಮದ ನಂತರದ ವರದಿ (ಪರಿಣಾಮ, ಫಲಿತಾಂಶಗಳು, ಕಾರ್ಯಕ್ರಮದ ಛಾಯಾಚಿತ್ರಗಳು)", "v. ಅರ್ಜಿದಾರರು ಮಾಡಿದ ವೆಚ್ಚಗಳನ್ನು ಪ್ರಮಾಣೀಕರಿಸುವ ಚಾರ್ಟರ್ಡ್ ಅಕೌಂಟೆಂಟ್ (CA) ನೀಡಿದ ಪತ್ರ ಅಥವಾ ಹೇಳಿಕೆ, ಪ್ರಮಾಣಪತ್ರ ಮತ್ತು ಇನ್"]', NULL, NULL, '3360');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('b84e5a4c-0b6c-4de6-9de4-b0950dc420af', 'DEPARTMENT-OF-ELECTR-16', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Rental Assistance', 'General', 60, 'To encourage IT/ITeS investments, GoK shall offer rental support aimed at lowering operational overheads for eligible companies.', '["I. Copy of the Registration Certificate issued by KITS.", "II. Self-attested bank account statement for proof of payment towards lease/rental payments", "III. Copy of the lease deed/rental agreement / business agreement / any other registered agreement with details of total space leased/rented. The lease deed/rental agreement / any registered agreement should be valid for the time period the lease/rental reimbursement is being claimed by the applicant.", "IV. Self-attested copies of Invoices/receipts of payment made towards the lease/rental for the time period the reimbursement is being claimed by the applicant.", "V. Self-attested declaration on the official letterhead stating that rent cost has not been cross charged/ recovered from any other entity which is not undertaking IT/ITeS activities.", "VI. Furnish complete bank account details (Account Holder Name, Bank Name, Account Number, Account type, IFSC Code, Branch Address)."]', '["The IT/ITeS should be incorporated or registered in Karnataka as Private Limited Companies, / LLP/ Partnership Firms", "The IT/ ITeS entity must have at least 50% of its total workforce (employees) based in Karnataka. This count shall exclude contract employees.", "A minimum employment threshold of 10 employees in Beyound Bengaluru region and 25 employees in Bengaluru.", "The applicant shall have established a new IT/ITeS Unit in Beyond Bengaluru during the policy period.", "Minimum space requirement: For eligibility under this policy incentive, the IT/ITeS entity must occupy at least 1,200 sq. ft. of space in Beyond Bengaluru locations and 3,000 sq. ft. in Bengaluru, inclusive of common areas."]', '[]', '["Company should be registered under the policy", "Company should submit the incentive application along with supporting documents as prescribed in the Policy OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/itpolicy/rental-assistance-it-policy', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಬಾಡಿಗೆ ನೆರವು', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಐಟಿ/ಐಟಿಇಎಸ್ ಹೂಡಿಕೆಗಳನ್ನು ಉತ್ತೇಜಿಸುವ ಉದ್ದೇಶದಿಂದ, ಅರ್ಹ ಕಂಪನಿಗಳ ಕಾರ್ಯಾಚರಣಾ ವೆಚ್ಚದ ಹೊರೆಯನ್ನು ಕಡಿಮೆ ಮಾಡಲು ಕರ್ನಾಟಕ ಸರ್ಕಾರದಿಂದ ಬಾಡಿಗೆ ವೆಚ್ಚದ ಮರುಪಾವತಿ ರೂಪದಲ್ಲಿ ಆರ್ಥಿಕ ನೆರವು ಒದಗಿಸಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಐಟಿ/ಐಟಿಇಎಸ್"]', '["ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ-2025-30 ರಡಿಯಲ್ಲಿ ನೋಂದಣಿಯಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["i. KITS ನಿಂದ ನೀಡಲಾದ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರದ ಪ್ರತಿ.", "ii. ಗುತ್ತಿಗೆ/ಬಾಡಿಗೆ ಪಾವತಿಗಳಿಗೆ ಪಾವತಿಯ ಪುರಾವೆಗಾಗಿ ಸ್ವಯಂ-ದೃಢೀಕರಿಸಿದ ಬ್ಯಾಂಕ್ ಖಾತೆ ಹೇಳಿಕೆ", "iii. ಗುತ್ತಿಗೆ ಪತ್ರ/ಬಾಡಿಗೆ ಒಪ್ಪಂದ/ವ್ಯವಹಾರ ಒಪ್ಪಂದ/ಒಟ್ಟು ಗುತ್ತಿಗೆ/ಬಾಡಿಗೆ ಸ್ಥಳದ ವಿವರಗಳೊಂದಿಗೆ ಯಾವುದೇ ಇತರ ನೋಂದಾಯಿತ ಒಪ್ಪಂದದ ಪ್ರತಿ. ಗುತ್ತಿಗೆ ಪತ್ರ/ಬಾಡಿಗೆ ಒಪ್ಪಂದ/ಯಾವುದೇ ನೋಂದಾಯಿತ ಒಪ್ಪಂದವು ಅರ್ಜಿದಾರರು ಗುತ್ತಿಗೆ/ಬಾಡಿಗೆ ಮರುಪಾವತಿಯನ್ನು ಕ್ಲೈಮ್ ಮಾಡುತ್ತಿರುವ ಅವಧಿಗೆ ಮಾನ್ಯವಾಗಿರಬೇಕು.", "iv. ಅರ್ಜಿದಾರರು ಮರುಪಾವತಿಯನ್ನು ಕ್ಲೈಮ್ ಮಾಡುತ್ತಿರುವ ಅವಧಿಗೆ ಗುತ್ತಿಗೆ/ಬಾಡಿಗೆಗೆ ಮಾಡಿದ ಪಾವತಿಯ ಇನ್"]', NULL, NULL, '3364');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('73d3182c-2c57-4d6b-80fe-f10688381022', 'DEPARTMENT-OF-ELECTR-18', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'GCC Registration', 'General', 30, 'In order to facilitate the submission and processing of incentive claims, concessions and subsidies provided under the policy, all applicants are required to register with the KITS.', '["Undertaking to be submitted by the Applicant in the prescribed format.", "Existing GCC Entities", "i.Audited financial statements for the last 01 year of operations.", "ii. Annual reports for the last 01 year.", "New GCC Entities", "i. Self – attested brief project reports on the business that includes financial projections for the next three years.", "Copy of Certificate of Incorporation and Supporting Documents", "i. If the Applicant is a Public/Private Company (under The Indian Companies Act, 1956/2013 and subsequent amendments):", "▪Copy of Certificate of Incorporation", "▪Copy of Memorandum of Association and Articles of Association", "ii. If the Applicant is a Partnership Firm or a Limited Liability Partnership (registered Partnership Firm under The Indian Partnership Act 1932 or Limited Liability Partnership Act 2008):", "▪Copy of Registration Certificate", "▪Copy of Partnership Deed", "Self-attested Copy of Rental Agreement/Lease deed agreement/Khata.", "Passport sized photograph of the authorized signatory of the applicant.", "Self-attested copy of GST Registration Certificate.", "Self-attested copy of PAN Card.", "Self-attested copies of the Detailed Project report and first sale invoice of services provided to support the nature of GCC activities undertaken.", "Chartered Accountant (CA) Certificate (With membership no.) showing shareholding pattern (indicating number of shares and investment).", "Shops and Establishment Certificate under The Karnataka Shops and Commercial Establishments Act 1961 And Rules 1963.", "Incorporation Certificate of the Parent Company."]', '["An entity incorporated under the Companies Act 2013 / a Partnership Firm registered under the Partnership Act 1932 / a Limited Liability Partnership under the Limited Liability Partnership Act 2008.", "The entity shall be a fully owned and integrated hub established by a multinational corporation headquartered outside India to leverage global talent, build intellectual property and enhance operational efficiency.", "The GCC shall be located or being set up in Karnataka.", "The GCC shall be engaged in servicing its parent organisation and/or group affiliates.", "A GCC unit located in Karnataka that was already operational before the effective date of the Policy, i.e., 03.12.2024.", "A GCC unit located in Karnataka that was already operational after the effective date of the Policy, i.e., 03.12.2024.", "The GCC should have an operational establishment in Karnataka and undertake its eligible GCC activities from the State."]', '[]', '[]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/gcc/gcc-register', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಜಾಗತಿಕ ಸಾಮರ್ಥ್ಯ ಕೇಂದ್ರದ ನೋಂದಣಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಅರ್ಜಿಗಳ ಸಲ್ಲಿಕೆ ಮತ್ತು ನೀತಿಯಡಿಯಲ್ಲಿ ನೀಡಲಾಗುವ ಪ್ರೋತ್ಸಾಹಕಗಳು, ವಿನಾಯಿತಿಗಳು ಹಾಗೂ ಸಬ್ಸಿಡಿಗಳ ವಿಲೇವಾರಿಯನ್ನು ಸುಲಭಗೊಳಿಸಲು, ಎಲ್ಲಾ ಅರ್ಜಿದಾರರು ಕೆಐಟಿಎಸ್ (KITS) ನೊಂದಿಗೆ ನೋಂದಾಯಿಸಿಕೊಳ್ಳುವುದು ಕಡ್ಡಾಯವಾಗಿದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಘಟಕವು ಕಂಪನಿಗಳ ಕಾಯ್ದೆ, 2013 ರಡಿ ನೋಂದಾಯಿತ ಕಂಪನಿ / ಪಾಲುದಾರಿಕೆ ಕಾಯ್ದೆ, 1932 ರಡಿ ನೋಂದಾಯಿತ ಪಾಲುದಾರಿಕೆ ಸಂಸ್ಥೆ / ಸೀಮಿತ ಹೊಣೆಗಾರಿಕೆ ಪಾಲುದಾರಿಕೆ ಕಾಯ್ದೆ, 2008 ರಡಿ ನೋಂದಾಯಿತ LLP ಆಗಿರಬೇಕು.", "ಘಟಕವು ಭಾರತದ ಹೊರಗೆ ಪ್ರಧಾನ ಕಚೇರಿ ಹೊಂದಿರುವ ಬಹುರಾಷ್ಟ್ರೀಯ ಸಂಸ್ಥೆಯಿಂದ ಸ್ಥಾಪಿಸಲಾದ, ಸಂಪೂರ್ಣ ಮಾಲೀಕತ್ವ ಹೊಂದಿರುವ ಮತ್ತು ಸಮಗ್ರ ಘಟಕವಾಗಿದ್ದು, ಜಾಗತಿಕ ಪ್ರತಿಭೆಯನ್ನು ಬಳಸಿಕೊಳ್ಳುವುದು, ಬೌದ್ಧಿಕ ಆಸ್ತಿ ಅಭಿವೃದ್ಧಿಪಡಿಸುವುದು ಹಾಗೂ ಕಾರ್ಯಾಚರಣೆಯ ದಕ್ಷತೆಯನ್ನು ಹೆಚ್ಚಿಸುವ ಉದ್ದೇಶ ಹೊಂದಿರಬೇಕು.", "GCC ಕರ್ನಾಟಕದಲ್ಲಿ ಸ್ಥಾಪಿತವಾಗಿರಬೇಕು ಅಥವಾ ಸ್ಥಾಪನೆಯ ಹಂತದಲ್ಲಿರಬೇಕು.", "GCC ತನ್ನ ಮೂಲ ಸಂಸ್ಥೆ (Parent Organisation) ಮತ್ತು/ಅಥವಾ ಸಮೂಹದ ಅಂಗಸಂಸ್ಥೆಗಳಿಗೆ (Group Affiliates) ಸೇವೆಗಳನ್ನು ಒದಗಿಸುತ್ತಿರಬೇಕು.", "03.12.2024 ರಂದು ಅಥವಾ ಅದಕ್ಕೂ ಮೊದಲು ಕರ್ನಾಟಕದಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿದ್ದ GCC ಘಟಕಗಳು ನೋಂದಣಿಗೆ ಅರ್ಹವಾಗಿರುತ್ತವೆ.", "03.12.2024ರ ನಂತರ ಕರ್ನಾಟಕದಲ್ಲಿ ವಾಣಿಜ್ಯ ಕಾರ್ಯಾಚರಣೆಗಳನ್ನು ಪ್ರಾರಂಭಿಸಿರುವ ಅಥವಾ ಪ್ರಾರಂಭಿಸಲಿರುವ GCC ಘಟಕಗಳು ನೋಂದಣಿಗೆ ಅರ್ಹವಾಗಿರುತ್ತವೆ.", "GCCಯು ಕರ್ನಾಟಕದಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಣಾ ಘಟಕವನ್ನು ಹೊಂದಿದ್ದು, ತನ್ನ ಅರ್ಹ GCC ಚಟುವಟಿಕೆಗಳನ್ನು ಕರ್ನಾಟಕದಿಂದಲೇ ನಿರ್ವಹಿಸುತ್ತಿರಬೇಕು."]', '["ಅರ್ಜಿದಾರ ಕಂಪನಿಯು GCC Policy 2024–29ರಡಿ, OPGಯಲ್ಲಿ ನಿಗದಿಪಡಿಸಿರುವಂತೆ, ನೋಂದಣಿ ನಮೂನೆಯೊಂದಿಗೆ ಅಗತ್ಯವಿರುವ ಪೂರಕ ದಾಖಲೆಗಳನ್ನು KITSಗೆ ಸಲ್ಲಿಸಬೇಕು."]', 1, '["ಅರ್ಜಿದಾರರು ಸಲ್ಲಿಸಬೇಕಾದ ದಾಖಲೆ:", "ನಿಗದಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿದಾರರು ಸಲ್ಲಿಸಬೇಕಾದ ಅಂಡರ್"]', NULL, NULL, '3370');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('3796febc-f2fa-4169-91bf-207cf0742f22', 'DEPARTMENT-OF-ELECTR-19', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Rental Assistance Incentive', 'General', 60, 'GoK offers incentives to help businesses access land and office space, facilitating quicker setup. Entities establishing a new GCC unit in the Beyond Bengaluru District area and leasing or renting space for operations will be eligible for reimbursements based on one of the following rent/lease reimbursements', '["i. Copy of the Registration Certificate issued by KITS.", "ii. Self-attested bank account statement for proof of payment towards lease/rental payments", "iii. Copy of the lease deed/rental agreement with details of total space leased/rented. The lease deed/rental agreement should be valid for the time period the lease/rental reimbursement is being claimed by the applicant.", "iv. Self-attested copies of Invoices/receipts of payment made towards the lease/rental for the time period the reimbursement is being claimed by the applicant.", "v. Self-attested declaration on the official letterhead stating that rent cost has not been cross charged/ recovered from any other entity which is not undertaking GCC activities."]', '["Applicable to New GCCs setting up with 100+ Employees", "The company should be based in Beyond Bengaluru District.", "Lease/Rental Reimbursement shall be applicable for spaces taken on lease or rent only during the policy period.", "Rental assistance shall be available for spaces taken on lease or rent for a continuous period of 12 months from the date of commencement of commercial operations.", "The Applicant shall avail the incentive only once under the Policy.", "Reimbursement shall be made on the actuals, up to the maximum limit defined for the lease/rental reimbursement (excluding maintenance costs, electricity charges, etc. and security deposit, if any)."]', '[]', '["The applicant Company should be registered with KITS under GCC Policy 2024-29", "Company should submit the incentive application along with supporting documents as prescribed in the OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/gcc/rental-assistance', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಬಾಡಿಗೆ ಸಹಾಯಧನ ಪ್ರೋತ್ಸಾಹಧನ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಸರ್ಕಾರವು ಉದ್ಯಮಗಳಿಗೆ ಜಮೀನು ಮತ್ತು ಕಚೇರಿ ಸ್ಥಳವನ್ನು ಪಡೆಯಲು ನೆರವಾಗಲು ಪ್ರೋತ್ಸಾಹಕಗಳನ್ನು ನೀಡುತ್ತದೆ, ಇದರಿಂದ ಶೀಘ್ರ ಸ್ಥಾಪನೆಗೆ ಅನುಕೂಲವಾಗುತ್ತದೆ. "ಬಿಯಾಂಡ್ ಬೆಂಗಳೂರು" (ಬೆಂಗಳೂರು ಹೊರತಾದ) ಜಿಲ್ಲಾ ಪ್ರದೇಶಗಳಲ್ಲಿ ಹೊಸ ಜಿಸಿಒ (GCC) ಘಟಕವನ್ನು ಸ್ಥಾಪಿಸುವ ಮತ್ತು ಕಾರ್ಯಾಚರಣೆಗಾಗಿ ಜಾಗವನ್ನು ಗುತ್ತಿಗೆ (Lease) ಅಥವಾ ಬಾಡಿಗೆಗೆ ಪಡೆಯುವ ಸಂಸ್ಥೆಗಳು ಕೆಳಗಿನ ಬಾಡಿಗೆ/ಗುತ್ತಿಗೆ ಮರುಪಾವತಿಯ ಆಧಾರದ ಮೇಲೆ ಅರ್ಹತೆ ಪಡೆಯುತ್ತವೆ.', NULL, NULL, NULL, NULL, NULL, '["100 ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ಉದ್ಯೋಗಿಗಳನ್ನು ಹೊಂದಿರುವ ಹೊಸದಾಗಿ ಸ್ಥಾಪಿಸಲಾದ ಜಾಗತಿಕ ಸಾಮರ್ಥ್ಯ ಕೇಂದ್ರಗಳಿಗೆ (GCCs) ಅನ್ವಯಿಸುತ್ತದೆ.", "ಸಂಸ್ಥೆಯು ಬೆಂಗಳೂರು ಹೊರವಲಯ ಜಿಲ್ಲೆಯಲ್ಲಿರಬೇಕು.", "ಗುತ್ತಿಗೆ (Lease) ಅಥವಾ ಬಾಡಿಗೆಯ (Rent) ಆಧಾರದ ಮೇಲೆ ಪಡೆದಿರುವ ಸ್ಥಳಗಳಿಗೆ ಮಾತ್ರ, ಮತ್ತು ಅದು ನೀತಿಯ ಅವಧಿಯಲ್ಲಿ ಪಡೆದಿದ್ದಲ್ಲಿ ಮಾತ್ರ, ಗುತ್ತಿಗೆ/ಬಾಡಿಗೆ ಮರುಪಾವತಿಗೆ ಅರ್ಹತೆ ಇರುತ್ತದೆ.", "ವಾಣಿಜ್ಯ ಕಾರ್ಯಾಚರಣೆ ಆರಂಭಗೊಂಡ ದಿನಾಂಕದಿಂದ ಸತತ ಹನ್ನೆರಡು (12) ತಿಂಗಳ ಅವಧಿಗೆ ಗುತ್ತಿಗೆ ಅಥವಾ ಬಾಡಿಗೆಯ ಆಧಾರದ ಮೇಲೆ ಪಡೆದಿರುವ ಸ್ಥಳಗಳಿಗೆ ಬಾಡಿಗೆ ಸಹಾಯಧನ ಲಭ್ಯವಾಗುತ್ತದೆ.", "ಅರ್ಜಿದಾರರು ಈ ನೀತಿಯಡಿ ಬಾಡಿಗೆ ಸಹಾಯಧನ ಪ್ರೋತ್ಸಾಹಧನವನ್ನು ಕೇವಲ ಒಂದು ಬಾರಿ ಮಾತ್ರ ಪಡೆಯಲು ಅರ್ಹರಾಗಿರುತ್ತಾರೆ.", "ಮರುಪಾವತಿಯನ್ನು ವಾಸ್ತವಿಕ ವೆಚ್ಚದ (Actuals) ಆಧಾರದ ಮೇಲೆ, ಗುತ್ತಿಗೆ/ಬಾಡಿಗೆ ಮರುಪಾವತಿಗಾಗಿ ನಿಗದಿಪಡಿಸಲಾದ ಗರಿಷ್ಠ ಮಿತಿಯೊಳಗೆ ಮಾತ್ರ ನೀಡಲಾಗುತ್ತದೆ. ನಿರ್ವಹಣಾ ವೆಚ್ಚಗಳು (Maintenance Charges), ವಿದ್ಯುತ್ ಶುಲ್ಕ, ಭದ್ರತಾ ಠೇವಣಿ (Security Deposit) ಹಾಗೂ ಇತರೆ ಸಂಬಂಧಿತ ವೆಚ್ಚಗಳನ್ನು ಮರುಪಾವತಿಗೆ ಪರಿಗಣಿಸಲಾಗುವುದಿಲ್ಲ."]', '["ಅರ್ಜಿದಾರ ಕಂಪನಿಯು GCC ನೀತಿಯಡಿ ಕರ್ನಾಟಕ ನವೋದ್ಯಮ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ಯಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["ಕರ್ನಾಟಕ ನಾವೀನ್ಯತೆ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ವತಿಯಿಂದ ನೀಡಲಾದ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರದ ಪ್ರತಿ.", "ಗುತ್ತಿಗೆ/ಬಾಡಿಗೆ ಪಾವತಿಯನ್ನು ಮಾಡಿರುವುದಕ್ಕೆ ಪುರಾವೆಯಾಗಿ ಬ್ಯಾಂಕ್ ಖಾತೆ ವಿವರಗಳ (Bank Account Statement) ಸ್ವಯಂ ದೃಢೀಕರಿಸಿದ ಪ್ರತಿ.", "ಗುತ್ತಿಗೆ ಪತ್ರ (Lease Deed) / ಬಾಡಿಗೆ ಒಪ್ಪಂದದ (Rental Agreement) ಪ್ರತಿ, ಗುತ್ತಿಗೆ/ಬಾಡಿಗೆಗೆ ಪಡೆದಿರುವ ಒಟ್ಟು ಸ್ಥಳದ ವಿವರಗಳೊಂದಿಗೆ. ಅರ್ಜಿದಾರರು ಮರುಪಾವತಿ ಕೋರುತ್ತಿರುವ ಅವಧಿಗೆ ಸಂಬಂಧಿಸಿದಂತೆ ಗುತ್ತಿಗೆ ಪತ್ರ/ಬಾಡಿಗೆ ಒಪ್ಪಂದವು ಮಾನ್ಯವಾಗಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ಮರುಪಾವತಿ ಕೋರುತ್ತಿರುವ ಅವಧಿಗೆ ಸಂಬಂಧಿಸಿದ ಗುತ್ತಿಗೆ/ಬಾಡಿಗೆ ಪಾವತಿಗೆ ಮಾಡಿದ ಇನ್"]', NULL, NULL, '3372');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('a3dae6ad-8039-4993-988c-ecada6120197', 'DEPARTMENT-OF-ELECTR-21', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'EPF Contribution Reimbursement', 'General', 60, 'GoK shall reimburse the employer''s EPF contributions for new hires', '["Self-Declaration regarding the No. of new workforce/ employees being considered for the computation of the EPF contribution reimbursement incentive.", "Company/Entity declaration for availing incentives for GCC.", "CA Certified letter mentioning employee’s details, PF no., and PF contribution of the new employees recruited by the Applicant, along with Self-attested copies of the Employment record.", "Self-attested copies of the Employment records for all new people employed for last 2 years: Self- attested copies of monthly employees and employer’s contribution statement from the official website of PF (https://www.epfindia.gov.in/site_en/index.php )", "Self-attested declaration on the official letterhead stating that appropriate recovery shall be made if the unit fails to maintain employment for a two-year period in accordance with the guidelines."]', '["Applicable to New GCCs setting up with 100+ Employees", "The company should be based in Beyond Bengaluru District", "An Applicant can apply for reimbursement of Provident Fund (PF) for the new employment created during the policy period for a continuous period of 2 years.", "The Applicant shall have completed at least 2 years of commercial operations."]', '[]', '["The applicant Company should be registered with KITS under GCC Policy 2024-29", "Company should submit the incentive application along with supporting documents as prescribed in the OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/gcc/epf-reimbursement', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಉದ್ಯೋಗಿಗಳ ಭವಿಷ್ಯ ನಿಧಿ (EPF) ಕೊಡುಗೆ ಮರುಪಾವತಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಹೊಸದಾಗಿ ನೇಮಕಗೊಂಡ ನೌಕರರಿಗಾಗಿ ಉದ್ಯೋಗದಾತರು ನೀಡುವ ಇಪಿಎಫ್ (EPF) ವಂತಿಗೆಯನ್ನು ಕರ್ನಾಟಕ ಸರ್ಕಾರವು ಮರುಪಾವತಿಸುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["100 ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ಉದ್ಯೋಗಿಗಳನ್ನು ಹೊಂದಿರುವ ಹೊಸದಾಗಿ ಸ್ಥಾಪಿಸಲಾದ ಜಾಗತಿಕ ಸಾಮರ್ಥ್ಯ ಕೇಂದ್ರಗಳಿಗೆ (GCCs) ಅನ್ವಯಿಸುತ್ತದೆ.", "ಸಂಸ್ಥೆಯು ಬೆಂಗಳೂರು ಹೊರವಲಯ ಜಿಲ್ಲೆಯಲ್ಲಿರಬೇಕು.", "ಅರ್ಜಿದಾರರು ನೀತಿಯ ಅವಧಿಯಲ್ಲಿ ಸೃಷ್ಟಿಸಲಾದ ಹೊಸ ಉದ್ಯೋಗಗಳಿಗೆ ಸಂಬಂಧಿಸಿದಂತೆ ಉದ್ಯೋಗಿಗಳ ಭವಿಷ್ಯ ನಿಧಿ (Provident Fund - PF) ಕೊಡುಗೆ ಮರುಪಾವತಿಗಾಗಿ ಸತತ ಎರಡು ವರ್ಷಗಳ ಅವಧಿಗೆ ಅರ್ಜಿ ಸಲ್ಲಿಸಲು ಅರ್ಹರಾಗಿರುತ್ತಾರೆ.", "ಅರ್ಜಿದಾರರು ಕನಿಷ್ಠ ಎರಡು ವರ್ಷಗಳ ವಾಣಿಜ್ಯ ಕಾರ್ಯಾಚರಣೆಯನ್ನು ಪೂರ್ಣಗೊಳಿಸಿರಬೇಕು."]', '["ಅರ್ಜಿದಾರ ಕಂಪನಿಯು GCC ನೀತಿಯಡಿ ಕರ್ನಾಟಕ ನವೋದ್ಯಮ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ಯಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["ಪ್ರೋತ್ಸಾಹಧನದ ಲೆಕ್ಕಾಚಾರಕ್ಕಾಗಿ ಪರಿಗಣಿಸಿರುವ ಹೊಸ ಉದ್ಯೋಗಿಗಳ ಸಂಖ್ಯೆ ಕುರಿತು ಸ್ವಯಂ ಘೋಷಣಾಪತ್ರ.", "ಜಿಸಿಸಿ (GCC) ಪ್ರೋತ್ಸಾಹಧನವನ್ನು ಪಡೆಯಲು ಸಂಸ್ಥೆ/ಘಟಕದಿಂದ ನೀಡಲಾದ ಘೋಷಣಾಪತ್ರ.", "ಅರ್ಜಿದಾರರು ನೇಮಕ ಮಾಡಿರುವ ಹೊಸ ಉದ್ಯೋಗಿಗಳ ವಿವರಗಳು, ಉದ್ಯೋಗಿಗಳ ಭವಿಷ್ಯ ನಿಧಿ (PF) ಸಂಖ್ಯೆ, ಪಿಎಫ್ (PF) ಕೊಡುಗೆ ವಿವರಗಳನ್ನು ಒಳಗೊಂಡಂತೆ ಚಾರ್ಟರ್ಡ್ ಅಕೌಂಟೆಂಟ್ (CA) ದೃಢೀಕರಿಸಿದ ಪತ್ರ ಹಾಗೂ ಉದ್ಯೋಗ ದಾಖಲೆಗಳ ಸ್ವಯಂ ದೃಢೀಕರಿಸಿದ ಪ್ರತಿಗಳು.", "ಕಳೆದ ಎರಡು ವರ್ಷಗಳಲ್ಲಿ ನೇಮಕಗೊಂಡ ಎಲ್ಲಾ ಹೊಸ ಉದ್ಯೋಗಿಗಳ ಉದ್ಯೋಗ ದಾಖಲೆಗಳ ಸ್ವಯಂ ದೃಢೀಕರಿಸಿದ ಪ್ರತಿಗಳು ಹಾಗೂ ಉದ್ಯೋಗಿಗಳ ಮತ್ತು ಉದ್ಯೋಗದಾತರ ಮಾಸಿಕ ಪಿಎಫ್ (PF) ಕೊಡುಗೆ ವಿವರಗಳ ಸ್ವಯಂ ದೃಢೀಕರಿಸಿದ ಪ್ರತಿಗಳು, ಉದ್ಯೋಗಿಗಳ ಭವಿಷ್ಯ ನಿಧಿ ಸಂಸ್ಥೆಯ (EPFO) ಅಧಿಕೃತ ವೆಬ್"]', NULL, NULL, '3329');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('6349ee20-3150-44b0-a76c-84ce38f5e504', 'DEPARTMENT-OF-ELECTR-23', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Electricity Duty Exemption', 'General', 60, 'GoK shall provide reimbursement of electricity duty to GCC entities registered with KITS,', '["i. Copy of the Registration Certificate issued by KITS.", "ii. Self-attested copy of registered rent/ lease agreement", "iii. Self-attested copy of ESCOMs power service letter with R.R. No. and date", "iv. Self- attested copies of the last 3 months of electricity bills since the date of submission of the application", "v. Power Tariff Sanction Letter Copy (as applicable)", "vi. Copy of the letter / order - Electricity Duty Reimbursement (as applicable)", "vii. A self-attested copy on letterhead stating the reimbursement requested for the electricity duty (complete calculation along with the breakup) for the period being claimed."]', '["Applicable to New GCCs across Karnataka", "An applicant may apply for Reimbursement of Electricity Duty within 12 months from the month of Commencement of Commercial Production. However, eligible applicants whose Date of Commencement of Commercial Production has already been achieved on the date of issue of these Guidelines may apply for reimbursement of electrical duty within 12 months from the date of issue of these guidelines.", "This reimbursement shall be in accordance with the enabling notification issued by the Energy Department, Government of Karnataka, and shall take effect upon its issuance.", "In case the applicant is availing reimbursement of electricity duty, the following conditions shall be applicable::", "o Where RR No. is in the name of the applicant and the applicant is also the owner of the premise, the applicant shall be eligible for this incentive.", "o Where RR No. is not under applicant’s name but in the name of the developer / owner owning the premise and applicant is the sole occupant of the premise, the applicant shall be eligible for this incentive.", "o Where RR No. is in the name of the developer/ owner having multiple tenants and applicant being one of them and the applicant has a submeter installed by the ESCOM, then the applicant shall be eligible for this incentive.", "o Where RR No. is in the name of the developer/ owner having multiple tenants and applicant being one of them and the applicant is not having a submeter installed by the ESCOM, then the applicant shall not be eligible for this incentive."]', '[]', '["The applicant Company should be registered with KITS under GCC Policy 2024-29", "Company should submit the incentive application along with supporting documents as prescribed in the OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/gcc/power-tariff-concession', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ವಿದ್ಯುತ್ ಸುಂಕ ವಿನಾಯಿತಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'KITS ನಲ್ಲಿ ನೋಂದಾಯಿತವಾದ GCC ಸಂಸ್ಥೆಗಳಿಗೆ ಕರ್ನಾಟಕ ಸರ್ಕಾರವು ವಿದ್ಯುತ್ ಸುಂಕದ (Electricity Duty) ಮರುಪಾವತಿಯನ್ನು ಒದಗಿಸುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕದಾದ್ಯಂತ ಹೊಸದಾಗಿ ಸ್ಥಾಪಿಸಲಾದ ಜಾಗತಿಕ ಸಾಮರ್ಥ್ಯ ಕೇಂದ್ರಗಳಿಗೆ (GCCs) ಅನ್ವಯಿಸುತ್ತದೆ.", "ಅರ್ಜಿದಾರರು ವಾಣಿಜ್ಯ ಕಾರ್ಯಾಚರಣೆ ಆರಂಭಗೊಂಡ (Date of Commencement of Commercial Production) ತಿಂಗಳಿನಿಂದ 12 ತಿಂಗಳೊಳಗೆ ವಿದ್ಯುತ್ ಸುಂಕ ಮರುಪಾವತಿಗಾಗಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು. ಆದರೆ, ಈ ಮಾರ್ಗಸೂಚಿಗಳು ಹೊರಬಂದ ದಿನಾಂಕದ ವೇಳೆಗೆ ವಾಣಿಜ್ಯ ಕಾರ್ಯಾಚರಣೆ ಆರಂಭಗೊಂಡಿರುವ ಅರ್ಹ ಅರ್ಜಿದಾರರು, ಈ ಮಾರ್ಗಸೂಚಿಗಳು ಹೊರಬಂದ ದಿನಾಂಕದಿಂದ 12 ತಿಂಗಳೊಳಗೆ ವಿದ್ಯುತ್ ಸುಂಕ ಮರುಪಾವತಿಗಾಗಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು.", "ಈ ಮರುಪಾವತಿಯು ಕರ್ನಾಟಕ ಸರ್ಕಾರದ ಇಂಧನ ಇಲಾಖೆಯು ಹೊರಡಿಸುವ ಸಕ್ರಿಯಗೊಳಿಸುವ ಅಧಿಸೂಚನೆಗೆ ಅನುಗುಣವಾಗಿದ್ದು, ಆ ಅಧಿಸೂಚನೆ ಜಾರಿಯಾದ ದಿನಾಂಕದಿಂದಲೇ ಅನ್ವಯವಾಗುತ್ತದೆ.", "ಅರ್ಜಿದಾರರು ವಿದ್ಯುತ್ ಸುಂಕ ಮರುಪಾವತಿಯನ್ನು ಪಡೆಯುತ್ತಿರುವಲ್ಲಿ, ಕೆಳಗಿನ ಷರತ್ತುಗಳು ಅನ್ವಯವಾಗುತ್ತವೆ:", "I. ಆರ್.ಆರ್. ಸಂಖ್ಯೆ (RR No.) ಅರ್ಜಿದಾರರ ಹೆಸರಿನಲ್ಲಿದ್ದು, ಅರ್ಜಿದಾರರು ಕಟ್ಟಡದ ಮಾಲೀಕರಾಗಿದ್ದರೆ, ಅವರು ಈ ಪ್ರೋತ್ಸಾಹಧನಕ್ಕೆ ಅರ್ಹರಾಗಿರುತ್ತಾರೆ.", "II. ಆರ್.ಆರ್. ಸಂಖ್ಯೆ (RR No.) ಅರ್ಜಿದಾರರ ಹೆಸರಿನಲ್ಲಿರದೆ, ಕಟ್ಟಡದ ಮಾಲೀಕ/ಅಭಿವೃದ್ಧಿಪಡಿಸುವವರ ಹೆಸರಿನಲ್ಲಿದ್ದು, ಅರ್ಜಿದಾರರು ಆ ಕಟ್ಟಡದ ಏಕೈಕ ಬಳಕೆದಾರರಾಗಿದ್ದರೆ, ಅವರು ಈ ಪ್ರೋತ್ಸಾಹಧನಕ್ಕೆ ಅರ್ಹರಾಗಿರುತ್ತಾರೆ.", "III. ಆರ್.ಆರ್. ಸಂಖ್ಯೆ (RR No.) ಕಟ್ಟಡದ ಮಾಲೀಕ/ಅಭಿವೃದ್ಧಿಪಡಿಸುವವರ ಹೆಸರಿನಲ್ಲಿದ್ದು, ಕಟ್ಟಡದಲ್ಲಿ ಅನೇಕ ಬಾಡಿಗೆದಾರರು ಇದ್ದು, ಅರ್ಜಿದಾರರು ಅವರಲ್ಲಿ ಒಬ್ಬರಾಗಿದ್ದು, ವಿದ್ಯುತ್ ಸರಬರಾಜು ಸಂಸ್ಥೆ (ESCOM) ಅಳವಡಿಸಿರುವ ಉಪ-ಮೀಟರ್ (Sub-meter) ಹೊಂದಿದ್ದರೆ, ಅವರು ಈ ಪ್ರೋತ್ಸಾಹಧನಕ್ಕೆ ಅರ್ಹರಾಗಿರುತ್ತಾರೆ.", "IV. ಆರ್.ಆರ್. ಸಂಖ್ಯೆ (RR No.) ಕಟ್ಟಡದ ಮಾಲೀಕ/ಅಭಿವೃದ್ಧಿಪಡಿಸುವವರ ಹೆಸರಿನಲ್ಲಿದ್ದು, ಕಟ್ಟಡದಲ್ಲಿ ಅನೇಕ ಬಾಡಿಗೆದಾರರು ಇದ್ದು, ಅರ್ಜಿದಾರರು ಅವರಲ್ಲಿ ಒಬ್ಬರಾಗಿದ್ದು, ವಿದ್ಯುತ್ ಸರಬರಾಜು ಸಂಸ್ಥೆ (ESCOM) ಅಳವಡಿಸಿರುವ ಉಪ-ಮೀಟರ್ (Sub-meter) ಹೊಂದಿರದಿದ್ದರೆ, ಅವರು ಈ ಪ್ರೋತ್ಸಾಹಧನಕ್ಕೆ ಅರ್ಹರಾಗಿರುವುದಿಲ್ಲ."]', '["ಅರ್ಜಿದಾರ ಕಂಪನಿಯು GCC ನೀತಿಯಡಿ ಕರ್ನಾಟಕ ನವೋದ್ಯಮ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ಯಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["i. ಕರ್ನಾಟಕ ಇನ್ನೋವೇಷನ್ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ವತಿಯಿಂದ ನೀಡಲಾದ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರದ ಪ್ರತಿ.", "ii. ನೋಂದಾಯಿತ ಬಾಡಿಗೆ / ಗುತ್ತಿಗೆ (Rent/Lease) ಒಪ್ಪಂದದ ಸ್ವಯಂ ದೃಢೀಕರಿಸಿದ ಪ್ರತಿ.", "iii. ವಿದ್ಯುತ್ ಸರಬರಾಜು ಸಂಸ್ಥೆ (ESCOM) ನೀಡಿರುವ ವಿದ್ಯುತ್ ಸೇವಾ ಮಂಜೂರಾತಿ ಪತ್ರದ (Power Service Letter) ಸ್ವಯಂ ದೃಢೀಕರಿಸಿದ ಪ್ರತಿ, ಇದರಲ್ಲಿ ಆರ್.ಆರ್. ಸಂಖ್ಯೆ (R.R. No.) ಹಾಗೂ ಮಂಜೂರಾತಿ ದಿನಾಂಕದ ವಿವರಗಳಿರಬೇಕು.", "iv. ಅರ್ಜಿ ಸಲ್ಲಿಸಿದ ದಿನಾಂಕದವರೆಗೆ ಕಳೆದ ಮೂರು ತಿಂಗಳ ವಿದ್ಯುತ್ ಬಿಲ್"]', NULL, NULL, '3348');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('979f1d8a-921f-4078-b544-9168687b2202', 'DEPARTMENT-OF-ELECTR-26', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Quality Certification Financial Assistance', 'General', 60, 'GoK provides reimbursement for the cost of Quality Certifications, to GCC entities registered with KITS, for obtaining the products/services certified under any industry standard quality certification, such as ISO Certification, CMMi Certification, SOC etc.', '["Self-attested copy of the testing/certification certificate received, along with payment receipts.", "Copy of the certificate from accredited agencies confirming the validity of the certificate.", "For reimbursement for ISO Certificate - Self-attested copy of the ISO Certificate obtained from NABCB accredited agencies."]', '["Applicable to GCCs across Karnataka", "This incentive is applicable to Quality Certifications that are obtained for the products/services certified under any industry standard quality certification, such as ISO Certification, CMMi Certification, SOC etc", "The applicant should submit the application for reimbursement within twelve (12) months from the date of the receipt of quality certification."]', '[]', '["The applicant Company should be registered with KITS under GCC Policy 2024-29", "Company should submit the incentive application along with supporting documents as prescribed in the OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/gcc/quality-certification-cost-reimbursement', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಗುಣಮಟ್ಟ ಪ್ರಮಾಣೀಕರಣಕ್ಕಾಗಿ ಹಣಕಾಸು ನೆರವು', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ISO ಪ್ರಮಾಣೀಕರಣ, CMMi ಪ್ರಮಾಣೀಕರಣ, SOC ನಂತಹ ಯಾವುದೇ ಉದ್ಯಮದ ಗುಣಮಟ್ಟದ ಪ್ರಮಾಣೀಕರಣದಡಿಯಲ್ಲಿ ಉತ್ಪನ್ನಗಳು/ಸೇವೆಗಳಿಗೆ ಪ್ರಮಾಣಪತ್ರ ಪಡೆಯಲು, KITS ನಲ್ಲಿ ನೋಂದಾಯಿತವಾದ GCC ಸಂಸ್ಥೆಗಳಿಗೆ ಗುಣಮಟ್ಟದ ಪ್ರಮಾಣೀಕರಣದ (Quality Certifications) ವೆಚ್ಚವನ್ನು ಕರ್ನಾಟಕ ಸರ್ಕಾರವು ಮರುಪಾವತಿಸುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕದಾದ್ಯಂತ ಸ್ಥಾಪಿತವಾಗಿರುವ ಜಾಗತಿಕ ಸಾಮರ್ಥ್ಯ ಕೇಂದ್ರಗಳಿಗೆ (GCCs) ಅನ್ವಯಿಸುತ್ತದೆ.", "ಈ ಪ್ರೋತ್ಸಾಹಧನವು ಕೈಗಾರಿಕಾ ಗುಣಮಟ್ಟದ ಮಾನದಂಡಗಳ ಅಡಿಯಲ್ಲಿ ಉತ್ಪನ್ನಗಳು/ಸೇವೆಗಳಿಗೆ ಪಡೆಯಲಾದ ಗುಣಮಟ್ಟ ಪ್ರಮಾಣೀಕರಣಗಳಿಗೆ ಅನ್ವಯಿಸುತ್ತದೆ. ಉದಾಹರಣೆಗೆ ISO ಪ್ರಮಾಣೀಕರಣ, CMMI ಪ್ರಮಾಣೀಕರಣ, SOC ಪ್ರಮಾಣೀಕರಣ ಇತ್ಯಾದಿ.", "ಅರ್ಜಿದಾರರು ಗುಣಮಟ್ಟ ಪ್ರಮಾಣೀಕರಣವನ್ನು ಪಡೆದ ದಿನಾಂಕದಿಂದ ಹನ್ನೆರಡು (12) ತಿಂಗಳೊಳಗೆ ಮರುಪಾವತಿಗಾಗಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಬೇಕು."]', '["ಅರ್ಜಿದಾರ ಕಂಪನಿಯು GCC ನೀತಿಯಡಿ ಕರ್ನಾಟಕ ನವೋದ್ಯಮ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ಯಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["ಪಡೆದಿರುವ ಪರೀಕ್ಷೆ/ಪ್ರಮಾಣೀಕರಣ ಪ್ರಮಾಣಪತ್ರದ (Testing/Certification Certificate) ಸ್ವಯಂ ದೃಢೀಕರಿಸಿದ ಪ್ರತಿ ಹಾಗೂ ಪಾವತಿ ರಸೀದಿಗಳ ಪ್ರತಿಗಳು.", "ಮಾನ್ಯತೆ ಪಡೆದ (Accredited) ಸಂಸ್ಥೆಗಳಿಂದ ಪ್ರಮಾಣೀಕರಣದ ಮಾನ್ಯತೆಯನ್ನು ದೃಢೀಕರಿಸುವ ಪ್ರಮಾಣಪತ್ರದ ಪ್ರತಿ.", "ISO ಪ್ರಮಾಣೀಕರಣದ ಮರುಪಾವತಿಗಾಗಿ, ರಾಷ್ಟ್ರೀಯ ಪ್ರಮಾಣೀಕರಣ ಮಂಡಳಿ (NABCB) ಮಾನ್ಯತೆ ಪಡೆದ ಸಂಸ್ಥೆಯಿಂದ ಪಡೆದ ISO ಪ್ರಮಾಣಪತ್ರದ ಸ್ವಯಂ ದೃಢೀಕರಿಸಿದ ಪ್ರತಿ."]', NULL, NULL, '3371');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('27085e24-03ad-4b36-91de-400cf2429ae9', 'DEPARTMENT-OF-ELECTR-27', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Co-Working Spaces Incentive', 'General', 60, 'Setting up co-working spaces in Beyond Bengaluru District area will be promoted by reimbursing operational expenses.', '["i. Copy of the Rental agreement or a Sanction Certificate on the letterhead of the co- working space entity, with details of total number of the seats occupied by the Applicant and the per seat rate for time period the rental reimbursement is being claimed for by the Applicant.", "ii. Copy of the Revenue Sharing or Profit-Sharing Agreement between the landlord of the building and the developer of the co-working space, as applicable.", "iii. Copy of Co Working Space Membership manual, membership agreement etc.,", "iv. Declaration by the Admin / HR with copy of Attendance Records of the Members / Punch-In Punch-Out Data / Seat utilization reports.", "v. Copy of the Building Plan and Seating Arrangement plan.", "vi. Copies of Invoices/receipts of payment made for the for occupancy of seats for the time period the reimbursement is being claimed for by the Applicant.", "vii. Copy of the property documents such as sale deed agreement, building occupancy certificate, fire safety certificate, insurance liability certificate (as applicable)", "viii. Copy of last 3 Financial years or latest ITRs (whichever is later), Balance Sheets, Auditor’s Certificate"]', '["The applicant should have a minimum dedicated area of 7,500 sq. ft. for co-working activities, with at least 50 seats, such that the space is occupied by one or more entities/occupants.", "Applicable to C-working space developer in Beyond Bengaluru District", "The incentive is applicable only to applicants establishing a new co-working space in Beyond Bengaluru Region, i.e., after the policy notification date (03.12.2024).", "The applicant shall be eligible to claim the incentive only if a minimum occupancy rate of 40% is achieved at the co-working setup.", "The Applicant shall have completed at least 1 year of commercial operations"]', '[]', '["The applicant Company should be registered with KITS under GCC Policy 2024-29", "Company should submit the incentive application along with supporting documents as prescribed in the OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/gcc/co-working-space-incentive', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಸಹ-ಕಾರ್ಯಸ್ಥಳಗಳಿಗಾಗಿ ಪ್ರೋತ್ಸಾಹಧನ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '"ಬಿಯಾಂಡ್ ಬೆಂಗಳೂರು" ಜಿಲ್ಲಾ ಪ್ರದೇಶದಲ್ಲಿ ಕಾರ್ಯಾಚರಣೆಯ ವೆಚ್ಚಗಳನ್ನು ಮರುಪಾವತಿಸುವ ಮೂಲಕ ''ಸಹ-ಕೆಲಸದ ಸ್ಥಳಗಳನ್ನು'' (Co-working spaces) ಸ್ಥಾಪಿಸುವುದನ್ನು ಉತ್ತೇಜಿಸಲಾಗುವುದು.', NULL, NULL, NULL, NULL, NULL, '["ಅರ್ಜಿದಾರರು ಸಹ-ಕಾರ್ಯಸ್ಥಳ (Co-Working Space) ಚಟುವಟಿಕೆಗಳಿಗಾಗಿ ಕನಿಷ್ಠ 7,500 ಚದರ ಅಡಿ ಮೀಸಲು ವಿಸ್ತೀರ್ಣವನ್ನು ಹೊಂದಿರಬೇಕು. ಈ ಸ್ಥಳದಲ್ಲಿ ಕನಿಷ್ಠ 50 ಆಸನಗಳಿದ್ದು, ಒಂದು ಅಥವಾ ಹೆಚ್ಚಿನ ಸಂಸ್ಥೆಗಳು/ಬಳಕೆದಾರರು ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿರಬೇಕು.", "ಈ ಪ್ರೋತ್ಸಾಹಧನವು ಬೆಂಗಳೂರು ಹೊರವಲಯ ಜಿಲ್ಲೆಗಳಲ್ಲಿರುವ ಸಹ-ಕಾರ್ಯಸ್ಥಳ (Co-Working Space) ಅಭಿವೃದ್ಧಿಪಡಿಸುವ ಸಂಸ್ಥೆಗಳಿಗೆ ಅನ್ವಯಿಸುತ್ತದೆ.", "ಈ ಪ್ರೋತ್ಸಾಹಧನವು ನೀತಿ ಅಧಿಸೂಚನೆ ದಿನಾಂಕ (03.12.2024) ನಂತರ ಬೆಂಗಳೂರು ಹೊರವಲಯ ಪ್ರದೇಶದಲ್ಲಿ ಹೊಸದಾಗಿ ಸ್ಥಾಪಿಸಲಾದ ಸಹ-ಕಾರ್ಯಸ್ಥಳಗಳಿಗೆ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ.", "ಸಹ-ಕಾರ್ಯಸ್ಥಳದಲ್ಲಿ ಕನಿಷ್ಠ 40% ಆಕ್ಯುಪೆನ್ಸಿ (Occupancy) ಸಾಧಿಸಿದ ನಂತರವೇ ಅರ್ಜಿದಾರರು ಈ ಪ್ರೋತ್ಸಾಹಧನವನ್ನು ಪಡೆಯಲು ಅರ್ಹರಾಗಿರುತ್ತಾರೆ.", "ಅರ್ಜಿದಾರರು ಕನಿಷ್ಠ ಒಂದು ವರ್ಷದ ವಾಣಿಜ್ಯ ಕಾರ್ಯಾಚರಣೆಯನ್ನು ಪೂರ್ಣಗೊಳಿಸಿರಬೇಕು."]', '["ಅರ್ಜಿದಾರ ಕಂಪನಿಯು GCC ನೀತಿಯಡಿ ಕರ್ನಾಟಕ ನವೋದ್ಯಮ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ಯಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["i. ಸಹ-ಕಾರ್ಯಸ್ಥಳ (Co-Working Space) ಸಂಸ್ಥೆಯ ಲೆಟರ್"]', NULL, NULL, '3376');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('8b0a9cde-1717-4d1e-9d11-3cef84079e22', 'DEPARTMENT-OF-ELECTR-28', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Internship Stipend Reimbursement', 'General', 60, 'GoK will collaborate with industry associations to facilitate internships between academia and industry', '["Copy of Internship Offer letters / Agreement/ Contract (as applicable)", "CA certified statement of claims submitted by the company detailing the number of interns, the stipend amount paid, and the period of reimbursement.", "Copy of documents indicating whether taxes have been deducted from the stipend, if applicable.", "A letter from the college authority stating that the internship is a part of the course curriculum.", "A detailed description of the internship program, including the nature of work, learning outcomes, and objectives."]', '["Applicable to GCCs across Karnataka", "Application for reimbursement can be filed on an annual basis during the policy period. For one full year of commercial operations, the application should be submitted within twelve (12) months from the completion of such one-year period."]', '[]', '["The applicant Company should be registered with KITS under GCC Policy 2024-29", "Company should submit the incentive application along with supporting documents as prescribed in the OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/gcc/internship-stipend', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಇಂಟರ್ನ್', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಶೈಕ್ಷಣಿಕ ಕ್ಷೇತ್ರ ಮತ್ತು ಉದ್ಯಮಗಳ ನಡುವೆ ಇಂಟರ್ನ್', NULL, NULL, NULL, NULL, NULL, '["ಕರ್ನಾಟಕದಾದ್ಯಂತ ಸ್ಥಾಪಿತವಾಗಿರುವ ಜಾಗತಿಕ ಸಾಮರ್ಥ್ಯ ಕೇಂದ್ರಗಳಿಗೆ (GCCs) ಅನ್ವಯಿಸುತ್ತದೆ.", "ಪ್ರೋತ್ಸಾಹಧನದ ಮರುಪಾವತಿಗಾಗಿ ಅರ್ಜಿಯನ್ನು ನೀತಿಯ ಅವಧಿಯಲ್ಲಿ ವಾರ್ಷಿಕ ಆಧಾರದ ಮೇಲೆ ಸಲ್ಲಿಸಬಹುದು. ಒಂದು ಪೂರ್ಣ ವರ್ಷದ ವಾಣಿಜ್ಯ ಕಾರ್ಯಾಚರಣೆಗೆ ಸಂಬಂಧಿಸಿದ ಮರುಪಾವತಿ ಅರ್ಜಿಯನ್ನು, ಆ ಒಂದು ವರ್ಷದ ಅವಧಿ ಪೂರ್ಣಗೊಂಡ ದಿನಾಂಕದಿಂದ ಹನ್ನೆರಡು (12) ತಿಂಗಳೊಳಗೆ ಸಲ್ಲಿಸಬೇಕು."]', '["ಅರ್ಜಿದಾರ ಕಂಪನಿಯು GCC ನೀತಿಯಡಿ ಕರ್ನಾಟಕ ನವೋದ್ಯಮ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ಯಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '[". ಇಂಟರ್ನ್"]', NULL, NULL, '3387');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('94eaa208-df12-440e-b396-f390589ee158', 'DEPARTMENT-OF-ELECTR-30', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Skilling of Local Talent', 'General', 60, 'Government of Karnataka (GoK) will support and promote various skilling initiatives for new recruits within one year of their hiring, thereby enhancing workforce competency, improving employability, and ensuring alignment with industry benchmarks.', '["i. Detailed proposal of the trainings and its duration that the employees have undergone (comprising of Skilling Program Design (domains, duration, target groups).", "ii. Detailed Budget and Funding Plan.", "iii. Infrastructure and Delivery Model.", "iv. Monitoring and Outcome Evaluation Plan. (Assessment and certifications)", "v. Copy of Letters of Support from Partner Institutions.", "vi. HR Certificate on a company letterhead confirming that the new recruits being trained are based in Karnataka.", "vii. Trainer profiles or training partner agreements with credentials.", "viii. Post-training assessment reports & Certificates issued.", "ix. Attendance records (with details like name, email, mobile number, designation, employee number etc.,) and data showing number of employees trained.", "x. Copies of invoices with a CA certificate confirming the expenses."]', '["Applicable to GCC’s across the state.", "The company must provide formal training or skill development programs to the recruited local talent within 01 year of hiring. The training should aim to upgrade the employees’ skills to meet industry standards.", "The New recruits participating in the skilling program must be based in Karnataka.", "Training programs should be designed in alignment with industry-relevant skills, covering both technical and soft skill development for the new employees.", "Measurable learning outcomes shall be ensured through assessments, with recognized certifications.", "Total expenses shall comprise costs incurred for training programs, including fees paid to training providers, costs of training materials, and related", "expenditures, subject to the maximum limit specified by the policy.", "Applicants must submit detailed proof of local hires, training schedules, attendance records, and invoices for training-related expenses. All claims will be subject to verification by the Government."]', '[]', '["The applicant Company should be registered with KITS under GCC Policy 2024-29", "Company should submit the incentive application along with supporting documents as prescribed in the OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/gcc/skilling-local-talent', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಸ್ಥಳೀಯ ಪ್ರತಿಭೆಗಳ ಕೌಶಲ್ಯಾಭಿವೃದ್ಧಿ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಕರ್ನಾಟಕ ಸರ್ಕಾರವು (GoK) ಹೊಸದಾಗಿ ನೇಮಕಗೊಂಡ ನೌಕರರು ಕೆಲಸಕ್ಕೆ ಸೇರಿದ ಒಂದು ವರ್ಷದೊಳಗೆ ಅವರಿಗೆ ವಿವಿಧ ಕೌಶಲ್ಯ ಅಭಿವೃದ್ಧಿ ಉಪಕ್ರಮಗಳನ್ನು ಬೆಂಬಲಿಸುತ್ತದೆ ಮತ್ತು ಉತ್ತೇಜಿಸುತ್ತದೆ. ಇದರಿಂದ ಕಾರ್ಯಪಡೆಯ ಸಾಮರ್ಥ್ಯ ಹೆಚ್ಚಾಗುತ್ತದೆ, ಉದ್ಯೋಗಾರ್ಹತೆ ಸುಧಾರಿಸುತ್ತದೆ ಮತ್ತು ಉದ್ಯಮದ ಮಾನದಂಡಗಳಿಗೆ ಅನುಗುಣವಾಗಿ ಹೊಂದಾಣಿಕೆಯಾಗುತ್ತದೆ.', NULL, NULL, NULL, NULL, NULL, '["ರಾಜ್ಯದಾದ್ಯಂತ ಇರುವ ಜಾಗತಿಕ ಸಾಮರ್ಥ್ಯ ಕೇಂದ್ರಗಳಿಗೆ (GCCs) ಅನ್ವಯಿಸುತ್ತದೆ.", "ಸಂಸ್ಥೆಯು ನೇಮಕಗೊಂಡ ಸ್ಥಳೀಯ ಪ್ರತಿಭೆಗಳಿಗೆ ನೇಮಕಾತಿಯ ದಿನಾಂಕದಿಂದ ಒಂದು (1) ವರ್ಷದೊಳಗೆ ಔಪಚಾರಿಕ ತರಬೇತಿ ಅಥವಾ ಕೌಶಲ್ಯಾಭಿವೃದ್ಧಿ ಕಾರ್ಯಕ್ರಮಗಳನ್ನು ಒದಗಿಸಬೇಕು. ಈ ತರಬೇತಿಯು ಉದ್ಯೋಗಿಗಳ ಕೌಶಲ್ಯಗಳನ್ನು ಕೈಗಾರಿಕಾ ಮಾನದಂಡಗಳಿಗೆ ಅನುಗುಣವಾಗಿ ಉನ್ನತೀಕರಿಸುವ ಉದ್ದೇಶವನ್ನು ಹೊಂದಿರಬೇಕು.", "ಕೌಶಲ್ಯಾಭಿವೃದ್ಧಿ ಕಾರ್ಯಕ್ರಮದಲ್ಲಿ ಭಾಗವಹಿಸುವ ಹೊಸದಾಗಿ ನೇಮಕಗೊಂಡ ಉದ್ಯೋಗಿಗಳು ಕರ್ನಾಟಕ ರಾಜ್ಯದಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿರಬೇಕು.", "ತರಬೇತಿ ಕಾರ್ಯಕ್ರಮಗಳನ್ನು ಕೈಗಾರಿಕೆಗೆ ಸಂಬಂಧಿಸಿದ ಕೌಶಲ್ಯಗಳಿಗೆ ಅನುಗುಣವಾಗಿ ರೂಪಿಸಬೇಕು ಹಾಗೂ ಹೊಸ ಉದ್ಯೋಗಿಗಳ ತಾಂತ್ರಿಕ (Technical) ಮತ್ತು ಮೃದು ಕೌಶಲ್ಯಗಳ (Soft Skills) ಅಭಿವೃದ್ಧಿಯನ್ನು ಒಳಗೊಂಡಿರಬೇಕು.", "ಮೌಲ್ಯಮಾಪನಗಳ (Assessments) ಮೂಲಕ ಅಳೆಯಬಹುದಾದ ಕಲಿಕಾ ಫಲಿತಾಂಶಗಳನ್ನು ಖಚಿತಪಡಿಸಬೇಕು ಹಾಗೂ ಮಾನ್ಯತೆ ಪಡೆದ ಪ್ರಮಾಣೀಕರಣಗಳನ್ನು (Recognized Certifications) ಒದಗಿಸಬೇಕು.", "ಒಟ್ಟು ವೆಚ್ಚದಲ್ಲಿ ತರಬೇತಿ ಕಾರ್ಯಕ್ರಮಗಳಿಗೆ ಉಂಟಾದ ವೆಚ್ಚಗಳು, ತರಬೇತಿ ಸಂಸ್ಥೆಗಳಿಗೆ ಪಾವತಿಸಿದ ಶುಲ್ಕ, ತರಬೇತಿ ಸಾಮಗ್ರಿಗಳ ವೆಚ್ಚ ಹಾಗೂ ಇತರೆ ಸಂಬಂಧಿತ ವೆಚ್ಚಗಳು ಒಳಗೊಂಡಿರುತ್ತವೆ. ಈ ವೆಚ್ಚಗಳು ನೀತಿಯಡಿ ನಿಗದಿಪಡಿಸಲಾದ ಗರಿಷ್ಠ ಮಿತಿಗೆ ಒಳಪಟ್ಟಿರುತ್ತವೆ.", "ಅರ್ಜಿದಾರರು ಸ್ಥಳೀಯವಾಗಿ ನೇಮಕಗೊಂಡ ಉದ್ಯೋಗಿಗಳ ವಿವರಗಳು, ತರಬೇತಿ ವೇಳಾಪಟ್ಟಿಗಳು, ಹಾಜರಾತಿ ದಾಖಲೆಗಳು ಹಾಗೂ ತರಬೇತಿಗೆ ಸಂಬಂಧಿಸಿದ ವೆಚ್ಚಗಳ ಸರಕುಪಟ್ಟಿಗಳು (Invoices) ಸೇರಿದಂತೆ ಅಗತ್ಯ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು. ಸಲ್ಲಿಸಲಾದ ಎಲ್ಲಾ ಹಕ್ಕು ಮಂಡನೆಗಳು (Claims) ಸರ್ಕಾರದ ಪರಿಶೀಲನೆಗೆ ಒಳಪಡುತ್ತವೆ."]', '["ಅರ್ಜಿದಾರ ಕಂಪನಿಯು GCC ನೀತಿಯಡಿ ಕರ್ನಾಟಕ ನವೋದ್ಯಮ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ಯಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["ಉದ್ಯೋಗಿಗಳು ಪಡೆದಿರುವ ತರಬೇತಿ ಕಾರ್ಯಕ್ರಮಗಳು ಹಾಗೂ ಅವುಗಳ ಅವಧಿಯ ವಿವರವಾದ ಪ್ರಸ್ತಾವನೆ, ಇದರಲ್ಲಿ ಕೌಶಲ್ಯಾಭಿವೃದ್ಧಿ ಕಾರ್ಯಕ್ರಮದ ವಿನ್ಯಾಸ (ತರಬೇತಿ ಕ್ಷೇತ್ರಗಳು (Domains), ತರಬೇತಿಯ ಅವಧಿ ಹಾಗೂ ಗುರಿ ಗುಂಪುಗಳು (Target Groups)) ಒಳಗೊಂಡಿರಬೇಕು.", "ii. ವಿವರವಾದ ಬಜೆಟ್ ಹಾಗೂ ಹಣಕಾಸು ಯೋಜನೆ (Budget and Funding Plan).", "iii. ತರಬೇತಿ ಮೂಲಸೌಕರ್ಯ ಹಾಗೂ ಅನುಷ್ಠಾನ ಮಾದರಿ (Infrastructure and Delivery Model).", "iv. ಮೇಲ್ವಿಚಾರಣೆ ಮತ್ತು ಫಲಿತಾಂಶ ಮೌಲ್ಯಮಾಪನ ಯೋಜನೆ (Monitoring and Outcome Evaluation Plan), ಇದರಲ್ಲಿ ಮೌಲ್ಯಮಾಪನ (Assessments) ಹಾಗೂ ಪ್ರಮಾಣೀಕರಣಗಳ (Certifications) ವಿವರಗಳು ಒಳಗೊಂಡಿರಬೇಕು.", "v. ಸಹಭಾಗಿ ಸಂಸ್ಥೆಗಳಿಂದ (Partner Institutions) ನೀಡಲಾದ ಬೆಂಬಲ ಪತ್ರಗಳ (Letters of Support) ಪ್ರತಿಗಳು.", "vi. ತರಬೇತಿ ಪಡೆಯುತ್ತಿರುವ ಹೊಸದಾಗಿ ನೇಮಕಗೊಂಡ ಉದ್ಯೋಗಿಗಳು ಕರ್ನಾಟಕದಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿದ್ದಾರೆ ಎಂಬುದನ್ನು ದೃಢೀಕರಿಸುವ ಸಂಸ್ಥೆಯ ಅಧಿಕೃತ ಲೆಟರ್"]', NULL, NULL, '3390');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('e4f09bf2-25ff-473e-98d1-a2f5b88032ca', 'DEPARTMENT-OF-ELECTR-31', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Host Events and Conferences', 'General', 60, 'GoK will provide funding for hosting R&D events and conferences in Karnataka to foster knowledge exchange and collaboration.', '["i. Detailed concept note of the event with the proposed theme, agenda and expected outcome", "ii. Proof of payment incurred towards organizing the event, along with event brochures, participation reports, complete registration details (name, designation, company, email and phone numbers of the participants/ speakers who have participated in the event media coverage etc.,", "iii. Post Event Report (impact, outcomes, event photographs)", "iv. A letter or statement issued by a Chartered Accountant (CA) certifying the expenses incurred by the applicant, along with a certificate and copy of invoices/ proof of payments, clearly stating the amount received through income generated from sponsorships, registrations, participation fees, and other sources."]', '["Applicable to GCC’s & Industry Associations across the state.", "Application should be submitted within six months from the date of event/ conferences.", "Supporting documents including (but limited to) copy of invite, invoices, payment proof, booking confirmation, statement of expenses certified by CA, event completion/ status report shall be submitted along with the application.", "Applicants are encouraged to collaborate with industry bodies, GCCs and State Government education institutes etc to enhance the visibility of the event.", "The event must focus on strategic themes like GCCs, Emerging Technologies, addressing current industry challenges and promoting adaptability, especially with AI.", "A minimum of 10 CXO-level speakers and participation from at least 25 diverse organizations is required, with national/international reach preferred."]', '[]', '["The applicant Company should be registered with KITS under GCC Policy 2024-29", "Company should submit the incentive application along with supporting documents as prescribed in the OPG."]', NULL, NULL, 'https://registration.eitbt.karnataka.gov.in/gcc/hosting-events-conferences', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಕಾರ್ಯಕ್ರಮಗಳ ಮತ್ತು ಸಮ್ಮೇಳನಗಳ ಆಯೋಜನೆ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ಜ್ಞಾನ ವಿನಿಮಯ ಮತ್ತು ಸಹಯೋಗವನ್ನು ಉತ್ತೇಜಿಸಲು ಕರ್ನಾಟಕದಲ್ಲಿ ಆರ್', NULL, NULL, NULL, NULL, NULL, '["ರಾಜ್ಯದಾದ್ಯಂತ ಇರುವ ಜಾಗತಿಕ ಸಾಮರ್ಥ್ಯ ಕೇಂದ್ರಗಳು (GCCs) ಹಾಗೂ ಕೈಗಾರಿಕಾ ಸಂಘಗಳಿಗೆ (Industry Associations) ಅನ್ವಯಿಸುತ್ತದೆ.", "ಕಾರ್ಯಕ್ರಮ/ಸಮ್ಮೇಳನ ನಡೆದ ದಿನಾಂಕದಿಂದ ಆರು (6) ತಿಂಗಳೊಳಗೆ ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಬೇಕು.", "ಅರ್ಜಿಯೊಂದಿಗೆ ಕಾರ್ಯಕ್ರಮಕ್ಕೆ ಸಂಬಂಧಿಸಿದ ಪೂರಕ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು. ಅವುಗಳಲ್ಲಿ ಆಹ್ವಾನ ಪತ್ರದ ಪ್ರತಿ, ಸರಕುಪಟ್ಟಿಗಳು (Invoices), ಪಾವತಿ ಪುರಾವೆಗಳು, ಬುಕ್ಕಿಂಗ್ ದೃಢೀಕರಣ, ಚಾರ್ಟರ್ಡ್ ಅಕೌಂಟೆಂಟ್ (CA) ದೃಢೀಕರಿಸಿದ ವೆಚ್ಚಗಳ ವಿವರ, ಕಾರ್ಯಕ್ರಮ ಪೂರ್ಣಗೊಂಡಿರುವ/ಸ್ಥಿತಿ ವರದಿ ಇತ್ಯಾದಿಗಳು (ಇವುಗಳಿಗೆ ಮಾತ್ರ ಸೀಮಿತವಾಗಿರುವುದಿಲ್ಲ) ಒಳಗೊಂಡಿರಬೇಕು.", "ಕಾರ್ಯಕ್ರಮದ ವ್ಯಾಪ್ತಿ ಮತ್ತು ಪ್ರಚಾರವನ್ನು ಹೆಚ್ಚಿಸುವ ಉದ್ದೇಶದಿಂದ ಕೈಗಾರಿಕಾ ಸಂಘಗಳು, ಜಾಗತಿಕ ಸಾಮರ್ಥ್ಯ ಕೇಂದ್ರಗಳು (GCCs), ರಾಜ್ಯ ಸರ್ಕಾರದ ಶೈಕ್ಷಣಿಕ ಸಂಸ್ಥೆಗಳು ಹಾಗೂ ಇತರೆ ಸಂಬಂಧಿತ ಸಂಸ್ಥೆಗಳೊಂದಿಗೆ ಸಹಭಾಗಿತ್ವದಲ್ಲಿ ಕಾರ್ಯಕ್ರಮಗಳನ್ನು ಆಯೋಜಿಸಲು ಅರ್ಜಿದಾರರನ್ನು ಪ್ರೋತ್ಸಾಹಿಸಲಾಗುತ್ತದೆ.", "ಕಾರ್ಯಕ್ರಮವು ಜಾಗತಿಕ ಸಾಮರ್ಥ್ಯ ಕೇಂದ್ರಗಳು (GCCs), ಉದಯೋನ್ಮುಖ ತಂತ್ರಜ್ಞಾನಗಳು (Emerging Technologies), ಪ್ರಸ್ತುತ ಕೈಗಾರಿಕಾ ಸವಾಲುಗಳನ್ನು ಪರಿಹರಿಸುವುದು ಹಾಗೂ ವಿಶೇಷವಾಗಿ ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ (AI) ಕ್ಷೇತ್ರದಲ್ಲಿ ಹೊಂದಾಣಿಕೆ ಸಾಮರ್ಥ್ಯವನ್ನು ಉತ್ತೇಜಿಸುವಂತಹ ಕಾರ್ಯತಂತ್ರದ ವಿಷಯಗಳ ಮೇಲೆ ಕೇಂದ್ರೀಕೃತವಾಗಿರಬೇಕು.", "ಕಾರ್ಯಕ್ರಮದಲ್ಲಿ ಕನಿಷ್ಠ 10 ಮುಖ್ಯ ಕಾರ್ಯನಿರ್ವಾಹಕ ಅಧಿಕಾರಿ (CXO) ಮಟ್ಟದ ಭಾಷಣಕಾರರು ಭಾಗವಹಿಸಬೇಕು ಹಾಗೂ ಕನಿಷ್ಠ 25 ವಿಭಿನ್ನ ಸಂಸ್ಥೆಗಳ ಭಾಗವಹಿಸುವಿಕೆ ಇರಬೇಕು. ರಾಷ್ಟ್ರೀಯ ಅಥವಾ ಅಂತರರಾಷ್ಟ್ರೀಯ ಮಟ್ಟದ ಭಾಗವಹಿಸುವಿಕೆಗೆ ಆದ್ಯತೆ ನೀಡಲಾಗುತ್ತದೆ."]', '["ಅರ್ಜಿದಾರ ಕಂಪನಿಯು GCC ನೀತಿಯಡಿ ಕರ್ನಾಟಕ ನವೋದ್ಯಮ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ಯಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["i. ಕಾರ್ಯಕ್ರಮದ ಪ್ರಸ್ತಾವಿತ ವಿಷಯ (Theme), ಕಾರ್ಯಸೂಚಿ (Agenda) ಹಾಗೂ ನಿರೀಕ್ಷಿತ ಫಲಿತಾಂಶಗಳನ್ನು ಒಳಗೊಂಡ ಕಾರ್ಯಕ್ರಮದ ವಿವರವಾದ ಪರಿಕಲ್ಪನಾ ಟಿಪ್ಪಣಿ (Concept Note).", "ii. ಕಾರ್ಯಕ್ರಮ ಆಯೋಜನೆಗೆ ಸಂಬಂಧಿಸಿದ ವೆಚ್ಚಗಳ ಪಾವತಿ ಪುರಾವೆಗಳು, ಕಾರ್ಯಕ್ರಮದ ಕರಪತ್ರಗಳು (Event Brochures), ಭಾಗವಹಿಸುವಿಕೆ ವರದಿಗಳು, ಭಾಗವಹಿಸಿದ ಪ್ರತಿನಿಧಿಗಳು/ಭಾಷಣಕಾರರ ಸಂಪೂರ್ಣ ನೋಂದಣಿ ವಿವರಗಳು (ಹೆಸರು, ಹುದ್ದೆ, ಸಂಸ್ಥೆ, ಇ-ಮೇಲ್ ವಿಳಾಸ ಹಾಗೂ ದೂರವಾಣಿ ಸಂಖ್ಯೆ), ಕಾರ್ಯಕ್ರಮಕ್ಕೆ ಸಂಬಂಧಿಸಿದ ಮಾಧ್ಯಮ ವರದಿಗಳು ಹಾಗೂ ಇತರೆ ಸಂಬಂಧಿತ ದಾಖಲೆಗಳ ಪ್ರತಿಗಳು.", "iii. ಕಾರ್ಯಕ್ರಮೋತ್ತರ ವರದಿ (Post Event Report), ಇದರಲ್ಲಿ ಕಾರ್ಯಕ್ರಮದ ಪರಿಣಾಮ, ಫಲಿತಾಂಶಗಳು ಹಾಗೂ ಕಾರ್ಯಕ್ರಮದ ಛಾಯಾಚಿತ್ರಗಳು ಒಳಗೊಂಡಿರಬೇಕು.", "iv. ಅರ್ಜಿದಾರರು ಕಾರ್ಯಕ್ರಮ ಆಯೋಜನೆಗೆ ಭರಿಸಿದ ವೆಚ್ಚಗಳನ್ನು ದೃಢೀಕರಿಸುವ ಚಾರ್ಟರ್ಡ್ ಅಕೌಂಟೆಂಟ್ (CA) ನೀಡಿದ ಪ್ರಮಾಣಪತ್ರ/ಪತ್ರ, ಜೊತೆಗೆ ಸಂಬಂಧಿತ ಸರಕುಪಟ್ಟಿಗಳ (Invoices) ಹಾಗೂ ಪಾವತಿ ಪುರಾವೆಗಳ ಪ್ರತಿಗಳು. ಇದಲ್ಲದೆ, ಪ್ರಾಯೋಜಕತ್ವ (Sponsorship), ನೋಂದಣಿ ಶುಲ್ಕ (Registration Fee), ಭಾಗವಹಿಸುವಿಕೆ ಶುಲ್ಕ (Participation Fee) ಹಾಗೂ ಇತರೆ ಮೂಲಗಳಿಂದ ಪಡೆದ ಆದಾಯದ ವಿವರವನ್ನು ಸ್ಪಷ್ಟವಾಗಿ ಉಲ್ಲೇಖಿಸಿರಬೇಕು."]', NULL, NULL, '3326');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('11f19ec1-90e7-4c57-8f8a-72cdda71ed76', 'REVENUE-DEPARTMENT-116', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'FORM NO.10', 'General', 0, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (FORM NO.10)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಫಾರಂ ನಂ 10', NULL, NULL, NULL, NULL, NULL, 20.00, NULL, 'ಫಾರಂ ನಂ 10 ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3126');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('a39214d1-5793-4330-badc-fdb3c46fe7fb', 'EDUCATION-DEPARTMENT-1', 'bd235dfc-9efa-4507-aaf0-f78a93e05e6a', 'SSLC DPC TPC QPC Marks Card and Fail Marks Card With DOB', 'Certificate', 0, 'Candidates who wish to get S.S.L.C Duplicate Marks Card (Second, Third and Fourth Marks Copy of Marks Card) and Fail Marks Card can apply through online', '["The Application sent by the applicant must be addressed to “Secretary, Karnataka School Examination and Assessment Board …………Division”", "Copy of Affidavit", "Copy of Marks Card if he/she is having the same", "Aadhar Card"]', '["SSLC Pass & Fail students"]', '[]', '["KSEAB Website → Online Services → SSLC → DPC/TPC/QPC → Fill Application → Upload Documents → Pay Fee → Submit → Receive Marks Card.", "KSEAB Website → Online Services → SSLC → DPC/TPC/QPC & Fail Marks Card → Select Fail Marks Card → Fill Application → Upload Documents → Pay Fee → Submit → Receive Marks Card."]', NULL, NULL, 'https://kseeb.karnataka.gov.in/DuplicateMarksCard/', true, '2026-10-30 16:55:56.458552+00', 'e61a6e68-d61f-4782-a4e6-388fca3e3652', 'ಎಸ್ ಎಸ್ ಎಲ್ ಸಿ ದ್ವಿತೀಯ ತೃತೀಯ ನಾಲ್ಕನೇ ಅಂಕಪಟ್ಟಿ ಮತ್ತು ಜನ್ಮ ದಿನಾಂಕ ಸಹಿತ ಅನುತ್ತೀರ್ಣ ಅಂಕಪಟ್ಟಿ', 'Candidates who wish to get S.S.L.C Duplicate Marks Card (Second, Third and Fourth Marks Copy of Marks Card) and Fail Marks Card can apply through online', NULL, 'Urban & Rural', NULL, NULL, NULL, NULL, 'ಎಸ್', NULL, NULL, NULL, true, 'YES', '["ಎಸ್"]', '["KSEAB ವೆಬ್"]', 1, '["ಅಭ‍್ಯರ್ಥಿಯು “ಕಾರ್ಯದರ್ಶಿಗಳು, ಕರ್ನಾಟಕ ಶಾಲಾ ಪರೀಕ್ಷೆ ಮತ್ತು ಮೌಲ್ಯನಿರ್ಣಯ ಮಂಡಲಿ, ………………………… ವಿಭಾಗ” ರವರಿಗೆ ಬರೆದಿರುವ ಅರ್ಜಿ.", "ಅಫಿಡವಿಟ್‍ ಪ್ರತಿ", "ಅಂಕಪಟ್ಟಿಯ ಪ್ರತಿ ಇದ್ದಲ್ಲಿ", "ಆಧಾರ್ ಕಾರ್ಡ್"]', NULL, NULL, '3429');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('b452c103-5e6c-489e-bcba-60fdefaaeb5e', 'EDUCATION-DEPARTMENT-2', 'bd235dfc-9efa-4507-aaf0-f78a93e05e6a', 'SSLC Marks card correction', 'Certificate', 0, 'Regarding corrections in the candidates’ marks cards, such as the candidate’s name, father’s name, mother’s name, date of birth, gender, etc., a proposal shall be submitted to the concerned Divisional Office along with the relevant extract from the school records (Admission Register Extract) obtained from the Block Education Officer and the memorandum.', '["Request letter from the Headmaster/Headmistress.", "Official memorandum regarding the correction obtained from the Taluk Block Education Officer.", "A3-size copy of the Primary and High School Admission Register, duly certified by the Headmaster/Headmistress and the Block Education Officer.", "Certified copies of the Transfer Certificates of the Primary and High School where the candidate has studied, duly certified by the Headmaster/Headmistress and the Block Education Officer.", "Original SSLC Marks Card of the candidate."]', '["SSLC Pass students"]', '[]', '["Student → Approach the respective school → HM logs in through the school login → Select SSLC Marks Card Correction → Select the required correction → Upload the required documents → Pay the prescribed fee → Submit the application → Application will be processed.", "Note: The student cannot apply individually. The Headmaster (HM) has to submit the application through the school login on behalf of the student"]', NULL, NULL, 'https://kseeb.karnataka.gov.in/SCHOOLLOGIN/Views/LoginPage.aspx', true, '2026-10-30 16:55:56.458552+00', 'e61a6e68-d61f-4782-a4e6-388fca3e3652', 'ಅಂಕಪಟ್ಟಿ ತಿದ್ದುಪಡಿ', 'Regarding corrections in the candidates’ marks cards, such as the candidate’s name, father’s name, mother’s name, date of birth, gender, etc., a proposal shall be submitted to the concerned Divisional Office along with the relevant extract from the school records (Admission Register Extract) obtained from the Block Education Officer and the memorandum.', NULL, 'Urban & Rural', NULL, NULL, NULL, NULL, 'ಅಭ್ಯರ್ಥಿಗಳ ಅಂಕಪಟ್ಟಿಯಲ್ಲಿ ಅಭ್ಯರ್ಥಿಯ ಹೆಸರು, ತಂದೆಯ ಹೆಸರು, ತಾಯಿ ಹೆಸರು, ಜನ್ಮದಿನಾಂಕ, Gender ಇತ್ಯಾದಿ ತಿದ್ದುಪಡಿ ಸಂಬಂಧ ಪ್ರಸ್ತಾವನೆಯನ್ನು ಕ್ಷೇತ್ರ ಶಿಕ್ಷಣಾಧಿಕಾರಿಗಳಿಂದ ಪಡೆದ ಶಾಲಾ ದಾಖಲಾತಿಯ ಉದ್ದೃತಭಾಗ (Admission Register Extract) ಹಾಗೂ ಜ್ಞಾಪನದೊಂದಿಗೆ ಆಯಾ ವಿಭಾಗೀಯ ಕಚೇರಿಗೆ ಪ್ರಸ್ತಾವನೆಯನ್ನು ಸಲ್ಲಿಸಬೇಕಾಗುತ್ತದೆ.', NULL, NULL, NULL, false, 'NO', '["ಎಸ್"]', '["ವಿದ್ಯಾರ್ಥಿ → ಸಂಬಂಧಿತ ಶಾಲೆಯನ್ನು ಸಂಪರ್ಕಿಸಬೇಕು → HM ಶಾಲೆಯ ಲಾಗಿನ್ ಮೂಲಕ Login ಮಾಡಬೇಕು → SSLC ಅಂಕಪಟ್ಟಿ ತಿದ್ದುಪಡಿ ಆಯ್ಕೆ ಮಾಡಬೇಕು → ಅಗತ್ಯವಿರುವ ತಿದ್ದುಪಡಿಯನ್ನು ಆಯ್ಕೆ ಮಾಡಬೇಕು → ಅಗತ್ಯ ದಾಖಲೆಗಳನ್ನು Upload ಮಾಡಬೇಕು → ನಿಗದಿತ ಶುಲ್ಕವನ್ನು ಪಾವತಿಸಬೇಕು → ಅರ್ಜಿಯನ್ನು Submit ಮಾಡಬೇಕು → ಅರ್ಜಿಯನ್ನು ಪ್ರಕ್ರಿಯೆಗೊಳಿಸಲಾಗುತ್ತದೆ.", "ಮುಖ್ಯ ಸೂಚನೆ: ವಿದ್ಯಾರ್ಥಿಯು ವೈಯಕ್ತಿಕವಾಗಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ. ವಿದ್ಯಾರ್ಥಿಯ ಪರವಾಗಿ HM ಅವರು ಶಾಲೆಯ ಲಾಗಿನ್ ಮೂಲಕ ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["ಮುಖ್ಯಶಿಕ್ಷಕರ ಕೋರಿಕೆ ಪತ್ರ.", "ತಾಲ್ಲೂಕು ಕ್ಷೇತ್ರ ಶಿಕ್ಷಣಾಧಿಕಾರಿಗಳಿಂದ ತಿದ್ದುಪಡಿಯ ಬಗ್ಗೆ ಪಡೆದಿರುವ ಅಧಿಕೃತ ಜ್ಞಾಪನ ಪತ್ರ.", "ಮುಖ್ಯಶಿಕ್ಷಕರು ಹಾಗೂ ಕ್ಷೇತ್ರ ಶಿಕ್ಷಣಾಧಿಕಾರಿಗಳು ದೃಢೀಕರಿಸಿರುವ ಪ್ರಾಥಮಿಕ ಮತ್ತು ಪ್ರೌಢಶಾಲಾ ದಾಖಲಾತಿ ವಹಿಯ A3 ಅಳತೆಯ ಪ್ರತಿ.", "ಮುಖ್ಯಶಿಕ್ಷಕರು ಹಾಗೂ ಕ್ಷೇತ್ರ ಶಿಕ್ಷಣಾಧಿಕಾರಿಗಳು ದೃಢೀಕರಿಸಿರುವ ಅಭ್ಯರ್ಥಿಯು ವ್ಯಾಸಂಗ ಮಾಡಿರುವಂತಹ ಪ್ರಾಥಮಿಕ ಹಾಗೂ ಪ್ರೌಢಶಾಲಾ ವರ್ಗಾವಣಾ ಪತ್ರಗಳ ದೃಢೀಕೃತ ಪ್ರತಿಗಳು.", "ಅಭ್ಯರ್ಥಿಯ ಮೂಲ ಎಸ್.ಎಸ್.ಎಲ್.ಸಿ. ಅಂಕಪಟ್ಟಿ."]', NULL, NULL, '3430');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('b9ec303c-3a02-441e-8b85-bdadaa08968b', 'REVENUE-DEPARTMENT-118', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', '2ND RECLASS TIPPAN BOOK', 'General', 0, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (2ND RECLASS TIPPAN BOOK)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'ಎರಡನೇ ರೀಕ್ಲಾಸಿಫಿಕೇಷನ್ ಟಿಪ್ಪಣಿ ಪುಸ್ತಕ', NULL, NULL, NULL, NULL, NULL, 35.00, NULL, 'ಎರಡನೇ ರೀಕ್ಲಾಸಿಫಿಕೇಷನ್ ಟಿಪ್ಪಣಿ ಪುಸ್ತಕ ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3129');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('739e55a3-5d8e-40b6-85bf-587a77deb5de', 'EDUCATION-DEPARTMENT-3', 'bd235dfc-9efa-4507-aaf0-f78a93e05e6a', 'SSLC Migration Certificate', 'Certificate', 0, 'Candidates who have passed the SSLC examination from 2003 can obtain Migration certificate online in order to continue their study in other states. 
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('25cef19c-96f3-4f8a-ac37-e454d818deda', 'EDUCATION-DEPARTMENT-4', 'bd235dfc-9efa-4507-aaf0-f78a93e05e6a', 'SSLC Marks card Verification', 'Certificate', 0, 'Only the marks cards of candidates who have passed the SSLC examination should be submitted for verification of authenticity.', '["The Application sent by the appointing authority/designated authority/ Individuals directed by the institutions must be addressed to “Director (Exams), Karnataka School Examination and Assessment Board, 6th Cross, Malleshwaram, Bangalore - 560003”", "The appointment order/related document of the candidate.", "Marks card of the candidate"]', '["SSLC Pass students"]', '[]', '["KSEAB Website → Online Services → SSLC → Marks Card Verification → Fill Application → Upload Documents → Pay Fee → Submit → Verification will be done by the divisional offices.", "Note: This service is for passed SSLC candidates only, and the proposal must be submitted by the appointing/designated authority or an individual directed by the institution, not by the candidate individually.", "But for civil avaition category, the students can apply by themselves by providing covering letter & public notice"]', NULL, NULL, 'https://kseeb.karnataka.gov.in/MarkscardVerification/', true, '2026-10-30 16:55:56.458552+00', 'e61a6e68-d61f-4782-a4e6-388fca3e3652', 'ಎಸ್ ಎಸ್ ಎಲ್ ಸಿ ಅಂಕಪಟ್ಟಿ ನೈಜತೆ ಪರಿಶೀಲನೆ', 'Only the marks cards of candidates who have passed the SSLC examination should be submitted for verification of authenticity.', NULL, 'Urban & Rural', NULL, NULL, NULL, NULL, 'ಎಸ್‍.ಎಸ್‍.ಎಲ್‍.ಸಿ ಪರೀಕ್ಷೆಯಲ್ಲಿ ಉತ್ತೀರ್ಣರಾದ ಅಭ್ಯರ್ಥಿಗಳ ಅಂಕಪಟ್ಟಿಗಳನ್ನು ಮಾತ್ರ ನೈಜತೆಗಾಗಿ ಸಲ್ಲಿಸುವುದು.', NULL, NULL, NULL, true, 'YES', '["ಎಸ್"]', '["KSEAB ವೆಬ್"]', 1, '["ನೇಮಕಾತಿ ಪ್ರಾಧಿಕಾರ / ನಿಯೋಜಿತ ಪ್ರಾಧಿಕಾರ/ ಸಂಸ್ಥೆಗಳಿಂದ ನಿರ್ದೇಶಿಸಲ್ಪಟ್ಟ ಅಭ್ಯರ್ಥಿಗಳು ”ನಿರ್ದೇಶಕರು (ಪರೀಕ್ಷೆಗಳು), ಕರ್ನಾಟಕ ಶಾಲಾ ಪರೀಕ್ಷೆ ಮತ್ತು ಮೌಲ್ಯನಿರ್ಣಯ ಮಂಡಲಿ, 6ನೇ ಅಡ್ಡರಸ್ತೆ, ಮಲ್ಲೇಶ್ವರಂ, ಬೆಂಗಳೂರು - 560003” ರವರಿಗೆ ಬರೆದಿರುವ ಅರ್ಜಿ.", "ಅಭ್ಯರ್ಥಿಯ ನೇಮಕಾತಿ ಆದೇಶ ಪತ್ರ / ಸಂಬಂಧಿಸಿದ ದಾಖಲೆ.", "ಅಭ್ಯರ್ಥಿಯ ಅಂಕಪಟ್ಟಿ"]', NULL, NULL, '3432');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('c862494f-8260-43d2-8ed0-477a5f05cc6c', 'EDUCATION-DEPARTMENT-8', 'bd235dfc-9efa-4507-aaf0-f78a93e05e6a', 'Issuing Duplicate Markscard General case other exams (Commerce Exam, Arabic Exam , D Ed Exam , KOS Exam , PPT Exam, D P Ed Exam, Music Exam, Drawing Grade Exam, Film Acting Exam)', 'Markscards and Certificate', 0, 'Candidates who wish to get Duplicate Marks Card (Second, Third and Fourth Marks Copy of Marks Card)', '["The Application sent by the applicant must be addressed to “Secretary, Karnataka School Examination and Assessment Board …………Division” Request Letter", "Copy of Affidavit", "Copy of Marks Card if he/she is having the same", "Aadhar Card"]', '["Passed Candidates"]', '[]', '["KSEAB Website → Online Services → other Exams → DPC/TPC/QPC → Fill Application → Upload Documents → Pay Fee → Submit → Receive Marks Card."]', NULL, NULL, 'https://kseeb.karnataka.gov.in/otherexamwebservice2/', true, '2026-10-30 16:55:56.458552+00', 'e61a6e68-d61f-4782-a4e6-388fca3e3652', 'ಇತರೆ ಪರೀಕ್ಷೆಗಳ ಅಂಕಪಟ್ಟಿಯ ನಕಲು ಪ್ರತಿ ಸಾಮಾನ್ಯ ಪ್ರಕರಣ (Commerce Exam, Arabic Exam , D Ed Exam , KOS Exam , PPT Exam, D P Ed Exam, Music Exam, Drawing Grade Exam, Film Acting Exam)', 'Candidates who wish to get Duplicate Marks Card (Second, Third and Fourth Marks Copy of Marks Card)', NULL, 'Urban & Rural', NULL, NULL, NULL, NULL, 'ಮೂಲ ಅಂಕಪಟ್ಟಿ ಕಳೆದುಕೊಂಡ ಅಭ್ಯರ್ಥಿಗಳು ದ್ವಿತೀಯ/ತೃತೀಯ/ನಾಲ್ಕನೇ ಪ್ರತಿಯ ಅಂಕಪಟ್ಟಿಗಾಗಿ ಆನ್ ಲೈನ್ ಮೂಲಕ ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದಾಗಿದೆ.', NULL, NULL, NULL, true, 'YES', '["ಉತ್ತೀರ್ಣರಾದ ಅಭ್ಯರ್ಥಿಗಳು"]', '["KSEAB ವೆಬ್"]', 1, '["ಅಭ‍್ಯರ್ಥಿಯು “ಕಾರ್ಯದರ್ಶಿಗಳು, ಕರ್ನಾಟಕ ಶಾಲಾ ಪರೀಕ್ಷೆ ಮತ್ತು ಮೌಲ್ಯನಿರ್ಣಯ ಮಂಡಲಿ, ………………………… ವಿಭಾಗ” ರವರಿಗೆ ಬರೆದಿರುವ ಅರ್ಜಿ.", "ಅಫಿಡವಿಟ್‍ ಪ್ರತಿ", "ಅಂಕಪಟ್ಟಿಯ ಪ್ರತಿ ಇದ್ದಲ್ಲಿ", "ಆಧಾರ್ ಕಾರ್ಡ್"]', NULL, NULL, '3436');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('9ce2420b-b80a-41f2-92fe-dc401f6b4bf1', 'EDUCATION-DEPARTMENT-9', 'bd235dfc-9efa-4507-aaf0-f78a93e05e6a', 'KOS Migration Certificate', 'Certificate', 0, 'Candidates who have passed the KOS examination from 2003 can obtain Migration certificate online in order to continue their study in other states. 
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('bdb629d0-bc97-4d7b-812a-e044d7aca159', 'EDUCATION-DEPARTMENT-10', 'bd235dfc-9efa-4507-aaf0-f78a93e05e6a', 'Photocopy of Answer scripts other examination (Commerce Exam, Arabic Exam , D Ed Exam , KOS Exam , D P Ed Exam, Drawing Grade Exam, Film Acting Exam)', 'Scanned Answer Script', 0, 'After the results are announced, Candidates can apply for a photocopy of their answer scripts using their Register Number. This allows them to review their answers and verify the marks given.', '["Register Number"]', '["Students who has written exams"]', '[]', '["KSEAB Website → Online Services →Other Exams → Photocopy/Scanned Copy of Answer Script → Enter Register Number → Select Subject(s) → Pay the prescribed fee → Submit Application → Receive SMS when the answer script is uploaded → Download the scanned answer script."]', NULL, NULL, 'https://kseeb.karnataka.gov.in/OtherExamPHRVonline/', true, '2026-10-30 16:55:56.458552+00', 'e61a6e68-d61f-4782-a4e6-388fca3e3652', 'ಉತ್ತರ ಪತ್ರಿಕೆಗಳ ಛಾಯಾಪ್ರತಿ ಇತರೆ ಪರೀಕ್ಷೆಗಳು(Commerce Exam, Arabic Exam , D Ed Exam , KOS Exam , D P Ed Exam, Drawing Grade Exam, Film Acting Exam)', 'After the results are announced, Candidates can apply for a photocopy of their answer scripts using their Register Number. This allows them to review their answers and verify the marks given.', NULL, 'Urban & Rural', NULL, NULL, 500.00, NULL, 'ಫಲಿತಾಂಶ ಪ್ರಕಟವಾದ ನಂತರ, ಅಭ್ಯರ್ಥಿಗಳು ತಮ್ಮ ನೋಂದಣಿ ಸಂಖ್ಯೆಯನ್ನು (Register Number) ಬಳಸಿ ಉತ್ತರ ಪತ್ರಿಕೆಯ ಛಾಯಾಪ್ರತಿಗಾಗಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು. ಇದರ ಮೂಲಕ ವಿದ್ಯಾರ್ಥಿಗಳು ತಮ್ಮ ಉತ್ತರಗಳನ್ನು ಪರಿಶೀಲಿಸಿ, ನೀಡಲಾಗಿರುವ ಅಂಕಗಳನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಬಹುದು.', NULL, NULL, NULL, true, 'YES', '["ಪರೀಕ್ಷೆ ಬರೆದ ವಿದ್ಯಾರ್ಥಿಗಳು"]', '["KSEAB ವೆಬ್"]', 1, '["ನೋಂದಣಿ ಸಂಖ್ಯೆ"]', NULL, NULL, '3440');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('bbcfe621-77e7-43e7-a575-5bafa8dfa83b', 'EDUCATION-DEPARTMENT-11', 'bd235dfc-9efa-4507-aaf0-f78a93e05e6a', 'Revaluation of Answer scripts other examination (Commerce Exam, Arabic Exam , D Ed Exam , KOS Exam , D P Ed Exam, Drawing Grade Exam, Film Acting Exam)', 'Revaluation of Answer script', 0, 'After receiving the photocopy of the answer script, Candidates may apply for revaluation, if they wish to have their marks re-evaluated, using their Register Number.', '["Register Number"]', '["Students who has written exams in that particular academic year"]', '[]', '["KSEAB Website → Online Services →Other Exams → Get Scanned Answer Script → Check Answers & Marks → Apply for Revaluation → Enter Register Number → Select Subject(s) → Pay Fee → Submit → Revaluation Result/Updated Marks."]', NULL, NULL, 'https://kseeb.karnataka.gov.in/OtherExamPHRVonline/', true, '2026-10-30 16:55:56.458552+00', 'e61a6e68-d61f-4782-a4e6-388fca3e3652', 'ಉತ್ತರ ಪತ್ರಿಕೆಗಳ ಮರುಮೌಲ್ಯಮಾಪನ ಇತರೆ ಪರೀಕ್ಷೆಗಳು (Commerce Exam, Arabic Exam , D Ed Exam , KOS Exam , D P Ed Exam, Drawing Grade Exam, Film Acting Exam)', 'After receiving the photocopy of the answer script, Candidates may apply for revaluation, if they wish to have their marks re-evaluated, using their Register Number.', NULL, 'Urban & Rural', NULL, NULL, 800.00, NULL, 'ಉತ್ತರ ಪತ್ರಿಕೆಯ ಛಾಯಾಪ್ರತಿಯನ್ನು ಪಡೆದ ನಂತರ, ಅಭ್ಯರ್ಥಿಗಳು ತಮ್ಮ ಅಂಕಗಳನ್ನು ಮರುಪರಿಶೀಲಿಸಲು ಬಯಸಿದಲ್ಲಿ, ತಮ್ಮ ನೋಂದಣಿ ಸಂಖ್ಯೆಯನ್ನು (Register Number) ಬಳಸಿ ಮರುಮೌಲ್ಯಮಾಪನಕ್ಕೆ (Revaluation) ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು.', NULL, NULL, NULL, true, 'YES', '["ಶೈಕ್ಷಣಿಕ ವರ್ಷದಲ್ಲಿ ಪರೀಕ್ಷೆ ಬರೆದ ವಿದ್ಯಾರ್ಥಿಗಳು"]', '["KSEAB ವೆಬ್"]', 1, '["ನೋಂದಣಿ ಸಂಖ್ಯೆ"]', NULL, NULL, '3441');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('f5594e47-01ef-4973-b0b2-55048fd395f4', 'EDUCATION-DEPARTMENT-12', 'bd235dfc-9efa-4507-aaf0-f78a93e05e6a', 'Retotaling of Marks Secured other examination (Commerce Exam, Arabic Exam , D Ed Exam , KOS Exam , D P Ed Exam, Drawing Grade Exam, Film Acting Exam)', 'Re-totaling of Answer script', 0, 'After receiving the photocopy of the answer script, Candidates may apply for re-totalling if they find any discrepancy in the calculation of their marks, using their Register Number.', '["Register Number"]', '["Students who has written exams"]', '[]', '["KSEAB Website → Online Services →Other Exams → Get Scanned Answer Script → Check Answers & Marks → Apply for Re-totaling → Enter Register Number → Select Subject(s) → Pay Fee → Submit → Re-totaling Result/Updated Marks."]', NULL, NULL, 'https://kseeb.karnataka.gov.in/OtherExamPHRVonline/', true, '2026-10-30 16:55:56.458552+00', 'e61a6e68-d61f-4782-a4e6-388fca3e3652', 'ಪರೀಕ್ಷೆಗಳಲ್ಲಿ ಗಳಿಸಿದ ಅಂಕಗಳ ಮರುಎಣಿಕೆ ಇತರೆ ಪರೀಕ್ಷೆಗಳು (Commerce Exam, Arabic Exam , D Ed Exam , KOS Exam , D P Ed Exam, Drawing Grade Exam, Film Acting Exam)', 'After receiving the photocopy of the answer script, Candidates may apply for re-totalling if they find any discrepancy in the calculation of their marks, using their Register Number.', NULL, 'Urban & Rural', NULL, NULL, 150.00, NULL, 'ಉತ್ತರ ಪತ್ರಿಕೆಯ ಛಾಯಾಪ್ರತಿಯನ್ನು ಪಡೆದ ನಂತರ, ಅಂಕಗಳ ಮೊತ್ತದ ಲೆಕ್ಕಾಚಾರದಲ್ಲಿ ಯಾವುದೇ ವ್ಯತ್ಯಾಸ ಕಂಡುಬಂದಲ್ಲಿ, ಅಭ್ಯರ್ಥಿಗಳು ತಮ್ಮ ನೋಂದಣಿ ಸಂಖ್ಯೆಯನ್ನು (Register Number) ಬಳಸಿ ಅಂಕಗಳ ಮರುಎಣಿಕೆಗೆ (Re-totalling) ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು.', NULL, NULL, NULL, true, 'YES', '["ಶೈಕ್ಷಣಿಕ ವರ್ಷದಲ್ಲಿ ಪರೀಕ್ಷೆ ಬರೆದ ವಿದ್ಯಾರ್ಥಿಗಳು"]', '["KSEAB ವೆಬ್‌ಸೈಟ್ → ಆನ್‌ಲೈನ್ ಸೇವೆಗಳು → Other Exams → ಸ್ಕ್ಯಾನ್ ಮಾಡಿದ ಉತ್ತರ ಪತ್ರಿಕೆಯನ್ನು ಪಡೆಯಿರಿ → ಉತ್ತರಗಳು ಮತ್ತು ಅಂಕಗಳನ್ನು ಪರಿಶೀಲಿಸಿ → ಮರುಎಣಿಕೆಗೆ ಅರ್ಜಿ ಸಲ್ಲಿಸಿ → ನೋಂದಣಿ ಸಂಖ್ಯೆಯನ್ನು ನಮೂದಿಸಿ → ವಿಷಯ(ಗಳನ್ನು) ಆಯ್ಕೆ ಮಾಡಿ → ಶುಲ್ಕ ಪಾವತಿಸಿ → ಸಲ್ಲಿಸಿ → ಮರುಎಣಿಕೆ ಫಲಿತಾಂಶ/ತಿದ್ದುಪಡಿ ಅಂಕಗಳನ್ನು ಪಡೆಯಿರಿ."]', 1, '["ನೋಂದಣಿ ಸಂಖ್ಯೆ"]', NULL, NULL, '3443');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('3172526a-b8d4-4c74-8e89-97462088ab66', 'DEPARTMENT-OF-ELECTR-34', '7f13f89f-b8a9-413a-b831-fe2734d98176', 'Establish ''GCC Immersive Hubs'' in Karnataka', 'General', 180, 'GoK will support setting up of ''GCC Immersive Hubs’ to showcase innovation and R&D being undertaken in the State, on Public-Private Partnership (PPP) mode, as part of proposal-based incentive', '["Covering letter", "Full Project Proposal along with all annexures, covering all the sections as outlined in section – 8 of this EOI (Proposal Submission Guidelines) (signed and stamped by Authorized signatory)", "Presentation for Evaluation Committee Meeting – add photographs in PPT (if any, as applicable).", "Company Registration Certificate of the(lead) applicant", "Proof of availability of working & lab space. Copy of the lease deed / ownership documents and floor plan.", "Audited Annual Reports (for eg. Income Tax Return, Balance Sheet, and Profit & Loss Account & Auditor’s Reports) for the last three Financial Years.", "Know Your Customer (KYC) documents of applicant organization. KYC means Identity & Address proof of the organization which includes Company PAN Card, Electricity Bill, etc.)", "Self-Declaration of Applicant on Company letterhead, signed by MD/CEO/Company Secretary, as all Statutory Norms are compiled by the Applicant till date.", "Share Holding Pattern of the Company (highlighting the Foreign Investment, if any)", "CV of the proposed CEO / head of the R&D facility and key leadership team.", "List of equipment & collaborating GCCs/R&D centers for display in the Immersive Hub."]', '["Applicable to any form of entity registered in Karnataka and Industry Associations across the state.", "An entity can either utilize their existing space or establish a new space for the Immersive Hub.", "Applicant should be registered in Karnataka. In case of a consortium, the companies should identify a lead applicant, and the lead applicant shall be registered in Karnataka.", "The registered entity / industry association / lead applicant (in case of consortium) should have the approval from the entity’s authorized leadership to establish the GCC Immersive Hubs.", "Technical Staff/manpower/Faculty having experience in innovation programs", "Applicant GCC should not be debarred by any procurement entity in Central/State Government/Department/Organization/ Institution or any State government applicant for indulging in corrupt or fraudulent practices or for indulging in unfair trade practices for any reasons whatsoever at the time of applying for incentive."]', '[]', '["The applicant Company should be registered with KITS under GCC Policy 2024-29", "Company should submit the incentive application along with supporting documents as prescribed in the OPG."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '583a2c2f-fb37-40ea-a932-d01ab567b91c', 'ಕರ್ನಾಟಕದಲ್ಲಿ ''GCC ಇಮ್ಮರ್ಸಿವ್ ಹಬ್', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ರಾಜ್ಯದಲ್ಲಿ ನಡೆಯುತ್ತಿರುವ ಆವಿಷ್ಕಾರ ಮತ್ತು ಆರ್', NULL, NULL, NULL, NULL, NULL, '["ಸಂಸ್ಥೆಯು ತನ್ನ ಈಗಿರುವ ಸ್ಥಳವನ್ನು ಬಳಸಿಕೊಳ್ಳಬಹುದು ಅಥವಾ ಇಮ್ಮರ್ಸಿವ್ ಹಬ್ (Immersive Hub) ಸ್ಥಾಪನೆಗಾಗಿ ಹೊಸ ಸ್ಥಳವನ್ನು ಸ್ಥಾಪಿಸಬಹುದು.", "ಅರ್ಜಿದಾರ ಸಂಸ್ಥೆಯು ಕರ್ನಾಟಕ ರಾಜ್ಯದಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು. ಒಕ್ಕೂಟದ (Consortium) ರೂಪದಲ್ಲಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಿದಲ್ಲಿ, ಭಾಗವಹಿಸುವ ಸಂಸ್ಥೆಗಳು ಪ್ರಮುಖ ಅರ್ಜಿದಾರರನ್ನು (Lead Applicant) ಗುರುತಿಸಬೇಕು ಹಾಗೂ ಸದರಿ ಪ್ರಮುಖ ಅರ್ಜಿದಾರರು ಕರ್ನಾಟಕದಲ್ಲಿ ನೋಂದಾಯಿತರಾಗಿರಬೇಕು.", "ನೋಂದಾಯಿತ ಸಂಸ್ಥೆ / ಕೈಗಾರಿಕಾ ಸಂಘ / ಪ್ರಮುಖ ಅರ್ಜಿದಾರರು (ಒಕ್ಕೂಟದ ಸಂದರ್ಭದಲ್ಲಿ) GCC ಇಮ್ಮರ್ಸಿವ್ ಹಬ್"]', '["ಅರ್ಜಿದಾರ ಕಂಪನಿಯು GCC ನೀತಿಯಡಿ ಕರ್ನಾಟಕ ನವೋದ್ಯಮ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಸೊಸೈಟಿ (KITS) ಯಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು.", "ಕಂಪನಿಯು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ನೀತಿ ಕಾರ್ಯಾಚರಣೆ ಸೂಚಿಯಲ್ಲಿಯರುವ ನಿಗಧಿತ ನಮೂನೆಯಲ್ಲಿ ಅರ್ಜಿಯನ್ನು ಹಾಗೂ ಸಂಬಂದಿಸಿದ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಬೇಕು"]', 1, '["ಅಧಿಕೃತ ಸಹಿ ಮಾಡಿದವರಿಂದ ಸಹಿ ಮಾಡಲಾದ ಅರ್ಜಿ ಪತ್ರ (Covering Letter).", "ಈ EOI ಯ ವಿಭಾಗ–8 (ಪ್ರಸ್ತಾವನೆ ಸಲ್ಲಿಕೆ ಮಾರ್ಗಸೂಚಿಗಳು) ಯಲ್ಲಿ ಸೂಚಿಸಲಾದ ಎಲ್ಲಾ ಅಂಶಗಳನ್ನು ಒಳಗೊಂಡ ಸಂಪೂರ್ಣ ಯೋಜನಾ ಪ್ರಸ್ತಾವನೆ (Full Project Proposal) ಹಾಗೂ ಅದರ ಎಲ್ಲಾ ಅನುಬಂಧಗಳು (Annexures) (ಅಧಿಕೃತ ಸಹಿ ಮಾಡಿದವರ ಸಹಿ ಮತ್ತು ಸಂಸ್ಥೆಯ ಮುದ್ರೆಯೊಂದಿಗೆ).", "ಮೌಲ್ಯಮಾಪನ ಸಮಿತಿ ಸಭೆಗಾಗಿ ಪ್ರಸ್ತುತಿಕರಣ (Presentation). ಅನ್ವಯಿಸುವಲ್ಲಿ, ಛಾಯಾಚಿತ್ರಗಳನ್ನು (Photographs) ಪ್ರಸ್ತುತಿಕರಣದಲ್ಲಿ ಸೇರಿಸಬೇಕು.", "(ಪ್ರಮುಖ) ಅರ್ಜಿದಾರ ಸಂಸ್ಥೆಯ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರದ ಪ್ರತಿ.", "ಕಾರ್ಯನಿರ್ವಹಣಾ ಸ್ಥಳ (Working Space) ಹಾಗೂ ಪ್ರಯೋಗಾಲಯ (Lab) ಸ್ಥಳದ ಲಭ್ಯತೆಗೆ ಸಂಬಂಧಿಸಿದ ದಾಖಲೆಗಳು – ಗುತ್ತಿಗೆ ಪತ್ರ (Lease Deed) / ಮಾಲೀಕತ್ವದ ದಾಖಲೆಗಳು ಮತ್ತು ಮಹಡಿ ವಿನ್ಯಾಸ ನಕ್ಷೆ (Floor Plan).", "ಕಳೆದ ಮೂರು ಹಣಕಾಸು ವರ್ಷಗಳ ಲೆಕ್ಕಪರಿಶೋಧಿತ ವಾರ್ಷಿಕ ವರದಿಗಳು (ಉದಾಹರಣೆಗೆ – ಆದಾಯ ತೆರಿಗೆ ರಿಟರ್ನ್, ಆಯವ್ಯಯ ಪತ್ರ (Balance Sheet), ಲಾಭ–ನಷ್ಟ ಖಾತೆ ಹಾಗೂ ಲೆಕ್ಕಪರಿಶೋಧಕರ ವರದಿಗಳು).", "ಅರ್ಜಿದಾರ ಸಂಸ್ಥೆಯ ‘ನಿಮ್ಮ ಗ್ರಾಹಕರನ್ನು ತಿಳಿದುಕೊಳ್ಳಿ’ (Know Your Customer – KYC) ದಾಖಲೆಗಳು. KYC ದಾಖಲೆಗಳಲ್ಲಿ ಸಂಸ್ಥೆಯ ಗುರುತು ಮತ್ತು ವಿಳಾಸದ ಪುರಾವೆಗಳಾದ ಕಂಪನಿಯ PAN ಕಾರ್ಡ್, ವಿದ್ಯುತ್ ಬಿಲ್ ಇತ್ಯಾದಿಗಳನ್ನು ಒಳಗೊಂಡಿರಬೇಕು.", "ಸಂಸ್ಥೆಯ ಅಧಿಕೃತ ಲೆಟರ್"]', NULL, NULL, '3338');
