INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('d6ee3893-e9a1-4f4d-8a0d-4014a0f94ab1', 'REVENUE-DEPARTMENT-98', '18b9c82c-f365-482c-acdb-00aa3d65b1c6', 'B side Prathi Book(Durasti)', 'General', 0, 'ISSUE OF DUPLICATE COPIES IN SURVEY SECTION (B side Prathi Book(Durasti)', '[]', '[]', '[]', '[]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', '4a83508d-1e48-4c5d-a4a9-bf202811c23b', 'B side ಪ್ರತಿ ಪುಸ್ತಕ(ದುರಸ್ತಿ)', NULL, NULL, NULL, NULL, NULL, 35.00, NULL, 'B side ಪ್ರತಿ ಪುಸ್ತಕ(ದುರಸ್ತಿ) ನಕಲು ಪ್ರತಿಯ ವಿತರಣೆ', NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1, '[]', NULL, NULL, '3105');
INSERT INTO discovery.sevaone_service_master (id, service_id, department_id, service_name, category, sakala_days, description, required_documents_json, eligibility_json, aliases_json, steps_json, portal, service_url, deeplink_citizen_url, is_active, created_at, sub_department_id, service_name_kannada, short_description, department_service_id, jurisdiction, mode_of_service, remarks, department_fee, service_charge, description_kannada, short_description_kannada, deeplink_operator_url, homepage_url, is_sakala_enabled, sakala_label_raw, eligibility_json_kannada, steps_json_kannada, version, documents_json_kannada, deeplink_citizen_url_kannada, integration_method, sevasindhu_service_id) VALUES ('7d9d6c1c-fc2d-4773-9db9-a9cce35913df', 'EDUCATION-DEPARTMENT-7', 'bd235dfc-9efa-4507-aaf0-f78a93e05e6a', 'Online Re-total Software', 'General', 0, 'After receiving the photocopy of the answer script, students may apply for re-totalling if they find any discrepancy in the calculation of their marks, using their Register Number.', '["Register Number"]', '["Students who has written exams"]', '[]', '["Get Scanned Answer Script → Check Marks & Total → Apply for Re-totaling → Enter Register Number → Select Subject(s) → Pay Fee → Submit → Re-totaling Result/Updated Marks."]', NULL, NULL, 'https://sevasindhu.karnataka.gov.in/', true, '2026-10-30 16:55:56.458552+00', 'e61a6e68-d61f-4782-a4e6-388fca3e3652', 'ಆನ್', 'After receiving the photocopy of the answer script, students may apply for re-totalling if they find any discrepancy in the calculation of their marks, using their Register Number.', NULL, 'Urban & Rural', NULL, NULL, NULL, NULL, 'ಉತ್ತರ ಪತ್ರಿಕೆಯ ಛಾಯಾಪ್ರತಿಯನ್ನು ಪಡೆದ ನಂತರ, ಅಂಕಗಳ ಮೊತ್ತದ ಲೆಕ್ಕಾಚಾರದಲ್ಲಿ ಯಾವುದೇ ವ್ಯತ್ಯಾಸ ಕಂಡುಬಂದಲ್ಲಿ, ವಿದ್ಯಾರ್ಥಿಗಳು ತಮ್ಮ ನೋಂದಣಿ ಸಂಖ್ಯೆಯನ್ನು (Register Number) ಬಳಸಿ ಅಂಕಗಳ ಮರುಎಣಿಕೆಗೆ (Re-totalling) ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು.', NULL, NULL, NULL, NULL, NULL, '["ಶೈಕ್ಷಣಿಕ ವರ್ಷದಲ್ಲಿ ಪರೀಕ್ಷೆ ಬರೆದ ವಿದ್ಯಾರ್ಥಿಗಳು"]', '["ಸ್ಕ್ಯಾನ್ ಮಾಡಿದ ಉತ್ತರ ಪತ್ರಿಕೆಯನ್ನು ಪಡೆಯಿರಿ → ಅಂಕಗಳು ಮತ್ತು ಒಟ್ಟು ಮೊತ್ತವನ್ನು ಪರಿಶೀಲಿಸಿ → ಮರುಎಣಿಕೆಗೆ ಅರ್ಜಿ ಸಲ್ಲಿಸಿ → ನೋಂದಣಿ ಸಂಖ್ಯೆಯನ್ನು ನಮೂದಿಸಿ → ವಿಷಯ(ಗಳನ್ನು) ಆಯ್ಕೆ ಮಾಡಿ → ಶುಲ್ಕ ಪಾವತಿಸಿ → ಸಲ್ಲಿಸಿ → ಮರುಎಣಿಕೆ ಫಲಿತಾಂಶ/ತಿದ್ದುಪಡಿ ಅಂಕಗಳನ್ನು ಪಡೆಯಿರಿ."]', 1, '["ನೋಂದಣಿ ಸಂಖ್ಯೆ"]', NULL, NULL, '3435');
